/* ===============================================================
 * BALANCE FORMULAS
 * Every balance-sensitive calculation lives here.
 * =============================================================*/
const FORMULAS = {
  timeline: {
    referenceSpeed: 100,
    speedExponent: 0.77,
    baseRecovery: 1000,

    turnRate(speed) {
      return Math.pow(
        Math.max(1, speed) / this.referenceSpeed,
        this.speedExponent
      );
    },

    recoveryDelay(speed, recovery) {
      return recovery / this.turnRate(speed);
    }
  },

  damage: {
    physical({ attack, defense, power }) {
      return Math.max(1, attack * power / 100 - defense * 0.5);
    },

    magical({ magic, resistance, power }) {
      return Math.max(1, magic * power / 100 - resistance * 0.5);
    },

    percentMaxHp({ targetMaxHp, power }) {
      return Math.max(1, targetMaxHp * power / 100);
    }
  },

  healing: {
    magical({ magic, power }) {
      return Math.max(1, magic * power / 100);
    },

    flat({ power }) {
      return Math.max(1, power);
    }
  },

  accuracy: {
    hitChance({ accuracy, evasion, bonus = 0 }) {
      return clamp(0.05, 0.95, 0.8 + (accuracy - evasion) * 0.01 + bonus);
    }
  }
};

