/* ===============================================================
 * AI PROFILES
 * =============================================================*/
/* Authored in src/content/gameplay/ai-profiles.json. Weight vectors for the
 * scoring AI; the behaviour itself is engine code. */
const AI_PROFILES = GAMEPLAY_CONTENT.aiProfiles;

/* =========================================================================
 *
 *                      EDITABLE CONTENT ABOVE
 *                          ENGINE BELOW
 *
 * =======================================================================*/
/* ---------------------------------------------------------------
 * ENGINE — GENERIC UTILITIES
 * -------------------------------------------------------------*/

function deepFreeze(value) {
  if (value && typeof value === "object" && !Object.isFrozen(value)) {
    Object.freeze(value);
    for (const key of Object.keys(value)) deepFreeze(value[key]);
  }
  return value;
}

function tileKey(x, y) {
  return x + "," + y;
}

function parseTileKey(key) {
  const parts = key.split(",");
  return { x: Number(parts[0]), y: Number(parts[1]) };
}

function manhattan(a, b) {
  return Math.abs(a.x - b.x) + Math.abs(a.y - b.y);
}

function chebyshev(a, b) {
  return Math.max(Math.abs(a.x - b.x), Math.abs(a.y - b.y));
}

function gridDistance(a, b) {
  return GAME_CONFIG.grid.allowDiagonalMovement
    ? chebyshev(a, b)
    : manhattan(a, b);
}

/* ---------------------------------------------------------------
 * CONTENT REGISTRY
 * Ids derive from object keys. Definitions are normalized + frozen.
 * -------------------------------------------------------------*/

function deriveIds(source, normalize) {
  const out = {};
  for (const key of Object.keys(source)) {
    const entry = normalize({ ...source[key] }, key);
    entry.id = key;
    out[key] = entry;
  }
  return out;
}

const DEFAULT_BASE_STATS = {
  // How many tiles of forced movement this frame simply absorbs. Zero for
  // almost everything; an anchored emplacement or a heavy frame declares more.
  // An ordinary stat on purpose, so equipment, statuses and perks can move it
  // through the pipeline that already exists rather than a bespoke one.
  displacementResistance: 0,
  // Extra tiles a chain may reach when arcing to or from this frame. Also an
  // ordinary stat, so a conductive status is a modifier rather than a
  // conductivity subsystem.
  propagationRadiusBonus: 0,
  maxHp: 1,
  attack: 0,
  magic: 0,
  defense: 0,
  resistance: 0,
  speed: 100,
  accuracy: 100,
  evasion: 100,
  movement: 1
};

/**
 * Sensors and emissions as ordinary content.
 *
 * A chassis, a status and a piece of equipment all normalize to the same
 * shape, so "a scanner drone", "a cloak field" and "a thermal optic" are three
 * data entries rather than three engine features:
 *
 *   perception: {
 *     sensors:   { thermal: { range: 8 } },   // what it can detect
 *     emissions: { optical: 0, signal: 2 }    // what it gives off, as a factor
 *   }
 *
 * Absent fields mean "unchanged", which is why every existing content entry
 * keeps behaving exactly as it did.
 */
function normalizePerceptionProfile(authored) {
  const sensors = {};
  const emissions = {};
  const source = authored || {};
  for (const channelId of Object.keys(source.sensors || {})) {
    if (!OBSERVATION_CHANNELS[channelId]) continue;
    const entry = source.sensors[channelId];
    sensors[channelId] = { range: entry && entry.range != null ? entry.range : 0 };
  }
  for (const channelId of Object.keys(source.emissions || {})) {
    if (!OBSERVATION_CHANNELS[channelId]) continue;
    const value = source.emissions[channelId];
    if (typeof value === "number") emissions[channelId] = value;
  }
  return { sensors, emissions };
}

function buildContentRegistry(sources) {
  // Resource definitions are authored alongside everything else, so the
  // content registry carries them too. Without this an effect that names a
  // resource had nothing to be validated against, and a typo was only
  // discoverable by watching a transfer move nothing.
  const resources = deriveIds(sources.resources || {}, (entry) => {
    entry.scope = entry.scope === "faction" ? "faction" : "unit";
    entry.tags = entry.tags || [];
    return entry;
  });

  const units = deriveIds(sources.units, (entry) => {
    entry.baseStats = { ...DEFAULT_BASE_STATS, ...(entry.baseStats || {}) };
    entry.abilities = entry.abilities ? entry.abilities.slice() : [];
    entry.glyph = entry.glyph || (entry.name ? entry.name[0] : "?");
    entry.classId = entry.classId || null;
    entry.assets = entry.assets || {};
    entry.description = entry.description || "";
    entry.resources = entry.resources || {};
    entry.tags = entry.tags || [];
    // Traversal limits live in baseStats so the generic modifyStat effect can
    // raise or lower them without any named-skill logic in pathfinding.
    entry.baseStats = entry.baseStats || {};
    if (entry.baseStats.maxClimb == null) entry.baseStats.maxClimb = 1;
    if (entry.baseStats.maxDrop == null) entry.baseStats.maxDrop = 1;
    entry.defaultEquipment = entry.defaultEquipment || {};
    entry.role = entry.role || "";
    // What this chassis can detect and what it gives off. Absent means "an
    // ordinary body with ordinary eyes", which is what every existing unit is.
    entry.perception = normalizePerceptionProfile(entry.perception);
    return entry;
  });

  const abilities = deriveIds(sources.abilities, (entry) => {
    const targeting = entry.targeting || {};
    entry.targeting = {
      type: targeting.type || "enemy",
      rangeMin: targeting.rangeMin == null ? 1 : targeting.rangeMin,
      rangeMax: targeting.rangeMax == null ? 1 : targeting.rangeMax,
      requiresLineOfSight: targeting.requiresLineOfSight !== false,
      allowsDefeated: targeting.allowsDefeated === true,
      area: targeting.area || { shape: "single" },
      filters: targeting.filters || []
    };
    entry.timing = {
      recovery: (entry.timing && entry.timing.recovery) || 0,
      cooldown: (entry.timing && entry.timing.cooldown) || 0
    };
    entry.effects = entry.effects ? entry.effects.map((e) => ({ ...e })) : [];
    entry.activation = entry.activation || "manual";
    entry.assets = entry.assets || {};
    entry.description = entry.description || "";
    entry.costs = entry.costs || {};
    entry.conditions = entry.conditions || [];
    entry.targeting = entry.targeting || {};
    entry.targeting.filters = entry.targeting.filters || [];
    entry.targeting.allowsDefeated = entry.targeting.allowsDefeated === true;
    entry.targeting.area = entry.targeting.area || { shape: "single" };
    entry.timing = entry.timing || {};
    entry.timing.recovery = entry.timing.recovery == null ? 0 : entry.timing.recovery;
    entry.timing.cooldown = entry.timing.cooldown == null ? 0 : entry.timing.cooldown;
    return entry;
  });

  const statuses = deriveIds(sources.statuses, (entry) => {
    entry.duration = entry.duration || { type: "targetActivations", amount: 1 };
    entry.modifiers = entry.modifiers || {};
    entry.triggers = entry.triggers ? entry.triggers.map((t) => ({ ...t })) : [];
    entry.preventsAction = entry.preventsAction === true;
    // A damaged frame loses capability, not just numbers. Defaulted here so
    // nothing downstream has to check whether the lists exist.
    entry.removesAbilities = entry.removesAbilities || [];
    entry.blocksAbilityTags = entry.blocksAbilityTags || [];
    entry.glyph = entry.glyph || "•";
    entry.assets = entry.assets || {};
    entry.perception = normalizePerceptionProfile(entry.perception);
    return entry;
  });

  const terrains = deriveIds(sources.terrains, (entry) => {
    entry.walkable = entry.walkable !== false;
    entry.movementCost = entry.movementCost == null ? 1 : entry.movementCost;
    entry.blocksLineOfSight = entry.blocksLineOfSight === true;
    entry.modifiers = entry.modifiers || {};
    entry.assets = entry.assets || {};
    return entry;
  });

  const maps = deriveIds(sources.maps, (entry) => {
    // Rows + legend are the authoring format; tiles are the engine format.
    if (!entry.tiles && entry.rows) {
      entry.tiles = entry.rows.map((row) =>
        row.split("").map((ch) => (entry.legend ? entry.legend[ch] : ch))
      );
    }
    entry.tiles = entry.tiles || [];
    entry.height = entry.height == null ? entry.tiles.length : entry.height;
    entry.width =
      entry.width == null
        ? entry.tiles[0]
          ? entry.tiles[0].length
          : 0
        : entry.width;
    // Elevation authoring: rows of digits, an explicit matrix, or nothing at
    // all. Maps without elevation normalize to a completely flat board.
    if (!entry.elevations && entry.elevationRows) {
      entry.elevations = entry.elevationRows.map((row) =>
        String(row)
          .split("")
          .map((character) => Number(character))
      );
    }
    if (!entry.elevations) {
      entry.elevations = entry.tiles.map((row) => row.map(() => 0));
    }
    entry.elevations = entry.elevations.map((row) => row.map((value) => value));
    return entry;
  });

  const encounters = deriveIds(sources.encounters, (entry) => {
    entry.teams = (entry.teams || []).map((t) => ({ ...t }));
    entry.units = (entry.units || []).map((u) => ({ ...u }));
    entry.objective = entry.objective || "defeatAllEnemies";
    return entry;
  });

  // Equipment is ordinary content: slots, compatibility, modifiers and
  // granted abilities are all data.
  const equipment = deriveIds(sources.equipment || {}, (entry) => {
    entry.slot = entry.slot || "utilitySystem";
    entry.compatibleClasses = entry.compatibleClasses || [];
    entry.modifiers = entry.modifiers || [];
    entry.grantsAbilities = entry.grantsAbilities || [];
    entry.removesAbilities = entry.removesAbilities || [];
    entry.tags = entry.tags || [];
    entry.description = entry.description || "";
    entry.assets = entry.assets || {};
    entry.perception = normalizePerceptionProfile(entry.perception);
    return entry;
  });

  const aiProfiles = deriveIds(sources.aiProfiles, (entry) => entry);

  // Presentation records. The engine only ever checks that referenced ids
  // exist; it never reads a source, a URL, or a pixel.
  /* Things that sit on a tile and are not units. Normalised the same way as
   * everything else, so an author who omits a field gets the safe default
   * rather than an undefined the runtime trips over. */
  const fixtures = deriveIds(sources.fixtures || {}, (entry) => {
    entry.name = entry.name || entry.id;
    entry.glyph = entry.glyph || "◈";
    entry.description = entry.description || "";
    entry.tags = entry.tags || [];
    entry.visibility = entry.visibility || "ownerTeam";
    entry.initialState = entry.initialState || "armed";
    entry.trigger = entry.trigger || { type: "command" };
    entry.area = entry.area || { shape: "single" };
    entry.affects = entry.affects || "enemy";
    entry.effects = entry.effects || [];
    entry.charges = entry.charges == null ? 1 : entry.charges;
    entry.consumedOnTrigger = entry.consumedOnTrigger !== false;
    entry.blocksMovement = entry.blocksMovement === true;
    entry.stacks = entry.stacks === true;
    entry.triggerTiles = entry.triggerTiles || [];
    entry.assets = entry.assets || {};
    return entry;
  });

  const presentationAssets = deriveIds(sources.presentationAssets || {}, (entry) => {
    entry.type = entry.type || "image";
    entry.src = entry.src == null ? null : entry.src;
    entry.srcCandidates = Array.isArray(entry.srcCandidates) ? entry.srcCandidates.slice() : [];
    entry.recommended = entry.recommended || null;
    entry.fallback = entry.fallback || { type: "glyph", value: "?" };
    return entry;
  });

  const unitAbilities = {};
  const abilityUsers = {};
  for (const unitId of Object.keys(units)) {
    unitAbilities[unitId] = units[unitId].abilities.slice();
    for (const abilityId of units[unitId].abilities) {
      if (!abilityUsers[abilityId]) abilityUsers[abilityId] = [];
      abilityUsers[abilityId].push(unitId);
    }
  }

  const mapEncounters = {};
  for (const encounterId of Object.keys(encounters)) {
    const mapId = encounters[encounterId].mapId;
    if (!mapEncounters[mapId]) mapEncounters[mapId] = [];
    mapEncounters[mapId].push(encounterId);
  }

  const registry = {
    units,
    abilities,
    statuses,
    resources,
    terrains,
    maps,
    encounters,
    aiProfiles,
    equipment,
    fixtures,
    presentationAssets,

    unitAbilities,
    abilityUsers,
    mapEncounters
  };

  const report = collectContentIssues(registry);
  registry.errors = report.errors;
  registry.warnings = report.warnings;

  deepFreeze(registry.units);
  deepFreeze(registry.abilities);
  deepFreeze(registry.statuses);
  deepFreeze(registry.terrains);
  deepFreeze(registry.maps);
  deepFreeze(registry.encounters);
  deepFreeze(registry.aiProfiles);
  deepFreeze(registry.equipment);
  deepFreeze(registry.fixtures);
  deepFreeze(registry.presentationAssets);

  return registry;
}

/* ---------------------------------------------------------------
 * SEEDED RANDOMNESS
 * -------------------------------------------------------------*/

function createRandomState(seed) {
  return { seed: seed >>> 0, counter: 0 };
}

function randomFloat(state) {
  const rs = state.randomState;
  rs.counter += 1;
  let t = (rs.seed + Math.imul(rs.counter, 0x6d2b79f5)) >>> 0;
  t = Math.imul(t ^ (t >>> 15), 1 | t);
  t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
}

function randomInt(state, min, max) {
  return min + Math.floor(randomFloat(state) * (max - min + 1));
}

function rollChance(state, probability) {
  return randomFloat(state) < probability;
}

/* ---------------------------------------------------------------
 * STAT CALCULATION PIPELINE
 * base -> (future layers) -> status modifiers -> effective
 * -------------------------------------------------------------*/

/**
 * Equipment fitted to a unit right now. Runtime state stores ids only; the
 * definitions themselves are never copied or mutated.
 */
/* ---------------------------------------------------------------
 * DEFINITION LOOKUP
 *
 * Every real battle resolves definitions straight out of the frozen CONTENT
 * registry. `state.contentOverride` is null in all of them — it exists so the
 * Gameplay Data Studio can compose stats for data it has not saved yet, using
 * this pipeline rather than a second copy of it. Nothing in the simulation
 * ever sets it, and `serializeBattle` does not carry it.
 * -------------------------------------------------------------*/

function definitionFrom(state, group, id) {
  const override = state && state.contentOverride;
  const supplied = override && override[group] && override[group][id];
  return supplied || CONTENT[group][id];
}

function equippedItems(state, unitId) {
  const unit = state.units[unitId];
  if (!unit || !unit.equipment) return [];
  const items = [];
  for (const slot of GAME_CONFIG.equipment.slots) {
    const equipmentId = unit.equipment[slot];
    if (!equipmentId) continue;
    const definition = definitionFrom(state, "equipment", equipmentId);
    if (definition) items.push(definition);
  }
  return items;
}

/** Is this part legal for this chassis class? */
function isEquipmentCompatible(definitionId, equipmentId) {
  const unitDefinition = CONTENT.units[definitionId];
  const item = CONTENT.equipment[equipmentId];
  if (!unitDefinition || !item) return false;
  if (!item.compatibleClasses.length) return true;
  return item.compatibleClasses.includes(unitDefinition.classId);
}

function equipmentCompatibilityReason(definitionId, equipmentId) {
  const unitDefinition = CONTENT.units[definitionId];
  const item = CONTENT.equipment[equipmentId];
  if (!item) return "Unknown equipment.";
  if (!unitDefinition) return "Unknown chassis.";
  if (isEquipmentCompatible(definitionId, equipmentId)) return null;
  return item.name + " does not fit a " + (unitDefinition.classId || "chassis") + " chassis.";
}

/**
 * Every ability a unit can use: its chassis list plus anything granted by
 * equipment, minus anything a part removes.
 */
/**
 * Everything a unit can currently do.
 *
 * Chassis, plus what equipment grants, minus what equipment or a *status*
 * takes away.
 *
 * The status half is the whole of this project's subsystem-damage model, and
 * it is deliberately this small. Statuses could already express a damaged
 * frame in every way that matters — a stat modifier is a mobility hit, a
 * perception profile is a wrecked sensor array — with exactly one gap: they
 * could not take a weapon offline, because only equipment could remove an
 * ability and equipment does not change mid-battle.
 *
 * Closing that gap here rather than building a subsystem model means an
 * impairment inherits the entire status lifecycle for free: duration, stacking,
 * display, save/load, and repair as an ordinary `cleanse` or `removeStatus`.
 * A separate model would have had to reimplement all of it to gain nothing.
 *
 * `blocksAbilityTags` covers the case an id list cannot: "your weapons are
 * offline" should apply to whatever this frame happens to be carrying, not to
 * a list the author has to keep in step with every chassis.
 */
function getUnitAbilities(state, unitId) {
  const unit = state.units[unitId];
  if (!unit) return [];
  const definition = definitionFrom(state, "units", unit.definitionId);
  const abilities = definition.abilities.slice();
  const removed = new Set();
  const blockedTags = new Set();
  for (const item of equippedItems(state, unitId)) {
    for (const abilityId of item.grantsAbilities) {
      if (!abilities.includes(abilityId)) abilities.push(abilityId);
    }
    for (const abilityId of item.removesAbilities) removed.add(abilityId);
  }
  for (const applied of unit.statuses || []) {
    const status = definitionFrom(state, "statuses", applied.statusId);
    if (!status) continue;
    for (const abilityId of status.removesAbilities || []) removed.add(abilityId);
    for (const tag of status.blocksAbilityTags || []) blockedTags.add(tag);
  }
  return abilities.filter((abilityId) => {
    if (removed.has(abilityId)) return false;
    if (!blockedTags.size) return true;
    const ability = CONTENT.abilities[abilityId];
    const tags = (ability && ability.ui && ability.ui.tags) || [];
    return !tags.some((tag) => blockedTags.has(tag));
  });
}

/**
 * Whether an ability made entirely of transfers would move anything.
 *
 * Deliberately only an opinion about abilities that are *nothing but*
 * transfers. One that also heals or damages still has work to do when a pool
 * happens to be full, and greying it out would be a lie in the other
 * direction; one whose whole purpose is to move points and cannot move any is
 * an action the player would spend a turn regretting.
 *
 * The judgement comes from `planTransfer` — the same call the forecast and the
 * executor make — so an ability is never offered on terms the transfer would
 * then refuse.
 */
function transferAbilityIsIdle(state, unitId, abilityId, targetUnitId) {
  const ability = CONTENT.abilities[abilityId];
  const effects = (ability && ability.effects) || [];
  if (!effects.length) return false;
  if (!effects.every((effect) => effect.type === "transferResource")) return false;
  return !effects.some((effect) => {
    const plan = transferPlanFor(state, {
      effect,
      sourceUnitId: unitId,
      targetUnitId: targetUnitId || unitId,
      abilityId
    });
    return plan && planTransfer(state, plan).ok;
  });
}

/** Why an ability a unit normally carries is currently unavailable, or null.
 *  Presentation only — the authority is `getUnitAbilities`. */
function abilityImpairment(state, unitId, abilityId) {
  const unit = state.units[unitId];
  if (!unit) return null;
  const ability = CONTENT.abilities[abilityId];
  const tags = (ability && ability.ui && ability.ui.tags) || [];
  for (const applied of unit.statuses || []) {
    const status = definitionFrom(state, "statuses", applied.statusId);
    if (!status) continue;
    const byId = (status.removesAbilities || []).includes(abilityId);
    const byTag = (status.blocksAbilityTags || []).some((tag) => tags.includes(tag));
    if (byId || byTag) return { statusId: applied.statusId, name: status.name || applied.statusId };
  }
  return null;
}

const STAT_LAYERS = [
  function baseStatsLayer(stats, context) {
    Object.assign(stats, context.definition.baseStats);
  },

  function statusModifierLayer(stats, context) {
    for (const applied of context.unit.statuses) {
      const def = definitionFrom(context.state, "statuses", applied.statusId);
      if (!def || !def.modifiers) continue;
      for (const key of Object.keys(def.modifiers)) {
        const value = def.modifiers[key];
        if (key.endsWith("Multiplier")) {
          const statName = key.slice(0, -"Multiplier".length);
          if (stats[statName] != null) stats[statName] *= value;
        } else if (key.endsWith("Flat")) {
          const statName = key.slice(0, -"Flat".length);
          if (stats[statName] != null) stats[statName] += value;
        }
      }
    }
  },

  function equipmentLayer(stats, context) {
    const state = context.state;
    if (!state || !context.unit.equipment) return;
    const ordered = [[], [], []];
    for (const item of equippedItems(state, context.unit.id)) {
      for (const modifier of item.modifiers) {
        const index =
          modifier.mode === "flat" ? 0 : modifier.mode === "multiplier" ? 1 : 2;
        ordered[index].push(modifier);
      }
    }
    for (const group of ordered) {
      for (const modifier of group) {
        if (stats[modifier.stat] == null) continue;
        if (modifier.mode === "multiplier") stats[modifier.stat] *= modifier.value;
        else if (modifier.mode === "override") stats[modifier.stat] = modifier.value;
        else stats[modifier.stat] += modifier.value;
      }
    }
  },

  function modifierLayer(stats, context) {
    const modifiers = context.unit.modifiers || [];
    const ordered = [
      modifiers.filter((entry) => entry.mode === "flat"),
      modifiers.filter((entry) => entry.mode === "multiplier"),
      modifiers.filter((entry) => entry.mode === "override")
    ];
    for (const group of ordered) {
      for (const modifier of group) {
        if (stats[modifier.stat] == null) continue;
        if (modifier.mode === "flat") stats[modifier.stat] += modifier.value;
        else if (modifier.mode === "multiplier") stats[modifier.stat] *= modifier.value;
        else stats[modifier.stat] = modifier.value;
      }
    }
  },

  function terrainModifierLayer(stats, context) {
    const state = context.state;
    if (!state || !state.terrainOverrides) return;
    const override = terrainOverrideAt(state, context.unit.x, context.unit.y);
    if (!override) return;
    const terrain = CONTENT.terrains[override.terrainId];
    if (!terrain || !terrain.modifiers) return;
    for (const key of Object.keys(terrain.modifiers)) {
      const value = terrain.modifiers[key];
      if (key.endsWith("Multiplier")) {
        const statName = key.slice(0, -"Multiplier".length);
        if (stats[statName] != null) stats[statName] *= value;
      } else if (key.endsWith("Flat")) {
        const statName = key.slice(0, -"Flat".length);
        if (stats[statName] != null) stats[statName] += value;
      }
    }
  }
];

function calculateUnitStats(state, unitId) {
  const unit = state.units[unitId];
  const definition = definitionFrom(state, "units", unit.definitionId);
  const stats = {};
  const context = { state, unit, definition };
  for (const layer of STAT_LAYERS) layer(stats, context);
  for (const key of Object.keys(stats)) {
    if (!Number.isFinite(stats[key])) stats[key] = 0;
  }
  stats.speed = Math.max(1, stats.speed);
  stats.maxHp = Math.max(1, Math.round(stats.maxHp));
  return stats;
}

function turnRateOf(state, unitId) {
  return FORMULAS.timeline.turnRate(calculateUnitStats(state, unitId).speed);
}

/**
 * What a chassis plus a loadout actually composes into.
 *
 * Built for the Gameplay Data Studio, which must never own a second stat
 * calculator: two calculators eventually disagree, and the one you are reading
 * is always the wrong one. So this stands up the smallest possible unit the
 * real pipeline accepts and runs `calculateUnitStats` — the same function the
 * battle uses — over it.
 *
 * The unit is off-board, unstatused and unmodified, so what comes back is the
 * chassis and its equipment and nothing else. Terrain, statuses and buffs are
 * battle circumstances, and reading them here would be reading noise.
 *
 * @param request.registries  Optional unsaved definitions, resolved ahead of
 *                            CONTENT, so the Studio can compose a change
 *                            before it has been saved or tested.
 */
function composeUnitPreview(request) {
  const definitionId = request && request.definitionId;
  // `registries` lets the Studio compose data it has not saved yet: unsaved
  // definitions are handed in and resolved ahead of CONTENT, so the numbers on
  // screen follow the number being typed. Omitted, this is the shipped data.
  // Authored data, run through the registry's own normalizers before the
  // pipeline sees it. Raw JSON omits every default — an item with no
  // `removesAbilities`, a chassis with no `resources` — and the engine is
  // entitled to assume those are present, because for CONTENT they always are.
  const supplied = request && request.registries;
  const overrides = supplied
    ? (() => {
        const normalized = buildContentRegistry({
          units: supplied.units || {},
          abilities: supplied.abilities || CONTENT.abilities,
          statuses: supplied.statuses || {},
          terrains: {},
          maps: {},
          encounters: {},
          aiProfiles: supplied.aiProfiles || CONTENT.aiProfiles,
          equipment: supplied.equipment || {},
          resources: supplied.resources || RESOURCES_BY_ID,
          presentationAssets: {}
        });
        return {
          units: normalized.units,
          equipment: normalized.equipment,
          statuses: normalized.statuses
        };
      })()
    : null;

  const state = {
    units: {},
    unitOrder: ["preview"],
    terrainOverrides: null,
    contentOverride: overrides
  };

  const definition = definitionFrom(state, "units", definitionId);
  if (!definition) return { error: 'No unit definition "' + String(definitionId) + '".' };

  const equipment = {};
  const requested = (request && request.equipment) || definition.defaultEquipment || {};
  for (const slot of GAME_CONFIG.equipment.slots) {
    if (requested[slot]) equipment[slot] = requested[slot];
  }

  const unit = {
    id: "preview",
    definitionId,
    equipment,
    statuses: [],
    modifiers: [],
    x: 0,
    y: 0,
    alive: true
  };
  state.units.preview = unit;

  const total = calculateUnitStats(state, "preview");
  const base = definition.baseStats;
  const items = equippedItems(state, "preview");

  const rows = Object.keys(base).map((stat) => {
    const contributions = [];
    for (const item of items) {
      for (const modifier of item.modifiers) {
        if (modifier.stat !== stat) continue;
        contributions.push(
          item.name + " " +
            (modifier.mode === "multiplier"
              ? "×" + modifier.value
              : modifier.mode === "override"
                ? "=" + modifier.value
                : (modifier.value >= 0 ? "+" : "") + modifier.value)
        );
      }
    }
    return {
      stat,
      base: base[stat],
      total: total[stat],
      sources: contributions.length ? "base " + base[stat] + " · " + contributions.join(" · ") : "base only"
    };
  });

  return {
    definitionId,
    equipment,
    rows,
    abilities: getUnitAbilities(state, "preview"),
    slots: GAME_CONFIG.equipment.slots.map((slot) => ({ slot, equipmentId: equipment[slot] || null }))
  };
}

/* ---------------------------------------------------------------
 * GRID
 * -------------------------------------------------------------*/

function getMap(state) {
  return CONTENT.maps[state.mapId];
}

function inBounds(map, x, y) {
  return x >= 0 && y >= 0 && x < map.width && y < map.height;
}

/** Runtime terrain override id for a tile, if any. */
function terrainOverrideAt(state, x, y) {
  if (!state || !state.terrainOverrides) return null;
  return state.terrainOverrides[tileKey(x, y)] || null;
}

function terrainAt(map, x, y, state) {
  if (!inBounds(map, x, y)) return null;
  const override = terrainOverrideAt(state, x, y);
  if (override) return CONTENT.terrains[override.terrainId] || null;
  return CONTENT.terrains[map.tiles[y][x]] || null;
}

/**
 * Normalized tile elevation, or null outside the map. Pure map data: this
 * never reads presentation or camera state.
 */
function elevationAt(map, x, y) {
  if (!map || !inBounds(map, x, y)) return null;
  const row = map.elevations ? map.elevations[y] : null;
  const value = row ? row[x] : 0;
  return Number.isFinite(value) ? value : 0;
}

function terrainIdAt(state, x, y) {
  const map = getMap(state);
  if (!inBounds(map, x, y)) return null;
  const override = terrainOverrideAt(state, x, y);
  return override ? override.terrainId : map.tiles[y][x];
}

function isWalkable(map, x, y, state) {
  const terrain = terrainAt(map, x, y, state);
  return !!terrain && terrain.walkable;
}

function unitAt(state, x, y, ignoreUnitId) {
  for (const id of state.unitOrder) {
    const unit = state.units[id];
    if (!unit.alive) continue;
    if (ignoreUnitId && id === ignoreUnitId) continue;
    if (unit.x === x && unit.y === y) return unit;
  }
  return null;
}

function isTileFree(state, x, y, ignoreUnitId) {
  const map = getMap(state);
  if (!isWalkable(map, x, y, state)) return false;
  return !unitAt(state, x, y, ignoreUnitId);
}

/**
 * The single authoritative rule for stepping between two adjacent tiles.
 * Terrain, occupancy, adjacency and elevation limits all resolve here, so
 * pathfinding, validation, AI, danger zones and forecasts share one answer.
 *
 * Elevation affects movement only. Height-aware combat (range, accuracy,
 * line-of-sight interception, falling) is deliberately left to a later phase.
 */
function evaluateTraversalStep(state, unitId, from, to, options) {
  const opts = options || {};
  const map = getMap(state);
  const policy = opts.movementPolicy || "normal";
  const errors = [];

  const fromElevation = elevationAt(map, from.x, from.y);
  const toElevation = elevationAt(map, to.x, to.y);
  const delta = toElevation == null || fromElevation == null ? 0 : toElevation - fromElevation;
  const direction = delta > 0 ? "up" : delta < 0 ? "down" : "level";

  const result = {
    valid: false,
    errors,
    from: { x: from.x, y: from.y },
    to: { x: to.x, y: to.y },
    fromElevation,
    toElevation,
    elevationDelta: delta,
    direction,
    terrainCost: 0,
    elevationCost: 0,
    totalCost: Infinity,
    policy
  };

  if (!inBounds(map, to.x, to.y)) {
    errors.push("Destination is outside the map.");
    return result;
  }

  const dx = Math.abs(to.x - from.x);
  const dy = Math.abs(to.y - from.y);
  const diagonal = dx === 1 && dy === 1;
  const orthogonal = dx + dy === 1;
  const adjacent = orthogonal || (diagonal && GAME_CONFIG.grid.allowDiagonalMovement);
  if (policy !== "teleport" && !adjacent) {
    errors.push("Tiles are not adjacent.");
    return result;
  }

  const terrain = terrainAt(map, to.x, to.y, state);
  if (!terrain || !terrain.walkable) {
    errors.push("Destination terrain is impassable.");
    return result;
  }
  if (!opts.ignoreOccupancy && unitAt(state, to.x, to.y, unitId)) {
    errors.push("Destination is occupied.");
    return result;
  }

  result.terrainCost = terrain.movementCost;
  if (diagonal) result.terrainCost *= GAME_CONFIG.grid.diagonalMovementCostMultiplier;

  if (policy !== "teleport" && !opts.ignoresElevation) {
    const stats = calculateUnitStats(state, unitId);
    const maxClimb = opts.maxClimb == null ? stats.maxClimb : opts.maxClimb;
    const maxDrop = opts.maxDrop == null ? stats.maxDrop : opts.maxDrop;
    if (delta > 0 && delta > maxClimb) {
      errors.push("Requires climb " + delta + "; unit maximum is " + maxClimb + ".");
      return result;
    }
    if (delta < 0 && Math.abs(delta) > maxDrop) {
      errors.push("Requires drop " + Math.abs(delta) + "; unit maximum is " + maxDrop + ".");
      return result;
    }
    result.elevationCost =
      delta > 0
        ? delta * GAME_CONFIG.grid.uphillMovementCostPerLevel
        : Math.abs(delta) * GAME_CONFIG.grid.downhillMovementCostPerLevel;
  }

  result.valid = true;
  result.totalCost = result.terrainCost + result.elevationCost;
  return result;
}

function neighborsOf(map, x, y) {
  const out = [
    { x: x + 1, y, diagonal: false },
    { x: x - 1, y, diagonal: false },
    { x, y: y + 1, diagonal: false },
    { x, y: y - 1, diagonal: false }
  ];
  if (GAME_CONFIG.grid.allowDiagonalMovement) {
    out.push(
      { x: x + 1, y: y + 1, diagonal: true },
      { x: x + 1, y: y - 1, diagonal: true },
      { x: x - 1, y: y + 1, diagonal: true },
      { x: x - 1, y: y - 1, diagonal: true }
    );
  }
  return out.filter((t) => inBounds(map, t.x, t.y));
}

/**
 * Dijkstra movement range. Returns Map<tileKey, {x, y, cost, from}>.
 */
function computeMovementRange(state, unitId, options) {
  const opts = options || {};
  const unit = state.units[unitId];
  const map = getMap(state);
  const origin = opts.origin || { x: unit.x, y: unit.y };
  const budget =
    opts.budget == null ? calculateUnitStats(state, unitId).movement : opts.budget;

  const visited = new Map();
  visited.set(tileKey(origin.x, origin.y), {
    x: origin.x,
    y: origin.y,
    cost: 0,
    from: null
  });

  const frontier = [{ x: origin.x, y: origin.y, cost: 0 }];
  while (frontier.length) {
    let bestIndex = 0;
    for (let i = 1; i < frontier.length; i += 1) {
      if (frontier[i].cost < frontier[bestIndex].cost) bestIndex = i;
    }
    const current = frontier.splice(bestIndex, 1)[0];
    const currentKey = tileKey(current.x, current.y);
    if (current.cost > visited.get(currentKey).cost) continue;

    for (const next of neighborsOf(map, current.x, current.y)) {
      const traversal = evaluateTraversalStep(
        state,
        unitId,
        { x: current.x, y: current.y },
        { x: next.x, y: next.y },
        opts
      );
      if (!traversal.valid) continue;
      const cost = current.cost + traversal.totalCost;
      if (cost > budget) continue;
      const key = tileKey(next.x, next.y);
      const known = visited.get(key);
      if (!known || cost < known.cost) {
        visited.set(key, { x: next.x, y: next.y, cost, from: currentKey });
        frontier.push({ x: next.x, y: next.y, cost });
      }
    }
  }
  return visited;
}

/**
 * Shortest valid path (inclusive of origin) or null when unreachable.
 */
function findPath(state, unitId, target, options) {
  const range = computeMovementRange(state, unitId, options);
  const key = tileKey(target.x, target.y);
  if (!range.has(key)) return null;
  const path = [];
  let cursor = key;
  while (cursor) {
    const node = range.get(cursor);
    path.unshift({ x: node.x, y: node.y });
    cursor = node.from;
  }
  return path;
}

function pathCost(state, unitId, path, options) {
  let cost = 0;
  for (let i = 1; i < path.length; i += 1) {
    const traversal = evaluateTraversalStep(state, unitId, path[i - 1], path[i], options);
    if (!traversal.valid) return Infinity;
    cost += traversal.totalCost;
  }
  return cost;
}

function validatePath(state, unitId, path, options) {
  const errors = [];
  const map = getMap(state);
  const unit = state.units[unitId];
  if (!Array.isArray(path) || path.length === 0) {
    return { valid: false, errors: ["Path is empty."], cost: 0, tiles: 0 };
  }
  if (path[0].x !== unit.x || path[0].y !== unit.y) {
    errors.push("Path must start on the unit's current tile.");
  }
  for (let i = 1; i < path.length; i += 1) {
    const step = path[i];
    const previous = path[i - 1];
    if (!inBounds(map, step.x, step.y)) {
      errors.push("Path leaves the map at step " + i + ".");
      break;
    }
    const traversal = evaluateTraversalStep(state, unitId, previous, step, options);
    if (!traversal.valid) {
      errors.push("Path step " + i + ": " + traversal.errors.join(" "));
      break;
    }
  }
  const cost = errors.length ? Infinity : pathCost(state, unitId, path, options);
  const budget = calculateUnitStats(state, unitId).movement;
  if (!errors.length && cost > budget) {
    errors.push("Path costs " + cost + " but movement is " + budget + ".");
  }
  return {
    valid: errors.length === 0,
    errors,
    cost: errors.length ? 0 : cost,
    tiles: path.length - 1
  };
}

/**
 * Grid line of sight. Intermediate blocking tiles stop the line.
 */
function hasLineOfSight(map, from, to, state) {
  let x0 = from.x;
  let y0 = from.y;
  const x1 = to.x;
  const y1 = to.y;
  const dx = Math.abs(x1 - x0);
  const dy = Math.abs(y1 - y0);
  const sx = x0 < x1 ? 1 : -1;
  const sy = y0 < y1 ? 1 : -1;
  let err = dx - dy;
  let guard = (dx + dy) * 2 + 4;

  while (guard-- > 0) {
    if (x0 === x1 && y0 === y1) return true;
    const doubled = err * 2;
    if (doubled > -dy) {
      err -= dy;
      x0 += sx;
    } else if (doubled < dx) {
      err += dx;
      y0 += sy;
    }
    if (x0 === x1 && y0 === y1) return true;
    const terrain = terrainAt(map, x0, y0, state);
    if (!terrain || terrain.blocksLineOfSight) return false;
  }
  return false;
}

/**
 * Area shapes: single, adjacent, diamond radius.
 */
const AREA_SHAPES = {
  single(center) {
    return [{ x: center.x, y: center.y }];
  },

  adjacent(center, area, map) {
    const tiles = [{ x: center.x, y: center.y }];
    for (const tile of neighborsOf(map, center.x, center.y)) {
      tiles.push({ x: tile.x, y: tile.y });
    }
    return tiles;
  },

  diamond(center, area, map) {
    const radius = area.radius == null ? 1 : area.radius;
    const tiles = [];
    for (let dy = -radius; dy <= radius; dy += 1) {
      for (let dx = -radius; dx <= radius; dx += 1) {
        if (Math.abs(dx) + Math.abs(dy) > radius) continue;
        const x = center.x + dx;
        const y = center.y + dy;
        if (inBounds(map, x, y)) tiles.push({ x, y });
      }
    }
    return tiles;
  },

  square(center, area, map) {
    const radius = area.radius == null ? 1 : area.radius;
    const tiles = [];
    for (let dy = -radius; dy <= radius; dy += 1) {
      for (let dx = -radius; dx <= radius; dx += 1) {
        const x = center.x + dx;
        const y = center.y + dy;
        if (inBounds(map, x, y)) tiles.push({ x, y });
      }
    }
    return tiles;
  },

  ring(center, area, map) {
    const radius = area.radius == null ? 1 : area.radius;
    const inner = area.innerRadius == null ? radius : area.innerRadius;
    const tiles = [];
    for (let dy = -radius; dy <= radius; dy += 1) {
      for (let dx = -radius; dx <= radius; dx += 1) {
        const distance = Math.abs(dx) + Math.abs(dy);
        if (distance > radius || distance < inner) continue;
        const x = center.x + dx;
        const y = center.y + dy;
        if (inBounds(map, x, y)) tiles.push({ x, y });
      }
    }
    return tiles;
  },

  cross(center, area, map) {
    const radius = area.radius == null ? 1 : area.radius;
    const tiles = [{ x: center.x, y: center.y }];
    for (let step = 1; step <= radius; step += 1) {
      tiles.push({ x: center.x + step, y: center.y });
      tiles.push({ x: center.x - step, y: center.y });
      tiles.push({ x: center.x, y: center.y + step });
      tiles.push({ x: center.x, y: center.y - step });
    }
    return tiles.filter((tile) => inBounds(map, tile.x, tile.y));
  },

  line(center, area, map, context) {
    const length = area.length == null ? (area.radius == null ? 3 : area.radius) : area.length;
    const origin = (context && context.origin) || center;
    const direction = orientationFrom(origin, center);
    const tiles = area.includeCenter === false ? [] : [{ x: center.x, y: center.y }];
    for (let step = 1; step <= length; step += 1) {
      tiles.push({ x: center.x + direction.dx * step, y: center.y + direction.dy * step });
    }
    return tiles.filter((tile) => inBounds(map, tile.x, tile.y));
  },

  path(center, area, map, context) {
    const origin = (context && context.origin) || center;
    const direction = orientationFrom(origin, center);
    const tiles = [];
    let x = origin.x;
    let y = origin.y;
    let guard = 0;
    while (guard < GAME_CONFIG.grid.maxPathLength && (x !== center.x || y !== center.y)) {
      guard += 1;
      x += direction.dx;
      y += direction.dy;
      if (!inBounds(map, x, y)) break;
      tiles.push({ x, y });
    }
    if (!tiles.length) tiles.push({ x: center.x, y: center.y });
    return tiles;
  },

  cone(center, area, map, context) {
    const radius = area.radius == null ? 2 : area.radius;
    const origin = (context && context.origin) || center;
    const direction = orientationFrom(origin, center);
    const tiles = [];
    for (let step = 0; step <= radius; step += 1) {
      const spread = area.spread == null ? step : Math.min(step, area.spread);
      for (let offset = -spread; offset <= spread; offset += 1) {
        const x = center.x + direction.dx * step + (direction.dx === 0 ? offset : 0);
        const y = center.y + direction.dy * step + (direction.dy === 0 ? offset : 0);
        if (inBounds(map, x, y)) tiles.push({ x, y });
      }
    }
    return tiles;
  },

  selfAura(center, area, map, context) {
    const radius = area.radius == null ? 1 : area.radius;
    const origin = (context && context.origin) || center;
    return AREA_SHAPES.diamond({ x: origin.x, y: origin.y }, { radius }, map);
  }
};

/** Cardinal orientation from an origin tile toward a target tile. */
function orientationFrom(origin, target) {
  const dx = target.x - origin.x;
  const dy = target.y - origin.y;
  if (dx === 0 && dy === 0) return { dx: 0, dy: 1 };
  if (Math.abs(dx) >= Math.abs(dy)) return { dx: dx > 0 ? 1 : -1, dy: 0 };
  return { dx: 0, dy: dy > 0 ? 1 : -1 };
}

/* ---------------------------------------------------------------
 * DIAGONAL FACING AND FLANKING
 * Units face along the visible edges of an isometric tile.
 * Facing belongs to authoritative battle state. The renderer only consumes it.
 * -------------------------------------------------------------*/

const DIAGONAL_FACING = {
  northeast: { dx: 0, dy: -1 },
  southeast: { dx: 1, dy: 0 },
  southwest: { dx: 0, dy: 1 },
  northwest: { dx: -1, dy: 0 }
};

function normalizeFacing(facing) {
  return GAME_CONFIG.facing.directions.includes(facing) ? facing : "southeast";
}

function facingFromVector(vector) {
  if (!vector) return "southeast";
  if (Math.abs(vector.dx) >= Math.abs(vector.dy)) {
    return vector.dx >= 0 ? "southeast" : "northwest";
  }
  return vector.dy >= 0 ? "southwest" : "northeast";
}

function facingFromTiles(origin, target, fallback) {
  if (!origin || !target || (origin.x === target.x && origin.y === target.y)) {
    return normalizeFacing(fallback);
  }
  return facingFromVector({ dx: target.x - origin.x, dy: target.y - origin.y });
}

function oppositeFacing(facing) {
  return {
    northeast: "southwest",
    southwest: "northeast",
    southeast: "northwest",
    northwest: "southeast"
  }[normalizeFacing(facing)];
}

function attackArcAgainstFacing(targetFacing, directionFromTargetToAttacker) {
  const facing = normalizeFacing(targetFacing);
  const attackerDirection = normalizeFacing(directionFromTargetToAttacker);
  if (attackerDirection === facing) return "front";
  if (attackerDirection === oppositeFacing(facing)) return "rear";
  return "side";
}

function flankProfile(state, sourceUnitId, targetUnitId, options) {
  const opts = options || {};
  const source = state.units[sourceUnitId];
  const target = state.units[targetUnitId];
  if (!source || !target || sourceUnitId === targetUnitId || !isHostile(state, sourceUnitId, targetUnitId)) {
    const neutral = GAME_CONFIG.facing.flank.front;
    return {
      arc: "front",
      targetFacing: target ? normalizeFacing(target.facing) : "southeast",
      attackerDirection: null,
      accuracyBonus: neutral.accuracyBonus,
      damageMultiplier: neutral.damageMultiplier
    };
  }
  const sourceTile = opts.sourceTile || { x: source.x, y: source.y };
  const targetTile = opts.targetTile || { x: target.x, y: target.y };
  const attackerDirection = facingFromTiles(targetTile, sourceTile, target.facing);
  const arc = attackArcAgainstFacing(target.facing, attackerDirection);
  const modifier = GAME_CONFIG.facing.flank[arc] || GAME_CONFIG.facing.flank.front;
  return {
    arc,
    targetFacing: normalizeFacing(target.facing),
    attackerDirection,
    accuracyBonus: modifier.accuracyBonus,
    damageMultiplier: modifier.damageMultiplier
  };
}

/**
 * Which way a unit turns when nothing authored says otherwise.
 *
 * Toward the nearest hostile its faction is aware of. A faction that starts
 * blind faces the middle of the map instead of pivoting toward an ambush it
 * cannot possibly have noticed.
 */
function nearestHostileFacing(state, unitId) {
  const unit = state.units[unitId];
  if (!unit) return "southeast";
  let nearest = null;
  let nearestDistance = Infinity;
  for (const threat of perceivedThreats(state, perceptionDeps(), unit.teamId)) {
    if (threat.unitId === unitId || !threat.alive) continue;
    const distance = gridDistance(unit, { x: threat.x, y: threat.y });
    if (distance < nearestDistance) {
      nearest = { x: threat.x, y: threat.y };
      nearestDistance = distance;
    }
  }
  if (nearest) return facingFromTiles(unit, nearest, unit.facing);
  const map = getMap(state);
  return facingFromTiles(
    unit,
    { x: (map.width - 1) / 2, y: (map.height - 1) / 2 },
    "southeast"
  );
}

function dedupeTiles(tiles) {
  const seen = new Set();
  const out = [];
  for (const tile of tiles) {
    const key = tileKey(tile.x, tile.y);
    if (seen.has(key)) continue;
    seen.add(key);
    out.push({ x: tile.x, y: tile.y });
  }
  return out;
}

function tilesInArea(state, center, area, context) {
  const map = getMap(state);
  const shape = AREA_SHAPES[area && area.shape ? area.shape : "single"];
  if (!shape) return [{ x: center.x, y: center.y }];
  return dedupeTiles(
    shape(center, area || {}, map, context || {}).filter((t) => inBounds(map, t.x, t.y))
  );
}
/* ---------------------------------------------------------------
 * BATTLE STATE
 * -------------------------------------------------------------*/

function createBattle(encounterId, seed, options) {
  const opts = options || {};
  // A mission file that declares phases or beats brings its runtime with it.
  // Encounters without one never touch the scripting layer at all.
  if (!opts.missionScript && MISSION_CONTENT.scriptsByEncounter[encounterId]) {
    const candidate = MISSION_CONTENT.scriptsByEncounter[encounterId];
    if ((candidate.phases || []).length || (candidate.beats || []).length) {
      opts.missionScript = candidate;
    }
  }
  if (opts.missionScript) registerMissionScript(opts.missionScript);
  const encounter = CONTENT.encounters[encounterId];
  if (!encounter) throw new Error("Unknown encounter: " + encounterId);
  if (CONTENT.errors.length && !opts.ignoreContentErrors) {
    throw new Error(
      "Content validation failed; battle initialization blocked:\n" +
        CONTENT.errors.join("\n")
    );
  }

  const state = {
    id: "battle-" + (opts.battleNumber || 1),
    encounterId,
    mapId: encounter.mapId,

    currentTime: 0,

    teams: encounter.teams.map((t) => ({ ...t })),
    units: {},
    unitOrder: [],

    scheduledEvents: [],
    resolutionQueue: [],

    objectiveState: {
      objectiveId: encounter.objective,
      params: encounter.objectiveParams ? JSON.parse(JSON.stringify(encounter.objectiveParams)) : {},
      progress: {},
      // Script-owned objective stack. Empty means "use the single legacy
      // objective above", which is what every pre-existing encounter does.
      entries: []
    },
    battleLog: [],

    // Faction relationships live in battle state so they serialize with a save
    // and can be rewritten mid-battle. Defaults reproduce the old behaviour.
    factions: createFactionState(
      encounter.teams.map((team) => team.id),
      (opts.missionScript && opts.missionScript.factions) || encounter.factions || null
    ),

    // Reaction runtime: economy, link state and any suspended choice prompt.
    // Always present — an encounter with no link simply has no legal
    // reactions, and the trigger index makes discovery free in that case.
    reactions: createReactionState(REACTION_CONTENT, {
      unlockedLinkIds: opts.unlockedLinkIds || null,
      autoResolve: opts.autoResolveReactions !== false,
      autoPolicy: opts.reactionPolicy || "takeFirst"
    }),
    autoResolveReactions: opts.autoResolveReactions !== false,

    // Why each event happened. Ambient parentage plus a chain id, so a
    // reaction cascade can be attributed, bounded and explained.
    causality: createCausalityState(),

    // Things standing on tiles that are not units: mines, charges, beacons.
    // Always present, so no code path has to ask whether the collection exists.
    fixtures: createFixtureState(),

    // Actions that have been chosen and paid for but have not happened yet.
    // The only window in which a defender can change what is about to occur.
    interventions: createInterventionState(),

    // A commanded order over activations that are already coming. Empty means
    // ordinary time rules, which is nearly always.
    sequencing: createSequencingState(),

    // Faction-scoped resource balances. Unit balances stay on the unit, where
    // they already live; this is the shared half of one resource system.
    resources: createResourceState(COMBAT_RESOURCE_DEFINITIONS, encounter.teams.map((team) => team.id)),

    // Faction-scoped battlefield knowledge. Always present so no code path has
    // to ask whether it exists; `enabled: false` restores full information and
    // is what the A/B benchmark toggles.
    perception: createPerception(encounter.teams.map((team) => team.id), {
      enabled: opts.perception !== false,
      config: (opts.missionScript && opts.missionScript.perception) || encounter.perception || null
    }),

    // Mission scripting runtime. Null for encounters with no script, which
    // keeps the whole system off the critical path for existing content.
    mission: opts.missionScript ? createMissionRuntimeState(opts.missionScript) : null,
    missionScriptId: opts.missionScript ? opts.missionScript.id || null : null,

    randomSeed: seed == null ? GAME_CONFIG.defaults.seed : seed,
    randomState: createRandomState(seed == null ? GAME_CONFIG.defaults.seed : seed),

    activeUnitId: null,
    activation: null,
    winner: null,
    finished: false,

    activationCount: 0,
    errors: [],

    terrainOverrides: {},
    delayedEffects: [],
    spawnCount: 0,
    nextRuntimeId: 1
  };

  const roster = (options && options.roster) || null;
  const rosterTeamId = (options && options.rosterTeamId) || "player";
  let rosterIndex = 0;
  encounter.units.forEach((spawn, index) => {
    let definitionId = spawn.definitionId;
    let equipment = spawn.equipment || null;
    let rosterEntry = null;
    if (roster && spawn.teamId === rosterTeamId) {
      const entry = roster[rosterIndex];
      rosterEntry = entry || null;
      rosterIndex += 1;
      if (entry) {
        definitionId = entry.definitionId;
        equipment = entry.equipment || null;
      }
    }
    const unit = createRuntimeUnit(state, {
      id: "u" + (index + 1),
      definitionId,
      teamId: spawn.teamId,
      equipment,
      x: spawn.x,
      y: spawn.y,
      facing: (rosterEntry && rosterEntry.facing) || spawn.facing || null,
      aiProfileId: spawn.aiProfile || null,
      // A deployed operator's ref wins over the encounter's placeholder, so a
      // campaign mission addresses the same units file-authored fixtures do.
      ref: (rosterEntry && rosterEntry.ref) || spawn.ref || null,
      groupId: spawn.groupId || null,
      modifiers: rosterEntry && rosterEntry.modifiers ? rosterEntry.modifiers : spawn.modifiers || null
    });
    state.units[unit.id] = unit;
    state.unitOrder.push(unit.id);
  });

  // Establish what each faction can see before anything consults it. Silent,
  // because nothing has changed yet — this is the opening state of the world.
  refreshPerception(state, perceptionDeps(), { emit: false });
  seedSearchAnchors(state);
  grantObjectiveIntel(state);

  // Units without authored facing begin oriented toward their nearest *known*
  // hostile, falling back to the map default when a faction starts blind.
  for (const id of state.unitOrder) {
    if (!state.units[id].facing) state.units[id].facing = nearestHostileFacing(state, id);
  }

  // Apply loadout/condition modifiers before finalizing starting HP and schedule.
  // Negative max-HP modifiers must never leave current HP above the live maximum.
  for (const id of state.unitOrder) {
    const stats = calculateUnitStats(state, id);
    // Start at the *effective* maximum, not the chassis base. Equipment that
    // raises max HP used to leave a unit permanently short of full at battle
    // start; condition modifiers that lower it still cap correctly.
    state.units[id].currentHp = Math.max(0, stats.maxHp);
    state.units[id].alive = state.units[id].currentHp > 0;
    state.units[id].nextActionTime = FORMULAS.timeline.recoveryDelay(
      stats.speed,
      FORMULAS.timeline.baseRecovery
    );
  }

  // Links can only be judged once every unit is on the field.
  refreshReactionLinks(state);

  logLine(state, "battleStarted", "Battle started: " + encounter.name);

  if (state.mission) {
    state.campaignFlagsSnapshot = opts.campaignFlags ? { ...opts.campaignFlags } : {};
    // Headless callers (tests, soaks, deterministic replay) resolve blocking
    // scenes with their authored defaults so a scripted battle runs to
    // completion without a renderer. The authoritative outcome is identical
    // either way, because scenes never touch battle state — only their choices
    // do, and those resolve to a fixed default rather than a random pick.
    state.autoResolveScenes = opts.autoResolveScenes === true;

    // Groups that start asleep put their units to sleep before the first turn.
    for (const groupId of Object.keys(state.mission.groups)) {
      if (state.mission.groups[groupId].active) continue;
      for (const unitId of state.unitOrder) {
        if (state.units[unitId].groupId === groupId) state.units[unitId].dormant = true;
      }
    }

    startMissionScript(state, {
      script: opts.missionScript,
      campaignFlags: state.campaignFlagsSnapshot,
      autoResolve: state.autoResolveScenes
    });
    processAllEvents(state);
    checkObjectives(state);
  }
  return state;
}

/**
 * Builds a runtime unit from a definition. Used for the starting roster and
 * for anything summoned later; the engine never names a specific unit.
 */
function createRuntimeUnit(state, options) {
  const definition = CONTENT.units[options.definitionId];
  const id = options.id || "s" + state.nextRuntimeId;
  if (!options.id) state.nextRuntimeId += 1;
  const resources = {};
  for (const key of Object.keys(definition.resources || {})) {
    const resource = definition.resources[key];
    resources[key] = {
      current: resource.startsAt == null ? resource.max : resource.startsAt,
      max: resource.max
    };
  }
  const equipment = {};
  for (const slot of GAME_CONFIG.equipment.slots) {
    const equipmentId =
      options.equipment && options.equipment[slot] !== undefined
        ? options.equipment[slot]
        : definition.defaultEquipment[slot];
    if (!equipmentId) continue;
    if (!CONTENT.equipment[equipmentId]) continue;
    if (!isEquipmentCompatible(options.definitionId, equipmentId)) continue;
    equipment[slot] = equipmentId;
  }

  return {
    id,
    definitionId: options.definitionId,
    teamId: options.teamId,
    equipment,
    creationOrder: state.unitOrder.length,

    x: options.x,
    y: options.y,
    facing: options.facing ? normalizeFacing(options.facing) : null,

    currentHp:
      options.currentHp == null ? definition.baseStats.maxHp : options.currentHp,

    nextActionTime: options.nextActionTime == null ? 0 : options.nextActionTime,

    statuses: [],
    cooldowns: {},
    resources,
    shields: [],
    modifiers: (options.modifiers || []).map((modifier) => ({ ...modifier })),

    summonedBy: options.summonedBy || null,
    remainingLifetime: options.lifetime == null ? null : options.lifetime,

    aiProfileId: options.aiProfileId || definition.aiProfile || null,

    // Authored identity. The mission runtime addresses units by `ref` rather
    // than by index, which is what lets an objective or a trigger name a unit
    // that gets spawned mid-battle.
    ref: options.ref || id,
    groupId: options.groupId || null,
    // A dormant unit stays on the map but takes no turns, which is how
    // reinforcement waves and sleeping sectors work.
    dormant: options.dormant === true,

    alive: true
  };
}

function logLine(state, type, text, data) {
  state.battleLog.push({
    index: state.battleLog.length,
    time: Math.round(state.currentTime * 100) / 100,
    type,
    text,
    data: data || null
  });
}

function unitLabel(state, unitId) {
  const unit = state.units[unitId];
  if (!unit) return "?";
  return CONTENT.units[unit.definitionId].name + " [" + unit.id + "]";
}

function livingUnits(state) {
  return state.unitOrder.map((id) => state.units[id]).filter((u) => u.alive);
}

function teamLabel(state, teamId) {
  const team = (state.teams || []).find((entry) => entry.id === teamId);
  return (team && team.name) || teamId;
}

/** Log text for a knowledge transition, phrased from the faction's side. */
function knowledgeLogText(state, event) {
  const who = teamLabel(state, event.factionId);
  const what = unitLabel(state, event.unitId);
  if (event.to === "acquired") return who + " acquires " + what;
  if (event.to === "unseen") return who + " loses track of " + what;
  if (event.from === "unseen") return who + " picks up a contact: " + what;
  return who + " downgrades " + what + " to " + event.to;
}

/**
 * The one place hostility is decided. Reads the battle's faction matrix, which
 * defaults to "different team means enemy" so every pre-existing encounter
 * behaves exactly as before, and which a mission script can rewrite mid-battle
 * without recreating a single unit.
 */
function isHostile(state, aId, bId) {
  const a = state.units[aId];
  const b = state.units[bId];
  if (!a || !b) return false;
  return factionsHostile(state.factions, a.teamId, b.teamId);
}

/** True when two units are on the same side — same team, or teams that have
 *  been made allies. Used for ally targeting and threat display. */
function isFriendly(state, aId, bId) {
  const a = state.units[aId];
  const b = state.units[bId];
  if (!a || !b) return false;
  return relationshipBetween(state.factions, a.teamId, b.teamId) === "allied";
}

/* ---------------------------------------------------------------
 * TIMELINE
 * -------------------------------------------------------------*/

function compareTimelineEntries(a, b) {
  if (a.time !== b.time) return a.time - b.time;
  // A commanded sequence breaks ties its own way, and only between two units
  // the same command named. This is what lets a reorder express *every*
  // permutation: units sharing a timestamp are otherwise separated by speed,
  // which would silently undo the order the player chose.
  if (a.sequenceIndex != null && b.sequenceIndex != null && a.sequenceIndex !== b.sequenceIndex) {
    return a.sequenceIndex - b.sequenceIndex;
  }
  if (a.speed !== b.speed) return b.speed - a.speed;
  return a.creationOrder - b.creationOrder;
}

/**
 * Who is scheduled, and when.
 *
 * The one place a commanded sequence is applied. A unit named by a live
 * command reports the slot it was dealt instead of its own clock; the slot
 * came out of the set those units already owned, so nobody outside the command
 * shifts by a single position. `unit.nextActionTime` is untouched — see
 * `src/combat/sequencing.js` for why that matters.
 */
function timelineCandidates(state) {
  const sequence = state.sequencing;
  return livingUnits(state)
    .filter((unit) => !unit.dormant)
    .map((unit) => {
      const commanded = sequencedEntry(sequence, unit.id);
      return {
        unitId: unit.id,
        time: commanded ? commanded.time : unit.nextActionTime,
        scheduledTime: unit.nextActionTime,
        sequenceIndex: commanded ? commanded.index : null,
        speed: calculateUnitStats(state, unit.id).speed,
        creationOrder: unit.creationOrder
      };
    });
}

function getNextActionableUnitId(state) {
  const candidates = timelineCandidates(state);
  if (!candidates.length) return null;
  candidates.sort(compareTimelineEntries);
  return candidates[0].unitId;
}

/**
 * Pure projection of upcoming activations. Never mutates authoritative state.
 * Future recovery is estimated with the configured wait recovery.
 */
function previewTimeline(state, count) {
  const total = count == null ? GAME_CONFIG.timeline.previewCount : count;
  const projected = timelineCandidates(state).map((entry) => ({
    ...entry,
    estimated: false
  }));
  if (!projected.length) return [];

  const out = [];
  for (let i = 0; i < total; i += 1) {
    projected.sort(compareTimelineEntries);
    const next = projected[0];
    out.push({
      order: i + 1,
      unitId: next.unitId,
      time: Math.round(next.time * 100) / 100,
      speed: next.speed,
      estimated: next.estimated
    });
    const rate = FORMULAS.timeline.turnRate(next.speed);
    next.time += GAME_CONFIG.timeline.waitRecovery / rate;
    next.estimated = true;
  }
  return out;
}

/* ---------------------------------------------------------------
 * COMMANDED SEQUENCING — the engine side
 *
 * The pure planner in `src/combat/sequencing.js` knows nothing about battles.
 * This is the adapter: it turns the live timeline into the abstract entry list
 * the planner wants, and it is the *only* way anything asks what a command may
 * reorder. The preview, the validator, the executor and the tests all come
 * through here, so none of them can disagree about the window.
 * -------------------------------------------------------------*/

/**
 * A resource definition by id, whatever scope it has.
 *
 * The one lookup that lets an ability cost, a reaction cost and a command cost
 * all name the same resource and mean the same thing.
 */
function combatResourceDefinition(resourceId) {
  const raw = REACTION_INDEX.resourceById[resourceId];
  if (raw) return normalizeResourceDefinition({ id: resourceId, ...raw });
  // Pools declared only on a chassis have no registry entry. They are
  // unit-scoped by definition — a unit's own resources dictionary is the only
  // place they exist — so this describes what is already true rather than
  // inventing anything.
  return normalizeResourceDefinition({ id: resourceId, scope: "unit" });
}

/** Who pays for a cost of this resource when this unit uses the ability. */
function costOwnerFor(state, unitId, definition) {
  const unit = state.units[unitId];
  if (!unit) return null;
  return definition.scope === "faction" ? { teamId: unit.teamId } : { unitId };
}

/**
 * What a unit's side of a named resource currently looks like.
 *
 * Deliberately routed through the same definition and owner resolution that
 * spending, restoring and transferring use. Every previous scope bug in this
 * project came from a second lookup that only knew about `unit.resources`, so
 * asking a question about a balance goes through the same door as changing one.
 */
function resourceReadingFor(state, unitId, resourceId) {
  if (!resourceId) return null;
  const definition = combatResourceDefinition(resourceId);
  const owner = costOwnerFor(state, unitId, definition);
  if (!owner) return null;
  return readResource(state, definition, owner);
}

/**
 * Whether a unit can pay an ability's declared costs, in any scope.
 *
 * Shared by every validator that charges for an ability, so a faction-scoped
 * cost is refused for the right reason rather than passing because nobody
 * looked in the right pool.
 */
function abilityCostProblems(state, unitId, ability) {
  const problems = [];
  for (const resourceId of Object.keys((ability && ability.costs) || {})) {
    const definition = combatResourceDefinition(resourceId);
    const price = ability.costs[resourceId];
    if (!definition) {
      problems.push("Unknown resource " + resourceId + ".");
      continue;
    }
    const owner = costOwnerFor(state, unitId, definition);
    const check = canSpendResource(state, definition, owner, price);
    if (!check.ok) {
      problems.push(
        "Not enough " + (definition.name || resourceId) + " (needs " + price + ")."
      );
    }
  }
  return problems;
}

/**
 * Which command an ability is issued through.
 *
 * Most abilities are an ordinary `useAbility`. A few need input that command
 * cannot carry: a route needs segments, a detonator needs a device, a command
 * needs an order. Declaring that once means the validator, the AI and the UI
 * all agree about it rather than each growing its own list of exceptions —
 * and the exceptions were already being got wrong. An AI handed a detonator
 * would enumerate it as an ordinary attack, spend its action resolving an
 * ability with no effects, and do nothing at all for the turn.
 */
function commandKindForAbility(ability) {
  if (!ability) return "useAbility";
  if (ability.trajectory) return "trajectory";
  if (ability.fixtureTargeting) return "activateFixture";
  if (ability.activationWindow) return "reorderActivations";
  return "useAbility";
}

/** Window rules an ability declares. Absent, the ability cannot sequence. */
function activationWindowRules(ability) {
  const declared = (ability && ability.activationWindow) || null;
  if (!declared) return null;
  return {
    relationship: declared.relationship || "allied",
    lookahead: declared.lookahead == null ? Infinity : declared.lookahead,
    maxUnits: declared.maxUnits == null ? 4 : declared.maxUnits,
    hostileBarrier: declared.hostileBarrier || "stop",
    includeActive: declared.includeActive === true
  };
}

/**
 * The upcoming activations one unit's command may sequence.
 *
 * Planned against the *effective* order — what the player is actually looking
 * at — so issuing a second command sees the world the first one produced,
 * rather than a timeline nobody is living in.
 */
function planUnitActivationWindow(state, unitId, ability) {
  const rules = activationWindowRules(ability);
  if (!rules) return null;
  const actor = state.units[unitId];
  const entries = timelineCandidates(state)
    .sort(compareTimelineEntries)
    .map((entry) => {
      const unit = state.units[entry.unitId];
      return {
        unitId: entry.unitId,
        time: entry.time,
        scheduledTime: entry.scheduledTime,
        relationship:
          entry.unitId === unitId
            ? "self"
            : relationshipBetween(state.factions, actor.teamId, unit.teamId),
        actionable: unit.alive && !unit.dormant,
        active: state.activeUnitId === entry.unitId
      };
    });
  return planActivationWindow(entries, { now: state.currentTime, ...rules });
}

/**
 * Says out loud when a commanded slot stopped applying.
 *
 * A commander whose order quietly stops being followed is worse than one whose
 * order is refused: the player planned around a sequence and has no way to
 * discover it changed.
 */
function reportDroppedSequence(state, dropped) {
  for (const entry of dropped || []) {
    logLine(
      state,
      "activationOrderDropped",
      unitLabel(state, entry.unitId) +
        (entry.reason === "gone"
          ? " leaves the commanded order"
          : " was rescheduled and returns to the ordinary timeline"),
      { unitId: entry.unitId, reason: entry.reason }
    );
  }
}

/**
 * The upcoming order this plan would produce, without committing anything.
 *
 * Pure, and deliberately built the same way the live comparator builds the
 * real one: dealt slot first, commanded index to break a tie between two
 * commanded units, and current position for everyone else. If this and the
 * comparator ever disagreed, the preview would be a lie — so they are the same
 * three rules written once each.
 */
function projectCommandedOrder(plan, order) {
  const dealt = dealSlots(plan, order);
  const bySlot = new Map(dealt.map((entry, index) => [entry.unitId, { time: entry.time, index }]));
  return plan.entries
    .map((record, position) => {
      const slot = bySlot.get(record.unitId);
      return {
        unitId: record.unitId,
        time: slot ? slot.time : record.time,
        sequenceIndex: slot ? slot.index : null,
        position
      };
    })
    .sort(
      (a, b) =>
        a.time - b.time ||
        (a.sequenceIndex != null && b.sequenceIndex != null
          ? a.sequenceIndex - b.sequenceIndex
          : 0) ||
        a.position - b.position
    )
    .map((entry) => entry.unitId);
}

/**
 * Everything the planning UI shows, and everything the acceptance run reads.
 *
 * Built from `planUnitActivationWindow` and `validateOrder` — the same two
 * calls the command validator makes — so a preview can never describe an order
 * the command would refuse, and never refuse one it would accept.
 */
function createCommandPlanModel(state, unitId, abilityId, order) {
  const ability = CONTENT.abilities[abilityId];
  const plan = planUnitActivationWindow(state, unitId, ability);
  if (!plan) return null;

  const chosen = (order || []).slice();
  const check = chosen.length
    ? validateOrder(plan, chosen)
    : { ok: false, reason: "no units selected" };
  const costProblems = abilityCostProblems(state, unitId, ability);
  const unchanged = check.ok && sameOrder(plan.naturalOrder, chosen);

  const describe = (record) => {
    const unit = state.units[record.unitId];
    const definition = CONTENT.units[unit.definitionId];
    const team = state.teams.find((entry) => entry.id === unit.teamId) || {};
    const selectedIndex = chosen.indexOf(record.unitId);
    return {
      unitId: record.unitId,
      ref: unit.ref || record.unitId,
      name: definition.name,
      glyph: definition.glyph,
      portrait: resolveDefinitionAsset(definition, "portrait", definition.glyph),
      teamId: unit.teamId,
      teamAccent: team.accent || "sky",
      teamMarker: team.marker || "●",
      hostile: record.relationship === "hostile",
      time: Math.round(record.time * 100) / 100,
      delay: Math.round(record.delay * 100) / 100,
      eligible: record.eligible,
      reason: record.reason,
      selected: selectedIndex >= 0,
      selectedIndex: selectedIndex >= 0 ? selectedIndex + 1 : null
    };
  };

  return {
    abilityId,
    abilityName: ability.name,
    costs: { ...(ability.costs || {}) },
    costText: describeAbilityCosts(state, unitId, ability),
    affordable: costProblems.length === 0,
    costProblems,
    maxUnits: plan.maxUnits,
    lookahead: plan.lookahead,
    barrier: plan.barrier
      ? { ...plan.barrier, name: CONTENT.units[state.units[plan.barrier.unitId].definitionId].name }
      : null,
    entries: plan.entries.map(describe),
    eligibleIds: plan.eligibleIds.slice(),
    naturalOrder: plan.naturalOrder.slice(),
    selectedOrder: chosen,
    resultingOrder: check.ok ? projectCommandedOrder(plan, chosen) : plan.entries.map((e) => e.unitId),
    unchanged,
    ok: check.ok && !unchanged && costProblems.length === 0,
    reason: costProblems[0] || (unchanged ? "That is already the order." : check.reason)
  };
}

/** "2 Command Points", in whatever scopes the ability draws from. */
function describeAbilityCosts(state, unitId, ability) {
  const parts = [];
  for (const resourceId of Object.keys((ability && ability.costs) || {})) {
    const definition = combatResourceDefinition(resourceId);
    parts.push(ability.costs[resourceId] + " " + ((definition && definition.name) || resourceId));
  }
  return parts.join(", ");
}

/** Why a transfer moved less than it was asked to. Stable phrasing, because
 *  the log, the forecast and the ability model all render it. */
function transferRefusalText(limitedBy) {
  switch (limitedBy) {
    case "source":
      return "not enough to give";
    case "destination":
      return "no room to receive";
    case "noSource":
      return "nothing there to draw from";
    case "noDestination":
      return "nowhere to put it";
    case "sourceUnavailable":
      return "that supply is unavailable";
    case "destinationUnavailable":
      return "that pool is unavailable";
    case "sameBalance":
      return "that would put it back where it came from";
    case "allOrNothing":
      return "not enough for a full transfer";
    default:
      return "nothing to move";
  }
}

/** Whether two id sequences are the same list in the same order. */
function sameOrder(a, b) {
  const left = a || [];
  const right = b || [];
  return left.length === right.length && left.every((id, index) => id === right[index]);
}

/** Drops commanded slots the timeline has overtaken. Cheap and idempotent. */
function refreshSequencing(state) {
  if (!sequenceIsActive(state.sequencing)) return [];
  return pruneSequence(state.sequencing, (unitId) => {
    const unit = state.units[unitId];
    if (!unit) return null;
    return { actionable: unit.alive && !unit.dormant, time: unit.nextActionTime };
  });
}

/* ---------------------------------------------------------------
 * TARGETING
 * -------------------------------------------------------------*/

/**
 * Generic concealment: any status flagged `untargetable` hides its bearer
 * from hostile unit-targeted abilities. Nothing here knows about Cloak.
 */
function isUnitConcealed(state, unitId) {
  const unit = state.units[unitId];
  if (!unit) return false;
  return unit.statuses.some((applied) => {
    const definition = CONTENT.statuses[applied.statusId];
    return definition && definition.untargetable === true;
  });
}

/** Statuses flagged `hidden` remove the bearer from an opposing view. */
function isUnitHiddenFrom(state, unitId, viewerTeamId) {
  const unit = state.units[unitId];
  if (!unit || !viewerTeamId || unit.teamId === viewerTeamId) return false;
  return unit.statuses.some((applied) => {
    const definition = CONTENT.statuses[applied.statusId];
    return definition && definition.hidden === true;
  });
}

const TARGET_FILTERS = {
  self(state, sourceUnitId, unit) {
    return unit.id === sourceUnitId;
  },
  ally(state, sourceUnitId, unit) {
    // "Not hostile" is not the same as "allied" once neutrals exist: a repair
    // must not be able to target a civilian faction the player merely tolerates.
    return unit.id === sourceUnitId || isFriendly(state, sourceUnitId, unit.id);
  },
  enemy(state, sourceUnitId, unit) {
    return isHostile(state, sourceUnitId, unit.id);
  },
  any() {
    return true;
  },
  emptyTile() {
    return false;
  }
};

function resolveTargetTile(state, target) {
  if (!target) return null;
  if (target.unitId && state.units[target.unitId]) {
    const unit = state.units[target.unitId];
    return { x: unit.x, y: unit.y };
  }
  if (typeof target.x === "number" && typeof target.y === "number") {
    return { x: target.x, y: target.y };
  }
  return null;
}

/** Occupancy as seen from a hypothetical source position. */
function unitAtProjected(state, x, y, sourceUnitId, from) {
  if (from && x === from.x && y === from.y) return state.units[sourceUnitId];
  return unitAt(state, x, y, sourceUnitId);
}

function evaluateTargeting(state, sourceUnitId, abilityId, target, origin) {
  const errors = [];
  const ability = CONTENT.abilities[abilityId];
  const map = getMap(state);
  const source = state.units[sourceUnitId];
  const from = origin || { x: source.x, y: source.y };
  const tile =
    target && target.unitId === sourceUnitId
      ? { x: from.x, y: from.y }
      : resolveTargetTile(state, target);

  if (!ability) {
    return { valid: false, errors: ["Unknown ability."], tiles: [], targetUnitIds: [] };
  }
  if (!tile) {
    return { valid: false, errors: ["No target supplied."], tiles: [], targetUnitIds: [] };
  }
  if (!inBounds(map, tile.x, tile.y)) errors.push("Target is outside the map.");

  const targeting = ability.targeting;
  const distance = gridDistance(from, tile);
  if (distance < targeting.rangeMin || distance > targeting.rangeMax) {
    errors.push("Target is out of range.");
  }
  if (
    targeting.requiresLineOfSight &&
    errors.length === 0 &&
    !hasLineOfSight(map, from, tile, state)
  ) {
    errors.push("Line of sight is blocked.");
  }

  const filter = TARGET_FILTERS[targeting.type];
  if (!filter) errors.push("Unknown targeting type: " + targeting.type + ".");

  const primary =
    target && target.unitId && state.units[target.unitId]
      ? state.units[target.unitId]
      : unitAtProjected(state, tile.x, tile.y, sourceUnitId, from);
  if (primary && !primary.alive && !targeting.allowsDefeated) {
    errors.push("Target is defeated.");
  }
  if (targeting.type === "emptyTile") {
    if (primary) errors.push("Target tile is occupied.");
    if (errors.length === 0 && !isWalkable(map, tile.x, tile.y, state)) {
      errors.push("Target tile is impassable.");
    }
  } else if (!primary) {
    errors.push("No unit on the target tile.");
  } else if (
    primary &&
    errors.length === 0 &&
    isHostile(state, sourceUnitId, primary.id) &&
    isUnitConcealed(state, primary.id)
  ) {
    errors.push("Target cannot be detected.");
  } else if (filter && errors.length === 0 && !filter(state, sourceUnitId, primary)) {
    errors.push("Target does not match this ability's targeting rule.");
  } else if (
    primary &&
    errors.length === 0 &&
    (targeting.area.shape || "single") === "single" &&
    !passesTargetFilters(state, targeting.filters, {
      unit: primary,
      sourceUnitId,
      abilityId
    })
  ) {
    // Single-target abilities are gated by their filters; area abilities let
    // the filters decide which units inside the shape are affected.
    errors.push("Target does not match this ability's filters.");
  }

  const tiles = errors.length
    ? []
    : tilesInArea(state, tile, targeting.area, { origin: from, sourceUnitId });
  const targetUnitIds = [];
  if (!errors.length && targeting.type !== "emptyTile") {
    for (const areaTile of tiles) {
      const occupant = unitAtProjected(state, areaTile.x, areaTile.y, sourceUnitId, from);
      if (!occupant) continue;
      if (!occupant.alive && !targeting.allowsDefeated) continue;
      if (!filter(state, sourceUnitId, occupant)) continue;
      if (
        !passesTargetFilters(state, targeting.filters, {
          unit: occupant,
          sourceUnitId,
          abilityId
        })
      ) {
        continue;
      }
      if (
        targeting.requiresLineOfSight &&
        !hasLineOfSight(map, from, { x: areaTile.x, y: areaTile.y }, state)
      ) {
        continue;
      }
      targetUnitIds.push(occupant.id);
    }
  }

  return {
    valid: errors.length === 0,
    errors,
    tile,
    tiles,
    targetUnitIds
  };
}

/* ---------------------------------------------------------------
 * EFFECT HANDLERS
 * -------------------------------------------------------------*/

function effectContextStats(state, sourceUnitId, targetUnitId, effect) {
  const source = calculateUnitStats(state, sourceUnitId);
  const target = calculateUnitStats(state, targetUnitId);
  return {
    attack: source.attack,
    magic: source.magic,
    accuracy: source.accuracy,
    defense: target.defense,
    resistance: target.resistance,
    evasion: target.evasion,
    targetMaxHp: target.maxHp,
    sourceMaxHp: source.maxHp,
    power: effect.power == null ? 0 : effect.power
  };
}

/**
 * Named quantities an effect may scale from.
 *
 * A registry rather than an expression language, on purpose. Content says
 * "scale from approach distance, 12 per tile, capped at 60"; it does not write
 * arithmetic, and the engine never evaluates authored code. Adding a source is
 * one entry here plus a line of documentation.
 */
const EFFECT_SCALING_SOURCES = {
  approachDistance: {
    label: "Approach distance",
    summary: "Tiles the source travelled on the route that produced this effect.",
    read: (state, context) => {
      const trajectory = state.trajectory;
      if (!trajectory || trajectory.unitId !== context.sourceUnitId) return 0;
      return trajectory.distanceTravelled;
    }
  },
  segmentDistance: {
    label: "Current segment distance",
    summary: "Tiles travelled in the segment that produced this effect.",
    read: (state, context) => {
      const trajectory = state.trajectory;
      if (!trajectory || trajectory.unitId !== context.sourceUnitId) return 0;
      return trajectory.segmentDistance;
    }
  },
  redirectCount: {
    label: "Redirects taken",
    summary: "How many hard turns the route has made so far.",
    read: (state, context) => {
      const trajectory = state.trajectory;
      if (!trajectory || trajectory.unitId !== context.sourceUnitId) return 0;
      return trajectory.redirectCount;
    }
  },
  hopIndex: {
    label: "Arc number",
    summary:
      "How far along a chain this node is. Zero on the initial target, one on " +
      "the first arc. Pair it with a negative `perUnit` to author decay.",
    read: (state, context) => {
      const chain = propagationContextOf(state, context.sourceUnitId);
      return chain ? chain.hop : 0;
    }
  },
  hopDistance: {
    label: "Arc length",
    summary: "Tiles the current arc crossed to reach this node.",
    read: (state, context) => {
      const chain = propagationContextOf(state, context.sourceUnitId);
      return chain ? chain.hopDistance : 0;
    }
  },
  propagationKills: {
    label: "Kills so far this chain",
    summary:
      "Units this chain has already destroyed. Counted, never re-triggered, so " +
      "rewarding a kill cannot feed itself.",
    read: (state, context) => {
      const chain = propagationContextOf(state, context.sourceUnitId);
      return chain ? chain.kills : 0;
    }
  },

  /**
   * A condition the target is already carrying.
   *
   * This is the setup-and-payoff primitive. Everything the engine needed for
   * "a marked target takes more" already existed — a status to apply, a
   * condition to read it — except the one connection that makes the payoff a
   * *number* rather than a branch. Naming the status here rather than
   * branching on it in a damage handler is what keeps mark, ionise, expose and
   * whatever comes next the same mechanism.
   *
   * Counted rather than tested, so `statusTag` can measure how comprehensively
   * a target has been taken apart. A status id contributes at most one,
   * because reapplying a status refreshes its duration instead of stacking.
   */
  targetStatus: {
    label: "Status on the target",
    summary:
      "How many of the target's statuses match. Name `statusId` for one condition or " +
      "`statusTag` for a family of them.",
    read: (state, context, scaling) => countMatchingStatuses(state, context.targetUnitId, scaling)
  }
};

export const EFFECT_SCALING_IDS = Object.keys(EFFECT_SCALING_SOURCES);

function countMatchingStatuses(state, unitId, query) {
  const unit = state.units[unitId];
  if (!unit || !query) return 0;
  if (!query.statusId && !query.statusTag) return 0;
  let count = 0;
  for (const applied of unit.statuses || []) {
    if (query.statusId && applied.statusId !== query.statusId) continue;
    if (query.statusTag) {
      const definition = CONTENT.statuses[applied.statusId];
      if (!definition || !(definition.tags || []).includes(query.statusTag)) continue;
    }
    count += 1;
  }
  return count;
}

/** One scaling block, or several. Authored either way, read the same way. */
function scalingEntries(scaling) {
  if (!scaling) return [];
  return Array.isArray(scaling) ? scaling : [scaling];
}

/**
 * Extra power an effect earns from a named source.
 *
 * Zero when the source is unknown or the context does not apply — a strike
 * made standing still scales from nothing, which is exactly the counterplay
 * the operator is supposed to have.
 *
 * `perUnit` may be negative, which is how decay is authored: an arc that is
 * worth less the further it travels is the same mechanism as a charge that is
 * worth more the further it ran, with the sign flipped. `min` bounds the
 * downside and defaults to zero, so an author who does not think about decay
 * gets exactly the old behaviour.
 */
function effectScaling(state, context, scaling) {
  let power = 0;
  let multiplier = 1;
  for (const entry of scalingEntries(scaling)) {
    if (!entry || !entry.from) continue;
    const source = EFFECT_SCALING_SOURCES[entry.from];
    if (!source) continue;
    const value = source.read(state, context, entry) || 0;
    const per = Number(entry.perUnit || 0);
    const cap = entry.max == null ? Infinity : Number(entry.max);
    const floor = entry.min == null ? 0 : Number(entry.min);
    const bounded = Math.max(floor, Math.min(cap, value * per));
    if (entry.mode === "multiplier") multiplier *= 1 + bounded;
    else power += bounded;
  }
  return { power, multiplier };
}

function resolveDamageEffect(state, context) {
  const { sourceUnitId, targetUnitId, effect } = context;
  const formula = FORMULAS.damage[effect.formula];
  if (!formula) {
    state.errors.push("Missing damage formula: " + effect.formula);
    return;
  }
  const numbers = effectContextStats(state, sourceUnitId, targetUnitId, effect);
  // Approach distance, redirects taken, a mark already on the target — earned
  // value from a named source rather than a bespoke calculator per ability.
  const scaling = effectScaling(state, context, effect.scaling);
  if (scaling.power) numbers.power += scaling.power;
  const flank = flankProfile(state, sourceUnitId, targetUnitId, {
    sourceTile: context.sourceTile,
    targetTile: context.targetTile
  });

  if (effect.canMiss) {
    const chance = FORMULAS.accuracy.hitChance({
      accuracy: numbers.accuracy,
      evasion: numbers.evasion,
      bonus: (effect.accuracyBonus || 0) + flank.accuracyBonus
    });
    if (!rollChance(state, chance)) {
      queueEvent(state, {
        type: "attackMissed",
        sourceUnitId,
        targetUnitId,
        abilityId: context.abilityId || null,
        hitChance: chance,
        flankArc: flank.arc,
        targetFacing: flank.targetFacing,
        attackerDirection: flank.attackerDirection
      });
      return;
    }
  }

  const baseAmount = Math.max(1, Math.round(formula(numbers)));
  const amount = Math.max(
    1,
    Math.round(baseAmount * flank.damageMultiplier * scaling.multiplier)
  );
  queueEvent(state, {
    type: "damageResolved",
    sourceUnitId,
    targetUnitId,
    abilityId: context.abilityId || null,
    statusId: context.statusId || null,
    formula: effect.formula,
    baseAmount,
    amount,
    flankArc: flank.arc,
    targetFacing: flank.targetFacing,
    attackerDirection: flank.attackerDirection,
    damageMultiplier: flank.damageMultiplier,
    scalingBonus: scaling.power || 0,
    scalingMultiplier: scaling.multiplier
  });
}

function resolveHealEffect(state, context) {
  const { sourceUnitId, targetUnitId, effect } = context;
  const formula = FORMULAS.healing[effect.formula];
  if (!formula) {
    state.errors.push("Missing healing formula: " + effect.formula);
    return;
  }
  const numbers = effectContextStats(state, sourceUnitId, targetUnitId, effect);
  const amount = Math.max(1, Math.round(formula(numbers)));
  queueEvent(state, {
    type: "healResolved",
    sourceUnitId,
    targetUnitId,
    abilityId: context.abilityId || null,
    amount
  });
}

function resolveApplyStatusEffect(state, context) {
  const { sourceUnitId, targetUnitId, effect } = context;
  const chance = effect.chance == null ? 1 : effect.chance;
  if (chance < 1 && !rollChance(state, chance)) {
    queueEvent(state, {
      type: "statusResisted",
      sourceUnitId,
      targetUnitId,
      statusId: effect.statusId
    });
    return;
  }
  queueEvent(state, {
    type: "statusApplied",
    sourceUnitId,
    targetUnitId,
    statusId: effect.statusId
  });
}

function resolveRemoveStatusEffect(state, context) {
  queueEvent(state, {
    type: "statusRemoved",
    sourceUnitId: context.sourceUnitId,
    targetUnitId: context.targetUnitId,
    statusId: context.effect.statusId
  });
}

function resolveModifyTimelineEffect(state, context) {
  const effect = context.effect;
  const delta = (effect.delay || 0) - (effect.hasten || 0);
  queueEvent(state, {
    type: "timelineModified",
    sourceUnitId: context.sourceUnitId,
    targetUnitId: context.targetUnitId,
    abilityId: context.abilityId || null,
    delta
  });
}


/* ---------------------------------------------------------------
 * PHASE 3 EFFECT HANDLERS
 * -------------------------------------------------------------*/

function resolveShieldEffect(state, context) {
  const effect = context.effect;
  queueEvent(state, {
    type: "shieldApplied",
    sourceUnitId: context.sourceUnitId,
    targetUnitId: context.targetUnitId,
    abilityId: context.abilityId,
    amount: effect.amount == null ? 0 : effect.amount,
    duration: effect.duration || null,
    tags: effect.tags || []
  });
}

function resolveModifyStatEffect(state, context) {
  const effect = context.effect;
  queueEvent(state, {
    type: "statModifierApplied",
    sourceUnitId: context.sourceUnitId,
    targetUnitId: context.targetUnitId,
    abilityId: context.abilityId,
    stat: effect.stat,
    mode: effect.mode || "flat",
    value: effect.value,
    duration: effect.duration || null
  });
}

/** Shared forced-movement resolution for moveUnit, push and pull. */
function resolveForcedMovement(state, context, direction, distance) {
  const effect = context.effect;
  const unit = state.units[context.targetUnitId];
  if (!unit || !unit.alive) return;
  const map = getMap(state);
  const path = [{ x: unit.x, y: unit.y }];
  let x = unit.x;
  let y = unit.y;
  let blocked = false;
  for (let step = 0; step < distance; step += 1) {
    const nextX = x + direction.dx;
    const nextY = y + direction.dy;
    if (!inBounds(map, nextX, nextY)) {
      blocked = true;
      break;
    }
    if (effect.ignoresTerrain === true) {
      if (unitAt(state, nextX, nextY, unit.id)) {
        blocked = true;
        break;
      }
    } else {
      const traversal = evaluateTraversalStep(
        state,
        unit.id,
        { x, y },
        { x: nextX, y: nextY },
        {
          movementPolicy: effect.movementPolicy || "forced",
          ignoresElevation: effect.ignoresElevation === true
        }
      );
      if (!traversal.valid) {
        blocked = true;
        break;
      }
    }
    x = nextX;
    y = nextY;
    path.push({ x, y });
  }
  if (path.length > 1) {
    // The whole subtree below a shove is "because it was forced", which is how
    // a reaction can care that a target did not choose to be there.
    const blockTile = blocked ? { x: x + direction.dx, y: y + direction.dy } : null;
    const blocker = blockTile ? unitAt(state, blockTile.x, blockTile.y, unit.id) : null;
    const forcedEvent = queueEvent(state, {
      type: "unitForcedMove",
      sourceUnitId: context.sourceUnitId,
      unitId: unit.id,
      abilityId: context.abilityId,
      from: path[0],
      to: path[path.length - 1],
      path,
      tiles: path.length - 1,
      requested: distance,
      blocked,
      // Why it stopped short, and against what. Enough for a collision
      // consequence to be authored without a physics model.
      blockReason: blocked ? "the way is blocked" : null,
      blockTile,
      blockedBy: blocker ? blocker.id : null
    });
    if (forcedEvent.cause) forcedEvent.cause.forced = true;
  }
  if (blocked && effect.collision === "damage" && effect.collisionDamagePower) {
    resolveDamageEffect(state, {
      ...context,
      effect: {
        type: "damage",
        formula: effect.collisionFormula || "physical",
        power: effect.collisionDamagePower,
        canMiss: false
      }
    });
  }
}

function directionBetween(from, to) {
  const dx = to.x - from.x;
  const dy = to.y - from.y;
  if (dx === 0 && dy === 0) return { dx: 0, dy: 0 };
  if (Math.abs(dx) >= Math.abs(dy)) return { dx: dx > 0 ? 1 : -1, dy: 0 };
  return { dx: 0, dy: dy > 0 ? 1 : -1 };
}

function resolveMoveUnitEffect(state, context) {
  const effect = context.effect;
  const unit = state.units[context.targetUnitId];
  if (!unit) return;
  const direction = effect.direction || directionBetween(context.sourceTile || unit, unit);
  resolveForcedMovement(state, context, direction, effect.distance == null ? 1 : effect.distance);
}

/**
 * Precise displacement: exactly this far, in exactly this direction.
 *
 * The distinction from `push` is the whole tactical point. A shove asks for
 * maximum knockback; this asks for a *chosen* distance, because the difference
 * between two tiles and three is the difference between opening a firing lane
 * and wasting the setup. Everything else is identical — the target walks the
 * real forced-movement path, through the real traversal rules, and the event
 * says how far it actually got and what stopped it.
 */
function resolveDisplaceEffect(state, context) {
  const effect = context.effect;
  const unit = state.units[context.targetUnitId];
  if (!unit || !unit.alive) return;

  // Heading: authored outright, or away from / toward the source.
  let heading = effect.heading;
  if (!heading) {
    const from = context.sourceTile || state.units[context.sourceUnitId];
    if (!from) return;
    const away = effect.toward === true
      ? headingBetween({ x: unit.x, y: unit.y }, { x: Math.sign(from.x - unit.x) + unit.x, y: Math.sign(from.y - unit.y) + unit.y })
      : headingBetween({ x: from.x, y: from.y }, { x: from.x + Math.sign(unit.x - from.x), y: from.y + Math.sign(unit.y - from.y) });
    heading = away ? away.id : null;
  }
  if (!heading) return;

  const resistance = effect.ignoresResistance === true
    ? 0
    : calculateUnitStats(state, context.targetUnitId).displacementResistance;

  const plan = planDisplacement(
    { x: unit.x, y: unit.y },
    heading,
    effect.distance == null ? 1 : effect.distance,
    trajectoryDeps(state, context.targetUnitId, {
      movementPolicy: effect.movementPolicy || "forced",
      ignoresElevation: effect.ignoresElevation === true
    }),
    { resistance }
  );

  if (!plan.actual) {
    // Nothing moved, but the attempt is still a fact worth publishing: a shove
    // that bounced off a wall is exactly the moment a collision reaction wants.
    queueEvent(state, {
      type: "displacementBlocked",
      sourceUnitId: context.sourceUnitId,
      unitId: unit.id,
      abilityId: context.abilityId || null,
      heading: plan.heading,
      requested: plan.requested,
      actual: 0,
      resisted: plan.resisted,
      blockReason: plan.blockReason,
      blockTile: plan.blockTile,
      blockedBy: plan.blockedBy
    });
    return;
  }

  const forced = queueEvent(state, {
    type: "unitForcedMove",
    sourceUnitId: context.sourceUnitId,
    unitId: unit.id,
    abilityId: context.abilityId || null,
    from: { ...plan.origin },
    to: { ...plan.endpoint },
    path: [plan.origin].concat(plan.tiles),
    tiles: plan.actual,
    heading: plan.heading,
    // The precise half of the contract: what was asked for, what happened, and
    // why they differ. A reaction can respond to the shortfall as readily as
    // to the shove.
    requested: plan.requested,
    resisted: plan.resisted,
    blocked: plan.blocked,
    blockReason: plan.blockReason,
    blockTile: plan.blockTile,
    blockedBy: plan.blockedBy
  });
  if (forced.cause) forced.cause.forced = true;
}

function resolvePushEffect(state, context) {
  const unit = state.units[context.targetUnitId];
  if (!unit || !context.sourceTile) return;
  const direction = directionBetween(context.sourceTile, unit);
  resolveForcedMovement(
    state,
    context,
    direction,
    context.effect.distance == null ? 1 : context.effect.distance
  );
}

function resolvePullEffect(state, context) {
  const unit = state.units[context.targetUnitId];
  if (!unit || !context.sourceTile) return;
  const direction = directionBetween(unit, context.sourceTile);
  resolveForcedMovement(
    state,
    context,
    direction,
    context.effect.distance == null ? 1 : context.effect.distance
  );
}

function resolveTeleportEffect(state, context) {
  const effect = context.effect;
  const unitId = effect.applyTo === "source" ? context.sourceUnitId : context.targetUnitId;
  const unit = state.units[unitId];
  const tile = context.targetTile;
  if (!unit || !tile) return;
  // Teleport policy: destination legality only, no intermediate elevation.
  const traversal = evaluateTraversalStep(state, unitId, unit, tile, {
    movementPolicy: "teleport"
  });
  if (!traversal.valid) {
    state.errors.push("Teleport destination is not free.");
    return;
  }
  queueEvent(state, {
    type: "unitTeleported",
    sourceUnitId: context.sourceUnitId,
    unitId,
    abilityId: context.abilityId,
    from: { x: unit.x, y: unit.y },
    to: { x: tile.x, y: tile.y }
  });
}

function resolveSwapPositionsEffect(state, context) {
  const source = state.units[context.sourceUnitId];
  const target = state.units[context.targetUnitId];
  if (!source || !target || source.id === target.id) return;
  if (!target.alive || !source.alive) return;
  queueEvent(state, {
    type: "unitsSwapped",
    sourceUnitId: source.id,
    targetUnitId: target.id,
    abilityId: context.abilityId,
    sourceTile: { x: source.x, y: source.y },
    targetTile: { x: target.x, y: target.y }
  });
}

function resolveRestoreResourceEffect(state, context) {
  queueEvent(state, {
    type: "resourceRestored",
    sourceUnitId: context.sourceUnitId,
    targetUnitId: context.targetUnitId,
    resourceId: context.effect.resourceId,
    amount: context.effect.amount == null ? 0 : context.effect.amount
  });
}

function resolveSpendResourceEffect(state, context) {
  queueEvent(state, {
    type: "resourceSpent",
    sourceUnitId: context.sourceUnitId,
    targetUnitId: context.targetUnitId,
    resourceId: context.effect.resourceId,
    amount: context.effect.amount == null ? 0 : context.effect.amount
  });
}

/**
 * Moving a resource instead of conjuring one.
 *
 * The one effect behind every kind of support this game has: handing a frame
 * some of your own capacity, converting one resource into another, and
 * contributing a personal resource to the squad's shared pool are all the same
 * sum, so they are all this.
 *
 * `from` and `to` nominate an *owner* — the ability's source or its target.
 * Which pool that owner actually touches is decided by the resource
 * definition's own scope, which is why crossing from a unit resource to a
 * faction one needs no special case anywhere.
 *
 * Applied directly rather than queued as a spend and a gain. Two independent
 * events would be two independent clamps, and the pair could disagree: the
 * source debited for points the destination had no room to accept. Here the
 * arithmetic happens once and the event reports what actually moved.
 */
function resolveTransferResourceEffect(state, context) {
  const effect = context.effect;
  const plan = transferPlanFor(state, context);
  if (!plan) return;
  const result = applyTransfer(state, plan);
  queueEvent(state, {
    type: "resourceTransferred",
    sourceUnitId: context.sourceUnitId,
    targetUnitId: context.targetUnitId,
    abilityId: context.abilityId || null,
    fromUnitId: plan.fromUnitId,
    toUnitId: plan.toUnitId,
    fromResourceId: plan.fromDefinition.id,
    toResourceId: plan.toDefinition.id,
    fromScope: plan.fromDefinition.scope,
    toScope: plan.toDefinition.scope,
    requested: (effect.maxTransfers == null ? 1 : effect.maxTransfers) * result.gain,
    spent: result.spent,
    gained: result.gained,
    transfers: result.transfers,
    limitedBy: result.limitedBy || null
  });
}

/**
 * Resolves an authored transfer against the live battle.
 *
 * Null when either side names a resource nobody involved carries — which is a
 * content mistake the validator catches, but a mid-battle transform or a
 * summoned unit can also produce it, and a support ability that throws is
 * worse than one that does nothing.
 */
function transferPlanFor(state, context) {
  const effect = context.effect;
  const sourceId = context.sourceUnitId;
  const targetId = context.targetUnitId || context.sourceUnitId;
  const ownerOf = (which) => (which === "target" ? targetId : sourceId);
  const fromUnitId = ownerOf(effect.from || "source");
  const toUnitId = ownerOf(effect.to || "target");

  const fromDefinition = combatResourceDefinition(effect.resourceId);
  const toDefinition = combatResourceDefinition(effect.intoResourceId || effect.resourceId);
  if (!fromDefinition || !toDefinition) return null;
  if (!state.units[fromUnitId] || !state.units[toUnitId]) return null;

  return {
    fromUnitId,
    toUnitId,
    fromDefinition,
    toDefinition,
    fromOwner: costOwnerFor(state, fromUnitId, fromDefinition),
    toOwner: costOwnerFor(state, toUnitId, toDefinition),
    cost: effect.cost,
    gain: effect.gain,
    maxTransfers: effect.maxTransfers,
    partial: effect.partial
  };
}

function resolveCreateTerrainEffect(state, context) {
  const tile = context.targetTile;
  if (!tile) return;
  if (Object.keys(state.terrainOverrides).length >= GAME_CONFIG.limits.maxTerrainOverrides) {
    state.errors.push("Terrain override limit reached.");
    return;
  }
  queueEvent(state, {
    type: "terrainCreated",
    sourceUnitId: context.sourceUnitId,
    abilityId: context.abilityId,
    tile: { x: tile.x, y: tile.y },
    terrainId: context.effect.terrainId,
    duration: context.effect.duration || null
  });
}

function resolveRemoveTerrainEffect(state, context) {
  const tile = context.targetTile;
  if (!tile) return;
  queueEvent(state, {
    type: "terrainRemoved",
    sourceUnitId: context.sourceUnitId,
    tile: { x: tile.x, y: tile.y }
  });
}

function resolveSpawnUnitEffect(state, context) {
  const effect = context.effect;
  const tile = spawnPlacementTile(state, context);
  if (!tile) {
    state.errors.push("No legal spawn placement available.");
    return;
  }
  if (state.spawnCount >= GAME_CONFIG.limits.maxSpawnedUnits) {
    state.errors.push("Spawn limit reached.");
    return;
  }
  queueEvent(state, {
    type: "unitSpawned",
    sourceUnitId: context.sourceUnitId,
    abilityId: context.abilityId,
    definitionId: effect.definitionId,
    team: effect.team || "sourceTeam",
    tile,
    lifetime: effect.duration == null ? null : effect.duration
  });
}

function spawnPlacementTile(state, context) {
  const placement = context.effect.placement || { type: "targetTile" };
  const source = state.units[context.sourceUnitId];
  if (placement.type === "targetTile" && context.targetTile) {
    const tile = context.targetTile;
    return isTileFree(state, tile.x, tile.y) ? { x: tile.x, y: tile.y } : null;
  }
  if (placement.type === "adjacentToSource" && source) {
    const map = getMap(state);
    for (const neighbour of neighborsOf(map, source.x, source.y)) {
      if (isTileFree(state, neighbour.x, neighbour.y)) {
        return { x: neighbour.x, y: neighbour.y };
      }
    }
  }
  return null;
}

function resolveDespawnUnitEffect(state, context) {
  const unit = state.units[context.targetUnitId];
  if (!unit) return;
  queueEvent(state, {
    type: "unitDespawned",
    sourceUnitId: context.sourceUnitId,
    unitId: unit.id
  });
}

function resolveReviveEffect(state, context) {
  const unit = state.units[context.targetUnitId];
  if (!unit || unit.alive) return;
  const effect = context.effect;
  const stats = calculateUnitStats(state, unit.id);
  const amount =
    effect.percent != null
      ? Math.max(1, Math.round((stats.maxHp * effect.percent) / 100))
      : Math.max(1, effect.amount == null ? 1 : effect.amount);
  if (!isTileFree(state, unit.x, unit.y, unit.id)) {
    state.errors.push("Revive tile is occupied.");
    return;
  }
  queueEvent(state, {
    type: "unitRevived",
    sourceUnitId: context.sourceUnitId,
    targetUnitId: unit.id,
    abilityId: context.abilityId,
    amount,
    timelinePolicy: effect.timelinePolicy || "afterSource"
  });
}

function resolveTransformUnitEffect(state, context) {
  const effect = context.effect;
  if (!CONTENT.units[effect.definitionId]) {
    state.errors.push("Unknown transform definition: " + effect.definitionId);
    return;
  }
  queueEvent(state, {
    type: "unitTransformed",
    sourceUnitId: context.sourceUnitId,
    targetUnitId: context.targetUnitId,
    definitionId: effect.definitionId,
    duration: effect.duration || null,
    keepHpRatio: effect.keepHpRatio !== false
  });
}

function statusMatchesSelector(statusId, selector) {
  const definition = CONTENT.statuses[statusId];
  if (!definition) return false;
  if (selector.statusId) return statusId === selector.statusId;
  if (selector.tag) return (definition.tags || []).includes(selector.tag);
  if (selector.category) return definition.category === selector.category;
  return true;
}

function resolveCopyStatusEffect(state, context) {
  const source = state.units[context.sourceUnitId];
  if (!source) return;
  for (const applied of source.statuses) {
    if (!statusMatchesSelector(applied.statusId, context.effect)) continue;
    queueEvent(state, {
      type: "statusApplied",
      sourceUnitId: context.sourceUnitId,
      targetUnitId: context.targetUnitId,
      statusId: applied.statusId
    });
  }
}

function resolveTransferStatusEffect(state, context) {
  const source = state.units[context.sourceUnitId];
  if (!source) return;
  for (const applied of source.statuses.slice()) {
    if (!statusMatchesSelector(applied.statusId, context.effect)) continue;
    queueEvent(state, {
      type: "statusRemoved",
      sourceUnitId: context.sourceUnitId,
      targetUnitId: context.sourceUnitId,
      statusId: applied.statusId
    });
    queueEvent(state, {
      type: "statusApplied",
      sourceUnitId: context.sourceUnitId,
      targetUnitId: context.targetUnitId,
      statusId: applied.statusId
    });
  }
}

function resolveCleanseEffect(state, context) {
  const unit = state.units[context.targetUnitId];
  if (!unit) return;
  const effect = context.effect;
  const category = effect.category || "negative";
  let removed = 0;
  const limit = effect.count == null ? Infinity : effect.count;
  for (const applied of unit.statuses.slice()) {
    if (removed >= limit) break;
    const definition = CONTENT.statuses[applied.statusId];
    if (!definition) continue;
    const matches = effect.statusId
      ? applied.statusId === effect.statusId
      : effect.tag
      ? (definition.tags || []).includes(effect.tag)
      : definition.category === category;
    if (!matches) continue;
    removed += 1;
    queueEvent(state, {
      type: "statusRemoved",
      sourceUnitId: context.sourceUnitId,
      targetUnitId: unit.id,
      statusId: applied.statusId
    });
  }
}

function resolveDispelEffect(state, context) {
  const unit = state.units[context.targetUnitId];
  if (!unit) return;
  const effect = context.effect;
  resolveCleanseEffect(state, {
    ...context,
    effect: { ...effect, category: effect.category || "positive" }
  });
  const keptModifiers = [];
  let removedModifiers = 0;
  for (const modifier of unit.modifiers) {
    const matches = effect.stat ? modifier.stat === effect.stat : true;
    if (matches && removedModifiers < (effect.count == null ? Infinity : effect.count)) {
      removedModifiers += 1;
      continue;
    }
    keptModifiers.push(modifier);
  }
  if (removedModifiers) {
    queueEvent(state, {
      type: "modifiersDispelled",
      sourceUnitId: context.sourceUnitId,
      targetUnitId: unit.id,
      count: removedModifiers
    });
    unit.modifiers = keptModifiers;
  }
  if (effect.removesShields) {
    const shieldCount = unit.shields.length;
    if (shieldCount) {
      unit.shields = [];
      queueEvent(state, {
        type: "shieldsDispelled",
        sourceUnitId: context.sourceUnitId,
        targetUnitId: unit.id,
        count: shieldCount
      });
    }
  }
}

function resolveDelayedEffect(state, context) {
  const effect = context.effect;
  queueEvent(state, {
    type: "delayedEffectScheduled",
    sourceUnitId: context.sourceUnitId,
    targetUnitId: context.targetUnitId,
    abilityId: context.abilityId,
    remaining: effect.delayActivations == null ? 1 : effect.delayActivations,
    effects: effect.effects || [],
    chainDepth: context.chainDepth + 1
  });
}

function resolveConditionalEffect(state, context) {
  const effect = context.effect;
  const branch = evaluateConditions(context, effect.conditions) ? effect.ifTrue : effect.ifFalse;
  resolveEffects(state, {
    sourceUnitId: context.sourceUnitId,
    targetUnitIds: context.targetUnitId ? [context.targetUnitId] : [],
    targetTile: context.targetTile,
    affectedTiles: context.affectedTiles,
    abilityId: context.abilityId,
    statusId: context.statusId,
    effects: branch || [],
    chainDepth: context.chainDepth + 1
  });
}

/**
 * Gives an activation resource back, capped per activation so no effect can
 * chain forever. Entirely generic: the effect data names the resource.
 */
function resolveRefreshActivationResource(state, context) {
  const effect = context.effect;
  const activation = state.activation;
  if (!activation || activation.unitId !== context.sourceUnitId) return;
  const resource = effect.resource === "action" ? "acted" : "moved";
  const limit = effect.maxPerActivation == null ? 1 : effect.maxPerActivation;
  activation.refunds = activation.refunds || {};
  const used = activation.refunds[resource] || 0;
  if (used >= limit) {
    return;
  }
  if (!activation[resource]) return;
  activation.refunds[resource] = used + 1;
  queueEvent(state, {
    type: "activationResourceRefreshed",
    sourceUnitId: context.sourceUnitId,
    unitId: context.sourceUnitId,
    resource,
    remainingRefunds: limit - (used + 1)
  });
}

function resolveRepeatEffect(state, context) {
  const effect = context.effect;
  const requested = effect.count == null ? 1 : effect.count;
  const count = Math.min(requested, GAME_CONFIG.limits.maxRepeatedEffects);
  if (requested > count) {
    state.errors.push("Repeat count clamped to the configured maximum.");
  }
  for (let index = 0; index < count; index += 1) {
    resolveEffects(state, {
      sourceUnitId: context.sourceUnitId,
      targetUnitIds: context.targetUnitId ? [context.targetUnitId] : [],
      targetTile: context.targetTile,
      affectedTiles: context.affectedTiles,
      abilityId: context.abilityId,
      statusId: context.statusId,
      effects: effect.effects || [],
      chainDepth: context.chainDepth + 1,
      repetition: index
    });
  }
}

/**
 * Resolves an effect list along a chain of targets.
 *
 * The chain is planned once, from live positions, and then each node's effects
 * go through `resolveEffects` exactly as they would if the node had been
 * targeted directly. That is the entire trick: there is no chain-damage
 * routine, so an authored chain of statuses, heals or shields needs no new
 * targeting architecture — only a different effect list inside this one.
 *
 * Ordering is the plan's ordering, and the plan is deterministic, so a replay
 * arcs through the same units in the same sequence.
 */
function resolvePropagateEffect(state, context) {
  const effect = context.effect;
  const sourceUnitId = context.sourceUnitId;
  const plan = planUnitPropagation(state, sourceUnitId, context.abilityId, context.targetUnitId);

  const chain = createPropagationContext(plan, { abilityId: context.abilityId || null });
  const previous = state.propagation;
  state.propagation = chain;

  queueEvent(state, {
    type: "propagationPlanned",
    sourceUnitId,
    abilityId: context.abilityId || null,
    initialTargetId: plan.initialTargetId,
    order: plan.order.slice(),
    hops: plan.hops,
    maxHops: plan.maxHops,
    terminationReason: plan.terminationReason,
    legal: plan.legal
  });

  for (const node of plan.nodes) {
    const unit = state.units[node.id];
    if (!unit) continue;
    // The world changes as the chain resolves — an earlier arc may have killed
    // this node, or a reaction may have moved it. A node that stopped being a
    // legal target is skipped rather than forced through.
    if (!unit.alive && !effect.allowsDefeated) {
      chain.resolved.push(node.id);
      continue;
    }

    advancePropagation(chain, node);
    const before = unit.currentHp;

    resolveEffects(state, {
      sourceUnitId,
      targetUnitIds: [node.id],
      targetTile: { x: unit.x, y: unit.y },
      affectedTiles: context.affectedTiles,
      abilityId: context.abilityId,
      statusId: context.statusId,
      effects: effect.effects || [],
      chainDepth: context.chainDepth + 1
    });
    processAllEvents(state);

    queueEvent(state, {
      type: "propagationHop",
      sourceUnitId,
      targetUnitId: node.id,
      abilityId: context.abilityId || null,
      hop: node.hop,
      fromUnitId: node.fromId,
      distance: node.distance,
      radius: node.radius
    });
    processAllEvents(state);

    // Counted, never re-triggered. A kill can make the *next* arc hit harder
    // because content asked it to; it cannot cause another arc, which is what
    // would turn a cascade into a loop.
    const after = state.units[node.id];
    if (before > 0 && (!after || !after.alive || after.currentHp <= 0)) chain.kills += 1;
  }

  queueEvent(state, {
    type: "propagationCompleted",
    sourceUnitId,
    abilityId: context.abilityId || null,
    resolved: chain.resolved.slice(),
    hops: chain.hop,
    kills: chain.kills,
    terminationReason: plan.terminationReason
  });
  state.propagation = previous || null;
}

/**
 * Puts an authored fixture on a tile.
 *
 * A tile effect, so it resolves against the tile the ability targeted rather
 * than a unit. The definition supplies everything about what the thing is; the
 * effect supplies only where it goes and who it belongs to.
 */
function resolvePlaceFixtureEffect(state, context) {
  const effect = context.effect;
  const tile = context.targetTile;
  if (!tile) {
    state.errors.push("placeFixture needs a target tile.");
    return;
  }
  const definition = fixtureDefinition(effect.definitionId);
  if (!definition) {
    state.errors.push("placeFixture references unknown fixture: " + effect.definitionId);
    return;
  }
  const owner = state.units[context.sourceUnitId];
  const existing = fixturesAtTile(state.fixtures, tile.x, tile.y).filter((entry) =>
    fixtureIsActive(entry)
  );
  // One of a kind per tile unless the definition says stacking is fine. Two
  // mines on one tile is almost always a misclick, and letting it through
  // makes the board lie about how dangerous a tile is.
  if (!definition.stacks && existing.some((entry) => entry.definitionId === effect.definitionId)) {
    state.errors.push("A " + (definition.name || effect.definitionId) + " is already on that tile.");
    return;
  }

  const fixture = createFixture(state.fixtures, {
    definitionId: effect.definitionId,
    x: tile.x,
    y: tile.y,
    ownerTeamId: owner ? owner.teamId : null,
    ownerUnitId: context.sourceUnitId || null,
    createdBy: context.sourceUnitId || null,
    state: definition.initialState || "armed",
    visibility: definition.visibility,
    revealed: definition.visibility === "everyone",
    blocksMovement: definition.blocksMovement === true,
    charges: definition.charges,
    consumedOnTrigger: definition.consumedOnTrigger !== false,
    triggerTiles: definition.triggerTiles || [],
    createdAt: state.currentTime
  });

  queueEvent(state, {
    type: "fixturePlaced",
    fixtureId: fixture.id,
    definitionId: fixture.definitionId,
    sourceUnitId: context.sourceUnitId || null,
    ownerTeamId: fixture.ownerTeamId,
    tile: { x: tile.x, y: tile.y }
  });
}

/** Moves a fixture between authored states. Used for arming and disarming. */
function resolveSetFixtureStateEffect(state, context) {
  const effect = context.effect;
  const fixtureId = effect.fixtureId || (context.targetFixtureId || null);
  const fixture = findFixture(state.fixtures, fixtureId);
  if (!fixture) return;
  const result = setFixtureState(state.fixtures, fixture.id, effect.state);
  if (!result.ok || !result.changed) return;
  queueEvent(state, {
    type: "fixtureStateChanged",
    fixtureId: fixture.id,
    definitionId: fixture.definitionId,
    ownerTeamId: fixture.ownerTeamId,
    from: result.from,
    to: effect.state,
    byUnitId: context.sourceUnitId || null
  });
}

const EFFECT_HANDLERS = {
  damage: resolveDamageEffect,
  heal: resolveHealEffect,
  applyStatus: resolveApplyStatusEffect,
  removeStatus: resolveRemoveStatusEffect,
  modifyTimeline: resolveModifyTimelineEffect,
  shield: resolveShieldEffect,
  modifyStat: resolveModifyStatEffect,
  moveUnit: resolveMoveUnitEffect,
  displace: resolveDisplaceEffect,
  push: resolvePushEffect,
  pull: resolvePullEffect,
  teleport: resolveTeleportEffect,
  swapPositions: resolveSwapPositionsEffect,
  restoreResource: resolveRestoreResourceEffect,
  spendResource: resolveSpendResourceEffect,
  transferResource: resolveTransferResourceEffect,
  createTerrain: resolveCreateTerrainEffect,
  removeTerrain: resolveRemoveTerrainEffect,
  spawnUnit: resolveSpawnUnitEffect,
  despawnUnit: resolveDespawnUnitEffect,
  revive: resolveReviveEffect,
  transformUnit: resolveTransformUnitEffect,
  copyStatus: resolveCopyStatusEffect,
  transferStatus: resolveTransferStatusEffect,
  cleanse: resolveCleanseEffect,
  dispel: resolveDispelEffect,
  delayedEffect: resolveDelayedEffect,
  conditionalEffect: resolveConditionalEffect,
  repeatEffect: resolveRepeatEffect,
  propagate: resolvePropagateEffect,
  placeFixture: resolvePlaceFixtureEffect,
  setFixtureState: resolveSetFixtureStateEffect,
  refreshActivationResource: resolveRefreshActivationResource
};

function resolveEffects(state, options) {
  const { sourceUnitId, targetUnitIds, effects } = options;
  const chainDepth = options.chainDepth == null ? 0 : options.chainDepth;
  if (chainDepth > GAME_CONFIG.limits.maxEffectChainDepth) {
    state.errors.push("Effect chain depth limit reached.");
    return;
  }
  effects.forEach((effect, effectIndex) => {
    const handler = EFFECT_HANDLERS[effect.type];
    if (!handler) {
      state.errors.push("No handler for effect type: " + effect.type);
      return;
    }
    const meta = effectMetadata(effect.type);
    const runOne = (targetUnitId) => {
      const context = createEffectContext(state, {
        sourceUnitId,
        targetUnitId,
        abilityId: options.abilityId || null,
        statusId: options.statusId || null,
        targetTile: options.targetTile || null,
        affectedTiles: options.affectedTiles || [],
        effect,
        effectIndex,
        chainDepth
      });
      if (effect.conditions && !evaluateConditions(context, effect.conditions)) return;
      handler(state, context);
    };

    const defer = (targetUnitId) => {
      queueEvent(state, {
        type: "deferredEffect",
        sourceUnitId,
        targetUnitId: targetUnitId || null,
        abilityId: options.abilityId || null,
        statusId: options.statusId || null,
        targetTile: options.targetTile || null,
        effect,
        chainDepth: chainDepth + 1
      });
    };

    if (meta.applies === "tile") {
      if (effect.resolveAfterEffects) defer(null);
      else runOne(null);
      return;
    }
    for (const rawTargetId of targetUnitIds) {
      const targetUnitId = effect.applyTo === "source" ? sourceUnitId : rawTargetId;
      const target = state.units[targetUnitId];
      if (!target) continue;
      const allowsDefeated = options.allowsDefeated || meta.allowsDefeated || effect.allowsDefeated;
      if (!target.alive && !allowsDefeated) continue;
      if (effect.resolveAfterEffects) defer(targetUnitId);
      else runOne(targetUnitId);
    }
    if (!targetUnitIds.length && effect.applyTo === "source") runOne(sourceUnitId);
  });
}


/* ---------------------------------------------------------------
 * CONDITIONS (data driven, registry based)
 * -------------------------------------------------------------*/

const CONDITION_HANDLERS = {
  targetHpBelowPercent: (context, condition) => hpPercent(context.state, context.targetUnitId) < condition.value,
  targetHpAbovePercent: (context, condition) => hpPercent(context.state, context.targetUnitId) > condition.value,
  sourceHpBelowPercent: (context, condition) => hpPercent(context.state, context.sourceUnitId) < condition.value,
  sourceHpAbovePercent: (context, condition) => hpPercent(context.state, context.sourceUnitId) > condition.value,
  sourceHasStatus: (context, condition) => unitHasStatus(context.state, context.sourceUnitId, condition.statusId),
  targetHasStatus: (context, condition) => unitHasStatus(context.state, context.targetUnitId, condition.statusId),
  sourceMissingStatus: (context, condition) => !unitHasStatus(context.state, context.sourceUnitId, condition.statusId),
  targetMissingStatus: (context, condition) => !unitHasStatus(context.state, context.targetUnitId, condition.statusId),
  // A unit reduced to zero counts as defeated even before its defeat event
  // has been processed, so follow-up effects can react in the same resolution.
  targetIsDefeated: (context) => {
    const unit = context.state.units[context.targetUnitId];
    return !!unit && (!unit.alive || unit.currentHp <= 0);
  },
  targetIsAlive: (context) => {
    const unit = context.state.units[context.targetUnitId];
    return !!unit && unit.alive && unit.currentHp > 0;
  },
  targetIsAlly: (context) => sameTeam(context.state, context.sourceUnitId, context.targetUnitId),
  targetIsEnemy: (context) =>
    context.targetUnitId != null && !sameTeam(context.state, context.sourceUnitId, context.targetUnitId),
  tileIsEmpty: (context) => {
    const tile = context.targetTile;
    return !!tile && isTileFree(context.state, tile.x, tile.y, context.sourceUnitId);
  },
  tileHasTerrainTag: (context, condition) => {
    const tile = context.targetTile;
    if (!tile) return false;
    const terrainId = terrainIdAt(context.state, tile.x, tile.y);
    const terrain = terrainId ? CONTENT.terrains[terrainId] : null;
    return !!terrain && (terrain.tags || []).includes(condition.value);
  },
  distanceAtMost: (context, condition) => effectDistance(context) <= condition.value,
  distanceAtLeast: (context, condition) => effectDistance(context) >= condition.value,
  /**
   * A combat resource balance, on whoever is acting or whoever is being acted
   * on. Reads through the same scope resolution as an ability cost, so an
   * author names a resource and never a scope.
   *
   * This is what an ability needs to say "only worth using while you still
   * have charge", and what a steal needs to say "do not offer this against
   * somebody carrying nothing".
   */
  resourceBalance: (context, condition) =>
    resourceQueryHolds(
      resourceReadingFor(
        context.state,
        condition.of === "target" ? context.targetUnitId : context.sourceUnitId,
        condition.resourceId
      ),
      condition
    ),
  chance: (context, condition) => rollChance(context.state, condition.value)
};


function hpPercent(state, unitId) {
  const unit = state.units[unitId];
  if (!unit) return 0;
  return (unit.currentHp / calculateUnitStats(state, unitId).maxHp) * 100;
}

function unitHasStatus(state, unitId, statusId) {
  const unit = state.units[unitId];
  return !!unit && unit.statuses.some((applied) => applied.statusId === statusId);
}

function sameTeam(state, a, b) {
  const left = state.units[a];
  const right = state.units[b];
  return !!left && !!right && left.teamId === right.teamId;
}

function effectDistance(context) {
  const source = context.state.units[context.sourceUnitId];
  const tile = context.targetTile ||
    (context.targetUnitId ? context.state.units[context.targetUnitId] : null);
  if (!source || !tile) return 0;
  return Math.abs(source.x - tile.x) + Math.abs(source.y - tile.y);
}

/** Probability of a condition set without consuming RNG (preview use). */
function conditionProbability(conditions) {
  const list = normalizeConditions(conditions);
  let probability = 1;
  for (const entry of list.entries) {
    if (entry.type === "chance") probability *= entry.value;
  }
  return list.mode === "any" && list.entries.length ? 1 : probability;
}

function normalizeConditions(conditions) {
  if (!conditions) return { mode: "all", entries: [] };
  if (Array.isArray(conditions)) return { mode: "all", entries: conditions };
  return { mode: conditions.mode || "all", entries: conditions.entries || [] };
}

/** Preview-safe evaluation: never rolls, reports probability instead. */
function evaluateConditionsPure(context, conditions) {
  const list = normalizeConditions(conditions);
  if (!list.entries.length) return { deterministic: true, value: true, probability: 1 };
  let probability = 1;
  let deterministic = true;
  const results = [];
  for (const entry of list.entries) {
    if (entry.type === "chance") {
      deterministic = false;
      probability *= entry.value;
      results.push(true);
      continue;
    }
    const handler = CONDITION_HANDLERS[entry.type];
    results.push(handler ? handler(context, entry) === true : false);
  }
  const value = list.mode === "any" ? results.some(Boolean) : results.every(Boolean);
  return { deterministic, value, probability };
}

function evaluateConditions(context, conditions) {
  const list = normalizeConditions(conditions);
  if (!list.entries.length) return true;
  const results = list.entries.map((entry) => {
    const handler = CONDITION_HANDLERS[entry.type];
    if (!handler) {
      context.state.errors.push("No handler for condition type: " + entry.type);
      return false;
    }
    return handler(context, entry) === true;
  });
  return list.mode === "any" ? results.some(Boolean) : results.every(Boolean);
}

/* ---------------------------------------------------------------
 * TARGET FILTERS (data driven, registry based)
 * -------------------------------------------------------------*/

const TARGET_FILTER_HANDLERS = {
  hasStatus: (state, context, filter) => unitHasStatus(state, context.unit.id, filter.statusId),
  missingStatus: (state, context, filter) => !unitHasStatus(state, context.unit.id, filter.statusId),
  hpBelowPercent: (state, context, filter) => hpPercent(state, context.unit.id) < filter.value,
  hpAbovePercent: (state, context, filter) => hpPercent(state, context.unit.id) > filter.value,
  unitTag: (state, context, filter) =>
    (CONTENT.units[context.unit.definitionId].tags || []).includes(filter.value),
  classTag: (state, context, filter) =>
    CONTENT.units[context.unit.definitionId].classId === filter.value,
  terrainTag: (state, context, filter) => {
    const terrainId = terrainIdAt(state, context.unit.x, context.unit.y);
    const terrain = terrainId ? CONTENT.terrains[terrainId] : null;
    return !!terrain && (terrain.tags || []).includes(filter.value);
  },
  summoned: (state, context) => !!context.unit.summonedBy,
  notSummoned: (state, context) => !context.unit.summonedBy,
  sourceOnly: (state, context) => context.unit.id === context.sourceUnitId,
  excludeSource: (state, context) => context.unit.id !== context.sourceUnitId
};

function passesTargetFilters(state, filters, context) {
  for (const filter of filters || []) {
    const handler = TARGET_FILTER_HANDLERS[filter.type];
    if (!handler) {
      state.errors.push("No handler for target filter: " + filter.type);
      return false;
    }
    if (!handler(state, context, filter)) return false;
  }
  return true;
}

/* ---------------------------------------------------------------
 * EFFECT CONTEXT
 * -------------------------------------------------------------*/

let effectEventCounter = 0;

function createEffectContext(state, options) {
  effectEventCounter += 1;
  const source = state.units[options.sourceUnitId] || null;
  const target = options.targetUnitId ? state.units[options.targetUnitId] : null;
  return {
    state,
    sourceUnitId: options.sourceUnitId,
    targetUnitId: options.targetUnitId || null,
    abilityId: options.abilityId || null,
    statusId: options.statusId || null,
    sourceTile: source ? { x: source.x, y: source.y } : null,
    targetTile:
      options.targetTile || (target ? { x: target.x, y: target.y } : null),
    affectedTiles: options.affectedTiles || [],
    effect: options.effect,
    effectIndex: options.effectIndex == null ? 0 : options.effectIndex,
    chainDepth: options.chainDepth == null ? 0 : options.chainDepth,
    eventId: "fx-" + effectEventCounter
  };
}

/** Which unit an effect entry applies to: the ability target or its source. */
const EFFECT_METADATA = {
  damage: { applies: "unit" },
  heal: { applies: "unit" },
  applyStatus: { applies: "unit" },
  removeStatus: { applies: "unit" },
  modifyTimeline: { applies: "unit" },
  shield: { applies: "unit" },
  modifyStat: { applies: "unit" },
  moveUnit: { applies: "unit" },
  displace: { applies: "unit" },
  push: { applies: "unit" },
  pull: { applies: "unit" },
  teleport: { applies: "unit", needsTile: true },
  swapPositions: { applies: "unit" },
  restoreResource: { applies: "unit" },
  spendResource: { applies: "unit" },
  transferResource: { applies: "unit" },
  createTerrain: { applies: "tile" },
  removeTerrain: { applies: "tile" },
  spawnUnit: { applies: "tile" },
  despawnUnit: { applies: "unit" },
  revive: { applies: "unit", allowsDefeated: true },
  transformUnit: { applies: "unit" },
  copyStatus: { applies: "unit" },
  transferStatus: { applies: "unit" },
  cleanse: { applies: "unit" },
  dispel: { applies: "unit" },
  delayedEffect: { applies: "unit" },
  conditionalEffect: { applies: "unit" },
  repeatEffect: { applies: "unit" },
  propagate: { applies: "unit" },
  // A fixture goes on a tile, not on whoever happens to be standing there.
  placeFixture: { applies: "tile", needsTile: true },
  setFixtureState: { applies: "tile" },
  refreshActivationResource: { applies: "unit", allowsDefeated: true }
};

function effectMetadata(effectType) {
  return EFFECT_METADATA[effectType] || { applies: "unit" };
}

/** Shields absorb damage before HP, oldest first. */
function consumeShields(state, unit, amount, event) {
  let remaining = amount;
  let absorbed = 0;
  for (const shield of unit.shields) {
    if (remaining <= 0) break;
    const used = Math.min(shield.remaining, remaining);
    shield.remaining -= used;
    remaining -= used;
    absorbed += used;
    if (used > 0) {
      queueEvent(state, {
        type: "shieldConsumed",
        targetUnitId: unit.id,
        sourceUnitId: event ? event.sourceUnitId : null,
        amount: used,
        shieldId: shield.id
      });
    }
  }
  unit.shields = unit.shields.filter((shield) => shield.remaining > 0);
  return absorbed;
}

/** Ticks shields, stat modifiers, transformations and summon lifetimes. */
function tickUnitRuntimeDurations(state, unitId, durationType) {
  const unit = state.units[unitId];
  if (!unit) return;
  const keptShields = [];
  for (const shield of unit.shields) {
    if (shield.duration && shield.duration.type === durationType) {
      shield.remainingDuration -= 1;
      if (shield.remainingDuration <= 0) {
        queueEvent(state, { type: "shieldExpired", targetUnitId: unitId, shieldId: shield.id });
        continue;
      }
    }
    keptShields.push(shield);
  }
  unit.shields = keptShields;

  const keptModifiers = [];
  for (const modifier of unit.modifiers) {
    if (modifier.duration && modifier.duration.type === durationType) {
      modifier.remainingDuration -= 1;
      if (modifier.remainingDuration <= 0) {
        queueEvent(state, {
          type: "statModifierExpired",
          targetUnitId: unitId,
          stat: modifier.stat
        });
        continue;
      }
    }
    keptModifiers.push(modifier);
  }
  unit.modifiers = keptModifiers;

  if (unit.remainingTransform != null && durationType === "targetActivations") {
    unit.remainingTransform -= 1;
    if (unit.remainingTransform <= 0 && unit.originalDefinitionId) {
      queueEvent(state, {
        type: "unitTransformed",
        sourceUnitId: unitId,
        targetUnitId: unitId,
        definitionId: unit.originalDefinitionId,
        duration: null,
        keepHpRatio: true
      });
      unit.remainingTransform = null;
    }
  }

  if (unit.remainingLifetime != null && durationType === "targetActivations") {
    unit.remainingLifetime -= 1;
    if (unit.remainingLifetime <= 0) {
      queueEvent(state, { type: "unitDespawned", unitId });
    }
  }
}

/** Global per-activation ticking for terrain overrides and delayed effects. */
function tickGlobalRuntimeDurations(state, unitId) {
  for (const key of Object.keys(state.terrainOverrides)) {
    const override = state.terrainOverrides[key];
    if (!override.duration) continue;
    override.remainingDuration -= 1;
    if (override.remainingDuration <= 0) {
      const [x, y] = key.split(",").map(Number);
      queueEvent(state, { type: "terrainRemoved", sourceUnitId: null, tile: { x, y } });
    }
  }

  const pending = [];
  for (const delayed of state.delayedEffects) {
    if (delayed.targetUnitId !== unitId) {
      pending.push(delayed);
      continue;
    }
    delayed.remaining -= 1;
    if (delayed.remaining > 0) {
      pending.push(delayed);
      continue;
    }
    resolveEffects(state, {
      sourceUnitId: delayed.sourceUnitId,
      targetUnitIds: [delayed.targetUnitId],
      abilityId: delayed.abilityId,
      effects: delayed.effects,
      chainDepth: delayed.chainDepth
    });
  }
  state.delayedEffects = pending;
}

/* ---------------------------------------------------------------
 * STATUS HELPERS
 * -------------------------------------------------------------*/

function hasBlockingStatus(state, unitId) {
  return state.units[unitId].statuses.some((applied) => {
    const def = CONTENT.statuses[applied.statusId];
    return def && def.preventsAction;
  });
}

/* ---------------------------------------------------------------
 * STATUS TRIGGERS
 *
 * A status that does something on its own, at a named moment.
 *
 * The representation was always generic — a list of `{ event, effects }` on
 * the status — but only one moment ever called it, so every passive that was
 * not "burn at the start of your turn" had to be built as something else.
 * These are the moments that now call it. They are deliberately few: each one
 * has to answer *who the effect lands on* unambiguously, and an event that
 * cannot is worse than an event that is missing.
 * -------------------------------------------------------------*/

/**
 * Runs whatever the holder's statuses have to say about this moment.
 *
 * Three safety properties, all of which cost something real if dropped:
 *
 *   The list is copied before iteration, because a trigger may cleanse the
 *   status that is firing — and removing an entry from the array being walked
 *   would silently skip the next one.
 *
 *   A dead holder triggers nothing. `unitDefeated` clears statuses anyway, but
 *   a holder can die *inside* an earlier trigger in the same pass, and a
 *   corpse retaliating is exactly the impossible effect this has to refuse.
 *
 *   Depth is bounded by the causal chain the events already carry, not by a
 *   private counter. Retaliation that provokes retaliation is a legitimate
 *   authored exchange, so it is allowed to happen — and then to stop, at the
 *   same ceiling every other cascade in the engine stops at. Nothing here
 *   needs to know it is inside itself.
 */
function runStatusTriggers(state, unitId, eventName, context) {
  const unit = state.units[unitId];
  if (!unit || !unit.alive) return;
  if (state.causality && chainExhausted(state.causality.current)) return;
  const counterpartId = (context && context.counterpartUnitId) || null;
  for (const applied of unit.statuses.slice()) {
    const def = CONTENT.statuses[applied.statusId];
    if (!def) continue;
    // Still carried? An earlier trigger in this same pass may have cleansed it.
    if (!unit.statuses.some((entry) => entry.statusId === applied.statusId)) continue;
    if (!unit.alive) return;
    for (const trigger of def.triggers) {
      if (trigger.event !== eventName) continue;
      const landsOn = trigger.target === "counterpart" ? counterpartId : unitId;
      // A counterpart trigger with nobody on the other side does nothing. That
      // is a content mistake rather than an engine one, so it stays quiet.
      if (!landsOn) continue;
      const recipient = state.units[landsOn];
      if (!recipient || !recipient.alive) continue;
      queueEvent(state, {
        type: "statusTriggered",
        targetUnitId: unitId,
        counterpartUnitId: counterpartId,
        statusId: applied.statusId,
        triggerEvent: eventName
      });
      resolveEffects(state, {
        sourceUnitId: applied.sourceUnitId || unitId,
        targetUnitIds: [landsOn],
        effects: trigger.effects || [],
        statusId: applied.statusId
      });
    }
  }
}

function tickStatusDurations(state, unitId, durationType) {
  const unit = state.units[unitId];
  const expired = [];
  unit.statuses = unit.statuses.filter((applied) => {
    const def = CONTENT.statuses[applied.statusId];
    if (!def || def.duration.type !== durationType) return true;
    applied.remaining -= 1;
    if (applied.remaining <= 0) {
      expired.push(applied.statusId);
      return false;
    }
    return true;
  });
  for (const statusId of expired) {
    logLine(
      state,
      "statusExpired",
      CONTENT.statuses[statusId].name + " expired on " + unitLabel(state, unitId)
    );
  }
}

/* ---------------------------------------------------------------
 * EVENT QUEUE
 * -------------------------------------------------------------*/

/**
 * Queues an authoritative event, attributed to whatever is currently running.
 *
 * The attribution is ambient rather than passed explicitly: an effect deep in
 * a handler should not have to thread a cause through six call frames to have
 * its consequences recorded correctly, and one that forgot would silently
 * detach a whole subtree of the chain.
 */
function queueEvent(state, event) {
  if (state.causality) stampCause(state.causality, event);
  state.resolutionQueue.push(event);
  return event;
}

/** Opens a new causal chain. Called wherever something genuinely originates:
 *  a player command, an AI activation, a mission action. */
function openCausalChain(state, origin) {
  if (!state.causality) return null;
  state.causality.current = beginChain(state.causality, origin);
  return state.causality.current;
}

/**
 * Keeps a bounded record of what caused what.
 *
 * Only enough to answer "why did that fire?" in the debug view and in a test.
 * Bounded on purpose: a full event log for a long battle is a memory leak
 * wearing a diagnostics costume.
 */
const CAUSAL_TRACE_LIMIT = 120;

function recordCausalEvent(state, event) {
  if (!state.causality) return;
  if (!state.causalTrace) state.causalTrace = [];
  state.causalTrace.push({
    seq: event.__seq || null,
    type: event.type,
    unitId: event.unitId || event.targetUnitId || null,
    sourceUnitId: event.sourceUnitId || null,
    cause: event.cause || null
  });
  if (state.causalTrace.length > CAUSAL_TRACE_LIMIT) state.causalTrace.shift();
}

/** Generic hook reserved for Phase 4 reactions. */
function emitBattleTrigger(state, triggerName, payload) {
  if (!state.triggerListeners) return;
  for (const listener of state.triggerListeners) listener(state, triggerName, payload);
}

/* ---------------------------------------------------------------
 * DECLARED ACTIONS
 *
 * A command used to become its consequence immediately: `useAbility` queued
 * `abilityUsed`, and by the time anything could respond, the shot had been
 * fired. There was no moment at which an action was *chosen but not yet true*,
 * and without that moment a defender can only ever clean up afterwards.
 *
 * `actionDeclared` is that moment. It is an ordinary event with an ordinary
 * handler, which is the whole trick: the veto contract the event queue does
 * not have is not needed, because the declaration itself is the veto point.
 * The handler asks the intervention record what the verdict was and emits the
 * real action, a different real action, or nothing at all.
 *
 * WHAT THIS BUYS
 *
 *   - `processNextEvent` is untouched. No handler is ever skipped, no event is
 *     ever silently dropped, and the continuation invariant is unaffected:
 *     `actionDeclared` always resolves, it just sometimes resolves into
 *     nothing.
 *   - A cancelled action and a resolved one have the same shape in a causal
 *     trace. One has a shorter tail.
 *   - Content that never mentions interventions behaves byte-identically,
 *     because the default verdict is "continue".
 *
 * COST-COMMIT SEMANTICS — the rule, stated once
 *
 *   A declared action is paid for whether or not it resolves.
 *
 * The resource cost is queued *ahead* of the declaration, so it has already
 * been spent by the time anyone can object. The activation is marked spent by
 * the declaration, not by the outcome. Recovery is charged either way. Being
 * stopped is a thing that happened to you, not a refund — if it were a refund,
 * intercepting would cost the defender a Command Point to accomplish nothing
 * except making the attacker try again, and no defensive ability should be a
 * tempo loss for the person using it.
 * -------------------------------------------------------------*/

/**
 * Opens the window in which an action can still be stopped.
 *
 * Queued first so the event carries a real cause, then the declaration is
 * opened against that cause's chain and the id is stamped back onto the event.
 */
function declareAction(state, declaration) {
  const actor = state.units[declaration.unitId];
  const event = queueEvent(state, {
    type: "actionDeclared",
    kind: declaration.kind,
    unitId: declaration.unitId,
    sourceUnitId: declaration.unitId,
    abilityId: declaration.abilityId || null,
    target: declaration.target || null,
    targetUnitIds: (declaration.targetUnitIds || []).slice(),
    // The engine's own phrase for what is about to happen, carried so the
    // reaction layer and the prompt never have to reconstruct it from an id.
    actionName: declaration.actionName || null,
    tiles: declaration.tiles || [],
    path: declaration.path || null,
    from: declaration.from || null,
    stepFacings: declaration.stepFacings || [],
    facingFrom: declaration.facingFrom || null,
    facingTo: declaration.facingTo || null,
    redirectable: declaration.redirectable !== false
  });
  const record = openDeclaration(state.interventions, {
    kind: declaration.kind,
    actorUnitId: declaration.unitId,
    actorTeamId: actor ? actor.teamId : null,
    abilityId: declaration.abilityId || null,
    targetUnitIds: declaration.targetUnitIds || [],
    tile: declaration.target || null,
    path: declaration.path || null,
    redirectable: declaration.redirectable !== false,
    chainId: event.cause ? event.cause.chainId : null,
    openedAt: state.activationCount
  });
  event.declarationId = record.id;
  return record;
}

/**
 * Whether an action can be pointed at somebody else at all.
 *
 * A single-target shot can. A self-buff, an empty-tile placement and a
 * five-tile blast cannot — dragging an area effect across the map is not a
 * defensive parry, it is a second ability, and the honest answer for those is
 * that a defender must cancel or replace instead.
 */
function actionIsRedirectable(ability, targeting) {
  if (!ability) return false;
  const shape = (ability.targeting.area && ability.targeting.area.shape) || "single";
  if (shape !== "single") return false;
  if (ability.targeting.type === "self" || ability.targeting.type === "emptyTile") return false;
  return (targeting.targetUnitIds || []).length === 1;
}

/** The declared route, cut short at a tile that is actually on it. */
function truncatedRoute(path, tile) {
  if (!path || path.length < 2 || !tile) return null;
  const index = path.findIndex((step) => step.x === tile.x && step.y === tile.y);
  // Index 0 is where the mover already stands, so stopping there is a cancel
  // rather than a redirect, and the last tile is the declared destination.
  if (index < 1 || index >= path.length - 1) return null;
  return { path: path.slice(0, index + 1), to: { x: tile.x, y: tile.y }, tiles: index };
}

/**
 * What a declared action actually turns into.
 *
 * The fallback matters as much as the verdicts. A redirect whose new target is
 * not legally targetable does not silently become a shot at the wrong person
 * and does not silently evaporate: it reverts to the declared action and says
 * why, because a defensive ability that sometimes does nothing for reasons the
 * player cannot see is worse than one that fails loudly.
 */
function resolveDeclaredAction(state, event, verdict) {
  const actor = state.units[event.sourceUnitId];
  if (!actor || !actor.alive || actor.dormant) {
    // Not an intervention kind: the engine simply will not resolve an action
    // for somebody who is no longer able to take it. An intercept that killed
    // the attacker stops the attack without needing to say so.
    return { prevented: true, reason: "actorGone", byUnitId: verdict.byUnitId || null };
  }
  if (verdict.kind === "cancel" || verdict.kind === "replace") {
    return {
      prevented: true,
      reason: verdict.kind,
      byUnitId: verdict.byUnitId || null,
      reactionId: verdict.byReactionId || null
    };
  }
  if (verdict.kind !== "redirect") return { prevented: false, event };

  const revert = (why) => ({ prevented: false, event, revertedFrom: "redirect", why });

  if (event.kind === "movement") {
    const stop = truncatedRoute(event.path, verdict.tile);
    if (!stop) return revert("that tile is not on the route");
    if (!isTileFree(state, stop.to.x, stop.to.y, event.sourceUnitId)) {
      return revert("that tile is occupied");
    }
    const stepFacings = (event.stepFacings || []).slice(0, stop.tiles);
    return {
      prevented: false,
      redirected: true,
      byUnitId: verdict.byUnitId || null,
      event: {
        ...event,
        path: stop.path,
        target: stop.to,
        tiles: stop.tiles,
        stepFacings,
        facingTo: stepFacings.length ? stepFacings[stepFacings.length - 1] : event.facingFrom
      }
    };
  }

  const target = state.units[verdict.targetUnitId];
  if (!target || !target.alive) return revert("the new target is gone");
  // The full targeting check, not a distance comparison: range, line of sight,
  // filters and concealment all still apply to a shot somebody else pulled.
  const retargeted = evaluateTargeting(state, event.sourceUnitId, event.abilityId, {
    unitId: verdict.targetUnitId
  });
  if (!retargeted.valid) return revert(retargeted.errors[0] || "the shot cannot be pulled that way");

  return {
    prevented: false,
    redirected: true,
    byUnitId: verdict.byUnitId || null,
    event: {
      ...event,
      target: retargeted.tile,
      targetUnitIds: retargeted.targetUnitIds,
      tiles: retargeted.tiles,
      facingTo: facingFromTiles(actor, retargeted.tile, actor.facing)
    }
  };
}

/** A short human phrase for what was declared. Shared by the log, the reaction
 *  prompt and the debug view so all three call the same thing by one name. */
function describeDeclaredAction(state, event) {
  if (event.kind === "movement") return "the move";
  const ability = event.abilityId ? CONTENT.abilities[event.abilityId] : null;
  return ability ? ability.name : "the action";
}

const EVENT_HANDLERS = {
  unitActivated(state, event) {
    const unit = state.units[event.unitId];
    state.activationCount += 1;
    // The commanded slot is spent the moment its unit takes it. Consuming here
    // rather than at `turnEnded` means a unit destroyed mid-activation still
    // leaves the sequence in a correct state, because it has already had its
    // turn as far as the command is concerned.
    consumeSequence(state.sequencing, unit.id);
    logLine(state, "unitActivated", unitLabel(state, unit.id) + " activates", {
      unitId: unit.id,
      teamId: unit.teamId,
      activationIndex: state.activationCount
    });
    for (const abilityId of Object.keys(unit.cooldowns)) {
      if (unit.cooldowns[abilityId] > 0) unit.cooldowns[abilityId] -= 1;
    }
    runStatusTriggers(state, unit.id, "activationStart");
    queueEvent(state, { type: "activationReady", unitId: unit.id });
  },

  activationReady(state, event) {
    const unit = state.units[event.unitId];
    if (!unit.alive) {
      endActivation(state, { recovery: 0, defeated: true });
      return;
    }
    const blocked = hasBlockingStatus(state, unit.id);
    tickStatusDurations(state, unit.id, "targetActivations");
    tickUnitRuntimeDurations(state, unit.id, "targetActivations");
    tickGlobalRuntimeDurations(state, unit.id);
    if (blocked) {
      logLine(state, "activationSkipped", unitLabel(state, unit.id) + " cannot act", {
        unitId: unit.id
      });
      state.activation.acted = true;
      state.activation.ended = true;
      state.activation.actionRecovery += GAME_CONFIG.timeline.skippedActivationRecovery;
      endActivation(state, {
        recovery: GAME_CONFIG.timeline.skippedActivationRecovery
      });
    }
  },

  unitMoved(state, event) {
    const mover = state.units[event.unitId];
    if (mover) {
      for (const applied of mover.statuses.slice()) {
        const definition = CONTENT.statuses[applied.statusId];
        if (definition && definition.removedOnMovement) {
          queueEvent(state, {
            type: "statusRemoved",
            sourceUnitId: event.unitId,
            targetUnitId: event.unitId,
            statusId: applied.statusId
          });
        }
      }
    }
    const unit = state.units[event.unitId];
    // Something may be waiting partway along this path. A mover crossing a
    // mined tile has to set it off *there*, so the move stops at the first
    // contact and the rest is queued behind whatever the contact does. With no
    // fixtures placed this is a scan of an empty list and nothing changes.
    const path = event.path && event.path.length ? event.path : [event.from, event.to];
    const contact = firstFixtureContactOnPath(state, unit.id, path);
    const interrupted = contact && contact.index < path.length - 1 ? contact : null;
    const landing = interrupted ? interrupted.tile : event.to;
    const travelled = interrupted ? interrupted.index : event.tiles;

    unit.x = landing.x;
    unit.y = landing.y;
    // Out-of-turn movement never touches the activation. A reaction advance or
    // a cinematic reposition must not spend the unit's move for the turn, and
    // must not add movement recovery to a turn it is not part of.
    if (!event.scripted && state.activation && state.activation.unitId === unit.id) {
      state.activation.moved = true;
      state.activation.movementRecovery += movementRecoveryFor(travelled);
    }
    logLine(
      state,
      "unitMoved",
      unitLabel(state, unit.id) +
        " moves to " +
        tileKey(landing.x, landing.y) +
        " (" +
        travelled +
        " tiles)",
      { unitId: unit.id, tiles: travelled, from: event.from, to: { ...landing } }
    );

    const resume = interrupted
      ? {
          unitId: unit.id,
          from: { ...landing },
          to: { ...event.to },
          path: path.slice(interrupted.index),
          tiles: event.tiles - travelled,
          startFacing: event.startFacing,
          scripted: event.scripted === true
        }
      : null;
    const fired = contact ? triggerFixturesAt(state, unit.id, landing, resume) : 0;
    // Nothing actually triggered — the contact was stale — so the rest of the
    // walk is owed immediately rather than never.
    if (resume && !fired) queueEvent(state, { type: "unitMovementResumed", ...resume });
    // After the landing tile is settled, so anything a trail leaves behind is
    // left where the mover actually stopped rather than where it aimed.
    runStatusTriggers(state, unit.id, "unitMoved", null);
  },

  /**
   * The rest of a movement that stopped on something.
   *
   * Queued behind the interruption, so whatever the fixture did has already
   * resolved by the time this runs. It re-checks everything rather than
   * assuming: the mover may be dead, may have been thrown somewhere else, or
   * may be standing on a second fixture.
   */
  unitMovementResumed(state, event) {
    const unit = state.units[event.unitId];
    if (!unit || !unit.alive || unit.dormant) return;
    // Displaced by the blast, or otherwise no longer where the rest of this
    // path starts. The remainder is not owed to it.
    if (unit.x !== event.from.x || unit.y !== event.from.y) return;
    if (event.tiles <= 0) return;
    queueEvent(state, {
      type: "unitMoved",
      unitId: event.unitId,
      from: { ...event.from },
      to: { ...event.to },
      path: event.path,
      tiles: event.tiles,
      startFacing: event.startFacing,
      scripted: event.scripted === true
    });
  },

  facingChanged(state, event) {
    const unit = state.units[event.unitId];
    if (!unit || !unit.alive) return;
    const priorFacing = normalizeFacing(unit.facing);
    unit.facing = normalizeFacing(event.to);
    logLine(state, "facingChanged", unitLabel(state, unit.id) + " faces " + unit.facing, {
      unitId: unit.id,
      from: event.from || priorFacing,
      to: unit.facing,
      reason: event.reason || "manual"
    });
  },

  /**
   * The action has been chosen and paid for. This is the last moment anyone
   * can do anything about it.
   *
   * By the time this handler runs, the before-stage reactions have already had
   * their say and written a verdict onto the declaration. All that is left is
   * to emit what the verdict describes.
   */
  actionDeclared(state, event) {
    const verdict = resolveDeclaration(state.interventions, event.declarationId);
    const outcome = resolveDeclaredAction(state, event, verdict);
    const what = describeDeclaredAction(state, event);

    if (outcome.revertedFrom) {
      logLine(
        state,
        "interventionFailed",
        "The redirect on " + what + " did not hold — " + outcome.why,
        { declarationId: event.declarationId, unitId: event.sourceUnitId, reason: outcome.why }
      );
    }

    if (outcome.prevented) {
      // The activation is spent either way. See the cost-commit rule above:
      // being stopped is a thing that happened to you, not a refund.
      if (event.kind === "movement" && state.activation && state.activation.unitId === event.sourceUnitId) {
        state.activation.moved = true;
        state.activation.movementRecovery += movementRecoveryFor(0);
      }
      queueEvent(state, {
        type: "actionPrevented",
        declarationId: event.declarationId,
        kind: event.kind,
        unitId: event.sourceUnitId,
        sourceUnitId: outcome.byUnitId || null,
        abilityId: event.abilityId || null,
        actionName: event.actionName || what,
        targetUnitIds: event.targetUnitIds || [],
        reactionId: outcome.reactionId || null,
        reason: outcome.reason
      });
      return;
    }

    const resolved = outcome.event;
    if (resolved.facingTo && resolved.facingTo !== resolved.facingFrom) {
      queueEvent(state, {
        type: "facingChanged",
        unitId: resolved.sourceUnitId,
        from: resolved.facingFrom,
        to: resolved.facingTo,
        reason: resolved.kind === "movement" ? "movement" : "attack"
      });
    }

    if (outcome.redirected) {
      logLine(
        state,
        "actionRedirected",
        unitLabel(state, outcome.byUnitId || resolved.sourceUnitId) +
          " pulls " + what + " onto " +
          (resolved.kind === "movement"
            ? tileKey(resolved.target.x, resolved.target.y)
            : unitLabel(state, resolved.targetUnitIds[0])),
        {
          declarationId: event.declarationId,
          unitId: outcome.byUnitId || null,
          targetUnitIds: resolved.targetUnitIds || [],
          abilityId: resolved.abilityId || null
        }
      );
    }

    if (resolved.kind === "movement") {
      queueEvent(state, {
        type: "unitMoved",
        unitId: resolved.sourceUnitId,
        from: resolved.from,
        to: resolved.target,
        path: resolved.path.map((step) => ({ x: step.x, y: step.y })),
        tiles: resolved.tiles,
        startFacing: resolved.facingFrom,
        stepFacings: resolved.stepFacings || []
      });
      return;
    }

    queueEvent(state, {
      type: "abilityUsed",
      sourceUnitId: resolved.sourceUnitId,
      abilityId: resolved.abilityId,
      target: resolved.target,
      targetUnitIds: resolved.targetUnitIds,
      tiles: resolved.tiles
    });
  },

  /**
   * An action that was declared and then did not happen.
   *
   * Its own event rather than a log line, because everything downstream of an
   * action that never resolved is a legitimate reactive moment: the defender
   * who stopped it may want to follow up, and the attacker's allies may want
   * to answer.
   */
  actionPrevented(state, event) {
    const what = event.abilityId
      ? (CONTENT.abilities[event.abilityId] || {}).name || event.abilityId
      : "the move";
    const whose = unitLabel(state, event.unitId) + "'s " + what;
    const by = event.sourceUnitId ? unitLabel(state, event.sourceUnitId) : "the defence";
    const text =
      event.reason === "actorGone"
        ? whose + " never happens: they are no longer able to act"
        : event.reason === "replace"
        ? whose + " never lands — " + by + " got there first"
        : whose + " is stopped by " + by;
    logLine(state, "actionPrevented", text, {
      unitId: event.unitId,
      sourceUnitId: event.sourceUnitId,
      abilityId: event.abilityId,
      reactionId: event.reactionId,
      reason: event.reason,
      declarationId: event.declarationId
    });
  },

  abilityUsed(state, event) {
    const ability = CONTENT.abilities[event.abilityId];
    const actor = state.units[event.sourceUnitId];
    if (ability.timing.cooldown > 0) {
      // +1 so the decrement at the start of the next activation still leaves
      // the ability blocked for the full configured number of activations.
      state.units[event.sourceUnitId].cooldowns[event.abilityId] =
        ability.timing.cooldown + 1;
    }
    logLine(
      state,
      "abilityUsed",
      unitLabel(state, event.sourceUnitId) + " uses " + ability.name,
      {
        unitId: event.sourceUnitId,
        abilityId: event.abilityId,
        targetUnitIds: event.targetUnitIds
      }
    );
    emitBattleTrigger(state, "abilityUsed", event);
    // Any hostile action drops concealment: generic, driven by status data.
    const hostileAction =
      ability.targeting.type === "enemy" ||
      (event.targetUnitIds || []).some((targetId) =>
        isHostile(state, event.sourceUnitId, targetId)
      );
    if (actor && hostileAction) {
      for (const applied of actor.statuses.slice()) {
        const statusDefinition = CONTENT.statuses[applied.statusId];
        if (statusDefinition && statusDefinition.removedOnHostileAction) {
          queueEvent(state, {
            type: "statusRemoved",
            sourceUnitId: event.sourceUnitId,
            targetUnitId: event.sourceUnitId,
            statusId: applied.statusId
          });
        }
      }
    }
    resolveEffects(state, {
      sourceUnitId: event.sourceUnitId,
      targetUnitIds: event.targetUnitIds,
      targetTile: event.target || null,
      affectedTiles: event.tiles || [],
      effects: ability.effects,
      abilityId: event.abilityId,
      allowsDefeated: ability.targeting.allowsDefeated
    });
  },

  attackMissed(state, event) {
    logLine(
      state,
      "attackMissed",
      unitLabel(state, event.sourceUnitId) +
        " misses " +
        unitLabel(state, event.targetUnitId),
      {
        unitId: event.sourceUnitId,
        targetUnitId: event.targetUnitId,
        hitChance: event.hitChance,
        flankArc: event.flankArc || "front",
        targetFacing: event.targetFacing || null
      }
    );
  },


  shieldApplied(state, event) {
    const target = state.units[event.targetUnitId];
    if (!target || !target.alive) return;
    target.shields.push({
      id: "shield-" + state.nextRuntimeId++,
      sourceUnitId: event.sourceUnitId,
      amount: event.amount,
      remaining: event.amount,
      duration: event.duration || null,
      remainingDuration: event.duration ? event.duration.amount : null,
      tags: event.tags || []
    });
    logLine(state, "shieldApplied", unitLabel(state, target.id) + " gains a " + event.amount + " shield", {
      unitId: target.id,
      amount: event.amount
    });
  },

  shieldConsumed(state, event) {
    logLine(state, "shieldConsumed", unitLabel(state, event.targetUnitId) + " shield absorbs " + event.amount, {
      unitId: event.targetUnitId,
      amount: event.amount
    });
  },

  shieldExpired(state, event) {
    logLine(state, "shieldExpired", unitLabel(state, event.targetUnitId) + " shield fades", {
      unitId: event.targetUnitId
    });
  },

  statModifierApplied(state, event) {
    const target = state.units[event.targetUnitId];
    if (!target || !target.alive) return;
    target.modifiers.push({
      id: "mod-" + state.nextRuntimeId++,
      sourceUnitId: event.sourceUnitId,
      stat: event.stat,
      mode: event.mode,
      value: event.value,
      duration: event.duration || null,
      remainingDuration: event.duration ? event.duration.amount : null
    });
    logLine(
      state,
      "statModifierApplied",
      unitLabel(state, target.id) + " " + event.stat + " " + event.mode + " " + event.value,
      { unitId: target.id, stat: event.stat, mode: event.mode, value: event.value }
    );
  },

  statModifierExpired(state, event) {
    logLine(state, "statModifierExpired", unitLabel(state, event.targetUnitId) + " modifier expires", {
      unitId: event.targetUnitId,
      stat: event.stat
    });
  },

  modifiersDispelled(state, event) {
    logLine(state, "modifiersDispelled", unitLabel(state, event.targetUnitId) + " loses " + event.count + " modifiers", {
      unitId: event.targetUnitId,
      count: event.count
    });
  },

  shieldsDispelled(state, event) {
    logLine(state, "shieldsDispelled", unitLabel(state, event.targetUnitId) + " loses its shields", {
      unitId: event.targetUnitId,
      count: event.count
    });
  },

  unitForcedMove(state, event) {
    const unit = state.units[event.unitId];
    if (!unit) return;
    unit.x = event.to.x;
    unit.y = event.to.y;
    // A shove crosses tiles exactly the way a walk does, and anything waiting
    // on one of them cannot tell the difference. This is the whole reason
    // punching an enemy onto a mine needs no special case: both movement
    // handlers ask the same question of the same list.
    const forcedPath = event.path && event.path.length ? event.path : [event.from, event.to];
    const forcedContact = firstFixtureContactOnPath(state, unit.id, forcedPath);
    if (forcedContact) {
      unit.x = forcedContact.tile.x;
      unit.y = forcedContact.tile.y;
    }
    logLine(
      state,
      "unitForcedMove",
      unitLabel(state, unit.id) + " is moved to " + tileKey(unit.x, unit.y) +
        (event.blocked ? " and stops short" : ""),
      {
        unitId: unit.id,
        sourceUnitId: event.sourceUnitId || null,
        tiles: event.tiles,
        from: event.from,
        to: event.to,
        // What was asked for versus what happened, and what stopped it. A
        // collision consequence is authorable from this without a physics model.
        requested: event.requested == null ? event.tiles : event.requested,
        resisted: event.resisted || 0,
        blocked: event.blocked,
        blockReason: event.blockReason || null,
        blockTile: event.blockTile || null,
        blockedBy: event.blockedBy || null,
        stoppedOnFixture: !!forcedContact
      }
    );
    if (forcedContact) triggerFixturesAt(state, unit.id, forcedContact.tile);
  },

  unitTeleported(state, event) {
    const unit = state.units[event.unitId];
    if (!unit) return;
    unit.x = event.to.x;
    unit.y = event.to.y;
    logLine(state, "unitTeleported", unitLabel(state, unit.id) + " blinks to " + tileKey(unit.x, unit.y), {
      unitId: unit.id,
      from: event.from,
      to: event.to
    });
  },

  unitsSwapped(state, event) {
    const source = state.units[event.sourceUnitId];
    const target = state.units[event.targetUnitId];
    if (!source || !target) return;
    source.x = event.targetTile.x;
    source.y = event.targetTile.y;
    target.x = event.sourceTile.x;
    target.y = event.sourceTile.y;
    logLine(state, "unitsSwapped", unitLabel(state, source.id) + " swaps with " + unitLabel(state, target.id), {
      unitId: source.id,
      targetUnitId: target.id
    });
  },

  /**
   * Spending a resource an ability declared as its cost.
   *
   * Scope-aware, and it had to become so: this used to read
   * `unit.resources[id]` and nothing else, so an ability whose cost named a
   * *faction*-scoped resource — Command Points, the squad's whole coordination
   * budget — deducted nothing at all and reported nothing. It was free, and
   * silently so, which is the worst way for a cost to be wrong.
   */
  resourceSpent(state, event) {
    const unit = state.units[event.targetUnitId || event.sourceUnitId];
    if (!unit) return;
    const definition = combatResourceDefinition(event.resourceId);
    if (!definition) return;
    const owner = definition.scope === "faction" ? { teamId: unit.teamId } : { unitId: unit.id };
    if (!resourceEntry(state, definition, owner)) return;
    spendCombatResource(state, definition, owner, event.amount);
    logLine(state, "resourceSpent", unitLabel(state, unit.id) + " spends " + event.amount + " " + event.resourceId, {
      unitId: unit.id,
      resourceId: event.resourceId,
      amount: event.amount,
      scope: definition.scope,
      remaining: resourceBalance(state, definition, owner)
    });
  },

  /**
   * Putting points back into a resource.
   *
   * Scope-aware for the same reason spending is: this used to read
   * `unit.resources[id]` and nothing else, so restoring a *faction*-scoped
   * resource added nothing and said nothing. The spend side was fixed when
   * squad-funded abilities arrived; this is the other half of the same bug,
   * and it is the half that has to work before a support operator can put
   * anything back into the squad's budget.
   */
  /**
   * Points moved from one balance to another.
   *
   * Its own event rather than a spend plus a gain, because the connection is
   * the interesting part: a causal trace that shows capacity leaving one frame
   * and arriving in another is what makes support legible, and two unrelated
   * events would show the same battle as two coincidences.
   */
  resourceTransferred(state, event) {
    const from = combatResourceDefinition(event.fromResourceId);
    const to = combatResourceDefinition(event.toResourceId);
    const fromName = (from && from.name) || event.fromResourceId;
    const toName = (to && to.name) || event.toResourceId;
    const receiver =
      event.toScope === "faction"
        ? teamLabel(state, state.units[event.toUnitId].teamId)
        : unitLabel(state, event.toUnitId);
    const text = event.transfers
      ? unitLabel(state, event.fromUnitId) + " spends " + event.spent + " " + fromName +
        ": " + receiver + " gains " + event.gained + " " + toName +
        (event.limitedBy ? " (" + transferRefusalText(event.limitedBy) + ")" : "")
      : unitLabel(state, event.fromUnitId) + " transfers nothing — " +
        transferRefusalText(event.limitedBy);
    logLine(state, "resourceTransferred", text, {
      unitId: event.fromUnitId,
      targetUnitId: event.toUnitId,
      abilityId: event.abilityId,
      fromResourceId: event.fromResourceId,
      toResourceId: event.toResourceId,
      spent: event.spent,
      gained: event.gained,
      requested: event.requested,
      limitedBy: event.limitedBy
    });
  },

  resourceRestored(state, event) {
    const unit = state.units[event.targetUnitId];
    if (!unit) return;
    const definition = combatResourceDefinition(event.resourceId);
    if (!definition) return;
    const owner = definition.scope === "faction" ? { teamId: unit.teamId } : { unitId: unit.id };
    if (!resourceEntry(state, definition, owner)) return;
    const landed = gainCombatResource(state, definition, owner, event.amount);
    logLine(
      state,
      "resourceRestored",
      unitLabel(state, unit.id) + " restores " + landed + " " + (definition.name || event.resourceId),
      {
        unitId: unit.id,
        resourceId: event.resourceId,
        amount: landed,
        requested: event.amount,
        scope: definition.scope,
        remaining: resourceBalance(state, definition, owner)
      }
    );
  },

  terrainCreated(state, event) {
    state.terrainOverrides[tileKey(event.tile.x, event.tile.y)] = {
      terrainId: event.terrainId,
      sourceUnitId: event.sourceUnitId,
      duration: event.duration || null,
      remainingDuration: event.duration ? event.duration.amount : null
    };
    logLine(
      state,
      "terrainCreated",
      CONTENT.terrains[event.terrainId].name + " appears at " + tileKey(event.tile.x, event.tile.y),
      { tile: event.tile, terrainId: event.terrainId }
    );
  },

  terrainRemoved(state, event) {
    delete state.terrainOverrides[tileKey(event.tile.x, event.tile.y)];
    logLine(state, "terrainRemoved", "Terrain clears at " + tileKey(event.tile.x, event.tile.y), {
      tile: event.tile
    });
  },

  /** A unit changed team. The change is already applied — this event exists so
   *  the reaction layer, the mission stream and the renderer all observe it at
   *  a defined point in the queue. */
  unitChangedTeam(state, event) {
    void event;
  },

  /**
   * A faction's belief about a unit moved between states.
   *
   * The knowledge model already applied the change; this event puts it on the
   * authoritative queue so mission triggers and reactions can key off "they
   * have spotted us" or "we lost him" without either layer knowing the
   * perception system exists. Only real transitions reach here.
   */
  knowledgeChanged(state, event) {
    if (event.to === "unseen" || event.from === "unseen" || event.to === "acquired") {
      logLine(state, "knowledgeChanged", knowledgeLogText(state, event), {
        factionId: event.factionId,
        unitId: event.unitId,
        from: event.from,
        to: event.to,
        reason: event.reason,
        tile: event.x == null ? null : { x: event.x, y: event.y }
      });
    }
  },

  /** A unit placed by the mission script. The unit already exists — this event
   *  exists so the log, the renderer and the mission stream all see it. */
  unitDeployed(state, event) {
    logLine(state, "unitDeployed", unitLabel(state, event.unitId) + " deploys", {
      unitId: event.unitId,
      tile: event.tile,
      groupId: event.groupId || null
    });
  },

  unitSpawned(state, event) {
    const source = state.units[event.sourceUnitId];
    const teamId =
      event.team === "sourceTeam"
        ? source
          ? source.teamId
          : state.teams[0].id
        : event.team;
    const unit = createRuntimeUnit(state, {
      definitionId: event.definitionId,
      teamId,
      x: event.tile.x,
      y: event.tile.y,
      summonedBy: event.sourceUnitId,
      lifetime: event.lifetime
    });
    state.units[unit.id] = unit;
    state.unitOrder.push(unit.id);
    state.spawnCount += 1;
    const spawnStats = calculateUnitStats(state, unit.id);
    unit.currentHp = Math.max(0, Math.min(unit.currentHp, spawnStats.maxHp));
    unit.alive = unit.currentHp > 0;
    unit.nextActionTime =
      state.currentTime +
      FORMULAS.timeline.recoveryDelay(spawnStats.speed, FORMULAS.timeline.baseRecovery);
    logLine(state, "unitSpawned", unitLabel(state, unit.id) + " is summoned", {
      unitId: unit.id,
      summonedBy: event.sourceUnitId,
      tile: event.tile
    });
  },

  unitDespawned(state, event) {
    const unit = state.units[event.unitId];
    if (!unit) return;
    unit.alive = false;
    unit.currentHp = 0;
    logLine(state, "unitDespawned", unitLabel(state, unit.id) + " vanishes", { unitId: unit.id });
  },

  unitRevived(state, event) {
    const unit = state.units[event.targetUnitId];
    if (!unit || unit.alive) return;
    unit.alive = true;
    unit.currentHp = Math.min(calculateUnitStats(state, unit.id).maxHp, event.amount);
    unit.statuses = [];
    unit.shields = [];
    const stats = calculateUnitStats(state, unit.id);
    unit.nextActionTime =
      state.currentTime + FORMULAS.timeline.recoveryDelay(stats.speed, FORMULAS.timeline.baseRecovery);
    logLine(state, "unitRevived", unitLabel(state, unit.id) + " returns to the fight", {
      unitId: unit.id,
      amount: unit.currentHp
    });
  },

  unitTransformed(state, event) {
    const unit = state.units[event.targetUnitId];
    if (!unit) return;
    const previousStats = calculateUnitStats(state, unit.id);
    const ratio = previousStats.maxHp > 0 ? unit.currentHp / previousStats.maxHp : 1;
    unit.originalDefinitionId = unit.originalDefinitionId || unit.definitionId;
    unit.definitionId = event.definitionId;
    unit.remainingTransform = event.duration ? event.duration.amount : null;
    const stats = calculateUnitStats(state, unit.id);
    unit.currentHp = event.keepHpRatio
      ? Math.max(1, Math.round(stats.maxHp * ratio))
      : Math.min(unit.currentHp, stats.maxHp);
    logLine(state, "unitTransformed", unitLabel(state, unit.id) + " transforms", {
      unitId: unit.id,
      definitionId: event.definitionId
    });
  },

  deferredEffect(state, event) {
    // Resolves once the effects queued beside it have already applied, so a
    // condition can react to a defeat, a heal or a status that just landed.
    resolveEffects(state, {
      sourceUnitId: event.sourceUnitId,
      targetUnitIds: event.targetUnitId ? [event.targetUnitId] : [],
      targetTile: event.targetTile,
      abilityId: event.abilityId,
      statusId: event.statusId,
      effects: [{ ...event.effect, resolveAfterEffects: false }],
      chainDepth: event.chainDepth,
      allowsDefeated: true
    });
  },

  activationResourceRefreshed(state, event) {
    const activation = state.activation;
    if (!activation || activation.unitId !== event.unitId) return;
    activation[event.resource] = false;
    if (event.resource === "moved") activation.movementRecovery = 0;
    logLine(
      state,
      "activationResourceRefreshed",
      unitLabel(state, event.unitId) + " regains its " + event.resource + " action",
      { unitId: event.unitId, resource: event.resource }
    );
  },

  delayedEffectScheduled(state, event) {
    state.delayedEffects.push({
      id: "delayed-" + state.nextRuntimeId++,
      sourceUnitId: event.sourceUnitId,
      targetUnitId: event.targetUnitId,
      abilityId: event.abilityId,
      remaining: event.remaining,
      effects: event.effects,
      chainDepth: event.chainDepth || 1
    });
    logLine(state, "delayedEffectScheduled", "A delayed effect is set on " + unitLabel(state, event.targetUnitId), {
      unitId: event.targetUnitId,
      remaining: event.remaining
    });
  },

  damageResolved(state, event) {
    const target = state.units[event.targetUnitId];
    if (!target.alive) return;
    const absorbed = consumeShields(state, target, event.amount, event);
    const applied = event.amount - absorbed;
    event.absorbed = absorbed;
    event.appliedAmount = applied;
    const before = target.currentHp;
    target.currentHp = Math.max(0, before - applied);
    if (applied <= 0) {
      logLine(
        state,
        "damageAbsorbed",
        unitLabel(state, event.targetUnitId) + " absorbs " + absorbed + " damage",
        { unitId: event.targetUnitId, amount: absorbed }
      );
      emitBattleTrigger(state, "damageResolved", event);
      return;
    }
    logLine(
      state,
      "damageResolved",
      unitLabel(state, event.targetUnitId) +
        " takes " +
        applied +
        " damage (" +
        target.currentHp +
        " HP left)",
      {
        unitId: event.targetUnitId,
        sourceUnitId: event.sourceUnitId,
        amount: applied,
        absorbed,
        remainingHp: target.currentHp,
        flankArc: event.flankArc || "front",
        targetFacing: event.targetFacing || null,
        attackerDirection: event.attackerDirection || null,
        baseAmount: event.baseAmount == null ? event.amount : event.baseAmount,
        damageMultiplier: event.damageMultiplier == null ? 1 : event.damageMultiplier,
        // How much of this was earned by the approach rather than the weapon.
        // Attributed rather than folded into the total, so a player can tell
        // whether the runway was worth it.
        scalingBonus: event.scalingBonus || 0
      }
    );
    emitBattleTrigger(state, "damageResolved", event);
    if (target.currentHp <= 0) {
      // Who killed it and which tile it was holding. Both are what an
      // "advance into the opening" reaction needs, and neither is derivable
      // once the unit is off the board.
      queueEvent(state, {
        type: "unitDefeated",
        unitId: target.id,
        sourceUnitId: event.sourceUnitId || null,
        tile: { x: target.x, y: target.y }
      });
      // The killer's own passives, before the victim's statuses are cleared.
      if (event.sourceUnitId && event.sourceUnitId !== target.id) {
        runStatusTriggers(state, event.sourceUnitId, "killedUnit", {
          counterpartUnitId: target.id
        });
      }
      return;
    }
    // Survived it. Retaliation answers the unit that dealt the damage, which
    // is why the trigger takes a counterpart rather than always landing home.
    runStatusTriggers(state, target.id, "unitDamaged", {
      counterpartUnitId: event.sourceUnitId || null
    });
  },

  healResolved(state, event) {
    const target = state.units[event.targetUnitId];
    if (!target.alive) return;
    const stats = calculateUnitStats(state, target.id);
    const before = target.currentHp;
    target.currentHp = Math.min(stats.maxHp, before + event.amount);
    // What was actually restored, which is what a "qualifying repair"
    // condition has to read — topping up a full frame repairs nothing.
    event.appliedAmount = target.currentHp - before;
    logLine(
      state,
      "healResolved",
      unitLabel(state, target.id) +
        " recovers " +
        (target.currentHp - before) +
        " HP (" +
        target.currentHp +
        " HP)",
      {
        unitId: target.id,
        sourceUnitId: event.sourceUnitId,
        amount: target.currentHp - before,
        remainingHp: target.currentHp
      }
    );
  },

  statusApplied(state, event) {
    const target = state.units[event.targetUnitId];
    if (!target.alive) return;
    const def = CONTENT.statuses[event.statusId];
    if (!def) {
      state.errors.push("Unknown status: " + event.statusId);
      return;
    }
    const existing = target.statuses.find((s) => s.statusId === event.statusId);
    if (existing) {
      existing.remaining = def.duration.amount;
    } else {
      target.statuses.push({
        statusId: event.statusId,
        remaining: def.duration.amount,
        sourceUnitId: event.sourceUnitId || null
      });
    }
    logLine(
      state,
      "statusApplied",
      unitLabel(state, target.id) + " gains " + def.name,
      { unitId: target.id, statusId: event.statusId, sourceUnitId: event.sourceUnitId }
    );
    runStatusTriggers(state, target.id, "statusApplied", {
      counterpartUnitId: event.sourceUnitId || null
    });
  },

  statusResisted(state, event) {
    logLine(
      state,
      "statusResisted",
      unitLabel(state, event.targetUnitId) +
        " resists " +
        CONTENT.statuses[event.statusId].name
    );
  },

  statusRemoved(state, event) {
    const target = state.units[event.targetUnitId];
    const before = target.statuses.length;
    target.statuses = target.statuses.filter((s) => s.statusId !== event.statusId);
    if (target.statuses.length !== before) {
      logLine(
        state,
        "statusRemoved",
        unitLabel(state, target.id) +
          " loses " +
          CONTENT.statuses[event.statusId].name
      );
    }
  },

  statusTriggered(state, event) {
    logLine(
      state,
      "statusTriggered",
      CONTENT.statuses[event.statusId].name +
        " triggers on " +
        unitLabel(state, event.targetUnitId),
      { unitId: event.targetUnitId, statusId: event.statusId }
    );
  },

  /**
   * Moves a unit's next activation along the timeline.
   *
   * Two clamps, both load-bearing. The requested delta is capped so no single
   * effect can rewrite the whole order, and the resulting time is floored just
   * after the present, because an activation scheduled at or before `now` is
   * one that fires immediately and then again and again.
   */
  timelineModified(state, event) {
    const target = state.units[event.targetUnitId];
    if (!target.alive) return;
    const config = GAME_CONFIG.timeline;
    const cap = config.maxTurnDelayAdjustment;
    const requested = Math.max(-cap, Math.min(cap, event.delta));
    const rate = turnRateOf(state, target.id);
    const floor = state.currentTime + config.minTimeUntilNextAction;
    const before = target.nextActionTime;
    target.nextActionTime = Math.max(floor, before + requested / rate);
    const applied = target.nextActionTime - before;
    logLine(
      state,
      "timelineModified",
      unitLabel(state, target.id) +
        (applied >= 0 ? " is delayed by " : " acts sooner by ") +
        Math.abs(Math.round(applied)) +
        " time",
      {
        unitId: event.targetUnitId,
        sourceUnitId: event.sourceUnitId,
        delta: event.delta,
        requestedDelta: requested,
        appliedDelta: applied,
        clamped: requested !== event.delta || applied !== requested / rate
      }
    );
  },

  /**
   * A commanded order was issued.
   *
   * Its own event rather than a log line: the order is authoritative state,
   * and a change to it deserves the same visibility a damage number gets. It
   * carries both orders so the log and the debug view can show the difference
   * rather than the result.
   */
  activationOrderChanged(state, event) {
    const naming = (ids) => describeOrder(ids, (id) => unitLabel(state, id));
    logLine(
      state,
      "activationOrderChanged",
      unitLabel(state, event.sourceUnitId) + " sets the order: " + naming(event.order),
      {
        unitId: event.sourceUnitId,
        abilityId: event.abilityId || null,
        previousOrder: event.previousOrder,
        order: event.order,
        unitIds: event.order,
        cost: event.cost || null,
        windowStart: event.windowStart,
        windowEnd: event.windowEnd
      }
    );
  },

  unitDefeated(state, event) {
    const unit = state.units[event.unitId];
    if (!unit.alive) return;
    unit.alive = false;
    unit.currentHp = 0;
    unit.statuses = [];
    logLine(state, "unitDefeated", unitLabel(state, unit.id) + " is defeated", {
      unitId: unit.id,
      teamId: unit.teamId
    });
    emitBattleTrigger(state, "unitDefeated", event);
  },

  turnEnded(state, event) {
    const unit = state.units[event.unitId];
    // Fired here rather than from `endActivation`, so it happens exactly once
    // per activation however that activation finished — spent, ended early,
    // or skipped by a blocking status. Its effects resolve as ordinary queued
    // events immediately behind this one.
    runStatusTriggers(state, event.unitId, "activationEnd", null);
    if (unit.alive) {
      const stats = calculateUnitStats(state, unit.id);
      const delay = FORMULAS.timeline.recoveryDelay(stats.speed, event.totalRecovery);
      unit.nextActionTime = state.currentTime + delay;
      logLine(
        state,
        "turnEnded",
        unitLabel(state, unit.id) +
          " recovers for " +
          Math.round(delay) +
          " (next at " +
          Math.round(unit.nextActionTime) +
          ")",
        {
          unitId: unit.id,
          totalRecovery: event.totalRecovery,
          actionRecovery: event.actionRecovery,
          movementRecovery: event.movementRecovery,
          nextActionTime: unit.nextActionTime
        }
      );
    }
    state.activeUnitId = null;
    state.activation = null;
  },

  /** A shove that achieved nothing still happened. Logged and published so a
   *  reaction or a mission trigger can respond to the failed displacement. */
  displacementBlocked(state, event) {
    logLine(
      state,
      "displacementBlocked",
      unitLabel(state, event.unitId) + " does not budge" +
        (event.resisted ? " (absorbs " + event.resisted + ")" : "") +
        (event.blockReason ? " — " + event.blockReason : ""),
      {
        unitId: event.unitId,
        sourceUnitId: event.sourceUnitId,
        requested: event.requested,
        resisted: event.resisted,
        blockReason: event.blockReason,
        blockTile: event.blockTile,
        blockedBy: event.blockedBy
      }
    );
  },

  /** Bookkeeping and a log line. The route already happened, segment by
   *  segment; this is where it is recorded as one tactical act. */
  trajectoryCompleted(state, event) {
    logLine(
      state,
      "trajectoryCompleted",
      unitLabel(state, event.unitId) +
        (event.interrupted ? " breaks off after " : " completes a route of ") +
        event.distance +
        " tiles" +
        (event.redirects ? " with " + event.redirects + " redirect(s)" : "") +
        (event.interrupted && event.interruptReason ? " — " + event.interruptReason : ""),
      {
        unitId: event.unitId,
        abilityId: event.abilityId,
        distance: event.distance,
        redirects: event.redirects,
        interrupted: event.interrupted,
        interruptReason: event.interruptReason,
        endpoint: event.endpoint
      }
    );
  },

  fixturePlaced(state, event) {
    const fixture = findFixture(state.fixtures, event.fixtureId);
    const definition = fixtureDefinition(event.definitionId);
    logLine(
      state,
      "fixturePlaced",
      unitLabel(state, event.sourceUnitId) +
        " places " +
        ((definition && definition.name) || event.definitionId) +
        " at " + tileKey(event.tile.x, event.tile.y),
      {
        fixtureId: event.fixtureId,
        definitionId: event.definitionId,
        sourceUnitId: event.sourceUnitId,
        ownerTeamId: event.ownerTeamId,
        tile: event.tile,
        state: fixture ? fixture.state : "removed",
        // Deliberately not the visibility flag: a log line the player reads is
        // their own side's record, and it is their fixture.
        charges: fixture ? fixture.charges : null
      }
    );
  },

  fixtureTriggered(state, event) {
    const definition = fixtureDefinition(event.definitionId);
    logLine(
      state,
      "fixtureTriggered",
      ((definition && definition.name) || event.definitionId) +
        " triggers under " +
        unitLabel(state, event.unitId),
      {
        fixtureId: event.fixtureId,
        definitionId: event.definitionId,
        unitId: event.unitId,
        ownerTeamId: event.ownerTeamId,
        tile: event.tile,
        activation: event.activation
      }
    );
    resolveFixtureActivation(state, event);
    if (event.resume) queueEvent(state, { type: "unitMovementResumed", ...event.resume });
  },

  fixtureDetonated(state, event) {
    const definition = fixtureDefinition(event.definitionId);
    logLine(
      state,
      "fixtureDetonated",
      ((definition && definition.name) || event.definitionId) +
        " goes off, catching " +
        event.targetUnitIds.length +
        (event.targetUnitIds.length === 1 ? " frame" : " frames"),
      {
        fixtureId: event.fixtureId,
        definitionId: event.definitionId,
        sourceUnitId: event.sourceUnitId,
        ownerTeamId: event.ownerTeamId,
        tile: event.tile,
        targetUnitIds: event.targetUnitIds,
        activation: event.activation,
        triggeredByUnitId: event.triggeredByUnitId
      }
    );
  },

  fixtureSpent(state, event) {
    const definition = fixtureDefinition(event.definitionId);
    logLine(
      state,
      "fixtureSpent",
      ((definition && definition.name) || event.definitionId) +
        (event.consumed ? " is spent" : event.rearmed ? " resets" : " goes inert"),
      {
        fixtureId: event.fixtureId,
        definitionId: event.definitionId,
        ownerTeamId: event.ownerTeamId,
        consumed: event.consumed,
        rearmed: event.rearmed,
        remaining: event.remaining,
        state: event.state
      }
    );
    if (event.consumed) removeFixture(state.fixtures, event.fixtureId);
  },

  fixtureStateChanged(state, event) {
    const definition = fixtureDefinition(event.definitionId);
    logLine(
      state,
      "fixtureStateChanged",
      ((definition && definition.name) || event.definitionId) + " is " + event.to,
      {
        fixtureId: event.fixtureId,
        definitionId: event.definitionId,
        ownerTeamId: event.ownerTeamId,
        from: event.from,
        to: event.to,
        byUnitId: event.byUnitId || null
      }
    );
    if (event.to === "removed") removeFixture(state.fixtures, event.fixtureId);
  },

  propagationPlanned(state, event) {
    logLine(
      state,
      "propagationPlanned",
      unitLabel(state, event.sourceUnitId) +
        " arcs through " +
        event.order.length +
        (event.order.length === 1 ? " target" : " targets") +
        " — " +
        event.order.map((id) => unitLabel(state, id)).join(" → "),
      {
        sourceUnitId: event.sourceUnitId,
        abilityId: event.abilityId,
        initialTargetId: event.initialTargetId,
        order: event.order,
        hops: event.hops,
        maxHops: event.maxHops,
        terminationReason: event.terminationReason,
        legal: event.legal
      }
    );
  },

  propagationHop(state, event) {
    // Hop zero is the target the player aimed at; it is not an arc and reads
    // as noise in the log beside the damage line that follows it.
    if (!event.hop) return;
    logLine(
      state,
      "propagationHop",
      "The arc jumps " +
        event.distance +
        " to " +
        unitLabel(state, event.targetUnitId) +
        " from " +
        unitLabel(state, event.fromUnitId),
      {
        sourceUnitId: event.sourceUnitId,
        targetUnitId: event.targetUnitId,
        fromUnitId: event.fromUnitId,
        abilityId: event.abilityId,
        hop: event.hop,
        distance: event.distance,
        radius: event.radius
      }
    );
  },

  propagationCompleted(state, event) {
    logLine(
      state,
      "propagationCompleted",
      "The chain ends after " +
        event.hops +
        (event.hops === 1 ? " arc" : " arcs") +
        (event.kills ? ", leaving " + event.kills + " destroyed" : ""),
      {
        sourceUnitId: event.sourceUnitId,
        abilityId: event.abilityId,
        resolved: event.resolved,
        hops: event.hops,
        kills: event.kills,
        terminationReason: event.terminationReason
      }
    );
  },

  battleEnded(state, event) {
    logLine(
      state,
      "battleEnded",
      event.winner ? "Winner: " + event.winner : "Battle ended with no winner"
    );
  }
};

/**
 * Small serializable snapshot used by observers (presentation, replay tools).
 * Contains only mutable battle values.
 */
function snapshotForEvents(state) {
  const units = {};
  for (const id of state.unitOrder) {
    const unit = state.units[id];
    units[id] = {
      currentHp: unit.currentHp,
      alive: unit.alive,
      x: unit.x,
      y: unit.y,
      nextActionTime: unit.nextActionTime,
      statuses: unit.statuses.map((applied) => ({
        statusId: applied.statusId,
        remaining: applied.remaining
      }))
    };
  }
  return { currentTime: state.currentTime, units };
}

/**
 * Applies one event, with a reaction window on each side of the handler.
 *
 * `before` runs with the event dequeued but unapplied, which is the only
 * moment an intercept or a defensive guard can matter. `after` runs against
 * settled state, which is where counterattacks and pursuit live.
 *
 * If a window suspends waiting on a player, the event is pushed back onto the
 * front of the queue and processing stops. `__seq` and `__beforeDone` ride on
 * the event itself — plain data, so they survive a save taken mid-window and
 * the before-stage is never discovered twice for the same event.
 */
function processNextEvent(state, onEvent) {
  if (!state.resolutionQueue.length) return null;
  if (state.reactions && state.reactions.window) return null;

  const event = state.resolutionQueue.shift();
  const handler = EVENT_HANDLERS[event.type];
  if (!handler) {
    state.errors.push("No handler for event type: " + event.type);
    return event;
  }

  if (reactionsEnabled(state)) {
    if (event.__seq == null) {
      state.reactions.eventSeq += 1;
      event.__seq = "e" + state.reactions.eventSeq;
      reactionsBeginEvent(state);
    }
    if (!event.__beforeDone) {
      // Set first: a suspend must not rediscover this stage on resume.
      event.__beforeDone = true;
      if (runReactionsForEvent(state, event, "before")) {
        state.resolutionQueue.unshift(event);
        return null;
      }
    }
  }

  const before = onEvent ? snapshotForEvents(state) : null;
  // Everything the handler queues inherits this event's cause. That is what
  // makes a reaction three steps down the chain attributable to the shove
  // that started it, without any handler having to know it is in a chain.
  recordCausalEvent(state, event);
  if (state.causality) withCause(state.causality, event, () => handler(state, event));
  else handler(state, event);

  // Perception consumes the same authoritative event, immediately after it is
  // applied and before anything downstream can make a decision on stale
  // beliefs. It runs first because a mission trigger keyed on "they spotted
  // us" must see the spot, not the move that caused it.
  if (state.perception && event.type !== "knowledgeChanged") {
    ingestPerceptionEvent(state, perceptionDeps(), event);
  }

  // The mission scripting layer consumes the same authoritative event the
  // simulation just applied. No log rescanning, no polling.
  if (state.mission) {
    const deps = missionDeps(state);
    if (deps) ingestSimulationEvent(state, deps, event);
  }
  if (onEvent) onEvent(event, before, snapshotForEvents(state));

  if (reactionsEnabled(state)) {
    // Anything that can change who is linked to whom re-evaluates the links
    // before the after-stage decides what is legal.
    if (event.type === "unitDefeated" || event.type === "unitChangedTeam" || event.type === "unitDeployed") {
      refreshReactionLinks(state);
    }
    if (event.type === "unitActivated") {
      reactionsOnUnitActivated(state, reactionDeps(), event.unitId);
    }
    runReactionsForEvent(state, event, "after");
  }
  return event;
}

function processAllEvents(state, onEvent) {
  const processed = [];
  let guard = 0;
  while (state.resolutionQueue.length) {
    // A pending player reaction parks the queue; the caller resumes it.
    if (state.reactions && state.reactions.window) break;
    guard += 1;
    if (guard > GAME_CONFIG.limits.maxEventsPerCommand) {
      state.errors.push("Event queue exceeded the maximum event count.");
      state.resolutionQueue.length = 0;
      break;
    }
    const event = processNextEvent(state, onEvent);
    if (event) processed.push(event);
    else if (state.reactions && state.reactions.window) break;
    else if (!state.resolutionQueue.length) break;
  }
  return processed;
}

/** True while the battle is parked on a player reaction prompt. */
function reactionWindowPending(state) {
  return !!(state.reactions && state.reactions.window);
}

/**
 * Extra recovery charged by an explicit End Turn, based on which activation
 * resources were left unused. Fully configurable, no content ids involved.
 */
function endTurnBaseRecovery(state) {
  const activation = state.activation;
  const config = GAME_CONFIG.timeline;
  if (!activation) return config.endTurnIdleRecovery;
  if (activation.acted) return config.endTurnActedOnlyRecovery;
  if (activation.moved) return config.endTurnMovedOnlyRecovery;
  return config.endTurnIdleRecovery;
}

/** An activation closes once both resources are spent or it was ended. */
function shouldAutomaticallyEndActivation(state) {
  const activation = state.activation;
  if (!activation) return false;
  if (activation.ended || activation.waited) return true;
  return activation.moved && activation.acted;
}

/** Schedules the end of an activation exactly once. */
function finishActivationIfComplete(state) {
  const activation = state.activation;
  if (!activation || activation.pendingEnd || activation.closed) return false;
  if (!shouldAutomaticallyEndActivation(state)) return false;
  activation.pendingEnd = { recovery: activation.actionRecovery };
  return true;
}

function endActivation(state, options) {
  const activation = state.activation;
  const unitId = activation ? activation.unitId : state.activeUnitId;
  if (!unitId) return;
  if (activation) activation.closed = true;
  const movementRecovery = activation ? activation.movementRecovery : 0;
  const adjustment = activation ? activation.turnDelayAdjustment || 0 : 0;
  queueEvent(state, {
    type: "turnEnded",
    unitId,
    actionRecovery: options.recovery,
    movementRecovery,
    // Never below zero: a hasten shortens the wait, it does not schedule the
    // unit before the thing it just did.
    totalRecovery: Math.max(0, options.recovery + movementRecovery + adjustment),
    timelineAdjustment: adjustment
  });
}

/* ---------------------------------------------------------------
 * COMMANDS
 * -------------------------------------------------------------*/

function abilityRecovery(abilityId) {
  return CONTENT.abilities[abilityId].timing.recovery;
}

/** Single source of truth for movement recovery. */
function movementRecoveryFor(tiles) {
  return tiles * GAME_CONFIG.timeline.movementRecoveryPerTile;
}

/** Pure projection: when would this unit act after spending `totalRecovery`? */
function projectNextActionTime(state, unitId, totalRecovery) {
  const stats = calculateUnitStats(state, unitId);
  return state.currentTime + FORMULAS.timeline.recoveryDelay(stats.speed, totalRecovery);
}

/* ---------------------------------------------------------------
 * TRAJECTORY ACTIONS
 * -------------------------------------------------------------*/

/** Route rules an ability declares, in the shape the planner wants. Absent,
 *  the defaults describe an ordinary move: one segment, no turns. */
function trajectoryRules(ability) {
  const declared = (ability && ability.trajectory) || {};
  return {
    maxSegments: declared.maxSegments == null ? 1 : declared.maxSegments,
    maxDistance: declared.maxDistance,
    allowedRedirects: declared.allowedRedirects || null,
    movementPolicy: declared.movementPolicy || "normal",
    ignoresElevation: declared.ignoresElevation === true,
    redirectCosts: declared.redirectCosts || null,
    resourceId: declared.resourceId || null,
    /** Whether the route stops at its first contact or carries on. */
    continueAfterContact: declared.continueAfterContact !== false
  };
}

/**
 * What a route costs its mover, and whether they can pay.
 *
 * The engine multiplies and compares; the numbers and the resource are both
 * authored. Nothing here knows what is being spent.
 */
function trajectoryResourceCost(state, unitId, ability, plan) {
  const rules = trajectoryRules(ability);
  if (!rules.resourceId || !rules.redirectCosts) {
    return { ok: true, amount: 0, breakdown: [], resourceId: null };
  }
  const raw = REACTION_INDEX.resourceById[rules.resourceId];
  if (!raw) {
    return { ok: false, reason: 'This action spends "' + rules.resourceId + '", which is not a resource.' };
  }
  const definition = normalizeResourceDefinition({ id: rules.resourceId, ...raw });
  const cost = redirectCost(plan, rules.redirectCosts);
  if (!cost.total) return { ok: true, amount: 0, breakdown: [], resourceId: rules.resourceId };

  const unit = state.units[unitId];
  const owner = definition.scope === "faction" ? { teamId: unit.teamId } : { unitId };
  const check = canSpendResource(state, definition, owner, cost.total);
  return {
    ok: check.ok,
    reason: check.ok ? null : "That route needs " + cost.total + " " + (definition.name || definition.id) + " — " + check.reason + ".",
    amount: cost.total,
    breakdown: cost.breakdown,
    resourceId: rules.resourceId,
    definition,
    owner
  };
}

/**
 * Re-walks a planned segment against the battlefield as it is right now.
 *
 * A route is planned once and then resolves over several events, and those
 * events move things: a contact displaces someone into the lane, a reaction
 * advances an ally across it, the mover itself gets shoved. Replaying the
 * planned tiles blindly would drive the frame through whoever arrived after
 * the plan was made, so each segment asks the same authority the same question
 * again, later. `planUnitTrajectory` stays the only model of legality — this
 * re-runs it per step rather than reimplementing it.
 */
function revalidateSegment(state, unitId, segment, rules) {
  const deps = trajectoryDeps(state, unitId, rules);
  const unit = state.units[unitId];
  const live = {
    tiles: [],
    distance: 0,
    from: { x: unit.x, y: unit.y },
    to: { x: unit.x, y: unit.y },
    blocked: false,
    blockReason: null,
    blockTile: null,
    blockedBy: null
  };
  let cursor = live.from;
  for (const tile of segment.tiles) {
    const step = deps.canEnter(cursor, tile);
    if (!step.ok) {
      live.blocked = true;
      live.blockReason = step.reason || "the way is blocked";
      live.blockTile = { x: tile.x, y: tile.y };
      live.blockedBy = deps.unitAt(tile);
      break;
    }
    cursor = { x: tile.x, y: tile.y };
    live.tiles.push({ x: tile.x, y: tile.y });
    live.distance += 1;
  }
  live.to = cursor;
  return live;
}

/**
 * Runs a planned route.
 *
 * Each segment is applied as an ordinary movement event, and the contact for
 * that segment resolves between segments. That ordering is what makes a
 * mid-route strike honest: the mover really is standing where the strike says
 * it is, every reaction that would fire on the movement has already fired, and
 * the remaining segments are re-checked against a battlefield the strike may
 * have changed.
 */
function executeTrajectory(state, command) {
  const unitId = command.unitId;
  const ability = command.abilityId ? CONTENT.abilities[command.abilityId] : null;
  const rules = trajectoryRules(ability);
  const plan = planUnitTrajectory(state, unitId, command.segments, rules);
  const context = createTrajectoryContext(plan, unitId, { abilityId: command.abilityId || null });
  state.trajectory = context;

  // An illegal route costs nothing and moves nobody. The command validator
  // normally catches this first; the check lives here too so that no caller can
  // half-run a route the planner already refused.
  if (!plan.legal) {
    context.interrupted = true;
    context.interruptReason = plan.reason || "this route is not legal";
    queueTrajectoryCompleted(state, command, context, plan);
    return context;
  }

  // Priced from the plan, before the first tile: the mover is buying the
  // attempt, not the outcome. A route the world interrupts halfway is still
  // paid for, the same way a missed shot is.
  const cost = trajectoryResourceCost(state, unitId, ability, plan);
  if (cost.amount) spendCombatResource(state, cost.definition, cost.owner, cost.amount);

  if (ability) {
    state.activation.acted = true;
    state.activation.actionRecovery += abilityRecovery(command.abilityId);
  }

  for (const segment of plan.segments) {
    // A route is abandoned rather than forced through if the mover stopped
    // being able to travel it — killed by a reaction to its own movement, for
    // instance, which is a real thing that can happen now.
    const mover = state.units[unitId];
    if (!mover || !mover.alive || mover.dormant) {
      context.interrupted = true;
      context.interruptReason = "the mover can no longer travel";
      break;
    }
    if (mover.x !== segment.from.x || mover.y !== segment.from.y) {
      context.interrupted = true;
      context.interruptReason = "the frame is no longer where this segment starts";
      break;
    }

    const live = revalidateSegment(state, unitId, segment, rules);
    if (live.distance > 0) {
      const startFacing = normalizeFacing(mover.facing);
      queueEvent(state, {
        type: "unitMoved",
        unitId,
        from: { ...live.from },
        to: { ...live.to },
        path: [live.from].concat(live.tiles).map((tile) => ({ x: tile.x, y: tile.y })),
        tiles: live.distance,
        startFacing,
        stepFacings: live.tiles.map(() => startFacing),
        // Trajectory segments are voluntary movement and do spend the move,
        // but only once for the whole route — charged after the last segment.
        scripted: true,
        trajectory: {
          segmentIndex: segment.index,
          heading: segment.heading,
          redirect: segment.redirect,
          distance: live.distance,
          plannedDistance: segment.distance,
          totalDistance: context.distanceTravelled + live.distance
        }
      });
      processAllEvents(state);
      advanceContext(context, { ...segment, distance: live.distance, to: live.to });
    }

    // The contact still resolves when the segment is cut short: being stopped
    // by the very thing you were charging at is a hit, not a miss. Reach is
    // what decides, and `resolveTrajectoryContact` measures it from where the
    // frame actually ended up.
    if (segment.contact) {
      const resolved = resolveTrajectoryContact(state, unitId, ability, segment, context);
      context.contacts.push(resolved);
      processAllEvents(state);
      if (!rules.continueAfterContact) {
        context.interrupted = true;
        context.interruptReason = "the action ends on contact";
        break;
      }
    }

    if (live.blocked) {
      context.interrupted = true;
      context.interruptReason = live.blockReason;
      context.blockTile = live.blockTile;
      context.blockedBy = live.blockedBy;
      break;
    }
  }

  context.completed = !context.interrupted;
  if (context.distanceTravelled && state.activation && state.activation.unitId === unitId) {
    state.activation.moved = true;
    state.activation.movementRecovery += movementRecoveryFor(context.distanceTravelled);
  }
  queueTrajectoryCompleted(state, command, context, plan);
  return context;
}

/** The one event that closes a route, whether it finished or gave up. */
function queueTrajectoryCompleted(state, command, context, plan) {
  const unitId = command.unitId;
  const mover = state.units[unitId];
  queueEvent(state, {
    type: "trajectoryCompleted",
    unitId,
    abilityId: command.abilityId || null,
    distance: context.distanceTravelled,
    segments: context.distanceTravelled || context.contacts.length ? context.segmentIndex + 1 : 0,
    redirects: context.redirectCount,
    endpoint: mover ? { x: mover.x, y: mover.y } : { ...plan.endpoint },
    plannedEndpoint: { ...plan.endpoint },
    interrupted: context.interrupted,
    interruptReason: context.interruptReason,
    blockedBy: context.blockedBy || null
  });
}

/**
 * Resolves whatever an authored segment wanted to do at its end.
 *
 * The contact names a target and the ability supplies the effects, so this is
 * a dispatcher rather than a behaviour: `machStrikePunch()` would be the exact
 * mistake this phase exists to avoid.
 */
function resolveTrajectoryContact(state, unitId, ability, segment, context) {
  const contact = segment.contact;
  const targetId =
    contact.targetUnitId ||
    (contact.targetRef
      ? state.unitOrder.find((id) => state.units[id].ref === contact.targetRef)
      : null);
  const record = {
    segment: segment.index,
    targetUnitId: targetId,
    approachDistance: context.distanceTravelled,
    resolved: false,
    reason: null
  };
  if (!targetId || !state.units[targetId] || !state.units[targetId].alive) {
    record.reason = "the target is gone";
    return record;
  }
  const target = state.units[targetId];
  const mover = state.units[unitId];
  if (gridDistance(mover, target) > (contact.range == null ? 1 : contact.range)) {
    record.reason = "out of reach at that point on the route";
    return record;
  }

  const authored = (ability && ability.trajectory && ability.trajectory.contactEffects) || [];
  if (!authored.length) {
    record.reason = "this action does nothing on contact";
    return record;
  }

  // The precise half of the contract. The ability authors a *maximum*
  // displacement; the player picks the actual distance and heading, because
  // the exact tile is the point of the whole manoeuvre. Clamped to what the
  // ability allows, so choosing is not the same as being unlimited.
  const effects = authored.map((effect) => {
    if (effect.type !== "displace" || !contact.displace) return effect;
    const maximum = effect.distance == null ? 1 : effect.distance;
    const wanted = contact.displace.distance == null ? maximum : Number(contact.displace.distance);
    return {
      ...effect,
      distance: Math.max(0, Math.min(maximum, wanted)),
      heading: contact.displace.heading || effect.heading
    };
  });
  record.displacement = contact.displace
    ? { requested: contact.displace.distance, heading: contact.displace.heading || null }
    : null;

  resolveEffects(state, {
    sourceUnitId: unitId,
    targetUnitIds: [targetId],
    abilityId: ability ? ability.id : null,
    effects,
    targetTile: { x: target.x, y: target.y }
  });
  record.resolved = true;
  return record;
}

const COMMAND_VALIDATORS = {
  activateUnit(state, command) {
    const errors = [];
    const unit = state.units[command.unitId];
    if (!unit) return { errors: ["Unknown unit."], preview: {} };
    if (!unit.alive) errors.push("Defeated units cannot act.");
    if (state.activeUnitId) errors.push("Another unit is already activated.");
    const next = getNextActionableUnitId(state);
    if (next !== command.unitId) {
      errors.push("This unit is not next on the timeline.");
    }
    return { errors, preview: { time: unit.nextActionTime } };
  },

  /**
   * Setting the order of activations that are already coming.
   *
   * Every rule is read from the ability's authored `activationWindow`, so the
   * same command serves any commander with any reach. There is no unit id and
   * no ability id anywhere in this function.
   *
   * The plan is recomputed here rather than trusted from the caller. A preview
   * the player looked at three seconds ago is a claim about a world that may
   * have moved, and the difference between a stale plan and a live one is a
   * unit acting twice.
   */
  reorderActivations(state, command) {
    const errors = [];
    const unit = state.units[command.unitId];
    if (!unit) return { errors: ["Unknown unit."], preview: {} };
    if (state.activeUnitId !== command.unitId) errors.push("Unit is not the active unit.");
    if (!unit.alive) errors.push("Defeated units cannot act.");
    if (state.activation && state.activation.acted) errors.push("Unit has already acted.");

    const ability = command.abilityId ? CONTENT.abilities[command.abilityId] : null;
    if (!ability) errors.push("Unknown ability.");
    else if (!activationWindowRules(ability)) errors.push("That action does not command the timeline.");
    if (ability) errors.push(...abilityCostProblems(state, command.unitId, ability));

    const plan = ability ? planUnitActivationWindow(state, command.unitId, ability) : null;
    let check = { ok: false, reason: null };
    if (plan) {
      check = validateOrder(plan, command.order || []);
      if (!check.ok) errors.push(check.reason);
      // A reorder that changes nothing is not an error, but spending the
      // squad's coordination budget to confirm the status quo is a mistake the
      // player almost certainly did not mean to make.
      else if (sameOrder(plan.naturalOrder, command.order)) {
        errors.push("That is already the order.");
      }
    }

    return {
      errors,
      preview: errors.length
        ? {}
        : {
            previousOrder: plan.naturalOrder.slice(),
            order: command.order.slice(),
            windowStart: plan.windowStart,
            windowEnd: plan.windowEnd,
            barrier: plan.barrier,
            recovery: ability.timing.recovery
          }
    };
  },

  /**
   * Activating a fixture you own.
   *
   * Every rule here is read from the ability's authored `fixtureTargeting`
   * block, so the same command serves a remote charge, a beacon and a shield
   * node. There is no list of fixture ids anywhere in this function.
   */
  activateFixture(state, command) {
    const errors = [];
    const unit = state.units[command.unitId];
    if (!unit) return { errors: ["Unknown unit."], preview: {} };
    if (state.activeUnitId !== command.unitId) errors.push("Unit is not the active unit.");
    if (!unit.alive) errors.push("Defeated units cannot act.");
    if (state.activation && state.activation.acted) errors.push("Unit has already acted.");

    const ability = command.abilityId ? CONTENT.abilities[command.abilityId] : null;
    if (!ability) errors.push("Unknown ability.");
    const rules = fixtureTargetingRules(ability);
    if (ability && !rules) errors.push("That action does not activate fixtures.");

    errors.push(...abilityCostProblems(state, command.unitId, ability));

    const fixture = findFixture(state.fixtures, command.fixtureId);
    if (!fixture) errors.push("That fixture is no longer there.");
    else if (rules) {
      const check = fixtureActivationEligibility(state, command.unitId, fixture, rules);
      if (!check.ok) errors.push(check.reason);
    }

    return {
      errors,
      preview: errors.length
        ? {}
        : {
            fixtureId: fixture.id,
            definitionId: fixture.definitionId,
            tile: { x: fixture.x, y: fixture.y },
            recovery: ability.timing.recovery,
            targets: fixtureActivationTargets(state, fixture)
          }
    };
  },

  /**
   * A high-speed route: segments, redirects, and optional contacts along the
   * way. Validated by the same planner that executes it, so the preview the
   * player confirmed is the route that runs.
   */
  trajectory(state, command) {
    const errors = [];
    const unit = state.units[command.unitId];
    if (!unit) return { errors: ["Unknown unit."], preview: {} };
    if (state.activeUnitId !== command.unitId) errors.push("Unit is not the active unit.");
    if (state.activation && state.activation.moved) errors.push("Unit has already moved.");
    if (!unit.alive) errors.push("Defeated units cannot act.");

    const ability = command.abilityId ? CONTENT.abilities[command.abilityId] : null;
    if (command.abilityId && !ability) errors.push("Unknown ability.");
    if (ability && state.activation && state.activation.acted) {
      errors.push("Unit has already acted.");
    }

    const rules = trajectoryRules(ability);
    const plan = planUnitTrajectory(state, command.unitId, command.segments, rules);
    if (!plan.legal) errors.push(plan.reason || "That route is not legal.");

    // Resource costs are content's, charged through the generic layer. The
    // command refuses rather than half-running: a route the mover cannot pay
    // for must not leave them stranded halfway.
    const cost = trajectoryResourceCost(state, command.unitId, ability, plan);
    if (!cost.ok) errors.push(cost.reason);

    return {
      errors,
      preview: {
        plan,
        cost: cost.breakdown,
        endpoint: plan.endpoint,
        distance: plan.totalDistance,
        redirects: redirectTally(plan)
      }
    };
  },

  move(state, command) {
    const errors = [];
    const unit = state.units[command.unitId];
    if (!unit) return { errors: ["Unknown unit."], preview: {} };
    if (state.activeUnitId !== command.unitId) {
      errors.push("Unit is not the active unit.");
    }
    if (state.activation && state.activation.moved) {
      errors.push("Already moved this activation.");
    }
    if (state.activation && (state.activation.waited || state.activation.ended)) {
      errors.push("This activation has already ended.");
    }
    const result = validatePath(state, command.unitId, command.path || []);
    errors.push(...result.errors);
    return {
      errors,
      preview: {
        tiles: result.tiles,
        pathCost: result.cost,
        movementRecovery: movementRecoveryFor(result.tiles)
      }
    };
  },

  useAbility(state, command) {
    const errors = [];
    const unit = state.units[command.unitId];
    if (!unit) return { errors: ["Unknown unit."], preview: {} };
    if (state.activeUnitId !== command.unitId) {
      errors.push("Unit is not the active unit.");
    }
    if (state.activation && state.activation.acted) {
      errors.push("Already acted this activation.");
    }
    if (state.activation && (state.activation.waited || state.activation.ended)) {
      errors.push("This activation has already ended.");
    }
    const definition = CONTENT.units[unit.definitionId];
    if (!getUnitAbilities(state, command.unitId).includes(command.abilityId)) {
      errors.push("Unit does not know this ability.");
    }
    if ((unit.cooldowns[command.abilityId] || 0) > 0) {
      errors.push("Ability is on cooldown.");
    }
    const ability = CONTENT.abilities[command.abilityId];
    if (ability && (ability.conditions || []).length) {
      const context = createEffectContext(state, {
        sourceUnitId: command.unitId,
        targetUnitId: command.unitId,
        abilityId: command.abilityId,
        effect: {}
      });
      if (!evaluateConditionsPure(context, ability.conditions).value) {
        errors.push(ability.requirementText || "This ability's requirements are not met.");
      }
    }
    // Every scope, through one helper: a squad-wide cost is checked against
    // the squad's pool rather than looked for on the unit and not found.
    if (ability) errors.push(...abilityCostProblems(state, command.unitId, ability));
    if (
      ability &&
      transferAbilityIsIdle(
        state,
        command.unitId,
        command.abilityId,
        (command.target && command.target.unitId) || command.unitId
      )
    ) {
      errors.push("There is nothing to transfer there.");
    }
    let targeting = { targetUnitIds: [], tiles: [] };
    if (!errors.length) {
      targeting = evaluateTargeting(
        state,
        command.unitId,
        command.abilityId,
        command.target
      );
      errors.push(...targeting.errors);
    }
    const preview = errors.length
      ? {}
      : buildAbilityPreview(state, command, targeting);
    return { errors, preview };
  },

  setFacing(state, command) {
    const errors = [];
    const unit = state.units[command.unitId];
    if (!unit) return { errors: ["Unknown unit."], preview: {} };
    if (state.activeUnitId !== command.unitId) errors.push("Unit is not the active unit.");
    if (!GAME_CONFIG.facing.directions.includes(command.facing)) {
      errors.push("Facing must be northeast, southeast, southwest or northwest.");
    }
    if (state.activation && (state.activation.waited || state.activation.ended || state.activation.closed)) {
      errors.push("This activation has already ended.");
    }
    return {
      errors,
      preview: { from: normalizeFacing(unit.facing), to: normalizeFacing(command.facing) }
    };
  },

  wait(state, command) {
    const errors = [];
    if (state.activeUnitId !== command.unitId) {
      errors.push("Unit is not the active unit.");
    }
    if (state.activation && state.activation.acted) {
      errors.push("Already acted this activation.");
    }
    return {
      errors,
      preview: {
        recovery: GAME_CONFIG.timeline.waitRecovery,
        movementRecovery: state.activation ? state.activation.movementRecovery : 0,
        totalRecovery:
          GAME_CONFIG.timeline.waitRecovery +
          (state.activation ? state.activation.movementRecovery : 0)
      }
    };
  },

  endTurn(state, command) {
    const errors = [];
    if (state.activeUnitId !== command.unitId) {
      errors.push("Unit is not the active unit.");
    }
    if (!state.activation) {
      errors.push("No activation is in progress.");
    }
    if (state.activation && (state.activation.ended || state.activation.waited)) {
      errors.push("This activation has already ended.");
    }
    const activation = state.activation;
    const actionRecovery = activation
      ? activation.actionRecovery + endTurnBaseRecovery(state)
      : GAME_CONFIG.timeline.endTurnIdleRecovery;
    const movementRecovery = activation ? activation.movementRecovery : 0;
    return {
      errors,
      preview: {
        recovery: actionRecovery,
        actionRecovery,
        movementRecovery,
        totalRecovery: actionRecovery + movementRecovery,
        moved: activation ? activation.moved : false,
        acted: activation ? activation.acted : false
      }
    };
  }
};


/* ---------------------------------------------------------------
 * EFFECT FORECASTERS (pure: no RNG, no mutation)
 * -------------------------------------------------------------*/

function forecastContext(state, options) {
  const target = options.targetUnitId ? state.units[options.targetUnitId] : null;
  const source = state.units[options.sourceUnitId];
  return {
    state,
    sourceUnitId: options.sourceUnitId,
    targetUnitId: options.targetUnitId,
    abilityId: options.abilityId,
    effect: options.effect,
    sourceTile: options.sourceTile || (source ? { x: source.x, y: source.y } : null),
    targetTile: options.targetTile || (target ? { x: target.x, y: target.y } : null),
    chainDepth: options.chainDepth || 0
  };
}

const EFFECT_FORECASTERS = {
  damage(state, options) {
    const { sourceUnitId, targetUnitId, effect } = options;
    const numbers = effectContextStats(state, sourceUnitId, targetUnitId, effect);
    // The same scaling authority the executor uses, on the same context. A
    // forecast that ignored it would promise the unmarked number and then
    // deliver the marked one, which is the one thing a preview may never do.
    const scaling = effectScaling(state, options, effect.scaling);
    if (scaling.power) numbers.power += scaling.power;
    const flank = flankProfile(state, sourceUnitId, targetUnitId, {
      sourceTile: options.sourceTile,
      targetTile: options.targetTile
    });
    const baseAmount = Math.max(1, Math.round(FORMULAS.damage[effect.formula](numbers)));
    const amount = Math.max(
      1,
      Math.round(baseAmount * flank.damageMultiplier * scaling.multiplier)
    );
    const hitChance = effect.canMiss
      ? FORMULAS.accuracy.hitChance({
          accuracy: numbers.accuracy,
          evasion: numbers.evasion,
          bonus: (effect.accuracyBonus || 0) + flank.accuracyBonus
        })
      : 1;
    const hits = options.hits || 1;
    return [
      {
        targetUnitId,
        effectType: "damage",
        baseAmount,
        amount,
        hits,
        totalAmount: amount * hits,
        hitChance,
        lethal: amount * hits >= state.units[targetUnitId].currentHp,
        flankArc: flank.arc,
        targetFacing: flank.targetFacing,
        attackerDirection: flank.attackerDirection,
        accuracyBonus: flank.accuracyBonus,
        damageMultiplier: flank.damageMultiplier
      }
    ];
  },

  /**
   * What a transfer would actually move, asked of the live balances.
   *
   * The whole point of forecasting a transfer is the cap: an ability that
   * says "restores 2" and delivers 1 because the target is nearly full has
   * lied to the player, and this is the only place that can be prevented.
   */
  transferResource(state, options) {
    const plan = transferPlanFor(state, {
      effect: options.effect,
      sourceUnitId: options.sourceUnitId,
      targetUnitId: options.targetUnitId,
      abilityId: options.abilityId
    });
    if (!plan) return [];
    const result = planTransfer(state, plan);
    return [
      {
        targetUnitId: options.targetUnitId,
        effectType: "transferResource",
        fromUnitId: plan.fromUnitId,
        toUnitId: plan.toUnitId,
        fromResourceId: plan.fromDefinition.id,
        toResourceId: plan.toDefinition.id,
        fromResourceName: plan.fromDefinition.name || plan.fromDefinition.id,
        toResourceName: plan.toDefinition.name || plan.toDefinition.id,
        toScope: plan.toDefinition.scope,
        spent: result.spent,
        gained: result.gained,
        amount: result.gained,
        transfers: result.transfers,
        limitedBy: result.limitedBy || null,
        display: {
          kind: "resource",
          label: result.ok ? "TRANSFERS" : "NOTHING TO MOVE",
          value: result.ok
            ? "+" + result.gained + " " + (plan.toDefinition.name || plan.toDefinition.id)
            : transferRefusalText(result.limitedBy)
        }
      }
    ];
  },

  heal(state, options) {
    const { sourceUnitId, targetUnitId, effect } = options;
    const numbers = effectContextStats(state, sourceUnitId, targetUnitId, effect);
    return [
      {
        targetUnitId,
        effectType: "heal",
        amount: Math.max(1, Math.round(FORMULAS.healing[effect.formula](numbers)))
      }
    ];
  },

  applyStatus(state, options) {
    return [
      {
        targetUnitId: options.targetUnitId,
        effectType: "applyStatus",
        statusId: options.effect.statusId,
        chance: options.effect.chance == null ? 1 : options.effect.chance
      }
    ];
  },

  removeStatus(state, options) {
    return [
      {
        targetUnitId: options.targetUnitId,
        effectType: "removeStatus",
        statusId: options.effect.statusId,
        chance: 1,
        display: { kind: "status", label: "REMOVES", value: CONTENT.statuses[options.effect.statusId].name }
      }
    ];
  },

  modifyTimeline(state, options) {
    const effect = options.effect;
    return [
      {
        targetUnitId: options.targetUnitId,
        effectType: "modifyTimeline",
        delta: (effect.delay || 0) - (effect.hasten || 0)
      }
    ];
  },

  shield(state, options) {
    const effect = options.effect;
    return [
      {
        targetUnitId: options.targetUnitId,
        effectType: "shield",
        amount: effect.amount || 0,
        display: {
          kind: "shield",
          label: "SHIELD",
          value: String(effect.amount || 0),
          detail: effect.duration
            ? effect.duration.amount + " " + effect.duration.type
            : "until consumed"
        }
      }
    ];
  },

  modifyStat(state, options) {
    const effect = options.effect;
    const value =
      effect.mode === "multiplier"
        ? Math.round((effect.value - 1) * 100) + "%"
        : String(effect.value);
    return [
      {
        targetUnitId: options.targetUnitId,
        effectType: "modifyStat",
        stat: effect.stat,
        mode: effect.mode,
        value: effect.value,
        display: {
          kind: "stat",
          label: effect.stat.toUpperCase(),
          value: (effect.mode === "flat" && effect.value > 0 ? "+" : "") + value,
          detail: effect.duration ? effect.duration.amount + " " + effect.duration.type : "permanent"
        }
      }
    ];
  },

  displace: (state, options) => forcedMoveForecast(state, options, "SHIFT"),
  push: (state, options) => forcedMoveForecast(state, options, "PUSH"),
  pull: (state, options) => forcedMoveForecast(state, options, "PULL"),
  moveUnit: (state, options) => forcedMoveForecast(state, options, "MOVE"),

  teleport(state, options) {
    const tile = options.targetTile;
    return [
      {
        targetUnitId: options.targetUnitId,
        effectType: "teleport",
        destination: tile ? { x: tile.x, y: tile.y } : null,
        display: {
          kind: "movement",
          label: "TELEPORT",
          value: tile ? tile.x + "," + tile.y : "-",
          detail: "destination"
        }
      }
    ];
  },

  swapPositions(state, options) {
    return [
      {
        targetUnitId: options.targetUnitId,
        effectType: "swapPositions",
        display: { kind: "movement", label: "SWAP", value: "positions", detail: "with target" }
      }
    ];
  },

  restoreResource(state, options) {
    const effect = options.effect;
    return [
      {
        targetUnitId: options.targetUnitId,
        effectType: "restoreResource",
        resourceId: effect.resourceId,
        amount: effect.amount,
        display: {
          kind: "resource",
          label: effect.resourceId.toUpperCase(),
          value: "+" + effect.amount,
          detail: "restored"
        }
      }
    ];
  },

  spendResource(state, options) {
    const effect = options.effect;
    return [
      {
        targetUnitId: options.targetUnitId,
        effectType: "spendResource",
        resourceId: effect.resourceId,
        amount: effect.amount,
        display: {
          kind: "resource",
          label: effect.resourceId.toUpperCase(),
          value: "-" + effect.amount,
          detail: "spent"
        }
      }
    ];
  },

  createTerrain(state, options) {
    const effect = options.effect;
    return [
      {
        targetUnitId: options.targetUnitId,
        effectType: "createTerrain",
        terrainId: effect.terrainId,
        display: {
          kind: "terrain",
          label: "TERRAIN",
          value: CONTENT.terrains[effect.terrainId].name,
          detail: effect.duration ? effect.duration.amount + " activations" : "permanent"
        }
      }
    ];
  },

  removeTerrain(state, options) {
    return [
      {
        targetUnitId: options.targetUnitId,
        effectType: "removeTerrain",
        display: { kind: "terrain", label: "TERRAIN", value: "cleared", detail: "" }
      }
    ];
  },

  spawnUnit(state, options) {
    const effect = options.effect;
    return [
      {
        targetUnitId: options.targetUnitId,
        effectType: "spawnUnit",
        definitionId: effect.definitionId,
        display: {
          kind: "summon",
          label: "SUMMON",
          value: CONTENT.units[effect.definitionId].name,
          detail: effect.duration ? effect.duration + " activations" : "permanent"
        }
      }
    ];
  },

  despawnUnit(state, options) {
    return [
      {
        targetUnitId: options.targetUnitId,
        effectType: "despawnUnit",
        display: { kind: "summon", label: "BANISH", value: "target", detail: "" }
      }
    ];
  },

  revive(state, options) {
    const effect = options.effect;
    const stats = calculateUnitStats(state, options.targetUnitId);
    const amount =
      effect.percent != null
        ? Math.max(1, Math.round((stats.maxHp * effect.percent) / 100))
        : effect.amount || 1;
    return [
      {
        targetUnitId: options.targetUnitId,
        effectType: "revive",
        amount,
        display: { kind: "revive", label: "REVIVE", value: String(amount) + " HP", detail: "" }
      }
    ];
  },

  transformUnit(state, options) {
    const effect = options.effect;
    return [
      {
        targetUnitId: options.targetUnitId,
        effectType: "transformUnit",
        definitionId: effect.definitionId,
        display: {
          kind: "transform",
          label: "TRANSFORM",
          value: CONTENT.units[effect.definitionId].name,
          detail: effect.duration ? effect.duration.amount + " activations" : "permanent"
        }
      }
    ];
  },

  copyStatus: (state, options) => statusTransferForecast(options, "COPY"),
  transferStatus: (state, options) => statusTransferForecast(options, "TRANSFER"),

  cleanse(state, options) {
    const effect = options.effect;
    return [
      {
        targetUnitId: options.targetUnitId,
        effectType: "cleanse",
        display: {
          kind: "status",
          label: "CLEANSE",
          value: effect.statusId
            ? CONTENT.statuses[effect.statusId].name
            : effect.category || "negative",
          detail: effect.count ? "up to " + effect.count : "all matching"
        }
      }
    ];
  },

  dispel(state, options) {
    const effect = options.effect;
    return [
      {
        targetUnitId: options.targetUnitId,
        effectType: "dispel",
        display: {
          kind: "status",
          label: "DISPEL",
          value: effect.stat ? effect.stat : effect.category || "positive",
          detail: effect.removesShields ? "and shields" : ""
        }
      }
    ];
  },

  delayedEffect(state, options) {
    const effect = options.effect;
    const inner = forecastEffectList(state, {
      ...options,
      effects: effect.effects || [],
      chainDepth: (options.chainDepth || 0) + 1
    });
    return [
      {
        targetUnitId: options.targetUnitId,
        effectType: "delayedEffect",
        remaining: effect.delayActivations == null ? 1 : effect.delayActivations,
        display: {
          kind: "delayed",
          label: "DELAYED",
          value: (effect.delayActivations == null ? 1 : effect.delayActivations) + " activations",
          detail: "then resolves"
        }
      }
    ].concat(inner.map((entry) => ({ ...entry, delayed: true })));
  },

  conditionalEffect(state, options) {
    const effect = options.effect;
    const context = forecastContext(state, options);
    const evaluation = evaluateConditionsPure(context, effect.conditions);
    if (evaluation.deterministic) {
      const branch = evaluation.value ? effect.ifTrue : effect.ifFalse;
      return forecastEffectList(state, {
        ...options,
        effects: branch || [],
        chainDepth: (options.chainDepth || 0) + 1
      }).map((entry) => ({ ...entry, branch: evaluation.value ? "ifTrue" : "ifFalse", certain: true }));
    }
    const truthy = forecastEffectList(state, {
      ...options,
      effects: effect.ifTrue || [],
      chainDepth: (options.chainDepth || 0) + 1
    }).map((entry) => ({ ...entry, branch: "ifTrue", branchProbability: evaluation.probability }));
    const falsy = forecastEffectList(state, {
      ...options,
      effects: effect.ifFalse || [],
      chainDepth: (options.chainDepth || 0) + 1
    }).map((entry) => ({ ...entry, branch: "ifFalse", branchProbability: 1 - evaluation.probability }));
    return truthy.concat(falsy);
  },

  refreshActivationResource(state, options) {
    const effect = options.effect;
    return [
      {
        targetUnitId: options.targetUnitId,
        effectType: "refreshActivationResource",
        display: {
          kind: "activation",
          label: "REFUND",
          value: effect.resource === "action" ? "action" : "movement",
          detail: "once per activation"
        }
      }
    ];
  },

  repeatEffect(state, options) {
    const effect = options.effect;
    const count = Math.min(
      effect.count == null ? 1 : effect.count,
      GAME_CONFIG.limits.maxRepeatedEffects
    );
    const inner = forecastEffectList(state, {
      ...options,
      effects: effect.effects || [],
      hits: count,
      chainDepth: (options.chainDepth || 0) + 1
    });
    return inner.map((entry) => ({ ...entry, hits: count, repeated: true }));
  },

  /**
   * Forecasts every node the chain will reach, not just the one aimed at.
   *
   * Uses the same planner execution uses, so the numbers beside the cursor are
   * the numbers the chain will produce — including the fact that it stops one
   * enemy short.
   */
  placeFixture(state, options) {
    const definition = fixtureDefinition(options.effect.definitionId);
    return [
      {
        targetUnitId: null,
        effectType: "placeFixture",
        label: "PLACE",
        detail: (definition && definition.name) || options.effect.definitionId
      }
    ];
  },

  setFixtureState(state, options) {
    return [
      { targetUnitId: null, effectType: "setFixtureState", label: "SET", detail: options.effect.state }
    ];
  },

  propagate(state, options) {
    const effect = options.effect;
    const plan = planUnitPropagation(
      state,
      options.sourceUnitId,
      options.abilityId,
      options.targetUnitId
    );
    const out = [];
    for (const node of plan.nodes) {
      const unit = state.units[node.id];
      if (!unit) continue;
      const inner = forecastEffectList(state, {
        ...options,
        targetUnitId: node.id,
        targetTile: { x: unit.x, y: unit.y },
        effects: effect.effects || [],
        chainDepth: (options.chainDepth || 0) + 1
      });
      for (const entry of inner) {
        out.push({
          ...entry,
          targetUnitId: node.id,
          hop: node.hop,
          hopDistance: node.distance,
          arcedFrom: node.fromId
        });
      }
    }
    return out;
  }
};

function forcedMoveForecast(state, options, label) {
  const effect = options.effect;
  const unit = state.units[options.targetUnitId];
  const source = state.units[options.sourceUnitId];
  const distance = effect.distance == null ? 1 : effect.distance;
  let destination = null;
  if (unit && source) {
    const direction =
      options.effect.type === "pull"
        ? directionBetween(unit, source)
        : directionBetween(source, unit);
    const map = getMap(state);
    let x = unit.x;
    let y = unit.y;
    for (let step = 0; step < distance; step += 1) {
      const nextX = x + direction.dx;
      const nextY = y + direction.dy;
      if (!inBounds(map, nextX, nextY)) break;
      const traversal = evaluateTraversalStep(
        state,
        unit.id,
        { x, y },
        { x: nextX, y: nextY },
        {
          movementPolicy: effect.movementPolicy || "forced",
          ignoresElevation: effect.ignoresElevation === true
        }
      );
      if (!traversal.valid) break;
      x = nextX;
      y = nextY;
    }
    destination = { x, y };
  }
  const blocked =
    destination && unit
      ? Math.abs(destination.x - unit.x) + Math.abs(destination.y - unit.y) < distance
      : false;
  return [
    {
      targetUnitId: options.targetUnitId,
      effectType: options.effect.type,
      distance,
      destination,
      blocked,
      display: {
        kind: "movement",
        label,
        value: distance + (distance === 1 ? " tile" : " tiles"),
        detail: destination
          ? "to " + destination.x + "," + destination.y + (blocked ? " (blocked)" : "")
          : ""
      }
    }
  ];
}

function statusTransferForecast(options, label) {
  return [
    {
      targetUnitId: options.targetUnitId,
      effectType: options.effect.type,
      display: {
        kind: "status",
        label,
        value: options.effect.statusId
          ? CONTENT.statuses[options.effect.statusId].name
          : options.effect.tag || "matching statuses",
        detail: ""
      }
    }
  ];
}

function forecastEffectList(state, options) {
  const outcomes = [];
  if ((options.chainDepth || 0) > GAME_CONFIG.limits.maxEffectChainDepth) return outcomes;
  for (const effect of options.effects || []) {
    const forecaster = EFFECT_FORECASTERS[effect.type];
    if (!forecaster) continue;
    const context = forecastContext(state, { ...options, effect });
    if (effect.conditions) {
      const evaluation = evaluateConditionsPure(context, effect.conditions);
      if (evaluation.deterministic && !evaluation.value) continue;
    }
    outcomes.push(
      ...forecaster(state, {
        ...options,
        effect,
        targetTile: context.targetTile
      })
    );
  }
  return outcomes;
}

function buildAbilityPreview(state, command, targeting, movementRecoveryOverride) {
  const ability = CONTENT.abilities[command.abilityId];
  const outcomes = [];
  const targetTile = targeting.tile || null;
  const targetIds = targeting.targetUnitIds.length
    ? targeting.targetUnitIds
    : [null];
  for (const targetUnitId of targetIds) {
    outcomes.push(
      ...forecastEffectList(state, {
        sourceUnitId: command.unitId,
        targetUnitId,
        abilityId: command.abilityId,
        sourceTile: command.origin || null,
        targetTile,
        effects: ability.effects
      })
    );
  }
  const stats = calculateUnitStats(state, command.unitId);
  const movementRecovery =
    movementRecoveryOverride == null
      ? state.activation
        ? state.activation.movementRecovery
        : 0
      : movementRecoveryOverride;
  const priorActionRecovery =
    state.activation && state.activation.unitId === command.unitId
      ? state.activation.actionRecovery
      : 0;
  const totalRecovery = ability.timing.recovery + movementRecovery + priorActionRecovery;
  return {
    targetUnitIds: targeting.targetUnitIds,
    tiles: targeting.tiles,
    recovery: ability.timing.recovery,
    priorActionRecovery,
    cooldown: ability.timing.cooldown,
    totalRecovery,
    nextActionTime: projectNextActionTime(state, command.unitId, totalRecovery),
    movementRecovery,
    speed: stats.speed,
    turnRate: FORMULAS.timeline.turnRate(stats.speed),
    outcomes
  };
}

function validateCommand(state, command) {
  if (!command || !command.type) {
    return { valid: false, errors: ["Command has no type."], preview: {} };
  }
  const validator = COMMAND_VALIDATORS[command.type];
  if (!validator) {
    return { valid: false, errors: ["Unknown command type: " + command.type], preview: {} };
  }
  if (state.finished) {
    return { valid: false, errors: ["The battle is already finished."], preview: {} };
  }
  const result = validator(state, command);
  return {
    valid: result.errors.length === 0,
    errors: result.errors,
    preview: result.errors.length ? {} : result.preview || {}
  };
}

const COMMAND_HANDLERS = {
  activateUnit(state, command) {
    const unit = state.units[command.unitId];
    state.currentTime = Math.max(state.currentTime, unit.nextActionTime);
    state.activeUnitId = unit.id;
    state.activation = {
      unitId: unit.id,
      moved: false,
      acted: false,
      waited: false,
      ended: false,
      movementRecovery: 0,
      actionRecovery: 0,
      // Banked by `modifyTurnDelay` while this unit is the one acting. Applied
      // to the recovery `turnEnded` charges, never to the clock directly.
      turnDelayAdjustment: 0,
      pendingEnd: null
    };
    queueEvent(state, { type: "unitActivated", unitId: unit.id });
  },

  trajectory(state, command) {
    executeTrajectory(state, command);
  },

  /**
   * Commits an order over activations that are already coming.
   *
   * Re-plans rather than trusting the validator's preview, for the same reason
   * the validator re-plans rather than trusting the caller: these are two
   * different moments and the only safe assumption is that the world moved
   * between them.
   */
  reorderActivations(state, command) {
    const ability = CONTENT.abilities[command.abilityId];
    const plan = planUnitActivationWindow(state, command.unitId, ability);
    const previous = plan.naturalOrder.slice();

    state.activation.acted = true;
    state.activation.actionRecovery += abilityRecovery(command.abilityId);
    for (const resourceId of Object.keys(ability.costs || {})) {
      queueEvent(state, {
        type: "resourceSpent",
        sourceUnitId: command.unitId,
        targetUnitId: command.unitId,
        resourceId,
        amount: ability.costs[resourceId]
      });
    }

    const dealt = dealSlots(plan, command.order);
    commitSequence(state.sequencing, dealt, {
      issuedBy: command.unitId,
      abilityId: command.abilityId,
      issuedAt: state.activationCount
    });
    queueEvent(state, {
      type: "activationOrderChanged",
      sourceUnitId: command.unitId,
      abilityId: command.abilityId,
      previousOrder: previous,
      order: command.order.slice(),
      cost: { ...(ability.costs || {}) },
      windowStart: plan.windowStart,
      windowEnd: plan.windowEnd
    });
  },

  /**
   * Sets off one of your own fixtures, now, because you chose to.
   *
   * Generic on purpose: what it selects is "a fixture this ability is allowed
   * to activate", which is as true of a beacon or a shield node as it is of a
   * charge. The ability names a tag, never an id.
   */
  activateFixture(state, command) {
    const ability = CONTENT.abilities[command.abilityId];
    const fixture = findFixture(state.fixtures, command.fixtureId);
    state.activation.acted = true;
    state.activation.actionRecovery += abilityRecovery(command.abilityId);
    for (const resourceId of Object.keys((ability && ability.costs) || {})) {
      queueEvent(state, {
        type: "resourceSpent",
        sourceUnitId: command.unitId,
        targetUnitId: command.unitId,
        resourceId,
        amount: ability.costs[resourceId]
      });
    }
    // What the ability does to the device it selected. Setting it off is the
    // default; anything else moves it between states instead, which is how one
    // command serves both a detonator and a pair of wire cutters.
    const action = (ability && ability.fixtureAction) || "activate";
    if (action !== "activate") {
      const next = action === "disarm" ? "disarmed" : action === "arm" ? "armed" : "removed";
      const changed = setFixtureState(state.fixtures, fixture.id, next);
      if (changed.ok && changed.changed) {
        queueEvent(state, {
          type: "fixtureStateChanged",
          fixtureId: fixture.id,
          definitionId: fixture.definitionId,
          ownerTeamId: fixture.ownerTeamId || null,
          from: changed.from,
          to: next,
          byUnitId: command.unitId
        });
      }
      return;
    }
    queueEvent(state, {
      type: "fixtureTriggered",
      fixtureId: fixture.id,
      definitionId: fixture.definitionId,
      unitId: command.unitId,
      sourceUnitId: fixture.ownerUnitId || command.unitId,
      ownerTeamId: fixture.ownerTeamId || null,
      tile: { x: fixture.x, y: fixture.y },
      // The one thing that separates this from a pressure plate, and the
      // reason it is worth recording rather than inferring.
      activation: "command"
    });
  },

  /**
   * Voluntary movement. Declared, and therefore stoppable.
   *
   * Being shoved is not: `unitForcedMove` has no declaration and never will,
   * because a mover who did not choose to go has made no decision for a
   * defender to answer. That asymmetry is the point, not an oversight — it is
   * what stops a duelist from vetoing the consequences of a shove she was not
   * part of.
   */
  move(state, command) {
    const path = command.path;
    const unit = state.units[command.unitId];
    const startFacing = normalizeFacing(unit.facing);
    const stepFacings = path.slice(1).map((tile, index) =>
      facingFromTiles(path[index], tile, startFacing)
    );
    declareAction(state, {
      kind: "movement",
      actionName: "the move",
      unitId: command.unitId,
      from: { x: path[0].x, y: path[0].y },
      target: { x: path[path.length - 1].x, y: path[path.length - 1].y },
      path: path.map((p) => ({ x: p.x, y: p.y })),
      tiles: path.length - 1,
      stepFacings,
      facingFrom: startFacing,
      facingTo: stepFacings.length ? stepFacings[stepFacings.length - 1] : startFacing
    });
  },

  useAbility(state, command) {
    const targeting = evaluateTargeting(
      state,
      command.unitId,
      command.abilityId,
      command.target
    );
    state.activation.acted = true;
    state.activation.actionRecovery += abilityRecovery(command.abilityId);
    const abilityDefinition = CONTENT.abilities[command.abilityId];
    // Queued ahead of the declaration on purpose: the cost is spent before
    // anybody can object, which is the cost-commit rule in the one place it
    // has to be true.
    for (const resourceId of Object.keys(abilityDefinition.costs || {})) {
      queueEvent(state, {
        type: "resourceSpent",
        sourceUnitId: command.unitId,
        targetUnitId: command.unitId,
        resourceId,
        amount: abilityDefinition.costs[resourceId]
      });
    }
    const actor = state.units[command.unitId];
    declareAction(state, {
      kind: "ability",
      actionName: abilityDefinition.name,
      unitId: command.unitId,
      abilityId: command.abilityId,
      target: targeting.tile,
      targetUnitIds: targeting.targetUnitIds,
      tiles: targeting.tiles,
      facingFrom: normalizeFacing(actor.facing),
      facingTo: targeting.tile
        ? facingFromTiles(actor, targeting.tile, actor.facing)
        : normalizeFacing(actor.facing),
      redirectable: actionIsRedirectable(abilityDefinition, targeting)
    });
  },

  setFacing(state, command) {
    const unit = state.units[command.unitId];
    queueEvent(state, {
      type: "facingChanged",
      unitId: command.unitId,
      from: normalizeFacing(unit.facing),
      to: normalizeFacing(command.facing),
      reason: "manual"
    });
  },

  wait(state, command) {
    state.activation.acted = true;
    state.activation.waited = true;
    state.activation.actionRecovery += GAME_CONFIG.timeline.waitRecovery;
    logLine(state, "unitWaited", unitLabel(state, command.unitId) + " waits", {
      unitId: command.unitId
    });
  },

  endTurn(state) {
    const activation = state.activation;
    activation.ended = true;
    activation.actionRecovery += endTurnBaseRecovery(state);
  }
};

/**
 * Validate, then mutate. Invalid commands never touch battle state.
 */
/**
 * Everything a command does *after* its events have drained: close the
 * activation, check objectives, run the mission script.
 *
 * Split out because a reaction window can park the queue halfway through. The
 * tail must not run against a half-applied event, so it is skipped while a
 * window is pending and replayed by `settleAfterReactions` once the player
 * answers.
 */
/**
 * The activation invariant.
 *
 * After anything that could have changed the world out of turn — a reaction
 * chain, a mission action, a scripted kill — the battle must be in exactly one
 * of three states: an active unit that can still do something, no active unit
 * with someone next on the timeline, or finished. Anything else is a battle
 * waiting for input that will never come.
 *
 * The case this exists for is an active unit that stops being able to act
 * *while it is active*: destroyed by a reaction it triggered, dormant, or
 * removed. `shouldAutomaticallyEndActivation` cannot see that, because from
 * its point of view the unit simply has not spent its resources yet.
 *
 * @returns true when it had to intervene
 */
function ensureActivationIsValid(state) {
  const activation = state.activation;
  const unitId = state.activeUnitId;
  if (!unitId) return false;
  const unit = state.units[unitId];
  const stillPlayable = !!unit && unit.alive && !unit.dormant;
  if (stillPlayable) return false;
  if (activation) activation.closed = true;
  // No recovery is charged: a destroyed frame is not "recovering", and a
  // dormant one never spent anything.
  state.activeUnitId = null;
  state.activation = null;
  logLine(state, "turnEnded", unitLabel(state, unitId) + " can no longer act; the activation ends", {
    unitId,
    reason: unit && !unit.alive ? "destroyed" : "unavailable"
  });
  return true;
}

function settleCommand(state, options) {
  const onEvent = options && options.onEvent ? options.onEvent : null;
  let events = [];
  if (reactionWindowPending(state)) return events;

  ensureActivationIsValid(state);
  finishActivationIfComplete(state);
  if (state.activation && state.activation.pendingEnd) {
    const pending = state.activation.pendingEnd;
    state.activation.pendingEnd = null;
    endActivation(state, pending);
    events = events.concat(processAllEvents(state, onEvent));
  }
  if (reactionWindowPending(state)) return events;
  // Anything that just happened may have killed a commanded unit or moved one
  // on the timeline. Dropping those slots here means the sequencing layer can
  // never outlive the facts it was built from.
  reportDroppedSequence(state, refreshSequencing(state));
  checkObjectives(state, onEvent);

  // Mission script last, so beats react to a settled battle state. Objectives
  // are then re-checked because a beat may have replaced them with something
  // already satisfied. Two passes, never a loop.
  if (state.mission) {
    runMissionScript(state, options);
    events = events.concat(processAllEvents(state, onEvent));
    checkObjectives(state, onEvent);
  }
  return events;
}

/** Resumes the tail of a command after a reaction prompt was answered. */
function settleAfterReactions(state, options) {
  if (reactionWindowPending(state)) return [];
  return settleCommand(state, options);
}

/**
 * What the battle should do next, as a single answer.
 *
 * The reaction lifecycle used to have no such answer, and that is precisely
 * how it deadlocked: the authoritative layer ended an activation, the
 * presentation layer never heard about it, and both sides waited. Rather than
 * teach the UI about reactions, the engine now states the continuation and the
 * UI obeys it.
 *
 *   "finished"    the battle is over
 *   "reaction"    a choice is pending; nothing else may proceed
 *   "active"      a unit is activated and can still act
 *   "advance"     no active unit; `unitId` is next on the timeline
 *   "stalled"     nothing can act at all — a bug, reported rather than hidden
 */
function battleContinuation(state) {
  if (state.finished) return { kind: "finished", unitId: null };
  if (reactionWindowPending(state)) return { kind: "reaction", unitId: null };
  if (state.activeUnitId) {
    const unit = state.units[state.activeUnitId];
    if (unit && unit.alive && !unit.dormant) return { kind: "active", unitId: state.activeUnitId };
    // Should be unreachable after `ensureActivationIsValid`; reported rather
    // than papered over, because a silent recovery here would hide the bug.
    return { kind: "stalled", unitId: state.activeUnitId, reason: "the active unit cannot act" };
  }
  const nextId = getNextActionableUnitId(state);
  if (nextId) return { kind: "advance", unitId: nextId };
  return { kind: "stalled", unitId: null, reason: "no unit can act" };
}

/**
 * Validate, then mutate. Invalid commands never touch battle state.
 */
function executeCommand(state, command, options) {
  const onEvent = options && options.onEvent ? options.onEvent : null;
  const validation = validateCommand(state, command);
  if (!validation.valid) {
    return { ok: false, errors: validation.errors, events: [] };
  }
  COMMAND_HANDLERS[command.type](state, command);
  let events = processAllEvents(state, onEvent);
  events = events.concat(settleCommand(state, options));
  return {
    ok: true,
    errors: [],
    events,
    preview: validation.preview,
    pendingReaction: reactionWindowPending(state)
  };
}

/* ---------------------------------------------------------------
 * OBJECTIVES
 * -------------------------------------------------------------*/

/** Marks handlers whose victory always implies one surviving team. */
function markEliminationObjectives(handlers, ids) {
  for (const id of ids) {
    if (handlers[id]) handlers[id].requiresElimination = true;
  }
}

/**
 * Objective parameters, with authored unit refs resolved against live state.
 *
 * Script-owned objectives keep symbolic refs rather than compile-time ids so a
 * unit spawned mid-battle can be an objective target. Legacy encounters carry
 * `unitIds` directly and pass through untouched.
 */
function resolveObjectiveParams(state, params) {
  const source = params || {};
  if (!source.unitRefs && !source.phases) return source;
  const resolved = { ...source };
  if (source.unitRefs) {
    resolved.unitIds = source.unitRefs
      .map((ref) => state.unitOrder.find((id) => state.units[id].ref === ref))
      .filter(Boolean);
  }
  if (source.phases) {
    resolved.phases = source.phases.map((phase) => ({
      ...phase,
      params: resolveObjectiveParams(state, phase.params)
    }));
  }
  return resolved;
}

function objectiveParams(state) {
  return resolveObjectiveParams(state, (state.objectiveState && state.objectiveState.params) || {});
}

function teamAlive(state, teamId) {
  return livingUnits(state).some((unit) => unit.teamId === teamId);
}

/**
 * Elimination resolves on *hostility*, not on team identity.
 *
 * Counting distinct surviving teams was correct while every different team was
 * automatically an enemy. Once factions exist, an allied third party sharing
 * the field means two teams survive and the battle would never end — which is
 * exactly what Grayfield produces after Section Seven changes sides.
 *
 * Under the default matrix (different team means hostile) this is equivalent
 * to the old rule, so existing encounters are unaffected.
 */
function eliminationResult(state) {
  const alive = livingUnits(state);
  if (!alive.length) return { finished: true, winner: null };

  for (let i = 0; i < alive.length; i += 1) {
    for (let j = i + 1; j < alive.length; j += 1) {
      if (isHostile(state, alive[i].id, alive[j].id)) return { finished: false, winner: null };
    }
  }

  // Nobody left is hostile to anybody. The survivors won; name the human side
  // if it is among them so the result reads correctly for the player.
  const survivingTeamIds = new Set(alive.map((unit) => unit.teamId));
  const human = state.teams.find((team) => team.controller === "human" && survivingTeamIds.has(team.id));
  const winner = human || state.teams.find((team) => survivingTeamIds.has(team.id));
  return { finished: true, winner: winner ? winner.id : null };
}

/**
 * Objectives are data-driven: an encounter names a handler and supplies its
 * parameters. Every handler resolves from authoritative battle state only.
 */
const OBJECTIVE_HANDLERS = {
  defeatAllEnemies(state) {
    return eliminationResult(state);
  },

  // Any listed unit reaching an extraction tile wins; losing the team loses.
  reachExtraction(state) {
    const params = objectiveParams(state);
    const tiles = params.tiles || [];
    const escapees = params.unitIds || state.unitOrder.filter((id) => state.units[id].teamId === "player");
    if (!teamAlive(state, params.teamId || "player")) {
      return { finished: true, winner: params.opposingTeamId || "foe" };
    }
    for (const unitId of escapees) {
      const unit = state.units[unitId];
      if (!unit || !unit.alive) continue;
      if (tiles.some((tile) => tile.x === unit.x && tile.y === unit.y)) {
        return { finished: true, winner: params.teamId || "player" };
      }
    }
    // Fighting the whole pursuit force off is also a way out.
    return eliminationResult(state);
  },

  // Every protected unit must survive; clearing the hostiles wins.
  protectUnits(state) {
    const params = objectiveParams(state);
    for (const unitId of params.unitIds || []) {
      const unit = state.units[unitId];
      if (!unit || !unit.alive) {
        return { finished: true, winner: params.opposingTeamId || "foe" };
      }
    }
    return eliminationResult(state);
  },

  // Destroy specific units rather than the whole opposing force.
  destroyTargets(state) {
    const params = objectiveParams(state);
    const targets = params.unitIds || [];
    if (!teamAlive(state, params.teamId || "player")) {
      return { finished: true, winner: params.opposingTeamId || "foe" };
    }
    const remaining = targets.filter((unitId) => {
      const unit = state.units[unitId];
      return unit && unit.alive;
    });
    if (!remaining.length) return { finished: true, winner: params.teamId || "player" };
    return { finished: false, winner: null };
  },

  // Stay alive (and optionally on a tile) for a number of activations.
  surviveActivations(state) {
    const params = objectiveParams(state);
    if (!teamAlive(state, params.teamId || "player")) {
      return { finished: true, winner: params.opposingTeamId || "foe" };
    }
    if (params.unitIds) {
      for (const unitId of params.unitIds) {
        const unit = state.units[unitId];
        if (!unit || !unit.alive) {
          return { finished: true, winner: params.opposingTeamId || "foe" };
        }
      }
    }
    if (state.activationCount >= (params.activations || 12)) {
      return { finished: true, winner: params.teamId || "player" };
    }
    return eliminationResult(state);
  },

  // Hold a set of tiles: occupy them when the timer expires.
  holdPosition(state) {
    const params = objectiveParams(state);
    if (!teamAlive(state, params.teamId || "player")) {
      return { finished: true, winner: params.opposingTeamId || "foe" };
    }
    if (state.activationCount < (params.activations || 12)) {
      return eliminationResult(state);
    }
    const holders = state.unitOrder.filter((unitId) => {
      const unit = state.units[unitId];
      return (
        unit.alive &&
        unit.teamId === (params.teamId || "player") &&
        (params.tiles || []).some((tile) => tile.x === unit.x && tile.y === unit.y)
      );
    });
    return {
      finished: true,
      winner: holders.length ? params.teamId || "player" : params.opposingTeamId || "foe"
    };
  }
};


/** Generic multi-phase objective. Each phase delegates to a data-described
 * objective check and advances only when the player completes that phase. */
function evaluateObjectivePhase(state, phase, rootParams) {
  const params = { ...(rootParams || {}), ...((phase && phase.params) || {}) };
  const player = params.teamId || (rootParams && rootParams.teamId) || "player";
  const foe = params.opposingTeamId || (rootParams && rootParams.opposingTeamId) || "foe";
  if (!teamAlive(state, player)) return { complete: false, failed: true, winner: foe };
  if (!phase) return { complete: true, failed: false, winner: player };
  if (phase.type === "destroyTargets") {
    const remaining = (params.unitIds || []).filter((id) => state.units[id] && state.units[id].alive);
    return { complete: remaining.length === 0, failed: false, winner: player };
  }
  if (phase.type === "reachExtraction") {
    const unitIds = params.unitIds || state.unitOrder.filter((id) => state.units[id].teamId === player);
    const complete = unitIds.some((id) => {
      const unit = state.units[id];
      return unit && unit.alive && (params.tiles || []).some((tile) => tile.x === unit.x && tile.y === unit.y);
    });
    if (complete) return { complete: true, failed: false, winner: player };
    if (params.allowElimination && !teamAlive(state, foe)) return { complete: true, failed: false, winner: player };
    return { complete: false, failed: false, winner: null };
  }
  if (phase.type === "surviveActivations") {
    return { complete: state.activationCount >= (params.activations || 12), failed: false, winner: player };
  }
  if (phase.type === "holdPosition") {
    if (state.activationCount < (params.activations || 12)) return { complete: false, failed: false, winner: null };
    const complete = state.unitOrder.some((id) => {
      const unit = state.units[id];
      return unit.alive && unit.teamId === player && (params.tiles || []).some((tile) => tile.x === unit.x && tile.y === unit.y);
    });
    return { complete, failed: !complete, winner: complete ? player : foe };
  }
  if (phase.type === "protectUnits") {
    const failed = (params.unitIds || []).some((id) => !state.units[id] || !state.units[id].alive);
    if (failed) return { complete: false, failed: true, winner: foe };
    return { complete: !teamAlive(state, foe), failed: false, winner: player };
  }
  if (phase.type === "defeatAllEnemies") {
    return { complete: !teamAlive(state, foe), failed: false, winner: player };
  }
  return { complete: false, failed: true, winner: foe };
}

OBJECTIVE_HANDLERS.phasedObjective = function phasedObjective(state) {
  const params = objectiveParams(state);
  const phases = params.phases || [];
  const progress = state.objectiveState.progress || (state.objectiveState.progress = {});
  const phaseIndex = progress.phaseIndex || 0;
  const phase = phases[phaseIndex];
  const result = evaluateObjectivePhase(state, phase, params);
  if (result.failed) return { finished: true, winner: result.winner || params.opposingTeamId || "foe" };
  if (!result.complete) return { finished: false, winner: null };
  if (phaseIndex >= phases.length - 1) return { finished: true, winner: result.winner || params.teamId || "player" };
  progress.phaseIndex = phaseIndex + 1;
  progress.completedPhaseIds = (progress.completedPhaseIds || []).concat(phase.id || String(phaseIndex));
  logLine(state, "objectivePhaseChanged", "Objective phase advanced to " + (phases[phaseIndex + 1].id || (phaseIndex + 2)), {
    fromIndex: phaseIndex,
    toIndex: phaseIndex + 1,
    fromId: phase.id || String(phaseIndex),
    toId: phases[phaseIndex + 1].id || String(phaseIndex + 1)
  });
  return { finished: false, winner: null };
};

markEliminationObjectives(OBJECTIVE_HANDLERS, ["defeatAllEnemies"]);

/**
 * Evaluates one entry of the script-owned objective stack in isolation, by
 * temporarily pointing the legacy objective slot at it. Every handler reads
 * `objectiveParams(state)` and `state.objectiveState.progress`, so this reuses
 * all six objective types without duplicating any of them.
 */
function evaluateObjectiveEntry(state, entry) {
  const handler = OBJECTIVE_HANDLERS[entry.objectiveId];
  if (!handler) {
    state.errors.push("No handler for objective: " + entry.objectiveId);
    return { finished: false, winner: null };
  }
  if (!entry.progress) entry.progress = {};
  const saved = state.objectiveState;
  state.objectiveState = {
    ...saved,
    objectiveId: entry.objectiveId,
    params: entry.params,
    progress: entry.progress
  };
  let result;
  try {
    result = handler(state);
  } finally {
    entry.progress = state.objectiveState.progress;
    state.objectiveState = saved;
  }
  return result;
}

/**
 * Resolves the script-owned objective stack. An entry completes when its
 * handler declares the player team the winner and fails when it declares the
 * opposition. Victory needs every required entry complete; one failed required
 * entry loses the mission.
 */
function checkObjectiveStack(state) {
  const entries = state.objectiveState.entries || [];
  const rootParams = state.objectiveState.params || {};
  const playerTeamId = rootParams.teamId || "player";
  const opposingTeamId = rootParams.opposingTeamId || "foe";

  if (!teamAlive(state, playerTeamId)) return { finished: true, winner: opposingTeamId };

  let required = 0;
  let complete = 0;
  for (const entry of entries) {
    if (entry.status === "failed") {
      if (entry.required) return { finished: true, winner: opposingTeamId };
      continue;
    }
    if (entry.required) required += 1;
    if (entry.status === "complete") {
      if (entry.required) complete += 1;
      continue;
    }
    const result = evaluateObjectiveEntry(state, entry);
    if (!result.finished) continue;
    const entryPlayerTeamId = (entry.params && entry.params.teamId) || playerTeamId;
    if (result.winner === entryPlayerTeamId) {
      entry.status = "complete";
      logLine(state, "objectiveCompleted", "Objective complete: " + (entry.text || entry.ref), {
        objectiveRef: entry.ref
      });
      if (state.mission) state.mission.inbox.push({ type: "objectiveCompleted", objectiveRef: entry.ref });
      if (entry.required) complete += 1;
    } else if (result.winner) {
      entry.status = "failed";
      logLine(state, "objectiveFailed", "Objective failed: " + (entry.text || entry.ref), {
        objectiveRef: entry.ref
      });
      if (state.mission) state.mission.inbox.push({ type: "objectiveFailed", objectiveRef: entry.ref });
      if (entry.required) return { finished: true, winner: opposingTeamId };
    }
  }

  if (required > 0 && complete >= required) {
    // Completing the last required objective only wins the battle once the
    // mission script has nothing left to say. Otherwise a phase-one objective
    // like "survive the interception" would end Grayfield at the exact moment
    // it is supposed to hand over to the betrayal phase. The script gets to
    // replace the objectives first; executeCommand re-checks immediately after.
    if (missionScriptBusy(state)) return { finished: false, winner: null };
    return { finished: true, winner: playerTeamId };
  }
  return { finished: false, winner: null };
}

/** True while the mission runtime still has events, queued beats or a scene in
 *  flight. Victory and defeat both wait for it. */
function missionScriptBusy(state) {
  const runtime = state.mission;
  if (!runtime) return false;
  return !!(
    runtime.wait ||
    runtime.pending ||
    runtime.queue.length ||
    runtime.inbox.length
  );
}

function checkObjectives(state, onEvent) {
  if (state.finished) return state;

  let result;
  if ((state.objectiveState.entries || []).length) {
    result = checkObjectiveStack(state);
  } else {
    const handler = OBJECTIVE_HANDLERS[state.objectiveState.objectiveId];
    if (!handler) {
      state.errors.push("No handler for objective: " + state.objectiveState.objectiveId);
      return state;
    }
    result = handler(state);
  }

  if (result.finished) {
    state.finished = true;
    state.winner = result.winner;
    state.activeUnitId = null;
    state.activation = null;
    queueEvent(state, { type: "battleEnded", winner: result.winner });
    processAllEvents(state, onEvent);
  }
  return state;
}
/* ---------------------------------------------------------------
 * MISSION SCRIPTING BRIDGE
 *
 * The mission runtime (src/mission/) is engine-agnostic: it knows about
 * phases, triggers and actions but nothing about this file. Everything it
 * needs from the simulation arrives through this adapter, which is the only
 * place the two halves meet.
 *
 * Every simulation-authority action routes to the same machinery ordinary
 * gameplay uses — resolveEffects, the event queue, the pathfinder — so a
 * scripted attack produces real damage, real defeat events and real log lines,
 * and shows up identically in a save.
 * -------------------------------------------------------------*/

const MISSION_ENGINE = {
  resolveEffects(state, options) {
    resolveEffects(state, options);
  },

  processEvents(state) {
    processAllEvents(state);
  },

  queueEvent(state, event) {
    queueEvent(state, event);
  },

  logLine(state, type, text, data) {
    logLine(state, type, text, data);
  },

  unitStats(state, unitId) {
    return calculateUnitStats(state, unitId);
  },

  unitTags(state, unitId) {
    const unit = state.units[unitId];
    if (!unit) return [];
    const definition = CONTENT.units[unit.definitionId];
    return (definition && definition.tags) || [];
  },

  isWalkable(state, x, y) {
    const map = getMap(state);
    return inBounds(map, x, y) && isWalkable(map, x, y, state);
  },

  /**
   * Pathfinding for a scripted move.
   *
   * Ordinary pathfinding is capped by the unit's per-turn movement allowance,
   * which is right for a player order and wrong for a cinematic: Reyes
   * crossing the field to reach Vale is not a normal move. The budget is
   * raised to the engine's path-length ceiling, so terrain, elevation and
   * blocking rules all still apply — only the turn allowance is lifted.
   */
  findPath(state, unitId, target) {
    return findPath(state, unitId, target, { budget: GAME_CONFIG.grid.maxPathLength });
  },

  /**
   * Scripted movement along a real path. Emits the same `unitMoved` event a
   * player move does, so region triggers, facing and the renderer all behave
   * exactly as they would for a normal move.
   */
  moveUnitAlongPath(state, unitId, path) {
    const unit = state.units[unitId];
    if (!unit || !path || path.length < 2) return false;
    const startFacing = normalizeFacing(unit.facing);
    const stepFacings = path.slice(1).map((tile, index) => facingFromTiles(path[index], tile, startFacing));
    const finalFacing = stepFacings.length ? stepFacings[stepFacings.length - 1] : startFacing;
    queueEvent(state, {
      type: "unitMoved",
      unitId,
      from: { x: path[0].x, y: path[0].y },
      to: { x: path[path.length - 1].x, y: path[path.length - 1].y },
      path: path.map((tile) => ({ x: tile.x, y: tile.y })),
      tiles: path.length - 1,
      startFacing,
      stepFacings,
      scripted: true
    });
    if (finalFacing !== startFacing) {
      queueEvent(state, { type: "facingChanged", unitId, from: startFacing, to: finalFacing, reason: "movement" });
    }
    return true;
  },

  /** Direct placement, used when no legal path exists. Goes through the same
   *  teleport effect ordinary abilities use. */
  teleportUnit(state, unitId, tile) {
    const unit = state.units[unitId];
    if (!unit) return false;
    queueEvent(state, {
      type: "unitTeleported",
      unitId,
      from: { x: unit.x, y: unit.y },
      to: { x: tile.x, y: tile.y },
      scripted: true
    });
    return true;
  },

  spawnUnit(state, spec) {
    if (state.spawnCount >= GAME_CONFIG.limits.maxSpawnedUnits) {
      state.errors.push("Spawn limit reached; scripted group was not placed.");
      return null;
    }
    if (!CONTENT.units[spec.definitionId]) {
      state.errors.push("Scripted spawn used unknown chassis: " + spec.definitionId);
      return null;
    }
    const unit = createRuntimeUnit(state, {
      definitionId: spec.definitionId,
      teamId: spec.teamId,
      x: spec.x,
      y: spec.y,
      facing: spec.facing || null,
      aiProfileId: spec.aiProfile || null,
      ref: spec.ref || null,
      groupId: spec.groupId || null,
      dormant: spec.dormant === true
    });
    state.units[unit.id] = unit;
    state.unitOrder.push(unit.id);
    state.spawnCount += 1;
    // Stats need the unit to be in state, and a reinforcement must not act the
    // instant it lands — it waits one full recovery like anything else.
    const spawnStats = calculateUnitStats(state, unit.id);
    unit.currentHp = Math.max(0, Math.min(unit.currentHp, spawnStats.maxHp));
    unit.alive = unit.currentHp > 0;
    unit.nextActionTime =
      state.currentTime + FORMULAS.timeline.recoveryDelay(spawnStats.speed, FORMULAS.timeline.baseRecovery);
    ensureFaction(state.factions, unit.teamId, state.teams.map((team) => team.id), "hostile");
    queueEvent(state, {
      type: "unitDeployed",
      unitId: unit.id,
      tile: { x: unit.x, y: unit.y },
      groupId: unit.groupId
    });
    return unit.id;
  },

  setTerrain(state, x, y, terrainId) {
    const map = getMap(state);
    if (!inBounds(map, x, y)) return false;
    if (!CONTENT.terrains[terrainId]) {
      state.errors.push("Scripted terrain change used unknown terrain: " + terrainId);
      return false;
    }
    queueEvent(state, {
      type: "terrainCreated",
      tile: { x, y },
      terrainId,
      sourceUnitId: null,
      scripted: true
    });
    return true;
  },

  /**
   * Moves a unit to another team in place. No despawn, no replacement: HP,
   * statuses, position, facing, equipment and timeline slot all survive. This
   * is what lets Kell and Reyes defect mid-battle and keep the damage they
   * took while hostile.
   */
  /** Combat links are battle state, so mission scripting toggles them the
   *  same way it toggles anything else authoritative. */
  setLinkState(state, linkId, options) {
    return setLinkStateById(state, reactionDeps(), linkId, options || {});
  },

  setUnitTeam(state, unitId, teamId) {
    const unit = state.units[unitId];
    if (!unit || unit.teamId === teamId) return;
    const from = unit.teamId;
    unit.teamId = teamId;
    ensureFaction(state.factions, teamId, state.teams.map((team) => team.id), "hostile");
    logLine(state, "unitChangedTeam", unitLabel(state, unitId) + " changes allegiance to " + teamId, {
      unitId,
      from,
      to: teamId
    });
    queueEvent(state, { type: "unitChangedTeam", unitId, from, to: teamId });
    refreshReactionLinks(state);
    // Deliberately no knowledge transfer. A defector brings themselves, not
    // their old side's map; a betrayal that is meant to come with the dossier
    // is an explicit `shareKnowledge` beat, which is the moment an author
    // wants to control anyway.
  },

  /* ---- knowledge ---- */

  setKnowledge(state, factionId, unitIds, next, options) {
    if (!state.perception) return 0;
    let changed = 0;
    for (const unitId of unitIds) {
      const unit = state.units[unitId];
      if (!unit) continue;
      const atLastKnown = options && options.atLastKnown;
      const existing = knowledgeOf(state.perception, factionId, unitId);
      const position =
        atLastKnown && existing && existing.x != null
          ? { x: existing.x, y: existing.y }
          : { x: unit.x, y: unit.y };
      const change = setKnowledge(state.perception, factionId, unitId, next, {
        activation: (state.perception.factions[factionId] || {}).clock || 0,
        x: position.x,
        y: position.y,
        accuracy: next === "acquired" ? "exact" : "approximate",
        channels: ["intel"],
        source: "script"
      });
      if (change) {
        changed += 1;
        queueEvent(state, {
          type: "knowledgeChanged",
          factionId,
          unitId,
          from: change.from,
          to: change.to,
          reason: "script",
          x: change.record.x,
          y: change.record.y
        });
      }
    }
    return changed;
  },

  shareKnowledge(state, fromFactionId, toFactionId, options) {
    if (!state.perception) return 0;
    const changes = shareKnowledge(state.perception, fromFactionId, toFactionId, {
      activation: (state.perception.factions[toFactionId] || {}).clock || 0,
      unitIds: (options && options.unitIds) || null,
      maxState: (options && options.maxState) || "acquired"
    });
    for (const change of changes) {
      queueEvent(state, {
        type: "knowledgeChanged",
        factionId: toFactionId,
        unitId: change.unitId,
        from: change.from,
        to: change.to,
        reason: "shared",
        x: change.record.x,
        y: change.record.y
      });
    }
    return changes.length;
  },

  emitSignature(state, unitIds, channel, options) {
    if (!state.perception) return 0;
    let changed = 0;
    for (const unitId of unitIds) {
      if (!state.units[unitId]) continue;
      if (
        emitSignature(state.perception, unitId, channel, {
          activation: state.activationCount,
          strength: (options && options.strength) == null ? 1 : options.strength,
          duration: (options && options.duration) == null ? 1 : options.duration
        })
      ) {
        changed += 1;
      }
    }
    // Sweep immediately: a vent that lights someone up should be seen in the
    // same beat that opened it, not on whatever event happens to come next.
    if (changed) refreshPerception(state, perceptionDeps());
    return changed;
  },

  /** A scripted attack resolved through the real damage pipeline. */
  scriptedAttack(state, options) {
    const { sourceUnitId, targetUnitIds, abilityId } = options;
    const ability = abilityId ? CONTENT.abilities[abilityId] : null;

    if (ability) {
      // Prefer the authored ability so the shot uses its real numbers, effects
      // and presentation profile.
      queueEvent(state, {
        type: "abilityUsed",
        sourceUnitId,
        abilityId,
        target: (() => {
          const target = state.units[targetUnitIds[0]];
          return target ? { x: target.x, y: target.y } : null;
        })(),
        targetUnitIds: targetUnitIds.slice(),
        scripted: true
      });
      processAllEvents(state);
      return;
    }

    // No ability named: a plain authored hit, still through resolveEffects so
    // shields, statuses, defeat and wreck events all behave normally.
    const power = options.power == null ? 999 : options.power;
    resolveEffects(state, {
      sourceUnitId,
      targetUnitIds,
      effects: [
        {
          type: "damage",
          formula: options.formula || "physical",
          power,
          canMiss: false,
          ignoresShields: options.lethal === true
        }
      ]
    });
    processAllEvents(state);
  },

  /** A scripted repair resolved through the real heal pipeline. */
  scriptedRepair(state, options) {
    const { sourceUnitId, targetUnitIds, abilityId } = options;
    if (abilityId && CONTENT.abilities[abilityId]) {
      queueEvent(state, {
        type: "abilityUsed",
        sourceUnitId,
        abilityId,
        target: (() => {
          const target = state.units[targetUnitIds[0]];
          return target ? { x: target.x, y: target.y } : null;
        })(),
        targetUnitIds: targetUnitIds.slice(),
        scripted: true
      });
      processAllEvents(state);
      return;
    }
    resolveEffects(state, {
      sourceUnitId,
      targetUnitIds,
      effects: [{ type: "heal", formula: "flat", power: options.amount == null ? 40 : options.amount }]
    });
    processAllEvents(state);
  }
};

/* ---------------------------------------------------------------
 * MID-MISSION SAVE (SAV-01)
 *
 * Battle state is plain serializable data by construction — the architecture
 * audit already forbids live references and definitions inside runtime units —
 * so a save is a JSON round-trip plus a version stamp and a guard that the
 * content it refers to still exists.
 *
 * What this covers, per GDD §12.1: RNG state and counter, the timeline and the
 * active unit, terrain overrides, delayed effects, faction relationships, the
 * objective stack with its per-entry progress, and the whole mission runtime —
 * current phase, mission facts, fired-once counters, group states, the pending
 * beat with its action index, and any scene the battle is suspended on.
 *
 * That last part is what makes a reload safe: a one-time cinematic is recorded
 * as fired *before* its actions run, so reloading a save taken after the beat
 * never replays it, and a save taken mid-beat resumes at the exact action.
 * -------------------------------------------------------------*/

const BATTLE_SAVE_VERSION = 1;

function serializeBattle(state) {
  return JSON.stringify({
    version: BATTLE_SAVE_VERSION,
    savedAt: state.currentTime,
    state
  });
}

function deserializeBattle(serialized) {
  const parsed = typeof serialized === "string" ? JSON.parse(serialized) : serialized;
  if (!parsed || parsed.version !== BATTLE_SAVE_VERSION) return null;
  const state = parsed.state;
  if (!state || !CONTENT.encounters[state.encounterId]) return null;
  if (!CONTENT.maps[state.mapId]) return null;

  // Fields added by a later engine version must not be undefined on an older
  // save, or the first thing that touches them throws.
  if (!state.factions) {
    state.factions = createFactionState(state.teams.map((team) => team.id), null);
  }
  if (!state.objectiveState.entries) state.objectiveState.entries = [];
  if (!state.reactions) {
    // A save from before reactions existed loads with an empty economy rather
    // than being rejected.
    state.reactions = createReactionState(REACTION_CONTENT, { autoResolve: true });
    state.autoResolveReactions = true;
  }
  if (!state.perception || state.perception.version !== PERCEPTION_VERSION) {
    // A save from before knowledge existed — or from an incompatible knowledge
    // version — reloads with full information rather than being rejected. The
    // first sweep after the reload re-derives the truth anyway; what is lost is
    // only the *memory* of contacts nobody can currently see.
    state.perception = createPerception(state.teams.map((team) => team.id), { enabled: false });
  }
  if (!state.terrainOverrides) state.terrainOverrides = {};
  if (!state.delayedEffects) state.delayedEffects = [];
  if (!state.errors) state.errors = [];
  // Fixtures are plain data, so the save carries them as-is; this only
  // re-establishes the shape for a save taken before they existed, and
  // rebuilds the id counter so a reload cannot mint an id already in use.
  state.fixtures = deserializeFixtures(state.fixtures);
  // Same contract as fixtures: plain data, carried as-is, re-shaped only for a
  // save taken before it existed. A save made while a declaration was open
  // reloads with that declaration still open and its verdict intact.
  state.interventions = deserializeInterventions(state.interventions);
  // Carried, never re-derived. A permutation is precisely the thing timestamps
  // cannot express, so reconstructing it from them would quietly change the
  // remaining order across a reload.
  state.sequencing = deserializeSequencing(state.sequencing);
  for (const id of state.unitOrder) {
    const unit = state.units[id];
    if (unit.ref == null) unit.ref = id;
    if (unit.dormant == null) unit.dormant = false;
    if (unit.groupId === undefined) unit.groupId = null;
  }

  // The compiled script is not stored in the save — it is content, and content
  // changes between builds. It is re-attached by id here.
  if (state.mission && state.missionScriptId) {
    const script = MISSION_SCRIPTS[state.missionScriptId] || MISSION_CONTENT.scriptsByEncounter[state.encounterId];
    if (script) registerMissionScript(script);
  }
  return state;
}

/* ---------------------------------------------------------------
 * PERCEPTION BRIDGE
 *
 * The knowledge system (src/perception/) knows about channels, contacts and
 * decay, and nothing about this file. Everything it needs from the simulation
 * arrives through this adapter — including line of sight, which is the
 * engine's existing implementation rather than a second, disagreeing one.
 *
 * The adapter is the *only* path by which the knowledge model reads a true
 * coordinate. Nothing downstream of it can.
 * -------------------------------------------------------------*/

/** Chassis + equipment + statuses, composed into one sensor suite. */
function sensorProfileFor(state, unitId) {
  const unit = state.units[unitId];
  if (!unit) return DEFAULT_SENSOR_PROFILE;
  const channels = {};
  for (const channelId of CHANNEL_ORDER) {
    const base = DEFAULT_SENSOR_PROFILE.channels[channelId];
    channels[channelId] = { range: base ? base.range : 0 };
  }

  // The best sensor wins rather than stacking: two pairs of binoculars do not
  // see twice as far, and a max keeps the composition order-independent.
  const contribute = (profile) => {
    if (!profile) return;
    for (const channelId of Object.keys(profile.sensors || {})) {
      if (!channels[channelId]) channels[channelId] = { range: 0 };
      channels[channelId].range = Math.max(channels[channelId].range, profile.sensors[channelId].range);
    }
  };

  const definition = CONTENT.units[unit.definitionId];
  contribute(definition && definition.perception);
  for (const item of equippedItems(state, unitId)) contribute(item.perception);
  for (const applied of unit.statuses) {
    const status = CONTENT.statuses[applied.statusId];
    contribute(status && status.perception);
  }
  return { channels };
}

/** Chassis + equipment + statuses, composed into what a unit gives off. */
function emissionProfileFor(state, unitId) {
  const unit = state.units[unitId];
  if (!unit) return DEFAULT_EMISSION_PROFILE;
  const emissions = { ...DEFAULT_EMISSION_PROFILE };

  // Emissions multiply, so a cloak that zeroes optical output stays zero no
  // matter what else is stacked on top of it.
  const contribute = (profile) => {
    if (!profile) return;
    for (const channelId of Object.keys(profile.emissions || {})) {
      const current = emissions[channelId] == null ? 0 : emissions[channelId];
      emissions[channelId] = current * profile.emissions[channelId];
    }
  };

  const definition = CONTENT.units[unit.definitionId];
  contribute(definition && definition.perception);
  for (const item of equippedItems(state, unitId)) contribute(item.perception);
  for (const applied of unit.statuses) {
    const status = CONTENT.statuses[applied.statusId];
    contribute(status && status.perception);
  }
  return emissions;
}

const PERCEPTION_ENGINE = {
  unitIds(state) {
    return state.unitOrder;
  },

  unit(state, unitId) {
    return state.units[unitId] || null;
  },

  teamRelationship(state, teamId, otherUnitId) {
    const other = state.units[otherUnitId];
    if (!other) return "neutral";
    return relationshipBetween(state.factions, teamId, other.teamId);
  },

  /**
   * Reciprocal line of sight.
   *
   * The engine's Bresenham walk is directional — it breaks diagonal ties in
   * the order it happens to step, so A can have a clear line to B while B does
   * not have one back. That never mattered while sight was only used to
   * validate an attacker's shot, but as the basis of *seeing* it produces
   * one-way visibility and genuine stalemates: a unit that is permanently
   * observed by an enemy it can never acquire.
   *
   * Sight is reciprocal, so perception tests both directions. Targeting keeps
   * using the existing directional check unchanged; the two are allowed to
   * differ, and the AI simply repositions until its shot is also legal.
   */
  lineOfSight(state, from, to) {
    const map = CONTENT.maps[state.mapId];
    return hasLineOfSight(map, from, to, state) || hasLineOfSight(map, to, from, state);
  },

  distance(a, b) {
    return gridDistance(a, b);
  },

  /** Concealment is the existing status-flag model, not a parallel one. */
  concealedFrom(state, unitId, viewerTeamId) {
    return isUnitConcealed(state, unitId) || isUnitHiddenFrom(state, unitId, viewerTeamId);
  },

  sensorProfile(state, unitId) {
    return sensorProfileFor(state, unitId);
  },

  emissionProfile(state, unitId) {
    return emissionProfileFor(state, unitId);
  },

  /**
   * How loud one event was for one unit.
   *
   * Content decides: an ability tagged `silent` makes no noise, one tagged
   * `loud` makes more. No ability id appears here.
   */
  signatureScale(state, unitId, event) {
    if (!event || !event.abilityId) return 1;
    const ability = CONTENT.abilities[event.abilityId];
    if (!ability) return 1;
    const tags = ability.tags || [];
    if (tags.includes("silent")) return 0;
    if (tags.includes("loud")) return 2;
    return 1;
  },

  activationIndex(state) {
    return state.activationCount;
  },

  queueEvent(state, event) {
    queueEvent(state, event);
  }
};

const PERCEPTION_DEPS = { engine: PERCEPTION_ENGINE };

function perceptionDeps() {
  return PERCEPTION_DEPS;
}

/** May this faction legitimately act against this unit right now? */
function canPerceptionTarget(state, factionId, unitId) {
  return factionCanActOn(state, perceptionDeps(), factionId, unitId);
}

/**
 * Units the mission itself names as targets, and the faction it names them to.
 *
 * Generic: any objective — root or phased — that carries `unitIds` is read as
 * a briefing. No objective type, unit id or mission id is special-cased.
 */
function briefedObjectiveTargets(state) {
  const params = objectiveParams(state);
  const teamId = params.teamId;
  if (!teamId) return null;
  const unitIds = [];
  const collect = (entry) => {
    for (const id of (entry && entry.unitIds) || []) {
      if (!unitIds.includes(id)) unitIds.push(id);
    }
  };
  collect(params);
  for (const phase of params.phases || []) collect({ ...params, ...(phase.params || {}) });
  return unitIds.length ? { teamId, unitIds } : null;
}

/**
 * Turns the mission briefing into knowledge.
 *
 * Being ordered to destroy something implies being told where it is. The
 * contact is SUSPECTED, not acquired — the squad still has to go and look
 * before it can shoot — and it is a snapshot: a briefed unit that walks away
 * leaves the briefing pointing at empty ground, which is correct.
 */
function grantObjectiveIntel(state) {
  if (!state.perception || !state.perception.enabled) return;
  const briefing = briefedObjectiveTargets(state);
  if (!briefing) return;
  for (const unitId of briefing.unitIds) {
    const unit = state.units[unitId];
    if (!unit || !unit.alive) continue;
    if (relationshipBetween(state.factions, briefing.teamId, unit.teamId) !== "hostile") continue;
    if (knowledgeStateOf(state.perception, briefing.teamId, unitId) !== "unseen") continue;
    setKnowledge(state.perception, briefing.teamId, unitId, "suspected", {
      x: unit.x,
      y: unit.y,
      accuracy: "approximate",
      channels: ["intel"],
      source: "briefing",
      persistent: true
    });
  }
}

/**
 * The opening briefing.
 *
 * Every faction starts knowing roughly where the other side came down — you do
 * not walk into an engagement with no idea which direction it is in. This is
 * an *area*, taken once at deployment: it cannot be targeted, it never
 * updates, and within a few activations of contact the real records have taken
 * over entirely. It exists so a faction that has lost every contact advances
 * and sweeps instead of standing on a completely flat scoring surface.
 */
function seedSearchAnchors(state) {
  if (!state.perception || !state.perception.enabled) return;
  for (const team of state.teams) {
    let sumX = 0;
    let sumY = 0;
    let count = 0;
    for (const id of state.unitOrder) {
      const other = state.units[id];
      if (!other.alive) continue;
      if (relationshipBetween(state.factions, team.id, other.teamId) !== "hostile") continue;
      sumX += other.x;
      sumY += other.y;
      count += 1;
    }
    if (!count) continue;
    setSearchAnchor(state.perception, team.id, {
      x: Math.round(sumX / count),
      y: Math.round(sumY / count)
    });
  }
}

/* ---------------------------------------------------------------
 * REACTION BRIDGE
 *
 * The reaction runtime (src/reactions/) knows about triggers, windows, links
 * and economies, and nothing about this file. Everything it needs from the
 * simulation arrives through this adapter.
 *
 * Reactions never call executeCommand: that path demands the unit be the
 * active unit and consumes its activation, which is precisely what an
 * out-of-turn response must not do. They route to the same effect and event
 * machinery instead, so a reaction attack is indistinguishable from a normal
 * one in the log, in a save, and in a replay.
 * -------------------------------------------------------------*/

/* ===============================================================
 * TRAJECTORY
 *
 * A route is planned and executed entirely through machinery that already
 * existed: `evaluateTraversalStep` decides every tile, and each segment is
 * applied as an ordinary `unitMoved` event. Normal movement is untouched — a
 * one-segment trajectory with no contacts is byte-identical to a plain move,
 * which is the property that lets this be additive rather than a rewrite.
 * =============================================================*/

/**
 * Whether a route ability has anywhere to start.
 *
 * One legal tile in any heading is enough — the planner decides the rest when
 * the player draws it. A frame boxed in on all sides genuinely cannot use a
 * route ability, which is the counterplay stated as a rule rather than a nerf.
 */
function trajectoryHasRunway(state, unitId, ability) {
  const rules = trajectoryRules(ability);
  return HEADING_IDS.some((heading) => {
    const plan = planUnitTrajectory(state, unitId, [{ heading, distance: 1 }], rules);
    return plan.legal && plan.totalDistance > 0;
  });
}

/** The engine adapter the planner asks about tiles. One legality model. */
function trajectoryDeps(state, unitId, options) {
  const opts = options || {};
  return {
    canEnter(from, to) {
      const step = evaluateTraversalStep(state, unitId, from, to, {
        movementPolicy: opts.movementPolicy || "normal",
        ignoresElevation: opts.ignoresElevation === true,
        ignoreOccupancy: opts.ignoreOccupancy === true
      });
      return { ok: step.valid, reason: step.errors[0] || null };
    },
    unitAt(tile) {
      const occupant = unitAt(state, tile.x, tile.y, unitId);
      return occupant ? occupant.id : null;
    }
  };
}

/**
 * Plans a route for a unit, through the engine's own rules.
 *
 * The single authority: execution, the player's preview and the tests all call
 * this. A preview that computed legality separately would eventually promise a
 * tile the engine then refuses, which is the worst kind of lie a tactics game
 * can tell.
 */
function planUnitTrajectory(state, unitId, segments, options) {
  const opts = options || {};
  const unit = state.units[unitId];
  if (!unit) return { legal: false, reason: "no such unit", segments: [], tiles: [], redirects: [] };
  const stats = calculateUnitStats(state, unitId);
  return planTrajectory(
    { x: unit.x, y: unit.y },
    segments,
    trajectoryDeps(state, unitId, opts),
    {
      maxSegments: opts.maxSegments,
      // A route is bounded by the mover's own movement unless the action says
      // otherwise. Acceleration is content's business, not the planner's.
      maxDistance: opts.maxDistance == null ? stats.movement : opts.maxDistance,
      allowedRedirects: opts.allowedRedirects,
      initialHeading: opts.initialHeading
    }
  );
}

/**
 * Everything an authored condition may read about a route in progress.
 *
 * Exposed as plain values rather than a formula language: content asks "was
 * the approach at least four tiles?", it does not write arithmetic.
 */
function trajectoryContextOf(state, unitId) {
  const context = state.trajectory;
  if (!context || context.unitId !== unitId) return null;
  return context;
}

/* ---------------------------------------------------------------
 * ROUTE PLANNING (the player's side)
 *
 * The preview is not a second implementation of anything. It calls
 * `planUnitTrajectory` for the route, `planDisplacement` for the shove and
 * `trajectoryResourceCost` for the price — the same three functions execution
 * calls, in the same order, with the same arguments. What it adds is names,
 * tile lists to draw, and the reason a segment is refused.
 * -------------------------------------------------------------*/

/** The ability, if it is one that flies a route. Content decides; nothing here
 *  keeps a list of which abilities are trajectories. */
function trajectoryAbility(abilityId) {
  const ability = abilityId ? CONTENT.abilities[abilityId] : null;
  return ability && ability.trajectory ? ability : null;
}

/**
 * The segment that reaches a clicked tile in a straight line, or null.
 *
 * A route is drawn one leg at a time: the player clicks where this leg ends,
 * and only tiles that lie on one heading from the current end qualify. That is
 * the whole input model — no dragging, no waypoint solver, no second
 * pathfinder to disagree with the first.
 */
function straightSegmentTo(from, tile) {
  if (!from || !tile) return null;
  const dx = tile.x - from.x;
  const dy = tile.y - from.y;
  if (!dx && !dy) return null;
  if (dx && dy && Math.abs(dx) !== Math.abs(dy)) return null;
  const step = headingBetween(from, {
    x: from.x + Math.sign(dx),
    y: from.y + Math.sign(dy)
  });
  if (!step) return null;
  return { heading: step.id, distance: Math.max(Math.abs(dx), Math.abs(dy)) };
}

/** Where a route currently ends, which is where the next leg starts. */
function routeEndpoint(state, unitId, segments) {
  const unit = state.units[unitId];
  if (!unit) return null;
  if (!segments || !segments.length) return { x: unit.x, y: unit.y };
  const plan = planUnitTrajectory(state, unitId, segments, {});
  const last = plan.segments[plan.segments.length - 1];
  return last ? { ...last.to } : { x: unit.x, y: unit.y };
}

/**
 * Everything the route preview needs, from the authorities that will run it.
 *
 * `candidate` is the leg the pointer is currently over. It is appended to the
 * committed segments before planning, so the player sees the route they would
 * get rather than the route they have.
 */
function createRoutePlanModel(state, input, candidate) {
  const unitId = input.selectedUnitId || state.activeUnitId;
  const ability = trajectoryAbility(input.selectedAbilityId);
  if (!unitId || !ability || !state.units[unitId]) return null;

  const rules = trajectoryRules(ability);
  const committed = input.routeSegments || [];
  const segments = candidate ? committed.concat([candidate]) : committed;
  const plan = planUnitTrajectory(state, unitId, segments, rules);
  const cost = trajectoryResourceCost(state, unitId, ability, plan);

  const resource = cost.definition
    ? resourceEntry(state, cost.definition, cost.owner)
    : null;
  const contacts = [];
  const displacementTiles = [];
  for (const segment of plan.segments) {
    if (!segment.contact) continue;
    contacts.push(describeRouteContact(state, unitId, ability, segment, displacementTiles));
  }

  return {
    unitId,
    abilityId: input.selectedAbilityId,
    abilityName: ability.name,
    empty: !segments.length,
    candidate: candidate || null,
    committedCount: committed.length,
    maxSegments: rules.maxSegments,
    maxDistance: rules.maxDistance == null ? calculateUnitStats(state, unitId).movement : rules.maxDistance,
    legal: plan.legal,
    reason: plan.reason,
    distance: plan.totalDistance,
    origin: plan.origin,
    endpoint: plan.endpoint,
    tiles: plan.tiles,
    segments: plan.segments.map((segment) => ({
      index: segment.index,
      heading: segment.heading,
      distance: segment.distance,
      requestedDistance: segment.requestedDistance,
      redirect: segment.redirect,
      from: segment.from,
      to: segment.to,
      blocked: segment.blocked,
      blockReason: segment.blockReason,
      blockTile: segment.blockTile,
      contact: segment.contact || null
    })),
    redirectTiles: (plan.redirects || [])
      .filter((redirect) => redirect.category !== "straight")
      .map((redirect) => ({ ...redirect.tile, category: redirect.category })),
    redirects: redirectTally(plan),
    contacts,
    displacementTiles,
    blockTile: (plan.segments.find((segment) => segment.blocked) || {}).blockTile || null,
    cost: {
      resourceId: cost.resourceId || null,
      resourceName: cost.definition ? cost.definition.name || cost.definition.id : null,
      amount: cost.amount || 0,
      breakdown: cost.breakdown || [],
      affordable: cost.ok !== false,
      reason: cost.ok === false ? cost.reason : null,
      available: resource ? resource.current : null,
      remaining: resource ? resource.current - (cost.amount || 0) : null
    }
  };
}

/** One contact on the route: who is hit, and exactly where they end up. */
function describeRouteContact(state, unitId, ability, segment, displacementTiles) {
  const contact = segment.contact;
  const targetId =
    contact.targetUnitId ||
    (contact.targetRef
      ? state.unitOrder.find((id) => state.units[id].ref === contact.targetRef)
      : null);
  const target = targetId ? state.units[targetId] : null;
  const effects = (ability.trajectory && ability.trajectory.contactEffects) || [];
  const displaceEffect = effects.find((effect) => effect.type === "displace") || null;
  const maximum = displaceEffect ? (displaceEffect.distance == null ? 1 : displaceEffect.distance) : 0;

  const record = {
    segment: segment.index,
    targetUnitId: targetId || null,
    targetName: target ? CONTENT.units[target.definitionId].name : "—",
    tile: target ? { x: target.x, y: target.y } : null,
    inReach: false,
    reachReason: null,
    maxDisplacement: maximum,
    displacement: null
  };
  if (!target || !target.alive) {
    record.reachReason = "no target";
    return record;
  }
  // Reach is measured from where the frame ends the segment, which is the
  // same tile the executing code measures from.
  const reach = contact.range == null ? 1 : contact.range;
  record.inReach = gridDistance(segment.to, target) <= reach;
  if (!record.inReach) record.reachReason = "out of reach at that point on the route";
  if (!displaceEffect || !contact.displace) return record;

  const wanted = contact.displace.distance == null ? maximum : Number(contact.displace.distance);
  const distance = Math.max(0, Math.min(maximum, wanted));
  const shove = planDisplacement(
    { x: target.x, y: target.y },
    contact.displace.heading || displaceEffect.heading,
    distance,
    trajectoryDeps(state, targetId, {
      movementPolicy: displaceEffect.movementPolicy || "forced",
      ignoresElevation: displaceEffect.ignoresElevation === true
    }),
    {
      resistance: displaceEffect.ignoresResistance === true
        ? 0
        : calculateUnitStats(state, targetId).displacementResistance
    }
  );
  record.displacement = {
    heading: shove.heading,
    requested: shove.requested,
    actual: shove.actual,
    resisted: shove.resisted,
    blocked: shove.blocked,
    blockReason: shove.blockReason,
    endpoint: shove.endpoint
  };
  if (shove.actual) displacementTiles.push({ ...shove.endpoint });
  return record;
}

/* ===============================================================
 * PROPAGATION
 *
 * A chain is planned through the engine's own distance, sight and targeting
 * rules and resolved through the ordinary effect pipeline. Nothing here knows
 * what is arcing or why; the search lives in `src/combat/propagation.js` and
 * this half only answers its questions.
 * =============================================================*/

/** The authored rules for an ability's chain, with the engine's defaults. */
function propagationRules(ability) {
  const declared = (ability && ability.propagation) || {};
  return {
    maxHops: declared.maxHops == null ? 1 : declared.maxHops,
    hopRadius: declared.hopRadius == null ? 2 : declared.hopRadius,
    allowRepeat: declared.allowRepeat === true,
    includeSource: declared.includeSource === true,
    // Sight between nodes is its own question: an arc that needs a clear line
    // is a different mechanic from one that does not, and the ability that
    // aimed at the first target already had its own line-of-sight rule.
    requiresLineOfSight: declared.requiresLineOfSight === true,
    allowsDefeated: declared.allowsDefeated === true,
    relationship: declared.relationship || "enemy",
    selection: declared.selection || "nearest",
    filters: declared.filters || null
  };
}

/**
 * The engine adapter the chain planner asks about the battlefield.
 *
 * Every answer comes from something that already existed — `gridDistance`,
 * `hasLineOfSight`, `TARGET_FILTERS`, `passesTargetFilters`. There is no
 * second metric and no second sight model, which is what makes a planned arc
 * a claim the engine will honour rather than one the preview invented.
 *
 * Positions are read at call time, never captured. That is the property the
 * whole mechanic rests on: move an enemy two tiles and the next question about
 * that enemy has a different answer.
 */
function propagationDeps(state, sourceUnitId, abilityId, rules) {
  const map = getMap(state);
  const relationship = TARGET_FILTERS[rules.relationship];
  const tileOf = (unitId) => {
    const unit = state.units[unitId];
    return unit ? { x: unit.x, y: unit.y } : null;
  };
  return {
    nodes() {
      const out = [];
      for (const id of state.unitOrder) {
        const unit = state.units[id];
        if (!unit) continue;
        out.push({
          id,
          x: unit.x,
          y: unit.y,
          // The tie-break weight for policies that want the weakest target.
          weight: unit.currentHp
        });
      }
      return out;
    },

    distance(fromId, toId) {
      const from = tileOf(fromId);
      const to = tileOf(toId);
      if (!from || !to) return Infinity;
      return gridDistance(from, to);
    },

    connected(fromId, toId) {
      if (!rules.requiresLineOfSight) return true;
      const from = tileOf(fromId);
      const to = tileOf(toId);
      if (!from || !to) return false;
      return hasLineOfSight(map, from, to, state);
    },

    /**
     * How far this particular arc may reach.
     *
     * The authored radius plus whatever either end contributes. Because the
     * contribution is an ordinary stat, a status, a piece of equipment and a
     * perk all reach it through the pipeline that already composes them.
     */
    hopRadius(fromId, toId) {
      const from = calculateUnitStats(state, fromId);
      const to = calculateUnitStats(state, toId);
      return (
        rules.hopRadius +
        (from ? from.propagationRadiusBonus || 0 : 0) +
        (to ? to.propagationRadiusBonus || 0 : 0)
      );
    },

    eligible(unitId) {
      const unit = state.units[unitId];
      if (!unit) return { ok: false, reason: "no such unit" };
      if (!unit.alive && !rules.allowsDefeated) return { ok: false, reason: "already destroyed" };
      if (!relationship) return { ok: false, reason: 'unknown relationship "' + rules.relationship + '"' };
      if (!relationship(state, sourceUnitId, unit)) {
        return { ok: false, reason: "not a legal target for this action" };
      }
      if (isHostile(state, sourceUnitId, unitId) && isUnitConcealed(state, unitId)) {
        return { ok: false, reason: "cannot be detected" };
      }
      if (
        rules.filters &&
        !passesTargetFilters(state, rules.filters, { unit, sourceUnitId, abilityId })
      ) {
        return { ok: false, reason: "does not match this action's filters" };
      }
      return { ok: true, reason: null };
    }
  };
}

/**
 * Plans a chain for an ability, from live state.
 *
 * The single authority: execution, the player's preview, the forecast and the
 * tests all call this. A preview that computed the chain separately would
 * eventually promise an arc the engine then refuses, which is the same class
 * of lie the route planner exists to prevent.
 */
function planUnitPropagation(state, sourceUnitId, abilityId, initialTargetId) {
  const ability = abilityId ? CONTENT.abilities[abilityId] : null;
  const rules = propagationRules(ability);
  return planPropagation(
    sourceUnitId,
    initialTargetId,
    propagationDeps(state, sourceUnitId, abilityId, rules),
    rules
  );
}

/* ===============================================================
 * FIXTURES
 *
 * Authored definitions live in the gameplay registry; runtime instances live
 * in `state.fixtures` and are owned by `src/combat/fixtures.js`. This half is
 * the adapter: it decides eligibility using the engine's own relationship
 * rules, and it resolves activation through the ordinary effect pipeline.
 *
 * Nothing here knows what a mine is.
 * =============================================================*/

function fixtureDefinition(definitionId) {
  return (definitionId && CONTENT.fixtures[definitionId]) || null;
}

/**
 * Whether a unit walking onto a fixture sets it off.
 *
 * Relationship comes from the engine's existing faction rules, so a fixture
 * that is hostile to you is hostile for the same reason everything else is.
 * An author can widen it — a healing station triggers for allies — but the
 * default is the one that makes a mine a mine.
 */
function fixtureTriggeredBy(state, fixture, unitId) {
  if (!isArmed(fixture)) return false;
  const unit = state.units[unitId];
  if (!unit || !unit.alive) return false;
  const definition = fixtureDefinition(fixture.definitionId);
  if (!definition) return false;
  const trigger = definition.trigger || {};
  if (trigger.type !== "unitEnters") return false;

  // The owner does not step on their own mine unless the author says so.
  if (fixture.ownerUnitId === unitId && !trigger.includesOwner) return false;

  const relationship = trigger.triggeredBy || "enemy";
  if (relationship === "any") return true;
  if (!fixture.ownerTeamId) return relationship === "enemy";
  const ownerUnit = fixture.ownerUnitId ? state.units[fixture.ownerUnitId] : null;
  const reference = ownerUnit || { teamId: fixture.ownerTeamId };
  const hostile = relationshipBetween(state.factions, reference.teamId, unit.teamId) === "hostile";
  if (relationship === "enemy") return hostile;
  if (relationship === "ally") return !hostile;
  return false;
}

/**
 * Queues activation for every fixture waiting on a tile.
 *
 * Called from the movement handlers, so voluntary and forced movement reach it
 * by exactly the same route. There is deliberately no "was this a shove?"
 * branch: a mine cannot tell the difference and neither can this.
 */
function triggerFixturesAt(state, unitId, tile, resume) {
  const waiting = fixturesAtTile(state.fixtures, tile.x, tile.y, (fixture) =>
    fixtureTriggeredBy(state, fixture, unitId)
  );
  waiting.forEach((fixture, index) => {
    queueEvent(state, {
      type: "fixtureTriggered",
      fixtureId: fixture.id,
      definitionId: fixture.definitionId,
      unitId,
      sourceUnitId: fixture.ownerUnitId || null,
      ownerTeamId: fixture.ownerTeamId || null,
      tile: { x: tile.x, y: tile.y },
      activation: "automatic",
      // Rides on the last trigger so the rest of an interrupted walk resumes
      // only once everything waiting on this tile has finished with the mover.
      resume: index === waiting.length - 1 ? resume || null : null
    });
  });
  return waiting.length;
}

/**
 * The earliest point on a path where something is waiting.
 *
 * A mover crossing a mined tile has to set it off there rather than on
 * arrival, so the movement handlers ask this before applying the whole move
 * and stop at the answer. With no fixtures placed it is a scan of an empty
 * list and movement is unchanged, which is the property that makes this
 * additive rather than a rewrite.
 */
function firstFixtureContactOnPath(state, unitId, path) {
  if (!state.fixtures || !state.fixtures.order.length) return null;
  let earliest = null;
  for (const fixture of allFixtures(state.fixtures)) {
    if (!fixtureTriggeredBy(state, fixture, unitId)) continue;
    const contact = pathContact(fixture, path);
    if (!contact) continue;
    // Index 0 is where the mover already stood; it did not enter it.
    if (contact.index === 0) continue;
    if (!earliest || contact.index < earliest.index) earliest = contact;
  }
  return earliest;
}

/**
 * Resolves a fixture's authored activation.
 *
 * The effects are an ordinary effect list against ordinary area targeting, so
 * a charge that damages and shoves is the same machinery as an ability that
 * damages and shoves. Nothing about this is explosive.
 */
function resolveFixtureActivation(state, event) {
  const fixture = findFixture(state.fixtures, event.fixtureId);
  if (!fixture) return;
  const definition = fixtureDefinition(fixture.definitionId);
  if (!definition) {
    state.errors.push("Fixture references unknown definition: " + fixture.definitionId);
    return;
  }

  const centre = { x: fixture.x, y: fixture.y };
  const area = definition.area || { shape: "single" };
  const tiles = tilesInArea(state, centre, area, { sourceUnitId: fixture.ownerUnitId || null });
  const targets = [];
  for (const tile of tiles) {
    const occupant = unitAt(state, tile.x, tile.y);
    if (!occupant || !occupant.alive) continue;
    if (definition.affects === "enemy" && fixture.ownerTeamId) {
      if (relationshipBetween(state.factions, fixture.ownerTeamId, occupant.teamId) !== "hostile") {
        continue;
      }
    }
    if (definition.affects === "ally" && fixture.ownerTeamId) {
      if (relationshipBetween(state.factions, fixture.ownerTeamId, occupant.teamId) === "hostile") {
        continue;
      }
    }
    targets.push(occupant.id);
  }

  queueEvent(state, {
    type: "fixtureDetonated",
    fixtureId: fixture.id,
    definitionId: fixture.definitionId,
    sourceUnitId: fixture.ownerUnitId || null,
    ownerTeamId: fixture.ownerTeamId || null,
    tile: centre,
    tiles,
    targetUnitIds: targets,
    activation: event.activation || "automatic",
    triggeredByUnitId: event.unitId || null
  });
  processAllEvents(state);

  resolveEffects(state, {
    // Attribution stays with whoever placed it. A mine's damage belongs to its
    // owner, not to the ground, and the causal record already knew that.
    sourceUnitId: fixture.ownerUnitId || event.unitId,
    targetUnitIds: targets,
    targetTile: centre,
    affectedTiles: tiles,
    abilityId: null,
    effects: definition.effects || []
  });
  processAllEvents(state);

  const spent = consumeFixtureCharge(state.fixtures, fixture.id);
  queueEvent(state, {
    type: "fixtureSpent",
    fixtureId: fixture.id,
    definitionId: fixture.definitionId,
    ownerTeamId: fixture.ownerTeamId || null,
    consumed: !!spent.consumed,
    rearmed: !!spent.rearmed,
    remaining: spent.remaining == null ? null : spent.remaining,
    state: spent.fixture ? spent.fixture.state : "removed"
  });
}

/** The authored rules for an ability that activates fixtures, or null. */
function fixtureTargetingRules(ability) {
  const declared = ability && ability.fixtureTargeting;
  if (!declared) return null;
  return {
    // A tag rather than an id, so one ability can command a family of things
    // and a new member of that family is a content change.
    tag: declared.tag || null,
    ownership: declared.ownership || "own",
    states: declared.states || ["armed"],
    rangeMax: declared.rangeMax == null ? null : declared.rangeMax,
    requiresLineOfSight: declared.requiresLineOfSight === true
  };
}

/** Whether a unit may activate a given fixture under an ability's rules. */
function fixtureActivationEligibility(state, unitId, fixture, rules) {
  const unit = state.units[unitId];
  if (!unit) return { ok: false, reason: "Unknown unit." };
  if (!fixtureIsActive(fixture)) return { ok: false, reason: "That fixture is spent." };

  if (rules.ownership === "own" && fixture.ownerUnitId !== unitId) {
    return { ok: false, reason: "That is not your device." };
  }
  if (rules.ownership === "team") {
    if (!fixture.ownerTeamId || fixture.ownerTeamId !== unit.teamId) {
      return { ok: false, reason: "That device belongs to another faction." };
    }
  }
  if (rules.tag) {
    const definition = fixtureDefinition(fixture.definitionId);
    if (!definition || !(definition.tags || []).includes(rules.tag)) {
      return { ok: false, reason: "This action cannot command that device." };
    }
  }
  if (!rules.states.includes(fixture.state)) {
    return { ok: false, reason: "That device is " + fixture.state + "." };
  }
  if (rules.rangeMax != null && gridDistance(unit, fixture) > rules.rangeMax) {
    return { ok: false, reason: "That device is out of range." };
  }
  if (
    rules.requiresLineOfSight &&
    !hasLineOfSight(getMap(state), { x: unit.x, y: unit.y }, { x: fixture.x, y: fixture.y }, state)
  ) {
    return { ok: false, reason: "No line of sight to that device." };
  }
  return { ok: true, reason: null };
}

/** Every fixture a unit could activate with a given ability, in placement order. */
function activatableFixtures(state, unitId, abilityId) {
  const rules = fixtureTargetingRules(CONTENT.abilities[abilityId]);
  if (!rules) return [];
  return allFixtures(state.fixtures).filter(
    (fixture) => fixtureActivationEligibility(state, unitId, fixture, rules).ok
  );
}

/** Who a fixture would catch if it went off right now. Shared by the preview. */
function fixtureActivationTargets(state, fixture) {
  const definition = fixtureDefinition(fixture.definitionId);
  if (!definition) return [];
  const tiles = tilesInArea(state, { x: fixture.x, y: fixture.y }, definition.area || { shape: "single" }, {
    sourceUnitId: fixture.ownerUnitId || null
  });
  const out = [];
  for (const tile of tiles) {
    const occupant = unitAt(state, tile.x, tile.y);
    if (!occupant || !occupant.alive) continue;
    if (definition.affects === "enemy" && fixture.ownerTeamId) {
      if (relationshipBetween(state.factions, fixture.ownerTeamId, occupant.teamId) !== "hostile") continue;
    }
    if (definition.affects === "ally" && fixture.ownerTeamId) {
      if (relationshipBetween(state.factions, fixture.ownerTeamId, occupant.teamId) === "hostile") continue;
    }
    out.push(occupant.id);
  }
  return out;
}

/**
 * The fixtures a faction is entitled to see.
 *
 * The only path by which fixtures reach a view model or a plan, so a device
 * hidden from a side is hidden everywhere that side can look — the board, the
 * panels and the AI's inputs alike. Leaking a mine's coordinates through a
 * debug surface would be the same bug as drawing it.
 */
function visibleFixturesFor(state, teamId, options) {
  return allFixtures(state.fixtures).filter(
    (fixture) => fixtureIsActive(fixture) && fixtureVisibleTo(fixture, teamId, options)
  );
}

/** Whether an ability chains at all. Content decides; the engine keeps no list. */
function propagatingAbility(abilityId) {
  const ability = abilityId ? CONTENT.abilities[abilityId] : null;
  return ability && ability.propagation ? ability : null;
}

/**
 * Everything the chain preview needs, from the authorities that will run it.
 *
 * The order comes from `planUnitPropagation` and the numbers from the ordinary
 * forecast pipeline — the same two calls execution makes. Because the plan is
 * read from live positions every time this is called, moving an enemy and
 * re-hovering shows a different chain without anything having to invalidate a
 * cache.
 */
function createChainPreviewModel(state, sourceUnitId, abilityId, targetUnitId) {
  const ability = propagatingAbility(abilityId);
  const source = sourceUnitId ? state.units[sourceUnitId] : null;
  const target = targetUnitId ? state.units[targetUnitId] : null;
  if (!ability || !source || !target) return null;

  const plan = planUnitPropagation(state, sourceUnitId, abilityId, targetUnitId);
  const forecast = forecastEffectList(state, {
    sourceUnitId,
    targetUnitId,
    abilityId,
    sourceTile: { x: source.x, y: source.y },
    targetTile: { x: target.x, y: target.y },
    effects: ability.effects
  });

  const damage = {};
  for (const entry of forecast) {
    if (entry.effectType !== "damage" || entry.targetUnitId == null) continue;
    const bucket = damage[entry.targetUnitId] || (damage[entry.targetUnitId] = { amount: 0, lethal: false });
    bucket.amount += entry.totalAmount == null ? entry.amount : entry.totalAmount;
    bucket.lethal = bucket.lethal || !!entry.lethal;
  }

  const nodes = plan.nodes.map((node) => {
    const unit = state.units[node.id];
    const hit = damage[node.id];
    return {
      unitId: node.id,
      name: unit ? CONTENT.units[unit.definitionId].name : "—",
      hop: node.hop,
      distance: node.distance,
      fromUnitId: node.fromId,
      tile: unit ? { x: unit.x, y: unit.y } : null,
      amount: hit ? hit.amount : null,
      lethal: hit ? hit.lethal : false
    };
  });

  const costs = Object.keys(ability.costs || {}).map((resourceId) => {
    const definition = REACTION_INDEX.resourceById[resourceId];
    const pool = source.resources ? source.resources[resourceId] : null;
    const price = ability.costs[resourceId];
    return {
      resourceId,
      name: (definition && definition.name) || resourceId,
      amount: price,
      available: pool ? pool.current : null,
      remaining: pool ? pool.current - price : null,
      affordable: !!pool && pool.current >= price
    };
  });

  return {
    sourceUnitId,
    abilityId,
    abilityName: ability.name,
    legal: plan.legal,
    initialLegal: plan.initialLegal,
    initialReason: plan.initialReason,
    nodes,
    reached: nodes.length,
    hops: plan.hops,
    maxHops: plan.maxHops,
    termination: describeTermination(plan),
    terminationReason: plan.terminationReason,
    costs,
    affordable: costs.every((cost) => cost.affordable),
    totalDamage: nodes.reduce((total, node) => total + (node.amount || 0), 0),
    lethalCount: nodes.filter((node) => node.lethal).length
  };
}

/**
 * Everything an authored scaling source or condition may read about a chain in
 * progress. Plain values on battle state, so a save mid-chain resumes with the
 * same answers.
 */
function propagationContextOf(state, sourceUnitId) {
  const context = state.propagation;
  if (!context || context.sourceUnitId !== sourceUnitId) return null;
  return context;
}

const REACTION_ENGINE = {
  logLine(state, type, text, data) {
    logLine(state, type, text, data);
  },

  /** A balance and its ceiling, resolved through the ordinary scope rules. */
  resourceReading(state, unitId, resourceId) {
    return resourceReadingFor(state, unitId, resourceId);
  },

  processEvents(state) {
    processAllEvents(state);
  },

  relationship(state, aId, bId) {
    const a = state.units[aId];
    const b = state.units[bId];
    if (!a || !b) return "hostile";
    return relationshipBetween(state.factions, a.teamId, b.teamId);
  },

  hpPercent(state, unitId) {
    const unit = state.units[unitId];
    if (!unit) return 0;
    return (unit.currentHp / Math.max(1, calculateUnitStats(state, unitId).maxHp)) * 100;
  },

  /** What the viewer's faction believes about a unit. Non-hostiles are known. */
  knowledgeState(state, viewerUnitId, subjectUnitId) {
    const viewer = state.units[viewerUnitId];
    if (!viewer || !state.perception || !state.perception.enabled) return "acquired";
    if (!knowledgeGated(state, perceptionDeps(), viewer.teamId, subjectUnitId)) return "acquired";
    return knowledgeStateOf(state.perception, viewer.teamId, subjectUnitId);
  },

  unitMovement(state, unitId) {
    return calculateUnitStats(state, unitId).movement;
  },

  unitSpeed(state, unitId) {
    return calculateUnitStats(state, unitId).speed;
  },

  unitHasStatus(state, unitId, statusId) {
    return unitHasStatus(state, unitId, statusId);
  },

  statusTags(statusId) {
    const definition = CONTENT.statuses[statusId];
    return (definition && definition.tags) || [];
  },

  distance(state, aId, bId) {
    const a = state.units[aId];
    const b = state.units[bId];
    if (!a || !b) return null;
    return gridDistance(a, b);
  },

  /**
   * Can this unit see that tile?
   *
   * The basis of every exposure condition. It answers the question from the
   * viewer's own position rather than consulting a cached cover state,
   * because there is no such thing as being in cover in general — only in
   * cover from somewhere.
   */
  canSeeTile(state, viewerUnitId, tile) {
    const viewer = state.units[viewerUnitId];
    if (!viewer || !tile) return false;
    return hasLineOfSight(getMap(state), { x: viewer.x, y: viewer.y }, tile, state);
  },

  /**
   * Moves a unit's next activation along the real timeline.
   *
   * Routes through the same `timelineModified` event ordinary abilities use,
   * so there is one initiative calculator and a reaction's adjustment shows up
   * in a save, a replay and the log exactly like anything else. `delta` is in
   * recovery units and is scaled by the unit's own turn rate inside the
   * handler; the clamps live there too.
   */
  modifyTurnDelay(state, unitId, delta, options) {
    const unit = state.units[unitId];
    if (!unit || !unit.alive) return { applied: 0, reason: "no living unit" };

    // A unit that is mid-activation has no meaningful `nextActionTime` yet —
    // it is standing at the present moment, and its real next slot is decided
    // by the recovery `turnEnded` is about to charge. Adjusting the field now
    // would be overwritten a moment later. So the adjustment is banked against
    // the recovery instead, which is the same thing the author asked for:
    // "finish that and you are already moving".
    if (state.activation && state.activation.unitId === unitId && !state.activation.closed) {
      const cap = GAME_CONFIG.timeline.maxTurnDelayAdjustment;
      const banked = state.activation.turnDelayAdjustment || 0;
      const next = Math.max(-cap, Math.min(cap, banked + delta));
      const applied = next - banked;
      state.activation.turnDelayAdjustment = next;
      if (applied) {
        logLine(
          state,
          "timelineModified",
          unitLabel(state, unitId) +
            (applied < 0 ? " will recover faster by " : " will recover slower by ") +
            Math.abs(Math.round(applied)),
          { unitId, sourceUnitId: (options && options.sourceUnitId) || unitId, delta: applied, banked: true }
        );
      }
      return { applied, banked: true };
    }

    const before = unit.nextActionTime;
    queueEvent(state, {
      type: "timelineModified",
      sourceUnitId: (options && options.sourceUnitId) || unitId,
      targetUnitId: unitId,
      abilityId: null,
      delta
    });
    processAllEvents(state);
    return { applied: unit.nextActionTime - before };
  },

  /**
   * Runs a reaction's effects with the chain marked as passing through it.
   *
   * Everything the effect queues is then attributable to the reaction, which
   * is what lets a once-per-chain limit and the debug view both work without
   * the effect implementations knowing anything about causality.
   */
  withReactionCause(state, reactionId, fn) {
    if (!state.causality) return fn();
    const previous = state.causality.current;
    state.causality.current = {
      ...(previous || beginChain(state.causality, "reaction")),
      viaReaction: true,
      viaReactionId: reactionId
    };
    try {
      return fn();
    } finally {
      state.causality.current = previous;
    }
  },

  scriptedAttack(state, options) {
    MISSION_ENGINE.scriptedAttack(state, options);
  },

  scriptedRepair(state, options) {
    MISSION_ENGINE.scriptedRepair(state, options);
  },

  /**
   * Offers to change what a declared action does.
   *
   * The reaction layer never touches the intervention collection directly, and
   * never sees a command. It hands over a proposal and is told yes or no; the
   * engine owns the legality that the reaction layer has no way to judge —
   * whether a redirected shot is still in range and still has line of sight.
   */
  proposeIntervention(state, declarationId, proposal) {
    if (!state.interventions) return { ok: false, reason: "no intervention model" };
    return proposeIntervention(state.interventions, declarationId, proposal, (record, offer) => {
      if (offer.kind !== "redirect") return null;
      const target = state.units[offer.targetUnitId];
      if (!target || !target.alive) return "the new target is gone";
      if (record.kind === "movement") return "a move cannot be pointed at a unit";
      // The same check the declaration's own handler will make when it
      // resolves. Running it here as well means an illegal redirect is refused
      // while the reaction can still be refunded, rather than accepted now and
      // quietly reverted a moment later.
      const retargeted = evaluateTargeting(state, record.actorUnitId, record.abilityId, {
        unitId: offer.targetUnitId
      });
      return retargeted.valid ? null : retargeted.errors[0] || "that target is not legal";
    });
  },

  applyStatus(state, sourceUnitId, targetUnitIds, statusId) {
    if (!CONTENT.statuses[statusId]) {
      state.errors.push("Reaction used unknown status: " + statusId);
      return;
    }
    resolveEffects(state, {
      sourceUnitId,
      targetUnitIds,
      effects: [{ type: "applyStatus", statusId, chance: 1 }]
    });
    processAllEvents(state);
  },

  /**
   * Legal movement toward a tile, capped at a budget.
   *
   * Takes the exact tile when it can be entered, otherwise the reachable tile
   * closest to it. Returns `moved: false` rather than throwing when there is
   * nowhere legal to go — a reaction that cannot find ground is a no-op, not a
   * broken simulation.
   */
  moveTowardTile(state, unitId, tile, options) {
    const unit = state.units[unitId];
    if (!unit || !unit.alive) return { moved: false, reason: "the unit is gone" };
    const budget = (options && options.budget) || calculateUnitStats(state, unitId).movement;
    if (budget <= 0) return { moved: false, reason: "no movement available" };

    const range = computeMovementRange(state, unitId, { budget });
    let best = null;
    for (const node of range.values()) {
      if (node.x === unit.x && node.y === unit.y) continue;
      if (!isTileFree(state, node.x, node.y, unitId)) continue;
      const distance = Math.abs(node.x - tile.x) + Math.abs(node.y - tile.y);
      const current = Math.abs(unit.x - tile.x) + Math.abs(unit.y - tile.y);
      if (distance >= current) continue;
      // Closest to the opening; ties broken deterministically by cost then
      // by coordinate order so a replay always picks the same tile.
      if (
        !best ||
        distance < best.distance ||
        (distance === best.distance && node.cost < best.cost) ||
        (distance === best.distance && node.cost === best.cost && (node.y < best.y || (node.y === best.y && node.x < best.x)))
      ) {
        best = { ...node, distance };
      }
    }
    if (!best) return { moved: false, reason: "no legal ground closer to the opening" };

    const path = findPath(state, unitId, { x: best.x, y: best.y }, { budget });
    if (!path || path.length < 2) return { moved: false, reason: "no route to the opening" };
    MISSION_ENGINE.moveUnitAlongPath(state, unitId, path);
    processAllEvents(state);
    return { moved: true, tiles: path.length - 1, to: { x: best.x, y: best.y } };
  },

  /** Believed positions only: a reaction cannot advance on a contact its own
   *  faction has never made. */
  moveTowardNearestHostile(state, unitId, options) {
    const unit = state.units[unitId];
    if (!unit || !unit.alive) return { moved: false, reason: "the unit is gone" };
    let nearest = null;
    for (const threat of perceivedThreats(state, perceptionDeps(), unit.teamId)) {
      if (threat.unitId === unitId || !threat.alive) continue;
      const distance = gridDistance(unit, { x: threat.x, y: threat.y });
      if (!nearest || distance < nearest.distance) nearest = { x: threat.x, y: threat.y, distance };
    }
    if (!nearest) return { moved: false, reason: "nothing hostile to move toward" };
    return REACTION_ENGINE.moveTowardTile(state, unitId, { x: nearest.x, y: nearest.y }, options);
  },

  /**
   * The single basic action a partial action may take.
   *
   * Restricted to abilities flagged `basic` in content — a partial action is a
   * tempo grant, not a second activation. Target chosen by the same
   * deterministic scorer the AI uses, so headless and browser runs agree.
   */
  chooseBasicAction(state, unitId) {
    const unit = state.units[unitId];
    if (!unit || !unit.alive) return null;
    const origin = { x: unit.x, y: unit.y };
    const weights = aiProfileFor(state, unitId);
    let best = null;

    for (const abilityId of getUnitAbilities(state, unitId)) {
      if (!abilityUi(abilityId).basic) continue;
      if ((unit.cooldowns[abilityId] || 0) > 0) continue;
      if (!abilityConditionsMet(state, unitId, abilityId)) continue;
      for (const target of enumerateAiTargets(state, unitId, abilityId, origin)) {
        const targeting = evaluateTargeting(state, unitId, abilityId, target, origin);
        if (!targeting.valid || !targeting.targetUnitIds.length) continue;
        const score = scoreAbilityCandidate(state, unitId, abilityId, targeting, weights);
        const targetUnitId = targeting.targetUnitIds[0];
        if (!best || score > best.score || (score === best.score && targetUnitId < best.targetUnitId)) {
          best = { abilityId, targetUnitId, score };
        }
      }
    }
    return best;
  }
};

/** Reaction content is static, so the trigger index is built once. */
const REACTION_INDEX = buildReactionIndex(REACTION_CONTENT);

/* The dependency bundle is the same for every battle — content, the trigger
 * index, the adapter and the AI hook are all static — so it is built once
 * rather than allocated on every event. */
const REACTION_DEPS = {
  content: REACTION_CONTENT,
  index: REACTION_INDEX,
  engine: REACTION_ENGINE,
  chooseAiReaction: (state, offer, event) => chooseAiReaction(state, offer, event)
};

function reactionDeps() {
  return REACTION_DEPS;
}

/* ---------------------------------------------------------------
 * AI REACTION POLICY
 *
 * What replaced the placeholder, and why it had to.
 *
 * The old policy took anything affordable. That was honest about being a
 * stand-in and useless the moment the other side had more than one reaction:
 * an enemy squad with a taunt, a counter and a guard would fire whichever the
 * ordering happened to reach first, forever, regardless of whether it
 * accomplished anything. It also made an enemy duelist impossible to author,
 * because intercepting is only interesting if the AI can tell a shot worth
 * stopping from one worth ignoring.
 *
 * This is not a tactical genius and does not try to be. It answers the three
 * questions that decide whether an out-of-turn response was worth taking, in
 * one currency — expected HP:
 *
 *   what does it get me?    the reaction's own effect, forecast for real
 *   what does it stop?      for an intervention, the damage it prevents
 *   what does it cost me?   scarcity, not price — the last Command Point of
 *                           a battle is worth more than the first
 *
 * Deterministic and side-effect free: it reads forecasts, never the RNG, so a
 * replay from the same seed makes the same choices.
 * -------------------------------------------------------------*/

const REACTION_AI = {
  /** Below this, decline. Deliberately above zero: a reaction worth almost
   *  nothing is worth less than the resource it would spend. */
  threshold: 6,
  /** HP-equivalent value of the last point in a pool, versus the first. */
  scarcityWeight: 24,
  /** Losing a unit costs more than losing its remaining HP — the activation,
   *  the position and everything it would have done. */
  lethalBonus: 40,
  /** A declared move has no forecastable damage, so a movement interception is
   *  valued by denial rather than by prevention. Modest on purpose: stopping
   *  someone walking is worth something, not everything. */
  movementDenial: 14,
  /** Nudge from the authored priority, so an author can still break a tie
   *  without having to out-argue the arithmetic. */
  priorityWeight: 0.5
};

/** Expected damage from a forecast, counted against what the target can
 *  actually lose. Overkill is not extra value. */
function expectedHarm(state, outcomes) {
  let total = 0;
  for (const outcome of outcomes) {
    if (outcome.effectType !== "damage") continue;
    const target = state.units[outcome.targetUnitId];
    if (!target || !target.alive) continue;
    const chance = outcome.hitChance == null ? 1 : outcome.hitChance;
    total += Math.min(outcome.totalAmount || 0, target.currentHp) * chance;
    if (outcome.lethal) total += REACTION_AI.lethalBonus * chance;
  }
  return total;
}

/** What the declared action would do to the reactor's own side. */
function declaredThreatValue(state, event, reactorId) {
  if (event.actionKind === "movement" || !event.abilityId) return REACTION_AI.movementDenial;
  const ability = CONTENT.abilities[event.abilityId];
  if (!ability) return 0;
  let total = 0;
  for (const targetId of event.targetUnitIds || []) {
    const target = state.units[targetId];
    if (!target || !target.alive) continue;
    // Only harm to my own side counts. An enemy shooting another enemy is not
    // a problem I need to spend a Command Point on.
    if (isHostile(state, reactorId, targetId)) continue;
    total += expectedHarm(
      state,
      forecastEffectList(state, {
        sourceUnitId: event.sourceUnitId,
        targetUnitId: targetId,
        abilityId: event.abilityId,
        targetTile: event.tile || null,
        effects: ability.effects
      })
    );
  }
  return total;
}

/** What an out-of-turn attack by the reactor would achieve. */
function reactionAttackValue(state, reactorId, targetId, effect) {
  const target = state.units[targetId];
  if (!target || !target.alive) return 0;
  const ability = effect.abilityId ? CONTENT.abilities[effect.abilityId] : null;
  const effects = ability
    ? ability.effects
    : [
        {
          type: "damage",
          formula: effect.formula || "physical",
          power: effect.power == null ? 999 : effect.power,
          canMiss: false
        }
      ];
  return expectedHarm(
    state,
    forecastEffectList(state, {
      sourceUnitId: reactorId,
      targetUnitId: targetId,
      abilityId: effect.abilityId || null,
      targetTile: { x: target.x, y: target.y },
      effects
    })
  );
}

/**
 * What spending this actually costs, in the same currency.
 *
 * Linear in what is left afterwards rather than in the price: taking the last
 * point of a pool is four times as expensive as taking the first, which is the
 * only reason an AI ever holds anything back.
 */
function reactionScarcityCost(state, offer) {
  const unit = state.units[offer.reactorId];
  if (!unit) return 0;
  let cost = 0;
  for (const entry of (offer.cost && offer.cost.resources) || []) {
    const raw = REACTION_INDEX.resourceById[entry.id];
    if (!raw) continue;
    const amount = entry.amount == null ? 1 : entry.amount;
    const balance =
      raw.scope === "faction"
        ? (state.resources.faction[unit.teamId] || {})[entry.id]
        : (unit.resources || {})[entry.id];
    if (!balance || !balance.max) continue;
    const shareLeft = Math.max(0, balance.current - amount) / balance.max;
    cost += amount * REACTION_AI.scarcityWeight * (1 - shareLeft);
  }
  return cost;
}

/**
 * The score, in expected HP. Positive means it was worth doing.
 *
 * Exposed rather than inlined because the acceptance run and the tests both
 * need to see the number, not just the yes or no it collapses to.
 */
function scoreAiReaction(state, offer, event) {
  const reaction = REACTION_INDEX.reactionById[offer.reactionId];
  if (!reaction) return 0;
  const effect = reaction.effect || {};
  const reactorId = offer.reactorId;
  let value = 0;

  switch (effect.type) {
    case "cancelTriggeringAction":
      value = declaredThreatValue(state, event, reactorId);
      break;

    case "interceptAction": {
      const actorId = event.sourceUnitId;
      value = declaredThreatValue(state, event, reactorId);
      if (actorId) value += reactionAttackValue(state, reactorId, actorId, effect);
      break;
    }

    case "redirectTriggeringAction": {
      // Taking a hit for somebody else is worth the difference between what it
      // does to them and what it does to you. A bodyguard who is squishier
      // than her charge is not being brave, she is being wrong.
      const prevented = declaredThreatValue(state, event, reactorId);
      const self = event.abilityId
        ? expectedHarm(
            state,
            forecastEffectList(state, {
              sourceUnitId: event.sourceUnitId,
              targetUnitId: reactorId,
              abilityId: event.abilityId,
              targetTile: event.tile || null,
              effects: (CONTENT.abilities[event.abilityId] || { effects: [] }).effects
            })
          )
        : 0;
      value = prevented - self;
      break;
    }

    case "reactionAttack": {
      const targetId = event[effect.targetFrom === "source" ? "sourceUnitId" : "unitId"];
      value = targetId ? reactionAttackValue(state, reactorId, targetId, effect) : 0;
      break;
    }

    case "reactionRepair": {
      const targetId = event[effect.targetFrom === "source" ? "sourceUnitId" : "unitId"];
      const target = targetId ? state.units[targetId] : null;
      if (target && target.alive) {
        const missing = calculateUnitStats(state, targetId).maxHp - target.currentHp;
        value = Math.min(missing, effect.amount == null ? 30 : effect.amount);
      }
      break;
    }

    default:
      // Everything else — statuses, advances, timeline pushes — is real but
      // not forecastable in HP. A flat modest value keeps them in play without
      // pretending to a precision this policy does not have.
      value = GAME_CONFIG.ai.statusValue;
      break;
  }

  value += (offer.priority - 50) * REACTION_AI.priorityWeight;
  return value - reactionScarcityCost(state, offer);
}

/** Yes or no, from the score. Same legality path the player takes. */
function chooseAiReaction(state, offer, event) {
  // Do not spend anything reacting to something that is already gone.
  if (event && event.unitId && state.units[event.unitId] && !state.units[event.unitId].alive) {
    return false;
  }
  return scoreAiReaction(state, offer, event) >= REACTION_AI.threshold;
}

function reactionsEnabled(state) {
  return !!(state.reactions && state.reactions.enabled);
}

/** Runs one reaction stage for an event. Returns true when the queue must
 *  stop draining because a player choice is pending. */
function runReactionsForEvent(state, event, stage) {
  if (!reactionsEnabled(state)) return false;
  const result = runReactionStage(state, reactionDeps(), event, stage);
  if (result.suspended && state.autoResolveReactions) {
    autoResolveReactionWindows(state, reactionDeps());
    return !!(state.reactions && state.reactions.window);
  }
  return result.suspended;
}

/** Renderer callback: the player answered a reaction prompt. */
function resolveReactionChoice(state, offerId) {
  if (!state.reactions || !state.reactions.window) return false;
  resolveReactionWindow(state, reactionDeps(), offerId || null);
  // The event queue was parked mid-drain; finish it and settle the command.
  processAllEvents(state);
  settleAfterReactions(state);
  return true;
}

function refreshReactionLinks(state) {
  if (!reactionsEnabled(state)) return;
  refreshLinks(state, reactionDeps());
}

function reactionModel(state) {
  if (!state.reactions) return null;
  return describeReactions(state, reactionDeps());
}

/**
 * The authored scene a mission names for a hook, or null.
 *
 * Missions reference scenes by stable id, never by embedding them, so the same
 * scene can be shared by several missions and edited in one place.
 */
function missionSceneFor(missionId, hook) {
  const entry = missionId ? MISSION_CONTENT.missions[missionId] : null;
  const sceneId = entry ? entry[hook] : null;
  return sceneId ? sceneById(sceneId) : null;
}

/** Compiled mission scripts, keyed by the id stored on battle state. Kept out
 *  of battle state itself so a save stays small and a script edit does not
 *  invalidate old saves. */
const MISSION_SCRIPTS = {};

function registerMissionScript(script) {
  if (script && script.id) MISSION_SCRIPTS[script.id] = script;
  return script;
}

function missionScriptFor(state) {
  if (!state || !state.missionScriptId) return null;
  return MISSION_SCRIPTS[state.missionScriptId] || null;
}

/** The dependency bundle the mission runtime expects. */
function missionDeps(state, options) {
  const script = (options && options.script) || missionScriptFor(state);
  if (!script) return null;
  return {
    script,
    engine: MISSION_ENGINE,
    campaignFlags: (options && options.campaignFlags) || state.campaignFlagsSnapshot || {}
  };
}

/**
 * Runs the mission script forward after the simulation has changed.
 *
 * Called from executeCommand, so a scripted beat fires in the same tick as the
 * action that triggered it — headless or in the browser, identically.
 */
function runMissionScript(state, options) {
  const deps = missionDeps(state, options);
  if (!deps || !state.mission) return null;
  const result = advanceMission(state, deps);
  const autoResolve = (options && options.autoResolve) || state.autoResolveScenes;
  if (autoResolve && state.mission.wait) autoResolveWaits(state, deps);
  return result;
}

function startMissionScript(state, options) {
  const deps = missionDeps(state, options);
  if (!deps || !state.mission) return state;
  startMission(state, deps);
  if (options && options.autoResolve) autoResolveWaits(state, deps);
  return state;
}

/** Renderer callback: a blocking presentation request finished. */
function resolveMissionPresentation(state, token, payload, options) {
  const deps = missionDeps(state, options);
  if (!deps) return false;
  const resolved = resolveMissionWait(state, deps, token, payload);
  if (resolved) advanceMission(state, deps);
  return resolved;
}

/* ---------------------------------------------------------------
 * SCORE-BASED AI
 * -------------------------------------------------------------*/

function aiProfileFor(state, unitId) {
  const unit = state.units[unitId];
  const profile = CONTENT.aiProfiles[unit.aiProfileId];
  if (profile) return profile;
  const fallbackId = Object.keys(CONTENT.aiProfiles)[0];
  return CONTENT.aiProfiles[fallbackId];
}

/**
 * Candidate targets for an AI ability.
 *
 * Reads the acting faction's *believed* world, never the board. A hostile the
 * faction has not acquired is not in the list at all — not "in the list but
 * unscored", which would still leak its position through range filtering.
 * Suspected contacts are excluded: a last-known tile is somewhere to go, not
 * something to shoot.
 */
function enumerateAiTargets(state, unitId, abilityId, origin) {
  const ability = CONTENT.abilities[abilityId];
  const targeting = ability.targeting;
  if (targeting.type === "emptyTile") return [];
  if (targeting.type === "self") return [{ unitId }];
  const filter = TARGET_FILTERS[targeting.type];
  const actor = state.units[unitId];
  if (!actor) return [];
  const out = [];
  for (const entry of perceivedUnits(state, perceptionDeps(), actor.teamId, {
    includeDefeated: targeting.allowsDefeated,
    includeSuspected: false
  })) {
    const other = state.units[entry.unitId];
    if (!other.alive && !targeting.allowsDefeated) continue;
    if (!filter(state, unitId, other)) continue;
    const tile = entry.unitId === unitId ? origin : { x: entry.x, y: entry.y };
    const distance = gridDistance(origin, tile);
    if (distance < targeting.rangeMin || distance > targeting.rangeMax) continue;
    out.push({ unitId: entry.unitId });
  }
  return out;
}

function activeObjectiveTargetIds(state, unitId) {
  const unit = state.units[unitId];
  if (!unit) return [];
  const rootParams = objectiveParams(state);
  if (rootParams.teamId && unit.teamId !== rootParams.teamId) return [];
  let objectiveId = state.objectiveState.objectiveId;
  let params = rootParams;
  if (objectiveId === "phasedObjective") {
    const phases = rootParams.phases || [];
    const progress = state.objectiveState.progress || {};
    const phase = phases[progress.phaseIndex || 0];
    if (!phase) return [];
    objectiveId = phase.type;
    params = { ...rootParams, ...(phase.params || {}) };
  }
  if (objectiveId !== "destroyTargets") return [];
  return (params.unitIds || []).filter((id) => state.units[id] && state.units[id].alive);
}

/**
 * Pull toward the objective's named units.
 *
 * Being told to destroy something is not the same as knowing where it is: an
 * objective target the faction has no contact on contributes nothing. Missions
 * that mean to brief their squad say so with a `revealUnit` action, which is a
 * deliberate authoring decision rather than an engine assumption.
 */
function objectivePositionScore(state, unitId, tile) {
  const targets = activeObjectiveTargetIds(state, unitId);
  if (!targets.length) return 0;
  const unit = state.units[unitId];
  if (!unit) return 0;
  let nearest = Infinity;
  for (const targetId of targets) {
    const believed = believedPositionOf(state, perceptionDeps(), unit.teamId, targetId);
    if (!believed) continue;
    nearest = Math.min(nearest, gridDistance(tile, believed));
  }
  return Number.isFinite(nearest) ? -nearest * GAME_CONFIG.ai.objectiveProximityWeight : 0;
}

/**
 * How good a tile is, from the acting faction's point of view.
 *
 * Threat comes from `perceivedThreats`, so a hostile nobody has seen exerts no
 * pull and no fear. A suspected contact counts at half weight for danger while
 * still drawing the unit in — which is what makes "advance on the last known
 * position, carefully" fall out of ordinary scoring rather than a search mode.
 */
function tilePositionScore(state, unitId, tile, weights) {
  const unit = state.units[unitId];
  if (!unit) return 0;
  let proximity = 0;
  let danger = 0;
  let nearest = Infinity;
  let acquired = false;
  for (const threat of perceivedThreats(state, perceptionDeps(), unit.teamId)) {
    if (threat.unitId === unitId) continue;
    const distance = gridDistance(tile, { x: threat.x, y: threat.y });
    nearest = Math.min(nearest, distance);
    danger += Math.max(0, 4 - distance) * threat.threat;
    if (threat.state === "acquired") acquired = true;
  }
  if (Number.isFinite(nearest)) {
    proximity = -nearest;
    // Nothing it can shoot, but something to look for: prefer ground that can
    // actually see the last-known position over ground that is merely near it.
    // A painted contact is useless behind a wall, because the shot still needs
    // a line — so the search has to be about angles, not distance.
    if (!acquired) {
      const lead = searchLeadFor(state, perceptionDeps(), unitId);
      if (lead && PERCEPTION_ENGINE.lineOfSight(state, tile, { x: lead.x, y: lead.y })) {
        proximity += GAME_CONFIG.ai.sightlineBonus;
      }
    }
  } else {
    // Nothing known at all: head for the area the faction has reason to care
    // about. No threat is scored, because there is no threat to score.
    const anchor = searchAnchorFor(state, perceptionDeps(), unitId);
    if (anchor) proximity = -gridDistance(tile, anchor);
  }
  return (
    weights.targetProximity * proximity +
    weights.selfDanger * danger +
    objectivePositionScore(state, unitId, tile)
  );
}

const EFFECT_AI_SCORERS = {
  damage(state, context) {
    const { effect, numbers, target, weights } = context;
    const formula = FORMULAS.damage[effect.formula];
    if (!formula) return 0;
    const amount = Math.max(1, Math.round(formula(numbers)));
    const chance = effect.canMiss
      ? FORMULAS.accuracy.hitChance({
          accuracy: numbers.accuracy,
          evasion: numbers.evasion,
          bonus: effect.accuracyBonus || 0
        })
      : 1;
    let score = weights.expectedDamage * amount * chance;
    if (amount >= target.currentHp) score += weights.lethalBonus * chance;
    return score;
  },

  heal(state, context) {
    const { effect, numbers, target, weights } = context;
    const formula = FORMULAS.healing[effect.formula];
    if (!formula) return 0;
    const stats = calculateUnitStats(state, target.id);
    const missing = stats.maxHp - target.currentHp;
    const amount = Math.max(1, Math.round(formula(numbers)));
    let score = weights.healing * Math.min(amount, missing);
    if (missing <= 0) score -= GAME_CONFIG.ai.redundantHealPenalty;
    return score;
  },

  applyStatus(state, context) {
    const { effect, target } = context;
    const chance = effect.chance == null ? 1 : effect.chance;
    const alreadyApplied = target.statuses.some((s) => s.statusId === effect.statusId);
    return (
      (alreadyApplied ? GAME_CONFIG.ai.redundantStatusValue : GAME_CONFIG.ai.statusValue) * chance
    );
  },

  removeStatus: () => GAME_CONFIG.ai.cleanseValue,

  modifyTimeline(state, context) {
    const { effect, weights } = context;
    const delta = (effect.delay || 0) - (effect.hasten || 0);
    return weights.timelineDelay * (delta / GAME_CONFIG.ai.timelineDelayScale);
  },

  shield(state, context) {
    const { effect, target } = context;
    const friendly = !isHostile(state, context.unitId, target.id);
    const existing = target.shields.reduce((sum, shield) => sum + shield.remaining, 0);
    if (!friendly) return -GAME_CONFIG.ai.redundantHealPenalty;
    return (
      GAME_CONFIG.contextSelection.shieldWeight * (effect.amount || 0) -
      (existing > 0 ? GAME_CONFIG.ai.redundantStatusValue : 0)
    );
  },

  modifyStat(state, context) {
    const { effect, target } = context;
    const friendly = !isHostile(state, context.unitId, target.id);
    const magnitude =
      effect.mode === "multiplier" ? Math.abs(effect.value - 1) * 100 : Math.abs(effect.value);
    const helpful = effect.mode === "multiplier" ? effect.value >= 1 : effect.value >= 0;
    const wanted = friendly === helpful;
    return (wanted ? 1 : -1) * GAME_CONFIG.ai.statusValue * (magnitude / 30);
  },

  displace: (state, context) => forcedMovementScore(state, context),
  push: (state, context) => forcedMovementScore(state, context),
  pull: (state, context) => forcedMovementScore(state, context),
  moveUnit: (state, context) => forcedMovementScore(state, context),

  teleport: () => GAME_CONFIG.ai.statusValue / 2,
  swapPositions: () => GAME_CONFIG.ai.statusValue / 2,

  restoreResource(state, context) {
    const resource = context.target.resources[context.effect.resourceId];
    if (!resource) return 0;
    const missing = resource.max - resource.current;
    return Math.min(missing, context.effect.amount || 0) * 0.2;
  },

  spendResource: () => 0,

  /**
   * Worth exactly what it actually moves.
   *
   * Zero when the destination is full, which is the whole reason this is not
   * a flat value: a support AI that tops up a full pool has spent its turn
   * and its finite capacity to accomplish nothing, and would keep doing it.
   */
  transferResource(state, context) {
    const plan = transferPlanFor(state, {
      effect: context.effect,
      sourceUnitId: context.unitId,
      targetUnitId: context.target ? context.target.id : context.unitId,
      abilityId: context.abilityId
    });
    if (!plan) return 0;
    const result = planTransfer(state, plan);
    if (!result.ok) return -GAME_CONFIG.ai.redundantHealPenalty;
    return result.gained * GAME_CONFIG.ai.statusValue * 0.5;
  },

  createTerrain: () => GAME_CONFIG.ai.statusValue / 3,
  removeTerrain: () => 0,

  spawnUnit(state, context) {
    if (state.spawnCount >= GAME_CONFIG.limits.maxSpawnedUnits) return -100;
    return GAME_CONFIG.ai.statusValue * 1.5;
  },

  despawnUnit(state, context) {
    return context.target.summonedBy ? GAME_CONFIG.ai.statusValue : 0;
  },

  revive(state, context) {
    return context.target.alive ? -GAME_CONFIG.ai.redundantHealPenalty : GAME_CONFIG.ai.lethalBonus / 2;
  },

  transformUnit: () => GAME_CONFIG.ai.statusValue / 2,
  copyStatus: () => GAME_CONFIG.ai.statusValue / 3,
  transferStatus: () => GAME_CONFIG.ai.statusValue / 2,

  cleanse(state, context) {
    const negative = context.target.statuses.filter((applied) => {
      const definition = CONTENT.statuses[applied.statusId];
      return definition && definition.category === "negative";
    }).length;
    return negative ? GAME_CONFIG.ai.cleanseValue * negative : -GAME_CONFIG.ai.redundantHealPenalty;
  },

  dispel(state, context) {
    const positive = context.target.statuses.filter((applied) => {
      const definition = CONTENT.statuses[applied.statusId];
      return definition && definition.category === "positive";
    }).length;
    return positive || context.target.modifiers.length ? GAME_CONFIG.ai.cleanseValue : 0;
  },

  delayedEffect(state, context) {
    return scoreEffectList(state, context, context.effect.effects || []) * 0.6;
  },

  conditionalEffect(state, context) {
    const evaluation = evaluateConditionsPure(
      {
        state,
        sourceUnitId: context.unitId,
        targetUnitId: context.target.id,
        targetTile: { x: context.target.x, y: context.target.y },
        effect: context.effect
      },
      context.effect.conditions
    );
    const branch = evaluation.value ? context.effect.ifTrue : context.effect.ifFalse;
    return scoreEffectList(state, context, branch || []);
  },

  refreshActivationResource: () => GAME_CONFIG.ai.statusValue,

  repeatEffect(state, context) {
    const count = Math.min(
      context.effect.count == null ? 1 : context.effect.count,
      GAME_CONFIG.limits.maxRepeatedEffects
    );
    return scoreEffectList(state, context, context.effect.effects || []) * count;
  },

  /**
   * Worth what it reaches. The AI does not plan chains — it cannot choose a
   * target *because* of who stands behind them — but it can at least tell that
   * an action hitting four units is worth more than one hitting one.
   */
  /* Preparing ground is worth something, but the AI cannot reason about where
   * an enemy will want to stand two activations from now. A flat, modest score
   * keeps it from spamming devices without pretending it has a plan. */
  placeFixture: () => GAME_CONFIG.ai.statusValue * 0.5,
  setFixtureState: () => 0,

  propagate(state, context) {
    const plan = planUnitPropagation(state, context.unitId, context.abilityId, context.target.id);
    const per = scoreEffectList(state, context, context.effect.effects || []);
    return per * Math.max(1, plan.nodes.length);
  }
};

function forcedMovementScore(state, context) {
  const hostile = isHostile(state, context.unitId, context.target.id);
  const distance = context.effect.distance == null ? 1 : context.effect.distance;
  return (hostile ? 1 : 0.3) * GAME_CONFIG.ai.statusValue * (distance / 2);
}

function scoreEffectList(state, context, effects) {
  let score = 0;
  for (const effect of effects) {
    const scorer = EFFECT_AI_SCORERS[effect.type];
    if (!scorer) continue;
    score += scorer(state, {
      ...context,
      effect,
      numbers: effectContextStats(state, context.unitId, context.target.id, effect)
    });
  }
  return score;
}

function scoreAbilityCandidate(state, unitId, abilityId, targeting, weights) {
  const ability = CONTENT.abilities[abilityId];
  let score = 0;
  for (const targetUnitId of targeting.targetUnitIds) {
    const target = state.units[targetUnitId];
    score += scoreEffectList(
      state,
      { unitId, target, weights, abilityId },
      ability.effects
    );
  }
  const objectiveTargets = activeObjectiveTargetIds(state, unitId);
  if (
    objectiveTargets.some((targetId) => targeting.targetUnitIds.includes(targetId)) &&
    ability.effects.some((effect) => effect.type === "damage")
  ) {
    score += GAME_CONFIG.ai.objectiveTargetBonus;
  }
  for (const resourceId of Object.keys(ability.costs || {})) {
    const resource = state.units[unitId].resources[resourceId];
    if (!resource) continue;
    score -= (ability.costs[resourceId] / Math.max(1, resource.max)) * GAME_CONFIG.ai.statusValue;
  }
  return score;
}

/**
 * Returns a validated command sequence for the active unit.
 */
/** Are an ability's own requirements satisfied right now? Preview-safe. */
function abilityConditionsMet(state, unitId, abilityId) {
  const ability = CONTENT.abilities[abilityId];
  if (!ability || !(ability.conditions || []).length) return true;
  const context = createEffectContext(state, {
    sourceUnitId: unitId,
    targetUnitId: unitId,
    abilityId,
    effect: {}
  });
  return evaluateConditionsPure(context, ability.conditions).value;
}

function chooseAiCommands(state, unitId) {
  const unit = state.units[unitId];
  const definition = CONTENT.units[unit.definitionId];
  const weights = aiProfileFor(state, unitId);
  const reachable = [...computeMovementRange(state, unitId).values()].sort(
    (a, b) => (a.y - b.y) || (a.x - b.x)
  );

  const candidates = [];
  for (const tile of reachable) {
    const origin = { x: tile.x, y: tile.y };
    const movementPenalty = tile.cost * GAME_CONFIG.ai.movementCostWeight;
    const positionScore = tilePositionScore(state, unitId, origin, weights);

    candidates.push({
      origin,
      abilityId: null,
      target: null,
      score: positionScore - movementPenalty + GAME_CONFIG.ai.idleScore
    });

    for (const abilityId of getUnitAbilities(state, unitId)) {
      if ((unit.cooldowns[abilityId] || 0) > 0) continue;
      // Abilities issued through a different command are not the AI's to
      // choose here. Enumerating them produced an action that spent the turn
      // and resolved nothing.
      if (commandKindForAbility(CONTENT.abilities[abilityId]) !== "useAbility") continue;
      if (!abilityConditionsMet(state, unitId, abilityId)) continue;
      for (const target of enumerateAiTargets(state, unitId, abilityId, origin)) {
        const targeting = evaluateTargeting(state, unitId, abilityId, target, origin);
        if (!targeting.valid || !targeting.targetUnitIds.length) continue;
        const score =
          scoreAbilityCandidate(state, unitId, abilityId, targeting, weights) +
          positionScore -
          movementPenalty;
        candidates.push({ origin, abilityId, target, score });
      }
    }
  }

  let best = null;
  for (const candidate of candidates) {
    if (!best || candidate.score > best.score) {
      best = candidate;
    } else if (candidate.score === best.score && rollChance(state, 0.5)) {
      best = candidate;
    }
  }
  if (!best) return [{ type: "wait", unitId }];

  const commands = [];
  if (best.origin.x !== unit.x || best.origin.y !== unit.y) {
    const path = findPath(state, unitId, best.origin);
    if (path && path.length > 1) commands.push({ type: "move", unitId, path });
  }
  if (best.abilityId) {
    commands.push({
      type: "useAbility",
      unitId,
      abilityId: best.abilityId,
      target: best.target
    });
  } else {
    commands.push({ type: "wait", unitId });
  }
  return commands;
}

/* ---------------------------------------------------------------
 * BATTLE RUNNERS (engine-side, renderer independent)
 * -------------------------------------------------------------*/

function beginNextActivation(state, options) {
  if (state.finished) return null;
  const unitId = getNextActionableUnitId(state);
  if (!unitId) return null;
  const result = executeCommand(state, { type: "activateUnit", unitId }, options);
  return result.ok ? unitId : null;
}

/** Runs the currently activated unit's turn using its AI profile. */
function runAiTurn(state, options) {
  const unitId = state.activeUnitId;
  if (!unitId) return { unitId: null, commands: [], errors: [] };
  const commands = chooseAiCommands(state, unitId);
  const errors = [];
  for (const command of commands) {
    if (state.activeUnitId !== unitId || state.finished) break;
    const result = executeCommand(state, command, options);
    if (!result.ok) errors.push(...result.errors);
  }
  if (state.activeUnitId === unitId && !state.finished) {
    const acted = state.activation && state.activation.acted;
    executeCommand(state, { type: acted ? "endTurn" : "wait", unitId }, options);
  }
  return { unitId, commands, errors };
}

/** One complete activation: schedule, statuses, AI decision, recovery. */
function runActivation(state, options) {
  const unitId = beginNextActivation(state, options);
  if (!unitId) return { unitId: null, commands: [], errors: [] };
  if (state.activeUnitId !== unitId || state.finished) {
    return { unitId, commands: [], errors: [], skipped: true };
  }
  return runAiTurn(state, options);
}

function runBattle(state, maxActivations, options) {
  const cap = maxActivations || GAME_CONFIG.limits.maxActivationsPerBattle;
  let activations = 0;
  while (!state.finished && activations < cap) {
    const result = runActivation(state, options);
    if (!result.unitId) break;
    activations += 1;
  }
  return {
    finished: state.finished,
    winner: state.winner,
    activations,
    hitCap: !state.finished && activations >= cap
  };
}

/* ---------------------------------------------------------------
 * CONTENT VALIDATION
 * -------------------------------------------------------------*/

function collectContentIssues(registry) {
  const errors = [];
  const warnings = [];
  const statNames = Object.keys(DEFAULT_BASE_STATS);

  for (const unitId of Object.keys(registry.units)) {
    const unit = registry.units[unitId];
    if (!unit.name) warnings.push("Unit " + unitId + " has no name.");
    for (const statName of statNames) {
      const value = unit.baseStats[statName];
      if (!Number.isFinite(value)) {
        errors.push("Unit " + unitId + " has a non-finite " + statName + ".");
      } else if (value < 0) {
        errors.push("Unit " + unitId + " has a negative " + statName + ".");
      }
    }
    if (unit.baseStats.maxHp <= 0) errors.push("Unit " + unitId + " has no maxHp.");
    if (unit.baseStats.speed <= 0) errors.push("Unit " + unitId + " has no speed.");
    if (!unit.abilities.length) warnings.push("Unit " + unitId + " has no abilities.");
    for (const abilityId of unit.abilities) {
      if (!registry.abilities[abilityId]) {
        errors.push("Unit " + unitId + " references unknown ability " + abilityId + ".");
      }
    }
    errors.push(...validateAssetReferences(registry, unit, "Unit " + unitId));
    for (const abilityId of unit.abilities) {
      const ability = registry.abilities[abilityId];
      if (!ability) continue;
      for (const resourceId of Object.keys(ability.costs || {})) {
        // A faction-scoped cost is paid from the squad's pool, so the unit
        // carrying the ability is not expected to declare it. Checking only
        // the unit's own dictionary made a squad-wide cost look impossible.
        const declared = REACTION_INDEX.resourceById[resourceId];
        if (declared && declared.scope === "faction") continue;
        if (!unit.resources[resourceId]) {
          errors.push(
            "Unit " + unitId + " cannot pay the " + resourceId + " cost of " + abilityId + "."
          );
        }
      }
    }
    if (unit.aiProfile && !registry.aiProfiles[unit.aiProfile]) {
      errors.push("Unit " + unitId + " references unknown AI profile " + unit.aiProfile + ".");
    }
  }

  for (const abilityId of Object.keys(registry.abilities)) {
    const ability = registry.abilities[abilityId];
    const targeting = ability.targeting;
    if (!TARGET_FILTERS[targeting.type]) {
      errors.push("Ability " + abilityId + " has unknown targeting type " + targeting.type + ".");
    }
    if (!AREA_SHAPES[targeting.area.shape]) {
      errors.push("Ability " + abilityId + " has unknown area shape " + targeting.area.shape + ".");
    }
    if (targeting.rangeMin < 0 || targeting.rangeMax < targeting.rangeMin) {
      errors.push("Ability " + abilityId + " has an invalid range.");
    }
    if (!Number.isFinite(ability.timing.recovery) || ability.timing.recovery < 0) {
      errors.push("Ability " + abilityId + " has invalid recovery.");
    }
    if (!Number.isFinite(ability.timing.cooldown) || ability.timing.cooldown < 0) {
      errors.push("Ability " + abilityId + " has an invalid cooldown.");
    }
    errors.push(...validateAssetReferences(registry, ability, "Ability " + abilityId));
    const shape = ability.targeting.area ? ability.targeting.area.shape || "single" : "single";
    if (!AREA_SHAPES[shape]) {
      errors.push("Ability " + abilityId + " uses unknown area shape " + shape + ".");
    }
    for (const filter of ability.targeting.filters || []) {
      if (!TARGET_FILTER_HANDLERS[filter.type]) {
        errors.push("Ability " + abilityId + " uses unknown target filter " + filter.type + ".");
      }
      if (filter.statusId && !registry.statuses[filter.statusId]) {
        errors.push("Ability " + abilityId + " filters on unknown status " + filter.statusId + ".");
      }
    }
    errors.push(...validateConditionList(registry, ability.conditions, "Ability " + abilityId));
    errors.push(...validateEffectList(registry, ability.effects, "Ability " + abilityId));
  }

  for (const statusId of Object.keys(registry.statuses)) {
    const status = registry.statuses[statusId];
    if (status.duration.type !== "targetActivations") {
      errors.push("Status " + statusId + " has unknown duration type " + status.duration.type + ".");
    }
    if (!Number.isFinite(status.duration.amount) || status.duration.amount <= 0) {
      errors.push("Status " + statusId + " has an invalid duration amount.");
    }
    errors.push(...validateAssetReferences(registry, status, "Status " + statusId));
    for (const trigger of status.triggers) {
      errors.push(
        ...validateEffectList(registry, trigger.effects || [], "Status " + statusId)
      );
    }
  }

  for (const terrainId of Object.keys(registry.terrains)) {
    const terrain = registry.terrains[terrainId];
    errors.push(...validateAssetReferences(registry, terrain, "Terrain " + terrainId));
    if (terrain.walkable && !(terrain.movementCost > 0)) {
      errors.push("Terrain " + terrainId + " has an invalid movement cost.");
    }
  }

  for (const mapId of Object.keys(registry.maps)) {
    const map = registry.maps[mapId];
    if (!(map.width > 0) || !(map.height > 0)) {
      errors.push("Map " + mapId + " has invalid dimensions.");
    }
    if (map.tiles.length !== map.height) {
      errors.push("Map " + mapId + " row count does not match its height.");
    }
    map.tiles.forEach((row, y) => {
      if (row.length !== map.width) {
        errors.push("Map " + mapId + " row " + y + " does not match its width.");
      }
      row.forEach((terrainId, x) => {
        if (!registry.terrains[terrainId]) {
          errors.push(
            "Map " + mapId + " tile " + x + "," + y + " uses unknown terrain " + terrainId + "."
          );
        }
      });
    });
    errors.push(...validateMapElevation(map, mapId));
  }

  for (const encounterId of Object.keys(registry.encounters)) {
    const encounter = registry.encounters[encounterId];
    const encounterMap = registry.maps[encounter.mapId];
    if (encounterMap) {
      for (const spawn of encounter.units || []) {
        const inside =
          spawn.x >= 0 &&
          spawn.y >= 0 &&
          spawn.x < encounterMap.width &&
          spawn.y < encounterMap.height;
        if (!inside) {
          errors.push(
            "Encounter " + encounterId + " places a unit outside " + encounter.mapId + "."
          );
          continue;
        }
        const terrainId = encounterMap.tiles[spawn.y][spawn.x];
        const terrain = registry.terrains[terrainId];
        if (!terrain || !terrain.walkable) {
          errors.push(
            "Encounter " + encounterId + " places a unit on impassable terrain at " +
              spawn.x + "," + spawn.y + "."
          );
        }
      }
    }
    const map = registry.maps[encounter.mapId];
    if (!map) {
      errors.push("Encounter " + encounterId + " references unknown map " + encounter.mapId + ".");
    }
    if (!OBJECTIVE_HANDLERS[encounter.objective]) {
      errors.push(
        "Encounter " + encounterId + " uses unknown objective " + encounter.objective + "."
      );
    }
    const teamIds = new Set(encounter.teams.map((t) => t.id));
    if (teamIds.size < 2) {
      errors.push("Encounter " + encounterId + " needs at least two teams.");
    }
    const usedTiles = new Set();
    for (const spawn of encounter.units) {
      if (!registry.units[spawn.definitionId]) {
        errors.push(
          "Encounter " + encounterId + " spawns unknown unit " + spawn.definitionId + "."
        );
        continue;
      }
      if (!teamIds.has(spawn.teamId)) {
        errors.push(
          "Encounter " + encounterId + " spawns a unit on unknown team " + spawn.teamId + "."
        );
      }
      if (spawn.aiProfile && !registry.aiProfiles[spawn.aiProfile]) {
        errors.push(
          "Encounter " + encounterId + " references unknown AI profile " + spawn.aiProfile + "."
        );
      }
      if (!map) continue;
      const inside =
        spawn.x >= 0 && spawn.y >= 0 && spawn.x < map.width && spawn.y < map.height;
      if (!inside) {
        errors.push(
          "Encounter " + encounterId + " spawn " + spawn.x + "," + spawn.y + " is off the map."
        );
        continue;
      }
      const terrain = registry.terrains[map.tiles[spawn.y][spawn.x]];
      if (!terrain || !terrain.walkable) {
        errors.push(
          "Encounter " + encounterId + " spawn " + spawn.x + "," + spawn.y + " is blocked."
        );
      }
      const key = spawn.x + "," + spawn.y;
      if (usedTiles.has(key)) {
        errors.push("Encounter " + encounterId + " has duplicate spawn tile " + key + ".");
      }
      usedTiles.add(key);
    }
  }

  for (const profileId of Object.keys(registry.aiProfiles)) {
    const profile = registry.aiProfiles[profileId];
    for (const key of Object.keys(profile)) {
      if (key === "id") continue;
      if (!Number.isFinite(profile[key])) {
        errors.push("AI profile " + profileId + " has a non-numeric weight " + key + ".");
      }
    }
  }

  return { errors, warnings };
}

function validateAssetReferences(registry, definition, label) {
  const errors = [];
  const references = definition.assets || {};
  for (const slot of Object.keys(references)) {
    const assetId = references[slot];
    if (assetId == null) continue;
    if (!registry.presentationAssets[assetId]) {
      errors.push(label + " references unknown asset " + assetId + " for " + slot + ".");
    }
  }
  return errors;
}

/** Per-effect field validation. One validator per registered effect type. */
const EFFECT_VALIDATORS = {
  damage: (registry, effect, label) =>
    FORMULAS.damage[effect.formula]
      ? []
      : [label + " references unknown damage formula " + effect.formula + "."],
  heal: (registry, effect, label) =>
    FORMULAS.healing[effect.formula]
      ? []
      : [label + " references unknown healing formula " + effect.formula + "."],
  applyStatus: (registry, effect, label) => requireStatus(registry, effect, label),
  removeStatus: (registry, effect, label) => requireStatus(registry, effect, label),
  modifyTimeline: () => [],
  shield: (registry, effect, label) =>
    effect.amount > 0 ? [] : [label + " needs a positive shield amount."],
  modifyStat: (registry, effect, label) => {
    const errors = [];
    if (!effect.stat) errors.push(label + " needs a stat name.");
    if (!["flat", "multiplier", "override"].includes(effect.mode || "flat")) {
      errors.push(label + " uses an unknown stat mode.");
    }
    if (typeof effect.value !== "number") errors.push(label + " needs a numeric value.");
    return errors;
  },
  /* A transfer is entirely numbers and two resource ids, so every way of
   * getting it wrong is silent at runtime: it simply moves nothing. */
  transferResource: (registry, effect, label) => {
    const errors = [];
    const source = effect.resourceId;
    const destination = effect.intoResourceId || effect.resourceId;
    if (!source) errors.push(label + " needs a source resourceId.");
    else if (!registry.resources[source]) {
      errors.push(label + ' transfers unknown resource "' + source + '".');
    }
    if (!registry.resources[destination]) {
      errors.push(label + ' transfers into unknown resource "' + destination + '".');
    }
    for (const key of ["from", "to"]) {
      if (effect[key] && !["source", "target"].includes(effect[key])) {
        errors.push(label + " " + key + ' must be "source" or "target".');
      }
    }
    for (const key of ["cost", "gain", "maxTransfers"]) {
      if (effect[key] == null) continue;
      if (!Number.isFinite(effect[key]) || effect[key] < 1) {
        errors.push(label + " needs a positive whole " + key + ".");
      }
    }
    // Same resource, same owner: the points would come straight back.
    const fromSide = effect.from || "source";
    const toSide = effect.to || "target";
    if (source === destination && fromSide === toSide) {
      errors.push(label + " transfers a resource to the balance it came from, which does nothing.");
    }
    return errors;
  },

  moveUnit: (registry, effect, label) => requireDistance(effect, label),
  displace: (registry, effect, label) => {
    const errors = requireDistance(effect, label);
    if (effect.heading && !HEADING_IDS.includes(effect.heading)) {
      errors.push(label + ' uses unknown heading "' + effect.heading + '".');
    }
    return errors;
  },
  push: (registry, effect, label) => requireDistance(effect, label),
  pull: (registry, effect, label) => requireDistance(effect, label),
  teleport: () => [],
  swapPositions: () => [],
  restoreResource: (registry, effect, label) => requireResource(effect, label),
  spendResource: (registry, effect, label) => requireResource(effect, label),
  createTerrain: (registry, effect, label) =>
    registry.terrains[effect.terrainId]
      ? []
      : [label + " references unknown terrain " + effect.terrainId + "."],
  removeTerrain: () => [],
  spawnUnit: (registry, effect, label) =>
    registry.units[effect.definitionId]
      ? []
      : [label + " references unknown unit definition " + effect.definitionId + "."],
  despawnUnit: () => [],
  revive: (registry, effect, label) =>
    effect.percent == null && effect.amount == null
      ? [label + " needs a revive amount or percent."]
      : [],
  transformUnit: (registry, effect, label) =>
    registry.units[effect.definitionId]
      ? []
      : [label + " references unknown transform definition " + effect.definitionId + "."],
  copyStatus: () => [],
  transferStatus: () => [],
  cleanse: () => [],
  dispel: () => [],
  delayedEffect: (registry, effect, label) =>
    Array.isArray(effect.effects)
      ? validateEffectList(registry, effect.effects, label + " (delayed)")
      : [label + " needs an effects list."],
  conditionalEffect: (registry, effect, label) => {
    const errors = validateConditionList(registry, effect.conditions, label);
    errors.push(...validateEffectList(registry, effect.ifTrue || [], label + " (ifTrue)"));
    errors.push(...validateEffectList(registry, effect.ifFalse || [], label + " (ifFalse)"));
    return errors;
  },
  refreshActivationResource: (registry, effect, label) => {
    const errors = [];
    if (effect.resource && !["move", "action"].includes(effect.resource)) {
      errors.push(label + " refreshes an unknown activation resource.");
    }
    if (effect.maxPerActivation != null && !(effect.maxPerActivation > 0)) {
      errors.push(label + " needs a positive refund limit.");
    }
    return errors;
  },

  repeatEffect: (registry, effect, label) => {
    const errors = [];
    if (!(effect.count > 0)) errors.push(label + " needs a positive repeat count.");
    errors.push(...validateEffectList(registry, effect.effects || [], label + " (repeat)"));
    return errors;
  },
  propagate: (registry, effect, label) => {
    const errors = [];
    if (!(effect.effects || []).length) {
      errors.push(label + " propagates but applies nothing to what it reaches.");
    }
    errors.push(...validateEffectList(registry, effect.effects || [], label + " (arc)"));
    return errors;
  },
  placeFixture: (registry, effect, label) =>
    registry.fixtures && registry.fixtures[effect.definitionId]
      ? []
      : [label + " places unknown fixture " + effect.definitionId + "."],
  setFixtureState: (registry, effect, label) =>
    FIXTURE_STATES.includes(effect.state)
      ? []
      : [label + ' sets unknown fixture state "' + effect.state + '".']
};

function requireStatus(registry, effect, label) {
  return registry.statuses[effect.statusId]
    ? []
    : [label + " references unknown status " + effect.statusId + "."];
}

function requireDistance(effect, label) {
  return effect.distance == null || effect.distance > 0
    ? []
    : [label + " needs a positive distance."];
}

function requireResource(effect, label) {
  const errors = [];
  if (!effect.resourceId) errors.push(label + " needs a resource id.");
  if (!(effect.amount >= 0)) errors.push(label + " needs a non-negative amount.");
  return errors;
}

function validateConditionList(registry, conditions, label) {
  const errors = [];
  const list = normalizeConditions(conditions);
  for (const entry of list.entries) {
    if (!CONDITION_HANDLERS[entry.type]) {
      errors.push(label + " uses unknown condition " + entry.type + ".");
      continue;
    }
    if (entry.type === "chance" && (entry.value < 0 || entry.value > 1)) {
      errors.push(label + " has an out-of-range chance condition.");
    }
    if (entry.statusId && !registry.statuses[entry.statusId]) {
      errors.push(label + " condition references unknown status " + entry.statusId + ".");
    }
  }
  return errors;
}

/**
 * Elevation is optional. When present it must be a rectangular matrix of
 * finite integers matching the terrain dimensions.
 */
function validateMapElevation(map, mapId) {
  const errors = [];
  const label = "Map " + mapId;
  if (!Array.isArray(map.elevations)) {
    errors.push(label + " has no normalized elevation matrix.");
    return errors;
  }
  if (map.elevations.length !== map.height) {
    errors.push(label + " elevation row count does not match its height.");
    return errors;
  }
  map.elevations.forEach((row, y) => {
    if (!Array.isArray(row) || row.length !== map.width) {
      errors.push(label + " elevation row " + y + " does not match its width.");
      return;
    }
    row.forEach((value, x) => {
      const tile = " tile " + x + "," + y;
      if (typeof value !== "number" || !Number.isFinite(value)) {
        errors.push(label + tile + " has a non-numeric elevation.");
      } else if (!Number.isInteger(value)) {
        errors.push(label + tile + " has a non-integer elevation.");
      } else if (value < 0 && !GAME_CONFIG.grid.allowNegativeElevation) {
        errors.push(label + tile + " has a negative elevation.");
      }
    });
  });
  return errors;
}

function validateEffectList(registry, effects, label) {
  const errors = [];
  for (const effect of effects) {
    if (!EFFECT_HANDLERS[effect.type]) {
      errors.push(label + " uses unknown effect type " + effect.type + ".");
      continue;
    }
    const validator = EFFECT_VALIDATORS[effect.type];
    if (!validator) {
      errors.push(label + " has no validator for effect type " + effect.type + ".");
      continue;
    }
    errors.push(...validator(registry, effect, label));
    if (effect.chance != null && (effect.chance < 0 || effect.chance > 1)) {
      errors.push(label + " has an out-of-range chance value.");
    }
    if (effect.conditions) {
      errors.push(...validateConditionList(registry, effect.conditions, label));
    }
  }
  return errors;
}

function validateContent() {
  return collectContentIssues(CONTENT);
}

/* ---------------------------------------------------------------
 * BATTLE STATE VALIDATION
 * -------------------------------------------------------------*/

function validateBattleState(state) {
  const errors = [];
  const map = getMap(state);
  if (!map) errors.push("Battle references an unknown map.");
  const occupied = new Map();

  for (const id of state.unitOrder) {
    const unit = state.units[id];
    const label = "Unit " + id;
    if (map && !inBounds(map, unit.x, unit.y)) {
      errors.push(label + " is outside the map.");
    }
    if (!Number.isFinite(unit.currentHp)) errors.push(label + " has non-finite HP.");
    if (unit.currentHp < 0) errors.push(label + " has negative HP.");
    const stats = calculateUnitStats(state, id);
    if (unit.currentHp > stats.maxHp) errors.push(label + " exceeds max HP.");
    if (unit.alive && unit.currentHp <= 0) errors.push(label + " is alive at zero HP.");
    if (!unit.alive && unit.currentHp > 0) errors.push(label + " is defeated above zero HP.");
    if (!Number.isFinite(unit.nextActionTime)) {
      errors.push(label + " has a non-finite next action time.");
    }
    for (const applied of unit.statuses) {
      if (!CONTENT.statuses[applied.statusId]) {
        errors.push(label + " has an unknown status " + applied.statusId + ".");
      }
      if (!Number.isFinite(applied.remaining) || applied.remaining <= 0) {
        errors.push(label + " has an invalid status duration.");
      }
    }
    if (unit.alive) {
      const key = tileKey(unit.x, unit.y);
      if (occupied.has(key)) {
        errors.push("Tile " + key + " holds more than one living unit.");
      }
      occupied.set(key, id);
    }
  }

  if (state.activeUnitId) {
    const active = state.units[state.activeUnitId];
    if (!active) errors.push("Active unit does not exist.");
    else if (!active.alive) errors.push("Active unit is defeated.");
    if (state.finished) errors.push("A finished battle still has an active unit.");
  }

  for (const event of state.resolutionQueue) {
    if (!event || typeof event.type !== "string") {
      errors.push("Resolution queue holds a malformed event.");
    } else if (!EVENT_HANDLERS[event.type]) {
      errors.push("Resolution queue holds an unhandled event type " + event.type + ".");
    }
  }

  if (state.finished) {
    const alive = livingUnits(state);
    const teams = new Set(alive.map((u) => u.teamId));
    if (state.winner && teams.size === 1 && [...teams][0] !== state.winner) {
      errors.push("Winner does not match the surviving team.");
    }
    if (state.winner && teams.size > 1) {
      const handler = OBJECTIVE_HANDLERS[state.objectiveState.objectiveId];
      if (handler && handler.requiresElimination) {
        errors.push("A winner was declared while multiple teams survive.");
      }
    }
  }

  if (!Number.isFinite(state.currentTime)) errors.push("Battle time is non-finite.");
  errors.push(...state.errors);

  return { valid: errors.length === 0, errors };
}

/* ---------------------------------------------------------------
 * ARCHITECTURE AUDIT
 * -------------------------------------------------------------*/

const ENGINE_FUNCTIONS = {
  deepFreeze,
  deriveIds,
  buildContentRegistry,
  createRandomState,
  randomFloat,
  randomInt,
  rollChance,
  calculateUnitStats,
  turnRateOf,
  getMap,
  inBounds,
  terrainAt,
  isWalkable,
  unitAt,
  isTileFree,
  neighborsOf,
  computeMovementRange,
  findPath,
  pathCost,
  validatePath,
  hasLineOfSight,
  tilesInArea,
  unitAtProjected,
  createBattle,
  flankProfile,
  attackArcAgainstFacing,
  logLine,
  unitLabel,
  livingUnits,
  isHostile,
  compareTimelineEntries,
  timelineCandidates,
  getNextActionableUnitId,
  previewTimeline,
  resolveTargetTile,
  evaluateTargeting,
  effectContextStats,
  resolveDamageEffect,
  resolveHealEffect,
  resolveApplyStatusEffect,
  resolveRemoveStatusEffect,
  resolveModifyTimelineEffect,
  resolveEffects,
  hasBlockingStatus,
  runStatusTriggers,
  tickStatusDurations,
  queueEvent,
  emitBattleTrigger,
  snapshotForEvents,
  processNextEvent,
  processAllEvents,
  endActivation,
  abilityRecovery,
  endTurnBaseRecovery,
  shouldAutomaticallyEndActivation,
  finishActivationIfComplete,
  movementRecoveryFor,
  projectNextActionTime,
  buildAbilityPreview,
  validateCommand,
  executeCommand,
  checkObjectives,
  aiProfileFor,
  enumerateAiTargets,
  tilePositionScore,
  scoreAbilityCandidate,
  chooseAiCommands,
  beginNextActivation,
  runAiTurn,
  runActivation,
  runBattle,
  validateBattleState,
  // The route surface. Listed explicitly so the "no concrete content ids"
  // audit reads it: a charge is exactly the kind of mechanic that grows an
  // `if (abilityId === …)` if nothing is watching.
  trajectoryDeps,
  planUnitTrajectory,
  trajectoryRules,
  trajectoryResourceCost,
  trajectoryHasRunway,
  revalidateSegment,
  executeTrajectory,
  queueTrajectoryCompleted,
  resolveTrajectoryContact,
  resolveDisplaceEffect,
  effectScaling,
  straightSegmentTo,
  routeEndpoint,
  createRoutePlanModel,
  describeRouteContact,
  // The chain surface, for the same reason: a search over live positions is
  // exactly where a content id would hide.
  propagationRules,
  propagationDeps,
  planUnitPropagation,
  propagatingAbility,
  propagationContextOf,
  resolvePropagateEffect,
  createChainPreviewModel,
  // The fixture surface. A thing that sits on a tile and belongs to somebody is
  // exactly where an `if (fixtureId === …)` would hide.
  fixtureDefinition,
  fixtureTriggeredBy,
  triggerFixturesAt,
  firstFixtureContactOnPath,
  resolveFixtureActivation,
  resolvePlaceFixtureEffect,
  resolveSetFixtureStateEffect,
  fixtureTargetingRules,
  fixtureActivationEligibility,
  activatableFixtures,
  fixtureActivationTargets,
  visibleFixturesFor
};

function engineSourceEntries() {
  const entries = [];
  for (const name of Object.keys(ENGINE_FUNCTIONS)) {
    entries.push({ name, source: ENGINE_FUNCTIONS[name].toString() });
  }
  const registries = {
    STAT_LAYERS,
    AREA_SHAPES,
    TARGET_FILTERS,
    EFFECT_HANDLERS,
    EVENT_HANDLERS,
    COMMAND_VALIDATORS,
    COMMAND_HANDLERS,
    OBJECTIVE_HANDLERS
  };
  for (const registryName of Object.keys(registries)) {
    const registry = registries[registryName];
    const members = Array.isArray(registry) ? registry : Object.values(registry);
    members.forEach((fn, index) => {
      entries.push({
        name: registryName + "[" + index + "]",
        source: fn.toString()
      });
    });
  }
  return entries;
}

function contentIdList() {
  const ids = [];
  for (const category of [
    "units",
    "abilities",
    "statuses",
    "terrains",
    "maps",
    "encounters",
    "aiProfiles",
    "equipment",
    "presentationAssets"
  ]) {
    ids.push(...Object.keys(CONTENT[category]));
  }
  return [...new Set(ids)];
}

function auditArchitecture() {
  const failures = [];
  const checks = [];
  const record = (label, ok, detail) => {
    checks.push({ label, ok, detail: detail || "" });
    if (!ok) failures.push(label + (detail ? ": " + detail : ""));
  };

  const sources = engineSourceEntries();
  const ids = contentIdList();
  const presentationSources =
    typeof PRESENTATION_FUNCTIONS === "undefined"
      ? []
      : Object.keys(PRESENTATION_FUNCTIONS).map((name) => ({
          name: "presentation." + name,
          source: PRESENTATION_FUNCTIONS[name].toString()
        }));
  const uiSources =
    typeof UI_COMPONENTS === "undefined"
      ? []
      : Object.keys(UI_COMPONENTS).map((name) => ({
          name: "ui." + name,
          source: UI_COMPONENTS[name].toString()
        }));

  // 1. No concrete content ids inside engine or preview-helper code.
  const idHits = [];
  for (const entry of sources.concat(presentationSources)) {
    for (const id of ids) {
      const pattern = new RegExp("[\"'`]" + id + "[\"'`]");
      if (pattern.test(entry.source)) idHits.push(entry.name + " -> " + id);
    }
  }
  record("Engine contains no concrete content ids", idHits.length === 0, idHits.join(", "));

  // 2. No renderer dependency.
  const renderHits = sources
    .filter((entry) => /\bReact\b|useState|useEffect|document\.|window\./.test(entry.source))
    .map((entry) => entry.name);
  record("Engine never references React or the DOM", renderHits.length === 0, renderHits.join(", "));

  // 3. Headless simulation.
  let headless = false;
  let headlessDetail = "";
  try {
    const probe = createBattle(Object.keys(CONTENT.encounters)[0], 777);
    const outcome = runBattle(probe, 400);
    headless = outcome.finished === true;
    headlessDetail = "winner=" + outcome.winner + " activations=" + outcome.activations;
  } catch (error) {
    headlessDetail = String(error.message);
  }
  record("Battle engine simulates headlessly", headless, headlessDetail);

  // 4. Balance math is centralized in the formula registry.
  const mathHits = sources
    .filter((entry) => /Math\.pow\(|speedExponent|referenceSpeed/.test(entry.source))
    .map((entry) => entry.name);
  record("Balance math lives only in FORMULAS", mathHits.length === 0, mathHits.join(", "));

  // 5. Static definitions are not copied into runtime units.
  const sample = createBattle(Object.keys(CONTENT.encounters)[0], 1);
  const runtimeKeys = Object.keys(sample.units[sample.unitOrder[0]]);
  const forbidden = ["name", "baseStats", "abilities", "glyph", "classId", "targeting"];
  const copied = runtimeKeys.filter((key) => forbidden.includes(key));
  record("Runtime units hold only mutable state", copied.length === 0, copied.join(", "));

  // 6/7. Registered handlers.
  const effectTypes = new Set();
  for (const ability of Object.values(CONTENT.abilities)) {
    for (const effect of ability.effects) effectTypes.add(effect.type);
  }
  for (const status of Object.values(CONTENT.statuses)) {
    for (const trigger of status.triggers) {
      for (const effect of trigger.effects || []) effectTypes.add(effect.type);
    }
  }
  const missingEffects = [...effectTypes].filter((type) => !EFFECT_HANDLERS[type]);
  record(
    "Effects resolve through the handler registry",
    missingEffects.length === 0 && /EFFECT_HANDLERS\[/.test(resolveEffects.toString()),
    missingEffects.join(", ")
  );
  const missingObjectives = Object.values(CONTENT.encounters)
    .map((encounter) => encounter.objective)
    .filter((objective) => !OBJECTIVE_HANDLERS[objective]);
  record(
    "Objectives resolve through the handler registry",
    missingObjectives.length === 0 &&
      /OBJECTIVE_HANDLERS\[/.test(checkObjectives.toString()),
    missingObjectives.join(", ")
  );

  // 8. Seeded randomness only.
  const randomHits = sources
    .filter((entry) => /Math\.random\(/.test(entry.source))
    .map((entry) => entry.name);
  record("Randomness is seeded", randomHits.length === 0, randomHits.join(", "));

  // 9. Ids derive from object keys.
  const idMismatches = [];
  for (const category of ["units", "abilities", "statuses", "terrains", "maps", "encounters", "aiProfiles"]) {
    for (const key of Object.keys(CONTENT[category])) {
      if (CONTENT[category][key].id !== key) idMismatches.push(category + "." + key);
    }
  }
  const sourceHasId = [UNITS, ABILITIES, STATUSES, TERRAINS, MAPS, ENCOUNTERS, AI_PROFILES, ASSETS]
    .flatMap((group) => Object.entries(group))
    .filter(([, entry]) => Object.prototype.hasOwnProperty.call(entry, "id"))
    .map(([key]) => key);
  record(
    "Content ids derive from object keys",
    idMismatches.length === 0 && sourceHasId.length === 0,
    idMismatches.concat(sourceHasId).join(", ")
  );

  // 10. Timeline preview is pure.
  const previewProbe = createBattle(Object.keys(CONTENT.encounters)[0], 4242);
  const beforePreview = JSON.stringify(previewProbe);
  previewTimeline(previewProbe, 15);
  record(
    "Timeline preview does not mutate state",
    beforePreview === JSON.stringify(previewProbe)
  );

  // 11. Commands validate before mutating.
  const commandProbe = createBattle(Object.keys(CONTENT.encounters)[0], 99);
  const beforeCommand = JSON.stringify(commandProbe);
  executeCommand(commandProbe, {
    type: "move",
    unitId: commandProbe.unitOrder[0],
    path: [{ x: -5, y: -5 }, { x: -4, y: -5 }]
  });
  record(
    "Invalid commands never mutate state",
    beforeCommand === JSON.stringify(commandProbe) &&
      /validateCommand\(/.test(executeCommand.toString())
  );

  // 12. The renderer never recomputes a rule for itself.
  if (uiSources.length) {
    const forbidden = [
      /FORMULAS\./,
      /Math\.pow\(/,
      /EFFECT_HANDLERS/,
      /TARGET_FILTERS/,
      /AREA_SHAPES/,
      /randomFloat\(/,
      /randomInt\(/,
      /rollChance\(/,
      /hitChance\(/,
      /hasLineOfSight\(/,
      /evaluateTargeting\(/,
      /computeMovementRange\(/,
      /findPath\(/,
      /chooseAiCommands\(/,
      /calculateUnitStats\(/,
      /resolveEffects\(/,
      /queueEvent\(/,
      /CONDITION_HANDLERS/,
      /TARGET_FILTER_HANDLERS/
    ];
    const uiHits = [];
    for (const entry of uiSources) {
      for (const pattern of forbidden) {
        if (pattern.test(entry.source)) uiHits.push(entry.name + " -> " + pattern.source);
      }
    }
    record(
      "Renderer never computes damage, hit chance, movement, targets or AI itself",
      uiHits.length === 0,
      uiHits.join(", ")
    );
  } else {
    record(
      "Renderer never computes damage, hit chance, movement, targets or AI itself",
      true,
      "skipped: renderer not loaded (headless run)"
    );
  }

  // 13. Preview helpers are pure.
  if (typeof PURE_PREVIEW_HELPERS !== "undefined") {
    const pureProbe = createBattle(Object.keys(CONTENT.encounters)[0], 31415);
    runActivation(pureProbe);
    const impure = [];
    for (const name of Object.keys(PURE_PREVIEW_HELPERS)) {
      const snapshot = JSON.stringify(pureProbe);
      PURE_PREVIEW_HELPERS[name](pureProbe);
      if (JSON.stringify(pureProbe) !== snapshot) impure.push(name);
    }
    record("Preview helpers are pure", impure.length === 0, impure.join(", "));
  } else {
    record("Preview helpers are pure", true, "skipped: presentation layer not loaded");
  }

  // 14. Presentation state never leaks into authoritative battle state.
  const uiOnlyFields = [
    "hoveredTile",
    "selectedAbilityId",
    "openPanel",
    "animationSpeed",
    "targetPreview",
    "cursor",
    "cursorPosition",
    "inspectedUnitId",
    "selectedUnitId",
    "plannedPath",
    "mode",
    "presentationQueue"
  ];
  const leakProbe = createBattle(Object.keys(CONTENT.encounters)[0], 271);
  runActivation(leakProbe);
  const stateLeaks = uiOnlyFields.filter((field) =>
    Object.prototype.hasOwnProperty.call(leakProbe, field)
  );
  for (const id of leakProbe.unitOrder) {
    for (const field of uiOnlyFields) {
      if (Object.prototype.hasOwnProperty.call(leakProbe.units[id], field)) {
        stateLeaks.push(id + "." + field);
      }
    }
  }
  record("Presentation state stays out of battle state", stateLeaks.length === 0, stateLeaks.join(", "));

  // 15. Asset data never reaches battle rules.
  const assetPatterns = [
    /https?:\/\//,
    /\.(png|jpe?g|webp|svg|gif)\b/,
    /\bASSETS\b/,
    /new Image\(/,
    /resolveAsset\(/,
    /getAsset\(/
  ];
  const assetHits = [];
  for (const entry of sources) {
    for (const pattern of assetPatterns) {
      if (pattern.test(entry.source)) assetHits.push(entry.name + " -> " + pattern.source);
    }
  }
  const runtimeAssetKeys = Object.keys(leakProbe.units[leakProbe.unitOrder[0]]).filter((key) =>
    ["assets", "portrait", "icon", "sprite", "image"].includes(key)
  );
  record(
    "Asset references never enter battle rules",
    assetHits.length === 0 && runtimeAssetKeys.length === 0,
    assetHits.concat(runtimeAssetKeys).join(", ")
  );

  // 16. Engine events stay serializable.
  const serialProbe = createBattle(Object.keys(CONTENT.encounters)[0], 8080);
  const captured = [];
  runBattle(serialProbe, 400, {
    onEvent: (event) => captured.push(event)
  });
  let serializable = captured.length > 0;
  let serialDetail = captured.length + " events";
  try {
    for (const event of captured) {
      if (JSON.stringify(JSON.parse(JSON.stringify(event))) !== JSON.stringify(event)) {
        serializable = false;
        serialDetail = "event " + event.type + " did not round-trip";
        break;
      }
    }
  } catch (error) {
    serializable = false;
    serialDetail = String(error.message);
  }
  record("Engine events remain serializable", serializable, serialDetail);

  // 17. The engine never calls the presentation layer.
  if (presentationSources.length) {
    const presentationNames = Object.keys(PRESENTATION_FUNCTIONS);
    const callHits = [];
    for (const entry of sources) {
      for (const name of presentationNames) {
        if (new RegExp("\\b" + name + "\\s*\\(").test(entry.source)) {
          callHits.push(entry.name + " -> " + name);
        }
      }
    }
    record("Engine never calls presentation code", callHits.length === 0, callHits.join(", "));
  } else {
    record("Engine never calls presentation code", true, "skipped: presentation layer not loaded");
  }

  // 18. Abilities never close an activation by themselves.
  const abilitySource = COMMAND_HANDLERS.useAbility.toString();
  const fakeActed = { activation: { moved: false, acted: true, ended: false, waited: false } };
  const fakeBoth = { activation: { moved: true, acted: true, ended: false, waited: false } };
  record(
    "Ability commands never end an activation on their own",
    !/pendingEnd/.test(abilitySource) &&
      shouldAutomaticallyEndActivation(fakeActed) === false &&
      shouldAutomaticallyEndActivation(fakeBoth) === true,
    "acted-only stays open, moved+acted closes"
  );

  // 19. Movement and action resources are independent.
  const resourceProbe = createBattle(Object.keys(CONTENT.encounters)[0], 5150);
  beginNextActivation(resourceProbe);
  const activationKeys = resourceProbe.activation ? Object.keys(resourceProbe.activation) : [];
  const requiredKeys = ["moved", "acted", "movementRecovery", "actionRecovery"];
  const missingKeys = requiredKeys.filter((key) => !activationKeys.includes(key));
  record(
    "Movement and action resources are tracked independently",
    missingKeys.length === 0,
    missingKeys.length ? "missing " + missingKeys.join(", ") : activationKeys.join(", ")
  );

  // 20. End Turn is generic and configuration driven.
  const endTurnSource = endTurnBaseRecovery.toString();
  record(
    "End Turn is generic and configuration driven",
    !!COMMAND_VALIDATORS.endTurn &&
      !!COMMAND_HANDLERS.endTurn &&
      !/[0-9]/.test(endTurnSource) &&
      ids.every((id) => !endTurnSource.includes('"' + id + '"')),
    "recovery values come from GAME_CONFIG.timeline"
  );

  // 21. Presentation metadata never reaches the engine.
  const metadataHits = [];
  for (const entry of sources) {
    if (/\.ui\b|defaultAbilityId|abilityUi\(/.test(entry.source)) metadataHits.push(entry.name);
  }
  record(
    "Ability categories stay presentation metadata",
    metadataHits.length === 0,
    metadataHits.join(", ")
  );

  // 22. Combined command validation runs on a clone.
  let atomic = true;
  let atomicDetail = "skipped: presentation layer not loaded";
  if (typeof validateCommandSequence === "function") {
    const atomicProbe = createBattle(Object.keys(CONTENT.encounters)[0], 4242);
    const nextId = getNextActionableUnitId(atomicProbe);
    const snapshot = JSON.stringify(atomicProbe);
    const outcome = validateCommandSequence(atomicProbe, [
      { type: "activateUnit", unitId: nextId },
      { type: "wait", unitId: nextId }
    ]);
    atomic = outcome.valid && JSON.stringify(atomicProbe) === snapshot;
    atomicDetail = "sequence validated without mutating authoritative state";
  }
  record("Command sequences validate against a clone", atomic, atomicDetail);

  // 23. Effects, conditions, shapes and filters are registry driven.
  const registryGaps = [];
  for (const type of Object.keys(EFFECT_HANDLERS)) {
    if (!EFFECT_VALIDATORS[type]) registryGaps.push("validator:" + type);
    if (typeof EFFECT_FORECASTERS !== "undefined" && !EFFECT_FORECASTERS[type]) {
      registryGaps.push("forecaster:" + type);
    }
    if (!EFFECT_METADATA[type]) registryGaps.push("metadata:" + type);
  }
  for (const category of ["abilities", "statuses"]) {
    for (const id of Object.keys(CONTENT[category])) {
      const definition = CONTENT[category][id];
      const lists = definition.effects
        ? [definition.effects]
        : (definition.triggers || []).map((trigger) => trigger.effects || []);
      for (const list of lists) {
        for (const effect of list) {
          if (!EFFECT_HANDLERS[effect.type]) registryGaps.push("handler:" + effect.type);
        }
      }
    }
  }
  record(
    "Effects, conditions, shapes and filters stay registry driven",
    registryGaps.length === 0 &&
      Object.keys(CONDITION_HANDLERS).length > 0 &&
      Object.keys(AREA_SHAPES).length >= 10 &&
      Object.keys(TARGET_FILTER_HANDLERS).length >= 11,
    registryGaps.length
      ? registryGaps.join(", ")
      : Object.keys(EFFECT_HANDLERS).length +
        " effects, " +
        Object.keys(CONDITION_HANDLERS).length +
        " conditions, " +
        Object.keys(AREA_SHAPES).length +
        " shapes, " +
        Object.keys(TARGET_FILTER_HANDLERS).length +
        " filters"
  );

  // 24. Temporary modifiers never touch base definitions.
  const modifierProbe = createBattle(Object.keys(CONTENT.encounters)[0], 606);
  const definitionSnapshot = JSON.stringify(CONTENT.units);
  const probeUnitId = modifierProbe.unitOrder[0];
  modifierProbe.units[probeUnitId].modifiers.push({
    id: "audit-modifier",
    stat: "speed",
    mode: "multiplier",
    value: 2,
    duration: null,
    remainingDuration: null
  });
  const boosted = calculateUnitStats(modifierProbe, probeUnitId).speed;
  modifierProbe.units[probeUnitId].modifiers = [];
  const restored = calculateUnitStats(modifierProbe, probeUnitId).speed;
  record(
    "Temporary modifiers never mutate base definitions",
    JSON.stringify(CONTENT.units) === definitionSnapshot && boosted === restored * 2,
    "modifier layer applied and removed cleanly"
  );

  // 25. Summons use the generic runtime factory.
  const spawnProbe = createBattle(Object.keys(CONTENT.encounters)[0], 4242);
  const spawnSource = createRuntimeUnit.toString();
  const spawnIdHits = ids.filter((id) => spawnSource.includes('"' + id + '"'));
  const spawned = createRuntimeUnit(spawnProbe, {
    definitionId: spawnProbe.units[spawnProbe.unitOrder[0]].definitionId,
    teamId: spawnProbe.teams[0].id,
    x: 0,
    y: 0
  });
  record(
    "Summons are created through the generic runtime factory",
    spawnIdHits.length === 0 && !!spawned.id && spawned.id !== spawnProbe.unitOrder[0],
    spawnIdHits.join(", ")
  );

  // 26. Panel opacity comes from configuration, not component literals.
  if (typeof createPanelStyle === "function") {
    const configured = GAME_CONFIG.presentation.panels;
    const style = createPanelStyle("primary");
    const literalHits = [];
    for (const entry of uiSources) {
      if (/rgba\(2,\s*6,\s*23/.test(entry.source)) literalHits.push(entry.name);
    }
    record(
      "Panel opacity comes from presentation configuration",
      literalHits.length === 0 &&
        style.backgroundColor.includes(String(configured.primaryBackgroundOpacity)),
      literalHits.join(", ")
    );
  } else {
    record(
      "Panel opacity comes from presentation configuration",
      true,
      "skipped: presentation layer not loaded"
    );
  }

  // 27. Danger zones and contextual choices reuse engine helpers.
  if (typeof calculateUnitThreatZone === "function") {
    const threatSources = [
      calculateAbilityThreatTiles,
      calculateUnitThreatZone,
      createContextualTargetOptions,
      resolveContextualSelection,
      scoreContextualOption
    ].map((fn) => fn.toString());
    const forbidden = [/FORMULAS\./, /rollChance\(/, /randomFloat\(/, /EFFECT_HANDLERS/];
    const hits = [];
    for (const source of threatSources) {
      for (const pattern of forbidden) {
        if (pattern.test(source)) hits.push(pattern.source);
      }
      for (const id of ids) {
        if (source.includes('"' + id + '"')) hits.push("content id " + id);
      }
    }
    const usesEngine =
      /tilesInArea\(/.test(threatSources[0]) &&
      /hasLineOfSight\(/.test(threatSources[0]) &&
      /enumerateValidMoveDestinations\(/.test(threatSources[1]);
    record(
      "Danger zones and contextual choices use engine helpers only",
      hits.length === 0 && usesEngine,
      hits.join(", ")
    );
  } else {
    record(
      "Danger zones and contextual choices use engine helpers only",
      true,
      "skipped: presentation layer not loaded"
    );
  }

  // 28. Elevation is map content; camera data never reaches battle state.
  const elevationProbe = createBattle(Object.keys(CONTENT.encounters)[0], 31);
  const cameraFields = ["camera", "zoom", "panX", "panY", "projection", "tileSize", "elevations"];
  const cameraLeaks = cameraFields.filter((field) =>
    Object.prototype.hasOwnProperty.call(elevationProbe, field)
  );
  const mapsWithElevation = Object.keys(CONTENT.maps).filter((mapId) =>
    Array.isArray(CONTENT.maps[mapId].elevations)
  );
  record(
    "Elevation is map content and camera state stays out of battle state",
    cameraLeaks.length === 0 && mapsWithElevation.length === Object.keys(CONTENT.maps).length,
    cameraLeaks.join(", ")
  );

  // 29. One traversal helper answers every movement question.
  const traversalConsumers = {
    computeMovementRange,
    pathCost,
    validatePath,
    resolveForcedMovement
  };
  const traversalGaps = [];
  for (const name of Object.keys(traversalConsumers)) {
    if (!/evaluateTraversalStep\(/.test(traversalConsumers[name].toString())) {
      traversalGaps.push(name);
    }
  }
  const duplicateClimbChecks = [];
  for (const entry of sources) {
    // The registry only supplies defaults; the traversal helper owns the rule.
    if (entry.name === "evaluateTraversalStep" || entry.name === "buildContentRegistry") continue;
    if (/maxClimb|maxDrop/.test(entry.source)) duplicateClimbChecks.push(entry.name);
  }
  const climbProbe = createBattle(Object.keys(CONTENT.encounters)[0], 77);
  const climbUnitId = climbProbe.unitOrder[0];
  const baseClimb = calculateUnitStats(climbProbe, climbUnitId).maxClimb;
  climbProbe.units[climbUnitId].modifiers.push({
    id: "audit-climb",
    stat: "maxClimb",
    mode: "flat",
    value: 2,
    duration: null,
    remainingDuration: null
  });
  const boostedClimb = calculateUnitStats(climbProbe, climbUnitId).maxClimb;
  record(
    "Movement, validation and forced movement share one traversal rule",
    traversalGaps.length === 0 &&
      duplicateClimbChecks.length === 0 &&
      boostedClimb === baseClimb + 2,
    traversalGaps.concat(duplicateClimbChecks).join(", ")
  );

  // 30. The engine never reads projection or camera data.
  const projectionNames =
    typeof CAMERA_FUNCTIONS === "undefined" ? [] : Object.keys(CAMERA_FUNCTIONS);
  const projectionHits = [];
  for (const entry of sources) {
    if (/\bcamera\b|panX|panY|worldToScreen|screenToWorld|tileWidth|elevationHeight/.test(entry.source)) {
      projectionHits.push(entry.name);
    }
    for (const name of projectionNames) {
      if (new RegExp("\\b" + name + "\\s*\\(").test(entry.source)) {
        projectionHits.push(entry.name + " -> " + name);
      }
    }
  }
  record(
    "Engine functions never read projection or camera data",
    projectionHits.length === 0,
    projectionHits.join(", ")
  );

  // 31. Projection helpers are pure and battlefield components never multiply
  // grid coordinates into pixels.
  if (projectionNames.length) {
    const purityProbe = createBattle(Object.keys(CONTENT.encounters)[0], 8181);
    const snapshot = JSON.stringify(purityProbe);
    const map = CONTENT.maps[CONTENT.encounters[purityProbe.encounterId].mapId];
    calculateProjectedMapBounds(map);
    projectTileToWorld({ x: 1, y: 2, elevation: 1 });
    fitCameraToMap(map, { width: 800, height: 600 });
    const pixelHits = [];
    for (const entry of uiSources) {
      if (/\.[xy]\s*\*\s*(size|tileSize)\b/.test(entry.source)) pixelHits.push(entry.name);
    }
    record(
      "Projection helpers are pure and no component multiplies tiles into pixels",
      JSON.stringify(purityProbe) === snapshot && pixelHits.length === 0,
      pixelHits.join(", ")
    );
  } else {
    record(
      "Projection helpers are pure and no component multiplies tiles into pixels",
      true,
      "skipped: projection layer not loaded"
    );
  }


  // 32. Campaign deployment is roster-owned and guests are mission data.
  if (typeof createCampaignDeploymentState === "function") {
    const campaignProbe = createCampaignState();
    const openingDeployment = createCampaignDeploymentState(campaignProbe, "act1-01-hollowmere-perimeter");
    const openingIds = openingDeployment.candidates.map((entry) => entry.operatorId);
    const jailbreakDeployment = createCampaignDeploymentState(campaignProbe, "act1-08-jailbreak");
    const guest = jailbreakDeployment.candidates.find((entry) => entry.guest);
    record(
      "Campaign deployment cannot access unowned operators",
      openingIds.every((operatorId) => !!campaignProbe.roster[operatorId]) &&
        !openingIds.includes("nyx") &&
        !!guest && guest.operatorId === "nyx",
      openingIds.join(", ")
    );
  } else {
    record("Campaign deployment cannot access unowned operators", true, "skipped: campaign layer not loaded");
  }

  // 33. Campaign equipment comes from owned physical copies.
  if (typeof equipCampaignPart === "function") {
    const campaignProbe = createCampaignState();
    const deploymentProbe = createCampaignDeploymentState(campaignProbe, "act1-01-hollowmere-perimeter");
    const before = JSON.stringify(deploymentProbe.loadouts);
    const blockedEquip = equipCampaignPart(
      campaignProbe,
      deploymentProbe,
      "vale",
      "coreSystem",
      "overclockCore"
    );
    record(
      "Campaign equipment cannot access unowned items",
      JSON.stringify(blockedEquip.loadouts) === before &&
        !!blockedEquip.error &&
        !campaignProbe.inventory.overclockCore,
      blockedEquip.error || ""
    );
  } else {
    record("Campaign equipment cannot access unowned items", true, "skipped: campaign layer not loaded");
  }

  // 34. Generic campaign helpers contain no concrete mission/operator/equipment ids.
  if (typeof createCampaignDeploymentState === "function") {
    const campaignSources = [
      campaignDeploymentCandidates,
      createCampaignDeploymentState,
      campaignInventoryForSlot,
      toggleCampaignOperator,
      equipCampaignPart,
      validateCampaignDeployment,
      createCampaignDeploymentPreview,
      createCampaignMissionRoster,
      commitCampaignDeployment,
      createStorySceneModel,
      createStorySequenceModel,
      storyConditionMet,
      collectMissionFacts,
      resolveMissionOutcome
    ].map((fn) => ({ name: fn.name, source: fn.toString() }));
    const campaignIds = [
      ...Object.keys(CAMPAIGN.missions),
      ...Object.keys(CAMPAIGN.operators),
      ...Object.keys(CONTENT.equipment)
    ];
    const campaignIdHits = [];
    for (const entry of campaignSources) {
      for (const id of campaignIds) {
        const pattern = new RegExp("[\\\"'`]" + id + "[\\\"'`]");
        if (pattern.test(entry.source)) campaignIdHits.push(entry.name + " -> " + id);
      }
    }
    record(
      "Generic campaign helpers contain no concrete content ids",
      campaignIdHits.length === 0,
      campaignIdHits.join(", ")
    );
  } else {
    record("Generic campaign helpers contain no concrete content ids", true, "skipped: campaign layer not loaded");
  }

  // 35. Story view models only read campaign/outcome data.
  if (typeof createStorySceneModel === "function") {
    const storySources = [
      createStorySceneModel,
      createStorySequenceModel,
      createStoryProgress,
      currentStoryProgress,
      chooseStoryProgress,
      advanceStoryProgress
    ].map((fn) => fn.toString()).join("\n");
    const forbiddenStoryCalls = ["executeCommand(", "resolveEffects(", "runBattle(", "checkObjectives("]
      .filter((token) => storySources.includes(token));
    record(
      "Story presentation cannot mutate battle state",
      forbiddenStoryCalls.length === 0,
      forbiddenStoryCalls.join(", ")
    );
  } else {
    record("Story presentation cannot mutate battle state", true, "skipped: story layer not loaded");
  }

  // 36. Hollowmere flags come from authoritative battle facts, not the dialogue promise.
  if (typeof collectMissionFacts === "function") {
    const baseCampaign = applyDialogueChoice(
      createCampaignState(),
      "hollowmereApproach",
      "turretsOnly"
    );
    const cleanBattle = createBattle("missionHollowmerePerimeter", 62);
    const cleanFacts = collectMissionFacts(cleanBattle, "act1-01-hollowmere-perimeter");
    const cleanResolved = resolveMissionOutcome(baseCampaign, "act1-01-hollowmere-perimeter", {
      victory: true,
      activations: 1,
      conditions: collectMissionConditions(cleanBattle),
      facts: cleanFacts
    });

    const damagedBattle = createBattle("missionHollowmerePerimeter", 63);
    const sourceId = damagedBattle.unitOrder.find((id) => damagedBattle.units[id].teamId === "player");
    const civilianId = damagedBattle.unitOrder.find((id) =>
      (CONTENT.units[damagedBattle.units[id].definitionId].tags || []).includes("civilian")
    );
    resolveEffects(damagedBattle, {
      sourceUnitId: sourceId,
      targetUnitIds: [civilianId],
      effects: [{ type: "damage", formula: "physical", power: 30, canMiss: false }]
    });
    processAllEvents(damagedBattle);
    const damagedFacts = collectMissionFacts(damagedBattle, "act1-01-hollowmere-perimeter");
    const damagedResolved = resolveMissionOutcome(baseCampaign, "act1-01-hollowmere-perimeter", {
      victory: true,
      activations: 1,
      conditions: collectMissionConditions(damagedBattle),
      facts: damagedFacts
    });
    record(
      "Mission outcome flags are derived from authoritative result data",
      campaignFlag(baseCampaign, "intendedToSpareCivilians") &&
        campaignFlag(cleanResolved, "sparedHollowmereCivilians") &&
        !campaignFlag(damagedResolved, "sparedHollowmereCivilians") &&
        campaignFlag(damagedResolved, "hollowmereCivilianDamage"),
      "clean=" + campaignFlag(cleanResolved, "sparedHollowmereCivilians") +
        " damaged=" + campaignFlag(damagedResolved, "hollowmereCivilianDamage")
    );
  } else {
    record("Mission outcome flags are derived from authoritative result data", true, "skipped: campaign layer not loaded");
  }

  return {
    pass: failures.length === 0,
    failures,
    checks,
    summary: failures.length === 0 ? "Architecture audit: PASS" : "Architecture audit: FAIL"
  };
}


/* ---------------------------------------------------------------
 * FILE-BASED ASSET CONVENTIONS
 *
 * Drop files into public/assets using these predictable paths. The browser
 * tries WebP, PNG and JPG in order, then falls back to a readable silhouette,
 * glyph, color or text label. No game rule depends on an asset existing.
 * -------------------------------------------------------------*/
const ASSET_ROOT = "/assets";

function assetFileCandidates(pathWithoutExtension) {
  return ["webp", "png", "jpg", "jpeg"].map(
    (extension) => ASSET_ROOT + "/" + pathWithoutExtension + "." + extension
  );
}

function assetFileCandidatesForPaths(paths) {
  const candidates = [];
  for (const path of paths || []) candidates.push(...assetFileCandidates(path));
  return candidates;
}

function fallbackForUnit(definition, use, facing) {
  const tags = definition.tags || [];
  if (tags.includes("mech") || tags.includes("government") || tags.includes("deployable")) {
    return {
      type: "silhouette",
      value: definition.glyph || "M",
      label: definition.name || "Mech",
      variant: use === "portrait" ? "portrait" : "battlefield",
      facing: facing || null
    };
  }
  return { type: "glyph", value: definition.glyph || "?", label: definition.name || "Unit" };
}

function prepareAssetAwareContentSources(sources) {
  const assets = { ...(sources.presentationAssets || {}) };
  const cloneGroup = (group) => Object.fromEntries(
    Object.entries(group || {}).map(([id, value]) => [id, { ...value, assets: { ...(value.assets || {}) } }])
  );

  const units = cloneGroup(sources.units);
  for (const [id, definition] of Object.entries(units)) {
    const portraitAssetId = "unit." + id + ".portrait";
    definition.assets.portrait = portraitAssetId;
    assets[portraitAssetId] = {
      type: "image",
      src: null,
      srcCandidates: assetFileCandidates("units/" + id + "/portrait"),
      fallback: fallbackForUnit(definition, "portrait"),
      recommended: "512x512 portrait"
    };

    const battlefieldAssetId = "unit." + id + ".battlefield";
    definition.assets.battlefield = battlefieldAssetId;
    assets[battlefieldAssetId] = {
      type: "image",
      src: null,
      srcCandidates: assetFileCandidates("units/" + id + "/battlefield"),
      fallback: fallbackForUnit(definition, "battlefield"),
      recommended: "512x512 transparent generic battlefield sprite"
    };

    const directionalAliases = {
      northeast: ["battlefield-northeast", "battlefield-ne", "battlefield-back-right", "battlefield-back", "battlefield-north"],
      southeast: ["battlefield-southeast", "battlefield-se", "battlefield-front-right", "battlefield-right", "battlefield-east"],
      southwest: ["battlefield-southwest", "battlefield-sw", "battlefield-front-left", "battlefield-front", "battlefield-south"],
      northwest: ["battlefield-northwest", "battlefield-nw", "battlefield-back-left", "battlefield-left", "battlefield-west"]
    };
    for (const facing of GAME_CONFIG.facing.directions) {
      const directionalAssetId = "unit." + id + ".battlefield." + facing;
      definition.assets["battlefield" + facing[0].toUpperCase() + facing.slice(1)] =
        directionalAssetId;
      assets[directionalAssetId] = {
        type: "image",
        src: null,
        srcCandidates: assetFileCandidatesForPaths(
          directionalAliases[facing].map((name) => "units/" + id + "/" + name)
        ),
        fallback: fallbackForUnit(definition, "battlefield", facing),
        recommended:
          "512x512 transparent " +
          facing +
          "-facing battlefield sprite; if missing, the opposite-side diagonal partner will mirror automatically"
      };
    }
  }

  const abilities = cloneGroup(sources.abilities);
  for (const [id, definition] of Object.entries(abilities)) {
    const assetId = "ability." + id + ".icon";
    definition.assets.icon = assetId;
    assets[assetId] = {
      type: "image",
      src: null,
      srcCandidates: assetFileCandidates("abilities/" + id),
      fallback: { type: "glyph", value: (definition.ui && definition.ui.glyph) || "◆", label: definition.name || id },
      recommended: "128x128 transparent icon"
    };
  }

  const statuses = cloneGroup(sources.statuses);
  for (const [id, definition] of Object.entries(statuses)) {
    const assetId = "status." + id + ".icon";
    definition.assets.icon = assetId;
    assets[assetId] = {
      type: "image",
      src: null,
      srcCandidates: assetFileCandidates("statuses/" + id),
      fallback: { type: "glyph", value: definition.glyph || "•", label: definition.name || id },
      recommended: "96x96 transparent icon"
    };
  }

  const terrains = cloneGroup(sources.terrains);
  for (const [id, definition] of Object.entries(terrains)) {
    const assetId = "terrain." + id + ".tile";
    definition.assets.tile = assetId;
    // The authored swatch is the fallback colour too, so a tile with no art
    // looks the same in the map editor and in the game.
    const legacy =
      definition.paint ||
      (definition.walkable === false ? "#475569" : definition.movementCost > 1 ? "#334155" : "#1e293b");
    assets[assetId] = {
      type: "image",
      src: null,
      srcCandidates: assetFileCandidates("terrain/" + id),
      fallback: { type: "color", value: legacy, label: definition.name || id },
      recommended: "256x128 isometric tile"
    };
  }

  const equipment = cloneGroup(sources.equipment);
  for (const [id, definition] of Object.entries(equipment)) {
    const assetId = "equipment." + id + ".icon";
    definition.assets.icon = assetId;
    assets[assetId] = {
      type: "image",
      src: null,
      srcCandidates: assetFileCandidates("equipment/" + id),
      fallback: { type: "glyph", value: "🔧", label: definition.name || id },
      recommended: "128x128 transparent icon"
    };
  }

  return {
    ...sources,
    units,
    abilities,
    statuses,
    terrains,
    equipment,
    presentationAssets: assets
  };
}

function conventionAsset(id, pathWithoutExtension, fallback, recommended) {
  return {
    id,
    type: "image",
    src: null,
    srcCandidates: assetFileCandidates(pathWithoutExtension),
    value: fallback && fallback.value,
    fallback: fallback || { type: "glyph", value: "?" },
    recommended: recommended || null,
    missing: false
  };
}

/* ---------------------------------------------------------------
 * CONTENT REGISTRY INSTANCE
 * -------------------------------------------------------------*/

/* Maps and encounters authored as mission files (src/content/missions/*.json,
 * plus the editor's playtest slot) are merged in here, before the registry is
 * built and frozen. Hand-written entries win on an id collision so a stray
 * file can never shadow a built-in fixture. */
const CONTENT = buildContentRegistry(prepareAssetAwareContentSources({
  units: UNITS,
  abilities: ABILITIES,
  statuses: STATUSES,
  terrains: TERRAINS,
  maps: { ...MISSION_CONTENT.maps, ...MAPS },
  encounters: { ...MISSION_CONTENT.encounters, ...ENCOUNTERS },
  aiProfiles: AI_PROFILES,
  equipment: EQUIPMENT,
  fixtures: FIXTURE_DEFINITIONS,
  resources: RESOURCES_BY_ID,
  presentationAssets: ASSETS
}));
/* =========================================================================
 * PRESENTATION ADAPTER
 * Plain JavaScript. Knows about the engine; the engine knows nothing about
 * it. Formats engine results for a renderer and never re-implements a rule.
 * =======================================================================*/

/* ---------------------------------------------------------------
 * ASSETS
 * -------------------------------------------------------------*/

const MISSING_ASSET = {
  id: null,
  type: "glyph",
  src: null,
  value: "?",
  missing: true
};

function getAsset(assetId) {
  if (!assetId) return null;
  return CONTENT.presentationAssets[assetId] || null;
}

/**
 * Always returns a drawable descriptor, even for unknown or broken assets.
 */
function resolveAsset(assetId, fallbackValue) {
  const asset = getAsset(assetId);
  if (!asset) {
    return fallbackValue == null
      ? { ...MISSING_ASSET }
      : { id: assetId || null, type: "glyph", src: null, value: fallbackValue, missing: true };
  }
  const fallback = asset.fallback || {};
  const candidates = [asset.src, ...(asset.srcCandidates || [])].filter(Boolean);
  return {
    id: asset.id,
    type: candidates.length ? asset.type : fallback.type || "glyph",
    src: candidates[0] || null,
    srcCandidates: candidates,
    value: fallback.value == null ? (fallbackValue == null ? "?" : fallbackValue) : fallback.value,
    fallback,
    label: fallback.label || asset.id,
    recommended: asset.recommended || null,
    missing: false
  };
}

function resolveDefinitionAsset(definition, slot, fallbackValue) {
  const references = (definition && definition.assets) || {};
  return resolveAsset(references[slot], fallbackValue);
}

function directionalUnitCandidateEntries(definitionId, facing) {
  const normalized = normalizeFacing(facing);
  const pathsByFacing = {
    northeast: ["battlefield-northeast", "battlefield-ne", "battlefield-back-right", "battlefield-back", "battlefield-north"],
    southeast: ["battlefield-southeast", "battlefield-se", "battlefield-front-right", "battlefield-right", "battlefield-east"],
    southwest: ["battlefield-southwest", "battlefield-sw", "battlefield-front-left", "battlefield-front", "battlefield-south"],
    northwest: ["battlefield-northwest", "battlefield-nw", "battlefield-back-left", "battlefield-left", "battlefield-west"]
  };
  const mirrorFallbacks = {
    northeast: ["battlefield-northwest", "battlefield-nw", "battlefield-back-left", "battlefield-left", "battlefield-west"],
    southeast: ["battlefield-southwest", "battlefield-sw", "battlefield-front-left", "battlefield-front", "battlefield-south"],
    southwest: ["battlefield-southeast", "battlefield-se", "battlefield-front-right", "battlefield-right", "battlefield-east"],
    northwest: ["battlefield-northeast", "battlefield-ne", "battlefield-back-right", "battlefield-back", "battlefield-north"]
  };
  const entries = [];
  for (const path of pathsByFacing[normalized]) {
    for (const src of assetFileCandidates("units/" + definitionId + "/" + path)) {
      entries.push({ src, flipX: false });
    }
  }
  if (mirrorFallbacks[normalized]) {
    for (const path of mirrorFallbacks[normalized]) {
      for (const src of assetFileCandidates("units/" + definitionId + "/" + path)) {
        entries.push({ src, flipX: true });
      }
    }
  }
  for (const src of assetFileCandidates("units/" + definitionId + "/battlefield")) {
    entries.push({ src, flipX: false });
  }
  return entries;
}

function resolveDirectionalUnitBattlefieldAsset(definition, facing) {
  const normalized = normalizeFacing(facing);
  const slot = "battlefield" + normalized[0].toUpperCase() + normalized.slice(1);
  const directional = resolveDefinitionAsset(definition, slot, definition.glyph);
  const generic = resolveDefinitionAsset(definition, "battlefield", definition.glyph);
  return {
    ...directional,
    id: directional.id || "unit." + definition.id + ".battlefield." + normalized,
    facing: normalized,
    candidateEntries: directionalUnitCandidateEntries(definition.id, normalized),
    srcCandidates: [],
    src: null,
    fallback:
      directional.fallback ||
      generic.fallback ||
      fallbackForUnit(definition, "battlefield", normalized),
    value: directional.value || generic.value || definition.glyph,
    label: definition.name + " · facing " + normalized,
    recommended: "northeast/back-right, southeast/front-right, southwest/front-left and northwest/back-left sprites; any missing left/right diagonal will mirror its opposite-side partner automatically"
  };
}

function validateAssets() {
  const missing = [];
  const groups = [
    ["units", ["portrait", "battlefield", "battlefieldNortheast", "battlefieldSoutheast", "battlefieldSouthwest", "battlefieldNorthwest"]],
    ["abilities", ["icon"]],
    ["statuses", ["icon"]],
    ["terrains", ["tile"]]
  ];
  for (const [category, slots] of groups) {
    for (const id of Object.keys(CONTENT[category])) {
      const definition = CONTENT[category][id];
      for (const slot of slots) {
        const reference = (definition.assets || {})[slot];
        if (reference && !getAsset(reference)) {
          missing.push(category + "." + id + "." + slot + " -> " + reference);
        }
      }
    }
  }
  const unsourced = Object.keys(CONTENT.presentationAssets).filter(
    (id) => !CONTENT.presentationAssets[id].src
  );
  return { missing, unsourced, total: Object.keys(CONTENT.presentationAssets).length };
}

/** A production checklist generated from the same asset references consumed
 * by the renderer. Missing files remain valid because every row has a fallback. */
function createAssetReadinessReport() {
  const entries = [];
  const dimensions = {
    portrait: "512×512 portrait",
    battlefield: "256×256+ transparent sprite; rendered at approximately one tile wide",
    battlefieldNortheast: "256×256 northeast/back-right-facing sprite; northwest mirrors automatically when present",
    battlefieldSoutheast: "256×256 southeast/front-right-facing sprite; southwest mirrors automatically when present",
    battlefieldSouthwest: "256×256 southwest/front-left-facing sprite; southeast mirrors automatically when present",
    battlefieldNorthwest: "256×256 northwest/back-left-facing sprite; northeast mirrors automatically when present",
    icon: "64×64 transparent icon",
    tile: "256×128 isometric tile",
    storyBackground: "1920×1080 background",
    speakerPortrait: "512×512 portrait"
  };
  const groups = [
    ["units", ["portrait", "battlefield", "battlefieldNortheast", "battlefieldSoutheast", "battlefieldSouthwest", "battlefieldNorthwest"]],
    ["abilities", ["icon"]],
    ["statuses", ["icon"]],
    ["terrains", ["tile"]]
  ];
  for (const [category, slots] of groups) {
    for (const definitionId of Object.keys(CONTENT[category])) {
      const definition = CONTENT[category][definitionId];
      for (const slot of slots) {
        const assetId = (definition.assets || {})[slot] || null;
        const asset = assetId ? getAsset(assetId) : null;
        const fallback = asset && asset.fallback
          ? JSON.parse(JSON.stringify(asset.fallback))
          : { type: "glyph", value: definition.glyph || "?" };
        entries.push({
          assetId: assetId || category + "." + definitionId + "." + slot,
          category,
          definitionId,
          use: slot,
          supplied: !!(asset && asset.src),
          fallback,
          recommended: dimensions[slot]
        });
      }
    }
  }
  for (const missionId of Object.keys(CAMPAIGN.dialogue || {})) {
    const script = CAMPAIGN.dialogue[missionId];
    for (const sceneId of Object.keys(script.scenes || {})) {
      const scene = script.scenes[sceneId];
      entries.push({
        assetId: "story." + missionId + "." + sceneId,
        category: "story",
        definitionId: missionId,
        use: "storyBackground",
        supplied: false,
        fallback: { type: "locationLabel", value: scene.location || "Unknown" },
        recommended: dimensions.storyBackground
      });
    }
  }
  for (const speakerId of Object.keys(CAMPAIGN.speakers || {})) {
    const speaker = CAMPAIGN.speakers[speakerId];
    entries.push({
      assetId: "speaker." + speakerId,
      category: "story",
      definitionId: speakerId,
      use: "speakerPortrait",
      supplied: false,
      fallback: { type: "glyph", value: speaker.glyph || "?" },
      recommended: dimensions.speakerPortrait
    });
  }
  return {
    total: entries.length,
    supplied: entries.filter((entry) => entry.supplied).length,
    placeholders: entries.filter((entry) => !entry.supplied).length,
    entries
  };
}

/* ---------------------------------------------------------------
 * PRESENTATION TIMING (never affects simulation)
 * -------------------------------------------------------------*/

function getAnimationTiming(speedId) {
  const config = GAME_CONFIG.presentation;
  const speed = config.speeds[speedId] || config.speeds[config.defaultSpeedId];
  const timing = { id: speedId, name: speed.name, scale: speed.scale };
  for (const key of Object.keys(config.baseDurations)) {
    timing[key] = Math.round(config.baseDurations[key] * speed.scale);
  }
  return timing;
}

function presentationEventDuration(presentationEvent, timing) {
  switch (presentationEvent.type) {
    case "moveAnimation":
      return Math.max(0, timing.moveTile * Math.max(1, presentationEvent.path.length - 1));
    case "attackAnimation":
      return timing.attack;
    case "floatingNumber":
    case "floatingText":
      return timing.floatingNumber;
    case "statusPopup":
    case "impactAnimation":
    case "shieldAnimation":
      return timing.statusPopup;
    case "defeatAnimation":
      return timing.defeat;
    case "activationBanner":
    case "facingAnimation":
    case "timelineShift":
    case "timelineUpdate":
    case "battleEnd":
      return timing.beat;
    default:
      return timing.beat;
  }
}

/* ---------------------------------------------------------------
 * VIEW MODELS
 * -------------------------------------------------------------*/

function getUnitDisplayStats(state, unitId) {
  const unit = state.units[unitId];
  const definition = CONTENT.units[unit.definitionId];
  const stats = calculateUnitStats(state, unitId);
  const baseSpeed = definition.baseStats.speed;
  return {
    ...stats,
    maxClimb: stats.maxClimb,
    maxDrop: stats.maxDrop,
    baseSpeed,
    speedMultiplier: Math.round((stats.speed / baseSpeed) * 1000) / 1000,
    turnRate: Math.round(FORMULAS.timeline.turnRate(stats.speed) * 1000) / 1000
  };
}

function createUnitViewModel(state, unitId) {
  const unit = state.units[unitId];
  const definition = CONTENT.units[unit.definitionId];
  const stats = getUnitDisplayStats(state, unitId);
  const team = state.teams.find((t) => t.id === unit.teamId) || { id: unit.teamId };
  const activation = state.activation && state.activation.unitId === unitId ? state.activation : null;

  const viewerTeamId = state.teams.find((team) => team.controller === "human");
  const concealed = isUnitConcealed(state, unitId);
  const hiddenFromPlayer = isUnitHiddenFrom(
    state,
    unitId,
    viewerTeamId ? viewerTeamId.id : null
  );

  return {
    id: unit.id,
    definitionId: unit.definitionId,
    name: definition.name,
    concealed,
    hiddenFromPlayer,
    description: definition.description,
    classId: definition.classId,
    glyph: definition.glyph,
    portrait: resolveDefinitionAsset(definition, "portrait", definition.glyph),
    battlefieldAsset: resolveDirectionalUnitBattlefieldAsset(definition, unit.facing),
    facing: normalizeFacing(unit.facing),
    facingArrow: GAME_CONFIG.facing.arrows[normalizeFacing(unit.facing)],

    teamId: unit.teamId,
    teamName: team.name || unit.teamId,
    teamMarker: team.marker || "●",
    teamAccent: team.accent || "sky",
    controller: team.controller || "ai",
    aiProfileId: unit.aiProfileId,
    isEnemyToPlayer: viewerTeamId ? unit.teamId !== viewerTeamId.id : (team.controller || "ai") !== "human",

    x: unit.x,
    y: unit.y,
    elevation: elevationAt(getMap(state), unit.x, unit.y) || 0,
    alive: unit.alive,
    currentHp: unit.currentHp,
    maxHp: stats.maxHp,
    hpPercent: Math.max(0, Math.round((unit.currentHp / stats.maxHp) * 100)),
    stats,

    nextActionTime: unit.nextActionTime,
    isActive: state.activeUnitId === unitId,

    statuses: unit.statuses.map((applied) => {
      const definitionForStatus = CONTENT.statuses[applied.statusId];
      return {
        statusId: applied.statusId,
        name: definitionForStatus.name,
        remaining: applied.remaining,
        durationType: definitionForStatus.duration.type,
        icon: resolveDefinitionAsset(definitionForStatus, "icon", definitionForStatus.glyph)
      };
    }),

    abilities: getUnitAbilities(state, unitId).map((abilityId) => ({
      abilityId,
      name: CONTENT.abilities[abilityId].name,
      cooldownRemaining: unit.cooldowns[abilityId] || 0
    })),

    activation: activation
      ? {
          moved: activation.moved,
          acted: activation.acted,
          movementRecovery: activation.movementRecovery
        }
      : null
  };
}

function createAbilityViewModel(state, unitId, abilityId, options) {
  const opts = options || {};
  const ability = CONTENT.abilities[abilityId];
  const unit = state.units[unitId];
  const origin = opts.origin || { x: unit.x, y: unit.y };
  const cooldownRemaining = unit.cooldowns[abilityId] || 0;
  // A frame with a full rack is not a target for something that only fills
  // racks. Filtering here rather than reporting it afterwards means the
  // existing "no valid targets" path says it, in the words it already uses.
  const targets = enumerateValidAbilityTargets(state, unitId, abilityId, origin).filter(
    (target) => !transferAbilityIsIdle(state, unitId, abilityId, target.unitId || unitId)
  );

  const reasons = [];
  if (!abilityConditionsMet(state, unitId, abilityId)) {
    reasons.push(ability.requirementText || "Requirements not met.");
  }
  if (cooldownRemaining > 0) {
    reasons.push("Cooldown: " + cooldownRemaining + " activation" + (cooldownRemaining === 1 ? "" : "s"));
  }
  // What it costs is part of whether it can be used. The command validator has
  // always refused an unaffordable action; without this the model that draws
  // the button disagreed with it, and the player found out by clicking.
  // Every scope, through the same helper the validator uses. Reading only the
  // unit's own pools greyed out a squad-funded action for a frame that was
  // never going to carry the resource privately.
  reasons.push(...abilityCostProblems(state, unitId, ability));
  if (!targets.length) {
    // A route ability reaches by travelling. Judging it on who is standing next
    // to the frame right now would grey out the charge in exactly the situation
    // a charge is for, so what it needs instead is somewhere to run.
    if (ability.trajectory) {
      if (!trajectoryHasRunway(state, unitId, ability)) reasons.push("No room to run");
    } else {
      reasons.push("No valid targets in range");
    }
  }
  if (state.activeUnitId !== unitId) reasons.push("Not this unit's activation");
  if (state.activation && state.activation.unitId === unitId && state.activation.acted) {
    reasons.push("Already acted this activation.");
  }

  const model = {
    abilityId,
    name: ability.name,
    description: ability.description,
    icon: resolveDefinitionAsset(ability, "icon", ability.name[0]),
    rangeMin: ability.targeting.rangeMin,
    rangeMax: ability.targeting.rangeMax,
    rangeLabel:
      ability.targeting.rangeMin === ability.targeting.rangeMax
        ? "Range " + ability.targeting.rangeMax
        : "Range " + ability.targeting.rangeMin + "–" + ability.targeting.rangeMax,
    areaShape: ability.targeting.area.shape,
    areaRadius: ability.targeting.area.radius || 0,
    targetingType: ability.targeting.type,
    requiresLineOfSight: ability.targeting.requiresLineOfSight,
    recovery: ability.timing.recovery,
    cooldown: ability.timing.cooldown,
    cooldownRemaining,
    validTargetCount: targets.length,
    usable: reasons.length === 0,
    unusableReason: reasons[0] || null,
    unusableReasons: reasons,
    effects: ability.effects.map((effect) => ({
      type: effect.type,
      formula: effect.formula || null,
      power: effect.power == null ? null : effect.power,
      statusId: effect.statusId || null,
      chance: effect.chance == null ? 1 : effect.chance,
      delay: effect.delay || 0
    }))
  };

  if (opts.target) {
    model.preview = createActionPreview(state, unitId, abilityId, opts.target, opts);
  }
  return model;
}

/**
 * Rich, purely derived action preview. Consumes no RNG and mutates nothing.
 */
function createActionPreview(state, unitId, abilityId, target, options) {
  const opts = options || {};
  const validation = validateCommand(state, {
    type: "useAbility",
    unitId,
    abilityId,
    target
  });
  const ability = CONTENT.abilities[abilityId];
  const recovery = calculateActionRecoveryPreview(
    state,
    unitId,
    abilityId,
    opts.movementTiles
  );

  if (!validation.valid) {
    return {
      valid: false,
      errors: validation.errors,
      abilityId,
      abilityName: ability.name,
      recovery
    };
  }

  const preview = validation.preview;
  const outcomes = preview.outcomes.map((outcome) => {
    const targetUnit = state.units[outcome.targetUnitId];
    const targetStats = calculateUnitStats(state, outcome.targetUnitId);
    const entry = {
      ...outcome,
      targetName: CONTENT.units[targetUnit.definitionId].name,
      targetHp: targetUnit.currentHp,
      targetMaxHp: targetStats.maxHp,
      certainty: "deterministic"
    };
    if (outcome.effectType === "damage") {
      entry.certainty = outcome.hitChance < 1 ? "expected" : "deterministic";
      entry.hitChancePercent = Math.round(outcome.hitChance * 100);
      entry.expectedAmount = Math.round(outcome.amount * outcome.hitChance);
      entry.hpAfterOnHit = Math.max(0, targetUnit.currentHp - outcome.amount);
    }
    if (outcome.effectType === "heal") {
      entry.effectiveAmount = Math.min(outcome.amount, targetStats.maxHp - targetUnit.currentHp);
      entry.hpAfter = Math.min(targetStats.maxHp, targetUnit.currentHp + outcome.amount);
    }
    if (outcome.effectType === "applyStatus") {
      const statusDefinition = CONTENT.statuses[outcome.statusId];
      entry.certainty = outcome.chance < 1 ? "probability" : "deterministic";
      entry.statusName = statusDefinition.name;
      entry.chancePercent = Math.round(outcome.chance * 100);
      entry.statusDuration = statusDefinition.duration.amount;
      entry.statusDurationType = statusDefinition.duration.type;
      entry.icon = resolveDefinitionAsset(statusDefinition, "icon", statusDefinition.glyph);
    }
    if (outcome.effectType === "modifyTimeline") {
      const rate = FORMULAS.timeline.turnRate(calculateUnitStats(state, outcome.targetUnitId).speed);
      entry.appliedDelta = Math.round(outcome.delta / rate);
      entry.targetNextActionTime = targetUnit.nextActionTime + outcome.delta / rate;
    }
    return entry;
  });

  return {
    valid: true,
    errors: [],
    abilityId,
    abilityName: ability.name,
    icon: resolveDefinitionAsset(ability, "icon", ability.name[0]),
    targetTiles: preview.tiles,
    targetUnitIds: preview.targetUnitIds,
    outcomes,
    recovery
  };
}

function calculateActionRecoveryPreview(state, unitId, abilityId, movementTiles) {
  const stats = calculateUnitStats(state, unitId);
  const activation = state.activation && state.activation.unitId === unitId ? state.activation : null;
  const movementRecovery =
    movementTiles == null
      ? activation
        ? activation.movementRecovery
        : 0
      : movementRecoveryFor(movementTiles);
  const actionRecovery =
    abilityId == null ? GAME_CONFIG.timeline.waitRecovery : abilityRecovery(abilityId);
  const totalRecovery = actionRecovery + movementRecovery;
  return {
    speed: stats.speed,
    turnRate: Math.round(FORMULAS.timeline.turnRate(stats.speed) * 1000) / 1000,
    currentTime: state.currentTime,
    actionRecovery,
    movementRecovery,
    totalRecovery,
    delay: Math.round(projectNextActionTime(state, unitId, totalRecovery) - state.currentTime),
    projectedNextActionTime: projectNextActionTime(state, unitId, totalRecovery)
  };
}

function createTimelineViewModel(state, previewCount, options) {
  const opts = options || {};
  const entries = previewTimeline(state, previewCount || GAME_CONFIG.timeline.previewCount);
  return entries.map((entry) => {
    const unit = state.units[entry.unitId];
    const definition = CONTENT.units[unit.definitionId];
    const team = state.teams.find((t) => t.id === unit.teamId) || {};
    return {
      order: entry.order,
      unitId: entry.unitId,
      name: definition.name,
      glyph: definition.glyph,
      portrait: resolveDefinitionAsset(definition, "portrait", definition.glyph),
      teamId: unit.teamId,
      teamMarker: team.marker || "●",
      teamAccent: team.accent || "sky",
      time: entry.time,
      speed: entry.speed,
      estimated: entry.estimated,
      source: entry.estimated ? "estimated" : "scheduled",
      isActive: state.activeUnitId === entry.unitId,
      highlighted: opts.highlightUnitId === entry.unitId
    };
  });
}

/**
 * Alternate timeline: where would the acting unit land after spending
 * `totalRecovery`? Deterministic, no RNG, no mutation of live state.
 */
function previewTimelineAfterRecovery(state, unitId, totalRecovery, count) {
  const clone = cloneBattleState(state);
  clone.units[unitId].nextActionTime = projectNextActionTime(clone, unitId, totalRecovery);
  clone.activeUnitId = null;
  clone.activation = null;
  return createTimelineViewModel(clone, count || GAME_CONFIG.timeline.previewCount);
}

function cloneBattleState(state) {
  return JSON.parse(JSON.stringify(state));
}

/* ---------------------------------------------------------------
 * TARGET / DESTINATION ENUMERATION
 * -------------------------------------------------------------*/

function enumerateValidMoveDestinations(state, unitId) {
  const unit = state.units[unitId];
  const range = computeMovementRange(state, unitId);
  const out = [];
  for (const tile of range.values()) {
    const path = findPath(state, unitId, { x: tile.x, y: tile.y });
    if (!path) continue;
    const tiles = path.length - 1;
    out.push({
      x: tile.x,
      y: tile.y,
      cost: tile.cost,
      tiles,
      path,
      isOrigin: tile.x === unit.x && tile.y === unit.y,
      movementRecovery: movementRecoveryFor(tiles)
    });
  }
  return out.sort((a, b) => a.y - b.y || a.x - b.x);
}

function enumerateValidAbilityTargets(state, unitId, abilityId, origin) {
  const map = getMap(state);
  const results = [];
  for (let y = 0; y < map.height; y += 1) {
    for (let x = 0; x < map.width; x += 1) {
      const targeting = evaluateTargeting(state, unitId, abilityId, { x, y }, origin);
      if (!targeting.valid || !targeting.targetUnitIds.length) {
        if (!targeting.valid || CONTENT.abilities[abilityId].targeting.type !== "emptyTile") {
          continue;
        }
      }
      const occupant = unitAt(state, x, y);
      results.push({
        x,
        y,
        targetUnitId: occupant ? occupant.id : null,
        affectedTiles: targeting.tiles,
        affectedUnitIds: targeting.targetUnitIds
      });
    }
  }
  return results;
}

function describeTargetTile(state, unitId, abilityId, tile, origin) {
  const targeting = evaluateTargeting(state, unitId, abilityId, tile, origin);
  return {
    valid: targeting.valid && targeting.targetUnitIds.length > 0,
    errors: targeting.errors.length
      ? targeting.errors
      : targeting.targetUnitIds.length
      ? []
      : ["No unit in the affected area."],
    affectedTiles: targeting.tiles,
    affectedUnitIds: targeting.targetUnitIds
  };
}

/**
 * Validates (and, on a throwaway clone, executes) a command sequence so a
 * post-movement action can be previewed before movement is committed.
 */
function previewCommandSequence(state, commands) {
  const clone = cloneBattleState(state);
  const steps = [];
  for (const command of commands) {
    const validation = validateCommand(clone, command);
    steps.push({
      command,
      valid: validation.valid,
      errors: validation.errors,
      preview: validation.preview
    });
    if (!validation.valid) break;
    executeCommand(clone, command);
  }
  return {
    valid: steps.every((step) => step.valid),
    steps,
    finalTime: clone.currentTime
  };
}

/* ---------------------------------------------------------------
 * BATTLEFIELD VIEW MODEL
 * -------------------------------------------------------------*/

function createBattleViewModel(state, view) {
  const options = view || {};
  const map = getMap(state);
  const encounter = CONTENT.encounters[state.encounterId];
  const selectedUnitId = options.selectedUnitId || state.activeUnitId;

  const activation =
    state.activation && state.activation.unitId === selectedUnitId ? state.activation : null;
  const reachable = new Map();
  if (
    selectedUnitId &&
    state.units[selectedUnitId] &&
    state.units[selectedUnitId].alive &&
    state.activeUnitId === selectedUnitId &&
    !(activation && activation.moved) &&
    (options.mode === "unitReady" ||
      options.mode === "planningMove" ||
      options.mode === "confirmingAction")
  ) {
    for (const destination of enumerateValidMoveDestinations(state, selectedUnitId)) {
      reachable.set(tileKey(destination.x, destination.y), destination);
    }
  }

  const targetable = new Map();
  if (
    selectedUnitId &&
    options.abilityId &&
    (options.mode === "planningTarget" || options.mode === "confirmingAction")
  ) {
    for (const target of enumerateValidAbilityTargets(
      state,
      selectedUnitId,
      options.abilityId,
      options.origin
    )) {
      targetable.set(tileKey(target.x, target.y), target);
    }
  }

  const areaTiles = new Set();
  const focusTile = options.selectedTargetTile || options.hoveredTile;
  if (selectedUnitId && options.abilityId && focusTile) {
    const described = describeTargetTile(
      state,
      selectedUnitId,
      options.abilityId,
      focusTile,
      options.origin
    );
    for (const tile of described.affectedTiles) areaTiles.add(tileKey(tile.x, tile.y));
  }

  const threatImmediate = new Set();
  const threatPotential = new Set();
  if (options.threatZone) {
    for (const tile of options.threatZone.immediateTiles || []) {
      threatImmediate.add(tileKey(tile.x, tile.y));
    }
    for (const tile of options.threatZone.potentialTiles || []) {
      threatPotential.add(tileKey(tile.x, tile.y));
    }
  }

  const suggested = new Set();
  for (const tile of options.suggestedTiles || []) {
    suggested.add(tileKey(tile.x, tile.y));
  }

  const pathTiles = new Map();
  (options.plannedPath || []).forEach((tile, index) => {
    pathTiles.set(tileKey(tile.x, tile.y), index);
  });

  // Route marks. A trajectory is drawn as an ordinary planned path plus the
  // three things a path cannot say: where it turns, where it lands someone,
  // and where it stops short.
  const redirectTiles = new Map();
  const displacementTiles = new Set();
  let blockedTileKey = null;
  if (options.route) {
    for (const redirect of options.route.redirectTiles || []) {
      redirectTiles.set(tileKey(redirect.x, redirect.y), redirect.category);
    }
    for (const tile of options.route.displacementTiles || []) {
      displacementTiles.add(tileKey(tile.x, tile.y));
    }
    if (options.route.blockTile) {
      blockedTileKey = tileKey(options.route.blockTile.x, options.route.blockTile.y);
    }
  }

  // Chain marks. The board numbers each node with the arc that reaches it, so
  // the order the player is about to commit to is legible without a legend.
  const chainTiles = new Map();
  if (options.chain) {
    for (const node of options.chain.nodes || []) {
      if (node.tile) chainTiles.set(tileKey(node.tile.x, node.tile.y), node);
    }
  }

  const selectedElevation =
    selectedUnitId && state.units[selectedUnitId]
      ? elevationAt(map, state.units[selectedUnitId].x, state.units[selectedUnitId].y) || 0
      : null;

  const tiles = [];
  for (let y = 0; y < map.height; y += 1) {
    for (let x = 0; x < map.width; x += 1) {
      const terrainId = terrainIdAt(state, x, y);
      const terrain = CONTENT.terrains[terrainId];
      const elevation = elevationAt(map, x, y) || 0;
      const key = tileKey(x, y);
      const occupant = unitAt(state, x, y);
      const destination = reachable.get(key);
      tiles.push({
        x,
        y,
        key,
        terrainId,
        terrainName: terrain.name,
        elevation,
        projectedDepth: calculateTileRenderOrder({ x, y, elevation }),
        movementCost: terrain.movementCost,
        walkable: terrain.walkable,
        blocksLineOfSight: terrain.blocksLineOfSight,
        asset: resolveDefinitionAsset(terrain, "tile", ""),
        unitId: occupant ? occupant.id : null,
        reachable: !!destination,
        elevationDeltaFromSelectedUnit:
          selectedElevation == null ? null : elevation - selectedElevation,
        climbDelta:
          selectedElevation == null ? 0 : Math.max(0, elevation - selectedElevation),
        moveCost: destination ? destination.cost : null,
        moveTiles: destination ? destination.tiles : null,
        targetable: targetable.has(key),
        suggested: suggested.has(key),
        threatImmediate: threatImmediate.has(key),
        threatPotential: threatPotential.has(key),
        inArea: areaTiles.has(key),
        pathIndex: pathTiles.has(key) ? pathTiles.get(key) : null,
        routeRedirect: redirectTiles.has(key) ? redirectTiles.get(key) : null,
        routeDisplacement: displacementTiles.has(key),
        routeBlocked: blockedTileKey === key,
        chainHop: chainTiles.has(key) ? chainTiles.get(key).hop : null,
        chainLethal: chainTiles.has(key) ? chainTiles.get(key).lethal : false,
        isDestination:
          !!options.plannedDestination &&
          options.plannedDestination.x === x &&
          options.plannedDestination.y === y,
        hovered:
          !!options.hoveredTile && options.hoveredTile.x === x && options.hoveredTile.y === y,
        selected: !!occupant && occupant.id === selectedUnitId
      });
    }
  }

  const units = state.unitOrder.map((id) => createUnitViewModel(state, id));
  const nextUnitId = state.activeUnitId || getNextActionableUnitId(state);
  const nextUnit = nextUnitId ? state.units[nextUnitId] : null;
  const nextTeam = nextUnit ? state.teams.find((t) => t.id === nextUnit.teamId) : null;

  return {
    encounterId: state.encounterId,
    encounterName: encounter.name,
    mapName: map.name,
    width: map.width,
    height: map.height,
    currentTime: state.currentTime,
    activationCount: state.activationCount,
    seed: state.randomSeed,
    finished: state.finished,
    winner: state.winner,
    activeUnitId: state.activeUnitId,
    selectedUnitId,
    nextUnitId,
    isPlayerTurn: !!nextTeam && nextTeam.controller === "human",
    teams: state.teams.map((team) => ({
      ...team,
      aliveCount: state.unitOrder.filter(
        (id) => state.units[id].alive && state.units[id].teamId === team.id
      ).length
    })),
    tiles,
    units,
    // Where the player's squad last had eyes on a hostile it can no longer
    // see. An authoring aid rather than a HUD element — the board draws it
    // only when the Intel overlay is switched on.
    knowledgeMarkers: createKnowledgeMarkers(state),
    timeline: createTimelineViewModel(state, GAME_CONFIG.timeline.previewCount, {
      highlightUnitId: selectedUnitId
    }),
    engineErrors: state.errors.slice()
  };
}

function createKnowledgeMarkers(state) {
  if (!state.perception || !state.perception.enabled) return [];
  const map = getMap(state);
  const viewerTeam = state.teams.find((team) => team.controller === "human");
  if (!viewerTeam) return [];
  const faction = state.perception.factions[viewerTeam.id];
  if (!faction) return [];

  const out = [];
  for (const unitId of Object.keys(faction.units).sort()) {
    const record = faction.units[unitId];
    if (record.state !== "suspected" || record.x == null) continue;
    const unit = state.units[unitId];
    if (!unit || !unit.alive) continue;
    out.push({
      key: "knowledge-" + unitId,
      unitId,
      label: unitLabel(state, unitId),
      x: record.x,
      y: record.y,
      elevation: elevationAt(map, record.x, record.y) || 0,
      approximate: record.accuracy !== "exact",
      investigated: record.investigated
    });
  }
  return out;
}

/* ---------------------------------------------------------------
 * BATTLE SUMMARY (derived from the battle log)
 * -------------------------------------------------------------*/

function createBattleSummary(state) {
  const summary = {
    finished: state.finished,
    winner: state.winner,
    winnerName: null,
    playerVictory: false,
    activationCount: state.activationCount,
    finalTime: Math.round(state.currentTime),
    totalDamage: 0,
    totalHealing: 0,
    statusApplications: 0,
    timelineDelays: 0,
    timelineDelayTotal: 0,
    misses: 0,
    survivors: [],
    defeated: []
  };
  const winnerTeam = state.teams.find((team) => team.id === state.winner);
  if (winnerTeam) {
    summary.winnerName = winnerTeam.name;
    summary.playerVictory = winnerTeam.controller === "human";
  }
  for (const entry of state.battleLog) {
    const data = entry.data || {};
    if (entry.type === "damageResolved") summary.totalDamage += data.amount || 0;
    if (entry.type === "healResolved") summary.totalHealing += data.amount || 0;
    if (entry.type === "statusApplied") summary.statusApplications += 1;
    if (entry.type === "attackMissed") summary.misses += 1;
    if (entry.type === "timelineModified") {
      summary.timelineDelays += 1;
      summary.timelineDelayTotal += Math.round(data.appliedDelta || 0);
    }
  }
  for (const id of state.unitOrder) {
    const model = createUnitViewModel(state, id);
    if (model.alive) summary.survivors.push(model);
    else summary.defeated.push(model);
  }
  return summary;
}

/**
 * Groups the battle log into activation blocks for readable display.
 */
const LOG_FILTERS = {
  all: () => true,
  damage: (entry) => entry.type === "damageResolved" || entry.type === "attackMissed",
  healing: (entry) => entry.type === "healResolved",
  statuses: (entry) => entry.type.startsWith("status"),
  timeline: (entry) => entry.type === "timelineModified" || entry.type === "turnEnded",
  movement: (entry) => entry.type === "unitMoved",
  defeats: (entry) => entry.type === "unitDefeated",
  // Every moment somebody changed what was about to happen. Worth its own
  // filter because these are the lines that explain an outcome the player
  // cannot otherwise account for: an attack that produced no damage entry at
  // all reads as a bug until you can see the line that says why.
  vetoes: (entry) =>
    entry.type === "actionPrevented" ||
    entry.type === "actionRedirected" ||
    entry.type === "interventionFailed",
  // Who decided the order, and what happened to it afterwards. Worth its own
  // filter for the same reason: a turn arriving out of its natural place is
  // unexplainable from the rest of the log.
  orders: (entry) =>
    entry.type === "activationOrderChanged" || entry.type === "activationOrderDropped"
};

function createBattleLogViewModel(state, filterId) {
  const filter = LOG_FILTERS[filterId] || LOG_FILTERS.all;
  const groups = [];
  let current = null;
  for (const entry of state.battleLog) {
    if (entry.type === "unitActivated") {
      const unitId = entry.data ? entry.data.unitId : null;
      const unit = unitId ? state.units[unitId] : null;
      current = {
        key: "group-" + entry.index,
        time: entry.time,
        headline: entry.text,
        unitId,
        teamId: unit ? unit.teamId : null,
        entries: []
      };
      groups.push(current);
      continue;
    }
    if (!current) {
      current = {
        key: "group-" + entry.index,
        time: entry.time,
        headline: entry.text,
        unitId: null,
        teamId: null,
        entries: []
      };
      groups.push(current);
      continue;
    }
    if (filter(entry)) {
      current.entries.push({
        key: entry.index,
        time: entry.time,
        type: entry.type,
        text: entry.text,
        data: entry.data
      });
    }
  }
  return groups.filter((group) => group.entries.length || filterId === "all" || !filterId);
}

/* ---------------------------------------------------------------
 * ENGINE EVENT -> PRESENTATION EVENT TRANSLATION
 * -------------------------------------------------------------*/

/** Generic placeholder visual language for abilities. Final sprites and VFX
 * can replace these descriptors without changing battle logic. */
function createAbilityPresentationProfile(abilityId) {
  const ability = CONTENT.abilities[abilityId] || {};
  const target = ability.targeting || {};
  const serializedEffects = JSON.stringify(ability.effects || []).toLowerCase();
  const id = String(abilityId || "").toLowerCase();
  const category = abilityUi(abilityId).category;
  let kind = "system";
  if (id.includes("repair") || id.includes("heal") || id.includes("weld") || serializedEffects.includes('"type":"heal"')) kind = "repair";
  else if (serializedEffects.includes('"type":"shield"')) kind = "shield";
  else if (serializedEffects.includes('"type":"teleport"')) kind = "teleport";
  else if ((target.rangeMax || 0) <= 1 && category === "attack") kind = "melee";
  else if (id.includes("scatter") || id.includes("shotgun")) kind = "shotgun";
  else if (category === "attack" || serializedEffects.includes('"type":"damage"')) kind = "ballistic";
  else if (category === "movement") kind = "movement";
  const glyphs = {
    ballistic: { projectile: "•", impact: "✦" },
    shotgun: { projectile: "⋙", impact: "✹" },
    melee: { projectile: "╱", impact: "✧" },
    repair: { projectile: "≈", impact: "✚" },
    shield: { projectile: "◌", impact: "⬡" },
    teleport: { projectile: "◇", impact: "✦" },
    movement: { projectile: "➜", impact: "·" },
    system: { projectile: "·", impact: "✦" }
  };
  return {
    kind,
    projectileGlyph: glyphs[kind].projectile,
    impactGlyph: glyphs[kind].impact,
    screenShake: kind === "shotgun" || kind === "melee",
    recoil: category === "attack",
    icon: resolveDefinitionAsset(ability, "icon", glyphs[kind].impact)
  };
}

function engineEventToPresentationEvents(event, beforeState, afterState) {
  const before = beforeState || null;
  const after = afterState || null;
  const hp = (snapshot, unitId) =>
    snapshot && snapshot.units[unitId] ? snapshot.units[unitId].currentHp : null;

  switch (event.type) {
    case "unitActivated":
      return [{ type: "activationBanner", unitId: event.unitId }];

    case "facingChanged":
      // Movement and attacks already animate their own facing changes. Manual
      // reorientation keeps the short presentation beat.
      if (event.reason === "movement" || event.reason === "attack") return [];
      return [{
        type: "facingAnimation",
        unitId: event.unitId,
        facing: event.to,
        reason: event.reason || "manual"
      }];

    case "unitMoved":
      return [
        {
          type: "moveAnimation",
          unitId: event.unitId,
          from: event.from,
          to: event.to,
          path: event.path,
          tiles: event.tiles,
          startFacing: event.startFacing || null,
          stepFacings: event.stepFacings || []
        }
      ];

    case "abilityUsed":
      return [
        {
          type: "attackAnimation",
          sourceUnitId: event.sourceUnitId,
          abilityId: event.abilityId,
          targetUnitIds: event.targetUnitIds,
          targetTile: event.target || null,
          facing:
            after && after.units[event.sourceUnitId]
              ? normalizeFacing(after.units[event.sourceUnitId].facing)
              : null,
          profile: createAbilityPresentationProfile(event.abilityId)
        }
      ];

    case "damageResolved":
      return [
        {
          type: "floatingNumber",
          targetUnitId: event.targetUnitId,
          sourceUnitId: event.sourceUnitId,
          amount: event.amount,
          kind: "damage",
          hpBefore: hp(before, event.targetUnitId),
          hpAfter: hp(after, event.targetUnitId)
        },
        {
          type: "impactAnimation",
          targetUnitId: event.targetUnitId,
          sourceUnitId: event.sourceUnitId,
          kind: "damage",
          glyph: "✦"
        }
      ].concat(
        event.flankArc && event.flankArc !== "front"
          ? [{
              type: "floatingText",
              targetUnitId: event.targetUnitId,
              sourceUnitId: event.sourceUnitId,
              text: event.flankArc === "rear" ? "REAR ATTACK" : "FLANK",
              kind: event.flankArc === "rear" ? "rear" : "flank"
            }]
          : []
      );

    case "healResolved": {
      const hpBefore = hp(before, event.targetUnitId);
      const hpAfter = hp(after, event.targetUnitId);
      return [
        {
          type: "floatingNumber",
          targetUnitId: event.targetUnitId,
          sourceUnitId: event.sourceUnitId,
          amount: hpBefore == null || hpAfter == null ? event.amount : hpAfter - hpBefore,
          kind: "heal",
          hpBefore,
          hpAfter
        },
        {
          type: "impactAnimation",
          targetUnitId: event.targetUnitId,
          sourceUnitId: event.sourceUnitId,
          kind: "heal",
          glyph: "✚"
        }
      ];
    }

    case "attackMissed":
      return [
        {
          type: "floatingText",
          targetUnitId: event.targetUnitId,
          sourceUnitId: event.sourceUnitId,
          text: "Miss",
          kind: "miss"
        }
      ];

    case "statusApplied":
      return [
        {
          type: "statusPopup",
          targetUnitId: event.targetUnitId,
          statusId: event.statusId,
          kind: "applied"
        }
      ];

    case "statusResisted":
      return [
        {
          type: "floatingText",
          targetUnitId: event.targetUnitId,
          text: "Resisted",
          kind: "resist"
        }
      ];

    case "statusTriggered":
      return [
        {
          type: "statusPopup",
          targetUnitId: event.targetUnitId,
          statusId: event.statusId,
          kind: "triggered"
        }
      ];

    case "statusRemoved":
      return [
        {
          type: "statusPopup",
          targetUnitId: event.targetUnitId,
          statusId: event.statusId,
          kind: "removed"
        }
      ];

    case "shieldApplied":
      return [{
        type: "shieldAnimation",
        targetUnitId: event.targetUnitId,
        amount: event.amount || 0,
        kind: "applied",
        glyph: "⬡"
      }];

    case "shieldConsumed":
      return [{
        type: "shieldAnimation",
        targetUnitId: event.targetUnitId,
        amount: event.amount || 0,
        kind: "consumed",
        glyph: "◈"
      }];

    case "shieldExpired":
      return [{
        type: "shieldAnimation",
        targetUnitId: event.targetUnitId,
        amount: 0,
        kind: "expired",
        glyph: "◇"
      }];

    case "timelineModified":
      return [
        {
          type: "timelineShift",
          targetUnitId: event.targetUnitId,
          delta: event.delta,
          kind: event.delta >= 0 ? "delay" : "hasten"
        }
      ];

    case "unitDefeated":
      return [{ type: "defeatAnimation", unitId: event.unitId }];

    case "turnEnded":
      return [
        {
          type: "timelineUpdate",
          unitId: event.unitId,
          totalRecovery: event.totalRecovery,
          nextActionTime:
            after && after.units[event.unitId] ? after.units[event.unitId].nextActionTime : null
        }
      ];

    case "battleEnded":
      return [{ type: "battleEnd", winner: event.winner || null }];

    default:
      return [];
  }
}

function createEventCapture() {
  const records = [];
  return {
    records,
    onEvent(event, before, after) {
      records.push({ event, before, after });
    },
    presentationEvents() {
      const out = [];
      for (const record of records) {
        out.push(...engineEventToPresentationEvents(record.event, record.before, record.after));
      }
      return out;
    }
  };
}

function executeCommandWithPresentation(state, command) {
  const capture = createEventCapture();
  const result = executeCommand(state, command, { onEvent: capture.onEvent });
  return { ...result, presentation: result.ok ? capture.presentationEvents() : [] };
}

function runAiActivationWithPresentation(state) {
  const capture = createEventCapture();
  const result = runActivation(state, { onEvent: capture.onEvent });
  return { ...result, presentation: capture.presentationEvents() };
}
/* ---------------------------------------------------------------
 * ABILITY PRESENTATION METADATA (never read by the engine)
 * -------------------------------------------------------------*/

const DEFAULT_ABILITY_UI = { category: "action", basic: false, order: 50 };

function abilityUi(abilityId) {
  const ability = CONTENT.abilities[abilityId];
  const meta = (ability && ability.ui) || {};
  return {
    category: meta.category || DEFAULT_ABILITY_UI.category,
    basic: meta.basic === true,
    order: meta.order == null ? DEFAULT_ABILITY_UI.order : meta.order
  };
}

function isOffensiveAbility(abilityId) {
  const relation = CONTENT.abilities[abilityId].targeting.type;
  return relation === "enemy" || abilityUi(abilityId).category === "attack";
}

function unitAbilityIds(state, unitId) {
  return getUnitAbilities(state, unitId).sort((a, b) => {
    const left = abilityUi(a);
    const right = abilityUi(b);
    return left.order - right.order || a.localeCompare(b);
  });
}

function defaultAbilityIdFor(state, unitId) {
  const definition = CONTENT.units[state.units[unitId].definitionId];
  const abilities = getUnitAbilities(state, unitId);
  const nominated = definition.defaultAbilityId;
  if (nominated && abilities.includes(nominated)) return nominated;
  const basic = abilities.find((id) => abilityUi(id).basic);
  return basic || abilities[0] || null;
}

function validatePresentationMetadata() {
  const errors = [];
  for (const unitId of Object.keys(CONTENT.units)) {
    const definition = CONTENT.units[unitId];
    if (
      definition.defaultAbilityId &&
      !definition.abilities.includes(definition.defaultAbilityId)
    ) {
      errors.push("Unit " + unitId + " nominates an ability it does not know.");
    }
  }
  return errors;
}

/* ---------------------------------------------------------------
 * ACTIVATION RESOURCES
 * -------------------------------------------------------------*/

function createActivationResources(state, unitId) {
  const activation =
    state.activation && state.activation.unitId === unitId ? state.activation : null;
  return {
    unitId,
    active: state.activeUnitId === unitId,
    moved: !!(activation && activation.moved),
    acted: !!(activation && activation.acted),
    ended: !!(activation && (activation.ended || activation.waited || activation.closed)),
    movementRecovery: activation ? activation.movementRecovery : 0,
    actionRecovery: activation ? activation.actionRecovery : 0,
    moveLabel: activation && activation.moved ? "USED" : "READY",
    actionLabel: activation && activation.acted ? "USED" : "READY"
  };
}

/* ---------------------------------------------------------------
 * FORECASTS
 * -------------------------------------------------------------*/

/**
 * A conventional tactical forecast. Pure: no RNG, no mutation, no logging.
 * `origin` lets the forecast be taken from a planned destination.
 */
function createForecast(state, unitId, abilityId, target, options) {
  const opts = options || {};
  const ability = CONTENT.abilities[abilityId];
  const origin = opts.origin || null;
  const movementTiles = opts.movementTiles == null ? null : opts.movementTiles;
  const targeting = evaluateTargeting(state, unitId, abilityId, target, origin);
  const recovery = calculateActionRecoveryPreview(state, unitId, abilityId, movementTiles);

  const base = {
    valid: false,
    abilityId,
    abilityName: ability.name,
    category: abilityUi(abilityId).category,
    icon: resolveDefinitionAsset(ability, "icon", ability.name[0]),
    source: createForecastSide(state, unitId),
    target: null,
    headline: null,
    lines: [],
    outcomes: [],
    affectedTiles: targeting.tiles,
    affectedUnitIds: targeting.targetUnitIds,
    recovery,
    errors: targeting.errors.slice(),
    origin: origin ? { x: origin.x, y: origin.y } : null,
    movementTiles
  };

  if (!targeting.valid || !targeting.targetUnitIds.length) {
    if (!base.errors.length) base.errors.push("No unit in the affected area.");
    return base;
  }

  const preview = buildAbilityPreview(
    state,
    { unitId, abilityId, target, origin },
    targeting,
    movementTiles == null ? undefined : movementRecoveryFor(movementTiles)
  );

  const primaryUnitId = targeting.targetUnitIds[0];
  base.valid = true;
  base.target = createForecastSide(state, primaryUnitId);
  base.recovery = {
    ...recovery,
    actionRecovery: preview.recovery,
    movementRecovery: preview.movementRecovery,
    totalRecovery: preview.totalRecovery,
    projectedNextActionTime: preview.nextActionTime
  };

  for (const outcome of preview.outcomes) {
    const targetUnit = state.units[outcome.targetUnitId];
    const targetStats = calculateUnitStats(state, outcome.targetUnitId);
    const entry = {
      ...outcome,
      targetName: CONTENT.units[targetUnit.definitionId].name,
      targetHp: targetUnit.currentHp,
      targetMaxHp: targetStats.maxHp
    };
    if (outcome.effectType === "damage") {
      const hits = outcome.hits || 1;
      const total = outcome.totalAmount == null ? outcome.amount * hits : outcome.totalAmount;
      entry.hits = hits;
      entry.totalAmount = total;
      entry.hitChancePercent = Math.round(outcome.hitChance * 100);
      entry.expectedAmount = Math.round(total * outcome.hitChance);
      entry.hpAfterOnHit = Math.max(0, targetUnit.currentHp - total);
      entry.certainty = outcome.hitChance < 1 ? "expected" : "deterministic";
      if (outcome.flankArc && outcome.flankArc !== "front") {
        base.lines.push({
          kind: "flank",
          label: outcome.flankArc === "rear" ? "REAR ATTACK" : "SIDE FLANK",
          value: "+" + Math.round((outcome.damageMultiplier - 1) * 100) + "% damage",
          detail:
            "+" +
            Math.round((outcome.accuracyBonus || 0) * 100) +
            "% hit · target faces " +
            outcome.targetFacing
        });
      }
      if (hits > 1) {
        base.lines.push({
          kind: "multiHit",
          label: "HITS",
          value: hits + " x " + outcome.amount,
          detail: total + " on a full hit"
        });
      }
      if (outcome.branchProbability != null) {
        base.lines.push({
          kind: "branch",
          label: outcome.branch === "ifTrue" ? "IF CONDITION HOLDS" : "OTHERWISE",
          value: String(total),
          detail: Math.round(outcome.branchProbability * 100) + "% likely"
        });
      }
      if (!base.headline || base.headline.kind !== "damage") {
        base.headline = {
          kind: "damage",
          label: "DAMAGE",
          value: total,
          hits,
          perHit: outcome.amount,
          hitChancePercent: entry.hitChancePercent,
          lethal: outcome.lethal,
          targetHp: targetUnit.currentHp,
          targetHpAfter: entry.hpAfterOnHit,
          targetMaxHp: targetStats.maxHp,
          flankArc: outcome.flankArc || "front",
          targetFacing: outcome.targetFacing || null,
          damageMultiplier: outcome.damageMultiplier || 1,
          accuracyBonus: outcome.accuracyBonus || 0,
          note:
            outcome.lethal
              ? "LETHAL"
              : outcome.flankArc === "rear"
              ? "REAR ATTACK"
              : outcome.flankArc === "side"
              ? "FLANK"
              : null
        };
      }
    } else if (outcome.display) {
      base.lines.push({
        kind: outcome.display.kind,
        label: outcome.display.label,
        value: outcome.display.value,
        detail:
          (outcome.display.detail || "") +
          (outcome.branchProbability != null
            ? " (" + Math.round(outcome.branchProbability * 100) + "% branch)"
            : "")
      });
      entry.certainty = outcome.branchProbability != null ? "probability" : "deterministic";
    } else if (outcome.effectType === "heal") {
      entry.effectiveAmount = Math.min(outcome.amount, targetStats.maxHp - targetUnit.currentHp);
      entry.hpAfter = Math.min(targetStats.maxHp, targetUnit.currentHp + outcome.amount);
      entry.certainty = "deterministic";
      if (!base.headline) {
        base.headline = {
          kind: "heal",
          label: "HEAL",
          value: entry.effectiveAmount,
          targetHp: targetUnit.currentHp,
          targetHpAfter: entry.hpAfter,
          targetMaxHp: targetStats.maxHp,
          note: null
        };
      }
    } else if (outcome.effectType === "applyStatus") {
      const statusDefinition = CONTENT.statuses[outcome.statusId];
      entry.statusName = statusDefinition.name;
      entry.chancePercent = Math.round(outcome.chance * 100);
      entry.statusDuration = statusDefinition.duration.amount;
      entry.statusDurationType = statusDefinition.duration.type;
      entry.icon = resolveDefinitionAsset(statusDefinition, "icon", statusDefinition.glyph);
      entry.certainty = outcome.chance < 1 ? "probability" : "deterministic";
      base.lines.push({
        kind: "status",
        label: statusDefinition.name.toUpperCase(),
        value: entry.chancePercent + "%",
        detail: entry.statusDuration + " " + humanDuration(entry.statusDurationType)
      });
    } else if (outcome.effectType === "modifyTimeline") {
      const rate = FORMULAS.timeline.turnRate(targetStats.speed);
      entry.appliedDelta = Math.round(outcome.delta / rate);
      entry.certainty = "deterministic";
      base.lines.push({
        kind: "timeline",
        label: outcome.delta >= 0 ? "DELAY" : "HASTEN",
        value: (outcome.delta >= 0 ? "+" : "") + outcome.delta,
        detail: "base recovery (about " + Math.abs(entry.appliedDelta) + " battle time)"
      });
    }
    base.outcomes.push(entry);
  }

  if (!base.headline) {
    base.headline = { kind: "effect", label: ability.name.toUpperCase(), value: null, note: null };
  }
  return base;
}

function humanDuration(durationType) {
  if (durationType === "targetActivations") return "target activations";
  if (durationType === "sourceActivations") return "source activations";
  return "battle time";
}

function createForecastSide(state, unitId) {
  const unit = state.units[unitId];
  const definition = CONTENT.units[unit.definitionId];
  const stats = calculateUnitStats(state, unitId);
  const team = state.teams.find((entry) => entry.id === unit.teamId) || {};
  return {
    unitId,
    name: definition.name,
    teamId: unit.teamId,
    teamName: team.name || unit.teamId,
    teamMarker: team.marker || "*",
    teamAccent: team.accent || "sky",
    portrait: resolveDefinitionAsset(definition, "portrait", definition.glyph),
    currentHp: unit.currentHp,
    maxHp: stats.maxHp
  };
}

/** Every ability's outlook against a specific target (or in general). */
function createAbilityForecasts(state, unitId, options) {
  const opts = options || {};
  return unitAbilityIds(state, unitId).map((abilityId) => {
    const model = createAbilityViewModel(state, unitId, abilityId, {
      origin: opts.origin
    });
    model.ui = abilityUi(abilityId);
    model.isDefault = defaultAbilityIdFor(state, unitId) === abilityId;
    if (opts.targetUnitId && state.units[opts.targetUnitId]) {
      const target = state.units[opts.targetUnitId];
      model.forecast = createForecast(
        state,
        unitId,
        abilityId,
        { x: target.x, y: target.y },
        { origin: opts.origin, movementTiles: opts.movementTiles }
      );
    }
    return model;
  });
}

/** What could this unit do if it stood on `destination`? */
function createDestinationForecasts(state, unitId, destination, options) {
  const opts = options || {};
  const origin = { x: destination.x, y: destination.y };
  const results = [];
  for (const abilityId of unitAbilityIds(state, unitId)) {
    const model = createAbilityViewModel(state, unitId, abilityId, { origin });
    const targets = enumerateValidAbilityTargets(state, unitId, abilityId, origin);
    const entry = {
      abilityId,
      name: CONTENT.abilities[abilityId].name,
      icon: model.icon,
      usable: model.usable,
      unusableReason: model.unusableReason,
      targetCount: targets.length,
      forecasts: []
    };
    for (const target of targets.slice(0, opts.maxTargets || 3)) {
      const forecast = createForecast(
        state,
        unitId,
        abilityId,
        { x: target.x, y: target.y },
        { origin, movementTiles: destination.tiles }
      );
      if (forecast.valid) entry.forecasts.push(forecast);
    }
    results.push(entry);
  }
  return results;
}

/* ---------------------------------------------------------------
 * SUGGESTED ATTACK POSITIONS (click an enemy, get a plan)
 * -------------------------------------------------------------*/

function suggestAttackPositions(state, unitId, targetUnitId, abilityId) {
  const target = state.units[targetUnitId];
  if (!target || !target.alive) return [];
  const unit = state.units[unitId];
  const destinations = enumerateValidMoveDestinations(state, unitId);
  const positions = [];
  for (const destination of destinations) {
    const targeting = evaluateTargeting(
      state,
      unitId,
      abilityId,
      { x: target.x, y: target.y },
      { x: destination.x, y: destination.y }
    );
    if (!targeting.valid || !targeting.targetUnitIds.includes(targetUnitId)) continue;
    positions.push({
      x: destination.x,
      y: destination.y,
      cost: destination.cost,
      tiles: destination.tiles,
      path: destination.path,
      isOrigin: destination.x === unit.x && destination.y === unit.y,
      movementRecovery: destination.movementRecovery
    });
  }
  return positions.sort((a, b) => a.cost - b.cost || a.tiles - b.tiles);
}

/**
 * Full "click the enemy" plan: which ability, where to stand, what happens.
 * Returns null when no legal combination exists.
 */
function suggestAttackPlan(state, unitId, targetUnitId, options) {
  const opts = options || {};
  const resources = createActivationResources(state, unitId);
  const preferred = opts.abilityId ? [opts.abilityId] : [];
  const ordered = preferred.concat(
    unitAbilityIds(state, unitId).filter((id) => !preferred.includes(id))
  );
  const candidates = ordered.filter((abilityId) => {
    if (opts.abilityId) return abilityId === opts.abilityId;
    const target = state.units[targetUnitId];
    const relation = CONTENT.abilities[abilityId].targeting.type;
    const sameTeam = !isHostile(state, unitId, target.id);
    return sameTeam ? relation === "ally" || relation === "any" : isOffensiveAbility(abilityId);
  });

  const defaultAbility = defaultAbilityIdFor(state, unitId);
  candidates.sort((a, b) => {
    if (a === defaultAbility) return -1;
    if (b === defaultAbility) return 1;
    return abilityUi(a).order - abilityUi(b).order;
  });

  for (const abilityId of candidates) {
    const model = createAbilityViewModel(state, unitId, abilityId);
    if (resources.acted || (abilityCooldownRemaining(state, unitId, abilityId) > 0)) continue;
    const target = state.units[targetUnitId];
    // Already in range from here?
    const here = evaluateTargeting(state, unitId, abilityId, { x: target.x, y: target.y });
    if (here.valid && here.targetUnitIds.includes(targetUnitId)) {
      return {
        abilityId,
        abilityName: CONTENT.abilities[abilityId].name,
        targetUnitId,
        path: null,
        destination: null,
        positions: [],
        requiresMovement: false,
        forecast: createForecast(state, unitId, abilityId, { x: target.x, y: target.y }),
        blocked: !model.usable ? model.unusableReason : null
      };
    }
    if (resources.moved) continue;
    const positions = suggestAttackPositions(state, unitId, targetUnitId, abilityId).filter(
      (position) => !position.isOrigin
    );
    if (!positions.length) continue;
    const destination = positions[0];
    return {
      abilityId,
      abilityName: CONTENT.abilities[abilityId].name,
      targetUnitId,
      path: destination.path,
      destination,
      positions,
      requiresMovement: true,
      forecast: createForecast(
        state,
        unitId,
        abilityId,
        { x: target.x, y: target.y },
        { origin: { x: destination.x, y: destination.y }, movementTiles: destination.tiles }
      ),
      blocked: null
    };
  }
  return null;
}

function abilityCooldownRemaining(state, unitId, abilityId) {
  return state.units[unitId].cooldowns[abilityId] || 0;
}

/* ---------------------------------------------------------------
 * ATOMIC COMMAND SEQUENCES
 * -------------------------------------------------------------*/

/**
 * Validates a whole sequence against a clone. Authoritative state and the
 * seeded RNG are never touched, and a sequence that cannot complete is
 * reported before anything is executed.
 */
function validateCommandSequence(state, commands) {
  const clone = cloneBattleState(state);
  const steps = [];
  let valid = true;
  for (const command of commands) {
    const validation = validateCommand(clone, command);
    steps.push({
      command,
      valid: validation.valid,
      errors: validation.errors,
      preview: validation.preview
    });
    if (!validation.valid) {
      valid = false;
      break;
    }
    executeCommand(clone, command);
  }
  const unitId = commands.length ? commands[0].unitId : null;
  return {
    valid,
    steps,
    errors: steps.reduce((all, step) => all.concat(step.errors), []),
    projectedNextActionTime: unitId ? clone.units[unitId].nextActionTime : null,
    activationClosed: !clone.activeUnitId
  };
}

/** Executes a sequence only if the whole sequence validates first. */
function executeCommandSequenceWithPresentation(state, commands) {
  const validation = validateCommandSequence(state, commands);
  if (!validation.valid) {
    return { ok: false, errors: validation.errors, presentation: [], executed: 0 };
  }
  const presentation = [];
  let executed = 0;
  for (const command of commands) {
    const result = executeCommandWithPresentation(state, command);
    if (!result.ok) {
      return { ok: false, errors: result.errors, presentation, executed };
    }
    executed += 1;
    for (const event of result.presentation) presentation.push(event);
  }
  return { ok: true, errors: [], presentation, executed };
}

/* ---------------------------------------------------------------
 * COMMAND MENU
 * -------------------------------------------------------------*/

function createCommandMenu(state, unitId, options) {
  const opts = options || {};
  const resources = createActivationResources(state, unitId);
  const entries = [];

  entries.push({
    id: "move",
    kind: "move",
    label: "Move",
    shortcut: "M",
    enabled: resources.active && !resources.moved && !resources.ended,
    status: resources.moved ? "Used" : "Ready",
    reason: resources.moved ? "Already moved this activation." : null
  });

  const abilities = createAbilityForecasts(state, unitId, {
    targetUnitId: opts.targetUnitId,
    origin: opts.origin,
    movementTiles: opts.movementTiles
  });
  abilities.forEach((ability, index) => {
    entries.push({
      id: ability.abilityId,
      kind: "ability",
      label: ability.name,
      shortcut: String(index + 1),
      enabled: ability.usable,
      status: ability.usable
        ? "Ready"
        : ability.cooldownRemaining > 0
        ? "Cooldown " + ability.cooldownRemaining
        : resources.acted
        ? "Used"
        : "Unavailable",
      reason: ability.usable ? null : ability.unusableReason,
      ability
    });
  });

  entries.push({
    id: "wait",
    kind: "wait",
    label: "Wait",
    shortcut: "Q",
    enabled: resources.active && !resources.acted && !resources.ended,
    status: resources.acted ? "Unavailable" : "Ready",
    reason: resources.acted ? "Already acted this activation." : null
  });

  entries.push({
    id: "endTurn",
    kind: "endTurn",
    label: "End Turn",
    shortcut: "E",
    enabled: resources.active && !resources.ended,
    status: "Ready",
    reason: null
  });

  entries.push({
    id: "inspect",
    kind: "inspect",
    label: "Inspect",
    shortcut: "I",
    enabled: true,
    status: "",
    reason: null
  });

  return {
    unitId,
    resources,
    entries,
    suggestedAbilityId: opts.suggestedAbilityId || null
  };
}

/* ---------------------------------------------------------------
 * PLAYER INPUT STATE MACHINE (presentation only)
 * -------------------------------------------------------------*/

const INPUT_MODES = [
  "idle",
  "unitReady",
  "planningMove",
  "planningTarget",
  "planningRoute",
  "planningOrder",
  "confirmingAction",
  "presentingEvents",
  "battleFinished"
];

function createInputState(overrides) {
  return {
    mode: "idle",
    selectedUnitId: null,
    inspectedUnitId: null,
    hoveredTile: null,
    hoverPath: null,
    hoverForecast: null,
    plannedPath: null,
    plannedMoveDestination: null,
    plannedSequence: null,
    selectedAbilityId: null,
    selectedTarget: null,
    /** Committed legs of a trajectory, in the same shape the command takes.
     *  Null when no route is being drawn; an empty array means "drawing, but
     *  nothing chosen yet", which is a different thing the panel must say. */
    routeSegments: null,
    /** Units picked for a commanded order, in the order they were picked.
     *  Null when no command is being planned; an empty array means "planning,
     *  nothing chosen", which the panel says differently. */
    plannedOrder: null,
    forecast: null,
    contextOptions: null,
    contextTargetUnitId: null,
    threatUnitId: null,
    threatAbilityId: null,
    threatPinned: false,
    commandMenuOpen: false,
    resumeMode: null,
    errorMessage: "",
    ...(overrides || {})
  };
}

function inputStateOrigin(input, state) {
  if (input.plannedMoveDestination) return { ...input.plannedMoveDestination };
  if (input.selectedUnitId && state.units[input.selectedUnitId]) {
    const unit = state.units[input.selectedUnitId];
    return { x: unit.x, y: unit.y };
  }
  return null;
}

function sameTile(a, b) {
  return !!a && !!b && a.x === b.x && a.y === b.y;
}

function clearPlan(input, overrides) {
  return {
    ...input,
    mode: "unitReady",
    plannedPath: null,
    plannedMoveDestination: null,
    plannedSequence: null,
    selectedAbilityId: null,
    selectedTarget: null,
    routeSegments: null,
    plannedOrder: null,
    forecast: null,
    contextOptions: null,
    contextTargetUnitId: null,
    hoverPath: null,
    hoverForecast: null,
    commandMenuOpen: false,
    threatUnitId: null,
    threatAbilityId: null,
    threatPinned: false,
    errorMessage: "",
    ...(overrides || {})
  };
}

/**
 * Brings the input state back in line with the battle.
 *
 * The input machine tracks a selected unit and a mode; the simulation can end
 * an activation without either of them being told, and after a reaction chain
 * it routinely does. Rather than have every authoritative path remember to
 * notify the UI — which is the bug this fixes, one caller at a time — the UI
 * reconciles against the truth whenever it might have drifted.
 *
 * Pure: takes input and state, returns input.
 */
function reconcileInputWithBattle(input, state) {
  if (input.mode === "presentingEvents" || input.mode === "battleFinished") return input;
  if (state.finished) return { ...createInputState(), mode: "battleFinished" };

  const activeId = state.activeUnitId;
  const activeUnit = activeId ? state.units[activeId] : null;
  const hasActive = !!(activeUnit && activeUnit.alive && !activeUnit.dormant);

  if (hasActive) {
    if (input.selectedUnitId === activeId && input.mode !== "idle") return input;
    return clearPlan(input, {
      selectedUnitId: activeId,
      inspectedUnitId: activeId,
      commandMenuOpen: false,
      resumeMode: null
    });
  }

  if (input.mode === "idle" && !input.selectedUnitId) return input;
  // Nothing is activated: whatever the player was aiming at belongs to a turn
  // that is over. Inspection survives, because looking at a unit is not a plan.
  return createInputState({ mode: "idle", inspectedUnitId: input.inspectedUnitId });
}

/** Turns a contextual option into a confirmable plan. */
function applyContextOption(input, option, targetUnit) {
  const targetTile = { x: targetUnit.x, y: targetUnit.y };
  return {
    ...input,
    mode: "confirmingAction",
    selectedAbilityId: option.abilityId,
    selectedTarget: targetTile,
    plannedPath: option.suggestedPath,
    plannedMoveDestination: option.requiresMovement
      ? { x: option.suggestedOrigin.x, y: option.suggestedOrigin.y }
      : null,
    plannedSequence: option.requiresMovement
      ? { path: option.suggestedPath, abilityId: option.abilityId, target: targetTile }
      : null,
    forecast: option.forecast,
    contextOptions: null,
    contextTargetUnitId: null,
    commandMenuOpen: false,
    errorMessage: ""
  };
}

/** Commands produced by confirming whatever is currently planned. */
function commandsForPlan(input) {
  if (input.mode === "planningRoute" && input.routeSegments && input.routeSegments.length) {
    return [
      {
        type: "trajectory",
        unitId: input.selectedUnitId,
        abilityId: input.selectedAbilityId,
        segments: input.routeSegments
      }
    ];
  }
  if (input.plannedSequence) {
    const sequence = [];
    if (input.plannedSequence.path && input.plannedSequence.path.length > 1) {
      sequence.push({
        type: "move",
        unitId: input.selectedUnitId,
        path: input.plannedSequence.path
      });
    }
    sequence.push({
      type: "useAbility",
      unitId: input.selectedUnitId,
      abilityId: input.plannedSequence.abilityId,
      target: input.plannedSequence.target
    });
    return sequence;
  }
  if (input.mode === "confirmingAction" && input.selectedAbilityId && input.selectedTarget) {
    return [
      {
        type: "useAbility",
        unitId: input.selectedUnitId,
        abilityId: input.selectedAbilityId,
        target: input.selectedTarget
      }
    ];
  }
  if (input.plannedPath && input.plannedPath.length > 1) {
    return [{ type: "move", unitId: input.selectedUnitId, path: input.plannedPath }];
  }
  return [];
}

/**
 * Pure reducer. Returns the next input state plus any engine commands the
 * caller should execute. It never mutates battle state itself.
 */
function inputReducer(input, action, state) {
  const result = (next, commands, errors) => ({
    input: next,
    commands: commands || [],
    errors: errors || []
  });
  const fail = (next, message) => result({ ...next, errorMessage: message }, [], [message]);

  if (action.type === "reset") return result(createInputState());

  if (action.type === "battleFinished") {
    return result({ ...createInputState(), mode: "battleFinished" });
  }

  if (input.mode === "presentingEvents" && action.type !== "presentationFinished") {
    return result(
      { ...input, errorMessage: "Presentation in progress." },
      [],
      ["Input is disabled while events are presented."]
    );
  }

  if (input.mode === "battleFinished" && action.type !== "reset") {
    return result(input, [], ["The battle is over."]);
  }

  const activeId = state.activeUnitId;
  const isActive = !!activeId && input.selectedUnitId === activeId;

  switch (action.type) {
    case "activationStarted":
      // A new activation shows the active-unit indicator only. The command
      // menu waits for a deliberate click or shortcut.
      return result(
        createInputState({
          mode: "unitReady",
          selectedUnitId: action.unitId,
          inspectedUnitId: action.unitId,
          commandMenuOpen: false
        })
      );

    case "presentationFinished": {
      if (state.finished) {
        return result({ ...createInputState(), mode: "battleFinished" });
      }
      if (state.activeUnitId) {
        return result(
          clearPlan(input, {
            selectedUnitId: state.activeUnitId,
            inspectedUnitId: state.activeUnitId,
            commandMenuOpen: false,
            resumeMode: null
          })
        );
      }
      return result(
        createInputState({ mode: "idle", inspectedUnitId: input.inspectedUnitId })
      );
    }

    case "inspectUnit":
      return result({ ...input, inspectedUnitId: action.unitId });

    case "openMenu":
      return result({ ...input, commandMenuOpen: true, errorMessage: "" });

    case "closeMenu":
      return result({ ...input, commandMenuOpen: false });

    case "chooseMove": {
      if (!isActive) return fail(input, "No active unit.");
      const resources = createActivationResources(state, activeId);
      if (resources.moved) return fail(input, "Already moved this activation.");
      return result({
        ...input,
        mode: "planningMove",
        threatUnitId: null,
        threatPinned: false,
        commandMenuOpen: false,
        selectedAbilityId: null,
        selectedTarget: null,
        plannedSequence: null,
        forecast: null,
        errorMessage: ""
      });
    }

    case "chooseContextOption": {
      if (!isActive || !input.contextOptions) return result(input);
      const option = input.contextOptions.find(
        (entry) => entry.abilityId === action.abilityId
      );
      const targetUnit = input.contextTargetUnitId
        ? state.units[input.contextTargetUnitId]
        : null;
      if (!option || !targetUnit) return fail(input, "That option is no longer available.");
      return result(applyContextOption(input, option, targetUnit));
    }

    case "showThreat":
      return result({
        ...input,
        threatUnitId: action.unitId || null,
        threatAbilityId: action.abilityId || null,
        threatPinned: !!action.unitId,
        inspectedUnitId: action.unitId || input.inspectedUnitId
      });

    case "clearThreat":
      return result({ ...input, threatUnitId: null, threatAbilityId: null, threatPinned: false });

    case "chooseAbility": {
      if (!isActive) return fail(input, "No active unit.");
      if (action.abilityId == null) {
        return result({ ...input }, [{ type: "wait", unitId: activeId }]);
      }
      const model = createAbilityViewModel(state, activeId, action.abilityId);
      if (!model.usable) return fail(input, model.unusableReason || "Ability unavailable.");
      // A route is drawn, not aimed. Which one an ability is comes from its
      // content, so a new trajectory ability needs no UI change at all.
      const route = !!trajectoryAbility(action.abilityId);
      // Likewise an order is arranged, not aimed. Which kind of planning an
      // ability needs is read from its authored block, so a second commander
      // with a different reach needs no UI change either.
      const orders = !!activationWindowRules(CONTENT.abilities[action.abilityId]);
      return result({
        ...input,
        mode: route ? "planningRoute" : orders ? "planningOrder" : "planningTarget",
        threatUnitId: null,
        threatPinned: false,
        selectedAbilityId: action.abilityId,
        selectedTarget: null,
        routeSegments: route ? [] : null,
        plannedOrder: orders ? [] : null,
        plannedSequence: null,
        plannedPath: null,
        plannedMoveDestination: null,
        forecast: null,
        commandMenuOpen: false,
        errorMessage: ""
      });
    }

    /* ---- order planning ----
     *
     * Three actions and no drag-and-drop: clicking an eligible unit appends it
     * to the order, clicking it again removes it, and undo pops the last one.
     * Click-to-sequence is unambiguous about *what number this unit is*, which
     * dragging portraits around a rail is not.
     */

    case "toggleOrderPick": {
      if (input.mode !== "planningOrder" || !input.plannedOrder) return result(input);
      const plan = createCommandPlanModel(state, activeId, input.selectedAbilityId, input.plannedOrder);
      if (!plan) return fail(input, "That action does not command the timeline.");
      const already = input.plannedOrder.indexOf(action.unitId);
      if (already >= 0) {
        // Removing from the middle renumbers the rest, which is what the
        // player means: they are editing a sequence, not clearing a checkbox.
        return result({
          ...input,
          plannedOrder: input.plannedOrder.filter((id) => id !== action.unitId),
          errorMessage: ""
        });
      }
      const entry = plan.entries.find((record) => record.unitId === action.unitId);
      if (!entry) return fail(input, "That unit is not in the command window.");
      if (!entry.eligible) return fail(input, entry.reason || "That unit cannot be commanded.");
      if (input.plannedOrder.length >= plan.maxUnits) {
        return fail(input, "This command can sequence " + plan.maxUnits + ".");
      }
      return result({
        ...input,
        plannedOrder: input.plannedOrder.concat(action.unitId),
        errorMessage: ""
      });
    }

    case "undoOrderPick": {
      if (input.mode !== "planningOrder" || !input.plannedOrder) return result(input);
      if (!input.plannedOrder.length) return result(clearPlan(input));
      return result({ ...input, plannedOrder: input.plannedOrder.slice(0, -1), errorMessage: "" });
    }

    case "confirmOrder": {
      if (input.mode !== "planningOrder" || !input.plannedOrder) return result(input);
      if (!isActive) return fail(input, "No active unit.");
      // The same model the panel rendered, asked again at the moment of
      // commitment. If it now refuses, the refusal is the honest answer.
      const plan = createCommandPlanModel(state, activeId, input.selectedAbilityId, input.plannedOrder);
      if (!plan || !plan.ok) return fail(input, (plan && plan.reason) || "That order cannot be issued.");
      return result(
        { ...input, mode: "presentingEvents", resumeMode: "unitReady" },
        [
          {
            type: "reorderActivations",
            unitId: activeId,
            abilityId: input.selectedAbilityId,
            order: input.plannedOrder.slice()
          }
        ]
      );
    }

    /* ---- route planning ---- */

    case "undoRouteSegment": {
      if (input.mode !== "planningRoute" || !input.routeSegments) return result(input);
      if (!input.routeSegments.length) return result(clearPlan(input));
      return result({
        ...input,
        routeSegments: input.routeSegments.slice(0, -1),
        errorMessage: ""
      });
    }

    /**
     * The chosen displacement for a contact. This is the precise half of the
     * mechanic: the distance is the player's, bounded by what the ability
     * authorised, and the engine clamps it again on the way through.
     */
    case "setRouteDisplacement": {
      if (input.mode !== "planningRoute" || !input.routeSegments) return result(input);
      const index = action.segment == null ? input.routeSegments.length - 1 : action.segment;
      const segment = input.routeSegments[index];
      if (!segment || !segment.contact) return fail(input, "That leg has no contact.");
      const displace = { ...(segment.contact.displace || {}) };
      if (action.heading !== undefined) displace.heading = action.heading;
      if (action.distance !== undefined) displace.distance = Math.max(0, Number(action.distance) || 0);
      const segments = input.routeSegments.slice();
      segments[index] = {
        ...segment,
        contact: { ...segment.contact, displace }
      };
      return result({ ...input, routeSegments: segments, errorMessage: "" });
    }

    case "setFacing":
      if (!isActive) return fail(input, "No active unit.");
      return result(
        {
          ...input,
          mode: "presentingEvents",
          resumeMode: "unitReady",
          errorMessage: ""
        },
        [{ type: "setFacing", unitId: activeId, facing: action.facing }]
      );

    case "wait":
      if (!isActive) return fail(input, "No active unit.");
      return result(
        { ...input, mode: "presentingEvents", resumeMode: "idle" },
        [{ type: "wait", unitId: activeId }]
      );

    case "endTurn":
      if (!isActive) return fail(input, "No active unit.");
      return result(
        { ...input, mode: "presentingEvents", resumeMode: "idle" },
        [{ type: "endTurn", unitId: activeId }]
      );

    case "hoverTile": {
      const occupantUnderPointer = action.tile
        ? unitAt(state, action.tile.x, action.tile.y)
        : null;
      const hostileUnderPointer =
        occupantUnderPointer &&
        activeId &&
        isHostile(state, activeId, occupantUnderPointer.id) &&
        !isUnitConcealed(state, occupantUnderPointer.id)
          ? occupantUnderPointer.id
          : null;
      const next = {
        ...input,
        hoveredTile: action.tile ? { x: action.tile.x, y: action.tile.y } : null,
        hoverPath: null,
        hoverForecast: null,
        // Hovering previews an enemy's threat; leaving clears it unless the
        // player pinned that enemy by selecting it.
        threatUnitId: input.threatPinned ? input.threatUnitId : hostileUnderPointer,
        threatAbilityId: input.threatPinned ? input.threatAbilityId : null
      };
      if (!action.tile || !isActive) return result(next);
      const resources = createActivationResources(state, activeId);
      if (input.mode === "planningTarget" && input.selectedAbilityId) {
        next.hoverForecast = createForecast(
          state,
          activeId,
          input.selectedAbilityId,
          { x: action.tile.x, y: action.tile.y },
          { origin: inputStateOrigin(input, state) }
        );
        return result(next);
      }
      if (!resources.moved && (input.mode === "unitReady" || input.mode === "planningMove")) {
        next.hoverPath = findPath(state, activeId, action.tile);
      }
      return result(next);
    }

    case "rightClickTile": {
      const occupant = action.tile ? unitAt(state, action.tile.x, action.tile.y) : null;
      // While drawing a route, right-click removes the last leg rather than
      // throwing the whole thing away — a five-leg route is too much work to
      // lose to one misclick.
      if (input.mode === "planningRoute" && input.routeSegments) {
        if (!input.routeSegments.length) return result(clearPlan(input));
        return result({
          ...input,
          routeSegments: input.routeSegments.slice(0, -1),
          errorMessage: ""
        });
      }
      if (occupant && occupant.id === activeId) {
        return result({ ...input, commandMenuOpen: true, errorMessage: "" });
      }
      if (
        input.plannedPath ||
        input.plannedSequence ||
        input.selectedAbilityId ||
        input.selectedTarget ||
        input.contextOptions
      ) {
        return result(clearPlan(input, { threatUnitId: input.threatUnitId }));
      }
      if (input.threatUnitId) {
        return result({
          ...input,
          threatUnitId: null,
          threatAbilityId: null,
          threatPinned: false
        });
      }
      if (occupant) return result({ ...input, inspectedUnitId: occupant.id });
      return result(input);
    }

    case "clickTile": {
      const tile = action.tile;
      if (!tile) return result(input);
      const occupant = unitAt(state, tile.x, tile.y);

      if (!isActive) {
        return result({
          ...input,
          inspectedUnitId: occupant ? occupant.id : input.inspectedUnitId
        });
      }

      const resources = createActivationResources(state, activeId);

      /* ---- drawing a route ----
       *
       * Three things a click can mean, in the order a player expects them:
       * confirm the route by clicking its end again, hit something the route
       * already reaches, or add a leg. Every one of them is checked by the
       * planner before it is accepted, so an illegal route can never be drawn
       * in the first place — the reason is shown instead. */
      if (input.mode === "planningRoute" && input.routeSegments) {
        const segments = input.routeSegments;
        const end = routeEndpoint(state, activeId, segments);
        if (segments.length && sameTile(end, tile)) {
          const validation = validateCommand(state, commandsForPlan(input)[0]);
          if (!validation.valid) return fail(input, validation.errors[0]);
          return result(
            { ...input, mode: "presentingEvents", resumeMode: "idle" },
            commandsForPlan(input)
          );
        }
        if (occupant && segments.length && isHostile(state, activeId, occupant.id)) {
          if (gridDistance(end, occupant) > 1) {
            return fail(
              { ...input, inspectedUnitId: occupant.id },
              "The route does not pass within reach of that unit."
            );
          }
          const last = segments.length - 1;
          const next = segments.slice();
          next[last] = {
            ...segments[last],
            contact: { targetUnitId: occupant.id, displace: { heading: null, distance: null } }
          };
          return result({ ...input, routeSegments: next, inspectedUnitId: occupant.id, errorMessage: "" });
        }
        const leg = straightSegmentTo(end, tile);
        if (!leg) {
          return fail(input, "A leg has to run straight from where the last one ended.");
        }
        const candidate = segments.concat([leg]);
        const plan = planUnitTrajectory(
          state,
          activeId,
          candidate,
          trajectoryRules(CONTENT.abilities[input.selectedAbilityId])
        );
        if (!plan.legal) return fail(input, plan.reason || "That leg is not legal.");
        return result({ ...input, routeSegments: candidate, errorMessage: "" });
      }

      // Targeting an ability that is already selected.
      if (
        (input.mode === "planningTarget" || input.mode === "confirmingAction") &&
        input.selectedAbilityId
      ) {
        if (
          input.mode === "confirmingAction" &&
          sameTile(input.selectedTarget, tile) &&
          !input.plannedSequence
        ) {
          return result(
            { ...input, mode: "presentingEvents", resumeMode: "idle" },
            commandsForPlan(input)
          );
        }
        const command = {
          type: "useAbility",
          unitId: activeId,
          abilityId: input.selectedAbilityId,
          target: { x: tile.x, y: tile.y }
        };
        const validation = validateCommand(state, command);
        if (!validation.valid) {
          return fail(
            { ...input, inspectedUnitId: occupant ? occupant.id : input.inspectedUnitId },
            validation.errors[0]
          );
        }
        return result({
          ...input,
          mode: "confirmingAction",
          selectedTarget: { x: tile.x, y: tile.y },
          plannedSequence: null,
          inspectedUnitId: occupant ? occupant.id : input.inspectedUnitId,
          forecast: createForecast(state, activeId, input.selectedAbilityId, {
            x: tile.x,
            y: tile.y
          }),
          errorMessage: ""
        });
      }

      // Clicking the active unit focuses its command menu and keeps the plan.
      if (occupant && occupant.id === activeId) {
        return result({
          ...input,
          commandMenuOpen: !input.commandMenuOpen,
          inspectedUnitId: activeId,
          errorMessage: ""
        });
      }

      // Clicking any other unit: inspect it, show its threat, and offer the
      // abilities that can meaningfully reach it.
      if (occupant) {
        const hostile = isHostile(state, activeId, occupant.id);
        const sameThreat = input.threatUnitId === occupant.id;
        const inspected = {
          ...input,
          inspectedUnitId: occupant.id,
          errorMessage: "",
          contextOptions: null,
          contextTargetUnitId: null,
          threatUnitId: hostile && !isUnitConcealed(state, occupant.id)
            ? sameThreat
              ? null
              : occupant.id
            : null,
          threatPinned: hostile && !sameThreat && !isUnitConcealed(state, occupant.id),
          threatAbilityId: null
        };
        const selection = resolveContextualSelection(state, activeId, occupant.id);
        if (selection.mode === "none") {
          return result({ ...inspected, errorMessage: selection.reason });
        }
        if (selection.mode === "menu") {
          return result({
            ...inspected,
            mode: "unitReady",
            contextOptions: selection.options,
            contextTargetUnitId: occupant.id,
            commandMenuOpen: false
          });
        }
        return result(applyContextOption(inspected, selection.chosen, occupant));
      }

      // Empty terrain: movement planning.
      if (resources.moved) {
        return result({
          ...input,
          commandMenuOpen: false,
          contextOptions: null,
          contextTargetUnitId: null,
          errorMessage: "Already moved this activation."
        });
      }
      if (sameTile(input.plannedMoveDestination, tile)) {
        return result(
          { ...input, mode: "presentingEvents", resumeMode: "idle" },
          [{ type: "move", unitId: activeId, path: input.plannedPath }]
        );
      }
      const path = findPath(state, activeId, tile);
      if (!path) {
        return result({
          ...input,
          commandMenuOpen: false,
          contextOptions: null,
          contextTargetUnitId: null,
          errorMessage: "That tile is not reachable."
        });
      }
      const validation = validateCommand(state, {
        type: "move",
        unitId: activeId,
        path
      });
      if (!validation.valid) return fail(input, validation.errors[0]);
      return result({
        ...input,
        mode: "planningMove",
        plannedPath: path,
        plannedMoveDestination: { x: tile.x, y: tile.y },
        plannedSequence: null,
        selectedAbilityId: null,
        selectedTarget: null,
        forecast: null,
        commandMenuOpen: false,
        errorMessage: ""
      });
    }

    case "confirm": {
      if (!isActive) return result(input);
      const commands = commandsForPlan(input);
      if (!commands.length) return fail(input, "Nothing to confirm.");
      if (commands.length > 1) {
        const validation = validateCommandSequence(state, commands);
        if (!validation.valid) {
          return fail(clearPlan(input), validation.errors[0] || "That plan is no longer legal.");
        }
      }
      return result(
        {
          ...input,
          mode: "presentingEvents",
          resumeMode: "idle",
          threatUnitId: null,
          threatPinned: false,
          errorMessage: ""
        },
        commands
      );
    }

    case "cancel":
      if (
        !input.plannedPath &&
        !input.plannedSequence &&
        !input.selectedAbilityId &&
        !input.selectedTarget
      ) {
        // Nothing planned: cancelling still dismisses inspection overlays.
        return result({
          ...input,
          commandMenuOpen: true,
          threatUnitId: null,
          threatAbilityId: null,
          threatPinned: false,
          errorMessage: ""
        });
      }
      return result(clearPlan(input));

    default:
      return result(input);
  }
}

/* ---------------------------------------------------------------
 * THREAT / DANGER ZONES
 * -------------------------------------------------------------*/

function isHostileAbility(abilityId) {
  const targeting = CONTENT.abilities[abilityId].targeting;
  return targeting.type === "enemy" || isOffensiveAbility(abilityId);
}

function abilityIsAvailable(state, unitId, abilityId) {
  const unit = state.units[unitId];
  const ability = CONTENT.abilities[abilityId];
  if ((unit.cooldowns[abilityId] || 0) > 0) return false;
  for (const resourceId of Object.keys(ability.costs || {})) {
    const resource = unit.resources[resourceId];
    if (!resource || resource.current < ability.costs[resourceId]) return false;
  }
  return true;
}

/**
 * Tiles an ability could hit from the given origins. Uses the engine's own
 * range, line-of-sight and area rules; no geometry is reinvented here.
 */
function calculateAbilityThreatTiles(state, unitId, abilityId, options) {
  const opts = options || {};
  const unit = state.units[unitId];
  const map = getMap(state);
  const ability = CONTENT.abilities[abilityId];
  const targeting = ability.targeting;
  const origins = opts.origins || [{ x: unit.x, y: unit.y }];
  const tiles = new Map();
  const blocked = new Map();

  for (const origin of origins) {
    for (let y = 0; y < map.height; y += 1) {
      for (let x = 0; x < map.width; x += 1) {
        const distance = gridDistance(origin, { x, y });
        if (distance < targeting.rangeMin || distance > targeting.rangeMax) continue;
        if (
          targeting.requiresLineOfSight &&
          !hasLineOfSight(map, origin, { x, y }, state)
        ) {
          blocked.set(tileKey(x, y), { x, y });
          continue;
        }
        for (const areaTile of tilesInArea(state, { x, y }, targeting.area, {
          origin,
          sourceUnitId: unitId
        })) {
          tiles.set(tileKey(areaTile.x, areaTile.y), { x: areaTile.x, y: areaTile.y });
        }
      }
    }
  }
  for (const key of tiles.keys()) blocked.delete(key);
  return {
    abilityId,
    tiles: [...tiles.values()],
    blockedByLineOfSight: [...blocked.values()]
  };
}

/**
 * Full threat picture for a unit: what it can hit now, and what it could hit
 * after moving. Potential tiles are explicitly flagged as estimates.
 */
function calculateUnitThreatZone(state, unitId, options) {
  const opts = options || {};
  const unit = state.units[unitId];
  // A concealed mech reveals nothing, including its reach.
  if (unit && unit.alive && isUnitConcealed(state, unitId) && !opts.ignoreConcealment) {
    return {
      unitId,
      unitName: CONTENT.units[unit.definitionId].name,
      abilityIds: [],
      immediateTiles: [],
      potentialTiles: [],
      byAbility: {},
      attackOrigins: [],
      blockedByLineOfSight: [],
      estimated: false,
      concealed: true
    };
  }
  if (!unit || !unit.alive) {
    return {
      unitId,
      unitName: unit ? CONTENT.units[unit.definitionId].name : null,
      abilityIds: [],
      immediateTiles: [],
      potentialTiles: [],
      byAbility: {},
      attackOrigins: [],
      blockedByLineOfSight: [],
      estimated: false
    };
  }
  const abilityIds = (opts.abilityId ? [opts.abilityId] : unitAbilityIds(state, unitId)).filter(
    (abilityId) => (opts.includeAll ? true : isHostileAbility(abilityId)) &&
      (opts.ignoreAvailability ? true : abilityIsAvailable(state, unitId, abilityId))
  );

  const here = [{ x: unit.x, y: unit.y }];
  const origins = [...here];
  if (opts.includePotential !== false) {
    for (const destination of enumerateValidMoveDestinations(state, unitId)) {
      if (destination.isOrigin) continue;
      origins.push({ x: destination.x, y: destination.y });
    }
  }

  const immediate = new Map();
  const potential = new Map();
  const blocked = new Map();
  const byAbility = {};

  for (const abilityId of abilityIds) {
    const immediateResult = calculateAbilityThreatTiles(state, unitId, abilityId, {
      origins: here
    });
    const potentialResult = calculateAbilityThreatTiles(state, unitId, abilityId, {
      origins
    });
    byAbility[abilityId] = {
      immediateTiles: immediateResult.tiles,
      potentialTiles: potentialResult.tiles,
      blockedByLineOfSight: immediateResult.blockedByLineOfSight
    };
    for (const tile of immediateResult.tiles) immediate.set(tileKey(tile.x, tile.y), tile);
    for (const tile of potentialResult.tiles) potential.set(tileKey(tile.x, tile.y), tile);
    for (const tile of immediateResult.blockedByLineOfSight) {
      blocked.set(tileKey(tile.x, tile.y), tile);
    }
  }

  for (const key of immediate.keys()) potential.delete(key);
  for (const key of immediate.keys()) blocked.delete(key);
  for (const key of potential.keys()) blocked.delete(key);

  return {
    unitId,
    unitName: CONTENT.units[unit.definitionId].name,
    abilityIds,
    immediateTiles: [...immediate.values()],
    potentialTiles: [...potential.values()],
    byAbility,
    attackOrigins: origins,
    blockedByLineOfSight: [...blocked.values()],
    estimated: origins.length > 1
  };
}

/** Threat metadata for the inspector: movement plus per-ability reach. */
function createThreatSummary(state, unitId) {
  const unit = state.units[unitId];
  if (!unit) return null;
  const stats = getUnitDisplayStats(state, unitId);
  const zone = calculateUnitThreatZone(state, unitId, { ignoreAvailability: true });
  return {
    unitId,
    unitName: CONTENT.units[unit.definitionId].name,
    movement: stats.movement,
    immediateCount: zone.immediateTiles.length,
    potentialCount: zone.potentialTiles.length,
    abilities: zone.abilityIds.map((abilityId) => {
      const ability = CONTENT.abilities[abilityId];
      const entry = zone.byAbility[abilityId];
      return {
        abilityId,
        name: ability.name,
        rangeLabel:
          ability.targeting.rangeMin === ability.targeting.rangeMax
            ? "Range " + ability.targeting.rangeMax
            : "Range " + ability.targeting.rangeMin + "–" + ability.targeting.rangeMax,
        immediateTiles: entry.immediateTiles.length,
        potentialTiles: entry.potentialTiles.length,
        available: abilityIsAvailable(state, unitId, abilityId)
      };
    })
  };
}

/** Who threatens this tile, and with what. */
function describeThreatenedTile(state, tile, threatZones) {
  const entries = [];
  for (const zone of threatZones || []) {
    const immediate = zone.immediateTiles.some((entry) => entry.x === tile.x && entry.y === tile.y);
    const potential = zone.potentialTiles.some((entry) => entry.x === tile.x && entry.y === tile.y);
    if (!immediate && !potential) continue;
    entries.push({
      unitId: zone.unitId,
      unitName: zone.unitName,
      kind: immediate ? "immediate" : "potential",
      abilities: zone.abilityIds
        .filter((abilityId) => {
          const byAbility = zone.byAbility[abilityId];
          const list = immediate ? byAbility.immediateTiles : byAbility.potentialTiles;
          return list.some((entry) => entry.x === tile.x && entry.y === tile.y);
        })
        .map((abilityId) => CONTENT.abilities[abilityId].name)
    });
  }
  return entries;
}

/* ---------------------------------------------------------------
 * CONTEXTUAL TARGET OPTIONS ("click a unit and get the right choice")
 * -------------------------------------------------------------*/

function scoreContextualOption(state, activeUnitId, option) {
  const weights = GAME_CONFIG.contextSelection;
  const forecast = option.forecast;
  if (!forecast || !forecast.valid) return -Infinity;
  let score = 0;
  const target = state.units[option.targetUnitId];
  const ally = option.relation !== "enemy";

  for (const outcome of forecast.outcomes) {
    if (outcome.effectType === "damage") {
      const hits = outcome.hits || 1;
      const expected = outcome.amount * hits * (outcome.hitChance == null ? 1 : outcome.hitChance);
      score += (ally ? -weights.friendlyFirePenalty : weights.expectedDamageWeight * expected);
      if (outcome.lethal && !ally) score += weights.lethalBonus;
    } else if (outcome.effectType === "heal") {
      const stats = calculateUnitStats(state, outcome.targetUnitId);
      const missing = stats.maxHp - state.units[outcome.targetUnitId].currentHp;
      const effective = Math.min(outcome.amount, missing);
      score += weights.effectiveHealingWeight * effective;
      if (missing <= 0) score -= weights.redundantEffectPenalty;
    } else if (outcome.effectType === "shield") {
      const existing = target.shields.reduce((sum, shield) => sum + shield.remaining, 0);
      score += weights.shieldWeight * (outcome.amount || 0);
      if (existing > 0) score -= weights.redundantEffectPenalty / 2;
    } else if (outcome.effectType === "applyStatus") {
      const already = target.statuses.some((applied) => applied.statusId === outcome.statusId);
      const definition = CONTENT.statuses[outcome.statusId];
      const helpful = definition && definition.category === "positive";
      const wanted = ally === !!helpful;
      score += (wanted ? 1 : -1) * weights.usefulStatusWeight * (outcome.chance == null ? 1 : outcome.chance);
      if (already) score -= weights.redundantEffectPenalty;
    } else if (outcome.effectType === "modifyStat") {
      const helpful = outcome.mode === "multiplier" ? outcome.value >= 1 : outcome.value >= 0;
      score += (ally === helpful ? 1 : -1) * weights.usefulStatusWeight;
    } else if (outcome.effectType === "cleanse") {
      const negative = target.statuses.filter((applied) => {
        const definition = CONTENT.statuses[applied.statusId];
        return definition && definition.category === "negative";
      }).length;
      score += negative ? weights.usefulStatusWeight * negative : -weights.redundantEffectPenalty;
    } else if (outcome.effectType === "modifyTimeline") {
      score += weights.timelineValueWeight * Math.abs(outcome.delta || 0) * (ally ? 0.5 : 1);
    } else if (outcome.display) {
      score += weights.usefulStatusWeight / 2;
    }
  }

  if (option.requiresMovement) {
    score -= weights.movementCostPenalty * (option.suggestedPath ? option.suggestedPath.length - 1 : 0);
  }
  score -= weights.recoveryPenalty * (forecast.recovery ? forecast.recovery.totalRecovery : 0);
  return Math.round(score * 100) / 100;
}

/**
 * Every ability the active unit could meaningfully use against the clicked
 * unit, scored and sorted. Pure: no mutation, no RNG.
 */
function createContextualTargetOptions(state, activeUnitId, clickedUnitId, options) {
  const opts = options || {};
  const active = state.units[activeUnitId];
  const clicked = state.units[clickedUnitId];
  if (!active || !clicked) return [];
  const resources = createActivationResources(state, activeUnitId);
  const relation =
    activeUnitId === clickedUnitId
      ? "self"
      : isFriendly(state, activeUnitId, clickedUnitId)
      ? "ally"
      : isHostile(state, activeUnitId, clickedUnitId)
      ? "enemy"
      : "neutral";

  const results = [];
  for (const abilityId of unitAbilityIds(state, activeUnitId)) {
    const model = createAbilityViewModel(state, activeUnitId, abilityId);
    const targetTile = { x: clicked.x, y: clicked.y };
    const here = createForecast(state, activeUnitId, abilityId, targetTile);
    const legalNow =
      here.valid &&
      here.affectedUnitIds.includes(clickedUnitId) &&
      !resources.acted &&
      model.cooldownRemaining === 0;

    let option = null;
    if (here.valid && here.affectedUnitIds.includes(clickedUnitId)) {
      option = {
        abilityId,
        targetUnitId: clickedUnitId,
        relation,
        legalNow,
        requiresMovement: false,
        suggestedPath: null,
        suggestedOrigin: { x: active.x, y: active.y },
        forecast: here,
        category: abilityUi(abilityId).category,
        uiOrder: abilityUi(abilityId).order,
        unavailableReason: legalNow ? null : model.unusableReason
      };
    } else if (!resources.moved && !resources.acted && !opts.noMovement) {
      const positions = suggestAttackPositions(state, activeUnitId, clickedUnitId, abilityId).filter(
        (position) => !position.isOrigin
      );
      if (positions.length) {
        const destination = positions[0];
        const projected = createForecast(state, activeUnitId, abilityId, targetTile, {
          origin: { x: destination.x, y: destination.y },
          movementTiles: destination.tiles
        });
        if (projected.valid && projected.affectedUnitIds.includes(clickedUnitId)) {
          option = {
            abilityId,
            targetUnitId: clickedUnitId,
            relation,
            legalNow: false,
            requiresMovement: true,
            suggestedPath: destination.path,
            suggestedOrigin: { x: destination.x, y: destination.y },
            suggestedPositions: positions,
            forecast: projected,
            category: abilityUi(abilityId).category,
            uiOrder: abilityUi(abilityId).order,
            unavailableReason: model.cooldownRemaining ? model.unusableReason : null
          };
        }
      }
    }

    if (!option) continue;
    if (model.cooldownRemaining > 0 || resources.acted) {
      option.legalNow = false;
      option.unavailableReason = option.unavailableReason || model.unusableReason;
      if (opts.includeUnavailable !== true) continue;
    }
    option.recommendationScore = scoreContextualOption(state, activeUnitId, option);
    results.push(option);
  }

  return results.sort(
    (a, b) => b.recommendationScore - a.recommendationScore || a.uiOrder - b.uiOrder
  );
}

/**
 * Decides between "nothing useful", "one obvious choice" and "let the player
 * pick". Auto-selection only happens when a single meaningful option exists.
 */
function resolveContextualSelection(state, activeUnitId, clickedUnitId, options) {
  const all = createContextualTargetOptions(state, activeUnitId, clickedUnitId, options);
  const weights = GAME_CONFIG.contextSelection;
  const meaningful = all.filter(
    (option) => option.recommendationScore >= weights.minimumMeaningfulScore
  );
  if (!all.length) {
    return { mode: "none", options: [], chosen: null, reason: "No available ability reaches that unit." };
  }
  if (!meaningful.length) {
    return {
      mode: "none",
      options: all,
      chosen: null,
      reason: "No useful action available against that unit."
    };
  }
  if (meaningful.length === 1) {
    return { mode: "auto", options: meaningful, chosen: meaningful[0], reason: null };
  }
  const top = meaningful[0];
  const competingImmediateAttack = meaningful
    .slice(1)
    .some((option) => option.legalNow && option.category === "attack");
  if (
    top.legalNow &&
    top.category === "attack" &&
    !competingImmediateAttack &&
    top.recommendationScore - meaningful[1].recommendationScore >= weights.meaningfulScoreGap
  ) {
    return { mode: "auto", options: meaningful, chosen: top, reason: null };
  }
  return {
    mode: "menu",
    options: meaningful,
    chosen: null,
    recommended: meaningful[0],
    reason: null
  };
}
/* =========================================================================
 * HUD / LAYOUT ADAPTER
 * Pure presentation geometry and menu shaping. No battle rules live here:
 * every number that matters comes from the engine or a forecast.
 * =======================================================================*/

const HUD_LAYOUT = {
  minTileSize: 40,
  maxTileSize: 128,
  boardPadding: 20,
  panelGap: 18,
  reserved: {
    // Slim top and bottom bands; the major battle UI floats over the scene.
    top: 110,
    bottom: 56,
    left: 0,
    right: 0
  }
};

/**
 * Square tiles sized so the whole map fits the viewport without scrolling.
 */
function calculateBattlefieldLayout(options) {
  const opts = options || {};
  const reserved = { ...HUD_LAYOUT.reserved, ...(opts.reserved || {}) };
  const viewportWidth = Math.max(320, opts.viewportWidth || 1280);
  const viewportHeight = Math.max(320, opts.viewportHeight || 800);
  const mapWidth = opts.mapWidth || 8;
  const mapHeight = opts.mapHeight || 8;
  const compact = viewportWidth < (opts.compactBreakpoint || 900);

  const sideReserve = compact ? 0 : reserved.left + reserved.right;
  const availableWidth = Math.max(
    120,
    viewportWidth - sideReserve - HUD_LAYOUT.boardPadding * 2
  );
  const availableHeight = Math.max(
    120,
    viewportHeight - reserved.top - reserved.bottom - HUD_LAYOUT.boardPadding * 2
  );

  const rawTile = Math.min(availableWidth / mapWidth, availableHeight / mapHeight);
  const tileSize = Math.max(
    opts.minTileSize || HUD_LAYOUT.minTileSize,
    Math.min(opts.maxTileSize || HUD_LAYOUT.maxTileSize, Math.floor(rawTile))
  );

  const boardWidth = tileSize * mapWidth;
  const boardHeight = tileSize * mapHeight;
  const usableArea = viewportWidth * viewportHeight;
  const boardArea = boardWidth * boardHeight;
  const stageArea = (availableWidth + HUD_LAYOUT.boardPadding * 2) * (availableHeight + HUD_LAYOUT.boardPadding * 2);

  return {
    tileSize,
    compact,
    mapWidth,
    mapHeight,
    boardWidth,
    boardHeight,
    availableWidth,
    availableHeight,
    boardLeft: Math.round((availableWidth - boardWidth) / 2) + HUD_LAYOUT.boardPadding,
    boardTop: reserved.top + Math.round((availableHeight - boardHeight) / 2) + HUD_LAYOUT.boardPadding,
    fitsWithoutScrolling: boardWidth <= availableWidth && boardHeight <= availableHeight,
    stageBounds: {
      left: 4,
      top: reserved.top - 4,
      right: viewportWidth - (compact ? 4 : reserved.right),
      bottom: viewportHeight - reserved.bottom + 4
    },
    boardArea,
    usableArea,
    stageArea,
    stageShare: Math.round((stageArea / usableArea) * 1000) / 1000,
    boardShare: Math.round((boardArea / stageArea) * 1000) / 1000
  };
}

/**
 * Places a floating panel beside a battlefield tile, flipping and clamping so
 * it never leaves the viewport and never covers its own anchor tile.
 */
function calculateFloatingPanelPosition(options) {
  const opts = options || {};
  const tileSize = opts.tileSize || 64;
  const gap = opts.gap == null ? HUD_LAYOUT.panelGap : opts.gap;
  const panelWidth = opts.panelWidth || 240;
  const panelHeight = opts.panelHeight || 200;
  const board = opts.board || { left: 0, top: 0 };
  const viewport = opts.viewport || { width: 1280, height: 800 };
  const bounds = opts.bounds || {
    left: 4,
    top: 4,
    right: viewport.width - 4,
    bottom: viewport.height - 4
  };

  // Screen-space anchor rectangles come from the projection layer; the tile
  // form is kept for flat callers and tests.
  const anchor = opts.anchor || { x: 0, y: 0 };
  const rect = opts.anchorRect || null;
  const anchorLeft = rect ? rect.left : board.left + anchor.x * tileSize;
  const anchorTop = rect ? rect.top : board.top + anchor.y * tileSize;
  const anchorRight = rect ? rect.right : anchorLeft + tileSize;
  const anchorBottom = rect ? rect.bottom : anchorTop + tileSize;
  const anchorWidth = anchorRight - anchorLeft;

  let placement = "right";
  let left = anchorRight + gap;
  if (left + panelWidth > bounds.right) {
    placement = "left";
    left = anchorLeft - gap - panelWidth;
  }
  let flippedX = placement === "left";

  let top = anchorTop;
  let flippedY = false;
  if (top + panelHeight > bounds.bottom) {
    flippedY = true;
    top = anchorBottom - panelHeight;
  }

  // Nowhere to the side: place above or below instead.
  if (left < bounds.left) {
    placement = anchorTop - gap - panelHeight >= bounds.top ? "above" : "below";
    left = anchorLeft + anchorWidth / 2 - panelWidth / 2;
    top = placement === "above" ? anchorTop - gap - panelHeight : anchorBottom + gap;
    flippedX = false;
    flippedY = placement === "above";
  }

  const clampedLeft = Math.max(bounds.left, Math.min(left, bounds.right - panelWidth));
  const clampedTop = Math.max(bounds.top, Math.min(top, bounds.bottom - panelHeight));

  const overlapsAnchor =
    clampedLeft < anchorRight &&
    clampedLeft + panelWidth > anchorLeft &&
    clampedTop < anchorBottom &&
    clampedTop + panelHeight > anchorTop;

  return {
    left: Math.round(clampedLeft),
    top: Math.round(clampedTop),
    placement,
    flippedX,
    flippedY,
    clamped: clampedLeft !== Math.round(left) || clampedTop !== Math.round(top),
    coversAnchor: overlapsAnchor,
    withinViewport:
      clampedLeft >= bounds.left &&
      clampedTop >= bounds.top &&
      clampedLeft + panelWidth <= bounds.right &&
      clampedTop + panelHeight <= bounds.bottom,
    anchorTile: { x: anchor.x, y: anchor.y },
    anchorRect: {
      left: anchorLeft,
      top: anchorTop,
      right: anchorRight,
      bottom: anchorBottom
    },
    panelWidth,
    panelHeight
  };
}

/* ---------------------------------------------------------------
 * PANEL SURFACES (opacity and depth come from configuration)
 * -------------------------------------------------------------*/

const PANEL_SURFACES = ["primary", "secondary", "overlay"];

/**
 * Inline style for a readable floating surface. Values come from
 * GAME_CONFIG.presentation.panels so no component hard-codes opacity.
 */
function createPanelStyle(kind, overrides) {
  const config = GAME_CONFIG.presentation.panels;
  const opacity =
    kind === "secondary"
      ? config.secondaryBackgroundOpacity
      : kind === "overlay"
      ? config.overlayBackgroundOpacity
      : config.primaryBackgroundOpacity;
  return {
    backgroundColor: "rgba(2, 6, 23, " + opacity + ")",
    borderColor: "rgba(148, 163, 184, " + config.borderOpacity + ")",
    boxShadow: "0 10px 30px rgba(0, 0, 0, " + config.shadowStrength + ")",
    backdropFilter: "blur(" + config.backdropBlurPx + "px)",
    WebkitBackdropFilter: "blur(" + config.backdropBlurPx + "px)",
    ...(overrides || {})
  };
}

function panelOpacity(kind) {
  const config = GAME_CONFIG.presentation.panels;
  if (kind === "secondary") return config.secondaryBackgroundOpacity;
  if (kind === "overlay") return config.overlayBackgroundOpacity;
  return config.primaryBackgroundOpacity;
}

/** Overlay colours for the two danger-zone layers. */
function createDangerZoneStyles() {
  const danger = GAME_CONFIG.presentation.dangerZone;
  return {
    immediate: { backgroundColor: "rgba(190, 18, 60, " + danger.immediateOpacity + ")" },
    potential: {
      backgroundColor: "rgba(244, 63, 94, " + danger.potentialOpacity + ")",
      backgroundImage:
        "repeating-linear-gradient(45deg, rgba(244,63,94,0.35) 0 4px, rgba(0,0,0,0) 4px 8px)"
    }
  };
}

/* ---------------------------------------------------------------
 * CONTEXTUAL COMMAND MODEL
 * -------------------------------------------------------------*/

const CONTEXT_PANEL_KINDS = [
  "hidden",
  "commands",
  "abilities",
  "movePlan",
  "attackPlan",
  "combinedPlan"
];

/**
 * The single floating panel, in whichever mode the current input state calls
 * for. Contains the anchor tile, the headline numbers and the button set.
 */
function createContextCommandModel(state, input, options) {
  const opts = options || {};
  const hidden = {
    kind: "hidden",
    visible: false,
    anchorTile: null,
    title: null,
    resources: null,
    forecast: null,
    lines: [],
    actions: [],
    abilities: []
  };
  if (!state.activeUnitId) return hidden;
  if (input.mode === "presentingEvents" || input.mode === "battleFinished") return hidden;

  const unitId = state.activeUnitId;
  const unit = state.units[unitId];
  const resources = createActivationResources(state, unitId);
  const definition = CONTENT.units[unit.definitionId];
  const menu = createCommandMenu(state, unitId, {
    targetUnitId: opts.targetUnitId,
    origin: opts.origin,
    movementTiles: opts.movementTiles,
    suggestedAbilityId: opts.suggestedAbilityId
  });
  const abilityEntries = menu.entries.filter((entry) => entry.kind === "ability");

  const base = {
    unitId,
    unitName: definition.name,
    resources,
    visible: true,
    lines: [],
    forecast: null,
    abilities: abilityEntries,
    anchorTile: { x: unit.x, y: unit.y }
  };

  const action = (id, label, shortcut, enabled, reason) => ({
    id,
    label,
    shortcut: shortcut || null,
    enabled: enabled !== false,
    reason: reason || null
  });

  // Combined move-and-attack plan.
  if (input.plannedSequence && input.forecast) {
    const destination = input.plannedMoveDestination;
    return {
      ...base,
      kind: "combinedPlan",
      anchorTile: destination ? { ...destination } : base.anchorTile,
      title: "Move " + (input.plannedSequence.path.length - 1) + " tiles, then " + input.forecast.abilityName,
      forecast: input.forecast,
      lines: [
        {
          label: "Move",
          value: input.plannedSequence.path.length - 1 + " tiles"
        }
      ],
      actions: [
        action("confirm", "Confirm", "Enter"),
        action("changeTile", "Change tile", "M"),
        action("changeAbility", "Change ability", "1-9"),
        action("cancel", "Cancel", "Esc")
      ]
    };
  }

  // Target selected: attack or heal forecast.
  if (input.mode === "confirmingAction" && input.forecast) {
    return {
      ...base,
      kind: "attackPlan",
      anchorTile: input.selectedTarget ? { ...input.selectedTarget } : base.anchorTile,
      title: input.forecast.abilityName,
      forecast: input.forecast,
      // A chaining ability shows what it reaches beyond the unit aimed at,
      // because that is the part of the decision the reticle cannot express.
      chain: opts.chain || null,
      actions: [
        action("confirm", "Confirm attack", "Enter"),
        action("changeAbility", "Choose different ability", "1-9"),
        action("cancel", "Cancel", "Esc")
      ]
    };
  }

  // Movement planned but not committed.
  if (input.mode === "planningMove" && input.plannedPath && input.plannedMoveDestination) {
    const tiles = input.plannedPath.length - 1;
    const recovery = calculateActionRecoveryPreview(state, unitId, null, tiles);
    return {
      ...base,
      kind: "movePlan",
      anchorTile: { ...input.plannedMoveDestination },
      title: "Move here",
      lines: [
        { label: "Tiles", value: String(tiles) },
        { label: "Recovery", value: String(recovery.movementRecovery) },
        {
          label: "Next action",
          value: String(Math.round(recovery.projectedNextActionTime))
        }
      ],
      recovery,
      actions: [
        action("confirm", "Confirm move", "Enter"),
        action("attackFromHere", "Choose attack from here", "1-9"),
        action("cancel", "Cancel", "Esc")
      ]
    };
  }

  // Contextual choice list produced by clicking a unit.
  if (input.contextOptions && input.contextOptions.length) {
    const clicked = state.units[input.contextTargetUnitId];
    return {
      ...base,
      kind: "contextOptions",
      anchorTile: clicked ? { x: clicked.x, y: clicked.y } : base.anchorTile,
      title: clicked ? "Target " + CONTENT.units[clicked.definitionId].name : "Choose an ability",
      contextOptions: input.contextOptions.map((option, index) => ({
        ...option,
        abilityName: CONTENT.abilities[option.abilityId].name,
        icon: resolveDefinitionAsset(CONTENT.abilities[option.abilityId], "icon", "?"),
        recommended: index === 0,
        shortcut: String(index + 1)
      })),
      actions: [action("cancel", "Cancel", "Esc")]
    };
  }

  // A route being drawn. Everything shown here comes from the planner that
  // will run it, so the panel cannot promise a route the engine then refuses.
  if (input.mode === "planningRoute") {
    const route = createRoutePlanModel(state, input, opts.routeCandidate);
    if (route) {
      const lines = [
        { label: "Legs", value: route.segments.length + " / " + route.maxSegments },
        { label: "Distance", value: route.distance + " / " + route.maxDistance }
      ];
      if (route.cost.resourceId) {
        lines.push({
          label: route.cost.resourceName,
          value:
            route.cost.amount +
            (route.cost.available == null ? "" : " of " + route.cost.available)
        });
      }
      const actions = [
        action(
          "confirm",
          "Run the route",
          "Enter",
          !route.empty && route.legal && route.cost.affordable,
          route.empty
            ? "Click a tile to lay the first leg."
            : !route.legal
            ? route.reason
            : route.cost.reason
        ),
        action("undoRouteSegment", "Undo leg", "Backspace", route.committedCount > 0),
        action("cancel", "Cancel", "Esc")
      ];
      return {
        ...base,
        kind: "route",
        anchorTile: { ...route.endpoint },
        title: route.abilityName,
        route,
        lines,
        actions
      };
    }
  }

  // An order being arranged. Same contract as the route panel: everything
  // shown comes from the planner that will run it, so the panel cannot promise
  // a sequence the engine then refuses.
  if (input.mode === "planningOrder") {
    const plan = createCommandPlanModel(state, input.selectedUnitId, input.selectedAbilityId, input.plannedOrder || []);
    if (plan) {
      const lines = [
        { label: "Sequencing", value: (input.plannedOrder || []).length + " / " + plan.maxUnits },
        { label: "Cost", value: plan.costText }
      ];
      if (plan.barrier) lines.push({ label: "Blocked by", value: plan.barrier.name });
      return {
        ...base,
        kind: "order",
        title: plan.abilityName,
        order: plan,
        lines,
        actions: [
          action(
            "confirmOrder",
            "Issue the order",
            "Enter",
            plan.ok,
            plan.reason || "Pick the units in the order you want them."
          ),
          action("undoOrderPick", "Undo pick", "Backspace", (input.plannedOrder || []).length > 0),
          action("cancel", "Cancel", "Esc")
        ]
      };
    }
  }

  // Ability list.
  if (input.mode === "planningTarget" || opts.abilityMenuOpen) {
    return {
      ...base,
      kind: "abilities",
      title: "Abilities",
      selectedAbilityId: input.selectedAbilityId || null,
      actions: [action("cancel", "Back", "Esc")]
    };
  }

  // Default: the command list. It stays hidden until the player asks for it,
  // so a new activation shows only the active-unit indicator.
  if (!input.commandMenuOpen && !opts.forceOpen) {
    return { ...hidden, unitId, resources, abilities: abilityEntries };
  }
  const actions = [];
  actions.push(
    action(
      "move",
      "Move",
      "M",
      resources.active && !resources.moved && !resources.ended,
      resources.moved ? "Already moved this activation." : null
    )
  );
  actions.push(
    action(
      "abilities",
      "Abilities",
      "1-9",
      resources.active && !resources.acted && !resources.ended,
      resources.acted ? "Already acted this activation." : null
    )
  );
  actions.push(
    action("wait", "Wait", "Q", resources.active && !resources.acted && !resources.ended,
      resources.acted ? "Already acted this activation." : null)
  );
  actions.push(action("endTurn", "End Turn", "E", resources.active && !resources.ended));

  return {
    ...base,
    kind: "commands",
    title: definition.name,
    lines: [
      { label: "MOVE", value: resources.moveLabel },
      { label: "ACTION", value: resources.actionLabel }
    ],
    actions
  };
}

/* ---------------------------------------------------------------
 * HOVER FORECAST BADGES
 * -------------------------------------------------------------*/

/**
 * The small badge shown while the pointer rests on a tile. Never commits or
 * mutates anything; all numbers come from engine forecasts.
 */
function createHoverForecastModel(state, input, tile) {
  if (!tile || !state.activeUnitId) return null;
  const unitId = state.activeUnitId;
  if (input.selectedUnitId && input.selectedUnitId !== unitId) return null;
  const occupant = unitAt(state, tile.x, tile.y);
  const resources = createActivationResources(state, unitId);

  if (occupant && occupant.id !== unitId) {
    if (input.mode === "planningTarget" && input.selectedAbilityId) {
      const forecast = createForecast(
        state,
        unitId,
        input.selectedAbilityId,
        { x: tile.x, y: tile.y },
        { origin: inputStateOrigin(input, state) }
      );
      return forecast.valid ? badgeFromForecast(forecast, null) : null;
    }
    if (resources.acted) return null;
    const plan = suggestAttackPlan(state, unitId, occupant.id);
    if (!plan || !plan.forecast || !plan.forecast.valid) return null;
    return badgeFromForecast(plan.forecast, plan.requiresMovement ? plan.destination.tiles : null);
  }

  if (!occupant && !resources.moved && input.mode !== "planningTarget") {
    const destinations = enumerateValidMoveDestinations(state, unitId);
    const destination = destinations.find((entry) => entry.x === tile.x && entry.y === tile.y);
    if (!destination) return null;
    return {
      kind: "move",
      title: destination.tiles + (destination.tiles === 1 ? " tile" : " tiles"),
      value: "+" + destination.movementRecovery + " recovery",
      tile: { x: tile.x, y: tile.y },
      moveTiles: destination.tiles
    };
  }
  return null;
}

function badgeFromForecast(forecast, moveTiles) {
  const headline = forecast.headline;
  const isHeal = headline.kind === "heal";
  const parts = [];
  if (headline.value != null) {
    parts.push((isHeal ? "+" : "") + headline.value + (isHeal ? " HP" : " DMG"));
  }
  if (headline.lethal) parts.push("KO");
  else if (headline.hitChancePercent != null) parts.push(headline.hitChancePercent + "%");
  for (const line of forecast.lines) parts.push(line.label + " " + line.value);
  return {
    kind: isHeal ? "heal" : "damage",
    title: (moveTiles ? "Move " + moveTiles + " · " : "") + forecast.abilityName,
    value: parts.join(" · "),
    lethal: !!headline.lethal,
    moveTiles: moveTiles || null,
    tile: forecast.target
      ? null
      : null,
    targetUnitId: forecast.target ? forecast.target.unitId : null
  };
}

/* ---------------------------------------------------------------
 * TOP HUD + UNIT CARD
 * -------------------------------------------------------------*/

function humanizeId(id) {
  return String(id)
    .replace(/([A-Z])/g, " $1")
    .replace(/^./, (character) => character.toUpperCase())
    .trim();
}

function createBattleHudModel(state) {
  const encounter = CONTENT.encounters[state.encounterId];
  // A scripted mission owns a live objective stack; an unscripted encounter
  // still shows its single authored line.
  const stack = (state.objectiveState.entries || []).filter((entry) => !entry.hidden);
  const objectiveLine = stack.length
    ? stack
        .map((entry) => (entry.status === "complete" ? "✓ " : entry.status === "failed" ? "✗ " : "") + (entry.text || entry.ref))
        .join("   ·   ")
    : encounter.objectiveText || humanizeId(state.objectiveState.objectiveId);
  return {
    encounterName: encounter.name,
    objective: objectiveLine,
    objectives: stack.map((entry) => ({
      ref: entry.ref,
      text: entry.text || entry.ref,
      status: entry.status,
      required: entry.required
    })),
    missionPhase: state.mission ? state.mission.phaseId : null,
    currentTime: Math.round(state.currentTime),
    activationCount: state.activationCount,
    seed: state.randomSeed,
    finished: state.finished,
    winner: state.winner,
    teams: state.teams.map((team) => ({
      ...team,
      aliveCount: state.unitOrder.filter(
        (id) => state.units[id].alive && state.units[id].teamId === team.id
      ).length
    })),
    activeUnitId: state.activeUnitId
  };
}

/**
 * Everything the character screen shows for any unit, ally or enemy. Kept
 * apart from the compact battlefield menu on purpose.
 */
function createCharacterSheetModel(state, unitId) {
  if (!unitId || !state.units[unitId]) return null;
  const unit = state.units[unitId];
  const definition = CONTENT.units[unit.definitionId];
  const model = createUnitViewModel(state, unitId);
  const stats = getUnitDisplayStats(state, unitId);
  const timeline = createTimelineViewModel(state, GAME_CONFIG.timeline.previewCount);
  const position = timeline.findIndex((entry) => entry.unitId === unitId);

  return {
    unitId,
    name: model.name,
    className: definition.classId || "unclassed",
    description: definition.description,
    portrait: model.portrait,
    teamId: model.teamId,
    teamName: model.teamName,
    teamMarker: model.teamMarker,
    teamAccent: model.teamAccent,
    controller: model.controller,
    aiProfileId: model.aiProfileId,
    summonedBy: unit.summonedBy || null,

    currentHp: model.currentHp,
    maxHp: model.maxHp,
    hpPercent: model.hpPercent,
    alive: model.alive,

    stats,
    movement: {
      movement: stats.movement,
      maxClimb: stats.maxClimb,
      maxDrop: stats.maxDrop,
      elevation: model.elevation,
      tile: { x: unit.x, y: unit.y }
    },

    timeline: {
      nextActionTime: Math.round(unit.nextActionTime),
      currentTime: Math.round(state.currentTime),
      position: position < 0 ? null : position + 1,
      turnRate: stats.turnRate,
      speedMultiplier: stats.speedMultiplier,
      isActive: state.activeUnitId === unitId
    },

    resources: Object.keys(unit.resources || {}).map((resourceId) => ({
      resourceId,
      current: unit.resources[resourceId].current,
      max: unit.resources[resourceId].max
    })),

    statuses: model.statuses,
    shields: (unit.shields || []).map((shield) => ({
      amount: shield.remaining,
      remaining: shield.remainingDuration
    })),
    passives: (unit.modifiers || []).map((modifier) => ({
      stat: modifier.stat,
      mode: modifier.mode,
      value: modifier.value,
      remaining: modifier.remainingDuration
    })),

    equipment: GAME_CONFIG.equipment.slots
      .map((slot) => {
        const equipmentId = (unit.equipment || {})[slot];
        const item = equipmentId ? CONTENT.equipment[equipmentId] : null;
        return {
          slot,
          slotName: GAME_CONFIG.equipment.slotNames[slot] || slot,
          equipmentId: equipmentId || null,
          name: item ? item.name : "Empty",
          description: item ? item.description : "",
          tags: item ? item.tags : [],
          modifiers: item ? item.modifiers : [],
          grantsAbilities: item ? item.grantsAbilities : []
        };
      }),

    abilities: getUnitAbilities(state, unitId).map((abilityId) => {
      const ability = CONTENT.abilities[abilityId];
      const view = createAbilityViewModel(state, unitId, abilityId);
      return {
        abilityId,
        name: ability.name,
        description: ability.description,
        category: abilityUi(abilityId).category,
        icon: view.icon,
        rangeLabel: view.rangeLabel,
        recovery: view.recovery,
        cooldown: view.cooldown,
        cooldownRemaining: view.cooldownRemaining,
        costs: Object.keys(ability.costs || {}).map(
          (resourceId) => ability.costs[resourceId] + " " + resourceId
        )
      };
    })
  };
}

function createUnitCardModel(state, unitId) {
  if (!unitId || !state.units[unitId]) return null;
  const model = createUnitViewModel(state, unitId);
  const resources = createActivationResources(state, unitId);
  return {
    ...model,
    resources,
    speedLabel: Math.round(model.stats.speed) + " · " + model.stats.turnRate + "x",
    statusLabels: model.statuses.map(
      (status) => status.name + ": " + status.remaining + " activations"
    )
  };
}

/* ---------------------------------------------------------------
 * PRE-BATTLE DEPLOYMENT
 * Chassis selection and equipment fitting, entirely data driven.
 * -------------------------------------------------------------*/

/** Every chassis the player may deploy, in a stable order. */
function deployableChassis() {
  return Object.keys(CONTENT.units)
    .filter((definitionId) => (CONTENT.units[definitionId].tags || []).includes("deployable"))
    .sort((a, b) => a.localeCompare(b));
}

function createDefaultLoadout(definitionId) {
  const definition = CONTENT.units[definitionId];
  const loadout = {};
  for (const slot of GAME_CONFIG.equipment.slots) {
    const equipmentId = definition.defaultEquipment[slot] || null;
    loadout[slot] = equipmentId && isEquipmentCompatible(definitionId, equipmentId)
      ? equipmentId
      : null;
  }
  return loadout;
}

/** The starting setup state: nothing selected, default loadouts prepared. */
/** The encounter the setup screen deploys into, discovered from content. */
function deploymentEncounterId() {
  const rules = GAME_CONFIG.deployment;
  if (rules.encounterId && CONTENT.encounters[rules.encounterId]) return rules.encounterId;
  return Object.keys(CONTENT.encounters)[0];
}

function createDeploymentState() {
  const loadouts = {};
  for (const definitionId of deployableChassis()) {
    loadouts[definitionId] = createDefaultLoadout(definitionId);
  }
  return {
    selected: [],
    loadouts,
    inspectedDefinitionId: deployableChassis()[0] || null
  };
}

/** Which parts the test inventory offers for a slot, with compatibility. */
function inventoryForSlot(definitionId, slot) {
  return Object.keys(CONTENT.equipment)
    .filter((equipmentId) => CONTENT.equipment[equipmentId].slot === slot)
    .map((equipmentId) => {
      const item = CONTENT.equipment[equipmentId];
      const compatible = isEquipmentCompatible(definitionId, equipmentId);
      return {
        equipmentId,
        name: item.name,
        slot,
        description: item.description,
        tags: item.tags,
        modifiers: item.modifiers,
        grantsAbilities: item.grantsAbilities,
        compatible,
        reason: compatible ? null : equipmentCompatibilityReason(definitionId, equipmentId)
      };
    })
    .sort((a, b) => Number(b.compatible) - Number(a.compatible) || a.name.localeCompare(b.name));
}

/** Pure selection toggle honouring the team size and uniqueness rules. */
function toggleDeploymentSelection(deployment, definitionId) {
  const rules = GAME_CONFIG.deployment;
  const selected = deployment.selected.slice();
  const index = selected.indexOf(definitionId);
  if (index >= 0) {
    selected.splice(index, 1);
    return { ...deployment, selected, inspectedDefinitionId: definitionId };
  }
  if (rules.uniqueClasses && selected.includes(definitionId)) return deployment;
  if (selected.length >= rules.teamSize) {
    return {
      ...deployment,
      inspectedDefinitionId: definitionId,
      error: "Deploy exactly " + rules.teamSize + " mechs; remove one first."
    };
  }
  selected.push(definitionId);
  return { ...deployment, selected, inspectedDefinitionId: definitionId, error: null };
}

/** Fits a part, refusing anything the chassis cannot carry. */
function equipDeploymentPart(deployment, definitionId, slot, equipmentId) {
  if (equipmentId && !isEquipmentCompatible(definitionId, equipmentId)) {
    return {
      ...deployment,
      error: equipmentCompatibilityReason(definitionId, equipmentId)
    };
  }
  const item = equipmentId ? CONTENT.equipment[equipmentId] : null;
  if (item && item.slot !== slot) {
    return { ...deployment, error: item.name + " does not fit that slot." };
  }
  return {
    ...deployment,
    error: null,
    loadouts: {
      ...deployment.loadouts,
      [definitionId]: { ...deployment.loadouts[definitionId], [slot]: equipmentId || null }
    }
  };
}

function validateDeployment(deployment) {
  const rules = GAME_CONFIG.deployment;
  const errors = [];
  const selected = deployment.selected;
  if (selected.length !== rules.teamSize) {
    errors.push("Select exactly " + rules.teamSize + " mechs (" + selected.length + " chosen).");
  }
  if (rules.uniqueClasses && new Set(selected).size !== selected.length) {
    errors.push("Each mech class may only be deployed once.");
  }
  for (const definitionId of selected) {
    const loadout = deployment.loadouts[definitionId] || {};
    for (const slot of GAME_CONFIG.equipment.slots) {
      const equipmentId = loadout[slot];
      if (!equipmentId) continue;
      if (!isEquipmentCompatible(definitionId, equipmentId)) {
        errors.push(equipmentCompatibilityReason(definitionId, equipmentId));
      }
    }
  }
  return { valid: errors.length === 0, errors };
}

/** The roster handed to createBattle once the player presses Deploy. */
function createDeploymentRoster(deployment) {
  return deployment.selected.map((definitionId) => ({
    definitionId,
    equipment: { ...(deployment.loadouts[definitionId] || {}) }
  }));
}

/**
 * Preview of a build without touching any battle: stats, abilities and
 * fitted parts, all resolved through the same engine pipeline.
 */
function createDeploymentPreview(deployment, definitionId) {
  if (!definitionId || !CONTENT.units[definitionId]) return null;
  const definition = CONTENT.units[definitionId];
  const loadout = deployment.loadouts[definitionId] || {};
  const probe = createBattle(deploymentEncounterId(), 1, {
    roster: [{ definitionId, equipment: loadout }],
    rosterTeamId: "player"
  });
  const unitId = probe.unitOrder[0];
  const stats = getUnitDisplayStats(probe, unitId);
  const baseStats = definition.baseStats;

  return {
    definitionId,
    name: definition.name,
    className: definition.classId,
    role: definition.role,
    description: definition.description,
    glyph: definition.glyph,
    portrait: resolveDefinitionAsset(definition, "portrait", definition.glyph),
    stats,
    statDeltas: Object.keys(baseStats).reduce((deltas, stat) => {
      if (stats[stat] != null) deltas[stat] = Math.round((stats[stat] - baseStats[stat]) * 100) / 100;
      return deltas;
    }, {}),
    maxHp: stats.maxHp,
    movement: {
      movement: stats.movement,
      maxClimb: stats.maxClimb,
      maxDrop: stats.maxDrop
    },
    abilities: getUnitAbilities(probe, unitId).map((abilityId) => {
      const ability = CONTENT.abilities[abilityId];
      const granted = equippedItems(probe, unitId).some((item) =>
        item.grantsAbilities.includes(abilityId)
      );
      return {
        abilityId,
        name: ability.name,
        description: ability.description,
        category: abilityUi(abilityId).category,
        rangeLabel:
          ability.targeting.rangeMin === ability.targeting.rangeMax
            ? "Range " + ability.targeting.rangeMax
            : "Range " + ability.targeting.rangeMin + "–" + ability.targeting.rangeMax,
        recovery: ability.timing.recovery,
        cooldown: ability.timing.cooldown,
        granted
      };
    }),
    slots: GAME_CONFIG.equipment.slots.map((slot) => {
      const equipmentId = loadout[slot] || null;
      const item = equipmentId ? CONTENT.equipment[equipmentId] : null;
      return {
        slot,
        slotName: GAME_CONFIG.equipment.slotNames[slot] || slot,
        equipmentId,
        name: item ? item.name : "Empty",
        description: item ? item.description : "",
        modifiers: item ? item.modifiers : [],
        grantsAbilities: item ? item.grantsAbilities : [],
        options: inventoryForSlot(definitionId, slot)
      };
    })
  };
}

/* ---------------------------------------------------------------
 * ABILITY TOOLTIPS AND THE BATTLE HUD
 * -------------------------------------------------------------*/

function abilityGlyph(abilityId) {
  const ability = CONTENT.abilities[abilityId];
  const meta = (ability && ability.ui) || {};
  return meta.glyph || (ability ? ability.name[0] : "?");
}

/** Which fitted part granted this ability, if any. */
function abilitySourceEquipment(state, unitId, abilityId) {
  const definition = CONTENT.units[state.units[unitId].definitionId];
  if (definition.abilities.includes(abilityId)) return null;
  const item = equippedItems(state, unitId).find((entry) =>
    entry.grantsAbilities.includes(abilityId)
  );
  return item ? { equipmentId: item.id, name: item.name } : null;
}

/** Plain-language summary of what an ability actually does. */
function summariseAbilityEffects(state, unitId, abilityId) {
  const ability = CONTENT.abilities[abilityId];
  const lines = [];
  const describe = (effects, prefix) => {
    for (const effect of effects || []) {
      if (effect.type === "damage") {
        lines.push(prefix + "Damage " + effect.power + " power" + (effect.canMiss ? "" : " (never misses)"));
      } else if (effect.type === "heal") {
        lines.push(prefix + "Repairs " + effect.power + " power");
      } else if (effect.type === "shield") {
        lines.push(prefix + "Shield " + effect.amount);
      } else if (effect.type === "applyStatus") {
        const status = CONTENT.statuses[effect.statusId];
        lines.push(
          prefix +
            status.name +
            (effect.chance != null && effect.chance < 1
              ? " (" + Math.round(effect.chance * 100) + "%)"
              : "")
        );
      } else if (effect.type === "removeStatus" || effect.type === "cleanse") {
        lines.push(prefix + "Clears " + (effect.statusId ? CONTENT.statuses[effect.statusId].name : effect.category || "statuses"));
      } else if (effect.type === "modifyStat") {
        lines.push(prefix + effect.stat + " " + (effect.mode === "multiplier" ? "x" + effect.value : (effect.value > 0 ? "+" : "") + effect.value));
      } else if (effect.type === "push" || effect.type === "pull" || effect.type === "moveUnit") {
        lines.push(prefix + effect.type + " " + (effect.distance || 1) + " tiles");
      } else if (effect.type === "spawnUnit") {
        lines.push(prefix + "Deploys " + CONTENT.units[effect.definitionId].name);
      } else if (effect.type === "repeatEffect") {
        describe(effect.effects, prefix + effect.count + "x ");
      } else if (effect.type === "conditionalEffect") {
        describe(effect.ifTrue, prefix + "If condition: ");
        describe(effect.ifFalse, prefix + "Otherwise: ");
      } else if (effect.type === "refreshActivationResource") {
        lines.push(prefix + "Refunds " + (effect.resource === "action" ? "action" : "movement"));
      }
    }
  };
  describe(ability.effects, "");
  return lines;
}

/** Everything a tooltip needs, resolved from data and the live build. */
function createAbilityTooltipModel(state, unitId, abilityId) {
  const ability = CONTENT.abilities[abilityId];
  if (!ability) return null;
  const view = createAbilityViewModel(state, unitId, abilityId);
  const targeting = ability.targeting;
  const conditions = [];
  if (ability.requirementText) conditions.push(ability.requirementText);
  const actor = state.units[unitId];
  const breaksConcealment =
    targeting.type === "enemy" &&
    actor.statuses.some((applied) => {
      const definition = CONTENT.statuses[applied.statusId];
      return definition && definition.removedOnHostileAction;
    });
  if (breaksConcealment) conditions.push("Breaks concealment.");
  if (targeting.type === "ally") conditions.push("Requires an ally target.");
  if (targeting.type === "self") conditions.push("Targets this mech.");
  if (targeting.type === "emptyTile") conditions.push("Requires an empty tile.");
  for (const effect of ability.effects) {
    if (effect.type === "removeStatus" && effect.applyTo === "source") {
      conditions.push("Consumes " + CONTENT.statuses[effect.statusId].name + ".");
    }
  }

  return {
    abilityId,
    name: ability.name,
    glyph: abilityGlyph(abilityId),
    icon: view.icon,
    description: ability.description,
    category: abilityUi(abilityId).category,
    effects: summariseAbilityEffects(state, unitId, abilityId),
    rangeLabel: view.rangeLabel,
    areaShape: targeting.area.shape || "single",
    recovery: view.recovery,
    cooldown: view.cooldown,
    cooldownRemaining: view.cooldownRemaining,
    costs: Object.keys(ability.costs || {}).map(
      (resourceId) => ability.costs[resourceId] + " " + resourceId
    ),
    conditions,
    grantedBy: abilitySourceEquipment(state, unitId, abilityId),
    usable: view.usable,
    unusableReason: view.unusableReason
  };
}

/**
 * The compact bottom-left battle HUD: pilot and chassis identity, activation
 * resources and a row of ability icons with their tooltips.
 */
function createBattleHudPanelModel(state, unitId) {
  if (!unitId || !state.units[unitId]) return null;
  const unit = state.units[unitId];
  const definition = CONTENT.units[unit.definitionId];
  const model = createUnitViewModel(state, unitId);
  const resources = createActivationResources(state, unitId);
  return {
    unitId,
    name: model.name,
    className: definition.classId,
    mechGlyph: "🤖",
    operatorGlyph: "🧑‍🚀",
    portrait: model.portrait,
    facing: model.facing,
    currentHp: model.currentHp,
    maxHp: model.maxHp,
    hpPercent: model.hpPercent,
    teamAccent: model.teamAccent,
    resources,
    abilities: unitAbilityIds(state, unitId).map((abilityId) => {
      const tooltip = createAbilityTooltipModel(state, unitId, abilityId);
      return {
        abilityId,
        glyph: tooltip.glyph,
        name: tooltip.name,
        usable: tooltip.usable,
        cooldownRemaining: tooltip.cooldownRemaining,
        unusableReason: tooltip.unusableReason,
        tooltip
      };
    })
  };
}
/* =========================================================================
 * PROJECTION AND CAMERA (presentation only)
 * Pure geometry: logical tiles in, world and screen coordinates out. Nothing
 * here reads or writes battle state, and the camera never touches the engine.
 * =======================================================================*/

function battlefieldProjection(overrides) {
  return { ...GAME_CONFIG.presentation.battlefield, ...(overrides || {}) };
}

/**
 * Logical tile (x, y, elevation) to world coordinates. The world origin sits
 * at tile 0,0 on elevation 0; +x runs down-right, +y runs down-left and
 * elevation lifts the tile upward on screen.
 */
function projectTileToWorld(tile, projection) {
  const config = battlefieldProjection(projection);
  const elevation = tile.elevation == null ? 0 : tile.elevation;
  return {
    x: ((tile.x - tile.y) * config.tileWidth) / 2,
    y:
      ((tile.x + tile.y) * config.tileDepth) / 2 - elevation * config.elevationHeight
  };
}

/** The four corners of a tile's top face, in world space. */
function projectTileTopFace(tile, projection) {
  const config = battlefieldProjection(projection);
  const center = projectTileToWorld(tile, config);
  const halfWidth = config.tileWidth / 2;
  const halfDepth = config.tileDepth / 2;
  return {
    center,
    top: { x: center.x, y: center.y - halfDepth },
    right: { x: center.x + halfWidth, y: center.y },
    bottom: { x: center.x, y: center.y + halfDepth },
    left: { x: center.x - halfWidth, y: center.y }
  };
}

/** World-space bounding box of a tile's top face. */
function projectTileAnchorRect(tile, projection) {
  const config = battlefieldProjection(projection);
  const center = projectTileToWorld(tile, config);
  return {
    left: center.x - config.tileWidth / 2,
    top: center.y - config.tileDepth / 2,
    right: center.x + config.tileWidth / 2,
    bottom: center.y + config.tileDepth / 2,
    width: config.tileWidth,
    height: config.tileDepth,
    centerX: center.x,
    centerY: center.y
  };
}

/** Bounds covering every tile of a map, including elevation lift and sides. */
function calculateProjectedMapBounds(map, projection) {
  const config = battlefieldProjection(projection);
  let minX = Infinity;
  let minY = Infinity;
  let maxX = -Infinity;
  let maxY = -Infinity;
  for (let y = 0; y < map.height; y += 1) {
    for (let x = 0; x < map.width; x += 1) {
      const elevation = elevationAt(map, x, y) || 0;
      const rect = projectTileAnchorRect({ x, y, elevation }, config);
      minX = Math.min(minX, rect.left);
      maxX = Math.max(maxX, rect.right);
      minY = Math.min(minY, rect.top);
      // Tile side walls hang below the top face.
      maxY = Math.max(maxY, rect.bottom + elevation * config.elevationHeight);
    }
  }
  return {
    minX,
    minY,
    maxX,
    maxY,
    width: maxX - minX,
    height: maxY - minY,
    centerX: (minX + maxX) / 2,
    centerY: (minY + maxY) / 2
  };
}

function worldToScreen(worldPoint, camera) {
  return {
    x: worldPoint.x * camera.zoom + camera.panX,
    y: worldPoint.y * camera.zoom + camera.panY
  };
}

function screenToWorld(screenPoint, camera) {
  return {
    x: (screenPoint.x - camera.panX) / camera.zoom,
    y: (screenPoint.y - camera.panY) / camera.zoom
  };
}

/** Screen-space rectangle of a tile's top face under the current camera. */
function projectTileScreenRect(tile, camera, projection) {
  const rect = projectTileAnchorRect(tile, projection);
  const topLeft = worldToScreen({ x: rect.left, y: rect.top }, camera);
  const bottomRight = worldToScreen({ x: rect.right, y: rect.bottom }, camera);
  return {
    left: topLeft.x,
    top: topLeft.y,
    right: bottomRight.x,
    bottom: bottomRight.y,
    width: bottomRight.x - topLeft.x,
    height: bottomRight.y - topLeft.y,
    centerX: (topLeft.x + bottomRight.x) / 2,
    centerY: (topLeft.y + bottomRight.y) / 2
  };
}

/**
 * Deterministic painter's-algorithm depth. Tiles further along both axes and
 * lower elevations draw in front.
 */
function calculateTileRenderOrder(tile) {
  const elevation = tile.elevation == null ? 0 : tile.elevation;
  return (tile.x + tile.y) * 100 + elevation * 10;
}

function compareRenderOrder(a, b) {
  return (
    calculateTileRenderOrder(a) - calculateTileRenderOrder(b) ||
    a.y - b.y ||
    a.x - b.x
  );
}

/* ---------------------------------------------------------------
 * CAMERA (pure helpers over presentation-only state)
 * -------------------------------------------------------------*/

function createCameraState(overrides) {
  const config = battlefieldProjection();
  return {
    zoom: config.initialZoom,
    panX: 0,
    panY: 0,
    ...(overrides || {})
  };
}

function clampCameraZoom(zoom, projection) {
  const config = battlefieldProjection(projection);
  if (!Number.isFinite(zoom)) return config.initialZoom;
  return Math.max(config.minZoom, Math.min(config.maxZoom, zoom));
}

function panCamera(camera, deltaX, deltaY) {
  return { ...camera, panX: camera.panX + deltaX, panY: camera.panY + deltaY };
}

/** Zooms while keeping the world point under the cursor pinned in place. */
function zoomCameraAtPoint(camera, screenPoint, nextZoom, projection) {
  const zoom = clampCameraZoom(nextZoom, projection);
  const world = screenToWorld(screenPoint, camera);
  return {
    ...camera,
    zoom,
    panX: screenPoint.x - world.x * zoom,
    panY: screenPoint.y - world.y * zoom
  };
}

function centerCameraOnWorldPoint(camera, worldPoint, viewport) {
  return {
    ...camera,
    panX: viewport.width / 2 - worldPoint.x * camera.zoom,
    panY: viewport.height / 2 - worldPoint.y * camera.zoom
  };
}

/** Zoom and pan so the whole projected map sits inside the stage. */
function fitCameraToMap(map, viewport, projection) {
  const config = battlefieldProjection(projection);
  const bounds = calculateProjectedMapBounds(map, config);
  const padding = config.cameraPaddingPx;
  const available = {
    width: Math.max(80, viewport.width - padding),
    height: Math.max(80, viewport.height - padding)
  };
  const zoom = clampCameraZoom(
    Math.min(available.width / bounds.width, available.height / bounds.height),
    config
  );
  return centerCameraOnWorldPoint(
    { zoom, panX: 0, panY: 0 },
    { x: bounds.centerX, y: bounds.centerY },
    viewport
  );
}

function isWorldPointVisible(worldPoint, camera, viewport, margin) {
  const screen = worldToScreen(worldPoint, camera);
  const edge = margin == null ? 0 : margin;
  return (
    screen.x >= edge &&
    screen.y >= edge &&
    screen.x <= viewport.width - edge &&
    screen.y <= viewport.height - edge
  );
}

/**
 * Keeps at least part of the projected map recoverable on screen. The camera
 * may overscroll, but never far enough to lose the board entirely.
 */
function clampCameraToBounds(camera, map, viewport, projection) {
  const config = battlefieldProjection(projection);
  const bounds = calculateProjectedMapBounds(map, config);
  const overscroll = config.cameraPaddingPx;
  const left = bounds.minX * camera.zoom + camera.panX;
  const right = bounds.maxX * camera.zoom + camera.panX;
  const top = bounds.minY * camera.zoom + camera.panY;
  const bottom = bounds.maxY * camera.zoom + camera.panY;

  let panX = camera.panX;
  let panY = camera.panY;
  if (left > viewport.width - overscroll) panX -= left - (viewport.width - overscroll);
  if (right < overscroll) panX += overscroll - right;
  if (top > viewport.height - overscroll) panY -= top - (viewport.height - overscroll);
  if (bottom < overscroll) panY += overscroll - bottom;
  return { ...camera, panX, panY };
}

/** Camera that centres a specific tile, used by "focus active unit". */
function focusCameraOnTile(camera, tile, viewport, projection) {
  return centerCameraOnWorldPoint(camera, projectTileToWorld(tile, projection), viewport);
}

const CAMERA_FUNCTIONS = {
  battlefieldProjection,
  projectTileToWorld,
  projectTileTopFace,
  projectTileAnchorRect,
  calculateProjectedMapBounds,
  worldToScreen,
  screenToWorld,
  projectTileScreenRect,
  calculateTileRenderOrder,
  compareRenderOrder,
  createCameraState,
  clampCameraZoom,
  panCamera,
  zoomCameraAtPoint,
  centerCameraOnWorldPoint,
  fitCameraToMap,
  isWorldPointVisible,
  clampCameraToBounds,
  focusCameraOnTile
};

/* ---------------------------------------------------------------
 * OCCLUSION
 * A unit standing behind raised ground can be visually covered by the
 * tiles drawn in front of it. The renderer uses this to draw a silhouette
 * and to keep a clickable hit target above the terrain.
 * -------------------------------------------------------------*/

function calculateUnitOcclusion(map, unit, projection) {
  const config = battlefieldProjection(projection);
  const unitElevation = elevationAt(map, unit.x, unit.y) || 0;
  const occluders = [];
  // Only tiles drawn later (greater render order) can cover the unit, and a
  // tile must stand higher than the unit's own ground to hide it.
  const candidates = [
    { x: unit.x + 1, y: unit.y },
    { x: unit.x, y: unit.y + 1 },
    { x: unit.x + 1, y: unit.y + 1 }
  ];
  for (const candidate of candidates) {
    const elevation = elevationAt(map, candidate.x, candidate.y);
    if (elevation == null) continue;
    if (elevation <= unitElevation) continue;
    const lift = (elevation - unitElevation) * config.elevationHeight;
    occluders.push({ x: candidate.x, y: candidate.y, elevation, lift });
  }
  return {
    unitId: unit.id,
    elevation: unitElevation,
    occluded: occluders.length > 0,
    occluders,
    // How much of the token the terrain in front can cover.
    coverage: occluders.reduce((most, entry) => Math.max(most, entry.lift), 0)
  };
}

CAMERA_FUNCTIONS.calculateUnitOcclusion = calculateUnitOcclusion;
