const CAMPAIGN_SAVE_VERSION = 5;

const LEGACY_MISSION_ID_MAP = {
  hollowmerePerimeter: "act1-01-hollowmere-perimeter",
  borderOutpostDefense: "act1-02-border-outpost-defense",
  recoveredRelief: "act1-03-recovered-relief",
  cleanupOrder: "act1-04-cleanup-order",
  evidence: "act1-05-the-evidence",
  confrontation: "act1-06-confrontation-and-arrest",
  detentionBlock: "act1-07-detention-block",
  jailbreak: "act1-08-jailbreak",
  pursuitLine: "act1-09-pursuit-line",
  abandonedQuarry: "act1-10-abandoned-quarry",
  supplyInterception: "act1-11a-supply-interception",
  witnessConvoy: "act1-11b-witness-convoy",
  quarryDefense: "act1-12-quarry-defense"
};

function currentMissionId(missionId) {
  return LEGACY_MISSION_ID_MAP[missionId] || missionId || null;
}

/**
 * Operator ids that existed before an operator had exactly one.
 *
 * An operator used to be filed under a campaign key and *also* carry a `ref`
 * that links, reactions and mission units addressed instead. The two were
 * allowed to differ and, for one pilot, did — which meant the same person had
 * two names and no rule about which to use where.
 *
 * There is now one id: the registry key. This map exists purely so a save
 * written before that survives, and it is consulted in exactly one place —
 * loading. Nothing downstream of the load resolves an alias, because the point
 * of the migration is that the runtime only ever sees canonical ids.
 */
const LEGACY_OPERATOR_ID_MAP = {
  commander: "vale"
};

function currentOperatorId(operatorId) {
  return LEGACY_OPERATOR_ID_MAP[operatorId] || operatorId || null;
}

/** Re-keys any record filed by operator, dropping ids that no longer exist. */
function migrateOperatorKeyedRecord(record) {
  const out = {};
  for (const key of Object.keys(record || {})) {
    const canonical = currentOperatorId(key);
    if (!canonical) continue;
    out[canonical] = record[key];
  }
  return out;
}

/** Stored mission results carry a per-operator condition report of their own. */
function migrateOutcomeOperatorIds(outcomes) {
  const out = {};
  for (const missionId of Object.keys(outcomes || {})) {
    const outcome = outcomes[missionId];
    out[missionId] =
      outcome && outcome.conditions && outcome.conditions.byOperator
        ? {
            ...outcome,
            conditions: {
              ...outcome.conditions,
              byOperator: migrateOperatorKeyedRecord(outcome.conditions.byOperator)
            }
          }
        : outcome;
  }
  return out;
}

function migrateMissionIdList(values) {
  return (values || []).map(currentMissionId).filter(Boolean);
}

function migrateMissionKeyedRecord(record) {
  const migrated = {};
  for (const key of Object.keys(record || {})) migrated[currentMissionId(key)] = record[key];
  return migrated;
}

function migrateCompletedSceneKeys(values) {
  return (values || []).map((key) => {
    const separator = String(key).indexOf(":");
    if (separator < 0) return key;
    return currentMissionId(String(key).slice(0, separator)) + String(key).slice(separator);
  });
}

function cloneLoadout(loadout) {
  return { ...(loadout || {}) };
}

function addLoadoutOwnership(inventory, loadout, excludedIds) {
  const next = { ...inventory };
  const excluded = excludedIds || new Set();
  for (const equipmentId of Object.values(loadout || {})) {
    if (!equipmentId || excluded.has(equipmentId)) continue;
    next[equipmentId] = (next[equipmentId] || 0) + 1;
  }
  return next;
}

function firstMissionId() {
  return Object.keys(CAMPAIGN.missions)
    .filter((missionId) => !CAMPAIGN.missions[missionId].requires.length)
    .sort((a, b) => CAMPAIGN.missions[a].order - CAMPAIGN.missions[b].order)[0];
}

function createCampaignState() {
  const roster = {};
  let inventory = {};
  for (const operatorId of Object.keys(CAMPAIGN.operators)) {
    const operator = CAMPAIGN.operators[operatorId];
    if (operator.recruit) continue;
    const loadout = createDefaultLoadout(operator.chassis);
    roster[operatorId] = {
      operatorId,
      chassis: operator.chassis,
      condition: 100,
      loadout,
      xp: 0,
      rank: 1,
      perkId: null
    };
    inventory = addLoadoutOwnership(inventory, loadout);
  }
  return {
    version: CAMPAIGN_SAVE_VERSION,
    chapter: CAMPAIGN.startingChapter,
    flags: {},
    completed: [],
    available: [firstMissionId()],
    activeMissionId: null,
    roster,
    contacts: [],
    inventory,
    facilities: {},
    missionOrder: [],
    orderChoices: {},
    missionOutcomes: {},
    // Salvage, as quantities. Equipment already had a counted store; a
    // material is not equipment and must not be filed as if it were.
    materials: {},
    // Once-per-campaign rewards already taken, by claim key. Keyed by the
    // authored entry rather than by the item, so two different unique rewards
    // that happen to pay the same part are still two separate claims.
    rewardClaims: {},
    // Mission attempts whose receipt has already been paid. This is what makes
    // reward application exactly-once across remounts, reloads and a
    // double-clicked continue button.
    appliedReceipts: {},
    completedScenes: [],
    choiceHistory: [],
    supplies: CAMPAIGN.startingSupplies,
    funds: CAMPAIGN.startingFunds,
    intel: 0,
    attempts: {},
    log: [],
    finished: false
  };
}

function campaignFlag(campaign, flag) {
  return campaign.flags[flag] === true;
}

/** A mission is offered once its required flags are set and it is unfinished. */
function missionAvailable(campaign, missionId) {
  const mission = CAMPAIGN.missions[missionId];
  if (!mission) return false;
  if (campaign.completed.includes(missionId)) return false;
  return mission.requires.every((flag) => campaignFlag(campaign, flag));
}

function availableMissions(campaign) {
  return Object.keys(CAMPAIGN.missions)
    .filter((missionId) => missionAvailable(campaign, missionId))
    .sort((a, b) => CAMPAIGN.missions[a].order - CAMPAIGN.missions[b].order);
}

/** Mission board entries, including completed and still-locked missions. */
function createMissionBoardModel(campaign) {
  return Object.keys(CAMPAIGN.missions)
    .sort((a, b) => CAMPAIGN.missions[a].order - CAMPAIGN.missions[b].order)
    .map((missionId) => {
      const mission = CAMPAIGN.missions[missionId];
      const completed = campaign.completed.includes(missionId);
      const available = missionAvailable(campaign, missionId);
      const missing = mission.requires.filter((flag) => !campaignFlag(campaign, flag));
      return {
        missionId,
        name: mission.name,
        order: mission.order,
        chapter: mission.chapter,
        chapterName: CAMPAIGN.chapters[mission.chapter].name,
        kind: mission.kind,
        summary: mission.summary,
        objectiveText: mission.objectiveText,
        rewards: mission.rewards,
        completed,
        available,
        locked: !completed && !available,
        lockReason: missing.length ? "Requires: " + missing.join(", ") : null,
        attempts: campaign.attempts[missionId] || 0
      };
    });
}

function effectiveCampaignLoadouts(campaign, deployment) {
  const loadouts = {};
  for (const operatorId of Object.keys(campaign.roster || {})) {
    loadouts[operatorId] = cloneLoadout(campaign.roster[operatorId].loadout);
  }
  if (deployment && deployment.loadouts) {
    for (const operatorId of Object.keys(deployment.loadouts)) {
      if (!campaign.roster[operatorId]) continue;
      loadouts[operatorId] = cloneLoadout(deployment.loadouts[operatorId]);
    }
  }
  return loadouts;
}

function equipmentEquippedCount(campaign, deployment, equipmentId, ignored) {
  const loadouts = effectiveCampaignLoadouts(campaign, deployment);
  let count = 0;
  for (const operatorId of Object.keys(loadouts)) {
    for (const slot of GAME_CONFIG.equipment.slots) {
      if (ignored && ignored.operatorId === operatorId && ignored.slot === slot) continue;
      if (loadouts[operatorId][slot] === equipmentId) count += 1;
    }
  }
  return count;
}

function equipmentAvailableCount(campaign, deployment, equipmentId, ignored) {
  return Math.max(
    0,
    (campaign.inventory[equipmentId] || 0) -
      equipmentEquippedCount(campaign, deployment, equipmentId, ignored)
  );
}

/** The resistance base as it currently stands. */
function createBaseModel(campaign) {
  const stage = CAMPAIGN.baseStages
    .filter((entry) => !entry.flag || campaignFlag(campaign, entry.flag))
    .slice(-1)[0];
  return {
    stageName: stage.name,
    stageNote: stage.note,
    chapter: campaign.chapter,
    chapterName: CAMPAIGN.chapters[campaign.chapter].name,
    supplies: campaign.supplies,
    funds: campaign.funds,
    intel: campaign.intel,
    finished: campaign.finished,
    roster: Object.keys(campaign.roster).map((operatorId) => {
      const entry = campaign.roster[operatorId];
      const operator = CAMPAIGN.operators[operatorId];
      const definition = CONTENT.units[entry.chassis];
      return {
        operatorId,
        name: operator.name,
        glyph: operator.glyph,
        role: operator.role,
        chassis: entry.chassis,
        chassisName: definition.name,
        className: definition.classId,
        condition: entry.condition,
        repairCost: repairCost(campaign, operatorId),
        canRepair: entry.condition < 100 && campaign.supplies >= repairCost(campaign, operatorId),
        xp: entry.xp || 0,
        rank: entry.rank || 1,
        perkId: entry.perkId || null,
        perk: entry.perkId ? CAMPAIGN.perks[entry.perkId] : null,
        perkChoices: !entry.perkId && (entry.rank || 1) >= 2 ? (operator.perkChoices || []).map((perkId) => ({ perkId, ...CAMPAIGN.perks[perkId] })) : [],
        loadout: cloneLoadout(entry.loadout)
      };
    }),
    facilities: Object.keys(CAMPAIGN.facilities || {}).map((facilityId) => {
      const facility = CAMPAIGN.facilities[facilityId];
      return {
        facilityId,
        ...facility,
        built: !!campaign.facilities[facilityId],
        available: !campaign.facilities[facilityId] && (!facility.requiresFlag || campaignFlag(campaign, facility.requiresFlag)) && resourceCostAffordable(campaign, facility.cost)
      };
    }),
    contacts: campaign.contacts.map((contactId) => ({ contactId, ...CAMPAIGN.contacts[contactId] })),
    inventory: Object.keys(campaign.inventory)
      .sort((a, b) => (CONTENT.equipment[a]?.name || a).localeCompare(CONTENT.equipment[b]?.name || b))
      .map((equipmentId) => ({
        equipmentId,
        name: CONTENT.equipment[equipmentId] ? CONTENT.equipment[equipmentId].name : equipmentId,
        count: campaign.inventory[equipmentId],
        equipped: equipmentEquippedCount(campaign, null, equipmentId),
        available: equipmentAvailableCount(campaign, null, equipmentId)
      })),
    availableMissions: availableMissions(campaign).length,
    completedMissions: campaign.completed.length,
    totalMissions: Object.keys(CAMPAIGN.missions).length
  };
}

function valueAtPath(root, path) {
  if (!path) return root;
  return String(path)
    .split(".")
    .reduce((value, key) => (value == null ? undefined : value[key]), root);
}

function conditionComparison(value, condition) {
  const op = condition.op || "truthy";
  if (op === "truthy") return !!value;
  if (op === "falsy") return !value;
  if (op === "eq") return value === condition.value;
  if (op === "neq") return value !== condition.value;
  if (op === "gt") return Number(value) > Number(condition.value);
  if (op === "gte") return Number(value) >= Number(condition.value);
  if (op === "lt") return Number(value) < Number(condition.value);
  if (op === "lte") return Number(value) <= Number(condition.value);
  return false;
}

function storyConditionMet(campaign, condition, context) {
  if (!condition) return true;
  if (condition.all) return condition.all.every((entry) => storyConditionMet(campaign, entry, context));
  if (condition.any) return condition.any.some((entry) => storyConditionMet(campaign, entry, context));
  if (condition.not) return !storyConditionMet(campaign, condition.not, context);
  if (condition.flag) return campaignFlag(campaign, condition.flag);
  if (condition.notFlag) return !campaignFlag(campaign, condition.notFlag);
  if (condition.outcome) {
    return conditionComparison(valueAtPath((context && context.outcome) || {}, condition.outcome), condition);
  }
  if (condition.path) {
    return conditionComparison(valueAtPath((context && context.data) || {}, condition.path), condition);
  }
  return true;
}

function storyScript(missionId) {
  return missionFileScript(missionId) || CAMPAIGN.dialogue[missionId] || null;
}

function createStorySceneModel(campaign, missionId, sceneId, context) {
  const script = storyScript(missionId);
  const scene = script && script.scenes ? script.scenes[sceneId] : null;
  if (!scene) {
    return {
      sceneId,
      missionId,
      title: sceneId,
      location: "Unknown",
      kind: "dialogue",
      lines: [],
      choices: []
    };
  }
  const lines = (scene.lines || [])
    .filter((line) => storyConditionMet(campaign, line.when, context))
    .map((line) => {
      const speaker = CAMPAIGN.speakers[line.speaker] || { name: line.speaker, glyph: "💬" };
      return {
        speaker: line.speaker,
        name: speaker.name,
        glyph: speaker.glyph,
        portraitAsset: conventionAsset(
          "speaker." + line.speaker,
          "portraits/" + line.speaker,
          { type: "portraitSilhouette", value: speaker.glyph || "?", label: speaker.name || line.speaker },
          "512x512 portrait"
        ),
        text: line.text,
        kind: line.kind || scene.kind || "dialogue"
      };
    });
  const choices = (scene.choices || [])
    .filter((choice) => storyConditionMet(campaign, choice.when, context))
    .map((choice) => ({
      ...choice,
      options: (choice.options || []).filter((option) =>
        storyConditionMet(campaign, option.when, context)
      )
    }));
  return {
    sceneId,
    missionId,
    missionName: CAMPAIGN.missions[missionId] ? CAMPAIGN.missions[missionId].name : missionId,
    title: scene.title || sceneId,
    location: scene.location || "Unknown",
    kind: scene.kind || "dialogue",
    backgroundAsset: conventionAsset(
      "story." + missionId + "." + sceneId,
      "story/" + missionId + "/" + sceneId,
      { type: "sceneLabel", value: scene.location || "Unknown", label: scene.title || sceneId },
      "1920x1080 background"
    ),
    lines,
    choices,
    completed: (campaign.completedScenes || []).includes(missionId + ":" + sceneId)
  };
}

function createStorySequenceModel(campaign, missionId, sequenceId, context) {
  const script = storyScript(missionId);
  const sceneIds = script && script.sequences ? script.sequences[sequenceId] || [] : [];
  return {
    missionId,
    sequenceId,
    scenes: sceneIds.map((sceneId) => createStorySceneModel(campaign, missionId, sceneId, context))
  };
}

function createStoryProgress(sequence) {
  return {
    sceneIndex: 0,
    lineIndex: 0,
    chosen: {},
    complete: !sequence || !sequence.scenes || sequence.scenes.length === 0
  };
}

function currentStoryProgress(sequence, progress) {
  const scene = sequence && sequence.scenes ? sequence.scenes[progress.sceneIndex] || null : null;
  if (!scene) return { scene: null, line: null, choice: null, atLastLine: true };
  const line = scene.lines.length ? scene.lines[Math.min(progress.lineIndex, scene.lines.length - 1)] : null;
  const atLastLine = !scene.lines.length || progress.lineIndex >= scene.lines.length - 1;
  const choice = atLastLine ? (scene.choices || [])[0] || null : null;
  return { scene, line, choice, atLastLine };
}

function chooseStoryProgress(sequence, progress, choiceId, optionId) {
  const view = currentStoryProgress(sequence, progress);
  if (!view.choice || view.choice.id !== choiceId) return progress;
  if (!view.choice.options.some((option) => option.id === optionId)) return progress;
  return { ...progress, chosen: { ...progress.chosen, [choiceId]: optionId } };
}

function advanceStoryProgress(sequence, progress) {
  if (progress.complete) return { progress, blocked: false, complete: true, sceneCompleted: null };
  const view = currentStoryProgress(sequence, progress);
  if (!view.scene) {
    const next = { ...progress, complete: true };
    return { progress: next, blocked: false, complete: true, sceneCompleted: null };
  }
  if (!view.atLastLine) {
    return {
      progress: { ...progress, lineIndex: progress.lineIndex + 1 },
      blocked: false,
      complete: false,
      sceneCompleted: null
    };
  }
  if (view.choice && !progress.chosen[view.choice.id]) {
    return { progress, blocked: true, complete: false, sceneCompleted: null };
  }
  const sceneCompleted = view.scene.sceneId;
  if (progress.sceneIndex < sequence.scenes.length - 1) {
    return {
      progress: { ...progress, sceneIndex: progress.sceneIndex + 1, lineIndex: 0 },
      blocked: false,
      complete: false,
      sceneCompleted
    };
  }
  const next = { ...progress, complete: true };
  return { progress: next, blocked: false, complete: true, sceneCompleted };
}

/** Compatibility model for tests and small consumers expecting one dialogue phase. */
function createDialogueModel(missionId, phase, campaign, context) {
  const state = campaign || createCampaignState();
  const script = storyScript(missionId);
  if (!script) return { missionId, phase, lines: [], choices: [] };
  if (script.scenes && script.scenes[phase]) {
    const scene = createStorySceneModel(state, missionId, phase, context);
    return { ...scene, phase };
  }
  const sequence = createStorySequenceModel(state, missionId, phase, context);
  return {
    missionId,
    phase,
    missionName: CAMPAIGN.missions[missionId] ? CAMPAIGN.missions[missionId].name : missionId,
    lines: sequence.scenes.flatMap((scene) => scene.lines),
    choices: sequence.scenes.flatMap((scene) => scene.choices),
    scenes: sequence.scenes
  };
}

function markStorySceneComplete(campaign, missionId, sceneId) {
  const key = missionId + ":" + sceneId;
  if ((campaign.completedScenes || []).includes(key)) return campaign;
  return { ...campaign, completedScenes: (campaign.completedScenes || []).concat(key) };
}

/** Mid-battle triggers evaluated against authoritative battle state. */
function evaluateMidBattleTriggers(missionId, state, alreadyFired, campaign) {
  const script = storyScript(missionId);
  if (!script || !script.midBattle) return [];
  const fired = new Set(alreadyFired || []);
  const log = state.battleLog || [];
  const units = state.unitOrder.map((id) => state.units[id]);
  const living = units.filter((unit) => unit.alive);
  const foes = units.filter((unit) => unit.teamId === "foe");
  const livingFoes = foes.filter((unit) => unit.alive);
  const definitionFor = (unit) => unit ? CONTENT.units[unit.definitionId] : null;
  const hasTag = (unit, tag) => {
    const definition = definitionFor(unit);
    return !!definition && (definition.tags || []).includes(tag);
  };
  const matchingUnitIds = (params) => units
    .filter((unit) => {
      if (params.unitIds && !params.unitIds.includes(unit.id)) return false;
      if (params.definitionIds && !params.definitionIds.includes(unit.definitionId)) return false;
      if (params.teamId && unit.teamId !== params.teamId) return false;
      if (params.tag && !hasTag(unit, params.tag)) return false;
      return true;
    })
    .map((unit) => unit.id);
  const damageEntriesFor = (ids) => {
    const set = new Set(ids);
    return log.filter((entry) => entry.type === "damageResolved" && entry.data && set.has(entry.data.unitId) && (entry.data.amount || 0) > 0);
  };
  const defeatedEntriesFor = (ids) => {
    const set = new Set(ids);
    return log.filter((entry) => entry.type === "unitDefeated" && entry.data && set.has(entry.data.unitId));
  };
  const abilityEntries = (params) => log.filter((entry) => {
    if (entry.type !== "abilityUsed" || !entry.data) return false;
    if (params.abilityId && entry.data.abilityId !== params.abilityId) return false;
    const source = state.units[entry.data.unitId];
    if (params.teamId && (!source || source.teamId !== params.teamId)) return false;
    return true;
  });
  /**
   * Whether a unit is standing in a trigger's zone.
   *
   * `tiles` is what a compiled region produces and is exact. `zone` is the
   * older hand-authorable rectangle and is still honoured, because a mission
   * that wrote one meant a rectangle — but nothing derives one from a region
   * any more.
   */
  const unitInZone = (unit, trigger) => {
    if (!unit || !unit.alive) return false;
    if (trigger.tiles) return regionContains(trigger.tiles, unit.x, unit.y);
    const zone = trigger.zone;
    if (!zone) return false;
    return (
      unit.x >= (zone.xMin == null ? unit.x : zone.xMin) &&
      unit.x <= (zone.xMax == null ? unit.x : zone.xMax) &&
      unit.y >= (zone.yMin == null ? unit.y : zone.yMin) &&
      unit.y <= (zone.yMax == null ? unit.y : zone.yMax)
    );
  };
  const triggerMet = (entry) => {
    const trigger = typeof entry.trigger === "string" ? { type: entry.trigger } : (entry.trigger || {});
    const type = trigger.type;
    if (trigger.afterActivations != null && state.activationCount < trigger.afterActivations) return false;
    if (type === "battleStarted") return log.some((item) => item.type === "battleStarted");
    if (type === "activationCountReached") return state.activationCount >= (trigger.count || trigger.activations || 1);
    if (type === "firstEnemyDefeated") return livingFoes.length < foes.length;
    if (type === "halfEnemiesRemaining") return foes.length > 0 && livingFoes.length <= foes.length / 2;
    if (type === "enemyCountThreshold") return livingFoes.length <= (trigger.remainingAtMost == null ? 0 : trigger.remainingAtMost);
    if (type === "unitOfTagSpotted") return matchingUnitIds(trigger).length > 0 && state.activationCount >= (trigger.afterActivations || 0);
    if (type === "eliteUnitSpotted") return units.some((unit) => unit.alive && unit.teamId === (trigger.teamId || "foe") && hasTag(unit, "elite"));
    if (type === "specificObjectiveTargetDamaged") {
      const ids = matchingUnitIds(trigger);
      return damageEntriesFor(ids).length >= (trigger.occurrence || 1);
    }
    if (type === "specificObjectiveTargetDestroyed") {
      const ids = matchingUnitIds(trigger);
      return defeatedEntriesFor(ids).length >= (trigger.occurrence || 1);
    }
    if (type === "objectiveProgressReached") {
      const ids = trigger.targetUnitIds || matchingUnitIds(trigger);
      const destroyed = ids.filter((id) => state.units[id] && !state.units[id].alive).length;
      if (trigger.destroyed != null) return destroyed >= trigger.destroyed;
      if (trigger.percent != null) return ids.length > 0 && destroyed / ids.length >= trigger.percent / 100;
      return false;
    }
    if (type === "objectivePhaseChanged") return log.some((item) => item.type === "objectivePhaseChanged" && (!trigger.toId || (item.data && item.data.toId === trigger.toId)));
    if (type === "unitEnteredZone") return units.some((unit) => (!trigger.teamId || unit.teamId === trigger.teamId) && unitInZone(unit, trigger));
    if (type === "extractionActivated") {
      const phases = (state.objectiveState.params && state.objectiveState.params.phases) || [];
      const index = (state.objectiveState.progress && state.objectiveState.progress.phaseIndex) || 0;
      return phases[index] && phases[index].type === "reachExtraction";
    }
    if (type === "extractionReached") {
      const tiles = trigger.tiles || [];
      return units.some((unit) => unit.alive && unit.teamId === (trigger.teamId || "player") && tiles.some((tile) => tile.x === unit.x && tile.y === unit.y));
    }
    if (type === "alliedUnitHpBelowPercent" || type === "protectedUnitHpBelowPercent") {
      const ids = trigger.unitIds || matchingUnitIds({ ...trigger, teamId: trigger.teamId || "player" });
      return ids.some((id) => {
        const unit = state.units[id];
        if (!unit || !unit.alive) return false;
        const stats = calculateUnitStats(state, id);
        return (unit.currentHp / Math.max(1, stats.maxHp)) * 100 <= (trigger.percent || 50);
      });
    }
    if (type === "civilianAttacked") {
      const ids = units.filter((unit) => hasTag(unit, "civilian") && (!trigger.teamId || unit.teamId === trigger.teamId)).map((unit) => unit.id);
      const set = new Set(ids);
      return log.some((item) => item.type === "abilityUsed" && item.data && (item.data.targetUnitIds || []).some((id) => set.has(id)));
    }
    if (type === "civilianDamaged") {
      const ids = units.filter((unit) => hasTag(unit, "civilian") && (!trigger.teamId || unit.teamId === trigger.teamId)).map((unit) => unit.id);
      return damageEntriesFor(ids).length > 0;
    }
    if (type === "civilianDestroyed") {
      const ids = units.filter((unit) => hasTag(unit, "civilian") && (!trigger.teamId || unit.teamId === trigger.teamId)).map((unit) => unit.id);
      return defeatedEntriesFor(ids).length > 0;
    }
    if (type === "abilityUsed") return abilityEntries(trigger).length > 0;
    if (type === "statusApplied" || type === "statusRemoved") return log.some((item) => item.type === type && (!trigger.statusId || (item.data && item.data.statusId === trigger.statusId)));
    if (type === "reinforcementSpawned") return log.some((item) => item.type === "unitSpawned");
    if (type === "battleVictoryConditionMet") return state.finished && state.winner === (trigger.teamId || "player");
    if (type === "civilianSpotted") return units.some((unit) => hasTag(unit, "civilian")) && state.activationCount > 0;
    if (type === "crossedHalfway") {
      const map = getMap(state);
      return living.some((unit) => unit.teamId === "player" && unit.y <= Math.floor(map.height / 2));
    }
    return false;
  };

  return script.midBattle
    .filter((entry) => !fired.has(entry.id))
    .filter((entry) => storyConditionMet(campaign || createCampaignState(), entry.when, { data: { state } }))
    .filter(triggerMet)
    .map((entry, creationOrder) => {
      const speaker = CAMPAIGN.speakers[entry.speaker] || { name: entry.speaker, glyph: "💬" };
      const lines = [{ speaker: entry.speaker, name: speaker.name, glyph: speaker.glyph, text: entry.text }]
        .concat((entry.followUpLines || []).map((line) => {
          const followSpeaker = CAMPAIGN.speakers[line.speaker] || { name: line.speaker, glyph: "💬" };
          return { speaker: line.speaker, name: followSpeaker.name, glyph: followSpeaker.glyph, text: line.text };
        }));
      return {
        id: entry.id,
        speaker: entry.speaker,
        name: speaker.name,
        glyph: speaker.glyph,
        text: entry.text,
        lines,
        priority: entry.priority == null ? 50 : entry.priority,
        pauseBattle: entry.pauseBattle !== false,
        once: entry.once !== false,
        creationOrder
      };
    })
    .sort((a, b) => b.priority - a.priority || a.creationOrder - b.creationOrder);
}

/** Records a dialogue choice as a story flag. */
function applyDialogueChoice(campaign, choiceId, optionId) {
  for (const missionId of Object.keys(CAMPAIGN.dialogue)) {
    const script = CAMPAIGN.dialogue[missionId];
    for (const sceneId of Object.keys(script.scenes || {})) {
      for (const choice of script.scenes[sceneId].choices || []) {
        if (choice.id !== choiceId) continue;
        const option = choice.options.find((entry) => entry.id === optionId);
        if (!option) return campaign;
        const flags = { ...campaign.flags };
        for (const sibling of choice.options) delete flags[sibling.flag];
        flags[option.flag] = true;
        return {
          ...campaign,
          flags,
          choiceHistory: (campaign.choiceHistory || []).concat({
            missionId,
            sceneId,
            choiceId,
            optionId,
            flag: option.flag
          }),
          log: campaign.log.concat("Chose: " + option.text)
        };
      }
    }
  }
  return campaign;
}

/** Marks a mission as the one being attempted. */
function beginMission(campaign, missionId) {
  if (!missionAvailable(campaign, missionId)) return campaign;
  return {
    ...campaign,
    activeMissionId: missionId,
    attempts: { ...campaign.attempts, [missionId]: (campaign.attempts[missionId] || 0) + 1 }
  };
}

function missionDeploymentRules(missionId) {
  const mission = CAMPAIGN.missions[missionId];
  return mission && mission.deployment ? mission.deployment : null;
}

function campaignDeploymentCandidates(campaign, missionId) {
  const rules = missionDeploymentRules(missionId);
  if (!rules) return [];
  const required = rules.requiredOperatorIds || [];
  const optional =
    rules.optionalOperatorIds === "owned"
      ? Object.keys(campaign.roster)
      : rules.optionalOperatorIds || [];
  const guestDefinitions = rules.guestOperators || [];
  const order = rules.deploymentOrder || required.concat(optional).concat(guestDefinitions.map((guest) => guest.operatorId));
  const seen = new Set();
  const candidates = [];

  const addOwned = (operatorId, status) => {
    if (seen.has(operatorId) || !campaign.roster[operatorId]) return;
    seen.add(operatorId);
    const operator = CAMPAIGN.operators[operatorId];
    const rosterEntry = campaign.roster[operatorId];
    candidates.push({
      operatorId,
      name: operator.name,
      glyph: operator.glyph,
      role: operator.role,
      chassis: rosterEntry.chassis,
      condition: rosterEntry.condition,
      loadout: cloneLoadout(rosterEntry.loadout),
      status,
      guest: false
    });
  };

  for (const operatorId of required) addOwned(operatorId, "required");
  for (const operatorId of optional) addOwned(operatorId, required.includes(operatorId) ? "required" : "optional");
  for (const guest of guestDefinitions) {
    const operatorId = guest.operatorId;
    if (seen.has(operatorId)) continue;
    const operator = CAMPAIGN.operators[operatorId];
    if (!operator) continue;
    seen.add(operatorId);
    candidates.push({
      operatorId,
      name: operator.name,
      glyph: operator.glyph,
      role: operator.role,
      chassis: guest.chassis || operator.chassis,
      condition: guest.condition == null ? 100 : guest.condition,
      loadout: cloneLoadout(guest.loadout || createDefaultLoadout(guest.chassis || operator.chassis)),
      status: guest.status || "guest",
      guest: true
    });
  }

  return candidates.sort((a, b) => {
    const ai = order.indexOf(a.operatorId);
    const bi = order.indexOf(b.operatorId);
    return (ai < 0 ? 999 : ai) - (bi < 0 ? 999 : bi) || a.name.localeCompare(b.name);
  });
}

function createCampaignDeploymentState(campaign, missionId) {
  const rules = missionDeploymentRules(missionId);
  const candidates = campaignDeploymentCandidates(campaign, missionId);
  const size = rules ? rules.deploymentSize || GAME_CONFIG.deployment.teamSize : GAME_CONFIG.deployment.teamSize;
  const required = new Set((rules && rules.requiredOperatorIds) || []);
  const selected = [];
  for (const candidate of candidates) {
    if (required.has(candidate.operatorId) || candidate.guest || (rules && rules.lockedDeployment)) {
      selected.push(candidate.operatorId);
    }
  }
  if (!(rules && rules.lockedDeployment)) {
    for (const candidate of candidates) {
      if (selected.length >= size) break;
      if (!selected.includes(candidate.operatorId)) selected.push(candidate.operatorId);
    }
  }
  const loadouts = {};
  for (const candidate of candidates) loadouts[candidate.operatorId] = cloneLoadout(candidate.loadout);
  return {
    missionId,
    selected: selected.slice(0, size),
    candidates,
    loadouts,
    inspectedOperatorId: candidates[0] ? candidates[0].operatorId : null,
    error: null
  };
}

function campaignInventoryForSlot(campaign, deployment, operatorId, slot) {
  const candidate = deployment.candidates.find((entry) => entry.operatorId === operatorId);
  if (!candidate || candidate.guest) return [];
  const current = deployment.loadouts[operatorId] ? deployment.loadouts[operatorId][slot] : null;
  return Object.keys(campaign.inventory)
    .filter((equipmentId) => CONTENT.equipment[equipmentId] && CONTENT.equipment[equipmentId].slot === slot)
    .map((equipmentId) => {
      const item = CONTENT.equipment[equipmentId];
      const compatible = isEquipmentCompatible(candidate.chassis, equipmentId);
      const available = equipmentAvailableCount(campaign, deployment, equipmentId, {
        operatorId,
        slot
      });
      const fitted = current === equipmentId;
      return {
        equipmentId,
        name: item.name,
        slot,
        description: item.description,
        tags: item.tags,
        modifiers: item.modifiers,
        grantsAbilities: item.grantsAbilities,
        compatible,
        fitted,
        owned: campaign.inventory[equipmentId] || 0,
        available,
        selectable: compatible && (fitted || available > 0),
        reason: !compatible
          ? equipmentCompatibilityReason(candidate.chassis, equipmentId)
          : fitted || available > 0
            ? null
            : "Every owned copy is fitted to another operator."
      };
    })
    .sort((a, b) => Number(b.fitted) - Number(a.fitted) || Number(b.selectable) - Number(a.selectable) || a.name.localeCompare(b.name));
}

function toggleCampaignOperator(campaign, missionId, deployment, operatorId) {
  const rules = missionDeploymentRules(missionId);
  const candidate = deployment.candidates.find((entry) => entry.operatorId === operatorId);
  if (!rules || !candidate) return deployment;
  if (rules.lockedDeployment || candidate.status === "required" || candidate.guest) {
    return { ...deployment, inspectedOperatorId: operatorId, error: "This mission locks " + candidate.name + " into the lance." };
  }
  const selected = deployment.selected.slice();
  const index = selected.indexOf(operatorId);
  if (index >= 0) selected.splice(index, 1);
  else if (selected.length >= rules.deploymentSize) {
    return { ...deployment, inspectedOperatorId: operatorId, error: "Deploy exactly " + rules.deploymentSize + " operators; remove one first." };
  } else selected.push(operatorId);
  return { ...deployment, selected, inspectedOperatorId: operatorId, error: null };
}

function equipCampaignPart(campaign, deployment, operatorId, slot, equipmentId) {
  const candidate = deployment.candidates.find((entry) => entry.operatorId === operatorId);
  if (!candidate) return deployment;
  if (candidate.guest) return { ...deployment, error: "Guest loadouts are locked for this operation." };
  if (equipmentId) {
    const item = CONTENT.equipment[equipmentId];
    if (!item || !campaign.inventory[equipmentId]) return { ...deployment, error: "That part is not owned by the campaign." };
    if (item.slot !== slot) return { ...deployment, error: item.name + " does not fit that slot." };
    if (!isEquipmentCompatible(candidate.chassis, equipmentId)) {
      return { ...deployment, error: equipmentCompatibilityReason(candidate.chassis, equipmentId) };
    }
    const current = deployment.loadouts[operatorId][slot] || null;
    if (current !== equipmentId && equipmentAvailableCount(campaign, deployment, equipmentId, { operatorId, slot }) <= 0) {
      return { ...deployment, error: "Every owned copy of " + item.name + " is already fitted." };
    }
  }
  return {
    ...deployment,
    error: null,
    loadouts: {
      ...deployment.loadouts,
      [operatorId]: { ...deployment.loadouts[operatorId], [slot]: equipmentId || null }
    }
  };
}

function validateCampaignDeployment(campaign, missionId, deployment) {
  const rules = missionDeploymentRules(missionId);
  const errors = [];
  if (!rules) return { valid: false, errors: ["This mission has no deployment rules."] };
  if (deployment.selected.length !== rules.deploymentSize) {
    errors.push("Select exactly " + rules.deploymentSize + " operators (" + deployment.selected.length + " chosen)." );
  }
  if (new Set(deployment.selected).size !== deployment.selected.length) errors.push("Operators cannot be duplicated.");
  const candidateIds = new Set(deployment.candidates.map((entry) => entry.operatorId));
  for (const operatorId of deployment.selected) {
    if (!candidateIds.has(operatorId)) errors.push("Unowned operator cannot deploy: " + operatorId + ".");
  }
  for (const operatorId of rules.requiredOperatorIds || []) {
    if (!deployment.selected.includes(operatorId)) errors.push("Required operator missing: " + operatorId + ".");
  }
  for (const guest of rules.guestOperators || []) {
    if (rules.lockedDeployment && !deployment.selected.includes(guest.operatorId)) {
      errors.push("Required guest missing: " + guest.operatorId + ".");
    }
  }
  const chassis = deployment.selected
    .map((operatorId) => deployment.candidates.find((entry) => entry.operatorId === operatorId))
    .filter(Boolean)
    .map((entry) => entry.chassis);
  if (new Set(chassis).size !== chassis.length) errors.push("Each deployed chassis must be unique.");

  for (const candidate of deployment.candidates) {
    if (candidate.guest) continue;
    const loadout = deployment.loadouts[candidate.operatorId] || {};
    for (const slot of GAME_CONFIG.equipment.slots) {
      const equipmentId = loadout[slot];
      if (!equipmentId) continue;
      if (!campaign.inventory[equipmentId]) errors.push(CONTENT.equipment[equipmentId].name + " is not owned.");
      if (!isEquipmentCompatible(candidate.chassis, equipmentId)) {
        errors.push(equipmentCompatibilityReason(candidate.chassis, equipmentId));
      }
    }
  }
  for (const equipmentId of Object.keys(campaign.inventory)) {
    const equipped = equipmentEquippedCount(campaign, deployment, equipmentId);
    if (equipped > campaign.inventory[equipmentId]) {
      errors.push(CONTENT.equipment[equipmentId].name + " is equipped " + equipped + " times but only " + campaign.inventory[equipmentId] + " copies are owned.");
    }
  }
  return { valid: errors.length === 0, errors };
}

function createCampaignDeploymentPreview(campaign, missionId, deployment, operatorId) {
  const candidate = deployment.candidates.find((entry) => entry.operatorId === operatorId);
  if (!candidate) return null;
  const loadout = deployment.loadouts[operatorId] || {};
  const probeDeployment = {
    selected: [candidate.chassis],
    loadouts: { [candidate.chassis]: loadout },
    inspectedDefinitionId: candidate.chassis
  };
  const preview = createDeploymentPreview(probeDeployment, candidate.chassis);
  return {
    ...preview,
    operatorId,
    operatorName: candidate.name,
    operatorGlyph: candidate.glyph,
    operatorRole: candidate.role,
    condition: candidate.condition,
    status: candidate.status,
    guest: candidate.guest,
    slots: preview.slots.map((slotModel) => ({
      ...slotModel,
      options: campaignInventoryForSlot(campaign, deployment, operatorId, slotModel.slot)
    }))
  };
}

function createCampaignDeploymentModel(campaign, missionId, deployment) {
  const rules = missionDeploymentRules(missionId);
  const validation = validateCampaignDeployment(campaign, missionId, deployment);
  return {
    missionId,
    missionName: CAMPAIGN.missions[missionId] ? CAMPAIGN.missions[missionId].name : missionId,
    objectiveText: CAMPAIGN.missions[missionId] ? CAMPAIGN.missions[missionId].objectiveText : "",
    size: rules ? rules.deploymentSize : GAME_CONFIG.deployment.teamSize,
    locked: !!(rules && rules.lockedDeployment),
    candidates: deployment.candidates.map((candidate) => ({
      ...candidate,
      selected: deployment.selected.includes(candidate.operatorId),
      inspected: deployment.inspectedOperatorId === candidate.operatorId
    })),
    selected: deployment.selected.slice(),
    error: deployment.error,
    validation,
    preview: createCampaignDeploymentPreview(campaign, missionId, deployment, deployment.inspectedOperatorId)
  };
}

function orderedSelectedOperators(missionId, deployment) {
  const rules = missionDeploymentRules(missionId);
  const order = (rules && rules.deploymentOrder) || [];
  return deployment.selected.slice().sort((a, b) => {
    const ai = order.indexOf(a);
    const bi = order.indexOf(b);
    return (ai < 0 ? 999 : ai) - (bi < 0 ? 999 : bi);
  });
}

function createCampaignMissionRoster(campaign, missionId, deployment) {
  return orderedSelectedOperators(missionId, deployment).map((operatorId) => {
    const candidate = deployment.candidates.find((entry) => entry.operatorId === operatorId);
    const persistent = campaign.roster[operatorId] || null;
    const condition = candidate.condition == null ? 100 : candidate.condition;
    const conditionMultiplier = 0.75 + Math.max(0, Math.min(100, condition)) * 0.0025;
    const perk = persistent && persistent.perkId ? CAMPAIGN.perks[persistent.perkId] : null;
    const operator = CAMPAIGN.operators[operatorId] || {};
    return {
      operatorId,
      // Stable authored identity for content that names units: links,
      // reactions, objectives and mission triggers all address units by ref.
      // Defaults to the operator id, so a new operator needs no extra data.
      ref: operatorId,
      definitionId: candidate.chassis,
      equipment: cloneLoadout(deployment.loadouts[operatorId]),
      modifiers: [{ stat: "maxHp", mode: "multiplier", value: conditionMultiplier, source: "condition" }]
        .concat((perk && perk.modifiers) || []),
      guest: candidate.guest === true
    };
  });
}

function commitCampaignDeployment(campaign, deployment) {
  const roster = { ...campaign.roster };
  for (const candidate of deployment.candidates) {
    if (candidate.guest || !roster[candidate.operatorId]) continue;
    roster[candidate.operatorId] = {
      ...roster[candidate.operatorId],
      loadout: cloneLoadout(deployment.loadouts[candidate.operatorId])
    };
  }
  return { ...campaign, roster };
}

/** The deployment roster this mission will send into the encounter. */
function missionRoster(campaign, deployment, missionId) {
  if (deployment && deployment.candidates) {
    return createCampaignMissionRoster(campaign, missionId || deployment.missionId, deployment);
  }
  return createDeploymentRoster(deployment);
}

function missionEncounterId(missionId, campaign) {
  const mission = CAMPAIGN.missions[missionId];
  if (!mission) {
    // File-authored missions are not on the campaign board; they resolve
    // straight to the encounter the compiler produced.
    const fileMission = MISSION_CONTENT.missions[missionId];
    return fileMission ? fileMission.encounterId : null;
  }
  for (const variant of mission.encounterVariants || []) {
    if (storyConditionMet(campaign || createCampaignState(), variant.when, null)) return variant.encounterId;
  }
  return mission.encounterId || null;
}

function trackedUnitIds(state, group) {
  return state.unitOrder.filter((unitId) => {
    const unit = state.units[unitId];
    const definition = CONTENT.units[unit.definitionId];
    if (group.unitTag && !(definition.tags || []).includes(group.unitTag)) return false;
    if (group.definitionIds && !group.definitionIds.includes(unit.definitionId)) return false;
    if (group.teamId && unit.teamId !== group.teamId) return false;
    return true;
  });
}

function collectTrackedGroupFacts(state, group) {
  const ids = trackedUnitIds(state, group);
  const idSet = new Set(ids);
  const playerSources = new Set(
    state.unitOrder.filter((unitId) => state.units[unitId].teamId === "player")
  );
  const attacked = state.battleLog.some(
    (entry) =>
      entry.type === "abilityUsed" &&
      entry.data &&
      playerSources.has(entry.data.unitId) &&
      (entry.data.targetUnitIds || []).some((unitId) => idSet.has(unitId))
  );
  const damageEntries = state.battleLog.filter(
    (entry) =>
      entry.type === "damageResolved" &&
      entry.data &&
      idSet.has(entry.data.unitId) &&
      playerSources.has(entry.data.sourceUnitId) &&
      (entry.data.amount || 0) > 0
  );
  const destroyedIds = ids.filter((unitId) => !state.units[unitId].alive);
  return {
    total: ids.length,
    attacked,
    damaged: damageEntries.length > 0,
    damageEvents: damageEntries.length,
    damageTaken: damageEntries.reduce((sum, entry) => sum + (entry.data.amount || 0), 0),
    destroyed: destroyedIds.length,
    destroyedUnitIds: destroyedIds
  };
}

function collectMissionFacts(state, missionId) {
  const mission = CAMPAIGN.missions[missionId];
  const tracking = mission && mission.outcomeTracking;
  const groups = {};
  for (const group of (tracking && tracking.groups) || []) {
    groups[group.id] = collectTrackedGroupFacts(state, group);
  }
  return { groups };
}

function outcomeRuleMatches(rule, facts) {
  if (rule.all) return rule.all.every((entry) => outcomeRuleMatches(entry, facts));
  if (rule.any) return rule.any.some((entry) => outcomeRuleMatches(entry, facts));
  if (rule.not) return !outcomeRuleMatches(rule.not, facts);
  return conditionComparison(valueAtPath(facts, rule.path), rule);
}

function applyMissionOutcomeFlags(flags, mission, facts) {
  const next = { ...flags };
  for (const rule of (mission.outcomeTracking && mission.outcomeTracking.rules) || []) {
    next[rule.flag] = outcomeRuleMatches(rule, facts);
  }
  return next;
}

/**
 * Story scenes shown before rewards commit still need to react to the battle
 * that just happened. This creates a read-only preview of the flags that the
 * authoritative outcome resolver will commit after the scene completes.
 */
function previewCampaignOutcomeFlags(campaign, missionId, outcome) {
  const mission = CAMPAIGN.missions[missionId];
  if (!mission || !outcome || outcome.victory !== true) return campaign;
  let flags = { ...campaign.flags };
  for (const flag of mission.grantsFlags || []) flags[flag] = true;
  flags = applyMissionOutcomeFlags(flags, mission, outcome.facts || {});
  return { ...campaign, flags };
}


function resourceCostAffordable(campaign, cost) {
  const value = cost || {};
  return campaign.supplies >= (value.supplies || 0) &&
    campaign.funds >= (value.funds || 0) &&
    campaign.intel >= (value.intel || 0);
}

function buildCampaignFacility(campaign, facilityId) {
  const facility = CAMPAIGN.facilities && CAMPAIGN.facilities[facilityId];
  if (!facility || campaign.facilities[facilityId]) return campaign;
  if (facility.requiresFlag && !campaignFlag(campaign, facility.requiresFlag)) return campaign;
  if (!resourceCostAffordable(campaign, facility.cost)) return campaign;
  return {
    ...campaign,
    facilities: { ...campaign.facilities, [facilityId]: true },
    supplies: campaign.supplies - ((facility.cost && facility.cost.supplies) || 0),
    funds: campaign.funds - ((facility.cost && facility.cost.funds) || 0),
    intel: campaign.intel - ((facility.cost && facility.cost.intel) || 0),
    log: campaign.log.concat("Built: " + facility.name)
  };
}

function repairCost(campaign, operatorId) {
  const entry = campaign.roster[operatorId];
  if (!entry) return 0;
  const missing = Math.max(0, 100 - entry.condition);
  const base = Math.ceil(missing / 10) * 2;
  return campaign.facilities.repairBay ? Math.max(1, Math.ceil(base * 0.75)) : base;
}

function repairCampaignOperator(campaign, operatorId) {
  const entry = campaign.roster[operatorId];
  if (!entry || entry.condition >= 100) return campaign;
  const cost = repairCost(campaign, operatorId);
  if (campaign.supplies < cost) return campaign;
  return {
    ...campaign,
    supplies: campaign.supplies - cost,
    roster: { ...campaign.roster, [operatorId]: { ...entry, condition: 100 } },
    log: campaign.log.concat("Repaired " + CAMPAIGN.operators[operatorId].name + " for " + cost + " supplies")
  };
}

function chooseCampaignPerk(campaign, operatorId, perkId) {
  const entry = campaign.roster[operatorId];
  const operator = CAMPAIGN.operators[operatorId];
  if (!entry || !operator || entry.rank < 2 || entry.perkId) return campaign;
  if (!(operator.perkChoices || []).includes(perkId) || !CAMPAIGN.perks[perkId]) return campaign;
  return {
    ...campaign,
    roster: { ...campaign.roster, [operatorId]: { ...entry, perkId } },
    log: campaign.log.concat(CAMPAIGN.operators[operatorId].name + " chose " + CAMPAIGN.perks[perkId].name)
  };
}

function applyMissionOrderChoice(flags, orderChoices, mission) {
  const nextFlags = { ...flags };
  const nextChoices = { ...(orderChoices || {}) };
  const rule = mission.orderChoice;
  if (!rule) return { flags: nextFlags, orderChoices: nextChoices };
  const prior = nextChoices[rule.group] || [];
  if (!prior.length && rule.firstFlag) nextFlags[rule.firstFlag] = true;
  else if (rule.laterFlag) nextFlags[rule.laterFlag] = true;
  nextChoices[rule.group] = prior.concat(mission.name);
  return { flags: nextFlags, orderChoices: nextChoices };
}

/**
 * A repeat clear: rewards, and nothing else.
 *
 * Deliberately narrow. Everything a first clear does beyond paying — unlocking
 * the next mission, recruiting, advancing flags — has already happened and
 * must not happen again, so this touches none of it.
 */
function applyMissionRewardsOnly(campaign, missionId, outcome) {
  const receipt = planMissionRewards(campaign, missionId, outcome);
  const result = applyRewards(campaign, receipt);
  const mission = CAMPAIGN.missions[missionId];
  if (!result.applied) return { ...result.campaign, activeMissionId: null };
  return {
    ...result.campaign,
    activeMissionId: null,
    log: campaign.log.concat(
      (mission ? mission.name : missionId) + ": cleared again, " + describeReceipt(receipt)
    )
  };
}

/** A one-line summary of what a receipt paid, for the campaign log. */
function describeReceipt(receipt) {
  const parts = [];
  for (const [itemId, amount] of Object.entries(receipt.totals.currency)) {
    parts.push("+" + amount + " " + itemId);
  }
  const items = Object.keys(receipt.totals.equipment).length;
  const materials = Object.values(receipt.totals.material).reduce((sum, n) => sum + n, 0);
  if (items) parts.push(items + (items === 1 ? " item" : " items"));
  if (materials) parts.push(materials + " salvage");
  return parts.length ? parts.join(", ") : "nothing new";
}

/**
 * Applies a mission result. Victory grants deterministic rewards, flags,
 * unlocks and recruits; defeat only records the attempt so the player can
 * retry without advancing the story.
 */
function resolveMissionOutcome(campaign, missionId, outcome) {
  const mission = CAMPAIGN.missions[missionId];
  if (!mission) return campaign;
  const victory = outcome && outcome.victory === true;
  if (!victory) {
    return {
      ...campaign,
      activeMissionId: null,
      log: campaign.log.concat(mission.name + ": failed, retry available")
    };
  }
  // A replay no longer falls out here. Story progress — flags, unlocks,
  // recruits, contacts — is still strictly first-clear, because completing a
  // mission twice does not make a plot happen twice. What changed is that
  // rewards are now a separate question with their own claim rules, so a
  // second clear can still pay salvage without re-running the story.
  const firstClear = !campaign.completed.includes(missionId);
  if (!firstClear) return applyMissionRewardsOnly(campaign, missionId, outcome);

  let flags = { ...campaign.flags };
  for (const flag of mission.grantsFlags || []) flags[flag] = true;
  flags = applyMissionOutcomeFlags(flags, mission, (outcome && outcome.facts) || {});
  const ordered = applyMissionOrderChoice(flags, campaign.orderChoices, mission);
  flags = ordered.flags;

  const completed = campaign.completed.concat(missionId);
  const roster = {};
  for (const operatorId of Object.keys(campaign.roster)) {
    roster[operatorId] = {
      ...campaign.roster[operatorId],
      loadout: cloneLoadout(campaign.roster[operatorId].loadout)
    };
  }
  // A recruit brings their own frame's kit. Anything the reward pipeline is
  // about to grant is excluded, so a part that arrives as loot is not also
  // quietly conjured as a recruit's starting equipment.
  let inventory = { ...campaign.inventory };
  const receipt = planMissionRewards(campaign, missionId, outcome);
  const rewardIds = new Set(Object.keys(receipt.totals.equipment));
  for (const operatorId of mission.recruits || []) {
    if (roster[operatorId]) continue;
    const operator = CAMPAIGN.operators[operatorId];
    const loadout = createDefaultLoadout(operator.chassis);
    roster[operatorId] = { operatorId, chassis: operator.chassis, condition: 100, loadout, xp: 0, rank: 1, perkId: null };
    inventory = addLoadoutOwnership(inventory, loadout, rewardIds);
  }

  const contacts = campaign.contacts.slice();
  for (const contactId of mission.contacts || []) if (!contacts.includes(contactId)) contacts.push(contactId);

  const conditions = (outcome && outcome.conditions) || {};
  const byOperator = conditions.byOperator || {};
  const deployedOperatorIds = Object.keys(byOperator);
  for (const operatorId of Object.keys(roster)) {
    const reported = byOperator[operatorId] == null ? conditions[roster[operatorId].chassis] : byOperator[operatorId];
    if (reported != null) roster[operatorId] = { ...roster[operatorId], condition: Math.max(5, Math.round(reported)) };
    if (mission.kind === "battle" && deployedOperatorIds.includes(operatorId)) {
      const xp = (roster[operatorId].xp || 0) + 25;
      roster[operatorId] = { ...roster[operatorId], xp, rank: xp >= 50 ? Math.max(2, roster[operatorId].rank || 1) : (roster[operatorId].rank || 1) };
    }
  }

  const missionOutcomes = {
    ...(campaign.missionOutcomes || {}),
    [missionId]: {
      victory: true,
      activations: outcome ? outcome.activations || 0 : 0,
      conditions: JSON.parse(JSON.stringify(conditions)),
      facts: JSON.parse(JSON.stringify((outcome && outcome.facts) || {}))
    }
  };

  // Story progress first, then the payment. Rewards go through the same grant
  // pipeline a replay uses — there is no separate first-clear currency path,
  // which is what stops the two drifting apart.
  const progressed = {
    ...campaign,
    chapter: mission.chapter,
    flags,
    completed,
    roster,
    contacts,
    inventory,
    orderChoices: ordered.orderChoices,
    missionOrder: (campaign.missionOrder || []).concat(missionId),
    missionOutcomes,
    activeMissionId: null,
    available: availableMissionsAfter(missionId, flags, completed),
    finished: flags.prototypeComplete === true,
    log: campaign.log.concat(mission.name + ": complete")
  };
  return applyRewards(progressed, receipt).campaign;
}

function availableMissionsAfter(missionId, flags, completed) {
  return Object.keys(CAMPAIGN.missions)
    .filter((id) => !completed.includes(id))
    .filter((id) => CAMPAIGN.missions[id].requires.every((flag) => flags[flag] === true))
    .sort((a, b) => CAMPAIGN.missions[a].order - CAMPAIGN.missions[b].order);
}

function missionChapterAfter(mission, flags) {
  const nextMissionId = (mission.unlocks || [])[0];
  if (nextMissionId && CAMPAIGN.missions[nextMissionId]) {
    return CAMPAIGN.missions[nextMissionId].chapter;
  }
  if (flags.prototypeComplete) return "chapterThree";
  return mission.chapter;
}

/** Post-mission summary shown on the results screen. */
function createMissionResultModel(campaign, missionId, outcome, receipt) {
  const mission = CAMPAIGN.missions[missionId];
  const victory = outcome && outcome.victory === true;
  const conditions = (outcome && outcome.conditions && outcome.conditions.byOperator) || {};
  const paid = victory ? receipt || null : null;
  return {
    missionId,
    missionName: mission ? mission.name : missionId,
    victory,
    activations: outcome ? outcome.activations : 0,
    // The receipt the pipeline actually produced, grouped for display. The
    // screen renders what was paid rather than re-deriving what should have
    // been — there is one calculator, and this is not it.
    reward: paid ? describeReceiptForDisplay(paid) : null,
    rewards: victory && mission ? mission.rewards : { supplies: 0, funds: 0, intel: 0 },
    equipment: victory && mission && mission.rewards && mission.rewards.equipment ? mission.rewards.equipment : [],
    recruits: victory && mission ? (mission.recruits || []).map((id) => CAMPAIGN.operators[id]).filter(Boolean) : [],
    contacts: victory && mission ? (mission.contacts || []).map((id) => CAMPAIGN.contacts[id]).filter(Boolean) : [],
    unlocked: victory && mission ? (mission.unlocks || []).map((id) => CAMPAIGN.missions[id].name) : [],
    conditions: Object.keys(conditions).map((operatorId) => ({
      operatorId,
      name: CAMPAIGN.operators[operatorId] ? CAMPAIGN.operators[operatorId].name : operatorId,
      condition: conditions[operatorId]
    })),
    facts: (outcome && outcome.facts) || {},
    dialogue: createDialogueModel(
      missionId,
      victory ? "aftermath" : "defeat",
      campaign,
      { outcome }
    ),
    retryable: !victory,
    prototypeComplete: victory && !!mission && (mission.grantsFlags || []).includes("prototypeComplete")
  };
}

/**
 * A receipt, grouped the way a player reads it: what the operation paid, and
 * what came off the things you destroyed.
 *
 * Skipped lines are carried through with their reason, because "you already
 * have this one" is information a player needs in order to understand why a
 * replay paid less than the first clear did.
 */
function describeReceiptForDisplay(receipt) {
  const nameOf = (line) => {
    if (line.kind === "equipment") return (CONTENT.equipment[line.itemId] || {}).name || line.itemId;
    if (line.kind === "material") return (MATERIALS[line.itemId] || {}).name || line.itemId;
    return line.itemId;
  };
  const toEntry = (line) => ({
    kind: line.kind,
    itemId: line.itemId,
    name: nameOf(line),
    quantity: line.quantity,
    sourceKind: line.sourceKind,
    // Both: the label is what a player reads, the id is the stable authored
    // identity a debug view or a source index needs.
    sourceId: line.sourceId,
    sourceLabel: line.sourceLabel || line.sourceId,
    tableId: line.tableId,
    entryId: line.entryId,
    firstClear: line.sourceKind === "firstClear",
    skipped: line.skipped || null
  });
  const granted = (receipt.granted || []).map(toEntry);
  return {
    receiptId: receipt.receiptId,
    attempt: receipt.attempt,
    mission: granted.filter((entry) => entry.sourceKind !== "unitDefeated"),
    salvage: granted.filter((entry) => entry.sourceKind === "unitDefeated"),
    // Only the refusals a player would otherwise find confusing. A weight that
    // lost a roll is not shown; a unique they already own is.
    withheld: (receipt.skipped || [])
      .filter((line) => line.skipped === "alreadyClaimed")
      .map(toEntry),
    empty: !granted.length
  };
}

/** Mech condition derived from how battered each deployed operator finished. */
function collectMissionConditions(state, roster) {
  const conditions = { byOperator: {} };
  const playerIds = state.unitOrder.filter((unitId) => state.units[unitId].teamId === "player");
  playerIds.forEach((unitId, index) => {
    const unit = state.units[unitId];
    const stats = calculateUnitStats(state, unitId);
    const value = unit.alive ? Math.round((unit.currentHp / stats.maxHp) * 100) : 25;
    conditions[unit.definitionId] = value;
    const rosterEntry = roster && roster[index];
    if (rosterEntry && rosterEntry.operatorId) conditions.byOperator[rosterEntry.operatorId] = value;
  });
  return conditions;
}

/**
 * Who was left standing, and who was not.
 *
 * The smallest thing a drop needs: a reward may only come from a source that
 * was actually defeated, and "it was on the board" is not the same claim.
 * Read from final unit state rather than by re-scanning the battle log,
 * because a unit that was destroyed and then revived finished the operation
 * intact and should not pay salvage.
 *
 * Carries the placement `ref` — the same stable id links, objectives and
 * mission scripts already address units by — so a drop source is identified
 * by authored identity rather than by a runtime unit key.
 */
function collectDefeatedSources(state) {
  const defeated = [];
  for (const unitId of state.unitOrder) {
    const unit = state.units[unitId];
    if (!unit || unit.alive) continue;
    // Summons and anything spawned mid-battle have no authored placement, so
    // there is nothing stable to attribute a drop to.
    if (unit.summonedBy) continue;
    defeated.push({
      ref: unit.ref || unitId,
      definitionId: unit.definitionId,
      teamId: unit.teamId,
      label: unitLabel(state, unitId)
    });
  }
  return defeated;
}

/* ---------------------------------------------------------------
 * REWARDS
 *
 * The bridge between "a mission finished" and the pure reward planner. This
 * is the only place that knows what counts as a reward source; the planner
 * only knows how to resolve one.
 * -------------------------------------------------------------*/

/** The mission file's own reward block, if the mission came from one. */
function missionRewardTables(missionId) {
  const file = MISSION_CONTENT.missions ? MISSION_CONTENT.missions[missionId] : null;
  if (file && file.rewards) return file.rewards;
  return { clear: null, firstClear: null };
}

/**
 * What a defeated placement is worth.
 *
 * The placement wins if it says anything, because that is the whole point of
 * the override: a named officer and an ordinary trooper can share a chassis
 * and still pay differently, without duplicating a unit definition to do it.
 */
function dropTableForSource(missionId, source) {
  const file = MISSION_CONTENT.missions ? MISSION_CONTENT.missions[missionId] : null;
  const override = file && file.dropTableByRef && file.dropTableByRef[source.ref];
  if (override) return override;
  const definition = CONTENT.units[source.definitionId];
  return (definition && definition.dropTableId) || null;
}

/**
 * Every reward source a finished attempt produced, in a stable order.
 *
 * Legacy campaign rewards are adapted here rather than anywhere deeper: a
 * mission whose file names no tables still pays what the `CAMPAIGN` literal
 * says, through the same grant pipeline, so there is one authority at runtime
 * even while two authoring locations exist. See docs/REWARDS.md for the
 * migration path.
 */
function collectRewardSources(campaign, missionId, outcome) {
  const sources = [];
  const tables = missionRewardTables(missionId);
  const firstClear = !campaign.completed.includes(missionId);

  if (tables.clear) {
    sources.push({ kind: "missionClear", id: missionId, label: missionLabel(missionId), tableIds: [tables.clear] });
  }
  if (firstClear && tables.firstClear) {
    sources.push({ kind: "firstClear", id: missionId, label: missionLabel(missionId), tableIds: [tables.firstClear] });
  }
  // Legacy: a campaign mission whose file names no tables still pays what the
  // literal says, adapted into ordinary grants. This is the only place the old
  // shape is understood, and it produces the same receipt lines authored data
  // would, so nothing downstream has two cases to handle.
  if (!tables.clear && !tables.firstClear && firstClear) {
    const adapted = legacyRewardTable(missionId);
    if (adapted) {
      sources.push({
        kind: "firstClear",
        id: missionId,
        label: missionLabel(missionId),
        tableIds: [LEGACY_TABLE_PREFIX + missionId]
      });
    }
  }
  // Hostile placements only. Losing one of your own is not salvage.
  const playerTeams = new Set(["player", "sectionSeven"]);
  for (const defeated of (outcome && outcome.defeated) || []) {
    if (playerTeams.has(defeated.teamId)) continue;
    const tableId = dropTableForSource(missionId, defeated);
    if (!tableId) continue;
    sources.push({
      kind: "unitDefeated",
      id: defeated.ref,
      label: defeated.label || defeated.ref,
      tableIds: [tableId]
    });
  }
  return sources;
}

/**
 * The `CAMPAIGN` literal's reward block, as a loot table.
 *
 * A compatibility shim with a deliberate expiry: every one of these missions
 * should eventually carry its rewards in its own file, and the count of
 * missions still relying on this is the migration's progress bar. Built on
 * demand rather than stored, so it cannot drift from the literal it adapts.
 *
 * These were all first-clear-only before this phase — `resolveMissionOutcome`
 * refused to pay a replay at all — so they adapt as first-clear sources, which
 * preserves exactly what the game did.
 */
const LEGACY_TABLE_PREFIX = "legacy:";

function legacyRewardTable(missionId) {
  const mission = CAMPAIGN.missions[missionId];
  const rewards = mission && mission.rewards;
  if (!rewards) return null;
  const guaranteed = [];
  for (const currencyId of CAMPAIGN_CURRENCY_IDS) {
    const amount = Number(rewards[currencyId]) || 0;
    if (amount > 0) {
      guaranteed.push({ id: currencyId, kind: "currency", itemId: currencyId, quantity: amount });
    }
  }
  for (const equipmentId of rewards.equipment || []) {
    guaranteed.push({
      id: "equipment:" + equipmentId,
      kind: "equipment",
      itemId: equipmentId,
      quantity: 1,
      claim: "oncePerCampaign"
    });
  }
  if (!guaranteed.length) return null;
  return { name: mission.name + " (legacy rewards)", guaranteed, pools: [] };
}

/** Canonical tables plus whatever legacy adapters this attempt needs. */
function lootTablesFor(missionId) {
  const legacy = legacyRewardTable(missionId);
  if (!legacy) return LOOT_TABLES;
  return { ...LOOT_TABLES, [LEGACY_TABLE_PREFIX + missionId]: legacy };
}

function missionLabel(missionId) {
  const mission = CAMPAIGN.missions[missionId];
  if (mission) return mission.name;
  const file = MISSION_CONTENT.missions ? MISSION_CONTENT.missions[missionId] : null;
  return (file && file.name) || missionId;
}

/**
 * The receipt a finished attempt would pay, without paying it.
 *
 * Called by the results screen to render, by the tests to assert and by
 * `resolveMissionOutcome` to apply. One answer, three readers.
 */
function planMissionRewards(campaign, missionId, outcome) {
  return planRewards({
    missionId,
    // The attempt already exists and is already persistent, so the roll key
    // needs no new state and no campaign seed. Replaying increments it, which
    // is exactly when a repeatable drop is allowed to roll again.
    attempt: (campaign.attempts && campaign.attempts[missionId]) || 1,
    campaign,
    tables: lootTablesFor(missionId),
    sources: collectRewardSources(campaign, missionId, outcome),
    currencyIds: CAMPAIGN_CURRENCY_IDS,
    equipmentIds: Object.keys(CONTENT.equipment),
    materialIds: Object.keys(MATERIALS)
  });
}

/* ---------------------------------------------------------------
 * SAVE AND LOAD
 * -------------------------------------------------------------*/

function saveCampaign(campaign) {
  return JSON.stringify({ ...campaign, version: CAMPAIGN_SAVE_VERSION });
}

/**
 * Where a campaign save actually lives.
 *
 * The save/load buttons used to call `window.storage`, a host-provided API that
 * does not exist in an ordinary browser — every write threw and was swallowed,
 * and every read reported "No save found". That was invisible while the only
 * way to load was a button you had to press on purpose; it is not invisible
 * once a main menu offers Continue.
 *
 * `localStorage` is the backend. `window.storage` is still honoured first when
 * it exists, so a host that provides one keeps working. Everything is
 * synchronous and total: a browser with storage disabled reports no save
 * rather than throwing into a render.
 */
const CAMPAIGN_SAVE_KEY = "statuszero.campaign.save";

function readCampaignSlot() {
  try {
    if (typeof localStorage !== "undefined") {
      const value = localStorage.getItem(CAMPAIGN_SAVE_KEY);
      if (value) return value;
    }
  } catch {
    /* storage can be disabled; that is not an error worth surfacing */
  }
  return null;
}

function writeCampaignSlot(serialized) {
  try {
    if (typeof localStorage !== "undefined") {
      localStorage.setItem(CAMPAIGN_SAVE_KEY, serialized);
      return true;
    }
  } catch {
    /* quota or privacy mode */
  }
  return false;
}

function clearCampaignSlot() {
  try {
    if (typeof localStorage !== "undefined") localStorage.removeItem(CAMPAIGN_SAVE_KEY);
  } catch {
    /* nothing to do */
  }
}

/** The saved campaign, or null when there is nothing usable to continue. */
function loadCampaignSlot() {
  const serialized = readCampaignSlot();
  if (!serialized) return null;
  return loadCampaign(serialized);
}

/** Cheap enough to call during a render: does Continue have anything to do? */
function hasCampaignSlot() {
  return loadCampaignSlot() !== null;
}

function loadCampaign(serialized) {
  try {
    const parsed = typeof serialized === "string" ? JSON.parse(serialized) : serialized;
    if (!parsed || ![CAMPAIGN_SAVE_VERSION, 4, 3, 2, 1].includes(parsed.version)) return null;
    const base = createCampaignState();
    const roster = {};
    for (const storedId of Object.keys(parsed.roster || {})) {
      // The one place a legacy operator id is translated. Everything past this
      // loop — including the entry's own `operatorId` field — is canonical.
      const operatorId = currentOperatorId(storedId);
      if (!CAMPAIGN.operators[operatorId]) continue;
      roster[operatorId] = {
        ...parsed.roster[storedId],
        operatorId,
        xp: parsed.roster[storedId].xp || 0,
        rank: parsed.roster[storedId].rank || 1,
        perkId: parsed.roster[storedId].perkId || null,
        loadout: cloneLoadout(parsed.roster[storedId].loadout)
      };
    }
    const migrated = parsed.version === 1
      ? { ...base, roster, log: ["Phase 6 save migrated into the Act One campaign shell; old mission completion was reset."] }
      : parsed.version === 2
      ? {
          ...parsed,
          activeMissionId: currentMissionId(parsed.activeMissionId),
          completed: migrateMissionIdList(parsed.completed),
          available: migrateMissionIdList(parsed.available),
          missionOrder: migrateMissionIdList(parsed.missionOrder),
          missionOutcomes: migrateMissionKeyedRecord(parsed.missionOutcomes),
          attempts: migrateMissionKeyedRecord(parsed.attempts),
          completedScenes: migrateCompletedSceneKeys(parsed.completedScenes),
          choiceHistory: (parsed.choiceHistory || []).map((entry) => ({
            ...entry,
            missionId: currentMissionId(entry.missionId)
          })),
          log: (parsed.log || []).concat("Mission IDs migrated to the act1-xx-name format.")
        }
      : parsed;
    return {
      ...base,
      ...migrated,
      version: CAMPAIGN_SAVE_VERSION,
      flags: { ...(migrated.flags || {}) },
      roster: Object.keys(roster).length ? roster : base.roster,
      inventory: { ...(migrated.inventory || base.inventory) },
      // A save written before rewards existed has no salvage and no claims.
      // Defaulting them empty is the whole migration: nothing is invented, and
      // a mission already completed stays completed, so its first clear is
      // correctly already spent.
      materials: { ...(migrated.materials || {}) },
      rewardClaims: { ...(migrated.rewardClaims || {}) },
      appliedReceipts: { ...(migrated.appliedReceipts || {}) },
      facilities: { ...(migrated.facilities || {}) },
      orderChoices: JSON.parse(JSON.stringify(migrated.orderChoices || {})),
      missionOrder: migrateMissionIdList(migrated.missionOrder).filter((missionId) => !!CAMPAIGN.missions[missionId]),
      missionOutcomes: JSON.parse(
        JSON.stringify(migrateOutcomeOperatorIds(migrateMissionKeyedRecord(migrated.missionOutcomes || {})))
      ),
      attempts: migrateMissionKeyedRecord(migrated.attempts || {}),
      activeMissionId: currentMissionId(migrated.activeMissionId),
      completedScenes: migrateCompletedSceneKeys(migrated.completedScenes),
      choiceHistory: (migrated.choiceHistory || []).map((entry) => ({ ...entry, missionId: currentMissionId(entry.missionId) })),
      completed: migrateMissionIdList(migrated.completed).filter((missionId) => !!CAMPAIGN.missions[missionId]),
      contacts: (migrated.contacts || []).filter((contactId) => !!CAMPAIGN.contacts[contactId]),
      available: migrateMissionIdList(migrated.available).filter((missionId) => !!CAMPAIGN.missions[missionId]),
      log: (migrated.log || []).slice()
    };
  } catch (error) {
    return null;
  }
}

