const PURE_PREVIEW_HELPERS = {
  createBattleViewModel: (state) => createBattleViewModel(state, {}),
  createUnitViewModel: (state) => createUnitViewModel(state, state.unitOrder[0]),
  getUnitDisplayStats: (state) => getUnitDisplayStats(state, state.unitOrder[0]),
  createTimelineViewModel: (state) => createTimelineViewModel(state, 15),
  enumerateValidMoveDestinations: (state) =>
    enumerateValidMoveDestinations(state, state.unitOrder[0]),
  enumerateValidAbilityTargets: (state) =>
    enumerateValidAbilityTargets(
      state,
      state.unitOrder[0],
      CONTENT.units[state.units[state.unitOrder[0]].definitionId].abilities[0]
    ),
  calculateActionRecoveryPreview: (state) =>
    calculateActionRecoveryPreview(state, state.unitOrder[0], null, 2),
  previewTimelineAfterRecovery: (state) =>
    previewTimelineAfterRecovery(state, state.unitOrder[0], 700, 10),
  createBattleSummary: (state) => createBattleSummary(state),
  createBattleLogViewModel: (state) => createBattleLogViewModel(state, "all"),
  createForecast: (state) => {
    const unitId = getNextActionableUnitId(state);
    const target = state.unitOrder.find(
      (id) => state.units[id].alive && state.units[id].teamId !== state.units[unitId].teamId
    );
    return createForecast(state, unitId, unitAbilityIds(state, unitId)[0], {
      x: state.units[target].x,
      y: state.units[target].y
    });
  },
  suggestAttackPlan: (state) => {
    const unitId = state.activeUnitId || getNextActionableUnitId(state);
    const target = state.unitOrder.find(
      (id) => state.units[id].alive && state.units[id].teamId !== state.units[unitId].teamId
    );
    return suggestAttackPlan(state, unitId, target);
  },
  createContextCommandModel: (state) =>
    createContextCommandModel(
      state,
      createInputState({ mode: "unitReady", selectedUnitId: state.activeUnitId })
    ),
  createHoverForecastModel: (state) => {
    const unitId = state.activeUnitId || getNextActionableUnitId(state);
    const target = state.unitOrder.find(
      (id) => state.units[id].alive && state.units[id].teamId !== state.units[unitId].teamId
    );
    return createHoverForecastModel(
      state,
      createInputState({ mode: "unitReady", selectedUnitId: state.activeUnitId }),
      { x: state.units[target].x, y: state.units[target].y }
    );
  },
  createBattleHudModel: (state) => createBattleHudModel(state),
  calculateUnitThreatZone: (state) => {
    const unitId = state.unitOrder.find((id) => state.units[id].alive);
    return calculateUnitThreatZone(state, unitId);
  },
  createContextualTargetOptions: (state) => {
    const activeUnitId = state.activeUnitId || getNextActionableUnitId(state);
    const target = state.unitOrder.find(
      (id) => state.units[id].alive && state.units[id].teamId !== state.units[activeUnitId].teamId
    );
    return createContextualTargetOptions(state, activeUnitId, target);
  },
  createUnitCardModel: (state) =>
    createUnitCardModel(state, state.activeUnitId || getNextActionableUnitId(state)),
  createCommandMenu: (state) =>
    createCommandMenu(state, state.activeUnitId || getNextActionableUnitId(state)),
  createActivationResources: (state) =>
    createActivationResources(state, state.activeUnitId || getNextActionableUnitId(state)),
  validateCommandSequence: (state) =>
    validateCommandSequence(state, [
      { type: "activateUnit", unitId: getNextActionableUnitId(state) }
    ]),
  previewCommandSequence: (state) =>
    previewCommandSequence(state, [
      { type: "activateUnit", unitId: getNextActionableUnitId(state) }
    ])
};
/* =========================================================================
 * TEST FIXTURES AND AUTOMATED TESTS
 * Concrete content ids are allowed below this point.
 * =======================================================================*/

const TEST_ENCOUNTER = "testBattle";

function assert(condition, message) {
  if (!condition) throw new Error(message || "Assertion failed");
}

function assertClose(actual, expected, tolerance, message) {
  if (Math.abs(actual - expected) > tolerance) {
    throw new Error(
      (message || "Value mismatch") + ": expected ~" + expected + ", got " + actual
    );
  }
}

function assertEqual(actual, expected, message) {
  if (actual !== expected) {
    throw new Error(
      (message || "Value mismatch") + ": expected " + expected + ", got " + actual
    );
  }
}

function testBattle(seed) {
  return createBattle(TEST_ENCOUNTER, seed == null ? 12345 : seed);
}

function place(state, unitId, x, y) {
  state.units[unitId].x = x;
  state.units[unitId].y = y;
}

function isolate(state, keepIds) {
  for (const id of state.unitOrder) {
    if (!keepIds.includes(id)) {
      state.units[id].alive = false;
      state.units[id].currentHp = 0;
    }
  }
}

function activate(state, unitId) {
  state.units[unitId].nextActionTime = state.currentTime;
  return executeCommand(state, { type: "activateUnit", unitId });
}

function scanValues(value, path, report) {
  if (typeof value === "number") {
    if (!Number.isFinite(value)) report.nonFinite.push(path);
    if (path.endsWith("currentHp") && value < 0) report.negative.push(path);
  } else if (Array.isArray(value)) {
    value.forEach((item, index) => scanValues(item, path + "[" + index + "]", report));
  } else if (value && typeof value === "object") {
    for (const key of Object.keys(value)) {
      scanValues(value[key], path + "." + key, report);
    }
  }
  return report;
}

function scanBattle(state) {
  return scanValues(state, "state", { nonFinite: [], negative: [] });
}

const TESTS = [];

function test(group, name, fn) {
  TESTS.push({ group, name, fn });
}

/* --- Registry and formulas ------------------------------------ */

test("Registry and formulas", "Ids derive from object keys", () => {
  assertEqual(CONTENT.units.swiftblade.id, "swiftblade");
  assertEqual(CONTENT.abilities.quickStrike.id, "quickStrike");
  assertEqual(CONTENT.statuses.poison.id, "poison");
  assert(!Object.prototype.hasOwnProperty.call(UNITS.swiftblade, "id"));
});

test("Registry and formulas", "Every unit ability exists", () => {
  for (const unitId of Object.keys(CONTENT.units)) {
    for (const abilityId of CONTENT.units[unitId].abilities) {
      assert(CONTENT.abilities[abilityId], unitId + " -> " + abilityId);
    }
  }
});

test("Registry and formulas", "Every effect type has a handler", () => {
  for (const ability of Object.values(CONTENT.abilities)) {
    for (const effect of ability.effects) {
      assert(EFFECT_HANDLERS[effect.type], "Missing handler: " + effect.type);
    }
  }
  for (const status of Object.values(CONTENT.statuses)) {
    for (const trigger of status.triggers) {
      for (const effect of trigger.effects) {
        assert(EFFECT_HANDLERS[effect.type], "Missing handler: " + effect.type);
      }
    }
  }
});

test("Registry and formulas", "Every formula reference exists", () => {
  const check = (effects, label) => {
    for (const effect of effects) {
      if (effect.type === "damage") {
        assert(FORMULAS.damage[effect.formula], label + " " + effect.formula);
      }
      if (effect.type === "heal") {
        assert(FORMULAS.healing[effect.formula], label + " " + effect.formula);
      }
    }
  };
  for (const ability of Object.values(CONTENT.abilities)) check(ability.effects, ability.id);
  for (const status of Object.values(CONTENT.statuses)) {
    for (const trigger of status.triggers) check(trigger.effects, status.id);
  }
});

test("Registry and formulas", "100 Speed is about 1.00x turn rate", () => {
  assertClose(FORMULAS.timeline.turnRate(100), 1.0, 0.01);
});

test("Registry and formulas", "150 Speed is about 1.37x turn rate", () => {
  assertClose(FORMULAS.timeline.turnRate(150), 1.37, 0.01);
});

test("Registry and formulas", "200 Speed is about 1.70x turn rate", () => {
  assertClose(FORMULAS.timeline.turnRate(200), 1.7, 0.01);
});

test("Registry and formulas", "300 Speed is about 2.33x turn rate", () => {
  assertClose(FORMULAS.timeline.turnRate(300), 2.33, 0.01);
});

test("Registry and formulas", "Invalid Speed is safely clamped", () => {
  for (const speed of [0, -50, 0.0001]) {
    const rate = FORMULAS.timeline.turnRate(speed);
    assert(Number.isFinite(rate) && rate > 0, "Turn rate must stay finite and positive");
    assertEqual(rate, FORMULAS.timeline.turnRate(1));
  }
  const state = testBattle();
  state.units.u1.statuses.push({ statusId: "slow", remaining: 3 });
  state.units.u1.statuses.push({ statusId: "slow", remaining: 3 });
  assert(calculateUnitStats(state, "u1").speed >= 1);
});

test("Registry and formulas", "Formula changes affect engine results", () => {
  const state = testBattle();
  isolate(state, ["u1", "u4"]);
  place(state, "u1", 3, 3);
  place(state, "u4", 3, 4);
  activate(state, "u1");
  const before = validateCommand(state, {
    type: "useAbility",
    unitId: "u1",
    abilityId: "quickStrike",
    target: { unitId: "u4" }
  }).preview.outcomes[0].amount;

  const original = FORMULAS.damage.physical;
  FORMULAS.damage.physical = ({ attack, power }) => attack * power / 10;
  const after = validateCommand(state, {
    type: "useAbility",
    unitId: "u1",
    abilityId: "quickStrike",
    target: { unitId: "u4" }
  }).preview.outcomes[0].amount;
  FORMULAS.damage.physical = original;

  assert(after > before, "Editing the formula must change engine output");
});

/* --- Timeline -------------------------------------------------- */

test("Timeline", "Lowest next action time acts first", () => {
  const state = testBattle();
  state.units.u3.nextActionTime = 1;
  assertEqual(getNextActionableUnitId(state), "u3");
});

test("Timeline", "Ties use higher Speed", () => {
  const state = testBattle();
  for (const id of state.unitOrder) state.units[id].nextActionTime = 100;
  const fastest = state.unitOrder
    .map((id) => ({ id, speed: calculateUnitStats(state, id).speed }))
    .sort((a, b) => b.speed - a.speed)[0];
  assertEqual(getNextActionableUnitId(state), fastest.id);
});

test("Timeline", "Remaining ties use creation order", () => {
  const state = testBattle();
  isolate(state, ["u1", "u5"]);
  state.units.u1.nextActionTime = 50;
  state.units.u5.nextActionTime = 50;
  assertEqual(calculateUnitStats(state, "u1").speed, calculateUnitStats(state, "u5").speed);
  assertEqual(getNextActionableUnitId(state), "u1");
});

test("Timeline", "Fast units act twice before a slow unit", () => {
  const state = testBattle();
  const preview = previewTimeline(state, 12);
  const firstIronbound = preview.findIndex((entry) => state.units[entry.unitId].definitionId === "ironbound");
  const swiftBefore = preview
    .slice(0, firstIronbound)
    .filter((entry) => state.units[entry.unitId].definitionId === "swiftblade").length;
  assert(swiftBefore >= 2, "Swift units should lap slower ones");
});

test("Timeline", "Recovery affects next action time", () => {
  const state = testBattle();
  isolate(state, ["u1", "u4"]);
  place(state, "u1", 3, 3);
  place(state, "u4", 3, 4);
  activate(state, "u1");
  const start = state.currentTime;
  executeCommand(state, {
    type: "useAbility",
    unitId: "u1",
    abilityId: "quickStrike",
    target: { unitId: "u4" }
  });
  executeCommand(state, { type: "endTurn", unitId: "u1" });
  const rate = FORMULAS.timeline.turnRate(calculateUnitStats(state, "u1").speed);
  assertClose(
    state.units.u1.nextActionTime - start,
    CONTENT.abilities.quickStrike.timing.recovery / rate,
    0.001
  );
});

test("Timeline", "Movement adds recovery", () => {
  const state = testBattle();
  isolate(state, ["u1", "u4"]);
  place(state, "u1", 3, 3);
  place(state, "u4", 7, 0);
  activate(state, "u1");
  const start = state.currentTime;
  executeCommand(state, {
    type: "move",
    unitId: "u1",
    path: [{ x: 3, y: 3 }, { x: 3, y: 2 }, { x: 3, y: 1 }]
  });
  executeCommand(state, { type: "wait", unitId: "u1" });
  const rate = FORMULAS.timeline.turnRate(calculateUnitStats(state, "u1").speed);
  const expected =
    (GAME_CONFIG.timeline.waitRecovery + 2 * GAME_CONFIG.timeline.movementRecoveryPerTile) / rate;
  assertClose(state.units.u1.nextActionTime - start, expected, 0.001);
});

test("Timeline", "Waiting schedules the next action correctly", () => {
  const state = testBattle();
  isolate(state, ["u2", "u4"]);
  place(state, "u2", 3, 3);
  place(state, "u4", 7, 0);
  activate(state, "u2");
  const start = state.currentTime;
  executeCommand(state, { type: "wait", unitId: "u2" });
  const rate = FORMULAS.timeline.turnRate(calculateUnitStats(state, "u2").speed);
  assertClose(
    state.units.u2.nextActionTime - start,
    GAME_CONFIG.timeline.waitRecovery / rate,
    0.001
  );
});

test("Timeline", "Haste advances future turns", () => {
  const base = testBattle();
  isolate(base, ["u2", "u4"]);
  place(base, "u4", 7, 0);
  activate(base, "u2");
  executeCommand(base, { type: "wait", unitId: "u2" });
  const normal = base.units.u2.nextActionTime - 0;

  const hasted = testBattle();
  isolate(hasted, ["u2", "u4"]);
  place(hasted, "u4", 7, 0);
  hasted.units.u2.statuses.push({ statusId: "haste", remaining: 3 });
  activate(hasted, "u2");
  executeCommand(hasted, { type: "wait", unitId: "u2" });
  assert(hasted.units.u2.nextActionTime < normal, "Haste should shorten recovery");
});

test("Timeline", "Slow delays future turns", () => {
  const base = testBattle();
  isolate(base, ["u2", "u4"]);
  place(base, "u4", 7, 0);
  activate(base, "u2");
  executeCommand(base, { type: "wait", unitId: "u2" });
  const normal = base.units.u2.nextActionTime;

  const slowed = testBattle();
  isolate(slowed, ["u2", "u4"]);
  place(slowed, "u4", 7, 0);
  slowed.units.u2.statuses.push({ statusId: "slow", remaining: 3 });
  activate(slowed, "u2");
  executeCommand(slowed, { type: "wait", unitId: "u2" });
  assert(slowed.units.u2.nextActionTime > normal, "Slow should lengthen recovery");
});

test("Timeline", "Timeline preview does not mutate state", () => {
  const state = testBattle();
  const before = JSON.stringify(state);
  previewTimeline(state, 15);
  assertEqual(JSON.stringify(state), before);
});

/* --- Grid and movement ----------------------------------------- */

test("Grid and movement", "Movement stays within bounds", () => {
  const state = testBattle();
  const map = getMap(state);
  for (const tile of computeMovementRange(state, "u1").values()) {
    assert(inBounds(map, tile.x, tile.y), "Out of bounds tile " + tileKey(tile.x, tile.y));
  }
});

test("Grid and movement", "Units cannot move through walls", () => {
  const state = testBattle();
  isolate(state, ["u2"]);
  place(state, "u2", 2, 2);
  const range = computeMovementRange(state, "u2");
  assert(!range.has(tileKey(2, 1)), "Wall tile must be unreachable");
  const result = validatePath(state, "u2", [
    { x: 2, y: 2 },
    { x: 2, y: 1 }
  ]);
  assert(!result.valid, "Path through a wall must be rejected");
});

test("Grid and movement", "Units cannot move through occupied tiles", () => {
  const state = testBattle();
  isolate(state, ["u1", "u2"]);
  place(state, "u1", 3, 3);
  place(state, "u2", 3, 2);
  const range = computeMovementRange(state, "u1");
  assert(!range.has(tileKey(3, 2)), "Occupied tile must be excluded");
  const result = validatePath(state, "u1", [
    { x: 3, y: 3 },
    { x: 3, y: 2 }
  ]);
  assert(!result.valid, "Path into an occupied tile must be rejected");
});

test("Grid and movement", "Terrain movement cost is respected", () => {
  const state = testBattle();
  isolate(state, ["u1"]);
  place(state, "u1", 1, 2);
  const range = computeMovementRange(state, "u1");
  assertEqual(range.get(tileKey(1, 3)).cost, CONTENT.terrains.rough.movementCost);
});

test("Grid and movement", "Shortest path is valid", () => {
  const state = testBattle();
  isolate(state, ["u1"]);
  place(state, "u1", 0, 0);
  const path = findPath(state, "u1", { x: 3, y: 1 });
  assert(path, "Path should exist");
  const result = validatePath(state, "u1", path);
  assert(result.valid, result.errors.join(" "));
  assertEqual(path.length - 1, 4);
});

test("Grid and movement", "Unreachable targets return no path", () => {
  const state = testBattle();
  isolate(state, ["u1"]);
  place(state, "u1", 0, 0);
  assertEqual(findPath(state, "u1", { x: 2, y: 1 }), null);
  assertEqual(findPath(state, "u1", { x: 7, y: 7 }), null);
});

test("Grid and movement", "Movement range is calculated correctly", () => {
  const state = testBattle();
  isolate(state, ["u1"]);
  place(state, "u1", 4, 4);
  const budget = calculateUnitStats(state, "u1").movement;
  const range = computeMovementRange(state, "u1");
  for (const tile of range.values()) {
    assert(tile.cost <= budget, "Tile beyond movement budget");
    assert(isWalkable(getMap(state), tile.x, tile.y), "Unwalkable tile in range");
  }
  assert(range.has(tileKey(4, 3)) && range.has(tileKey(5, 4)));
});

test("Grid and movement", "A move command rejects an invalid path", () => {
  const state = testBattle();
  activate(state, getNextActionableUnitId(state));
  const unitId = state.activeUnitId;
  const before = JSON.stringify(state);
  const result = executeCommand(state, {
    type: "move",
    unitId,
    path: [
      { x: state.units[unitId].x, y: state.units[unitId].y },
      { x: state.units[unitId].x + 3, y: state.units[unitId].y }
    ]
  });
  assert(!result.ok, "Teleporting path must be rejected");
  assertEqual(JSON.stringify(state), before);
});

