  assert(!hasLineOfSight(map, { x: 2, y: 0 }, { x: 2, y: 2 }), "Wall should block");
  assert(hasLineOfSight(map, { x: 0, y: 0 }, { x: 0, y: 4 }), "Open column should see");
  isolate(state, ["u4", "u1"]);
  place(state, "u4", 2, 0);
