test("Statuses", "Poison lasts the correct number of personal activations", () => {
  const state = testBattle();
  isolate(state, ["u1", "u4"]);
  place(state, "u1", 0, 0);
  place(state, "u4", 7, 7);
  state.units.u1.statuses.push({ statusId: "poison", remaining: 3, sourceUnitId: "u4" });
  let ticks = 0;
  for (let i = 0; i < 5; i += 1) {
    const before = state.units.u1.currentHp;
    activate(state, "u1");
    if (state.units.u1.currentHp < before) ticks += 1;
    executeCommand(state, { type: "wait", unitId: "u1" });
  }
  assertEqual(ticks, 3);
  assertEqual(state.units.u1.statuses.length, 0);
});

