test("AI", "AI never selects an illegal command", () => {
  const state = testBattle(808);
  let checked = 0;
  let activations = 0;
  while (!state.finished && activations < GAME_CONFIG.limits.maxActivationsPerBattle) {
    const unitId = beginNextActivation(state);
    if (!unitId) break;
    activations += 1;
    if (state.activeUnitId !== unitId || state.finished) continue;
    for (const command of chooseAiCommands(state, unitId)) {
      const validation = validateCommand(state, command);
      assert(
        validation.valid,
        "Illegal AI command " + command.type + ": " + validation.errors.join(" ")
      );
      checked += 1;
      executeCommand(state, command);
    }
    if (state.activeUnitId === unitId && !state.finished) {
      executeCommand(state, { type: "wait", unitId });
    }
  }
  assert(checked > 10, "The AI should have issued commands");
});

