  const beforeCounter = state.randomState.counter;
  const preview = createActionPreview(state, "u1", "quickStrike", { unitId: "u4" });
  assert(preview.valid, (preview.errors || []).join(" "));
  assertEqual(state.randomState.counter, beforeCounter);
  assertEqual(JSON.stringify(state), beforeState);
  const sequence = previewCommandSequence(state, [
    { type: "move", unitId: "u1", path: [{ x: 3, y: 3 }, { x: 4, y: 3 }] }
  ]);
