test("Interaction", "A full manual player turn runs through the input state machine", () => {
  const state = activePlayerBattle(777);
  let input = createInputState();
  const dispatch = (action) => {
    const outcome = drive(input, action, state);
    input = outcome.input;
    for (const command of outcome.commands) {
      const result = executeCommandWithPresentation(state, command);
      assert(result.ok, "Command rejected: " + result.errors.join(" "));
    }
    if (outcome.commands.length) input = drive(input, { type: "presentationFinished" }, state).input;
    return outcome;
  };

  dispatch({ type: "activationStarted", unitId: "u1" });
  assertEqual(input.mode, "unitReady");
  assertEqual(input.commandMenuOpen, false, "A new activation shows no floating menu");
  dispatch({ type: "clickTile", tile: { x: 3, y: 3 } });
  assertEqual(input.commandMenuOpen, true, "Clicking the active unit opens the menu");
  dispatch({ type: "clickTile", tile: { x: 3, y: 3 } });
  assertEqual(input.commandMenuOpen, false, "Clicking it again closes the menu");

  dispatch({ type: "hoverTile", tile: { x: 4, y: 4 } });
  assert(input.hoverPath, "Hover should preview a path");

  dispatch({ type: "clickTile", tile: { x: 4, y: 4 } });
  assertEqual(input.mode, "planningMove");
  assertEqual(input.plannedMoveDestination.x, 4);

  dispatch({ type: "cancel" });
  assertEqual(input.mode, "unitReady");
  assertEqual(input.plannedPath, null);

  dispatch({ type: "clickTile", tile: { x: 4, y: 4 } });
  dispatch({ type: "clickTile", tile: { x: 4, y: 4 } });
  assertEqual(state.units.u1.x, 4);
  assertEqual(state.units.u1.y, 4);
  assertEqual(input.mode, "unitReady", "Movement returns to the ready state");
  assertEqual(input.commandMenuOpen, false, "The menu stays closed until asked for");
  assertEqual(createActivationResources(state, "u1").moveLabel, "USED");
  assertEqual(createActivationResources(state, "u1").actionLabel, "READY");

  dispatch({ type: "chooseAbility", abilityId: "quickStrike" });
  assertEqual(input.mode, "planningTarget");

  dispatch({ type: "clickTile", tile: { x: 3, y: 4 } });
  assertEqual(input.mode, "confirmingAction");
  assert(input.forecast.valid);
  assert(input.forecast.headline.value > 0);

  const hpBefore = state.units.u4.currentHp;
  dispatch({ type: "confirm" });
  assertEqual(state.activeUnitId, null, "Move plus act ends the activation");
  assertEqual(input.mode, "idle");
  assert(
    state.units.u4.currentHp < hpBefore || state.battleLog.some((e) => e.type === "attackMissed"),
    "The attack must resolve"
  );
  assert(validateBattleState(state).valid);
});

