test("Scenes", "The step registry drives the editor, so a new type needs no editor change", () => {
  // Every palette entry must be renderable and editable purely from its own
  // declaration. If this ever fails, someone special-cased a step somewhere.
  for (const type of SCENE_STEP_PALETTE) {
    const definition = SCENE_STEP_TYPES[type];
    assert(definition, type + " is in the palette but not the registry");
    assert(typeof definition.label === "string" && definition.label, type + " needs a label");
    assert(typeof definition.summary === "function", type + " needs a summary");
    assert(typeof definition.defaults === "function", type + " needs defaults");
    assert(typeof definition.validate === "function", type + " needs validation");
    assert(typeof definition.apply === "function", type + " needs an apply");
    assert(Array.isArray(definition.fields), type + " needs a field list");

    // A default step of every type must be valid once the author fills in what
    // the step declares required — text, and who is saying it. Anything else
    // missing would mean "add step" creates something broken.
    //
    // A speaker is required author input rather than a default: the step
    // registry is generic and must not name a character, so a new dialogue
    // step arrives with the field empty and the editor asks for it.
    const step = normalizeStep({ type });
    const placeholders = {
      text: "placeholder",
      line: "placeholder",
      background: "warner-road",
      // Whoever the campaign happens to list first. Read rather than named, so
      // this check survives the cast changing.
      speaker: Object.keys(CAMPAIGN.speakers)[0]
    };
    for (const field of definition.fields) {
      if (field.required && !step[field.key] && placeholders[field.kind]) {
        step[field.key] = placeholders[field.kind];
      }
    }
    const report = validateScene(
      buildTestScene([{ type: "dialogue", speaker: "vale", text: "x" }, step]),
      SCENE_TEST_REFS()
    );
    assertEqual(report.ok, true, type + " default is invalid: " + report.errors.join(" | "));

    // And every declared field must use a kind the inspector knows.
    for (const field of definition.fields) {
      assert(
        ["text", "line", "speaker", "expression", "position", "background", "musicContext", "enum"].includes(
          field.kind
        ),
        type + "." + field.key + ' uses unknown field kind "' + field.kind + '"'
      );
    }
  }
});

/* =========================================================================
 * GAMEPLAY DATA
 *
 * The property the whole Studio workflow rests on: authored data is a set of
 * files, the game reads exactly those files, and a bundle exported from the
 * Studio can be applied to the repository mechanically. Every test below is
 * defending one link in that chain.
 * =======================================================================*/

/** Deep equality that ignores key order, which the engine is free to change. */
function sameAuthoredValue(live, authored) {
  if (Array.isArray(authored)) {
    return (
      Array.isArray(live) &&
      live.length === authored.length &&
      authored.every((entry, index) => sameAuthoredValue(live[index], entry))
    );
  }
  if (authored && typeof authored === "object") {
    if (!live || typeof live !== "object") return false;
    return Object.keys(authored).every((key) => sameAuthoredValue(live[key], authored[key]));
  }
  return live === authored;
}

/** A deep copy of the shipped data, safe to mutate in a test. */
function gameplayDraftFixture() {
  const out = {};
  for (const kindId of REGISTRY_IDS) out[kindId] = JSON.parse(JSON.stringify(CANONICAL_GAMEPLAY[kindId]));
  return out;
}

test("Gameplay data", "Serialization is canonical, stable and lossless", () => {
  for (const kindId of REGISTRY_IDS) {
    const entries = CANONICAL_GAMEPLAY[kindId];
    assert(Object.keys(entries).length > 0, kindId + " is empty");

    const text = serializeRegistryFile(kindId, entries);
    const reread = parseRegistryFile(text).entries;
    assertEqual(
      JSON.stringify(reread),
      JSON.stringify(parseRegistryFile(serializeRegistryFile(kindId, reread)).entries),
      kindId + " does not survive a round trip"
    );

    // Same bytes twice: an export must be identifiable by its content alone,
    // with no clock, no counter and no insertion order leaking in.
    assertEqual(text, serializeRegistryFile(kindId, entries), kindId + " serialization is not stable");

    // Key order is not a matter of taste here. Two authors editing the same
    // entity must produce the same file, so a shuffled entity is byte-equal.
    const firstId = Object.keys(entries).sort()[0];
    const shuffled = {};
    for (const key of Object.keys(entries[firstId]).reverse()) shuffled[key] = entries[firstId][key];
    assertEqual(
      JSON.stringify(canonicalEntity(kindId, shuffled)),
      JSON.stringify(canonicalEntity(kindId, entries[firstId])),
      kindId + ": key order changes the canonical form"
    );
    assert(entitiesEqual(kindId, shuffled, entries[firstId]), kindId + ": reordering counts as a change");

    // Entities are written in id order, so a diff of two exports shows only
    // what moved.
    const ids = Object.keys(JSON.parse(text).entries);
    assertEqual(ids.join(","), ids.slice().sort().join(","), kindId + " entries are not id-ordered");
  }
});

test("Gameplay data", "The shipped files are already in canonical form", () => {
  // Guards against a hand-edit landing in a shape the Studio would rewrite:
  // if this fails, an export of unmodified data would produce a spurious diff.
  for (const kindId of REGISTRY_IDS) {
    const rewritten = JSON.parse(serializeRegistryFile(kindId, CANONICAL_GAMEPLAY[kindId]));
    assertEqual(rewritten.registry, kindId, kindId + " file declares the wrong registry");
    assertEqual(
      JSON.stringify(rewritten.entries),
      JSON.stringify(CANONICAL_GAMEPLAY[kindId]),
      kindId + ".json is not in canonical form — re-export it"
    );
  }
});

test("Gameplay data", "The game runs on the authored files, not a copy of them", () => {
  // The registries App.jsx builds CONTENT from must be the ones on disk. If
  // this ever fails, the Studio would be editing data the game ignores.
  const pairs = [
    ["units", CONTENT.units],
    ["abilities", CONTENT.abilities],
    ["statuses", CONTENT.statuses],
    ["equipment", CONTENT.equipment]
  ];
  for (const [kindId, live] of pairs) {
    const authored = GAMEPLAY_CONTENT[kindId];
    assertEqual(
      Object.keys(live).sort().join(","),
      Object.keys(authored).sort().join(","),
      kindId + ": the engine and the files disagree about which entities exist"
    );
    for (const id of Object.keys(authored)) {
      for (const key of Object.keys(authored[id])) {
        // Key order is not the claim here — the engine normalizes some of
        // these on the way in. The claim is that no authored value was lost.
        assert(
          sameAuthoredValue(live[id][key], authored[id][key]),
          kindId + "." + id + "." + key + " differs between the file and the engine"
        );
      }
    }
  }
  assert(
    Object.keys(GAMEPLAY_CONTENT.aiProfiles).every((id) => AI_PROFILES[id]),
    "AI profiles are not loaded from the file"
  );
});

test("Gameplay data", "The shipped data validates, and broken references do not", () => {
  const clean = validateGameplayData(CANONICAL_GAMEPLAY, {
    missionIds: Object.keys(MISSION_CONTENT.missions)
  });
  assertEqual(clean.errors.length, 0, clean.errors.join(" | "));

  const broken = gameplayDraftFixture();
  broken.units.assaultMech.abilities = ["scatterShot", "thisAbilityDoesNotExist"];
  const report = validateGameplayData(broken);
  assertEqual(report.ok, false, "a dangling ability reference must fail");
  assert(
    report.errors.some((message) => /thisAbilityDoesNotExist/.test(message)),
    report.errors.join(" | ")
  );

  const badSlot = gameplayDraftFixture();
  badSlot.units.assaultMech.defaultEquipment = { primaryWeapon: "plateArmor" };
  assertEqual(validateGameplayData(badSlot).ok, false, "armour in a weapon slot must fail");

  const badClass = gameplayDraftFixture();
  badClass.equipment.closeShotgun.compatibleClasses = ["support"];
  assertEqual(
    validateGameplayData(badClass).ok,
    false,
    "a chassis holding a part it may not hold must fail"
  );
});

/**
 * A route action is authored the same way anything else is, which means it can
 * be authored wrong the same way. Every rule the planner relies on has to be
 * something the Studio refuses before an export rather than something the
 * player discovers mid-charge.
 */
test("Gameplay data", "A route action is editable content, and a broken one is refused", () => {
  const schema = REGISTRY_SCHEMAS.abilities;
  const section = schema.sections.find((entry) => entry.id === "trajectory");
  assert(section, "the Studio has a trajectory section");
  const keys = section.fields.map((field) => field.key);
  for (const key of [
    "trajectory.maxSegments",
    "trajectory.allowedRedirects",
    "trajectory.resourceId",
    "trajectory.redirectCosts",
    "trajectory.contactEffects"
  ]) {
    assert(keys.includes(key), key + " is not editable");
  }
  // Precise displacement is a stat, so it has to be a stat an author can set.
  assert(
    BASE_STAT_FIELDS.some((field) => field.key === "displacementResistance"),
    "displacement resistance is invisible in the Studio"
  );

  const unknownResource = gameplayDraftFixture();
  unknownResource.abilities.machStrike.trajectory.resourceId = "notARealPool";
  assert(
    validateGameplayData(unknownResource).errors.some((message) => /notARealPool/.test(message)),
    "a route priced in a pool that does not exist must fail"
  );

  const unknownTurn = gameplayDraftFixture();
  unknownTurn.abilities.machStrike.trajectory.allowedRedirects = ["quarter", "pirouette"];
  assert(
    validateGameplayData(unknownTurn).errors.some((message) => /pirouette/.test(message)),
    "a turn category the planner has never heard of must fail"
  );

  const unpaid = gameplayDraftFixture();
  delete unpaid.abilities.machStrike.trajectory.resourceId;
  assertEqual(validateGameplayData(unpaid).ok, false, "prices with nothing to pay them in must fail");

  const deadPrice = gameplayDraftFixture();
  deadPrice.abilities.machStrike.trajectory.redirectCosts = { reverse: 3 };
  assert(
    validateGameplayData(deadPrice).warnings.some((message) => /reverse/.test(message)),
    "pricing a turn the action forbids is worth saying out loud"
  );

  const badContact = gameplayDraftFixture();
  badContact.abilities.machStrike.trajectory.contactEffects = [
    { type: "applyStatus", statusId: "noSuchStatus", chance: 1 }
  ];
  assert(
    validateGameplayData(badContact).errors.some((message) => /noSuchStatus/.test(message)),
    "a contact effect's references are checked like any other effect's"
  );
});

test("Gameplay data", "Deleting something other data depends on is refused", () => {
  const references = referencesTo(CANONICAL_GAMEPLAY, "abilities", "scatterShot", {});
  assert(references.length > 0, "scatterShot is used by a unit but nothing reported it");
  assert(
    references.every((entry) => typeof entry.where === "string" && entry.where),
    "a reference must say where it is"
  );
  assertEqual(
    referencesTo(CANONICAL_GAMEPLAY, "abilities", "noSuchAbility", {}).length,
    0,
    "an unreferenced id has no dependents"
  );
});

test("Gameplay data", "The diff is semantic: only a real change is a change", () => {
  const untouched = gameplayDraftFixture();
  assertEqual(diffAgainstCanonical(CANONICAL_GAMEPLAY, untouched).length, 0, "a copy is not a change");

  // Re-serializing everything must still be no change, which is what makes
  // "export changes" trustworthy.
  const rewritten = {};
  for (const kindId of REGISTRY_IDS) {
    rewritten[kindId] = parseRegistryFile(serializeRegistryFile(kindId, CANONICAL_GAMEPLAY[kindId])).entries;
  }
  assertEqual(diffAgainstCanonical(CANONICAL_GAMEPLAY, rewritten).length, 0, "a round trip is not a change");

  const edited = gameplayDraftFixture();
  edited.units.assaultMech.baseStats.maxHp = 999;
  edited.abilities.newThing = { name: "New Thing", effects: [] };
  delete edited.perks.valeBulwark;
  const changes = diffAgainstCanonical(CANONICAL_GAMEPLAY, edited);
  assertEqual(changes.length, 3, changes.map((entry) => entry.id).join(","));
  const byId = Object.fromEntries(changes.map((entry) => [entry.id, entry.operation]));
  assertEqual(byId.assaultMech, "modify");
  assertEqual(byId.newThing, "add");
  assertEqual(byId.valeBulwark, "delete");
});

test("Gameplay data", "A changes export names every entity and ships whole files", () => {
  const edited = gameplayDraftFixture();
  edited.units.assaultMech.baseStats.maxHp = 999;

  const bundle = buildBundle(CANONICAL_GAMEPLAY, edited, { mode: "changes" });
  assertEqual(bundle.changes.length, 1);
  assertEqual(bundle.manifest.entityCount, 1);
  assertEqual(bundle.manifest.entities[0].id, "assaultMech");
  assertEqual(bundle.manifest.entities[0].operation, "modify");
  assertEqual(bundle.manifest.entities[0].path, REGISTRY_KINDS.units.path);

  // Only the touched registry travels, and it travels complete: a partial
  // registry file is not something the game could load.
  assert(bundle.files[REGISTRY_KINDS.units.path], "the units file is missing");
  assert(!bundle.files[REGISTRY_KINDS.perks.path], "an untouched registry must not be exported");
  const shipped = parseRegistryFile(bundle.files[REGISTRY_KINDS.units.path]).entries;
  assertEqual(
    Object.keys(shipped).length,
    Object.keys(CANONICAL_GAMEPLAY.units).length,
    "the exported file must contain every unit, not just the edited one"
  );
  assertEqual(shipped.assaultMech.baseStats.maxHp, 999);

  // The handoff has to be readable by whoever applies it.
  assert(bundle.files["manifest.json"], "no manifest");
  assert(/assaultMech/.test(bundle.files["README.md"]), "the README does not name the change");
  assert(/src\/content\/gameplay\/units\.json/.test(bundle.files["README.md"]), "no destination path");

  // Deterministic: the same authored state exports the same bytes.
  assertEqual(
    bundleToText(bundle),
    bundleToText(buildBundle(CANONICAL_GAMEPLAY, gameplayDraftFixture_withHp(999), { mode: "changes" })),
    "two exports of the same state differ"
  );
});

function gameplayDraftFixture_withHp(value) {
  const draft = gameplayDraftFixture();
  draft.units.assaultMech.baseStats.maxHp = value;
  return draft;
}

test("Gameplay data", "Export and import round trip exactly", () => {
  const edited = gameplayDraftFixture();
  edited.units.assaultMech.baseStats.maxHp = 999;
  edited.equipment.closeShotgun.name = "Close Shotgun II";
  edited.abilities.newThing = { name: "New Thing", description: "", effects: [] };

  const bundle = buildBundle(CANONICAL_GAMEPLAY, edited, { mode: "changes" });
  const files = bundleFromText(bundleToText(bundle));
  assertEqual(
    Object.keys(files).sort().join(","),
    Object.keys(bundle.files).sort().join(","),
    "the text form lost a file"
  );
  for (const path of Object.keys(bundle.files)) {
    assertEqual(files[path], bundle.files[path], path + " changed passing through text");
  }

  const manifest = manifestFromFiles(files);
  assertEqual(manifest.entityCount, 3);

  const imported = draftFromBundle(CANONICAL_GAMEPLAY, files);
  assertEqual(imported.problems.length, 0, imported.problems.join(" | "));
  assertEqual(imported.applied.length, 3, "three registries should have been applied");

  const reimportedChanges = diffAgainstCanonical(CANONICAL_GAMEPLAY, imported.draft);
  assertEqual(
    reimportedChanges.map((entry) => entry.kind + ":" + entry.id + ":" + entry.operation).sort().join(","),
    diffAgainstCanonical(CANONICAL_GAMEPLAY, edited)
      .map((entry) => entry.kind + ":" + entry.id + ":" + entry.operation)
      .sort()
      .join(","),
    "the imported draft does not describe the same change set"
  );

  // Import is not an install: the canonical data this session loaded is
  // untouched, and so is the running game.
  assertEqual(CANONICAL_GAMEPLAY.units.assaultMech.baseStats.maxHp, 130, "import mutated canonical data");
});

test("Gameplay data", "A full export of unmodified data reproduces the shipped files", () => {
  const bundle = buildBundle(CANONICAL_GAMEPLAY, gameplayDraftFixture(), { mode: "full" });
  for (const kindId of REGISTRY_IDS) {
    assertEqual(
      bundle.files[REGISTRY_KINDS[kindId].path],
      serializeRegistryFile(kindId, CANONICAL_GAMEPLAY[kindId]),
      kindId + ": a full export does not match what is on disk"
    );
  }
  const imported = draftFromBundle(CANONICAL_GAMEPLAY, bundleFromText(bundleToText(bundle)));
  assertEqual(
    diffAgainstCanonical(CANONICAL_GAMEPLAY, imported.draft).length,
    0,
    "exporting and reimporting unmodified data produced a change"
  );
});

test("Gameplay data", "The schema describes every authored field", () => {
  // The anti-opacity guard. Anything present in the data but absent from the
  // schema would be invisible in the Studio and silently dropped by an author
  // who edited around it.
  for (const kindId of REGISTRY_IDS) {
    const schema = REGISTRY_SCHEMAS[kindId];
    assert(schema, kindId + " has no schema");
    const declared = new Set();
    for (const section of schema.sections) {
      for (const field of section.fields) declared.add(field.key.split(".")[0]);
    }
    // `*` means the editor edits the whole entity as one map, which covers
    // every key by construction (AI profiles are exactly that).
    if (!declared.has("*")) {
      const seen = new Set();
      for (const id of Object.keys(CANONICAL_GAMEPLAY[kindId])) {
        for (const key of Object.keys(CANONICAL_GAMEPLAY[kindId][id])) seen.add(key);
      }
      for (const key of seen) {
        assert(declared.has(key), kindId + "." + key + " exists in the data but not in the schema");
      }
    }

    // And a blank entity must be something the Studio can then save.
    const probe = gameplayDraftFixture();
    const blank = blankEntity(kindId);
    // A blank entity is valid once the author supplies the references only
    // they can choose. Filling those here is the same allowance the scene
    // suite makes for required free text.
    if (kindId === "combatLinks") {
      const anyOperator = Object.keys(probe.operators).sort()[0];
      blank.participants = [probe.operators[anyOperator].ref || anyOperator];
    }
    probe[kindId]["studioProbeEntity"] = blank;
    const report = validateGameplayData(probe);
    assert(
      !report.errors.some((message) => /studioProbeEntity/.test(message)),
      "a new " + kindId + " entry is born invalid: " +
        report.errors.filter((message) => /studioProbeEntity/.test(message)).join(" | ")
    );
  }
});

test("Gameplay data", "Every authored entity resolves to something the arena can field", () => {
  for (const kindId of REGISTRY_IDS) {
    for (const id of Object.keys(CANONICAL_GAMEPLAY[kindId]).sort()) {
      const plan = resolveTestSubject(CANONICAL_GAMEPLAY, kindId, id);
      if (plan.error) {
        // A refusal is a legitimate answer, but it has to be a sentence an
        // author can act on, not a silent nothing.
        assert(plan.error.length > 20, kindId + "/" + id + " refused without explaining why");
        continue;
      }
      assert(
        CANONICAL_GAMEPLAY.units[plan.definitionId],
        kindId + "/" + id + " resolved to a chassis that does not exist"
      );
      assert(plan.reason && plan.reason.length > 10, kindId + "/" + id + " deployed without saying who");
      assert(
        [ARENA_SUBJECT_REF, "durableTarget"].includes(plan.ref),
        kindId + "/" + id + " targets an arena slot that is not rewritable"
      );

      // Deterministic: the same selection always fields the same unit.
      assertEqual(
        JSON.stringify(resolveTestSubject(CANONICAL_GAMEPLAY, kindId, id)),
        JSON.stringify(plan),
        kindId + "/" + id + " resolves differently on a second call"
      );
    }
  }
  assert(resolveTestSubject(CANONICAL_GAMEPLAY, "units", "noSuchUnit").error, "a missing id must refuse");
});

test("Gameplay data", "The arena mission stays a valid mission after a swap", () => {
  const plan = resolveTestSubject(CANONICAL_GAMEPLAY, "operators", "kell");
  assert(!plan.error, plan.error);

  const mission = buildArenaMission(ARENA_FIXTURE, plan);
  assertEqual(mission.id, ARENA_FIXTURE.id, "the arena must keep its id so it replaces the shipped copy");
  const subject = mission.units.find((unit) => unit.ref === ARENA_SUBJECT_REF);
  assertEqual(subject.definitionId, plan.definitionId);

  const report = validateMissionFile(normalizeMission(mission), { sceneIds: allSceneIds() });
  assertEqual(report.ok, true, report.errors.join(" | "));

  // The fixture itself is untouched: the arena is a template, not state.
  assertEqual(
    ARENA_FIXTURE.units.find((unit) => unit.ref === ARENA_SUBJECT_REF).definitionId,
    "assaultMech",
    "buildArenaMission mutated the fixture"
  );

  // Equipment swaps land in the mission, so a part can be measured.
  const partPlan = resolveTestSubject(CANONICAL_GAMEPLAY, "equipment", "longRifle");
  const partMission = buildArenaMission(ARENA_FIXTURE, partPlan);
  const equipped = partMission.units.find((unit) => unit.ref === partPlan.ref);
  assertEqual(equipped.equipment.primaryWeapon, "longRifle");
  assertEqual(
    validateMissionFile(normalizeMission(partMission), { sceneIds: allSceneIds() }).ok,
    true
  );
});

test("Gameplay data", "The Studio reads derived values from the engine, not a copy", () => {
  // §16: there must be exactly one stat calculator. This asserts the preview
  // agrees with the battle for the same chassis and loadout, which is only
  // possible if it is the same code.
  const preview = composeUnitPreview({ definitionId: "assaultMech" });
  assert(!preview.error, preview.error);

  const state = createBattle(deploymentEncounterId(), 11);
  const unitId = state.unitOrder.find((id) => state.units[id].definitionId === "assaultMech");
  assert(unitId, "no assault mech in the deployment encounter");
  state.units[unitId].equipment = { ...preview.equipment };
  const live = calculateUnitStats(state, unitId);

  for (const row of preview.rows) {
    assertEqual(row.total, live[row.stat], "preview disagrees with the engine on " + row.stat);
  }
  assert(preview.rows.length >= 8, "the preview shows almost nothing");
  assert(preview.abilities.includes("scatterShot"), "granted abilities are missing from the preview");

  // Equipment contributions are attributed, not just totalled.
  const withRifle = composeUnitPreview({
    definitionId: "assaultMech",
    equipment: { primaryWeapon: "closeShotgun", armor: "plateArmor" }
  });
  const defense = withRifle.rows.find((row) => row.stat === "defense");
  assert(/Plate/.test(defense.sources), "the armour contribution is not named: " + defense.sources);

  assert(composeUnitPreview({ definitionId: "nothingLikeThis" }).error, "an unknown chassis must refuse");

  // Unsaved data composes through the same pipeline, which is what makes the
  // Studio's derived-values panel follow the number being typed.
  const draft = gameplayDraftFixture();
  draft.units.assaultMech.baseStats.maxHp = 400;
  draft.equipment.plateArmor.modifiers = [{ stat: "maxHp", mode: "flat", value: 50 }];
  const unsaved = composeUnitPreview({ definitionId: "assaultMech", registries: draft });
  const row = unsaved.rows.find((entry) => entry.stat === "maxHp");
  assertEqual(row.base, 400, "the preview ignored the unsaved chassis");
  assertEqual(row.total, 450, "the preview ignored the unsaved equipment");

  // And nothing leaks: the shipped data is unchanged and a real battle never
  // carries an override.
  assertEqual(CONTENT.units.assaultMech.baseStats.maxHp, 130);
  const battle = createBattle(deploymentEncounterId(), 3);
  assertEqual(battle.contentOverride, undefined, "a battle must never carry a content override");
  assertEqual(
    JSON.parse(serializeBattle(battle)).contentOverride,
    undefined,
    "a content override must not serialize"
  );
});

test("Gameplay data", "A draft changes the game only through the load-time overlay", () => {
  // Draft isolation, stated as a property: nothing in the Studio's storage
  // slot can affect a session that did not read it at import. This build did
  // not, so the running content is the shipped content.
  assertEqual(GAMEPLAY_DRAFT_ACTIVE, false, "a gameplay draft is active during the test run");
  assertEqual(CONTENT.units.assaultMech.baseStats.maxHp, CANONICAL_GAMEPLAY.units.assaultMech.baseStats.maxHp);
  assert(GAMEPLAY_DRAFT_STORAGE_KEY.startsWith("statuszero."), "the draft slot must be namespaced");
});


/* ---------------------------------------------------------------
 * ORCHESTRATION HELPERS
 * -------------------------------------------------------------*/

const SYNERGY_ENCOUNTER = "file:fixture-synergy-arena";

function synergyBattle(seed, options) {
  return createBattle(SYNERGY_ENCOUNTER, seed == null ? 11 : seed, {
    autoResolveScenes: true,
    autoResolveReactions: false,
    ...options
  });
}

/** Faction balance for a shared resource, or null. */
function factionResource(state, resourceId, teamId) {
  const team = teamId || "sectionSeven";
  return (state.resources.faction[team] || {})[resourceId] || null;
}

function setFactionResource(state, resourceId, value, teamId) {
  const entry = factionResource(state, resourceId, teamId);
  if (entry) entry.current = value;
}

function resourceDefinitionFor(resourceId) {
  return normalizeResourceDefinition({
    id: resourceId,
    ...REACTION_INDEX.resourceById[resourceId]
  });
}

function applyStatusForTest(state, unitId, statusId) {
  REACTION_ENGINE.applyStatus(state, unitId, [unitId], statusId);
  processAllEvents(state);
}

/** A real push through the engine's own forced-movement path. */
function pushUnit(state, sourceUnitId, targetUnitId, distance) {
  const source = state.units[sourceUnitId];
  EFFECT_HANDLERS.push(state, {
    sourceUnitId,
    targetUnitId,
    abilityId: null,
    sourceTile: { x: source.x, y: source.y },
    effect: { type: "push", distance: distance == null ? 1 : distance }
  });
}

/**
 * Activates a unit for a test, regardless of whose turn the timeline thinks it
 * is. The tests here are about orchestration, not initiative, and making each
 * one wind the clock forward to reach its subject would test the wrong thing.
 */
function activateForTest(state, unitId) {
  state.units[unitId].nextActionTime = state.currentTime;
  for (const otherId of state.unitOrder) {
    if (otherId !== unitId) state.units[otherId].nextActionTime = state.currentTime + 1000;
  }
  return executeCommand(state, { type: "activateUnit", unitId });
}

/* ---------------------------------------------------------------
 * RESOURCES
 * -------------------------------------------------------------*/

test("Orchestration", "Command Points are a faction resource, not a unit's secret", () => {
  const state = synergyBattle(11);
  const cp = factionResource(state, "commandPoints");
  assert(cp, "the squad has a Command Point balance");
  assertEqual(cp.current, 3, "the starting value comes from the authored data");
  assertEqual(cp.max, 4);

  // Every faction gets its own balance. Command Points are the squad's, not
  // the world's, and the other side spending theirs must not touch yours.
  const enemy = factionResource(state, "commandPoints", "loyalist");
  assert(enemy, "the other side has its own balance");
  assertEqual(enemy.current, 3);

  const definition = resourceDefinitionFor("commandPoints");
  assert(spendCombatResource(state, definition, { teamId: "sectionSeven" }, 2));
  assertEqual(factionResource(state, "commandPoints").current, 1);
  assertEqual(factionResource(state, "commandPoints", "loyalist").current, 3, "the other side is untouched");

  for (const unitId of state.unitOrder) {
    assert(
      !(state.units[unitId].resources || {}).commandPoints,
      "no unit may privately hold a faction resource"
    );
  }
});

test("Orchestration", "Resource gain, spend and maxima are deterministic and clamped", () => {
  const state = synergyBattle(12);
  const cp = resourceDefinitionFor("commandPoints");
  const owner = { teamId: "sectionSeven" };

  assertEqual(gainCombatResource(state, cp, owner, 10), 1, "gain stops at the maximum");
  assertEqual(factionResource(state, "commandPoints").current, 4);

  assertEqual(canSpendResource(state, cp, owner, 5).ok, false, "cannot overspend");
  assert(canSpendResource(state, cp, owner, 4).ok);
  spendCombatResource(state, cp, owner, 4);
  assertEqual(factionResource(state, "commandPoints").current, 0);
  assertEqual(spendCombatResource(state, cp, owner, 1), false, "an empty pool stays empty");
  assertEqual(factionResource(state, "commandPoints").current, 0, "and is never negative");

  setCombatResource(state, cp, owner, 99);
  assertEqual(factionResource(state, "commandPoints").current, 4, "set clamps too");
});

test("Orchestration", "A unit resource is not handed to units that never declared it", () => {
  const state = synergyBattle(13);
  const capacity = resourceDefinitionFor("reactionCapacity");
  const kell = unitByRef(state, "kell");
  assertEqual(resourceBalance(state, capacity, { unitId: kell.id }), 1, "capacity is universal");

  const invented = normalizeResourceDefinition({ id: "inventedPool", scope: "unit", max: 5 });
  assertEqual(resourceBalance(state, invented, { unitId: kell.id }), 0);
  assertEqual(canSpendResource(state, invented, { unitId: kell.id }, 1).ok, false);
  assert(!(kell.resources || {}).inventedPool, "checking a cost must not grant the means to pay it");
});

test("Orchestration", "A link-gated resource keeps its points while the link is down", () => {
  const state = linkBattle(14);
  refreshReactionLinks(state);
  const tempo = factionResource(state, "sectionSevenTempo", "player");
  assert(tempo.available, "the link starts active");
  tempo.current = 1;

  const reyes = unitByRef(state, "reyes");
  reyes.alive = false;
  refreshReactionLinks(state);
  assertEqual(factionResource(state, "sectionSevenTempo", "player").available, false, "the gate closed");
  assertEqual(factionResource(state, "sectionSevenTempo", "player").current, 1, "but the points remain");

  reyes.alive = true;
  refreshReactionLinks(state);
  const back = factionResource(state, "sectionSevenTempo", "player");
  assert(back.available, "and the gate reopens");
  assertEqual(back.current, back.max, "refilled, so a flickering link is not a tempo tax");
});

/* ---------------------------------------------------------------
 * REACTION LIFECYCLE
 * -------------------------------------------------------------*/

/**
 * The regression this phase was called for.
 *
 * One unit kills something, an ally's reaction becomes available, the player
 * accepts it, and the battle has to carry on. It used to stop: the reaction
 * ended the activation authoritatively while the presentation layer still
 * believed a unit was selected, and the turn driver refused to advance.
 */
test("Orchestration", "A kill-triggered ally reaction always leaves a valid continuation", () => {
  const state = linkBattle(101, { autoResolveReactions: false });
  const { kell, target } = stageLinkChain(state);

  activateForTest(state, kell.id);
  assertEqual(state.activeUnitId, kell.id);

  // Spend the activation completely, so ending it is the only continuation.
  state.activation.moved = true;
  state.activation.acted = true;
  target.currentHp = 1;
  MISSION_ENGINE.scriptedAttack(state, {
    sourceUnitId: kell.id,
    targetUnitIds: [target.id],
    power: 400,
    formula: "physical"
  });
  processAllEvents(state);

  const model = reactionModel(state);
  assert(model.window, "the ally is offered a reaction");
  assertEqual(model.window.offers[0].reactorRef, "vale");

  resolveReactionChoice(state, model.window.offers[0].id);

  assert(!reactionWindowPending(state), "the queue emptied");
  const next = battleContinuation(state);
  assert(
    ["advance", "active", "finished"].includes(next.kind),
    "the battle must have somewhere to go, got: " + next.kind + " " + (next.reason || "")
  );
  assertEqual(next.kind, "advance", "the activation was spent, so the timeline moves on");
  assert(next.unitId, "and it names who acts next");
});

test("Orchestration", "The continuation is valid whether or not the actor has actions left", () => {
  const withActions = linkBattle(102, { autoResolveReactions: false });
  const staged = stageLinkChain(withActions);
  activateForTest(withActions, staged.kell.id);
  staged.target.currentHp = 1;
  MISSION_ENGINE.scriptedAttack(withActions, {
    sourceUnitId: staged.kell.id,
    targetUnitIds: [staged.target.id],
    power: 400,
    formula: "physical"
  });
  processAllEvents(withActions);
  const window = reactionModel(withActions).window;
  assert(window, "the advance is offered");
  resolveReactionChoice(withActions, window.offers[0].id);
  const stillActive = battleContinuation(withActions);
  assertEqual(stillActive.kind, "active", "the actor has not moved, so it keeps the floor");
  assertEqual(stillActive.unitId, staged.kell.id);

  // Declining is also a valid resolution and must settle the same way.
  const declined = linkBattle(103, { autoResolveReactions: false });
  const other = stageLinkChain(declined);
  activateForTest(declined, other.kell.id);
  declined.activation.moved = true;
  declined.activation.acted = true;
  other.target.currentHp = 1;
  MISSION_ENGINE.scriptedAttack(declined, {
    sourceUnitId: other.kell.id,
    targetUnitIds: [other.target.id],
    power: 400,
    formula: "physical"
  });
  processAllEvents(declined);
  assert(reactionModel(declined).window, "a window opened");
  const before = factionResource(declined, "sectionSevenTempo", "player").current;
  resolveReactionChoice(declined, null);
  assert(!reactionWindowPending(declined));
  assertEqual(battleContinuation(declined).kind, "advance", "declining still advances");
  assertEqual(factionResource(declined, "sectionSevenTempo", "player").current, before, "and costs nothing");
});

test("Orchestration", "An active unit destroyed mid-chain does not strand the battle", () => {
  const state = linkBattle(104, { autoResolveReactions: true });
  const { kell } = stageLinkChain(state);
  activateForTest(state, kell.id);
  assertEqual(state.activeUnitId, kell.id);

  // Nothing in the ordinary activation rules covers this: the unit has not
  // moved, has not acted, and is not going to.
  kell.currentHp = 0;
  queueEvent(state, { type: "unitDefeated", unitId: kell.id, sourceUnitId: null });
  processAllEvents(state);
  settleCommand(state);

  assertEqual(state.activeUnitId, null, "the activation ended with the unit");
  const next = battleContinuation(state);
  assert(next.kind !== "stalled", next.reason || "");
  assert(
    state.battleLog.some(
      (entry) => entry.type === "turnEnded" && entry.data && entry.data.reason === "destroyed"
    ),
    "and said so in the log"
  );
});

test("Orchestration", "The input state machine can never sit on a unit that is not active", () => {
  const state = linkBattle(106, { autoResolveReactions: false });
  const { kell } = stageLinkChain(state);
  activateForTest(state, kell.id);

  // Exactly the shape the softlock had: the UI is showing an activation the
  // simulation has already ended.
  let input = inputReducer(createInputState(), { type: "activationStarted", unitId: kell.id }, state).input;
  assertEqual(input.mode, "unitReady");
  state.activeUnitId = null;
  state.activation = null;

  input = reconcileInputWithBattle(input, state);
  assertEqual(input.mode, "idle", "the UI lets go once nothing is activated");
  assertEqual(input.selectedUnitId, null);

  // And the reverse: an activation the UI has not caught up with.
  const resumed = linkBattle(107, { autoResolveReactions: false });
  const other = stageLinkChain(resumed);
  activateForTest(resumed, other.kell.id);
  const stale = reconcileInputWithBattle(createInputState(), resumed);
  assertEqual(stale.selectedUnitId, other.kell.id, "and picks the active unit back up");
});

/* ---------------------------------------------------------------
 * THE CONTINUATION INVARIANT, AS A PROPERTY
 *
 * The tests above pin the specific shapes the softlock took. These pin the
 * property itself, so a later phase that invents a new way to interrupt an
 * action finds out here rather than at the point somebody notices the battle
 * has quietly stopped asking for input.
 *
 * They are deliberately written against `battleContinuation` and nothing else,
 * because that function is the contract: the UI does what it says, and every
 * softlock this project has had was a moment when it said something the UI
 * could not act on.
 * -------------------------------------------------------------*/

/**
 * The battle always has somewhere to go.
 *
 * Four things have to agree, and every stall so far has been a moment when
 * they did not:
 *
 *   - the continuation is never "stalled";
 *   - a pending reaction window is the *only* reason to report "reaction";
 *   - an "active" unit is one that can genuinely act;
 *   - the activation record names the unit the state calls active.
 */
function assertContinuationIsLive(state, why) {
  const where = why ? " (" + why + ")" : "";
  const next = battleContinuation(state);
  assert(next.kind !== "stalled", "the battle stalled" + where + ": " + (next.reason || ""));
  assertEqual(
    next.kind === "reaction",
    reactionWindowPending(state),
    'only a pending window may report "reaction"' + where
  );
  if (state.activation) {
    assertEqual(
      state.activation.unitId,
      state.activeUnitId,
      "the activation record names the active unit" + where
    );
  }
  if (next.kind === "active") {
    const unit = state.units[next.unitId];
    assert(unit && unit.alive && !unit.dormant, "an active unit must be able to act" + where);
  }
  if (next.kind === "advance") {
    assertEqual(state.activeUnitId, null, "advancing means nothing is activated" + where);
    assert(next.unitId, "advancing must name who acts next" + where);
  }
  return next;
}

test("Continuation", "The invariant holds after every activation of a whole battle", () => {
  const state = linkBattle(120, { autoResolveReactions: true });
  assertContinuationIsLive(state, "before anything happens");

  let activations = 0;
  while (!state.finished && activations < 200) {
    const result = runActivation(state);
    if (!result.unitId) break;
    activations += 1;
    assertContinuationIsLive(state, "after activation " + activations + " (" + result.unitId + ")");
  }
  assert(activations > 3, "the battle actually ran, got " + activations + " activations");
  assert(state.finished || activations >= 200, "and reached an ending");
});

test("Continuation", "A parked window is the only thing that stops the queue, and it always resumes", () => {
  const state = linkBattle(121, { autoResolveReactions: false });
  const { kell, target } = stageLinkChain(state);
  activateForTest(state, kell.id);
  assertContinuationIsLive(state, "activated");

  target.currentHp = 1;
  MISSION_ENGINE.scriptedAttack(state, {
    sourceUnitId: kell.id,
    targetUnitIds: [target.id],
    power: 400,
    formula: "physical"
  });
  processAllEvents(state);

  assert(reactionWindowPending(state), "a choice is pending");
  assertEqual(assertContinuationIsLive(state, "parked").kind, "reaction");
  // The queue is parked, not lost: whatever was mid-drain is still there to
  // finish, which is exactly what the old deadlock threw away.
  assertEqual(state.activeUnitId, kell.id, "and the actor keeps the floor while it waits");

  resolveReactionChoice(state, reactionModel(state).window.offers[0].id);
  assert(!reactionWindowPending(state), "the window closed");
  assertContinuationIsLive(state, "resumed");
});

test("Continuation", "A battle saved inside a reaction window resumes on the same window", () => {
  const state = linkBattle(122, { autoResolveReactions: false });
  const { kell, target } = stageLinkChain(state);
  activateForTest(state, kell.id);
  target.currentHp = 1;
  MISSION_ENGINE.scriptedAttack(state, {
    sourceUnitId: kell.id,
    targetUnitIds: [target.id],
    power: 400,
    formula: "physical"
  });
  processAllEvents(state);
  assert(reactionWindowPending(state), "a choice is pending before the save");

  const restored = deserializeBattle(serializeBattle(state));
  assert(reactionWindowPending(restored), "and is still pending after the reload");
  assertEqual(
    restored.reactions.window.id,
    state.reactions.window.id,
    "the same window, not a freshly discovered one"
  );
  assertEqual(assertContinuationIsLive(restored, "reloaded").kind, "reaction");

  resolveReactionChoice(restored, restored.reactions.window.offers[0].id);
  assertContinuationIsLive(restored, "resolved after a reload");
});

test("Continuation", "Declining every window still runs a battle to an ending", () => {
  const state = linkBattle(123, { autoResolveReactions: false });
  let activations = 0;
  let guard = 0;
  while (!state.finished && activations < 200 && guard < 600) {
    guard += 1;
    if (reactionWindowPending(state)) {
      // The pathological player: says no to everything, forever. The battle
      // still has to end, and every step of it still has to be answerable.
      resolveReactionChoice(state, null);
      assertContinuationIsLive(state, "after declining");
      continue;
    }
    const result = runActivation(state);
    if (!result.unitId) break;
    activations += 1;
    assertContinuationIsLive(state, "after activation " + activations);
  }
  assert(guard < 600, "declining must not livelock the driver");
});

/* ---------------------------------------------------------------
 * THE ACTIVATION-OWNERSHIP INVARIANT
 *
 * Written before anything could reorder a timeline, for the same reason the
 * continuation property above was written before anything could veto an
 * action: the failure mode of a sequencing bug is a unit that acts twice or
 * never acts again, and both are invisible until somebody notices the battle
 * feels wrong three activations later.
 *
 * The invariant is deliberately about *ownership*, not about order:
 *
 *   every unit that can act owns exactly one upcoming activation, and the
 *   set of units owning one does not change when the order does.
 * -------------------------------------------------------------*/

/** Who is scheduled, and where. One entry per unit, by construction. */
function scheduledActivations(state) {
  const seen = new Map();
  for (const entry of timelineCandidates(state)) {
    assert(!seen.has(entry.unitId), "a unit appeared twice on the timeline: " + entry.unitId);
    seen.set(entry.unitId, entry);
  }
  return seen;
}

/**
 * Every actionable unit owns exactly one upcoming activation.
 *
 * @returns the ordered unit ids, so a caller can compare sequences.
 */
function assertOwnsOneActivationEach(state, why) {
  const where = why ? " (" + why + ")" : "";
  const scheduled = scheduledActivations(state);
  for (const unitId of state.unitOrder) {
    const unit = state.units[unitId];
    const actionable = unit.alive && !unit.dormant;
    assertEqual(
      scheduled.has(unitId),
      actionable,
      "an actionable unit owns exactly one activation and nobody else owns any" + where + ": " + unitId
    );
  }
  const ordered = [...scheduled.values()].sort(compareTimelineEntries);
  return ordered.map((entry) => entry.unitId);
}

test("Sequencing", "Every actionable unit owns exactly one upcoming activation", () => {
  const state = linkBattle(130, { autoResolveReactions: true });
  assertOwnsOneActivationEach(state, "at the start");

  let activations = 0;
  while (!state.finished && activations < 120) {
    const result = runActivation(state);
    if (!result.unitId) break;
    activations += 1;
    assertOwnsOneActivationEach(state, "after activation " + activations);
  }
  assert(activations > 3, "the battle ran, got " + activations);
});

test("Sequencing", "Activation order is a pure function of the timeline, not of iteration order", () => {
  const state = linkBattle(131);
  const first = assertOwnsOneActivationEach(state, "as built");

  // The same battle, with the unit map rebuilt in reverse insertion order. If
  // ordering depended on object key order anywhere, this would differ — which
  // is the property a reorder layer is about to start leaning on hard.
  const shuffled = deserializeBattle(serializeBattle(state));
  const reversed = {};
  for (const id of shuffled.unitOrder.slice().reverse()) reversed[id] = shuffled.units[id];
  shuffled.units = reversed;
  shuffled.unitOrder = shuffled.unitOrder.slice().reverse();

  assertEqual(
    assertOwnsOneActivationEach(shuffled, "rebuilt backwards").join(","),
    first.join(","),
    "the order must not depend on how the units happen to be stored"
  );
});

test("Sequencing", "Units sharing a timestamp still order deterministically", () => {
  const state = linkBattle(132);
  // The case a naive reorder gets wrong: identical times mean the comparator
  // falls through to its tie-breaks, and any scheme that expresses order
  // *only* through timestamps cannot separate these two at all.
  for (const unitId of state.unitOrder) state.units[unitId].nextActionTime = 500;
  const once = assertOwnsOneActivationEach(state, "all tied");
  const twice = assertOwnsOneActivationEach(state, "all tied, again");
  assertEqual(once.join(","), twice.join(","), "a tie is not a coin flip");

  const restored = deserializeBattle(serializeBattle(state));
  assertEqual(
    assertOwnsOneActivationEach(restored, "reloaded").join(","),
    once.join(","),
    "and it survives a save"
  );
});

