/* =========================================================================
 * PHASE 2.2 — BATTLEFIELD-FIRST HUD
 * =======================================================================*/

const DESKTOP_VIEWPORTS = [
  { width: 1920, height: 1080 },
  { width: 1600, height: 900 },
  { width: 1440, height: 900 },
  { width: 1280, height: 800 }
];

function hudInput(overrides) {
  // Most panel tests describe an already-open menu; the default battlefield
  // state keeps it closed.
  return createInputState({ mode: "unitReady", commandMenuOpen: true, ...(overrides || {}) });
}

test("UI typography", "Local pixel font paths are stable and self-contained", () => {
  assertEqual(GAME_FONT_ASSETS.body, "/assets/fonts/pixel-operator.ttf");
  assertEqual(GAME_FONT_ASSETS.bodyBold, "/assets/fonts/pixel-operator-bold.ttf");
  assertEqual(GAME_FONT_ASSETS.display, "/assets/fonts/silkscreen-bold.ttf");
});

test("UI layout", "Story portrait borders meet dialogue borders at every UI scale", () => {
  for (const option of UI_SCALE_OPTIONS) {
    const viewport = {
      width: Math.round(UI_DESIGN_RESOLUTION.width / option.factor),
      height: Math.round(UI_DESIGN_RESOLUTION.height / option.factor)
    };
    const layout = calculateCinematicDialogueLayout(viewport, "story");
    assertEqual(
      layout.portraitLeft + layout.portraitWidth,
      layout.dialogueLeft,
      "Portrait and dialogue must share one exact edge at " + option.label
    );
    assert(layout.dialogueWidth >= 800, "Dialogue is too narrow at " + option.label);
    assert(layout.portraitLeft >= layout.safeX, "Portrait left safe area failed at " + option.label);
    assert(layout.dialogueLeft + layout.dialogueWidth + layout.dialogueRight <= layout.width + 1);
    assert(layout.height - layout.bottom - layout.portraitHeight >= 0, "Portrait leaves viewport at " + option.label);
  }
});

test("UI layout", "Choice and combat dialogue panels remain inside the logical canvas", () => {
  for (const option of UI_SCALE_OPTIONS) {
    const viewport = {
      width: Math.round(UI_DESIGN_RESOLUTION.width / option.factor),
      height: Math.round(UI_DESIGN_RESOLUTION.height / option.factor)
    };
    const story = calculateCinematicDialogueLayout(viewport, "story");
    const combat = calculateCinematicDialogueLayout(viewport, "combat");
    assert(story.choiceRight + story.choiceWidth <= story.width, "Choice panel width failed at " + option.label);
    assert(story.choiceTop >= 0 && story.choiceTop < story.height, "Choice panel top failed at " + option.label);
    assert(combat.dialogueWidth >= 800, "Combat dialogue is too narrow at " + option.label);
    assert(combat.portraitLeft + combat.portraitWidth === combat.dialogueLeft);
  }
});

test("HUD layout", "The battle viewport never needs page scrolling on desktop", () => {
  for (const viewport of DESKTOP_VIEWPORTS) {
    const layout = calculateBattlefieldLayout({
      viewportWidth: viewport.width,
      viewportHeight: viewport.height
    });
    assert(
      layout.fitsWithoutScrolling,
      "Board must fit at " + viewport.width + "x" + viewport.height
    );
    assert(
      layout.boardHeight + HUD_LAYOUT.reserved.top + HUD_LAYOUT.reserved.bottom <= viewport.height,
      "Board plus chrome must fit the viewport height"
    );
    assert(layout.tileSize >= HUD_LAYOUT.minTileSize);
    assert(layout.tileSize <= HUD_LAYOUT.maxTileSize);
  }
});

test("HUD layout", "The battlefield stage dominates the usable viewport", () => {
  for (const viewport of DESKTOP_VIEWPORTS) {
    const layout = calculateBattlefieldLayout({
      viewportWidth: viewport.width,
      viewportHeight: viewport.height
    });
    assert(
      layout.stageShare >= 0.7 && layout.stageShare <= 0.9,
      "Stage share out of range at " + viewport.width + ": " + layout.stageShare
    );
    assert(
      layout.boardHeight / layout.availableHeight >= 0.95,
      "The board must fill the constraining axis"
    );
  }
});

test("HUD layout", "Tiles stay square and the whole map is preserved", () => {
  const layout = calculateBattlefieldLayout({
    viewportWidth: 1440,
    viewportHeight: 900,
    mapWidth: 8,
    mapHeight: 8
  });
  assertEqual(layout.boardWidth, layout.tileSize * 8);
  assertEqual(layout.boardHeight, layout.tileSize * 8);
  const tall = calculateBattlefieldLayout({ viewportWidth: 1440, viewportHeight: 1600 });
  assertEqual(tall.boardWidth, tall.boardHeight, "Tiles remain square on tall viewports");
  const tiny = calculateBattlefieldLayout({ viewportWidth: 420, viewportHeight: 620 });
  assertEqual(tiny.compact, true, "Narrow viewports drop the side rail");
  assert(tiny.tileSize >= HUD_LAYOUT.minTileSize);
});

test("HUD layout", "A floating panel anchors beside the unit without covering it", () => {
  const layout = calculateBattlefieldLayout({ viewportWidth: 1440, viewportHeight: 900 });
  const position = calculateFloatingPanelPosition({
    anchor: { x: 1, y: 2 },
    tileSize: layout.tileSize,
    board: { left: layout.boardLeft, top: layout.boardTop },
    viewport: { width: 1440, height: 900 },
    panelWidth: 240,
    panelHeight: 220
  });
  assertEqual(position.placement, "right");
  assertEqual(position.coversAnchor, false);
  assertEqual(position.withinViewport, true);
  assert(position.left > layout.boardLeft + layout.tileSize);
});

test("HUD layout", "A floating panel flips at the right and bottom edges", () => {
  const layout = calculateBattlefieldLayout({ viewportWidth: 1280, viewportHeight: 800 });
  const shared = {
    tileSize: layout.tileSize,
    board: { left: layout.boardLeft, top: layout.boardTop },
    viewport: { width: 1280, height: 800 },
    bounds: layout.stageBounds,
    panelWidth: 260,
    panelHeight: 240
  };
  const rightEdge = calculateFloatingPanelPosition({ ...shared, anchor: { x: 7, y: 1 } });
  assertEqual(rightEdge.withinViewport, true);
  assertEqual(rightEdge.coversAnchor, false);
  assert(["left", "right"].includes(rightEdge.placement));

  const bottomEdge = calculateFloatingPanelPosition({ ...shared, anchor: { x: 1, y: 7 } });
  assertEqual(bottomEdge.flippedY, true);
  assertEqual(bottomEdge.withinViewport, true);
  assertEqual(bottomEdge.coversAnchor, false);
});

test("HUD layout", "A floating panel always stays inside the viewport", () => {
  for (const viewport of DESKTOP_VIEWPORTS.concat([{ width: 900, height: 620 }])) {
    const layout = calculateBattlefieldLayout({
      viewportWidth: viewport.width,
      viewportHeight: viewport.height
    });
    for (let y = 0; y < 8; y += 1) {
      for (let x = 0; x < 8; x += 1) {
        const position = calculateFloatingPanelPosition({
          anchor: { x, y },
          tileSize: layout.tileSize,
          board: { left: layout.boardLeft, top: layout.boardTop },
          viewport,
          bounds: layout.stageBounds,
          panelWidth: 260,
          panelHeight: 240
        });
        assert(
          position.withinViewport,
          "Panel escaped the viewport at " + x + "," + y + " on " + viewport.width
        );
        assert(position.left >= 0 && position.top >= 0);
      }
    }
  }
});

