test("Context panel", "HUD helpers never re-implement engine rules", () => {
  const helpers = {
    calculateBattlefieldLayout,
    calculateFloatingPanelPosition,
    createContextCommandModel,
    createHoverForecastModel,
    createBattleHudModel,
    createUnitCardModel
  };
  const forbidden = [/FORMULAS\./, /Math\.pow\(/, /EFFECT_HANDLERS/, /randomFloat\(/, /rollChance\(/];
  const hits = [];
  for (const name of Object.keys(helpers)) {
    const source = helpers[name].toString();
    for (const pattern of forbidden) {
      if (pattern.test(source)) hits.push(name + " -> " + pattern.source);
    }
  }
  assertEqual(hits.length, 0, hits.join(", "));
  const ids = contentIdList();
  const idHits = [];
  for (const name of Object.keys(helpers)) {
    const source = helpers[name].toString();
    for (const id of ids) {
      if (source.includes('"' + id + '"')) idHits.push(name + " -> " + id);
    }
  }
  assertEqual(idHits.length, 0, idHits.join(", "));
});


/* =========================================================================
 * PHASE 3 — EFFECT FRAMEWORK, CONTEXTUAL SELECTION AND DANGER ZONES
 * =======================================================================*/

const LAB = "effectLab";

function labBattle(seed) {
  const state = createBattle(LAB, seed == null ? 11 : seed);
  return state;
}

/**
 * Isolates two units on the lab map, keeps one opposing unit alive in a far
 * corner so the objective does not resolve, and activates the first unit.
 */
function labPair(unitA, unitB, positions, seed) {
  const state = labBattle(seed);
  const keep = [unitA, unitB];
  const teams = new Set(keep.map((id) => state.units[id].teamId));
  let filler = null;
  if (teams.size === 1) {
    filler = state.unitOrder.find(
      (id) => !keep.includes(id) && state.units[id].teamId !== [...teams][0]
    );
    keep.push(filler);
  }
  isolate(state, keep);
  place(state, unitA, positions[0].x, positions[0].y);
  place(state, unitB, positions[1].x, positions[1].y);
  if (filler) {
    place(state, filler, 7, 0);
    state.units[filler].nextActionTime = 100000;
  }
  activate(state, unitA);
  return state;
}

function useAbility(state, unitId, abilityId, target) {
  return executeCommand(state, { type: "useAbility", unitId, abilityId, target });
}

