  assert(panels.secondaryBackgroundOpacity >= 0.85 && panels.secondaryBackgroundOpacity <= 0.95);
  const primary = createPanelStyle("primary");
  assert(primary.backgroundColor.includes(String(panels.primaryBackgroundOpacity)));
  assert(primary.backdropFilter.includes(String(panels.backdropBlurPx)));
  assert(primary.boxShadow.includes(String(panels.shadowStrength)));
  const secondary = createPanelStyle("secondary");
