  assertEqual(state.units.u2.alive, true);
  const maxHp = calculateUnitStats(state, "u2").maxHp;
  assertEqual(state.units.u2.currentHp, Math.round(maxHp * 0.5));
  assert(state.units.u2.nextActionTime > state.currentTime);

  const transform = labPair("u1", "u2", [{ x: 3, y: 3 }, { x: 3, y: 4 }]);
