  assertEqual(transform.units.u2.definitionId, "testSkeleton");
  assertEqual(calculateUnitStats(transform, "u2").maxHp, CONTENT.units.testSkeleton.baseStats.maxHp);
  assert(calculateUnitStats(transform, "u2").maxHp !== originalMax);
