test("Effects", "Conditional effects pick the branch that matches the state", () => {
  const healthy = labPair("u1", "u3", [{ x: 3, y: 3 }, { x: 3, y: 4 }]);
  const healthyPreview = createForecast(healthy, "u1", "execution", { x: 3, y: 4 });
  const wounded = labPair("u1", "u3", [{ x: 3, y: 3 }, { x: 3, y: 4 }]);
  wounded.units.u3.currentHp = Math.round(calculateUnitStats(wounded, "u3").maxHp * 0.2);
  const woundedPreview = createForecast(wounded, "u1", "execution", { x: 3, y: 4 });
  assert(
    woundedPreview.headline.value > healthyPreview.headline.value,
    "The wounded branch must hit harder: " +
      woundedPreview.headline.value +
      " vs " +
      healthyPreview.headline.value
  );
  const hpBefore = wounded.units.u3.currentHp;
  useAbility(wounded, "u1", "execution", { unitId: "u3" });
  const dealt = hpBefore - wounded.units.u3.currentHp;
  assert(
    dealt === Math.min(hpBefore, woundedPreview.headline.value) ||
      wounded.battleLog.some((e) => e.type === "attackMissed"),
    "Resolved damage should match the chosen branch: " + dealt
  );
});

test("Effects", "Chance conditions are deterministic and previews stay pure", () => {
  const results = [0, 1].map(() => {
    const state = labPair("u1", "u3", [{ x: 3, y: 3 }, { x: 3, y: 4 }], 99);
    const before = state.randomState.counter;
    const context = {
      state,
      sourceUnitId: "u1",
      targetUnitId: "u3",
      targetTile: { x: 3, y: 4 },
      effect: {}
    };
    const pure = evaluateConditionsPure(context, { mode: "all", entries: [{ type: "chance", value: 0.5 }] });
    assertEqual(state.randomState.counter, before, "Preview must not roll");
    assertEqual(pure.deterministic, false);
    assertEqual(pure.probability, 0.5);
    const rolled = evaluateConditions(context, {
      mode: "all",
      entries: [{ type: "chance", value: 0.5 }]
    });
    assert(state.randomState.counter > before, "Resolution consumes the seeded stream");
    return rolled;
  });
  assertEqual(results[0], results[1], "Same seed must produce the same roll");
});

test("Effects", "Repeat effects resolve the configured count and respect the limit", () => {
  const state = labPair("u1", "u3", [{ x: 3, y: 3 }, { x: 3, y: 4 }]);
  const before = state.randomState.counter;
  const forecast = createForecast(state, "u1", "tripleShot", { x: 3, y: 4 });
  assertEqual(state.randomState.counter, before, "Multi-hit previews consume no RNG");
  assertEqual(forecast.outcomes[0].hits, 3);
  assertEqual(forecast.headline.value, forecast.outcomes[0].amount * 3);
  const hitsLine = forecast.lines.find((line) => line.kind === "multiHit");
  assert(hitsLine && hitsLine.value.startsWith("3 x"), JSON.stringify(hitsLine));

  useAbility(state, "u1", "tripleShot", { unitId: "u3" });
  const events = state.battleLog.filter(
    (entry) => entry.type === "damageResolved" || entry.type === "attackMissed"
  );
  assertEqual(events.length, 3, "Three separate hits resolve");

  const limited = labPair("u1", "u3", [{ x: 3, y: 3 }, { x: 3, y: 4 }]);
  resolveEffects(limited, {
    sourceUnitId: "u1",
    targetUnitIds: ["u3"],
    effects: [
      {
        type: "repeatEffect",
        count: GAME_CONFIG.limits.maxRepeatedEffects + 5,
        effects: [{ type: "damage", formula: "physical", power: 5, canMiss: false }]
      }
    ]
  });
  processAllEvents(limited);
  const resolved = limited.battleLog.filter((entry) => entry.type === "damageResolved").length;
  assert(resolved <= GAME_CONFIG.limits.maxRepeatedEffects, "Repeat count is clamped");
  assert(limited.errors.some((error) => error.includes("Repeat count")));
});

