test("Effects", "The effect chain depth guard stops runaway recursion safely", () => {
  const state = labPair("u1", "u3", [{ x: 3, y: 3 }, { x: 3, y: 4 }]);
  let nested = { type: "damage", formula: "physical", power: 5, canMiss: false };
  for (let depth = 0; depth < GAME_CONFIG.limits.maxEffectChainDepth + 4; depth += 1) {
    nested = { type: "repeatEffect", count: 1, effects: [nested] };
  }
  resolveEffects(state, { sourceUnitId: "u1", targetUnitIds: ["u3"], effects: [nested] });
  processAllEvents(state);
  assert(state.errors.some((error) => error.includes("chain depth")), state.errors.join(" | "));
  const guarded = validateBattleState(state);
  assert(
    guarded.errors.every((error) => state.errors.includes(error)),
    "The guard must not corrupt the battle: " + guarded.errors.join(" | ")
  );
  assertEqual(JSON.stringify(JSON.parse(JSON.stringify(state))), JSON.stringify(state));
});

