test("Targeting shapes", "Every registered shape selects the expected tiles", () => {
  const state = labBattle();
  const center = { x: 4, y: 4 };
  const line = tilesInArea(state, center, { shape: "line", length: 2 }, { origin: { x: 4, y: 6 } });
  assertEqual(line.length, 3);
  assert(line.every((tile) => tile.x === 4));
  assert(line.some((tile) => tile.y === 2), JSON.stringify(line));

  const cross = tilesInArea(state, center, { shape: "cross", radius: 2 });
  assertEqual(cross.length, 9);
  assert(cross.every((tile) => tile.x === center.x || tile.y === center.y));

  const square = tilesInArea(state, center, { shape: "square", radius: 1 });
  assertEqual(square.length, 9);

  const ring = tilesInArea(state, center, { shape: "ring", radius: 2, innerRadius: 2 });
  assert(ring.every((tile) => Math.abs(tile.x - 4) + Math.abs(tile.y - 4) === 2));
  assertEqual(ring.length, 8);

  const cone = tilesInArea(state, center, { shape: "cone", radius: 2 }, { origin: { x: 4, y: 6 } });
  assert(cone.length > 3, "A cone widens with distance");
  assert(cone.every((tile) => tile.y <= 4));

  const path = tilesInArea(state, { x: 4, y: 1 }, { shape: "path" }, { origin: { x: 4, y: 4 } });
  assertEqual(path.length, 3);
  assertEqual(path[path.length - 1].y, 1);

  const aura = tilesInArea(state, { x: 7, y: 7 }, { shape: "selfAura", radius: 1 }, {
    origin: { x: 4, y: 4 }
  });
  assert(aura.some((tile) => tile.x === 4 && tile.y === 4), "Self aura centres on the source");
  assertEqual(aura.length, 5);

  for (const shape of Object.keys(AREA_SHAPES)) {
    const tiles = tilesInArea(state, center, { shape, radius: 1, length: 1 }, {
      origin: { x: 4, y: 6 }
    });
    assert(tiles.length > 0, shape + " produced no tiles");
  }
});

test("Targeting shapes", "Target filters reject invalid units and match validation", () => {
  const state = labPair("u1", "u2", [{ x: 3, y: 3 }, { x: 3, y: 4 }]);
  state.units.u2.currentHp = 10;
  for (const entry of enumerateValidAbilityTargets(state, "u1", "guardAura")) {
    const validation = validateCommand(state, {
      type: "useAbility",
      unitId: "u1",
      abilityId: "guardAura",
      target: { x: entry.x, y: entry.y }
    });
    assert(validation.valid, "Enumerated target rejected: " + validation.errors.join(" "));
  }

  state.units.u1.currentHp = calculateUnitStats(state, "u1").maxHp;
  const targeting = evaluateTargeting(state, "u1", "guardAura", { x: 3, y: 3 });
  assert(targeting.targetUnitIds.includes("u2"), "The wounded ally passes the filter");
  state.units.u2.currentHp = calculateUnitStats(state, "u2").maxHp;
  const healthy = evaluateTargeting(state, "u1", "guardAura", { x: 3, y: 3 });
  assert(
    !healthy.targetUnitIds.includes("u2"),
    "A full-health ally is filtered out: " + healthy.targetUnitIds.join(",")
  );

  const filterHandlers = Object.keys(TARGET_FILTER_HANDLERS);
  assert(filterHandlers.length >= 11, "Expected the documented filter set");
  state.units.u2.currentHp = 10;
  const context = { unit: state.units.u2, sourceUnitId: "u1", abilityId: "guardAura" };
  assertEqual(passesTargetFilters(state, [{ type: "notSummoned" }], context), true);
  assertEqual(passesTargetFilters(state, [{ type: "summoned" }], context), false);
  assertEqual(passesTargetFilters(state, [{ type: "excludeSource" }], context), true);
  assertEqual(passesTargetFilters(state, [{ type: "hpBelowPercent", value: 50 }], context), true);
});

