test("Effects", "The AI uses non-damage abilities without stalling", () => {
  let usedSupport = 0;
  for (let seed = 1; seed <= 12; seed += 1) {
    const state = createBattle(LAB, seed);
    const outcome = runBattle(state, 400);
    assertEqual(outcome.hitCap, false, "Seed " + seed + " hit the activation cap");
    assert(!state.activeUnitId || state.finished, "An activation was left open");
    const supportUse = state.battleLog.filter(
      (entry) =>
        entry.type === "shieldApplied" ||
        entry.type === "statModifierApplied" ||
        entry.type === "unitSpawned" ||
        entry.type === "terrainCreated" ||
        entry.type === "unitForcedMove"
    ).length;
    if (supportUse > 0) usedSupport += 1;
  }
  assert(usedSupport > 0, "The AI should sometimes choose non-damage abilities");
});


/* =========================================================================
 * PHASE 3.1 — ELEVATION, PROJECTION AND CAMERA
 * =======================================================================*/

const ELEVATION_ENCOUNTER = "elevationTrial";

function elevationBattle(seed) {
  return createBattle(ELEVATION_ENCOUNTER, seed == null ? 5 : seed);
}

/** Isolates one unit on the elevation map at a chosen tile. */
function elevationSolo(unitId, x, y, seed) {
  const state = elevationBattle(seed);
  const keep = [unitId];
  const foe = state.unitOrder.find(
    (id) => state.units[id].teamId !== state.units[unitId].teamId
  );
  if (state.units[unitId].teamId !== state.units[foe].teamId) keep.push(foe);
  isolate(state, keep);
  place(state, unitId, x, y);
  place(state, foe, 7, 7);
  state.units[foe].nextActionTime = 100000;
  activate(state, unitId);
  return state;
}

