test("Elevation", "A default unit climbs one level but not two", () => {
  const state = elevationSolo("u1", 3, 4);
  const stats = calculateUnitStats(state, "u1");
  assertEqual(stats.maxClimb, 1);
  assertEqual(stats.maxDrop, 1);

  const oneUp = evaluateTraversalStep(state, "u1", { x: 3, y: 4 }, { x: 3, y: 3 });
  assertEqual(oneUp.fromElevation, 1);
  assertEqual(oneUp.toElevation, 2);
  assertEqual(oneUp.elevationDelta, 1);
  assertEqual(oneUp.direction, "up");
  assertEqual(oneUp.valid, true);
  assertEqual(oneUp.totalCost, 1);

  const ground = elevationSolo("u1", 3, 5);
  const twoUp = evaluateTraversalStep(ground, "u1", { x: 3, y: 5 }, { x: 3, y: 4 });
  assertEqual(twoUp.valid, true, "Ground to ramp is a legal single climb");
  const cliff = evaluateTraversalStep(ground, "u1", { x: 1, y: 0 }, { x: 1, y: 1 });
  assertEqual(cliff.valid, true, "Flat ground stays legal");
  const impossible = evaluateTraversalStep(ground, "u1", { x: 3, y: 6 }, { x: 3, y: 5 });
  assertEqual(impossible.valid, true);
  const straightUp = evaluateTraversalStep(ground, "u1", { x: 4, y: 0 }, { x: 4, y: 1 });
  assertEqual(straightUp.valid, false, "A two-level cliff cannot be climbed");
  assertEqual(straightUp.elevationDelta, 2);
  assertEqual(straightUp.totalCost, Infinity);
  assert(straightUp.errors[0].includes("Requires climb 2"), straightUp.errors.join(" "));
});

test("Elevation", "A default unit drops one level but not three", () => {
  const state = elevationSolo("u1", 4, 1);
  const down = evaluateTraversalStep(state, "u1", { x: 4, y: 1 }, { x: 4, y: 0 });
  assertEqual(down.direction, "down");
  assertEqual(down.elevationDelta, -2);
  assertEqual(down.valid, false);
  assert(down.errors[0].includes("Requires drop 2"), down.errors.join(" "));

  const ramp = elevationSolo("u1", 3, 4);
  const stepDown = evaluateTraversalStep(ramp, "u1", { x: 3, y: 4 }, { x: 3, y: 5 });
  assertEqual(stepDown.elevationDelta, -1);
  assertEqual(stepDown.valid, true);

  const ledge = elevationSolo("u1", 6, 6);
  const bigDrop = evaluateTraversalStep(ledge, "u1", { x: 6, y: 6 }, { x: 6, y: 5 });
  assertEqual(bigDrop.elevationDelta, -3);
  assertEqual(bigDrop.valid, false);
});

test("Elevation", "A maxClimb modifier unlocks a cliff and expires cleanly", () => {
  const state = elevationSolo("u1", 4, 0);
  const definitionSnapshot = JSON.stringify(CONTENT.units.swiftblade);
  assertEqual(evaluateTraversalStep(state, "u1", { x: 4, y: 0 }, { x: 4, y: 1 }).valid, false);
  assert(!computeMovementRange(state, "u1").has(tileKey(4, 1)));

  resolveEffects(state, {
    sourceUnitId: "u1",
    targetUnitIds: ["u1"],
    effects: [
      {
        type: "modifyStat",
        stat: "maxClimb",
        mode: "flat",
        value: 2,
        duration: { type: "targetActivations", amount: 2 }
      }
    ]
  });
  processAllEvents(state);
  assertEqual(calculateUnitStats(state, "u1").maxClimb, 3);
  assertEqual(evaluateTraversalStep(state, "u1", { x: 4, y: 0 }, { x: 4, y: 1 }).valid, true);
  assert(computeMovementRange(state, "u1").has(tileKey(4, 1)), "The cliff is now reachable");

  executeCommand(state, { type: "endTurn", unitId: "u1" });
  for (let i = 0; i < 3; i += 1) {
    state.units.u1.nextActionTime = -1;
    activate(state, "u1");
    executeCommand(state, { type: "wait", unitId: "u1" });
  }
  assertEqual(state.units.u1.modifiers.length, 0);
  assertEqual(calculateUnitStats(state, "u1").maxClimb, 1);
  assertEqual(evaluateTraversalStep(state, "u1", { x: 4, y: 0 }, { x: 4, y: 1 }).valid, false);
  assertEqual(JSON.stringify(CONTENT.units.swiftblade), definitionSnapshot, "Definitions untouched");

  const status = elevationSolo("u1", 4, 0);
  status.units.u1.statuses.push({ statusId: "surefooted", remaining: 2, sourceUnitId: "u1" });
  assertEqual(calculateUnitStats(status, "u1").maxClimb, 3, "Statuses can grant traversal too");
});

test("Elevation", "The pathfinder routes around a cliff and gives up when it must", () => {
  const state = elevationSolo("u1", 3, 5);
  state.units.u1.modifiers.push({
    id: "test-move",
    stat: "movement",
    mode: "override",
    value: 8,
    duration: null,
    remainingDuration: null
  });
  const path = findPath(state, "u1", { x: 4, y: 3 });
  assert(path, "A legal ramp route should exist");
  assertEqual(path[0].x, 3);
  assertEqual(path[0].y, 5);
  assertEqual(path[path.length - 1].x, 4);
  assertEqual(path[path.length - 1].y, 3);
  for (let i = 1; i < path.length; i += 1) {
    const step = evaluateTraversalStep(state, "u1", path[i - 1], path[i]);
    assert(step.valid, "Every step must be legal: " + step.errors.join(" "));
    assert(Math.abs(step.elevationDelta) <= 1, "The route never exceeds the climb limit");
  }
  const validation = validatePath(state, "u1", path);
  assert(validation.valid, validation.errors.join(" "));
  assertEqual(validation.cost, pathCost(state, "u1", path), "pathCost and validatePath agree");

  const marooned = elevationSolo("u1", 7, 6);
  marooned.units.u1.modifiers.push({
    id: "test-move-2",
    stat: "movement",
    mode: "override",
    value: 8,
    duration: null,
    remainingDuration: null
  });
  place(marooned, "u1", 6, 6);
  assertEqual(findPath(marooned, "u1", { x: 0, y: 0 }), null, "No legal route off the pillar");
  assertEqual(computeMovementRange(marooned, "u1").size, 1, "Only its own tile is reachable");
});

test("Elevation", "Move commands reject an excessive climb", () => {
  const state = elevationSolo("u1", 4, 0);
  const command = {
    type: "move",
    unitId: "u1",
    path: [{ x: 4, y: 0 }, { x: 4, y: 1 }]
  };
  const validation = validateCommand(state, command);
  assertEqual(validation.valid, false);
  assert(validation.errors.join(" ").includes("climb"), validation.errors.join(" "));
  const result = executeCommand(state, command);
  assertEqual(result.ok, false);
  assertEqual(state.units.u1.y, 0, "The unit never moved");
});

test("Elevation", "AI, danger zones and combined plans all respect elevation", () => {
  const state = elevationBattle(3);
  isolate(state, ["u1", "u3"]);
  place(state, "u1", 4, 0);
  place(state, "u3", 4, 1);
  activate(state, "u3");
  const aiCommands = chooseAiCommands(state, "u3");
  for (const command of aiCommands) {
    if (command.type !== "move") continue;
    for (let i = 1; i < command.path.length; i += 1) {
      const step = evaluateTraversalStep(state, "u3", command.path[i - 1], command.path[i]);
      assert(step.valid, "The AI planned an illegal step: " + step.errors.join(" "));
    }
  }

  const threat = calculateUnitThreatZone(state, "u3");
  const cliffOrigins = threat.attackOrigins.filter(
    (origin) => (elevationAt(getMap(state), origin.x, origin.y) || 0) === 0
  );
  assertEqual(cliffOrigins.length, 0, "A stranded unit cannot threaten from the low ground");
  for (const origin of threat.attackOrigins) {
    if (origin.x === state.units.u3.x && origin.y === state.units.u3.y) continue;
    assert(findPath(state, "u3", origin), "Every threat origin must be walkable to");
  }

  place(state, "u1", 3, 5);
  const options = createContextualTargetOptions(state, "u3", "u1");
  for (const option of options) {
    if (!option.requiresMovement) continue;
    for (let i = 1; i < option.suggestedPath.length; i += 1) {
      const step = evaluateTraversalStep(
        state,
        "u3",
        option.suggestedPath[i - 1],
        option.suggestedPath[i]
      );
      assert(step.valid, "A suggested plan used an illegal climb");
    }
  }
});

test("Elevation", "Forced movement and teleport follow their configured policies", () => {
  // Pushing east from (2,1) runs straight into the two-level cliff at (3,1).
  const push = elevationSolo("u1", 1, 1);
  place(push, "u3", 2, 1);
  push.units.u3.alive = true;
  push.units.u3.currentHp = 50;
  resolveEffects(push, {
    sourceUnitId: "u1",
    targetUnitIds: ["u3"],
    effects: [{ type: "push", distance: 2 }]
  });
  processAllEvents(push);
  assertEqual(push.units.u3.x, 2, "The push stops when the next step is an illegal climb");

  const ignoring = elevationSolo("u1", 1, 1);
  place(ignoring, "u3", 2, 1);
  ignoring.units.u3.alive = true;
  ignoring.units.u3.currentHp = 50;
  resolveEffects(ignoring, {
    sourceUnitId: "u1",
    targetUnitIds: ["u3"],
    effects: [{ type: "push", distance: 2, ignoresElevation: true }]
  });
  processAllEvents(ignoring);
  assertEqual(ignoring.units.u3.x, 4, "An elevation-ignoring push travels the full distance");

  const teleport = elevationSolo("u1", 3, 5);
  resolveEffects(teleport, {
    sourceUnitId: "u1",
    targetUnitIds: ["u1"],
    targetTile: { x: 4, y: 1 },
    effects: [{ type: "teleport", applyTo: "source" }]
  });
  processAllEvents(teleport);
  assertEqual(teleport.units.u1.x, 4);
  assertEqual(teleport.units.u1.y, 1, "Teleport ignores intermediate height");
  assertEqual(elevationAt(getMap(teleport), 4, 1), 2);
});

test("Elevation", "Elevated battles stay valid, serializable and deterministic", () => {
  const state = elevationBattle(9);
  const outcome = runBattle(state, 400);
  assertEqual(outcome.hitCap, false, "The elevated fixture battle must resolve");
  assertEqual(outcome.finished, true);
  const validation = validateBattleState(state);
  assert(
    validation.errors.every((error) => state.errors.includes(error)),
    validation.errors.join(" | ")
  );
  assertEqual(JSON.stringify(JSON.parse(JSON.stringify(state))), JSON.stringify(state));
  const repeat = elevationBattle(9);
  const second = runBattle(repeat, 400);
  assertEqual(outcome.winner, second.winner);
  assertEqual(outcome.activations, second.activations);
  assertEqual(
    state.battleLog.map((entry) => entry.text).join("|"),
    repeat.battleLog.map((entry) => entry.text).join("|")
  );

  const flatReplay = deterministicReplayCheck(GAME_CONFIG.defaults.seed);
  assert(flatReplay.identical, "The playable encounter stays deterministic");
  assertEqual(flatReplay.winner, "player");
});

/* --- Projection -------------------------------------------------------- */

test("Projection", "Tiles project deterministically along the map axes", () => {
  const projection = battlefieldProjection();
  const origin = projectTileToWorld({ x: 0, y: 0, elevation: 0 }, projection);
  assertEqual(origin.x, 0);
  assertEqual(origin.y, 0);

  const east = projectTileToWorld({ x: 1, y: 0, elevation: 0 }, projection);
  assert(east.x > origin.x && east.y > origin.y, "Increasing x runs down-right");
  const south = projectTileToWorld({ x: 0, y: 1, elevation: 0 }, projection);
  assert(south.x < origin.x && south.y > origin.y, "Increasing y runs down-left");
  assertEqual(east.x, projection.tileWidth / 2);
  assertEqual(south.y, projection.tileDepth / 2);

  const raised = projectTileToWorld({ x: 0, y: 0, elevation: 2 }, projection);
  assertEqual(raised.y, -2 * projection.elevationHeight, "Elevation lifts the tile upward");
  assertEqual(raised.x, origin.x);

  const input = { x: 3, y: 4, elevation: 1 };
  const snapshot = JSON.stringify(input);
  projectTileToWorld(input, projection);
  assertEqual(JSON.stringify(input), snapshot, "Projection never mutates its input");
});

test("Projection", "Map bounds contain every tile and anchors match their tops", () => {
  const map = CONTENT.maps.elevationLab;
  const projection = battlefieldProjection();
  const bounds = calculateProjectedMapBounds(map, projection);
  for (let y = 0; y < map.height; y += 1) {
    for (let x = 0; x < map.width; x += 1) {
      const rect = projectTileAnchorRect({ x, y, elevation: elevationAt(map, x, y) }, projection);
      assert(rect.left >= bounds.minX - 0.001 && rect.right <= bounds.maxX + 0.001);
      assert(rect.top >= bounds.minY - 0.001 && rect.bottom <= bounds.maxY + 0.001);
    }
  }
  const tile = { x: 2, y: 3, elevation: 2 };
  const center = projectTileToWorld(tile, projection);
  const rect = projectTileAnchorRect(tile, projection);
  assertEqual(rect.centerX, center.x);
  assertEqual(rect.centerY, center.y);
  assertEqual(rect.width, projection.tileWidth);
  assertEqual(rect.height, projection.tileDepth);
  const face = projectTileTopFace(tile, projection);
  assertEqual(face.top.y, center.y - projection.tileDepth / 2);
  assertEqual(face.right.x, center.x + projection.tileWidth / 2);
});

test("Projection", "Render depth ordering is stable and elevation aware", () => {
  const near = { x: 0, y: 0, elevation: 0 };
  const far = { x: 3, y: 3, elevation: 0 };
  assert(calculateTileRenderOrder(far) > calculateTileRenderOrder(near));
  const low = { x: 2, y: 2, elevation: 0 };
  const high = { x: 2, y: 2, elevation: 2 };
  assert(calculateTileRenderOrder(high) > calculateTileRenderOrder(low));
  const tiles = [
    { x: 1, y: 0, elevation: 0 },
    { x: 0, y: 1, elevation: 1 },
    { x: 0, y: 0, elevation: 0 }
  ];
  const sortedOnce = tiles.slice().sort(compareRenderOrder);
  const sortedTwice = sortedOnce.slice().sort(compareRenderOrder);
  assertEqual(JSON.stringify(sortedOnce), JSON.stringify(sortedTwice), "Sorting is stable");
  assertEqual(sortedOnce[0].x + "," + sortedOnce[0].y, "0,0");
});

test("Projection", "Screen projection round-trips through the camera", () => {
  const camera = { zoom: 1.5, panX: 120, panY: -40 };
  const world = { x: 220, y: -60 };
  const screen = worldToScreen(world, camera);
  const back = screenToWorld(screen, camera);
  assertClose(back.x, world.x, 0.0001);
  assertClose(back.y, world.y, 0.0001);
  const rect = projectTileScreenRect({ x: 2, y: 1, elevation: 1 }, camera, battlefieldProjection());
  const anchor = projectTileAnchorRect({ x: 2, y: 1, elevation: 1 }, battlefieldProjection());
  assertClose(rect.left, anchor.left * camera.zoom + camera.panX, 0.0001);
  assertClose(rect.width, anchor.width * camera.zoom, 0.0001);
});

test("Projection", "Tile view models expose elevation and projected depth", () => {
  const state = elevationBattle();
  const view = createBattleViewModel(state, { selectedUnitId: "u1", mode: "unitReady" });
  const map = getMap(state);
  for (const tile of view.tiles) {
    assertEqual(tile.elevation, elevationAt(map, tile.x, tile.y));
    assertEqual(
      tile.projectedDepth,
      calculateTileRenderOrder({ x: tile.x, y: tile.y, elevation: tile.elevation })
    );
  }
  const unit = view.units.find((entry) => entry.id === "u1");
  assertEqual(unit.elevation, elevationAt(map, unit.x, unit.y));
  const before = JSON.stringify(state);
  createBattleViewModel(state, { selectedUnitId: "u1", mode: "unitReady" });
  assertEqual(JSON.stringify(state), before, "View models never mutate battle state");
});

test("Projection", "Floating panels anchor to projected screen rectangles", () => {
  const camera = { zoom: 1.2, panX: 200, panY: 90 };
  const projection = battlefieldProjection();
  const rect = projectTileScreenRect({ x: 3, y: 2, elevation: 1 }, camera, projection);
  const placed = calculateFloatingPanelPosition({
    anchorRect: rect,
    viewport: { width: 1440, height: 900 },
    bounds: { left: 4, top: 68, right: 1240, bottom: 840 },
    panelWidth: 250,
    panelHeight: 220
  });
  assertEqual(placed.withinViewport, true);
  assertEqual(placed.coversAnchor, false);
  assertEqual(placed.anchorRect.left, rect.left);
  const panned = projectTileScreenRect(
    { x: 3, y: 2, elevation: 1 },
    { ...camera, panX: camera.panX + 100 },
    projection
  );
  const movedPanel = calculateFloatingPanelPosition({
    anchorRect: panned,
    viewport: { width: 1440, height: 900 },
    bounds: { left: 4, top: 68, right: 1240, bottom: 840 },
    panelWidth: 250,
    panelHeight: 220
  });
  assertEqual(movedPanel.left - placed.left, 100, "The panel follows its anchor when panning");
});

