test("Camera", "Zoom clamps to the configured range", () => {
  const projection = battlefieldProjection();
  assertEqual(clampCameraZoom(0.01), projection.minZoom);
  assertEqual(clampCameraZoom(99), projection.maxZoom);
  assertEqual(clampCameraZoom(1), 1);
  assertEqual(clampCameraZoom(Number.NaN), projection.initialZoom);
  const camera = createCameraState();
  assertEqual(camera.zoom, projection.initialZoom);
  assertEqual(camera.panX, 0);
  assertEqual(camera.panY, 0);
});

test("Camera", "Zooming at a point keeps that world position under the cursor", () => {
  const camera = { zoom: 1, panX: 60, panY: 30 };
  const cursor = { x: 400, y: 260 };
  const worldBefore = screenToWorld(cursor, camera);
  const zoomed = zoomCameraAtPoint(camera, cursor, 1.75);
  const worldAfter = screenToWorld(cursor, zoomed);
  assertClose(worldAfter.x, worldBefore.x, 0.0001);
  assertClose(worldAfter.y, worldBefore.y, 0.0001);
  assertEqual(zoomed.zoom, 1.75);
  const clamped = zoomCameraAtPoint(camera, cursor, 99);
  assertEqual(clamped.zoom, battlefieldProjection().maxZoom);
  const stillPinned = screenToWorld(cursor, clamped);
  assertClose(stillPinned.x, worldBefore.x, 0.0001);
});

test("Camera", "Panning is pure presentation state", () => {
  const state = elevationBattle();
  const before = JSON.stringify(state);
  const counter = state.randomState.counter;
  const camera = createCameraState();
  const panned = panCamera(camera, 40, -25);
  assertEqual(panned.panX, 40);
  assertEqual(panned.panY, -25);
  assertEqual(camera.panX, 0, "The original camera is untouched");
  assertEqual(JSON.stringify(state), before);
  assertEqual(state.randomState.counter, counter);
  for (const field of ["camera", "zoom", "panX", "panY", "projection"]) {
    assert(!Object.prototype.hasOwnProperty.call(state, field), "Camera data must stay out of state");
  }
});

test("Camera", "Fit and focus produce a visible, recoverable camera", () => {
  const map = CONTENT.maps.elevationLab;
  const viewport = { width: 1200, height: 700 };
  const fitted = fitCameraToMap(map, viewport);
  const bounds = calculateProjectedMapBounds(map);
  assert(isWorldPointVisible({ x: bounds.centerX, y: bounds.centerY }, fitted, viewport));
  assertEqual(fitted.zoom, clampCameraZoom(fitted.zoom));
  const corners = [
    { x: bounds.minX, y: bounds.minY },
    { x: bounds.maxX, y: bounds.maxY }
  ];
  for (const corner of corners) {
    const screen = worldToScreen(corner, fitted);
    assert(
      screen.x >= -5 && screen.x <= viewport.width + 5,
      "Fit must show the whole map horizontally"
    );
  }

  const focused = focusCameraOnTile(fitted, { x: 6, y: 6, elevation: 3 }, viewport);
  const tileScreen = worldToScreen(projectTileToWorld({ x: 6, y: 6, elevation: 3 }), focused);
  assertClose(tileScreen.x, viewport.width / 2, 0.001);
  assertClose(tileScreen.y, viewport.height / 2, 0.001);

  const lost = clampCameraToBounds(
    { zoom: 1, panX: 99999, panY: 99999 },
    map,
    viewport
  );
  const recovered = worldToScreen({ x: bounds.minX, y: bounds.minY }, lost);
  assert(recovered.x < viewport.width, "The map can never be pushed entirely off-screen");
  const refitted = fitCameraToMap(map, viewport);
  assert(isWorldPointVisible({ x: bounds.centerX, y: bounds.centerY }, refitted, viewport));
});

test("Camera", "A large map projects beyond the stage and still fits on demand", () => {
  const map = CONTENT.maps.elevationLab;
  const projection = battlefieldProjection();
  const bounds = calculateProjectedMapBounds(map, projection);
  const smallStage = { width: 600, height: 380 };
  assert(bounds.width > smallStage.width, "The projected map is wider than a small stage");
  const fitted = fitCameraToMap(map, smallStage, projection);
  assert(fitted.zoom < 1, "Fitting a big map zooms out: " + fitted.zoom);
  assert(fitted.zoom >= projection.minZoom);
  assert(
    isWorldPointVisible({ x: bounds.centerX, y: bounds.centerY }, fitted, smallStage),
    "The map centre stays visible"
  );
});

test("Camera", "Camera helpers never touch battle rules", () => {
  const helpers = CAMERA_FUNCTIONS;
  const ids = contentIdList();
  const forbidden = [/FORMULAS\./, /rollChance\(/, /randomFloat\(/, /executeCommand\(/, /resolveEffects\(/];
  const hits = [];
  for (const name of Object.keys(helpers)) {
    const source = helpers[name].toString();
    for (const pattern of forbidden) {
      if (pattern.test(source)) hits.push(name + " -> " + pattern.source);
    }
    for (const id of ids) {
      if (source.includes('"' + id + '"')) hits.push(name + " -> " + id);
    }
  }
  assertEqual(hits.length, 0, hits.join(", "));
  assert(Object.keys(helpers).length >= 18, "Every projection and camera helper is registered");
});


