  const nyx = deployment.candidates.find((entry) => entry.operatorId === "nyx");
  assert(nyx && nyx.guest && nyx.status === "guest");
  assertEqual(Object.prototype.hasOwnProperty.call(beforeJailbreak.roster, "nyx"), false);

  const failed = resolveMissionOutcome(beginMission(beforeJailbreak, "act1-08-jailbreak"), "act1-08-jailbreak", { victory: false });
  assertEqual(Object.prototype.hasOwnProperty.call(failed.roster, "nyx"), false);
  const won = completeActOneMission(beforeJailbreak, "act1-08-jailbreak");
