test("Combat dialogue", "Act One contains substantial authored radio dialogue", () => {
  const scripts = Object.values(CAMPAIGN.dialogue);
  const triggers = scripts.reduce((sum, script) => sum + (script.midBattle || []).length, 0);
  const storyLines = scripts.reduce((sum, script) => sum + Object.values(script.scenes || {}).reduce((sceneSum, scene) => sceneSum + (scene.lines || []).length + (scene.choices || []).reduce((choiceSum, choice) => choiceSum + (choice.options || []).length, 0), 0), 0);
  const combatLines = scripts.reduce((sum, script) => sum + (script.midBattle || []).reduce((triggerSum, trigger) => triggerSum + 1 + (trigger.followUpLines || []).length, 0), 0);
  assert(triggers >= 25, "Expected at least 25 combat triggers");
  assert(storyLines + combatLines >= 150, "The Act One script is too thin");
});

