test("Maps and encounters", "Every battle initializes legally and reaches a terminal result under automated play", () => {
  let campaign = createCampaignState();
  let seed = 40;
  for (const missionId of ACT_ONE_ORDER) {
    const mission = CAMPAIGN.missions[missionId];
    if (mission.kind === "battle") {
      const deployment = createCampaignDeploymentState(campaign, missionId);
      const roster = createCampaignMissionRoster(campaign, missionId, deployment);
      const state = createBattle(missionEncounterId(missionId, campaign), seed, { roster, rosterTeamId: "player" });
      const result = runBattle(state, 400);
      assertEqual(result.hitCap, false, missionId + " stalled");
      assert(result.winner === "player" || result.winner === "foe", missionId + " did not resolve");
      assertEqual(state.errors.length, 0, missionId + ": " + state.errors.join(" | "));
      seed += 1;
    }
    if (missionAvailable(campaign, missionId)) campaign = completeActOneMission(campaign, missionId);
  }
});

