  resolveReactionWindowForTest(state, offer, {
    type: "targetMarked",
    unitRef: "drillA",
    unitId: target.id,
    sourceRef: "vale",
    sourceUnitId: vale.id,
    statusId: "marked",
    __seq: "staleProbe"
  });

  assertEqual(target.currentHp, hpBefore, "the dead unit did not fire");
