/** Runtime font check shown in Settings so font-path failures cannot be silent. */
function FontDiagnostics() {
  const [status, setStatus] = React.useState({ body: "checking", bold: "checking", display: "checking" });

  React.useEffect(() => {
    let cancelled = false;
    if (typeof document === "undefined" || !document.fonts || !document.fonts.load) {
      setStatus({ body: "unsupported", bold: "unsupported", display: "unsupported" });
      return undefined;
    }

    Promise.all([
      document.fonts.load('16px "Pixel Operator"').then((faces) => faces.length > 0),
      document.fonts.load('700 16px "Pixel Operator"').then((faces) => faces.length > 0),
      document.fonts.load('700 16px "Silkscreen"').then((faces) => faces.length > 0)
    ]).then(([body, bold, display]) => {
      if (!cancelled) {
        setStatus({
          body: body ? "loaded" : "missing",
          bold: bold ? "loaded" : "missing",
          display: display ? "loaded" : "missing"
        });
      }
    }).catch(() => {
      if (!cancelled) setStatus({ body: "missing", bold: "missing", display: "missing" });
    });

    return () => { cancelled = true; };
  }, []);

  const tone = (value) =>
    value === "loaded" ? "text-emerald-300" : value === "checking" ? "text-slate-400" : "text-rose-300";
  const allLoaded = status.body === "loaded" && status.bold === "loaded" && status.display === "loaded";

  return (
    <div className="mt-5 border border-slate-700 bg-slate-900/60 p-4">
      <div className="flex items-center justify-between gap-4">
        <span className="text-[11px] uppercase tracking-[0.2em] text-slate-500">Font files</span>
        <span className={"text-[10px] uppercase tracking-[0.16em] " + (allLoaded ? "text-emerald-300" : "text-rose-300")}>
          {allLoaded ? "All loaded" : "Check paths"}
        </span>
      </div>
      <div className="mt-3 space-y-2 text-[10px]">
        <p className="flex gap-3"><span className={tone(status.body)}>{status.body}</span><span className="break-all text-slate-500">{GAME_FONT_ASSETS.body}</span></p>
        <p className="flex gap-3"><span className={tone(status.bold)}>{status.bold}</span><span className="break-all text-slate-500">{GAME_FONT_ASSETS.bodyBold}</span></p>
        <p className="flex gap-3"><span className={tone(status.display)}>{status.display}</span><span className="break-all text-slate-500">{GAME_FONT_ASSETS.display}</span></p>
      </div>
      <div className="mt-4 grid grid-cols-2 gap-3 border-t border-slate-800 pt-4">
        <p style={{ fontFamily: '\"Pixel Operator\", monospace' }} className="text-[18px] text-slate-100">Pixel Operator 012345</p>
        <p style={{ fontFamily: '\"Silkscreen\", monospace', fontWeight: 700 }} className="text-[16px] uppercase text-sky-200">Silkscreen Tactical</p>
      </div>
    </div>
  );
}

/**
 * Shared story/combat dialogue geometry. Portrait right edge and dialogue
 * left edge are intentionally identical, so future portrait borders line up
 * perfectly with the dialogue frame at every UI scale.
 */
function calculateCinematicDialogueLayout(viewport, variant) {
  const width = Math.max(960, (viewport && viewport.width) || 1920);
  const height = Math.max(540, (viewport && viewport.height) || 1080);
  const safeX = Math.round(clamp(42, 76, width * 0.04));
  const bottom = Math.round(clamp(48, 76, height * 0.065));
  const portraitLeft = Math.round(clamp(safeX + 34, 188, width * 0.09));
  const portraitWidth = Math.round(clamp(252, 352, width * 0.18));
  const portraitHeight = Math.round(clamp(310, variant === "combat" ? 410 : 438, height * 0.4));
  const dialogueLeft = portraitLeft + portraitWidth;
  const dialogueRight = Math.round(clamp(84, 232, width * 0.12));
  const dialogueWidth = Math.max(560, width - dialogueLeft - dialogueRight);
  const dialogueHeight = Math.round(clamp(220, variant === "combat" ? 250 : 270, height * 0.245));
  const nameplateWidth = Math.round(clamp(310, 430, dialogueWidth * 0.38));
  const choiceWidth = Math.round(clamp(410, 560, width * 0.30));
  const textSize = Math.round(clamp(17, 20, width / 96));
  return {
    width,
    height,
    safeX,
    bottom,
    portraitLeft,
    portraitWidth,
    portraitHeight,
    dialogueLeft,
    dialogueRight,
    dialogueWidth,
    dialogueHeight,
    nameplateWidth,
    choiceWidth,
    choiceRight: safeX + 10,
    choiceTop: Math.round(clamp(190, 246, height * 0.22)),
    textSize,
    textMaxHeight: Math.max(120, dialogueHeight - 92)
  };
}

