/** Draws an asset descriptor: tries conventional files, then a safe fallback. */
function AssetImage({ asset, size, width, height, className, alt, cover = false, imageStyle }) {
  const candidates = asset
    ? asset.candidateEntries && asset.candidateEntries.length
      ? asset.candidateEntries
      : asset.srcCandidates && asset.srcCandidates.length
      ? asset.srcCandidates.map((src) => ({ src, flipX: !!asset.flipX }))
      : asset.src
      ? [{ src: asset.src, flipX: !!asset.flipX }]
      : []
    : [];
  const [candidateIndex, setCandidateIndex] = React.useState(0);
  React.useEffect(() => setCandidateIndex(0), [asset && asset.id, asset && asset.facing]);
  const resolvedWidth = width || size;
  const resolvedHeight = height || size;
  const currentCandidate = candidates[candidateIndex] || null;
  const style = {
    width: resolvedWidth,
    height: resolvedHeight,
    fontSize: Math.round(Math.min(Number(resolvedWidth) || 64, Number(resolvedHeight) || 64) * 0.45),
    transform: currentCandidate && currentCandidate.flipX ? "scaleX(-1)" : undefined
  };
  const currentSrc = currentCandidate ? currentCandidate.src : null;
  if (currentSrc) {
    return (
      <img
        src={currentSrc}
        alt={alt || asset.label || ""}
        style={{ ...style, ...(imageStyle || {}) }}
        onError={() => setCandidateIndex((index) => index + 1)}
        className={(cover ? "object-cover " : "object-contain ") + (className || "")}
      />
    );
  }

  const fallback = (asset && asset.fallback) || asset || { type: "glyph", value: "?" };
  if (fallback.type === "color") {
    return <span style={{ ...style, backgroundColor: fallback.value }} className={"inline-block " + (className || "")} title={fallback.label || ""} />;
  }
  if (fallback.type === "sceneLabel") {
    return (
      <div style={style} className={"flex items-center justify-center bg-gradient-to-br from-slate-950 via-slate-900 to-slate-800 border border-slate-700 " + (className || "")}>
        <div className="text-center px-4">
          <div className="text-4xl opacity-40 mb-2">▣</div>
          <div className="text-[10px] uppercase tracking-[0.25em] text-slate-500">{fallback.value}</div>
        </div>
      </div>
    );
  }
  if (fallback.type === "silhouette" || fallback.type === "portraitSilhouette") {
    const portrait = fallback.type === "portraitSilhouette" || fallback.variant === "portrait";
    return (
      <div style={style} title={fallback.label || "Placeholder asset"} className={"relative overflow-hidden inline-flex items-center justify-center bg-gradient-to-b from-slate-800 to-slate-950 border border-slate-700 " + (className || "")}>
        <div className={(portrait ? "text-[70%]" : "text-[60%]") + " opacity-80 drop-shadow-lg"}>♟</div>
        <div className="absolute bottom-1 inset-x-1 truncate text-center text-[7px] uppercase tracking-wider text-slate-500">{fallback.label || fallback.value || "MECH"}</div>
      </div>
    );
  }
  return (
    <span style={style} title={fallback.label || ""} className={"inline-flex items-center justify-center leading-none bg-slate-950 " + (className || "")}>
      {fallback.value == null ? "?" : fallback.value}
    </span>
  );
}


function createPixelOutlineOffsets(thicknessPx, cameraZoom) {
  const thickness = Math.max(0, Math.round(thicknessPx || 0));
  if (!thickness) return [];
  const zoom = Math.max(0.25, Number(cameraZoom) || 1);
  const offsets = [];
  // Build independent alpha-mask copies instead of chained drop-shadows.
  // Each ring is screen-space locked by compensating for camera zoom.
  for (let ring = 1; ring <= thickness; ring += 1) {
    const step = ring / zoom;
    for (let dx = -ring; dx <= ring; dx += 1) {
      for (let dy = -ring; dy <= ring; dy += 1) {
        if (Math.max(Math.abs(dx), Math.abs(dy)) !== ring) continue;
        offsets.push({ x: (dx / ring) * step, y: (dy / ring) * step });
      }
    }
  }
  return offsets;
}

/**
 * Transparent-PNG outline renderer for battlefield sprites.
 * It uses separate CSS mask copies behind the source image, so the outline
 * never recursively grows the way stacked drop-shadow filters do.
 */
function PixelOutlinedAssetImage({
  asset,
  width,
  height,
  outlineColor,
  outlineThickness = 0,
  cameraZoom = 1,
  className,
  alt
}) {
  const candidates = asset
    ? asset.candidateEntries && asset.candidateEntries.length
      ? asset.candidateEntries
      : asset.srcCandidates && asset.srcCandidates.length
      ? asset.srcCandidates.map((src) => ({ src, flipX: !!asset.flipX }))
      : asset.src
      ? [{ src: asset.src, flipX: !!asset.flipX }]
      : []
    : [];
  const [candidateIndex, setCandidateIndex] = React.useState(0);
  React.useEffect(() => setCandidateIndex(0), [asset && asset.id, asset && asset.facing]);
  const currentCandidate = candidates[candidateIndex] || null;
  const currentSrc = currentCandidate ? currentCandidate.src : null;

  if (!currentSrc) {
    return (
      <AssetImage
        asset={asset}
        width={width}
        height={height}
        imageStyle={{ imageRendering: "pixelated" }}
        className={className}
        alt={alt}
      />
    );
  }

  const offsets = outlineColor
    ? createPixelOutlineOffsets(outlineThickness, cameraZoom)
    : [];
  const mirrored = !!currentCandidate.flipX;
  const maskBase = {
    position: "absolute",
    inset: 0,
    width: "100%",
    height: "100%",
    backgroundColor: outlineColor,
    WebkitMaskImage: 'url("' + currentSrc + '")',
    maskImage: 'url("' + currentSrc + '")',
    WebkitMaskRepeat: "no-repeat",
    maskRepeat: "no-repeat",
    WebkitMaskPosition: "center",
    maskPosition: "center",
    WebkitMaskSize: "contain",
    maskSize: "contain",
    pointerEvents: "none"
  };

  return (
    <div
      style={{
        position: "relative",
        width,
        height,
        transform: mirrored ? "scaleX(-1)" : undefined,
        transformOrigin: "50% 50%",
        overflow: "visible"
      }}
      className={className || ""}
    >
      {offsets.map((offset, index) => (
        <span
          key={index}
          aria-hidden="true"
          style={{
            ...maskBase,
            transform: "translate(" + offset.x + "px," + offset.y + "px)"
          }}
        />
      ))}
      <img
        src={currentSrc}
        alt={alt || (asset && asset.label) || ""}
        onError={() => setCandidateIndex((index) => index + 1)}
        style={{
          position: "absolute",
          inset: 0,
          width: "100%",
          height: "100%",
          objectFit: "contain",
          imageRendering: "pixelated",
          pointerEvents: "none"
        }}
      />
    </div>
  );
}

