const DANGER_STYLES = createDangerZoneStyles();

function terrainSurface(tile) {
  if (tile.terrainId === "wall") return { top: "#475569", side: "#1e293b" };
  if (tile.terrainId === "burningGround") return { top: "#7c2d12", side: "#431407" };
  if (tile.movementCost > 1) return { top: "#334155", side: "#111827" };
  return { top: "#1e293b", side: "#0b1220" };
}

function overlayColor(tile) {
  // A node the chain will reach reads before anything else: it is the only
  // mark that says "this unit is about to be hit by something you aimed
  // somewhere else".
  if (tile.chainHop != null) {
    return tile.chainLethal ? "rgba(244, 114, 182, 0.7)" : "rgba(56, 189, 248, 0.6)";
  }
  // Route marks read before the generic path colour: a turn, a landing tile and
  // a stop are the three things the player is actually deciding between.
  if (tile.routeBlocked) return "rgba(244, 63, 94, 0.55)";
  if (tile.routeDisplacement) return "rgba(251, 191, 36, 0.6)";
  if (tile.routeRedirect) return "rgba(129, 140, 248, 0.6)";
  if (tile.isDestination) return "rgba(125, 211, 252, 0.65)";
  if (tile.pathIndex != null) return "rgba(56, 189, 248, 0.45)";
  if (tile.inArea) return "rgba(245, 158, 11, 0.5)";
  if (tile.suggested) return "rgba(163, 230, 53, 0.45)";
  if (tile.targetable) return "rgba(245, 158, 11, 0.28)";
  if (tile.reachable) return "rgba(14, 165, 233, 0.3)";
  return null;
}

/**
 * One logical tile drawn as a 2.5D block: a diamond top face plus side walls
 * for its elevation. Placement always comes from the projection helpers.
 */
function TileBlock({ tile, projection, onHover, onClick, onRightClick, disabled, showElevation }) {
  const rect = projectTileAnchorRect(tile, projection);
  const surface = terrainSurface(tile);
  const overlay = overlayColor(tile);
  const danger = tile.threatImmediate
    ? DANGER_STYLES.immediate
    : tile.threatPotential
    ? DANGER_STYLES.potential
    : null;
  const sideHeight = (tile.elevation || 0) * projection.elevationHeight + projection.tileDepth / 2;

  return (
    <div
      style={{
        position: "absolute",
        left: rect.left,
        top: rect.top,
        width: rect.width,
        height: rect.height + sideHeight,
        zIndex: tile.projectedDepth
      }}
    >
      {/* Side walls: purely decorative, never clickable. */}
      <div
        style={{
          position: "absolute",
          left: 0,
          top: rect.height / 2,
          width: rect.width,
          height: sideHeight,
          background: "linear-gradient(" + surface.side + ", #020617)",
          clipPath:
            "polygon(0% 0%, 50% 50%, 100% 0%, 100% " +
            Math.max(1, 100 - (projection.tileDepth / sideHeight) * 50) +
            "%, 50% 100%, 0% " +
            Math.max(1, 100 - (projection.tileDepth / sideHeight) * 50) +
            "%)",
          pointerEvents: "none",
          opacity: sideHeight > projection.tileDepth / 2 ? 1 : 0
        }}
      />
      {/* Top face: the clickable surface. */}
      <div
        onMouseEnter={() => onHover(tile)}
        onClick={() => (disabled ? null : onClick(tile))}
        onContextMenu={(event) => {
          event.preventDefault();
          if (!disabled) onRightClick(tile);
        }}
        title={
          tile.terrainName +
          " - elevation " +
          tile.elevation +
          (tile.moveCost != null ? " - move cost " + tile.moveCost : "") +
          (tile.climbDelta ? " - climb " + tile.climbDelta : "") +
          (tile.blocksLineOfSight ? " - blocks line of sight" : "")
        }
        style={{
          position: "absolute",
          left: 0,
          top: 0,
          width: rect.width,
          height: rect.height,
          background: overlay
            ? "linear-gradient(" + overlay + "," + overlay + "), " + surface.top
            : surface.top,
          clipPath: "polygon(50% 0%, 100% 50%, 50% 100%, 0% 50%)",
          border: "0",
          boxShadow: tile.hovered ? "inset 0 0 0 2px rgba(226, 232, 240, 0.8)" : "none",
          cursor: disabled ? "default" : "pointer"
        }}
      >
        {danger ? (
          <span
            style={{
              position: "absolute",
              inset: 0,
              clipPath: "polygon(50% 0%, 100% 50%, 50% 100%, 0% 50%)",
              pointerEvents: "none",
              ...danger
            }}
          />
        ) : null}
        <span
          style={{
            position: "absolute",
            inset: 0,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            pointerEvents: "none",
            fontSize: 10,
            color: "rgba(148, 163, 184, 0.9)"
          }}
        >
          {tile.terrainId === "wall" ? "#" : showElevation ? tile.elevation : ""}
        </span>
        {tile.chainHop != null ? (
          <span
            style={{
              position: "absolute",
              top: 1,
              width: "100%",
              textAlign: "center",
              fontSize: 10,
              fontWeight: 700,
              color: tile.chainLethal ? "#fdf2f8" : "#e0f2fe",
              textShadow: "0 1px 2px rgba(0, 0, 0, 0.9)",
              pointerEvents: "none"
            }}
          >
            {tile.chainHop + 1}
          </span>
        ) : null}
        {tile.reachable && tile.moveCost > 0 ? (
          <span
            style={{
              position: "absolute",
              bottom: 2,
              width: "100%",
              textAlign: "center",
              fontSize: 9,
              color: "rgba(186, 230, 253, 0.9)",
              pointerEvents: "none"
            }}
          >
            {tile.moveCost}
            {tile.climbDelta > 0 ? " ^" + tile.climbDelta : ""}
          </span>
        ) : null}
      </div>
    </div>
  );
}

function UnitToken({ unit, projection, position, lunging, isSelected, occlusion, cameraZoom, onSelect, onInspect, disabled }) {
  const [hovered, setHovered] = React.useState(false);
  const world = projectTileToWorld(
    { x: position.x, y: position.y, elevation: position.elevation || 0 },
    projection
  );

  const displayFacing = normalizeFacing(position.facing || unit.facing);
  const displayAsset = resolveDirectionalUnitBattlefieldAsset(
    CONTENT.units[unit.definitionId],
    displayFacing
  );
  const displayFacingArrow = GAME_CONFIG.facing.arrows[displayFacing];
  const selected = !!isSelected;
  const outlineColor = selected
    ? "rgba(74, 222, 128, 0.98)"
    : unit.isEnemyToPlayer
    ? "rgba(248, 113, 113, 0.98)"
    : hovered
    ? "rgba(248, 250, 252, 0.98)"
    : null;
  // Exact visible outline width in screen pixels. The renderer compensates for
  // battlefield camera zoom, and uses independent alpha-mask copies so it cannot
  // balloon outward through recursive CSS filters.
  const outlineThickness = selected ? 2 : outlineColor ? 1 : 0;

  const spriteWidth = Math.round(
    projection.tileWidth * (projection.unitSpriteWidthScale || 0.96)
  );
  const spriteHeight = Math.round(
    projection.tileWidth * (projection.unitSpriteHeightScale || 1.18)
  );
  const anchorY = world.y + projection.tileDepth * 0.34;

  return (
    <div
      style={{
        width: spriteWidth,
        height: spriteHeight,
        position: "absolute",
        left: 0,
        top: 0,
        transform:
          "translate(" +
          (world.x - spriteWidth / 2) +
          "px," +
          (anchorY - spriteHeight) +
          "px)",
        transition: "transform " + (position.duration || 0) + "ms linear",
        opacity: unit.alive ? (unit.concealed ? 0.45 : 1) : 0.25,
        zIndex:
          calculateTileRenderOrder({
            x: position.x,
            y: position.y,
            elevation: position.elevation || 0
          }) +
          (occlusion && occlusion.occluded && unit.alive ? 100000 : 5),
        pointerEvents: "none",
        overflow: "visible"
      }}
    >
      {occlusion && occlusion.occluded && unit.alive ? (
        <span
          title={unit.name + " (behind terrain)"}
          style={{
            position: "absolute",
            inset: 2,
            borderRadius: 4,
            border: "1px dashed rgba(226, 232, 240, 0.78)",
            boxShadow: "0 0 0 2px #020617",
            pointerEvents: "none"
          }}
        />
      ) : null}

      <span
        onMouseEnter={() => setHovered(true)}
        onMouseLeave={() => setHovered(false)}
        onClick={(event) => {
          if (disabled) return;
          event.stopPropagation();
          onSelect(unit);
        }}
        onContextMenu={(event) => {
          event.preventDefault();
          event.stopPropagation();
          onInspect(unit);
        }}
        title={
          unit.name +
          " " +
          unit.currentHp +
          "/" +
          unit.maxHp +
          " · facing " +
          displayFacing
        }
        style={{
          position: "absolute",
          inset: 0,
          pointerEvents: unit.alive ? "auto" : "none",
          cursor: disabled ? "default" : "pointer",
          zIndex: 7
        }}
      />

      <div
        style={{
          position: "absolute",
          inset: 0,
          transition: "transform 120ms ease-out",
          transform: lunging ? "scale(1.08)" : "scale(1)",
          transformOrigin: "50% 100%",
          pointerEvents: "none"
        }}
      >
        <PixelOutlinedAssetImage
          asset={displayAsset}
          width={spriteWidth}
          height={spriteHeight}
          outlineColor={outlineColor}
          outlineThickness={outlineThickness}
          cameraZoom={cameraZoom}
          className={(unit.alive ? "" : "grayscale ") + "block h-full w-full"}
          alt={unit.name}
        />
      </div>

      {/* HP is intentionally contextual: it sits above the art only while hovered,
          so it never creates the illusion that the mech is floating over a bar. */}
      {hovered && unit.alive ? (
        <div
          className="absolute left-1/2 z-[8] -translate-x-1/2 border border-slate-500/70 bg-slate-950/90 px-2 py-1 shadow-lg"
          style={{ top: -34, width: Math.max(86, Math.round(spriteWidth * 0.82)) }}
        >
          <div className="mb-1 flex justify-between gap-3 text-[9px] font-bold tabular-nums text-slate-100">
            <span>{unit.name}</span>
            <span>{unit.currentHp}/{unit.maxHp}</span>
          </div>
          <HealthBar unit={unit} />
        </div>
      ) : null}

      <span className="absolute left-1 top-1 z-[6] rounded-sm bg-slate-950/75 px-1 text-[9px] text-slate-200">
        {unit.teamMarker}
      </span>
      <span
        title={"Facing " + displayFacing}
        className="absolute -bottom-4 left-1/2 z-[6] -translate-x-1/2 text-[14px] font-black text-cyan-200 drop-shadow-[0_1px_2px_#020617]"
      >
        {displayFacingArrow}
      </span>

      {unit.statuses.length ? (
        <span className="absolute right-1 top-5 z-[6] rounded-sm bg-slate-950/75 px-1 text-[9px] text-amber-300">
          {unit.statuses.map((status) => status.icon.value).join("")}
        </span>
      ) : null}
      {unit.abilities.some((ability) => ability.cooldownRemaining > 0) ? (
        <span className="absolute bottom-7 right-1 z-[6] rounded-sm bg-slate-950/75 px-1 text-[9px] text-slate-300">⏱</span>
      ) : null}
    </div>
  );
}

function FacingControls({ unit, disabled, onFace }) {
  if (!unit || !unit.alive || !unit.isActive) return null;
  const faceButton = (facing, arrow, grid) => (
    <button
      type="button"
      disabled={disabled}
      title={"Face " + facing}
      onClick={() => onFace(facing)}
      style={{ gridArea: grid }}
      className={
        "h-11 w-11 border text-[22px] font-black transition-all " +
        (unit.facing === facing
          ? "border-sky-200 bg-sky-300/25 text-sky-100 shadow-[0_0_20px_rgba(125,211,252,0.2)]"
          : "border-slate-600 bg-slate-950/90 text-slate-300 hover:border-sky-300/70 hover:text-sky-100") +
        (disabled ? " opacity-40" : "")
      }
    >
      {arrow}
    </button>
  );
  return (
    <div
      style={{
        ...createPanelStyle("secondary"),
        position: "absolute",
        left: "50%",
        bottom: 24,
        zIndex: 39,
        transform: "translateX(-50%)",
        width: 210,
        border: "1px solid " + CINEMATIC_COLORS.border,
        background: "rgba(4,12,21,0.93)"
      }}
      className="p-3 shadow-2xl"
    >
      <FrameCorners />
      <div className="mb-2 flex items-center justify-between">
        <span className="text-[10px] uppercase tracking-[0.24em] text-sky-300/70">Final facing</span>
        <span className="text-[10px] uppercase text-slate-500">{unit.facing}</span>
      </div>
      <div
        className="mx-auto grid w-[142px] items-center justify-items-center gap-1"
        style={{ gridTemplateAreas: '"nw . ne" ". c ." "sw . se"' }}
      >
        {faceButton("northwest", "↖", "nw")}
        {faceButton("northeast", "↗", "ne")}
        <div style={{ gridArea: "c" }} className="flex h-9 w-9 items-center justify-center border border-slate-700 bg-slate-900/80 text-[9px] text-slate-500">FACE</div>
        {faceButton("southwest", "↙", "sw")}
        {faceButton("southeast", "↘", "se")}
      </div>
    </div>
  );
}

function Popup({ popup, projection }) {
  const tones = {
    damage: "text-rose-300",
    heal: "text-emerald-300",
    miss: "text-slate-300",
    resist: "text-slate-300",
    status: "text-amber-300",
    flank: "text-amber-200",
    rear: "text-rose-200"
  };
  return (
    <div
      style={(() => {
        const world = projectTileToWorld(
          { x: popup.x, y: popup.y, elevation: popup.elevation || 0 },
          projection
        );
        return {
          position: "absolute",
          left: 0,
          top: 0,
          transform:
            "translate(" +
            (world.x - projection.tileWidth / 4) +
            "px," +
            (world.y - projection.tileDepth - 16) +
            "px)",
          width: projection.tileWidth / 2,
          zIndex: 100000
        };
      })()}
      className={
        "pointer-events-none text-center text-xs font-bold " +
        (tones[popup.kind] || "text-slate-200")
      }
    >
      {popup.text}
    </div>
  );
}

function BattleEffect({ effect, projection }) {
  const project = (tile) => projectTileToWorld(
    { x: tile.x, y: tile.y, elevation: tile.elevation || 0 },
    projection
  );
  const tone = effect.kind === "heal" || effect.kind === "repair"
    ? "rgba(110, 231, 183, 0.95)"
    : effect.kind === "shield"
      ? "rgba(125, 211, 252, 0.95)"
      : effect.kind === "shotgun"
        ? "rgba(251, 191, 36, 0.95)"
        : "rgba(248, 250, 252, 0.95)";
  if (effect.from && effect.to) {
    const from = project(effect.from);
    const to = project(effect.to);
    const dx = to.x - from.x;
    const dy = to.y - from.y;
    const length = Math.max(8, Math.sqrt(dx * dx + dy * dy));
    const angle = Math.atan2(dy, dx);
    return (
      <div
        className="pointer-events-none"
        style={{
          position: "absolute",
          left: from.x,
          top: from.y - 4,
          width: length,
          height: effect.kind === "shotgun" ? 6 : 3,
          transformOrigin: "0 50%",
          transform: "rotate(" + angle + "rad)",
          background: "linear-gradient(90deg, transparent, " + tone + ", transparent)",
          boxShadow: "0 0 10px " + tone,
          borderRadius: 999,
          zIndex: 100002,
          opacity: 0.9
        }}
      >
        <span style={{ position: "absolute", right: -6, top: -9, color: tone, fontSize: 15 }}>
          {effect.glyph || "•"}
        </span>
      </div>
    );
  }
  if (!effect.to) return null;
  const at = project(effect.to);
  return (
    <div
      className="pointer-events-none flex items-center justify-center font-bold"
      style={{
        position: "absolute",
        left: at.x - projection.tileWidth * 0.18,
        top: at.y - projection.tileDepth * 1.15,
        width: projection.tileWidth * 0.36,
        height: projection.tileWidth * 0.36,
        border: "2px solid " + tone,
        borderRadius: effect.kind === "shield" ? "50%" : 6,
        color: tone,
        boxShadow: "0 0 16px " + tone,
        fontSize: Math.max(14, projection.tileWidth * 0.18),
        zIndex: 100003,
        transform: effect.kind === "damage" ? "rotate(12deg)" : "scale(1.05)"
      }}
    >
      {effect.glyph || "✦"}
    </div>
  );
}

function TargetBadge({ badge, projection }) {
  return (
    <div
      style={(() => {
        const world = projectTileToWorld(
          { x: badge.x, y: badge.y, elevation: badge.elevation || 0 },
          projection
        );
        return {
          position: "absolute",
          left: 0,
          top: 0,
          transform:
            "translate(" +
            (world.x - projection.tileWidth / 3) +
            "px," +
            (world.y - projection.tileDepth - 26) +
            "px)",
          width: (projection.tileWidth * 2) / 3,
          zIndex: 100001
        };
      })()}
      className="pointer-events-none text-center"
    >
      <span
        className={
          "inline-block px-1 rounded-sm text-[10px] font-bold " +
          (badge.kind === "heal"
            ? "bg-emerald-400 text-slate-950"
            : badge.lethal
            ? "bg-rose-400 text-slate-950"
            : "bg-slate-100 text-slate-950")
        }
      >
        {badge.text}
      </span>
    </div>
  );
}

/**
 * The projected world. Everything inside is positioned by the projection
 * helpers; the camera transform above it handles pan and zoom.
 */
/** "Last seen here": a ghost on the tile a contact was last confirmed on. */
function KnowledgeMarker({ marker, projection }) {
  const rect = projectTileAnchorRect(marker, projection);
  return (
    <div
      style={{
        position: "absolute",
        left: rect.left,
        top: rect.top - (marker.elevation || 0),
        width: rect.width,
        height: rect.height,
        zIndex: 24,
        pointerEvents: "none",
        border: "1px dashed rgba(251,191,36,0.85)",
        background: "rgba(251,191,36,0.10)",
        opacity: marker.investigated ? 0.45 : 1
      }}
      className="flex items-center justify-center"
      title={marker.label + " — last known position"}
    >
      <span className="text-[10px] font-bold text-amber-300">
        ?{marker.approximate ? "±" : ""}
      </span>
    </div>
  );
}

function Battlefield({
  view,
  projection,
  map,
  bounds,
  positions,
  popups,
  effects,
  badges,
  lungingUnitId,
  cameraZoom,
  showElevation,
  showIntel,
  onHoverTile,
  onClickTile,
  onRightClickTile,
  disabled
}) {
  const tiles = view.tiles.slice().sort(compareRenderOrder);
  return (
    <div
      style={{ position: "absolute", left: 0, top: 0, width: 0, height: 0 }}
      onMouseLeave={() => onHoverTile(null)}
      onContextMenu={(event) => event.preventDefault()}
    >
      <div style={{ position: "absolute", left: bounds.originX, top: bounds.originY }}>
        {tiles.map((tile) => (
          <TileBlock
            key={tile.key}
            tile={tile}
            projection={projection}
            onHover={onHoverTile}
            onClick={onClickTile}
            onRightClick={onRightClickTile}
            disabled={disabled}
            showElevation={showElevation}
          />
        ))}
        {showIntel
          ? (view.knowledgeMarkers || []).map((marker) => (
              <KnowledgeMarker key={marker.key} marker={marker} projection={projection} />
            ))
          : null}
        {view.units
          .filter((unit) => !unit.hiddenFromPlayer)
          .map((unit) => (
          <UnitToken
            key={unit.id}
            unit={unit}
            projection={projection}
            position={
              positions[unit.id] || { x: unit.x, y: unit.y, elevation: unit.elevation, duration: 0 }
            }
            lunging={lungingUnitId === unit.id}
            isSelected={view.selectedUnitId === unit.id}
            cameraZoom={cameraZoom}
            occlusion={map ? calculateUnitOcclusion(map, unit, projection) : null}
            disabled={disabled}
            onSelect={(entry) => onClickTile({ x: entry.x, y: entry.y })}
            onInspect={(entry) => onRightClickTile({ x: entry.x, y: entry.y })}
          />
          ))}
        {(effects || []).map((effect) => (
          <BattleEffect key={effect.id} effect={effect} projection={projection} />
        ))}
        {(badges || []).map((badge, index) => (
          <TargetBadge key={index} badge={badge} projection={projection} />
        ))}
        {popups.map((popup) => (
          <Popup key={popup.id} popup={popup} projection={projection} />
        ))}
      </div>
    </div>
  );
}

function TimelineRail({ timeline, alternate, title, compact }) {
  if (compact) {
    return (
      <div className="flex items-center gap-1 overflow-x-auto">
        <span className="text-[9px] uppercase tracking-widest text-slate-500 shrink-0">Now</span>
        {timeline.slice(0, 14).map((entry) => {
          const accent = accentOf(entry.teamAccent);
          const shifted =
            alternate && alternate[entry.order] && alternate[entry.order].unitId !== entry.unitId;
          return (
            <div
              key={entry.order}
              title={
                entry.name +
                " · " +
                (entry.estimated ? "estimated" : "scheduled") +
                " at t=" +
                Math.round(entry.time)
              }
              style={{ width: 30 }}
              className={
                "shrink-0 border rounded-sm text-center py-0.5 " +
                (entry.isActive ? "border-amber-300 " : "border-slate-800 ") +
                (entry.estimated ? "border-dashed opacity-70 " : "") +
                (shifted ? "ring-1 ring-amber-400/60 " : "") +
                accent.soft
              }
            >
              <div className={"text-[12px] leading-none " + accent.text}>
                {entry.portrait.value}
              </div>
              <div className="text-[8px] text-slate-500 tabular-nums leading-none">
                {Math.round(entry.time)}
              </div>
            </div>
          );
        })}
        {alternate ? (
          <span className="text-[9px] text-amber-300/80 shrink-0 ml-1">after plan</span>
        ) : null}
      </div>
    );
  }
  return (
    <div>
      <p className="text-[10px] uppercase tracking-wider text-slate-500 mb-1">{title}</p>
      <div className="flex gap-1 overflow-x-auto pb-1">
        {timeline.map((entry) => {
          const accent = accentOf(entry.teamAccent);
          return (
            <div
              key={entry.order}
              title={
                entry.name +
                " - " +
                (entry.estimated ? "estimated" : "scheduled") +
                " at t=" +
                Math.round(entry.time)
              }
              className={
                "shrink-0 w-11 border rounded-sm px-1 py-1 text-center " +
                (entry.isActive ? "border-amber-300 " : "border-slate-800 ") +
                (entry.estimated ? "opacity-60 " : "") +
                accent.soft
              }
            >
              <div className={"text-sm leading-none " + accent.text}>{entry.portrait.value}</div>
              <div className="text-[9px] text-slate-400 leading-none mt-1">{entry.teamMarker}</div>
              <div className="text-[9px] text-slate-500 tabular-nums leading-none mt-1">
                {Math.round(entry.time)}
              </div>
            </div>
          );
        })}
      </div>
      {alternate ? (
        <div className="mt-2">
          <p className="text-[10px] uppercase tracking-wider text-amber-300/80 mb-1">
            After this action
          </p>
          <div className="flex gap-1 overflow-x-auto pb-1">
            {alternate.map((entry) => {
              const accent = accentOf(entry.teamAccent);
              return (
                <div
                  key={entry.order}
                  title={entry.name + " at t=" + Math.round(entry.time)}
                  className={
                    "shrink-0 w-11 border border-dashed rounded-sm px-1 py-1 text-center " +
                    (entry.highlighted ? "border-amber-300 " : "border-slate-700 ") +
                    accent.soft
                  }
                >
                  <div className={"text-sm leading-none " + accent.text}>
                    {entry.portrait.value}
                  </div>
                  <div className="text-[9px] text-slate-500 tabular-nums leading-none mt-1">
                    {Math.round(entry.time)}
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      ) : null}
      <p className="mt-1 text-[10px] text-slate-600">
        Solid entries are scheduled. Faded entries are estimates that assume a plain wait.
      </p>
    </div>
  );
}

function SpeedExplainer({ unit, recovery }) {
  if (!unit) return null;
  return (
    <div
      className="text-[11px] text-slate-400 space-y-0.5"
      title={
        "Higher Speed reduces recovery delay. Abilities and movement add recovery. " +
        "Fast units may act several times before slower units."
      }
    >
      <div className="flex justify-between">
        <span>Speed</span>
        <span className="tabular-nums text-slate-200">
          {Math.round(unit.stats.speed)}
          {unit.stats.speedMultiplier !== 1 ? " (x" + unit.stats.speedMultiplier + ")" : ""}
        </span>
      </div>
      <div className="flex justify-between">
        <span>Turn rate</span>
        <span className="tabular-nums text-slate-200">x{unit.stats.turnRate}</span>
      </div>
      {recovery ? (
        <React.Fragment>
          <div className="flex justify-between">
            <span>Action recovery</span>
            <span className="tabular-nums text-slate-200">{recovery.actionRecovery}</span>
          </div>
          <div className="flex justify-between">
            <span>Movement recovery</span>
            <span className="tabular-nums text-slate-200">{recovery.movementRecovery}</span>
          </div>
          <div className="flex justify-between">
            <span>Total recovery</span>
            <span className="tabular-nums text-slate-200">{recovery.totalRecovery}</span>
          </div>
          <div className="flex justify-between">
            <span>Next action at</span>
            <span className="tabular-nums text-amber-200">
              {Math.round(recovery.projectedNextActionTime)}
            </span>
          </div>
        </React.Fragment>
      ) : null}
    </div>
  );
}

function UnitInspector({ unit, showActivation }) {
  if (!unit) {
    return <p className="text-[11px] text-slate-500">Click any unit to inspect it.</p>;
  }
  const accent = accentOf(unit.teamAccent);
  return (
    <div className="space-y-2 text-[11px]">
      <div className="flex items-center gap-2">
        <div className={"border border-slate-800 rounded-sm p-1 " + accent.soft}>
          <AssetImage asset={unit.portrait} size={34} className={accent.text} alt={unit.name} />
        </div>
        <div>
          <p className={"text-xs " + accent.text}>
            {unit.name} <span className="text-slate-600">{unit.id}</span>
          </p>
          <p className="text-slate-500">
            {unit.teamMarker} {unit.teamName}
            {unit.controller === "ai" && unit.aiProfileId ? " - AI: " + unit.aiProfileId : ""}
          </p>
        </div>
      </div>
      {unit.description ? <p className="text-slate-500">{unit.description}</p> : null}
      <div className="flex justify-between text-slate-300 tabular-nums">
        <span>
          HP {unit.currentHp} / {unit.maxHp}
        </span>
        <span className="text-slate-500">next {Math.round(unit.nextActionTime)}</span>
      </div>
      <HealthBar unit={unit} />
      <div className="grid grid-cols-2 gap-x-3 gap-y-0.5 text-slate-400 tabular-nums">
        <span>Attack {unit.stats.attack}</span>
        <span>Magic {unit.stats.magic}</span>
        <span>Defense {unit.stats.defense}</span>
        <span>Resist {unit.stats.resistance}</span>
        <span>Accuracy {unit.stats.accuracy}</span>
        <span>Evasion {unit.stats.evasion}</span>
        <span>Speed {Math.round(unit.stats.speed)}</span>
        <span>Movement {unit.stats.movement}</span>
        <span>Max climb {unit.stats.maxClimb}</span>
        <span>Max drop {unit.stats.maxDrop}</span>
      </div>
      <StatusChips unit={unit} />
      <div className="space-y-0.5">
        {unit.abilities.map((ability) => (
          <div key={ability.abilityId} className="flex justify-between text-slate-400">
            <span>{ability.name}</span>
            <span className="text-slate-600">
              {ability.cooldownRemaining > 0 ? "cooldown " + ability.cooldownRemaining : "ready"}
            </span>
          </div>
        ))}
      </div>
      {showActivation && unit.activation ? (
        <div className="border-t border-slate-800 pt-1 text-slate-400">
          <p>
            Moved: {unit.activation.moved ? "yes" : "no"} - Acted:{" "}
            {unit.activation.acted ? "yes" : "no"}
          </p>
          <p>Movement recovery so far: {unit.activation.movementRecovery}</p>
        </div>
      ) : null}
    </div>
  );
}

function ResourceStrip({ resources, unit }) {
  if (!resources || !resources.active) return null;
  const cell = (label, value) => (
    <span
      className={
        "px-2 py-0.5 rounded-sm text-[10px] tracking-wider " +
        (value === "READY" ? "bg-emerald-500/15 text-emerald-200" : "bg-slate-800 text-slate-400")
      }
    >
      {label}: {value}
    </span>
  );
  return (
    <div className="flex flex-wrap items-center gap-2">
      {unit ? <span className="text-[11px] text-slate-300">{unit.name}</span> : null}
      {cell("MOVE", resources.moveLabel)}
      {cell("ACTION", resources.actionLabel)}
    </div>
  );
}

function ForecastSide({ side, align }) {
  if (!side) return null;
  const accent = accentOf(side.teamAccent);
  return (
    <div className={align === "right" ? "text-right" : ""}>
      <p className={"text-[11px] uppercase tracking-wider " + accent.text}>
        {side.teamMarker} {side.name}
      </p>
      <p className="text-[11px] text-slate-300 tabular-nums">
        {side.currentHp} / {side.maxHp} HP
      </p>
    </div>
  );
}

function ForecastPanel({ forecast, plan, compact }) {
  if (!forecast) return null;
  if (!forecast.valid) {
    return (
      <div className="text-[11px] text-rose-300">
        {(forecast.errors || ["No legal target."]).join(" ")}
      </div>
    );
  }
  const headline = forecast.headline;
  const recovery = forecast.recovery;
  return (
    <div className="space-y-1" style={compact ? null : { minWidth: 240 }}>
      <div className="flex items-start justify-between gap-4">
        <ForecastSide side={forecast.source} />
        <ForecastSide side={forecast.target} align="right" />
      </div>
      {plan && plan.requiresMovement ? (
        <p className="text-[11px] text-sky-300">
          Move to {plan.destination.x},{plan.destination.y} ({plan.destination.tiles} tiles), then
          use {forecast.abilityName}
        </p>
      ) : (
        <p className="text-[11px] text-slate-300">{forecast.abilityName}</p>
      )}
      <div className="flex items-end gap-4">
        <div>
          <p className="text-[10px] uppercase tracking-[0.2em] text-slate-500">{headline.label}</p>
          <p
            className={
              "text-3xl leading-none font-bold " +
              (headline.kind === "heal" ? "text-emerald-300" : "text-rose-300")
            }
          >
            {headline.value == null ? "-" : headline.value}
          </p>
        </div>
        {headline.hitChancePercent != null ? (
          <div>
            <p className="text-[10px] uppercase tracking-[0.2em] text-slate-500">HIT</p>
            <p className="text-2xl leading-none font-bold text-amber-200">
              {headline.hitChancePercent}%
            </p>
          </div>
        ) : null}
        {headline.note ? (
          <span className="px-2 py-0.5 bg-rose-500 text-slate-950 text-[10px] font-bold rounded-sm">
            {headline.note}
          </span>
        ) : null}
      </div>
      {headline.targetHpAfter != null ? (
        <p className="text-[11px] text-slate-400 tabular-nums">
          Target HP: {headline.targetHp} to {headline.targetHpAfter} / {headline.targetMaxHp}
        </p>
      ) : null}
      {forecast.lines.map((line, index) => (
        <p key={index} className="text-[11px] text-slate-400">
          <span className="text-amber-200">{line.label} {line.value}</span>{" "}
          <span className="text-slate-600">{line.detail}</span>
        </p>
      ))}
      <div className="border-t border-slate-800 pt-1 text-[11px] text-slate-500 tabular-nums">
        <p>
          Recovery {recovery.totalRecovery} (action {recovery.actionRecovery} + movement{" "}
          {recovery.movementRecovery})
        </p>
        <p>Next action at {Math.round(recovery.projectedNextActionTime)}</p>
      </div>
    </div>
  );
}

function DestinationForecastPanel({ destination, entries, recovery }) {
  if (!destination) return null;
  return (
    <div className="text-[11px] space-y-1" style={{ minWidth: 240 }}>
      <p className="text-slate-100">
        Move to {destination.x},{destination.y} - {destination.tiles} tiles
      </p>
      {recovery ? (
        <p className="text-slate-500 tabular-nums">
          Movement recovery {recovery.movementRecovery} - next action{" "}
          {Math.round(recovery.projectedNextActionTime)} if you stop there
        </p>
      ) : null}
      <p className="text-[10px] uppercase tracking-wider text-slate-500">From this tile</p>
      {(entries || []).map((entry) => (
        <div key={entry.abilityId} className="text-slate-400">
          {entry.forecasts.length ? (
            <p>
              <span className="text-slate-200">{entry.name}</span> vs{" "}
              {entry.forecasts[0].target.name}:{" "}
              <span
                className={
                  entry.forecasts[0].headline.kind === "heal"
                    ? "text-emerald-300 font-bold"
                    : "text-rose-300 font-bold"
                }
              >
                {entry.forecasts[0].headline.value}
              </span>
              {entry.forecasts[0].headline.hitChancePercent != null
                ? " at " + entry.forecasts[0].headline.hitChancePercent + "%"
                : ""}
              {entry.forecasts.length > 1 ? (
                <span className="text-slate-600"> (+{entry.forecasts.length - 1} more)</span>
              ) : null}
            </p>
          ) : (
            <p className="text-slate-600">
              {entry.name}: {entry.usable ? "no target in range" : entry.unusableReason}
            </p>
          )}
        </div>
      ))}
    </div>
  );
}

function BattleLogPanel({ groups, filterId, onFilter }) {
  const filters = ["all", "damage", "healing", "statuses", "timeline", "movement", "defeats", "vetoes", "orders"];
  return (
    <div>
      <div className="flex flex-wrap gap-1 mb-2">
        {filters.map((id) => (
          <button
            key={id}
            onClick={() => onFilter(id)}
            className={
              "px-2 py-0.5 text-[10px] uppercase tracking-wider rounded-sm " +
              (filterId === id
                ? "bg-amber-400 text-slate-950"
                : "text-slate-400 hover:text-slate-200")
            }
          >
            {id}
          </button>
        ))}
      </div>
      <ol className="space-y-2 text-[11px] max-h-72 overflow-auto pr-1">
        {groups
          .slice()
          .reverse()
          .map((group) => (
            <li key={group.key}>
              <p className="text-slate-300">
                <span className="text-slate-600 tabular-nums">Time {Math.round(group.time)}</span> -{" "}
                {group.headline}
              </p>
              <ul className="mt-0.5 space-y-0.5">
                {group.entries.map((entry) => (
                  <li key={entry.key} className="text-slate-500">
                    {"\u2022 " + entry.text}
                  </li>
                ))}
              </ul>
            </li>
          ))}
      </ol>
    </div>
  );
}

function BattleEndScreen({ summary, onReport, onReplaySameSeed, onReplayNewSeed, onOpenDebug }) {
  return (
    <div
      style={{
        position: "relative",
        border: "1px solid " + CINEMATIC_COLORS.borderBright,
        background: "rgba(4,12,21,0.97)",
        boxShadow: "0 30px 100px rgba(0,0,0,0.65)"
      }}
      className="p-8"
    >
      <FrameCorners />
      <p className="text-[12px] uppercase tracking-[0.34em] text-sky-300/70">After-action report</p>
      <h2 className={"mt-3 text-[42px] font-black uppercase tracking-[0.08em] " + (summary.playerVictory ? "text-emerald-300" : "text-rose-300")}>
        {summary.playerVictory ? "Victory" : "Defeat"}
      </h2>
      <div className="mt-7 grid grid-cols-[1fr_1fr] gap-8">
        <div className="grid grid-cols-2 gap-x-8 gap-y-3 text-[13px] text-slate-400 tabular-nums">
          <span>Winner</span><span className="text-slate-100">{summary.winnerName || summary.winner}</span>
          <span>Activations</span><span className="text-slate-100">{summary.activationCount}</span>
          <span>Battle time</span><span className="text-slate-100">{summary.finalTime}</span>
          <span>Total damage</span><span className="text-slate-100">{summary.totalDamage}</span>
          <span>Total healing</span><span className="text-slate-100">{summary.totalHealing}</span>
          <span>Misses</span><span className="text-slate-100">{summary.misses}</span>
        </div>
        <div className="grid grid-cols-2 gap-5 text-[12px]">
          <div><p className="mb-2 uppercase tracking-[0.2em] text-slate-500">Survivors</p>{summary.survivors.map((unit) => <p key={unit.id} className={accentOf(unit.teamAccent).text}>{unit.teamMarker} {unit.name} · {unit.currentHp}/{unit.maxHp}</p>)}</div>
          <div><p className="mb-2 uppercase tracking-[0.2em] text-slate-500">Defeated</p>{summary.defeated.map((unit) => <p key={unit.id} className="text-slate-600 line-through">{unit.teamMarker} {unit.name}</p>)}</div>
        </div>
      </div>
      <div className="mt-8 flex flex-wrap justify-end gap-3">
        {onReport ? <Button tone="primary" onClick={onReport}>Report to command</Button> : null}
        <Button tone="primary" onClick={onReplaySameSeed}>Replay same seed</Button>
        <Button onClick={onReplayNewSeed}>Replay new seed</Button>
        <Button onClick={onOpenDebug}>Debug report</Button>
      </div>
    </div>
  );
}

function ChecklistPanel({ checklist }) {
  const items = [
    ["startEncounter", "Start encounter"],
    ["selectUnit", "Select active player unit"],
    ["previewMovement", "Preview movement"],
    ["confirmMovement", "Confirm movement"],
    ["selectAbility", "Select ability"],
    ["previewTarget", "Preview target"],
    ["confirmAttack", "Confirm attack"],
    ["enemyActivation", "Observe enemy activation"],
    ["fastRepeat", "Observe fast unit repeat on timeline"],
    ["healing", "Observe healing"],
    ["poison", "Observe poison application and trigger"],
    ["timelineDelay", "Observe timeline delay"],
    ["finishBattle", "Finish battle"],
    ["replaySameSeed", "Replay same seed"]
  ];
  return (
    <ul className="text-[11px] space-y-0.5">
      {items.map((item) => (
        <li key={item[0]} className={checklist[item[0]] ? "text-emerald-300" : "text-slate-500"}>
          {(checklist[item[0]] ? "[x] " : "[ ] ") + item[1]}
        </li>
      ))}
    </ul>
  );
}

function ValidationPanel({ state }) {
  const content = validateContent();
  const battle = validateBattleState(state);
  const assets = validateAssets();
  const rows = [
    { label: "Content errors", items: content.errors },
    { label: "Content warnings", items: content.warnings },
    { label: "Battle state errors", items: battle.errors },
    { label: "Missing asset references", items: assets.missing }
  ];
  return (
    <div className="space-y-3 text-[11px]">
      {rows.map((row) => (
        <div key={row.label}>
          <p className="text-slate-400">
            {row.label}:{" "}
            <span className={row.items.length ? "text-rose-300" : "text-emerald-300"}>
              {row.items.length}
            </span>
          </p>
          <ul className="mt-1 space-y-0.5 text-slate-400">
            {row.items.slice(0, 20).map((item, index) => (
              <li key={index}>{"- " + item}</li>
            ))}
          </ul>
        </div>
      ))}
      <p className="text-slate-600">
        {assets.unsourced.length} of {assets.total} assets are placeholder glyphs or colors.
      </p>
    </div>
  );
}

function TestPanel({ results, audit, onRun, running }) {
  return (
    <div className="text-[11px] space-y-3">
      <div className="flex items-center gap-2">
        <Button onClick={onRun} disabled={running} tone="primary">
          {running ? "Running" : "Run tests + audit"}
        </Button>
        {results ? (
          <span className="text-slate-400 tabular-nums">
            {results.passed}/{results.total} passing
            {results.failed ? " - " + results.failed + " failing" : ""}
          </span>
        ) : (
          <span className="text-slate-500">Not run in this session yet.</span>
        )}
      </div>
      {audit ? (
        <div>
          <p className={audit.pass ? "text-emerald-300" : "text-rose-300"}>{audit.summary}</p>
          <ul className="mt-1 space-y-0.5">
            {audit.checks.map((check) => (
              <li key={check.label} className="flex gap-2">
                <span className={check.ok ? "text-emerald-400" : "text-rose-400"}>
                  {check.ok ? "pass" : "fail"}
                </span>
                <span className="text-slate-400">{check.label}</span>
                {check.detail ? <span className="text-slate-600">{check.detail}</span> : null}
              </li>
            ))}
          </ul>
        </div>
      ) : null}
      {results ? (
        <ul className="space-y-0.5 max-h-72 overflow-auto">
          {results.results.map((result, index) => (
            <li key={index} className="flex gap-2">
              <span className={result.ok ? "text-emerald-400" : "text-rose-400"}>
                {result.ok ? "pass" : "fail"}
              </span>
              <span className="text-slate-600 w-44 shrink-0">{result.group}</span>
              <span className="text-slate-300">{result.name}</span>
              {result.error ? <span className="text-rose-300">{result.error}</span> : null}
            </li>
          ))}
        </ul>
      ) : null}
    </div>
  );
}

function CommandValidation({ state, view }) {
  const unitId = view.selectedUnitId || view.nextUnitId;
  if (!unitId) return <p className="text-[11px] text-slate-500">No unit to inspect.</p>;
  const unit = view.units.find((entry) => entry.id === unitId);
  const probes = [{ label: "wait", command: { type: "wait", unitId } }];
  for (const ability of unit.abilities) {
    for (const other of view.units) {
      if (!other.alive) continue;
      probes.push({
        label: ability.name + " to " + other.id,
        command: {
          type: "useAbility",
          unitId,
          abilityId: ability.abilityId,
          target: { unitId: other.id }
        }
      });
    }
  }
  return (
    <div>
      <p className="text-[11px] text-slate-400 mb-2">
        validateCommand() for {unit.name} [{unitId}]
      </p>
      <ul className="space-y-0.5 text-[11px] max-h-64 overflow-auto">
        {probes.map((probe, index) => {
          const result = validateCommand(state, probe.command);
          return (
            <li key={index} className="flex gap-2">
              <span className={result.valid ? "text-emerald-400" : "text-slate-600"}>
                {result.valid ? "ok " : "no "}
              </span>
              <span className="text-slate-300 w-40 shrink-0">{probe.label}</span>
              <span className="text-slate-500">
                {result.valid
                  ? "recovery " + (result.preview.totalRecovery || result.preview.recovery || 0)
                  : result.errors[0]}
              </span>
            </li>
          );
        })}
      </ul>
    </div>
  );
}

function StateInspector({ state }) {
  const snapshot = {
    id: state.id,
    encounterId: state.encounterId,
    currentTime: Math.round(state.currentTime * 100) / 100,
    activeUnitId: state.activeUnitId,
    activation: state.activation,
    activationCount: state.activationCount,
    randomSeed: state.randomSeed,
    randomState: state.randomState,
    objectiveState: state.objectiveState,
    winner: state.winner,
    finished: state.finished,
    queuedEvents: state.resolutionQueue.length,
    engineErrors: state.errors,
    units: state.unitOrder.map((id) => state.units[id])
  };
  return (
    <pre className="text-[10px] text-slate-400 max-h-96 overflow-auto whitespace-pre-wrap">
      {JSON.stringify(snapshot, null, 2)}
    </pre>
  );
}

/**
 * What each faction believes, side by side.
 *
 * The single most useful thing to have on screen while authoring a stealth
 * beat: whether the garrison has actually lost you, or is standing on your
 * last-known tile about to find you again. Read-only — it renders the
 * authoritative record and computes nothing.
 */
function KnowledgePanel({ state }) {
  const model = state.perception ? describePerception(state, perceptionDeps()) : null;
  if (!model) return <p className="text-[11px] text-slate-500">This battle has no knowledge model.</p>;
  if (!model.enabled) {
    return (
      <p className="text-[11px] text-amber-300">
        Knowledge is disabled for this battle — every faction sees everything.
      </p>
    );
  }

  const tone = { acquired: "text-rose-300", suspected: "text-amber-300", unseen: "text-slate-600" };
  return (
    <div className="space-y-3">
      {Object.keys(model.factions).map((factionId) => {
        const faction = model.factions[factionId];
        const runtime = state.perception.factions[factionId] || {};
        return (
          <div key={factionId} className="border border-slate-800 p-2">
            <div className="mb-1 flex items-baseline justify-between">
              <span className="text-[11px] uppercase tracking-widest text-slate-300">
                {teamLabel(state, factionId)}
              </span>
              <span className="text-[10px] tabular-nums text-slate-500">
                clock {runtime.clock || 0} · {faction.acquired} acquired · {faction.suspected} contact
                {faction.suspected === 1 ? "" : "s"}
                {runtime.withoutSolutionFor ? " · " + runtime.withoutSolutionFor + " without a solution" : ""}
              </span>
            </div>
            {faction.contacts.length === 0 ? (
              <p className="text-[10px] text-slate-600">Nothing known.</p>
            ) : (
              <table className="w-full text-[10px] tabular-nums">
                <tbody>
                  {faction.contacts.map((record) => (
                    <tr key={record.unitId} className="border-t border-slate-900">
                      <td className="py-0.5 text-slate-400">{unitLabel(state, record.unitId)}</td>
                      <td className={"py-0.5 " + (tone[record.state] || "text-slate-400")}>
                        {record.state}
                      </td>
                      <td className="py-0.5 text-slate-500">
                        {record.x == null ? "—" : record.x + "," + record.y}
                        {record.accuracy === "approximate" ? " ±" : ""}
                      </td>
                      <td className="py-0.5 text-slate-600">
                        {record.channels.length ? record.channels.join("+") : record.source}
                      </td>
                      <td className="py-0.5 text-slate-600">
                        {record.investigated ? "searched" : ""}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
            {runtime.searchAnchor ? (
              <p className="mt-1 text-[10px] text-slate-600">
                Sweeping toward {runtime.searchAnchor.x},{runtime.searchAnchor.y}
              </p>
            ) : null}
          </div>
        );
      })}
      <p className="text-[10px] text-slate-600">
        A contact is a place to go. Only an acquired record can be shot at.
      </p>
    </div>
  );
}

const DEV_TABS = [
  { id: "controls", label: "Controls" },
  { id: "checklist", label: "Playthrough" },
  { id: "tests", label: "Tests + audit" },
  { id: "validation", label: "Validation" },
  { id: "commands", label: "Commands" },
  { id: "knowledge", label: "Knowledge" },
  { id: "state", label: "State" }
];

function DeveloperTools(props) {
  const { state, view, seed, checklist, testResults, audit, devTab, notice } = props;
  return (
    <Panel
      title="Developer tools"
      right={
        <div className="flex flex-wrap gap-1">
          {DEV_TABS.map((tab) => (
            <button
              key={tab.id}
              onClick={() => props.onDevTab(tab.id)}
              className={
                "px-2 py-0.5 text-[10px] uppercase tracking-wider rounded-sm " +
                (devTab === tab.id
                  ? "bg-amber-400 text-slate-950"
                  : "text-slate-400 hover:text-slate-200")
              }
            >
              {tab.label}
            </button>
          ))}
        </div>
      }
    >
      {devTab === "controls" ? (
        <div className="space-y-2">
          <div className="flex flex-wrap items-center gap-2">
            <label className="text-[10px] uppercase tracking-wider text-slate-500">
              Seed
              <input
                type="number"
                value={seed}
                onChange={(event) => props.onSeed(event.target.value)}
                className="ml-2 w-24 bg-slate-900 border border-slate-700 px-2 py-1 text-xs text-slate-200 rounded-sm"
              />
            </label>
            <Button tone="primary" onClick={props.onStart}>
              Start test battle
            </Button>
            <Button onClick={props.onStep}>Run one activation</Button>
            <Button onClick={props.onRunUntilPlayer}>Run until player turn</Button>
            <Button onClick={props.onRunAi}>Run AI vs AI x10</Button>
            <Button onClick={props.onRunFull}>Run full battle</Button>
            <Button onClick={props.onReset}>Reset battle</Button>
          </div>
          <p className="text-[11px] text-slate-500">{notice}</p>
          <p className="text-[10px] text-slate-600">
            These controls drive the engine directly and bypass the player interface.
          </p>
        </div>
      ) : null}
      {devTab === "checklist" ? (
        <div className="space-y-2">
          <p className="text-[10px] text-slate-500 uppercase tracking-wider">
            Manual playthrough verification
          </p>
          <ChecklistPanel checklist={checklist} />
          <p className="text-[10px] text-slate-600">
            Items tick only when the matching action actually happens in this session.
          </p>
        </div>
      ) : null}
      {devTab === "tests" ? (
        <TestPanel
          results={testResults}
          audit={audit}
          onRun={props.onRunTests}
          running={props.running}
        />
      ) : null}
      {devTab === "validation" ? <ValidationPanel state={state} /> : null}
      {devTab === "commands" ? <CommandValidation state={state} view={view} /> : null}
      {devTab === "knowledge" ? <KnowledgePanel state={state} /> : null}
      {devTab === "state" ? <StateInspector state={state} /> : null}
    </Panel>
  );
}

/* ---------------------------------------------------------------
 * ROOT
 * -------------------------------------------------------------*/


function CameraControls({ zoom, onZoomIn, onZoomOut, onFit, onFocus, showElevation, onToggleElevation, showIntel, onToggleIntel }) {
  return (
    <div
      style={{
        position: "absolute",
        right: 46,
        bottom: 88,
        zIndex: 35,
        border: "1px solid " + CINEMATIC_COLORS.border,
        background: "rgba(4,12,21,0.9)"
      }}
      className="flex items-center gap-1 p-1.5 shadow-xl"
    >
      <Button size="sm" onClick={onZoomOut} title="Zoom out">−</Button>
      <span className="w-14 text-center text-[11px] tabular-nums text-slate-300">{Math.round(zoom * 100)}%</span>
      <Button size="sm" onClick={onZoomIn} title="Zoom in">+</Button>
      <Button size="sm" onClick={onFit}>Fit</Button>
      <Button size="sm" onClick={onFocus}>Focus</Button>
      <Button size="sm" tone={showElevation ? "primary" : "ghost"} onClick={onToggleElevation}>Elev</Button>
      <Button
        size="sm"
        tone={showIntel ? "primary" : "ghost"}
        onClick={onToggleIntel}
        title="Show where your squad last had eyes on a contact"
      >
        Intel
      </Button>
    </div>
  );
}

function TopHud({ hud, timeline, alternate, speedId, onSpeed, onSkip, onToggleDetails, onToggleDev, devOpen, height }) {
  const hostileTeam = (hud.teams || []).find((team) => team.controller === "ai") || null;
  const friendlyTeam = (hud.teams || []).find((team) => team.controller === "human") || null;
  return (
    <header style={{ height }} className="pointer-events-none absolute inset-x-0 top-0 z-40">
      <div
        className="pointer-events-auto absolute left-12 top-7 w-[420px] border border-sky-300/35 bg-slate-950/92 px-7 py-5 shadow-[0_20px_50px_rgba(0,0,0,0.35)]"
      >
        <FrameCorners />
        <p className="text-[11px] uppercase tracking-[0.36em] text-sky-300/75">Operation</p>
        <p className="mt-2 text-[18px] font-black uppercase tracking-[0.04em] text-slate-100">{hud.encounterName}</p>
        <div className="mt-4 space-y-1 text-[11px] uppercase tracking-[0.22em] text-slate-300">
          <p>• {hud.objective}</p>
          {hostileTeam ? <p>• Defeat all hostiles · {hostileTeam.aliveCount} left</p> : null}
          {friendlyTeam ? <p>• {friendlyTeam.name || friendlyTeam.id} must survive</p> : null}
        </div>
      </div>

      <div className="pointer-events-auto absolute left-1/2 top-8 -translate-x-1/2 text-center">
        <div className="mb-2 flex items-end justify-center gap-5 text-[11px] uppercase tracking-[0.34em] text-slate-500">
          <span>Turn {hud.activationCount}</span>
          <span className="text-sky-300/85">Now</span>
          <span>t {hud.currentTime}</span>
        </div>
        <div className="mx-auto border border-sky-300/25 bg-slate-950/85 px-4 py-3 shadow-[0_18px_50px_rgba(0,0,0,0.28)]">
          <TimelineRail timeline={timeline} alternate={alternate} compact />
        </div>
      </div>

      <div className="pointer-events-auto absolute right-12 top-7 flex items-center gap-2">
        <select
          value={speedId}
          onChange={(event) => onSpeed(event.target.value)}
          className="h-12 border border-slate-600 bg-slate-950/90 px-3 text-[11px] uppercase tracking-[0.22em] text-slate-100"
          title="Animation speed"
        >
          {Object.keys(GAME_CONFIG.presentation.speeds).map((id) => <option key={id} value={id}>{GAME_CONFIG.presentation.speeds[id].name}</option>)}
        </select>
        <Button size="sm" onClick={onSkip}>Skip</Button>
        <Button size="sm" onClick={onToggleDetails}>Log</Button>
        <Button size="sm" tone={devOpen ? "primary" : "ghost"} onClick={onToggleDev}>Debug</Button>
      </div>
    </header>
  );
}

function SideUnitCard({ card, active, activeResources, threat, onThreatAbility, onDetails, width, top, bottom }) {
  if (!card) return null;
  const accent = accentOf(card.teamAccent);
  return (
    <aside
      style={{
        position: "absolute",
        right: 54,
        top: 208,
        width: 310,
        zIndex: 38,
        border: "1px solid " + CINEMATIC_COLORS.borderBright,
        background: "rgba(4,12,21,0.95)",
        boxShadow: "0 26px 70px rgba(0,0,0,0.45)"
      }}
      className="overflow-hidden"
    >
      <FrameCorners />
      <div className="flex gap-3 border-b border-sky-300/15 p-4">
        <div className={"h-20 w-20 shrink-0 border border-slate-700 bg-slate-950/80 " + accent.soft}>
          <AssetImage asset={card.portrait} width="100%" height="100%" className={accent.text + " h-full w-full"} alt={card.name} />
        </div>
        <div className="min-w-0 flex-1">
          <p className={"truncate text-[15px] font-black uppercase tracking-[0.06em] " + accent.text}>{card.name}</p>
          <p className="mt-1 text-[10px] uppercase tracking-[0.18em] text-slate-500">{card.teamMarker} {card.teamName}</p>
          <p className="mt-3 text-[11px] tabular-nums text-slate-200">HP {card.currentHp} / {card.maxHp}</p>
          <HealthBar unit={card} className="mt-1 h-[6px]" />
        </div>
      </div>
      <div className="space-y-3 p-4 text-[10px]">
        <div className="grid grid-cols-2 gap-x-4 gap-y-1 text-slate-400 tabular-nums">
          <span>SPD {card.speedLabel}</span><span>NEXT {Math.round(card.nextActionTime)}</span>
          <span>MOV {card.stats.movement}</span><span>ELEV {card.elevation}</span>
        </div>
        {card.resources.active ? <ResourceStrip resources={card.resources} /> : null}
        {card.statusLabels.length ? <div className="space-y-1">{card.statusLabels.slice(0, 3).map((label) => <p key={label} className="text-amber-200">{label}</p>)}</div> : null}
        {threat ? (
          <div className="border-t border-sky-300/15 pt-3">
            <p className="text-[10px] uppercase tracking-[0.22em] text-rose-300">Threat</p>
            <p className="mt-1 text-slate-500">{threat.immediateCount} now · {threat.potentialCount} after move</p>
            {threat.abilities.slice(0, 3).map((entry) => (
              <button key={entry.abilityId} onClick={() => onThreatAbility(entry.abilityId)} className="mt-1 block w-full text-left text-slate-400 hover:text-sky-200">{entry.name} · {entry.rangeLabel}</button>
            ))}
          </div>
        ) : null}
        <div className="flex justify-end"><Button size="sm" onClick={onDetails}>Inspect</Button></div>
      </div>
    </aside>
  );
}

function BottomStrip({ notice, error, logGroups, onExpand, height }) {
  const latest = logGroups.length ? logGroups[logGroups.length - 1] : null;
  return (
    <footer
      style={{
        position: "absolute",
        left: 54,
        right: 54,
        bottom: 10,
        zIndex: 34,
        height: 34,
        border: "1px solid rgba(125,183,226,0.16)",
        background: "rgba(4,12,21,0.74)"
      }}
      className="flex items-center gap-4 px-4"
    >
      <p className={(error ? "text-rose-300 " : "text-slate-400 ") + "min-w-0 flex-1 truncate text-[10px] uppercase tracking-[0.2em]"}>{error || notice}</p>
      <button onClick={onExpand} className="text-[10px] uppercase tracking-[0.22em] text-sky-300/80 hover:text-sky-100">Log</button>
    </footer>
  );
}

function HoverBadge({ badge, position }) {
  if (!badge) return null;
  return (
    <div
      style={{ ...createPanelStyle("secondary"), left: position.left, top: position.top, maxWidth: 200 }}
      className="absolute z-40 pointer-events-none border px-2 py-1 rounded-sm"
    >
      <p className="text-[10px] text-slate-300">{badge.title}</p>
      <p
        className={
          "text-[12px] font-bold " +
          (badge.kind === "heal"
            ? "text-emerald-300"
            : badge.kind === "move"
            ? "text-sky-300"
            : badge.lethal
            ? "text-rose-400"
            : "text-rose-300")
        }
      >
        {badge.value}
      </p>
    </div>
  );
}

/**
 * The route breakdown: every leg, what each turn cost, who gets hit, and where
 * exactly they end up. The numbers are the planner's, not the panel's.
 */
/**
 * The command panel: who is coming, who may be moved, and what order results.
 *
 * The mechanic lives or dies on this being readable. A player who has to
 * decode timestamps to know what they just bought has not been given a
 * commander, they have been given a spreadsheet — so nothing here shows a
 * number that is not a position.
 */
function OrderSummary({ order, onPick }) {
  const chip = (label, tone) => (
    <span className={"px-1 py-0.5 text-[9px] uppercase tracking-wider rounded-sm " + tone}>
      {label}
    </span>
  );
  const resulting = order.resultingOrder
    .map((unitId) => order.entries.find((entry) => entry.unitId === unitId))
    .filter(Boolean);

  return (
    <div className="px-2 py-2 space-y-2 border-b border-slate-800">
      <div>
        <p className="text-[9px] uppercase tracking-[0.2em] text-slate-500 mb-1">Upcoming</p>
        <ul className="space-y-0.5">
          {order.entries.map((entry) => (
            <li key={entry.unitId}>
              <button
                onClick={() => (entry.eligible ? onPick(entry.unitId) : null)}
                disabled={!entry.eligible}
                title={entry.reason || ""}
                className={
                  "flex w-full items-center gap-2 px-1.5 py-1 text-left text-[11px] transition border " +
                  (entry.selected
                    ? "border-amber-300/60 bg-amber-950/40 text-amber-100"
                    : entry.eligible
                    ? "border-slate-800 hover:border-amber-300/40 hover:bg-slate-900 text-slate-200"
                    : "border-transparent text-slate-600 cursor-not-allowed")
                }
              >
                <span className="w-4 text-center tabular-nums text-[10px]">
                  {entry.selected ? entry.selectedIndex : entry.eligible ? "·" : "—"}
                </span>
                <span className="w-4 text-center">{entry.glyph}</span>
                <span className="flex-1 truncate">{entry.name}</span>
                {entry.hostile ? chip("enemy", "bg-rose-500/15 text-rose-200") : null}
                {!entry.eligible && entry.reason ? (
                  <span className="text-[9px] text-slate-600 truncate max-w-[150px]">{entry.reason}</span>
                ) : null}
              </button>
            </li>
          ))}
        </ul>
      </div>

      {order.selectedOrder.length ? (
        <div>
          <p className="text-[9px] uppercase tracking-[0.2em] text-emerald-400/80 mb-1">
            Resulting order
          </p>
          <ol className="flex flex-wrap gap-1">
            {resulting.map((entry, index) => (
              <li
                key={entry.unitId}
                className={
                  "px-1.5 py-0.5 text-[10px] border " +
                  (entry.selected
                    ? "border-emerald-400/50 bg-emerald-950/40 text-emerald-100"
                    : "border-slate-800 text-slate-500")
                }
              >
                <span className="tabular-nums text-slate-500 mr-1">{index + 1}</span>
                {entry.name}
              </li>
            ))}
          </ol>
        </div>
      ) : null}
    </div>
  );
}

function RouteSummary({ route, onDisplace }) {
  return (
    <div className="px-2 py-1 space-y-1 border-b border-slate-800">
      {route.empty ? (
        <p className="text-[10px] text-slate-500">
          Click a tile in line with the frame to lay the first leg.
        </p>
      ) : null}

      {route.segments.map((segment) => (
        <p key={segment.index} className="flex items-center gap-1 text-[10px]">
          <span className="text-slate-600 tabular-nums">{segment.index + 1}</span>
          <span className="uppercase tracking-wider text-slate-300">{segment.heading}</span>
          <span className="tabular-nums text-slate-400">{segment.distance}</span>
          {segment.redirect ? (
            <span className="px-1 rounded-sm bg-sky-500/15 text-sky-200">{segment.redirect}</span>
          ) : null}
          {segment.blocked ? (
            <span className="ml-auto text-rose-300 truncate" title={segment.blockReason}>
              {segment.blockReason}
            </span>
          ) : null}
        </p>
      ))}

      {route.cost.breakdown.map((entry) => (
        <p key={entry.category} className="flex justify-between text-[10px] text-slate-500">
          <span>
            {entry.count}× {entry.category}
          </span>
          <span className="tabular-nums">
            {entry.amount} {route.cost.resourceName}
          </span>
        </p>
      ))}
      {route.cost.resourceId && route.cost.remaining != null ? (
        <p
          className={
            "flex justify-between text-[10px] " +
            (route.cost.affordable ? "text-slate-400" : "text-rose-300")
          }
        >
          <span>After the route</span>
          <span className="tabular-nums">
            {Math.max(0, route.cost.remaining)} {route.cost.resourceName}
          </span>
        </p>
      ) : null}

      {route.contacts.map((contact) => (
        <div key={contact.segment} className="pt-1 border-t border-slate-900">
          <p className="flex items-center gap-1 text-[10px]">
            <span className="text-amber-200 truncate">{contact.targetName}</span>
            {contact.inReach ? null : (
              <span className="ml-auto text-rose-300">{contact.reachReason}</span>
            )}
          </p>
          {contact.maxDisplacement > 0 ? (
            <div className="mt-0.5 space-y-0.5">
              <div className="flex items-center gap-1">
                {["n", "e", "s", "w"].map((heading) => (
                  <button
                    key={heading}
                    onClick={() => onDisplace(contact.segment, { heading })}
                    className={
                      "px-1 rounded-sm text-[9px] uppercase " +
                      (contact.displacement && contact.displacement.heading === heading
                        ? "bg-amber-400/25 text-amber-100"
                        : "bg-slate-800 text-slate-400 hover:bg-slate-700")
                    }
                  >
                    {heading}
                  </button>
                ))}
                <span className="ml-auto text-[9px] text-slate-600">push</span>
              </div>
              <div className="flex items-center gap-1">
                {Array.from({ length: contact.maxDisplacement + 1 }, (_, distance) => (
                  <button
                    key={distance}
                    onClick={() => onDisplace(contact.segment, { distance })}
                    className={
                      "px-1 rounded-sm text-[9px] tabular-nums " +
                      (contact.displacement && contact.displacement.requested === distance
                        ? "bg-amber-400/25 text-amber-100"
                        : "bg-slate-800 text-slate-400 hover:bg-slate-700")
                    }
                  >
                    {distance}
                  </button>
                ))}
                <span className="ml-auto text-[9px] text-slate-600">
                  max {contact.maxDisplacement}
                </span>
              </div>
              {contact.displacement ? (
                <p className="flex justify-between text-[10px] text-slate-400">
                  <span>
                    {contact.displacement.actual} of {contact.displacement.requested}
                    {contact.displacement.resisted
                      ? " (−" + contact.displacement.resisted + " braced)"
                      : ""}
                  </span>
                  <span className="tabular-nums text-slate-200">
                    {contact.displacement.endpoint.x},{contact.displacement.endpoint.y}
                  </span>
                </p>
              ) : null}
              {contact.displacement && contact.displacement.blocked ? (
                <p className="text-[10px] text-rose-300">{contact.displacement.blockReason}</p>
              ) : null}
            </div>
          ) : null}
        </div>
      ))}

      {!route.legal && !route.empty ? (
        <p className="text-[10px] text-rose-300">{route.reason}</p>
      ) : null}
    </div>
  );
}

/**
 * The chain the player is about to commit to: who it reaches, in what order,
 * how far each arc jumps, what it costs, and where it gives up. Every number
 * is the planner's or the forecaster's.
 */
function ChainSummary({ chain }) {
  return (
    <div className="px-2 py-1 space-y-0.5 border-b border-slate-800">
      <p className="flex justify-between text-[11px] text-slate-400">
        <span>Reaches</span>
        <span className="tabular-nums text-slate-200">
          {chain.reached}
          {chain.lethalCount ? " · " + chain.lethalCount + " lethal" : ""}
        </span>
      </p>

      {chain.nodes.map((node) => (
        <p key={node.unitId} className="flex items-center gap-1 text-[10px]">
          <span
            className={
              "px-1 rounded-sm tabular-nums " +
              (node.lethal ? "bg-pink-500/25 text-pink-100" : "bg-sky-500/20 text-sky-100")
            }
          >
            {node.hop + 1}
          </span>
          <span className="text-slate-300 truncate">{node.name}</span>
          {node.hop ? (
            <span className="text-slate-600">+{node.distance}</span>
          ) : (
            <span className="text-slate-600">aimed</span>
          )}
          {node.amount != null ? (
            <span className="ml-auto tabular-nums text-rose-300">{node.amount}</span>
          ) : null}
        </p>
      ))}

      {chain.costs.map((cost) => (
        <p
          key={cost.resourceId}
          className={
            "flex justify-between text-[10px] " +
            (cost.affordable ? "text-slate-500" : "text-rose-300")
          }
        >
          <span>{cost.name}</span>
          <span className="tabular-nums">
            −{cost.amount}
            {cost.remaining == null ? "" : " · " + Math.max(0, cost.remaining) + " left"}
          </span>
        </p>
      ))}

      <p className="text-[10px] text-slate-500">Stops: {chain.termination}</p>
    </div>
  );
}

function FloatingPanel({ model, position, abilities, onAction, onAbility, onContextOption, onRouteDisplace, onOrderPick, width }) {
  if (!model.visible) return null;
  const forecast = model.forecast;
  return (
    <div
      style={{ ...createPanelStyle("primary"), left: position.left, top: position.top, width }}
      className="absolute z-40 border border-amber-400/40 rounded-sm"
    >
      <div className="px-2 py-1 border-b border-slate-800 flex items-center justify-between gap-2">
        <span className="text-[11px] text-slate-100 truncate">{model.title}</span>
        {model.resources && model.resources.active ? (
          <span className="text-[9px] text-slate-500 tracking-wider shrink-0">
            {model.resources.moveLabel[0] === "R" ? "M" : "m"}
            {model.resources.actionLabel[0] === "R" ? "A" : "a"}
          </span>
        ) : null}
      </div>

      {model.kind === "commands" ? (
        <div className="px-2 py-1 flex gap-2">
          {model.lines.map((line) => (
            <span
              key={line.label}
              className={
                "px-1.5 py-0.5 rounded-sm text-[9px] tracking-wider " +
                (line.value === "READY"
                  ? "bg-emerald-500/15 text-emerald-200"
                  : "bg-slate-800 text-slate-400")
              }
            >
              {line.label} {line.value}
            </span>
          ))}
        </div>
      ) : null}

      {model.kind === "movePlan" || model.kind === "route" || model.kind === "order" ? (
        <div className="px-2 py-1 space-y-0.5">
          {model.lines.map((line) => (
            <p key={line.label} className="flex justify-between text-[11px] text-slate-400">
              <span>{line.label}</span>
              <span className="tabular-nums text-slate-200">{line.value}</span>
            </p>
          ))}
        </div>
      ) : null}

      {model.kind === "route" && model.route ? (
        <RouteSummary route={model.route} onDisplace={onRouteDisplace} />
      ) : null}

      {model.kind === "order" && model.order ? (
        <OrderSummary order={model.order} onPick={onOrderPick} />
      ) : null}

      {model.chain ? <ChainSummary chain={model.chain} /> : null}

      {forecast ? (
        <div className="px-2 py-2 border-b border-slate-800">
          {model.kind === "combinedPlan" ? (
            <p className="text-[10px] text-sky-300 mb-1">{model.title}</p>
          ) : null}
          <ForecastPanel forecast={forecast} compact />
        </div>
      ) : null}

      {model.kind === "contextOptions" ? (
        <ul className="max-h-64 overflow-auto">
          {model.contextOptions.map((option) => (
            <li key={option.abilityId}>
              <button
                onClick={() => onContextOption(option)}
                className={
                  "w-full text-left px-2 py-1 border-b border-slate-900 hover:bg-slate-800 " +
                  (option.recommended ? "bg-amber-400/10" : "")
                }
              >
                <span className="flex items-center gap-2">
                  <AssetImage asset={option.icon} size={14} className="text-amber-200" />
                  <span className="text-[11px] text-slate-100 truncate">{option.abilityName}</span>
                  <span
                    className={
                      "ml-auto text-[10px] font-bold " +
                      (option.forecast.headline.kind === "heal"
                        ? "text-emerald-300"
                        : "text-rose-300")
                    }
                  >
                    {option.forecast.headline.kind === "heal" ? "+" : ""}
                    {option.forecast.headline.value}
                    {option.forecast.headline.hitChancePercent != null
                      ? " · " + option.forecast.headline.hitChancePercent + "%"
                      : ""}
                  </span>
                  <span className="text-[9px] text-slate-600">{option.shortcut}</span>
                </span>
                <span className="block pl-5 text-[9px] text-slate-500 truncate">
                  {option.requiresMovement
                    ? "Move " + (option.suggestedPath.length - 1)
                    : "In range"}
                  {" · "}
                  {option.forecast.recovery.totalRecovery}
                  {option.forecast.lines.length
                    ? " · " + option.forecast.lines[0].label + " " + option.forecast.lines[0].value
                    : ""}
                </span>
              </button>
            </li>
          ))}
        </ul>
      ) : null}

      {model.kind === "abilities" ? (
        <ul className="max-h-64 overflow-auto">
          {abilities.map((entry, index) => {
            const entryForecast = entry.ability && entry.ability.forecast;
            return (
              <li key={entry.id}>
                <button
                  onClick={() => onAbility(entry)}
                  disabled={!entry.enabled}
                  title={entry.reason || entry.ability.description}
                  className={
                    "w-full text-left px-2 py-1 border-b border-slate-900 hover:bg-slate-800 disabled:cursor-not-allowed " +
                    (entry.enabled ? "" : "opacity-45")
                  }
                >
                  <span className="flex items-center gap-2">
                    <AssetImage asset={entry.ability.icon} size={14} className="text-amber-200" />
                    <span className="text-[11px] text-slate-100 truncate">{entry.label}</span>
                    <span className="ml-auto text-[10px] font-bold text-rose-300">
                      {entryForecast && entryForecast.valid && entryForecast.headline.value != null
                        ? (entryForecast.headline.kind === "heal" ? "+" : "") +
                          entryForecast.headline.value +
                          (entryForecast.headline.hitChancePercent != null
                            ? " · " + entryForecast.headline.hitChancePercent + "%"
                            : "")
                        : null}
                    </span>
                    <span className="text-[9px] text-slate-600">{index + 1}</span>
                  </span>
                  <span className="block pl-5 text-[9px] text-slate-500 truncate">
                    {entry.ability.rangeLabel.replace("Range ", "R")} · {entry.ability.recovery}
                    {entry.ability.cooldown ? " · cd" + entry.ability.cooldown : ""}
                    {entry.enabled ? "" : " · " + (entry.reason || entry.status)}
                  </span>
                </button>
              </li>
            );
          })}
        </ul>
      ) : null}

      <ul>
        {model.actions.map((entry) => (
          <li key={entry.id}>
            <button
              onClick={() => onAction(entry)}
              disabled={!entry.enabled}
              title={entry.reason || ""}
              className={
                "w-full flex items-center gap-2 px-2 py-1 border-b border-slate-900 text-left hover:bg-slate-800 disabled:cursor-not-allowed " +
                (entry.enabled ? "" : "opacity-45")
              }
            >
              <span className="text-[11px] text-slate-100">{entry.label}</span>
              <span className="ml-auto text-[9px] uppercase tracking-wider text-slate-500">
                {entry.shortcut}
              </span>
            </button>
          </li>
        ))}
      </ul>

    </div>
  );
}

function StatRow({ label, value }) {
  return (
    <div className="flex justify-between text-[11px] text-slate-400 tabular-nums">
      <span>{label}</span>
      <span className="text-slate-200">{value}</span>
    </div>
  );
}

/** Full character breakdown, deliberately separate from the battle menu. */
function CharacterSheet({ sheet }) {
  if (!sheet) return <p className="text-[11px] text-slate-500">Select a unit to inspect.</p>;
  const accent = accentOf(sheet.teamAccent);
  return (
    <div className="space-y-3 text-[11px]">
      <div className="flex items-center gap-2">
        <div className={"border border-slate-800 rounded-sm p-1 " + accent.soft}>
          <AssetImage asset={sheet.portrait} size={42} className={accent.text} alt={sheet.name} />
        </div>
        <div className="min-w-0">
          <p className={"text-sm " + accent.text}>{sheet.name}</p>
          <p className="text-slate-500">
            {sheet.className} · {sheet.teamMarker} {sheet.teamName}
            {sheet.controller === "ai" && sheet.aiProfileId ? " · AI " + sheet.aiProfileId : ""}
          </p>
          <p className="text-slate-600">
            Tile {sheet.movement.tile.x},{sheet.movement.tile.y} · elevation{" "}
            {sheet.movement.elevation}
            {sheet.summonedBy ? " · summoned by " + sheet.summonedBy : ""}
          </p>
        </div>
      </div>

      {sheet.description ? <p className="text-slate-500">{sheet.description}</p> : null}

      <div>
        <p className="text-slate-300 tabular-nums">
          HP {sheet.currentHp} / {sheet.maxHp} {sheet.alive ? "" : "· defeated"}
        </p>
        <HealthBar unit={{ hpPercent: sheet.hpPercent, teamAccent: sheet.teamAccent }} />
      </div>

      <div>
        <p className="text-[10px] uppercase tracking-wider text-slate-500 mb-1">Stats</p>
        <div className="grid grid-cols-2 gap-x-3">
          <StatRow label="Attack" value={sheet.stats.attack} />
          <StatRow label="Magic" value={sheet.stats.magic} />
          <StatRow label="Defense" value={sheet.stats.defense} />
          <StatRow label="Resistance" value={sheet.stats.resistance} />
          <StatRow label="Accuracy" value={sheet.stats.accuracy} />
          <StatRow label="Evasion" value={sheet.stats.evasion} />
          <StatRow label="Speed" value={Math.round(sheet.stats.speed)} />
          <StatRow label="Turn rate" value={"x" + sheet.timeline.turnRate} />
        </div>
      </div>

      <div>
        <p className="text-[10px] uppercase tracking-wider text-slate-500 mb-1">Traversal</p>
        <div className="grid grid-cols-2 gap-x-3">
          <StatRow label="Movement" value={sheet.movement.movement} />
          <StatRow label="Max climb" value={sheet.movement.maxClimb} />
          <StatRow label="Max drop" value={sheet.movement.maxDrop} />
          <StatRow label="Elevation" value={sheet.movement.elevation} />
        </div>
      </div>

      <div>
        <p className="text-[10px] uppercase tracking-wider text-slate-500 mb-1">Timeline</p>
        <StatRow label="Battle time" value={sheet.timeline.currentTime} />
        <StatRow label="Next action" value={sheet.timeline.nextActionTime} />
        <StatRow
          label="Queue position"
          value={
            sheet.timeline.isActive
              ? "acting now"
              : sheet.timeline.position == null
              ? "beyond preview"
              : "#" + sheet.timeline.position
          }
        />
      </div>

      {sheet.resources.length ? (
        <div>
          <p className="text-[10px] uppercase tracking-wider text-slate-500 mb-1">Resources</p>
          {sheet.resources.map((resource) => (
            <StatRow
              key={resource.resourceId}
              label={resource.resourceId}
              value={resource.current + " / " + resource.max}
            />
          ))}
        </div>
      ) : null}

      <div>
        <p className="text-[10px] uppercase tracking-wider text-slate-500 mb-1">
          Statuses and passives
        </p>
        {sheet.statuses.length === 0 && sheet.passives.length === 0 && sheet.shields.length === 0 ? (
          <p className="text-slate-600">None active.</p>
        ) : null}
        {sheet.statuses.map((status) => (
          <p key={status.statusId} className="text-amber-200">
            {status.icon.value} {status.name} · {status.remaining} activations
          </p>
        ))}
        {sheet.shields.map((shield, index) => (
          <p key={"shield" + index} className="text-sky-200">
            Shield {shield.amount}
            {shield.remaining ? " · " + shield.remaining + " activations" : ""}
          </p>
        ))}
        {sheet.passives.map((passive, index) => (
          <p key={"passive" + index} className="text-emerald-200">
            {passive.stat} {passive.mode} {passive.value}
            {passive.remaining ? " · " + passive.remaining + " activations" : ""}
          </p>
        ))}
      </div>

      <div>
        <p className="text-[10px] uppercase tracking-wider text-slate-500 mb-1">Abilities</p>
        {sheet.abilities.map((ability) => (
          <div key={ability.abilityId} className="mb-1">
            <p className="flex items-center gap-2 text-slate-200">
              <AssetImage asset={ability.icon} size={14} className="text-amber-200" />
              {ability.name}
              <span className="ml-auto text-[10px] text-slate-500">
                {ability.rangeLabel} · rec {ability.recovery}
                {ability.cooldown ? " · cd " + ability.cooldown : ""}
                {ability.cooldownRemaining ? " (" + ability.cooldownRemaining + " left)" : ""}
              </span>
            </p>
            <p className="text-[10px] text-slate-500">
              {ability.category}
              {ability.costs.length ? " · costs " + ability.costs.join(", ") : ""}
            </p>
            <p className="text-[10px] text-slate-600">{ability.description}</p>
          </div>
        ))}
      </div>
    </div>
  );
}

function DetailsDrawer({ sheet, unit, activeUnit, recovery, destination, destinationForecasts, logGroups, logFilter, onFilter, onClose }) {
  return (
    <div className="absolute inset-y-0 right-0 z-50 w-96 max-w-full border-l border-slate-800 bg-slate-950 overflow-auto">
      <div className="flex items-center justify-between px-3 py-2 border-b border-slate-800">
        <span className="text-[10px] uppercase tracking-[0.2em] text-slate-400">Details</span>
        <Button size="sm" onClick={onClose}>
          Close
        </Button>
      </div>
      <div className="p-3 space-y-3">
        <CharacterSheet sheet={sheet} />
        <div className="border-t border-slate-800 pt-2">
          <UnitInspector unit={unit} showActivation={!!activeUnit} />
        </div>
        {activeUnit ? (
          <div className="border-t border-slate-800 pt-2">
            <p className="text-[10px] uppercase tracking-wider text-slate-500 mb-1">
              Speed and recovery
            </p>
            <SpeedExplainer unit={activeUnit} recovery={recovery} />
          </div>
        ) : null}
        {destinationForecasts ? (
          <div className="border-t border-slate-800 pt-2">
            <DestinationForecastPanel
              destination={destination}
              entries={destinationForecasts}
              recovery={recovery}
            />
          </div>
        ) : null}
        <div className="border-t border-slate-800 pt-2">
          <BattleLogPanel groups={logGroups} filterId={logFilter} onFilter={onFilter} />
        </div>
      </div>
    </div>
  );
}


function ModifierList({ modifiers }) {
  if (!modifiers || !modifiers.length) return <span className="text-slate-600">no stat change</span>;
  return (
    <span className="text-slate-400">
      {modifiers
        .map(
          (modifier) =>
            modifier.stat +
            " " +
            (modifier.mode === "multiplier"
              ? "x" + modifier.value
              : (modifier.value > 0 ? "+" : "") + modifier.value)
        )
        .join(", ")}
    </span>
  );
}

/** Campaign deployment: owned operators, persistent loadouts and real inventory. */
function DeploymentScreen({ model, onToggle, onInspect, onEquip, onDeploy, onBack }) {
  const preview = model.preview;
  const validation = model.validation;
  return (
    <Screen
      title="Operator Deployment"
      subtitle={model.missionName + " · " + model.objectiveText}
      right={<><Button size="sm" onClick={onBack}>Back</Button><span className="px-3 text-[12px] tabular-nums text-slate-400">{model.selected.length}/{model.size}</span><Button tone="primary" disabled={!validation.valid} onClick={onDeploy}>Deploy lance</Button></>}
    >
      <div className="grid h-full gap-6" style={{ gridTemplateColumns: "430px minmax(0, 1fr)" }}>
        <aside className="min-h-0 overflow-auto pr-2">
          <p className="mb-3 text-[11px] uppercase tracking-[0.24em] text-slate-500">Available operators</p>
          <div className="space-y-3">
            {model.candidates.map((entry) => {
              const definition = CONTENT.units[entry.chassis];
              const portrait = conventionAsset("speaker." + entry.operatorId, "portraits/" + entry.operatorId, { type: "portraitSilhouette", value: entry.glyph, label: entry.name }, "512x512 portrait");
              return (
                <div key={entry.operatorId} className={(entry.inspected ? "border-sky-300/70 " : "border-slate-700 ") + (entry.selected ? "bg-emerald-500/10 " : "bg-slate-950/80 ") + "border"}>
                  <button onClick={() => onInspect(entry.operatorId)} className="flex w-full gap-3 p-3 text-left">
                    <AssetImage asset={portrait} size={84} className="h-[84px] w-[84px] border border-slate-700" alt={entry.name} />
                    <span className="min-w-0 flex-1">
                      <span className="block text-[15px] font-bold uppercase tracking-[0.08em] text-slate-100">{entry.name}</span>
                      <span className="mt-1 block text-[11px] text-sky-300/70">{definition.name}</span>
                      <span className="mt-2 block text-[10px] leading-relaxed text-slate-500">{entry.role}</span>
                    </span>
                    <span className="text-right text-[10px] uppercase tracking-wider text-slate-500"><span className="block text-amber-300">{entry.status}</span><span>{entry.condition}%</span></span>
                  </button>
                  <div className="flex items-center gap-3 border-t border-slate-800 px-3 py-2"><Button size="sm" tone={entry.selected ? "danger" : "ghost"} disabled={model.locked || entry.status === "required" || entry.guest} onClick={() => onToggle(entry.operatorId)}>{entry.selected ? "Remove" : "Select"}</Button>{entry.selected ? <span className="text-[10px] uppercase tracking-wider text-emerald-300">deployed</span> : null}</div>
                </div>
              );
            })}
          </div>
          {model.error ? <p className="mt-3 text-[11px] text-rose-300">{model.error}</p> : null}
          {!validation.valid ? <div className="mt-3 border border-rose-500/30 bg-rose-500/5 p-3 text-[11px] text-rose-300">{validation.errors.map((error) => <p key={error}>{error}</p>)}</div> : null}
        </aside>
        <main className="min-h-0 overflow-auto pr-2">
          {preview ? (
            <div className="grid gap-5" style={{ gridTemplateColumns: "300px minmax(0, 1fr)" }}>
              <div className="space-y-5">
                <Panel title="Selected operator">
                  <div className="flex flex-col items-center text-center">
                    <AssetImage asset={conventionAsset("speaker." + preview.operatorId, "portraits/" + preview.operatorId, { type: "portraitSilhouette", value: preview.operatorGlyph, label: preview.operatorName })} width={230} height={280} className="h-[280px] w-[230px]" alt={preview.operatorName} />
                    <p className="mt-4 text-[20px] font-black uppercase tracking-[0.08em] text-sky-200">{preview.operatorName}</p>
                    <p className="mt-1 text-[12px] text-slate-400">{preview.name} · {preview.status}</p>
                    <p className="mt-3 text-[11px] leading-relaxed text-slate-500">{preview.operatorRole}</p>
                  </div>
                </Panel>
                <Panel title="Final statistics">
                  <div className="grid grid-cols-2 gap-x-5 gap-y-2 text-[12px] tabular-nums">
                    {[["HP", preview.stats.maxHp, preview.statDeltas.maxHp],["Attack", preview.stats.attack, preview.statDeltas.attack],["Systems", preview.stats.magic, preview.statDeltas.magic],["Defense", preview.stats.defense, preview.statDeltas.defense],["Resistance", preview.stats.resistance, preview.statDeltas.resistance],["Accuracy", preview.stats.accuracy, preview.statDeltas.accuracy],["Evasion", preview.stats.evasion, preview.statDeltas.evasion],["Speed", Math.round(preview.stats.speed), preview.statDeltas.speed],["Movement", preview.movement.movement, preview.statDeltas.movement]].map(([label,value,delta]) => <div key={label} className="flex justify-between"><span className="text-slate-500">{label}</span><span className="text-slate-100">{value}{delta ? <em className={(delta > 0 ? " text-emerald-300" : " text-rose-300") + " not-italic"}> {delta > 0 ? "+" : ""}{delta}</em> : null}</span></div>)}
                  </div>
                </Panel>
              </div>
              <div className="space-y-5">
                <Panel title="Campaign-owned equipment">
                  <div className="space-y-5">
                    {preview.slots.map((slot) => <div key={slot.slot}><div className="mb-2 flex justify-between"><p className="text-[11px] uppercase tracking-[0.2em] text-slate-500">{slot.slotName}</p><p className="text-[11px] text-sky-300">Fitted · {slot.name}</p></div><div className="grid grid-cols-2 gap-2">{slot.options.map((option) => <button key={option.equipmentId} disabled={!option.selectable || preview.guest} onClick={() => onEquip(preview.operatorId, slot.slot, option.equipmentId)} className={(option.fitted ? "border-sky-300/70 bg-sky-400/10 " : "border-slate-700 bg-slate-950/75 hover:border-slate-500 ") + "border p-3 text-left disabled:opacity-35"}><span className="block text-[12px] text-slate-100">{option.name}</span><span className="mt-1 block text-[10px] text-slate-500">owned {option.owned} · available {option.available}</span><span className="mt-1 block text-[10px]"><ModifierList modifiers={option.modifiers} /></span></button>)}</div></div>)}
                  </div>
                </Panel>
                <Panel title="Available abilities"><div className="grid grid-cols-2 gap-3">{preview.abilities.map((ability) => <div key={ability.abilityId} className="border border-slate-800 bg-slate-950/60 p-3"><p className="text-[12px] text-slate-100">{ability.name}</p><p className="mt-1 text-[10px] leading-relaxed text-slate-500">{ability.description}</p><p className="mt-2 text-[10px] uppercase tracking-wider text-sky-300/70">{ability.rangeLabel} · recovery {ability.recovery}</p></div>)}</div></Panel>
              </div>
            </div>
          ) : <p className="text-slate-600">No operator available for inspection.</p>}
        </main>
      </div>
    </Screen>
  );
}

function AbilityTooltip({ tooltip }) {
  if (!tooltip) return null;
  return (
    <div
      style={{ ...createPanelStyle("secondary"), width: 232 }}
      className="absolute bottom-full mb-2 left-0 z-50 border rounded-sm px-2 py-2 text-[11px] pointer-events-none"
    >
      <p className="text-slate-100">
        {tooltip.glyph} {tooltip.name}
        <span className="text-slate-500"> · {tooltip.category}</span>
      </p>
      <p className="text-[10px] text-slate-400">{tooltip.description}</p>
      {tooltip.effects.map((line, index) => (
        <p key={index} className="text-[10px] text-amber-200">
          {line}
        </p>
      ))}
      <p className="text-[10px] text-slate-500">
        {tooltip.rangeLabel} · area {tooltip.areaShape} · recovery {tooltip.recovery}
        {tooltip.cooldown ? " · cooldown " + tooltip.cooldown : ""}
      </p>
      {tooltip.costs.length ? (
        <p className="text-[10px] text-sky-300">Cost: {tooltip.costs.join(", ")}</p>
      ) : null}
      {tooltip.conditions.map((condition, index) => (
        <p key={"c" + index} className="text-[10px] text-rose-200">
          {condition}
        </p>
      ))}
      {tooltip.grantedBy ? (
        <p className="text-[10px] text-sky-300">From {tooltip.grantedBy.name}</p>
      ) : null}
      {tooltip.usable ? null : (
        <p className="text-[10px] text-rose-300">{tooltip.unusableReason}</p>
      )}
    </div>
  );
}

/** Compact bottom-left battle HUD for the selected active mech. */
function MechHud({ hud, selectedAbilityId, onAbility, onDetails, bottom }) {
  const [hovered, setHovered] = React.useState(null);
  if (!hud) return null;
  const accent = accentOf(hud.teamAccent);
  return (
    <div
      style={{
        position: "absolute",
        left: 54,
        bottom: 72,
        zIndex: 38,
        width: 760,
        minHeight: 118,
        border: "1px solid " + CINEMATIC_COLORS.borderBright,
        background: "rgba(4,12,21,0.96)",
        boxShadow: "0 22px 60px rgba(0,0,0,0.45)"
      }}
      className="overflow-visible"
    >
      <FrameCorners />
      <div className="flex min-h-[118px]">
        <div className="flex w-[308px] shrink-0 border-r border-sky-300/15">
          <div className={"m-3 h-[86px] w-[70px] shrink-0 border border-slate-700 bg-slate-950/85 " + accent.soft}>
            <AssetImage asset={hud.portrait} width="100%" height="100%" className="h-full w-full object-cover" alt={hud.name} />
          </div>
          <div className="min-w-0 flex-1 py-3 pr-4">
            <div className="flex items-start justify-between gap-3">
              <div className="min-w-0">
                <p className={"truncate text-[18px] font-black uppercase tracking-[0.04em] " + accent.text}>{hud.name}</p>
                <p className="mt-1 text-[10px] uppercase tracking-[0.26em] text-slate-500">{hud.className} · {hud.facing}</p>
              </div>
              <button onClick={onDetails} className="text-[10px] uppercase tracking-[0.22em] text-sky-300/80 hover:text-sky-100">Inspect</button>
            </div>
            <p className="mt-3 text-[13px] tabular-nums text-slate-100">HP {hud.currentHp} / {hud.maxHp}</p>
            <HealthBar unit={{ hpPercent: hud.hpPercent, teamAccent: hud.teamAccent }} className="mt-2 h-[7px]" />
          </div>
        </div>
        <div className="min-w-0 flex-1 px-3 py-2">
          <div className="mb-2"><ResourceStrip resources={hud.resources} /></div>
          <div className="flex flex-wrap gap-2">
            {hud.abilities.map((ability, index) => (
              <div key={ability.abilityId} className="relative">
                <button
                  onMouseEnter={() => setHovered(ability.abilityId)}
                  onMouseLeave={() => setHovered(null)}
                  onClick={() => onAbility(ability)}
                  disabled={!ability.usable}
                  title={ability.name}
                  className={
                    (selectedAbilityId === ability.abilityId ? "border-sky-200 bg-sky-300/20 text-sky-100 " : "border-slate-600 bg-slate-950/90 text-slate-100 hover:border-sky-300/60 ") +
                    "relative h-[58px] w-[58px] border text-[22px] disabled:opacity-35"
                  }
                >
                  {ability.glyph}
                  <span className="absolute bottom-1 left-1/2 -translate-x-1/2 text-[9px] uppercase tracking-[0.16em] text-slate-500">{index + 1}</span>
                  {ability.cooldownRemaining > 0 ? <span className="absolute right-1 top-0 text-[10px] text-rose-300">{ability.cooldownRemaining}</span> : null}
                </button>
                {hovered === ability.abilityId ? <AbilityTooltip tooltip={ability.tooltip} /> : null}
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

function Screen({ title, subtitle, right, children, footer }) {
  return (
    <CinematicBackdrop>
      <header className="absolute left-[54px] right-[54px] top-[46px] z-20 flex items-start justify-between">
        <TitlePlaque title={title} subtitle={subtitle} />
        <div className="flex items-center gap-3">{right}</div>
      </header>
      <main className="absolute left-[54px] right-[54px] top-[188px] bottom-[54px] z-10 overflow-hidden">
        {children}
      </main>
      {footer ? <footer className="absolute bottom-5 left-[54px] z-20 text-[11px] uppercase tracking-[0.14em] text-slate-600">{footer}</footer> : null}
    </CinematicBackdrop>
  );
}

function ResistanceBase({ base, onMissions, onRoster, onSave, onLoad, saveNote, onEnd, onRepair, onBuildFacility, onChoosePerk }) {
  return (
    <Screen
      title={base.stageName}
      subtitle={base.chapterName + " · " + base.stageNote}
      right={<><Button size="sm" onClick={onSave}>Save</Button><Button size="sm" onClick={onLoad}>Load</Button><Button size="sm" onClick={onRoster}>Roster</Button><Button tone="primary" onClick={onMissions}>Mission board</Button></>}
      footer={saveNote}
    >
      <div className="grid h-full gap-6" style={{ gridTemplateColumns: "410px minmax(0, 1fr) 470px" }}>
        <div className="space-y-6 overflow-auto pr-1">
          <Panel title="Resistance resources"><div className="grid grid-cols-3 gap-3 text-center"><div className="border border-slate-700 bg-slate-950/60 p-4"><p className="text-[24px] font-black text-sky-200">{base.supplies}</p><p className="text-[10px] uppercase tracking-wider text-slate-500">Supplies</p></div><div className="border border-slate-700 bg-slate-950/60 p-4"><p className="text-[24px] font-black text-amber-200">{base.funds}</p><p className="text-[10px] uppercase tracking-wider text-slate-500">Funds</p></div><div className="border border-slate-700 bg-slate-950/60 p-4"><p className="text-[24px] font-black text-emerald-200">{base.intel}</p><p className="text-[10px] uppercase tracking-wider text-slate-500">Intel</p></div></div><p className="mt-4 text-[11px] text-slate-500">{base.completedMissions}/{base.totalMissions} operations complete · {base.availableMissions} available</p></Panel>
          <div className="relative overflow-hidden border border-sky-300/40 bg-sky-950/15 p-7"><FrameCorners /><p className="text-[11px] uppercase tracking-[0.28em] text-sky-300/70">Next operation</p><p className="mt-3 text-[24px] font-black uppercase tracking-[0.05em] text-slate-100">Review the mission board</p><p className="mt-3 text-[12px] leading-relaxed text-slate-400">Choose the resistance's next move, review the objective, then configure the lance.</p><div className="mt-6"><Button tone="primary" onClick={onMissions}>Open operations</Button></div></div>
          {base.finished ? <Button tone="primary" onClick={onEnd}>View end of prototype</Button> : null}
        </div>
        <Panel title="Lance condition and rank" bodyClassName="h-[calc(100%-46px)] overflow-auto p-0">
          <div className="divide-y divide-slate-800/80">
            {base.roster.map((entry) => {
              const portrait = conventionAsset("speaker." + entry.operatorId, "portraits/" + entry.operatorId, { type: "portraitSilhouette", value: entry.glyph, label: entry.name });
              return <div key={entry.operatorId} className="flex gap-4 p-4"><AssetImage asset={portrait} width={120} height={150} className="h-[150px] w-[120px] shrink-0 border border-slate-700" alt={entry.name} /><div className="min-w-0 flex-1"><div className="flex items-start justify-between"><div><p className="text-[17px] font-black uppercase tracking-[0.06em] text-slate-100">{entry.name}</p><p className="text-[11px] uppercase tracking-wider text-sky-300/70">{entry.chassisName} · rank {entry.rank}</p></div><p className={(entry.condition < 40 ? "text-rose-300" : entry.condition < 75 ? "text-amber-300" : "text-emerald-300") + " text-[15px] font-bold"}>{entry.condition}%</p></div><p className="mt-3 text-[11px] leading-relaxed text-slate-500">{entry.role}</p><p className="mt-3 text-[10px] text-slate-600">XP {entry.xp}{entry.perk ? " · " + entry.perk.name : ""}</p><div className="mt-3 flex flex-wrap gap-2">{entry.condition < 100 ? <Button size="sm" disabled={!entry.canRepair} onClick={() => onRepair(entry.operatorId)}>Repair {entry.repairCost}</Button> : null}{entry.perkChoices.map((perk) => <Button key={perk.perkId} size="sm" onClick={() => onChoosePerk(entry.operatorId, perk.perkId)}>{perk.name}</Button>)}</div></div></div>;
            })}
          </div>
        </Panel>
        <div className="space-y-6 overflow-auto pr-1">
          <Panel title="Quarry facilities"><div className="space-y-4">{base.facilities.map((facility) => <div key={facility.facilityId} className="flex items-start gap-3 border-b border-slate-800 pb-4 last:border-0"><span className="text-[25px]">{facility.glyph}</span><div className="min-w-0 flex-1"><p className={facility.built ? "text-emerald-300" : "text-slate-100"}>{facility.name}{facility.built ? " · built" : ""}</p><p className="mt-1 text-[10px] leading-relaxed text-slate-500">{facility.description}</p></div>{!facility.built ? <Button size="sm" disabled={!facility.available} onClick={() => onBuildFacility(facility.facilityId)}>Build</Button> : null}</div>)}</div></Panel>
          <Panel title="Contacts and stores"><div className="space-y-3 text-[11px]">{base.contacts.length ? base.contacts.map((contact) => <p key={contact.contactId}><span className="text-slate-100">{contact.glyph} {contact.name}</span><span className="block pl-7 text-slate-500">{contact.note}</span></p>) : <p className="text-slate-600">No contacts yet.</p>}{base.inventory.map((item) => <p key={item.equipmentId} className="text-sky-300">🔧 {item.name} x{item.count} · {item.available} ready</p>)}</div></Panel>
        </div>
      </div>
    </Screen>
  );
}

function MissionBoard({ board, onSelect, onBack }) {
  const firstAvailable = board.find((mission) => mission.available) || board[0] || null;
  const [focusedId, setFocusedId] = React.useState(firstAvailable ? firstAvailable.missionId : null);
  const focused = board.find((mission) => mission.missionId === focusedId) || firstAvailable;
  return (
    <Screen title="Mission Board" subtitle="Select the resistance's next operation" right={<Button size="sm" onClick={onBack}>Back to base</Button>}>
      <div className="grid h-full gap-7" style={{ gridTemplateColumns: "650px minmax(0, 1fr)" }}>
        <div className="min-h-0 overflow-auto pr-2"><p className="mb-3 text-[11px] uppercase tracking-[0.24em] text-slate-500">Available operations</p><div className="space-y-3">{board.map((mission) => <button key={mission.missionId} onClick={() => setFocusedId(mission.missionId)} className={(focused && focused.missionId === mission.missionId ? "border-sky-300/80 bg-sky-400/10 " : "border-slate-700 bg-slate-950/75 hover:border-slate-500 ") + (mission.completed ? "opacity-55 " : "") + "w-full border p-4 text-left"}><div className="flex items-center gap-3"><span className="w-10 text-[22px] font-black text-sky-300/50 tabular-nums">{String(mission.order).padStart(2, "0")}</span><span className="min-w-0 flex-1"><span className="block truncate text-[17px] font-black uppercase tracking-[0.06em] text-slate-100">{mission.name}</span><span className="mt-1 block text-[10px] uppercase tracking-[0.18em] text-slate-500">{mission.chapterName}</span></span><span className={(mission.available ? "text-emerald-300" : mission.completed ? "text-sky-300" : "text-rose-300") + " text-[10px] uppercase tracking-wider"}>{mission.completed ? "complete" : mission.available ? "available" : "locked"}</span></div><p className="mt-3 line-clamp-2 text-[11px] leading-relaxed text-slate-500">{mission.summary}</p></button>)}</div></div>
        {focused ? <div className="relative min-h-0 overflow-hidden border border-sky-300/40 bg-slate-950/80 p-8"><FrameCorners /><p className="text-[12px] uppercase tracking-[0.3em] text-sky-300/70">Operation {String(focused.order).padStart(2, "0")}</p><h2 className="mt-4 text-[38px] font-black uppercase leading-none tracking-[0.04em] text-slate-100">{focused.name}</h2><p className="mt-3 text-[12px] uppercase tracking-[0.16em] text-slate-500">{focused.chapterName}</p><div className="mt-10 max-w-3xl"><p className="text-[12px] uppercase tracking-[0.22em] text-slate-500">Mission summary</p><p className="mt-3 text-[17px] leading-8 text-slate-300">{focused.summary}</p></div><div className="mt-8 grid grid-cols-2 gap-5"><Panel title="Primary objective"><p className="text-[15px] leading-relaxed text-slate-200">{focused.objectiveText}</p></Panel><Panel title="Projected reward"><p className="text-[14px] text-slate-200">{focused.rewards.supplies} supplies · {focused.rewards.funds} funds</p>{focused.rewards.equipment ? <p className="mt-2 text-[11px] text-sky-300">{focused.rewards.equipment.join(", ")}</p> : null}</Panel></div>{focused.locked ? <p className="mt-8 text-[13px] text-rose-300">{focused.lockReason}</p> : null}<div className="absolute bottom-8 right-8"><Button tone="primary" disabled={!focused.available} onClick={() => onSelect(focused.missionId)}>{focused.kind === "story" ? "Begin scene" : "Prepare deployment"}</Button></div></div> : null}
      </div>
    </Screen>
  );
}

/* =========================================================================
 * SCENE PLAYER
 *
 * Runs an authored scene (src/scene/format.js). The same component the game
 * uses for a standalone or mission-attached scene *is* the editor's preview —
 * there is no approximation, so "it looked right in the editor" and "it looks
 * right in the game" are the same statement.
 *
 * Sequencing is the format's own pure fold: `advanceScene` runs presentation
 * steps until it reaches one the player must acknowledge. This component owns
 * only what a component should — the current index, keyboard input, and the
 * drawing.
 * =======================================================================*/

/** Portrait for a character, preferring an expression-specific file. */
function scenePortraitAsset(characterId, expression) {
  const speaker = CAMPAIGN.speakers[characterId] || { name: characterId, glyph: "💬" };
  const stems = [];
  if (expression) stems.push("portraits/" + characterId + "-" + expression);
  stems.push("portraits/" + characterId);
  return {
    id: "speaker." + characterId + (expression ? "." + expression : ""),
    type: "image",
    src: null,
    // Falls back from the expression to the plain portrait to a silhouette, so
    // writing a reaction never depends on that artwork existing yet.
    srcCandidates: stems.flatMap((stem) => assetFileCandidates(stem)),
    value: speaker.glyph,
    fallback: { type: "portraitSilhouette", value: speaker.glyph || "?", label: speaker.name },
    recommended: "512x512 portrait",
    missing: false
  };
}

function sceneBackgroundAsset(background) {
  const id = (background && background.id) || "unknown";
  const label = (background && background.label) || id;
  return {
    id: "scene.background." + id,
    type: "image",
    src: null,
    srcCandidates: assetFileCandidates("backgrounds/" + id),
    value: label,
    fallback: { type: "sceneLabel", value: label, label },
    recommended: "1920x1080 background",
    missing: false
  };
}

const SCENE_PORTRAIT_SLOTS = { left: 0.2, center: 0.5, right: 0.8 };

function ScenePlayer({ scene, startIndex, title, onComplete, onExit, exitLabel, autoAdvanceMs }) {
  const appSettings = React.useContext(SettingsContext);
  const [position, setPosition] = React.useState(() => {
    const from = Math.max(0, startIndex || 0);
    return advanceScene(scene, from, stageBefore(scene, from));
  });

  // Restarting, or jumping to a different step, is a fresh fold from the same
  // data — which is exactly why Play from here can exist at all.
  React.useEffect(() => {
    const from = Math.max(0, startIndex || 0);
    setPosition(advanceScene(scene, from, stageBefore(scene, from)));
  }, [scene, startIndex]);

  const stage = position.stage;
  const step = scene.steps[position.index] || null;

  const advance = React.useCallback(() => {
    if (position.done) {
      if (onComplete) onComplete();
      return;
    }
    setPosition((current) =>
      advanceScene(scene, current.index + 1, { ...current.stage, line: null })
    );
  }, [position.done, scene, onComplete]);

  React.useEffect(() => {
    if (typeof window === "undefined") return undefined;
    const onKey = (event) => {
      if (appSettings && appSettings.settingsOpen) return;
      if (event.repeat) return;
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        advance();
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [advance, appSettings && appSettings.settingsOpen]);

  React.useEffect(() => {
    if (!autoAdvanceMs || position.done) return undefined;
    const timer = setTimeout(advance, autoAdvanceMs);
    return () => clearTimeout(timer);
  }, [autoAdvanceMs, advance, position.index, position.done]);

  // Music is a request to the existing audio layer, not a second player.
  React.useEffect(() => {
    if (!appSettings || !appSettings.setMusicRequest || !stage.music) return;
    appSettings.setMusicRequest({
      context: stage.music.context || "briefing",
      missionId: stage.music.track || null
    });
  }, [appSettings, stage.music && stage.music.context, stage.music && stage.music.track]);

  const layout = calculateCinematicDialogueLayout(
    appSettings && appSettings.logicalViewport,
    "story"
  );
  const viewport = (appSettings && appSettings.logicalViewport) || UI_DESIGN_RESOLUTION;
  const line = stage.line;
  const speaker = line ? CAMPAIGN.speakers[line.speaker] || { name: line.speaker, glyph: "💬" } : null;
  const speaking = line ? stage.characters.find((entry) => entry.character === line.speaker) : null;

  return (
    <div
      style={{ width: "100%", height: "100%", position: "relative", overflow: "hidden", background: "#02070d" }}
      className="font-mono pixel-crisp-text text-slate-100"
      onClick={advance}
    >
      <AssetImage
        asset={sceneBackgroundAsset(stage.background)}
        width="100%"
        height="100%"
        cover
        alt={(stage.background && stage.background.label) || "scene background"}
        className="absolute inset-0 h-full w-full"
      />
      <div
        className="pointer-events-none absolute inset-0"
        style={{
          background:
            "linear-gradient(180deg, rgba(2,7,13,0.58) 0%, rgba(2,7,13,0.05) 36%, rgba(2,7,13,0.18) 58%, rgba(2,7,13,0.9) 100%)"
        }}
      />

      {/* Everyone on stage, dimmed unless they are the one talking. */}
      {stage.characters.map((entry) => {
        const slot = SCENE_PORTRAIT_SLOTS[entry.position] == null ? 0.5 : SCENE_PORTRAIT_SLOTS[entry.position];
        const width = Math.round(viewport.width * 0.26);
        const isSpeaking = !!line && line.speaker === entry.character;
        return (
          <div
            key={entry.character}
            className="pointer-events-none absolute transition-opacity duration-200"
            style={{
              // Standing on the floor, behind the dialogue box, the way a
              // portrait in a visual novel does. The box draws over their feet.
              left: Math.round(viewport.width * slot - width / 2),
              bottom: 0,
              width,
              height: Math.round(viewport.height * 0.82),
              zIndex: isSpeaking ? 12 : 10,
              opacity: !line || isSpeaking ? 1 : 0.5,
              filter: !line || isSpeaking ? "none" : "brightness(0.6) saturate(0.7)"
            }}
          >
            <AssetImage
              asset={scenePortraitAsset(entry.character, entry.expression)}
              width="100%"
              height="100%"
              className="h-full w-full object-contain object-bottom drop-shadow-[0_24px_35px_rgba(0,0,0,0.7)]"
              alt={(CAMPAIGN.speakers[entry.character] || {}).name || entry.character}
            />
          </div>
        );
      })}

      <div className="absolute left-[58px] top-[48px] z-20">
        <TitlePlaque
          width={400}
          eyebrow={"SCENE" + (stage.background && stage.background.label ? " · " + stage.background.label : "")}
          title={title || scene.name}
          subtitle={
            "Step " + (position.index + 1) + " of " + scene.steps.length +
            (step ? " · " + (SCENE_STEP_TYPES[step.type] || {}).label : "")
          }
        />
      </div>

      {onExit ? (
        <div className="absolute right-[58px] top-[48px] z-30 flex gap-3">
          <Button size="sm" onClick={(event) => { event.stopPropagation(); onExit(); }}>
            {exitLabel || "Stop"}
          </Button>
        </div>
      ) : null}

      {line ? (
        <>
          <div
            className="absolute z-20 border border-sky-200/55 bg-slate-950/94 px-9 pb-8 pt-12 shadow-2xl"
            style={{
              bottom: layout.bottom,
              left: layout.portraitLeft,
              right: layout.dialogueRight,
              minHeight: layout.dialogueHeight
            }}
          >
            <FrameCorners />
            <div
              className="absolute -top-[62px] left-0 border border-sky-200/55 bg-sky-300/75 px-7 py-4 text-slate-950"
              style={{ width: layout.nameplateWidth, maxWidth: "78%" }}
            >
              <p className="font-display truncate text-[22px] font-black uppercase tracking-[0.025em]">
                {speaker.name}
              </p>
              {speaking && speaking.expression ? (
                <p className="truncate text-[10px] uppercase tracking-[0.2em] opacity-65">
                  {speaking.expression}
                </p>
              ) : null}
            </div>
            <p
              className="overflow-y-auto pr-3 leading-[1.65] text-sky-100"
              style={{ fontSize: layout.textSize, maxHeight: layout.textMaxHeight }}
            >
              {line.text}
            </p>
            <div className="absolute bottom-5 right-7 flex items-center gap-3 text-[10px] uppercase tracking-[0.2em] text-sky-300/70">
              <span>Space</span>
              <span className="text-[20px]">▼</span>
            </div>
          </div>
        </>
      ) : null}

      {position.done ? (
        <div className="absolute inset-x-0 bottom-0 z-30 flex justify-center pb-10">
          <Button
            tone="primary"
            onClick={(event) => {
              event.stopPropagation();
              if (onComplete) onComplete();
            }}
          >
            Scene complete — continue
          </Button>
        </div>
      ) : null}
    </div>
  );
}

function StorySequenceScreen({ sequence, title, subtitle, onChoose, onSceneComplete, onComplete }) {
  const appSettings = React.useContext(SettingsContext);
  const [sceneIndex, setSceneIndex] = React.useState(0);
  const [lineIndex, setLineIndex] = React.useState(0);
  const [chosen, setChosen] = React.useState({});
  const [history, setHistory] = React.useState([]);
  const [showLog, setShowLog] = React.useState(false);
  const [auto, setAuto] = React.useState(false);
  const scenes = sequence.scenes || [];
  const scene = scenes[sceneIndex] || null;
  const authoredLine = scene && scene.lines.length ? scene.lines[Math.min(lineIndex, scene.lines.length - 1)] : null;
  const atLastLine = !scene || !scene.lines.length || lineIndex >= scene.lines.length - 1;
  const choice = scene && atLastLine ? (scene.choices || [])[0] || null : null;
  const selectedOptionId = choice ? chosen[choice.id] : null;
  const selectedOption = choice && selectedOptionId
    ? choice.options.find((option) => option.id === selectedOptionId) || null
    : null;
  const choiceAnswered = !choice || !!selectedOption;
  const unresolvedChoiceAhead = scenes.slice(sceneIndex).some((entry) =>
    (entry.choices || []).some((entryChoice) => !chosen[entryChoice.id])
  );

  const choiceResponseLine = React.useMemo(() => {
    if (!choice || !selectedOption) return null;
    const speakerId = selectedOption.speaker || choice.speaker || "vale";
    const speaker = CAMPAIGN.speakers[speakerId] || { name: speakerId, glyph: "💬" };
    return {
      speaker: speakerId,
      name: speaker.name,
      glyph: speaker.glyph,
      portraitAsset: conventionAsset(
        "speaker." + speakerId,
        "portraits/" + speakerId,
        { type: "portraitSilhouette", value: speaker.glyph || "?", label: speaker.name || speakerId },
        "512x512 portrait"
      ),
      text: selectedOption.spokenText || selectedOption.text,
      kind: selectedOption.kind || choice.kind || scene.kind || "dialogue",
      fromChoice: true
    };
  }, [choice, selectedOption, scene && scene.kind]);

  const line = choiceResponseLine || authoredLine;

  const selectChoice = React.useCallback((option) => {
    if (!choice || !option) return;
    if (authoredLine) {
      setHistory((current) => current.concat(authoredLine).slice(-30));
    }
    setChosen((current) => ({ ...current, [choice.id]: option.id }));
    onChoose(choice.id, option.id);
  }, [choice, authoredLine, onChoose]);

  const advance = React.useCallback(() => {
    if (!scene) { onComplete(); return; }
    if (!atLastLine) {
      if (authoredLine) setHistory((current) => current.concat(authoredLine).slice(-30));
      setLineIndex((index) => index + 1);
      return;
    }
    if (!choiceAnswered) return;
    if (line) setHistory((current) => current.concat(line).slice(-30));
    if (onSceneComplete) onSceneComplete(scene.sceneId);
    if (sceneIndex < scenes.length - 1) {
      setSceneIndex((index) => index + 1);
      setLineIndex(0);
      return;
    }
    onComplete();
  }, [scene, atLastLine, choiceAnswered, authoredLine, line, onSceneComplete, sceneIndex, scenes.length, onComplete]);

  React.useEffect(() => {
    if ((appSettings && appSettings.settingsOpen) || !auto || !scene || (choice && !choiceAnswered)) return undefined;
    const timer = setTimeout(advance, 2800);
    return () => clearTimeout(timer);
  }, [auto, scene, choice, choiceAnswered, advance, appSettings && appSettings.settingsOpen]);

  React.useEffect(() => {
    if (typeof window === "undefined") return undefined;
    const onKey = (event) => {
      if (appSettings && appSettings.settingsOpen) return;
      if (event.repeat) return;
      if (choice && !choiceAnswered && /^[1-9]$/.test(event.key)) {
        const option = choice.options[Number(event.key) - 1];
        if (option) {
          event.preventDefault();
          selectChoice(option);
        }
        return;
      }
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        advance();
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [advance, choice, choiceAnswered, selectChoice, appSettings && appSettings.settingsOpen]);

  if (!scene) return <Screen title={title} subtitle={subtitle}><Button tone="primary" onClick={onComplete}>Continue</Button></Screen>;
  const speakerColor = line && line.kind === "propaganda" ? "text-rose-200" : "text-sky-100";
  const shownLineNumber = choiceResponseLine ? scene.lines.length + 1 : Math.min(lineIndex + 1, Math.max(1, scene.lines.length));
  const totalLineCount = Math.max(1, scene.lines.length + (choice ? 1 : 0));
  const dialogueLayout = calculateCinematicDialogueLayout(
    appSettings && appSettings.logicalViewport,
    "story"
  );
  return (
    <div style={{ width: "100%", height: "100%", position: "relative", overflow: "hidden", background: "#02070d" }} className="font-mono pixel-crisp-text text-slate-100">
      <AssetImage asset={scene.backgroundAsset} width="100%" height="100%" cover alt={scene.location + " background"} className="absolute inset-0 h-full w-full" />
      <div className="pointer-events-none absolute inset-0" style={{ background: "linear-gradient(180deg, rgba(2,7,13,0.58) 0%, rgba(2,7,13,0.05) 36%, rgba(2,7,13,0.18) 58%, rgba(2,7,13,0.9) 100%), linear-gradient(90deg, rgba(2,7,13,0.45), transparent 34%, transparent 72%, rgba(2,7,13,0.35))" }} />
      <div className="absolute left-[58px] top-[48px] z-20"><TitlePlaque width={400} eyebrow={(scene.kind || "scene").toUpperCase() + " · " + scene.location} title={title} subtitle={subtitle} /></div>
      <div className="absolute right-[58px] top-[48px] z-30 flex gap-3"><Button size="sm" tone={auto ? "primary" : "ghost"} onClick={() => setAuto((value) => !value)}>Auto</Button><Button size="sm" disabled={unresolvedChoiceAhead} title={unresolvedChoiceAhead ? "Answer the required story choice before skipping." : "Skip remaining dialogue"} onClick={onComplete}>{unresolvedChoiceAhead ? "Choice required" : "Skip"}</Button><Button size="sm" tone={showLog ? "primary" : "ghost"} onClick={() => setShowLog((value) => !value)}>Log</Button><Button size="sm" onClick={advance}>Next</Button></div>

      {choice && !choiceAnswered ? (
        <div
          className="absolute z-30"
          style={{ right: dialogueLayout.choiceRight, top: dialogueLayout.choiceTop, width: dialogueLayout.choiceWidth }}
        >
          <p className="font-display mb-3 text-[12px] uppercase tracking-[0.2em] text-sky-300/70">{choice.prompt || "Response"}</p>
          <div className="space-y-3">
            {choice.options.map((option, index) => (
              <button
                key={option.id}
                onClick={() => selectChoice(option)}
                className="group flex min-h-[72px] w-full items-center border border-slate-500/80 bg-slate-950/90 px-6 text-left text-[17px] font-bold leading-[1.35] text-slate-200 transition hover:border-sky-200 hover:bg-sky-300/75 hover:text-slate-950"
              >
                <span className="mr-4 shrink-0 text-sky-300 group-hover:text-slate-950">▶</span>
                <span className="min-w-0 flex-1">{option.text}</span>
                <span className="ml-4 shrink-0 text-[11px] opacity-50">{index + 1}</span>
              </button>
            ))}
          </div>
        </div>
      ) : null}

      {line ? <>
        <div
          className="absolute z-20 border border-sky-200/55 bg-slate-950/72 shadow-2xl"
          style={{
            bottom: dialogueLayout.bottom,
            left: dialogueLayout.portraitLeft,
            width: dialogueLayout.portraitWidth,
            height: dialogueLayout.portraitHeight
          }}
        >
          <FrameCorners />
          <div className="absolute inset-[12px] overflow-hidden border border-sky-300/10 bg-slate-950/35">
            <AssetImage asset={line.portraitAsset} width="100%" height="100%" className="h-full w-full object-contain object-bottom drop-shadow-[0_24px_35px_rgba(0,0,0,0.65)]" alt={line.name} />
          </div>
        </div>
        <div
          className="absolute z-20 border border-sky-200/55 bg-slate-950/94 px-9 pb-8 pt-12 shadow-2xl"
          style={{
            bottom: dialogueLayout.bottom,
            left: dialogueLayout.dialogueLeft,
            right: dialogueLayout.dialogueRight,
            minHeight: dialogueLayout.dialogueHeight
          }}
        >
          <FrameCorners />
          <div
            className="absolute -top-[62px] left-0 border border-sky-200/55 bg-sky-300/75 px-7 py-4 text-slate-950"
            style={{ width: dialogueLayout.nameplateWidth, maxWidth: "78%" }}
          >
            <p className="font-display truncate text-[22px] font-black uppercase tracking-[0.025em]">{line.name}</p>
            <p className="truncate text-[10px] uppercase tracking-[0.2em] opacity-65">{line.fromChoice ? "Selected response" : scene.location}</p>
          </div>
          <p
            className={"overflow-y-auto pr-3 leading-[1.65] " + speakerColor}
            style={{ fontSize: dialogueLayout.textSize, maxHeight: dialogueLayout.textMaxHeight }}
          >
            {line.text}
          </p>
          <div className="absolute bottom-5 right-7 flex items-center gap-3 text-[10px] uppercase tracking-[0.2em] text-sky-300/70"><span>Space</span><span className="text-[20px]">▼</span></div>
        </div>
      </> : null}

      {showLog ? <div className="absolute bottom-[355px] right-[58px] z-40 h-[520px] w-[460px] overflow-auto border border-sky-300/35 bg-slate-950/96 p-5 shadow-2xl"><div className="mb-4 flex items-center justify-between"><p className="text-[11px] uppercase tracking-[0.24em] text-sky-300/70">Dialogue log</p><Button size="sm" onClick={() => setShowLog(false)}>Close</Button></div>{history.length ? history.map((entry, index) => <div key={index} className="mb-4 border-b border-slate-800 pb-4"><p className="text-[11px] uppercase tracking-wider text-sky-300">{entry.name}</p><p className="mt-1 text-[12px] leading-relaxed text-slate-400">{entry.text}</p></div>) : <p className="text-slate-600">No previous lines.</p>}</div> : null}
      <div className="absolute bottom-5 left-[58px] text-[10px] uppercase tracking-[0.2em] text-slate-600">Scene {sceneIndex + 1}/{scenes.length} · Line {shownLineNumber}/{totalLineCount}</div>
    </div>
  );
}

function RosterScreen({ base, onBack }) {
  return (
    <Screen title="Roster" subtitle="Operators and their machines" right={<Button size="sm" onClick={onBack}>Back</Button>}>
      <div className="grid h-full grid-cols-2 gap-6 overflow-auto pr-2">
        {base.roster.map((entry) => {
          const portrait = conventionAsset("speaker." + entry.operatorId, "portraits/" + entry.operatorId, { type: "portraitSilhouette", value: entry.glyph, label: entry.name });
          return <div key={entry.operatorId} className="relative grid min-h-[330px] overflow-hidden border border-sky-300/35 bg-slate-950/86" style={{ gridTemplateColumns: "260px 1fr" }}><FrameCorners /><div className="border-r border-sky-300/15 bg-slate-950/70"><AssetImage asset={portrait} width="100%" height="100%" className="h-full w-full object-contain object-bottom" alt={entry.name} /></div><div className="p-7"><p className="text-[25px] font-black uppercase tracking-[0.06em] text-slate-100">{entry.name}</p><p className="mt-2 text-[11px] uppercase tracking-[0.22em] text-sky-300/70">{entry.chassisName} · {entry.className} · rank {entry.rank}</p><p className="mt-6 text-[13px] leading-7 text-slate-400">{entry.role}</p><div className="mt-7 grid grid-cols-2 gap-3 text-[12px]"><div className="border border-slate-700 bg-slate-950/60 p-3"><p className="text-slate-500">Condition</p><p className="mt-1 text-[20px] text-emerald-300">{entry.condition}%</p></div><div className="border border-slate-700 bg-slate-950/60 p-3"><p className="text-slate-500">Experience</p><p className="mt-1 text-[20px] text-sky-200">{entry.xp}</p></div></div><p className="mt-6 text-[10px] uppercase tracking-[0.15em] text-slate-600">{Object.keys(entry.loadout).filter((slot) => entry.loadout[slot]).map((slot) => CONTENT.equipment[entry.loadout[slot]].name).join(" · ")}</p></div></div>;
        })}
      </div>
    </Screen>
  );
}

/**
 * What the operation paid, from the receipt the pipeline produced.
 *
 * Two groups, because they answer different questions: the operation's own
 * reward is what clearing it is worth, and salvage is what the things you
 * destroyed were carrying. Salvage names its source, which is the whole point
 * of replaying a mission for a particular enemy.
 */
function RewardPanel({ result }) {
  const reward = result.reward;
  const currencyRow = (entries) =>
    entries.filter((entry) => entry.kind === "currency");
  const itemRow = (entries) => entries.filter((entry) => entry.kind !== "currency");
  const glyphFor = (entry) => (entry.kind === "material" ? "◈" : "🔧");

  return (
    <Panel title="Operation rewards">
      {!reward || reward.empty ? (
        <p className="text-[12px] text-slate-500">This operation paid nothing.</p>
      ) : (
        <div className="space-y-5">
          {currencyRow(reward.mission).length ? (
            <div className="grid grid-cols-3 gap-4 text-center">
              {currencyRow(reward.mission).map((entry) => (
                <div key={entry.entryId + entry.itemId} className="border border-slate-700 p-5">
                  <p className="text-[32px] font-black text-sky-200">+{entry.quantity}</p>
                  <p className="text-[10px] uppercase tracking-wider text-slate-500">{entry.itemId}</p>
                </div>
              ))}
            </div>
          ) : null}
          {itemRow(reward.mission).length ? (
            <div className="space-y-2 text-[12px]">
              {itemRow(reward.mission).map((entry) => (
                <p key={entry.tableId + entry.entryId} className={entry.firstClear ? "text-amber-300" : "text-sky-300"}>
                  {glyphFor(entry)} {entry.name}
                  {entry.quantity > 1 ? " ×" + entry.quantity : ""}
                  {entry.firstClear ? <span className="ml-2 text-[10px] uppercase tracking-wider">first clear</span> : null}
                </p>
              ))}
            </div>
          ) : null}
          {reward.salvage.length ? (
            <div>
              <p className="mb-2 text-[10px] uppercase tracking-[0.2em] text-slate-500">Salvage</p>
              <div className="space-y-1 text-[12px]">
                {reward.salvage.map((entry, index) => (
                  <p key={entry.tableId + entry.entryId + index} className="flex justify-between gap-4">
                    <span className="text-emerald-300">
                      {glyphFor(entry)} {entry.name}
                      {entry.quantity > 1 ? " ×" + entry.quantity : ""}
                    </span>
                    <span className="text-[11px] text-slate-500">{entry.sourceLabel}</span>
                  </p>
                ))}
              </div>
            </div>
          ) : null}
          {reward.withheld.length ? (
            <div>
              <p className="mb-2 text-[10px] uppercase tracking-[0.2em] text-slate-600">Already recovered</p>
              <div className="space-y-1 text-[11px] text-slate-600">
                {reward.withheld.map((entry, index) => (
                  <p key={entry.tableId + entry.entryId + index}>
                    {entry.name} — taken on an earlier operation
                  </p>
                ))}
              </div>
            </div>
          ) : null}
          <div className="space-y-2 text-[12px]">
            {result.recruits.map((recruit) => (
              <p key={recruit.name} className="text-emerald-300">{recruit.glyph} {recruit.name} joins the resistance</p>
            ))}
            {result.contacts.map((contact) => (
              <p key={contact.name} className="text-emerald-300">{contact.glyph} {contact.name} is now a contact</p>
            ))}
          </div>
        </div>
      )}
    </Panel>
  );
}

function ResultsScreen({ result, onContinue, onRetry }) {
  const civilian = result.facts && result.facts.groups ? result.facts.groups.civilians : null;
  return (
    <Screen title={result.victory ? "Mission Complete" : "Mission Failed"} subtitle={result.missionName + " · " + result.activations + " activations"} right={<>{result.retryable ? <Button onClick={onRetry}>Retry mission</Button> : null}<Button tone="primary" onClick={onContinue}>{result.prototypeComplete ? "End of prototype" : "Return to base"}</Button></>}>
      <div className="grid h-full gap-6" style={{ gridTemplateColumns: "1.2fr 0.8fr" }}>
        <div className="space-y-6 overflow-auto pr-2">{result.victory ? <><RewardPanel result={result} />{civilian ? <Panel title="Hollowmere outcome"><div className="grid grid-cols-3 gap-5 text-[13px]"><div><p className="text-slate-500">Civilians attacked</p><p className="mt-2 text-[20px] text-slate-100">{civilian.attacked ? "Yes" : "No"}</p></div><div><p className="text-slate-500">Damage inflicted</p><p className="mt-2 text-[20px] text-slate-100">{civilian.damaged ? civilian.damageTaken : 0}</p></div><div><p className="text-slate-500">Transports lost</p><p className="mt-2 text-[20px] text-slate-100">{civilian.destroyed}</p></div></div></Panel> : null}</> : <div className="border border-rose-500/35 bg-rose-950/20 p-8"><p className="text-[18px] font-black uppercase tracking-wider text-rose-300">Operation failed</p><p className="mt-4 text-[13px] leading-relaxed text-slate-400">No rewards, flags, recruits, contacts, or mech damage were committed. The operation remains available.</p></div>}</div>
        <Panel title="Lance condition" bodyClassName="p-0"><div className="divide-y divide-slate-800">{result.conditions.length ? result.conditions.map((entry) => <div key={entry.operatorId} className="flex items-center justify-between p-5"><span className="text-[14px] text-slate-100">{entry.name}</span><span className={(entry.condition < 40 ? "text-rose-300" : entry.condition < 75 ? "text-amber-300" : "text-emerald-300") + " text-[24px] font-black"}>{entry.condition}%</span></div>) : <p className="p-5 text-slate-600">No persistent condition report.</p>}</div></Panel>
      </div>
    </Screen>
  );
}

/**
 * Compact prompt for an optional out-of-turn reaction.
 *
 * Deliberately not a modal: it sits above the bottom strip, states what
 * triggered it, who would react and what it costs, and gets out of the way.
 * Automatic and mandatory reactions never reach here — they resolve in the
 * simulation and are reported in the log.
 */
function ReactionPrompt({ model, onChoose, onDecline }) {
  const appSettings = React.useContext(SettingsContext);
  React.useEffect(() => {
    if (typeof window === "undefined" || !model) return undefined;
    const onKey = (event) => {
      if (appSettings && appSettings.settingsOpen) return;
      if (event.repeat) return;
      const index = Number(event.key) - 1;
      if (index >= 0 && index < model.offers.length && model.offers[index].affordable) {
        event.preventDefault();
        onChoose(model.offers[index].id);
      } else if (event.key === "Escape") {
        event.preventDefault();
        onDecline();
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [model, onChoose, onDecline, appSettings && appSettings.settingsOpen]);

  if (!model) return null;
  return (
    <div className="pointer-events-none absolute inset-x-0 bottom-[120px] z-[70] flex justify-center">
      <div className="pointer-events-auto min-w-[420px] max-w-[720px] border border-amber-300/70 bg-slate-950/95 px-4 py-3 shadow-2xl">
        <FrameCorners />
        <div className="mb-2 flex items-baseline gap-2">
          <span className="text-[10px] font-black uppercase tracking-[0.24em] text-amber-300">Reaction</span>
          <span className="text-[12px] text-slate-300">{model.triggerText}</span>
          {/* Why this window is open, in chain terms. A cascade three steps
           *  deep is otherwise indistinguishable from a coincidence. */}
          {model.cause && model.cause.depth > 0 ? (
            <span className="text-[10px] text-slate-600">{describeCause(model.cause)}</span>
          ) : null}
        </div>
        <div className="space-y-1">
          {model.offers.map((offer, index) => (
            <button
              key={offer.id}
              onClick={() => (offer.affordable ? onChoose(offer.id) : null)}
              disabled={!offer.affordable}
              title={offer.affordable ? "" : offer.blockedReason || ""}
              className={
                "flex w-full items-center gap-3 border px-3 py-2 text-left transition " +
                (offer.affordable
                  ? "border-amber-300/40 bg-slate-900/80 hover:border-amber-200 hover:bg-amber-950/40"
                  : "cursor-not-allowed border-slate-800 bg-slate-950/60 opacity-60")
              }
            >
              <span className="text-[10px] text-slate-500">{offer.affordable ? index + 1 : "—"}</span>
              <span className="flex-1">
                <span className={"block text-[13px] " + (offer.affordable ? "text-amber-100" : "text-slate-500")}>
                  {offer.name}
                </span>
                <span className="block text-[11px] text-slate-400">
                  {offer.affordable ? offer.description : offer.blockedReason}
                </span>
                {/* What accepting does to the action that is still pending.
                 *  A prompt that names a price and not a consequence is
                 *  asking the player to gamble on their own kit. */}
                {offer.affordable && offer.intervention ? (
                  <span className="mt-0.5 block text-[11px] font-semibold text-emerald-300">
                    {offer.intervention.text}
                  </span>
                ) : null}
              </span>
              <span className="text-right">
                <span className="block text-[11px] uppercase tracking-wider text-sky-300">{offer.reactorRef}</span>
                <span className={"block text-[10px] " + (offer.affordable ? "text-slate-500" : "text-rose-300/80")}>
                  {offer.costText}
                </span>
              </span>
            </button>
          ))}
        </div>
        <div className="mt-2 flex items-center justify-between">
          <span className="text-[10px] text-slate-600">Optional · number keys to accept, Esc to decline</span>
          <Button size="sm" onClick={onDecline}>
            Decline
          </Button>
        </div>
      </div>
    </div>
  );
}

/** A row of pips for a resource balance. Reads at a glance, which a number
 *  in a corner does not. */
function ResourcePips({ resource, lit }) {
  return (
    <span className="flex items-center gap-0.5" title={resource.name + " " + resource.current + "/" + resource.max}>
      {Array.from({ length: Math.min(12, resource.max) }, (unused, index) => (
        <span
          key={index}
          className={
            "inline-block h-2 w-2 rounded-full " +
            (lit && index < resource.current ? "bg-amber-300" : "bg-slate-700")
          }
        />
      ))}
    </span>
  );
}

/**
 * Persistent readout for the squad's shared resources and combat links:
 * whether each link is live, why not when it is not, and how much of each
 * shared pool is left.
 */
function LinkStrip({ model, top }) {
  if (!model) return null;
  const squad = (model.resources && model.resources.faction) || [];
  // A link-gated resource is already drawn beside its link; showing it twice
  // would suggest there are two of them.
  const ungated = squad.filter((resource) => !resource.linkId);
  if (!model.links.length && !ungated.length) return null;
  return (
    <div className="pointer-events-none absolute left-1/2 z-[45] -translate-x-1/2" style={{ top }}>
      <div className="flex gap-2">
        {ungated.map((resource) => (
          <div
            key={resource.id}
            title={resource.name + " — " + resource.current + " of " + resource.max}
            className="flex items-center gap-2 border border-sky-400/50 bg-slate-950/80 px-2 py-1 text-[11px] text-sky-100"
          >
            <span className="uppercase tracking-wider">{resource.name}</span>
            <ResourcePips resource={resource} lit={resource.available} />
          </div>
        ))}
        {model.links.map((link) => {
          const pool = (link.resources || [])[0] || null;
          return (
            <div
              key={link.id}
              title={link.active ? link.description : link.name + " — " + link.reason}
              className={
                "flex items-center gap-2 border px-2 py-1 text-[11px] " +
                (link.active
                  ? "border-amber-300/70 bg-amber-950/50 text-amber-100"
                  : "border-slate-700 bg-slate-950/80 text-slate-600")
              }
            >
              <span>{link.icon}</span>
              <span className="uppercase tracking-wider">{link.name}</span>
              {pool ? <ResourcePips resource={pool} lit={link.active} /> : null}
              {!link.active ? <span className="text-[10px] italic">{link.reason}</span> : null}
            </div>
          );
        })}
      </div>
    </div>
  );
}

/** Last few resolutions, so a fast cascade stays readable. */
function ReactionTicker({ model, bottom }) {
  if (!model || !model.recent.length) return null;
  const entries = model.recent.filter((entry) => entry.ok).slice(0, 3);
  if (!entries.length) return null;
  return (
    <div className="pointer-events-none absolute right-3 z-[45] space-y-1 text-right" style={{ bottom }}>
      {entries.map((entry, index) => (
        <div
          key={entry.reactionId + index}
          className="inline-block border border-amber-300/30 bg-slate-950/85 px-2 py-0.5 text-[10px] text-amber-200/90"
          style={{ opacity: 1 - index * 0.3 }}
        >
          ◈ {entry.reactorRef} · {entry.detail || entry.reactionId}
        </div>
      ))}
    </div>
  );
}

function CombatDialogueOverlay({ entry, onDismiss }) {
  const appSettings = React.useContext(SettingsContext);
  const [lineIndex, setLineIndex] = React.useState(0);
  React.useEffect(() => setLineIndex(0), [entry && entry.id]);
  const lines = entry && entry.lines && entry.lines.length ? entry.lines : entry ? [{ speaker: entry.speaker, name: entry.name, glyph: entry.glyph, text: entry.text }] : [];
  const line = lines[Math.min(lineIndex, Math.max(0, lines.length - 1))];
  const choices = (entry && entry.choices) || [];
  const atLastLine = lineIndex >= lines.length - 1;
  const awaitingChoice = atLastLine && choices.length > 0;
  const advance = React.useCallback(() => {
    if (!entry) return;
    if (lineIndex < lines.length - 1) setLineIndex((index) => index + 1);
    // A scene that ends on a choice waits for the player to pick rather than
    // dismissing itself; the choice is what sets the mission fact.
    else if (!choices.length) onDismiss();
  }, [entry, lineIndex, lines.length, onDismiss, choices.length]);
  React.useEffect(() => { if (typeof window === "undefined" || !entry) return undefined; const onKey = (event) => { if (appSettings && appSettings.settingsOpen) return; if (!event.repeat && (event.key === "Enter" || event.key === " ")) { event.preventDefault(); advance(); } }; window.addEventListener("keydown", onKey); return () => window.removeEventListener("keydown", onKey); }, [entry, advance, appSettings && appSettings.settingsOpen]);
  if (!entry || !line) return null;
  const portrait = conventionAsset("speaker." + line.speaker, "portraits/" + line.speaker, { type: "portraitSilhouette", value: line.glyph || "?", label: line.name || entry.name }, "512x512 portrait");
  const dialogueLayout = calculateCinematicDialogueLayout(
    appSettings && appSettings.logicalViewport,
    "combat"
  );
  return (
    <div className="pointer-events-none absolute inset-0 z-[80] pixel-crisp-text" style={{ background: "linear-gradient(180deg, rgba(1,4,8,0.05), rgba(1,4,8,0.12) 50%, rgba(1,4,8,0.78) 100%)" }}>
      <div
        className="pointer-events-auto absolute border border-sky-200/55 bg-slate-950/72 shadow-2xl"
        style={{
          bottom: dialogueLayout.bottom,
          left: dialogueLayout.portraitLeft,
          width: dialogueLayout.portraitWidth,
          height: dialogueLayout.portraitHeight
        }}
      >
        <FrameCorners />
        <div className="absolute inset-[12px] overflow-hidden border border-sky-300/10 bg-slate-950/35">
          <AssetImage asset={portrait} width="100%" height="100%" className="h-full w-full object-contain object-bottom drop-shadow-[0_24px_35px_rgba(0,0,0,0.7)]" alt={line.name} />
        </div>
      </div>
      <div
        className="pointer-events-auto absolute border border-sky-200/55 bg-slate-950/96 px-9 pb-8 pt-12 shadow-2xl"
        style={{
          bottom: dialogueLayout.bottom,
          left: dialogueLayout.dialogueLeft,
          right: dialogueLayout.dialogueRight,
          minHeight: dialogueLayout.dialogueHeight
        }}
      >
        <FrameCorners />
        <div
          className="absolute -top-[60px] left-0 border border-sky-200/55 bg-sky-300/75 px-7 py-4 text-slate-950"
          style={{ width: dialogueLayout.nameplateWidth, maxWidth: "78%" }}
        >
          <p className="font-display truncate text-[21px] font-black uppercase tracking-[0.025em]">{line.name || entry.name}</p>
          <p className="truncate text-[10px] uppercase tracking-[0.18em] opacity-65">Tactical communications</p>
        </div>
        <p
          className="overflow-y-auto pr-3 leading-[1.65] text-slate-100"
          style={{ fontSize: dialogueLayout.textSize, maxHeight: dialogueLayout.textMaxHeight }}
        >
          {line.text}
        </p>
        {awaitingChoice ? (
          <div className="mt-5 space-y-2">
            {choices[0].options.map((option) => (
              <button
                key={option.id}
                className="block w-full border border-sky-200/45 bg-slate-900/70 px-4 py-2 text-left text-[15px] text-sky-100 transition hover:border-sky-200 hover:bg-sky-900/50"
                onClick={() =>
                  onDismiss({
                    choiceId: choices[0].id,
                    optionId: option.id,
                    facts: option.fact
                      ? { [option.fact]: option.factValue === undefined ? true : option.factValue }
                      : {}
                  })
                }
              >
                {option.text}
              </button>
            ))}
          </div>
        ) : null}
        <div className="absolute bottom-5 right-6 flex items-center gap-3"><span className="text-[10px] uppercase tracking-[0.2em] text-slate-600">{lineIndex + 1}/{lines.length}</span>{awaitingChoice ? null : <Button tone="primary" size="sm" onClick={advance}>{lineIndex < lines.length - 1 ? "Next" : "Continue"}</Button>}</div>
      </div>
    </div>
  );
}

/**
 * Turns a compiled scene into the shape CombatDialogueOverlay renders.
 * Presentation-only: it reads the mission script and the speaker table and
 * never touches battle state.
 */
function createMissionSceneModel(script, sceneRef, token) {
  const scene = script && script.scenes ? script.scenes[sceneRef] : null;
  if (!scene) return null;
  const speakerOf = (id) => CAMPAIGN.speakers[id] || { name: id, glyph: "💬" };
  return {
    id: token + ":" + sceneRef,
    token,
    sceneRef,
    title: scene.title || sceneRef,
    location: scene.location || "",
    name: speakerOf((scene.lines[0] || {}).speaker).name,
    lines: (scene.lines || []).map((line) => {
      const speaker = speakerOf(line.speaker);
      return { speaker: line.speaker, name: speaker.name, glyph: speaker.glyph, text: line.text };
    }),
    choices: scene.choices || []
  };
}

function EndOfPrototype({ base, onBase }) {
  return (
    <Screen title="End of Prototype" subtitle="Act One complete — the first base survives">
      <div className="space-y-3 max-w-3xl text-[12px]">
        <p className="text-slate-200">
          🏚 {base.stageName} survived its first attack. Four pilots, rescued witnesses, and a handful of contacts now have one vulnerable place to stand.
        </p>
        <p className="text-slate-400">
          The broadcasts call you terrorists. The people at the quarry call you the first officers who came back for them.
        </p>
        <Panel title="Resistance status">
          <div className="text-[11px] space-y-1">
            <p>📦 Supplies {base.supplies} · 💰 Funds {base.funds} · 🛰 Intel {base.intel}</p>
            <p>Lance: {base.roster.map((entry) => entry.name).join(", ")}</p>
            <p>Contacts: {base.contacts.map((contact) => contact.name).join(", ") || "none"}</p>
          </div>
        </Panel>
        <Panel title="Act Two threads">
          <div className="text-[11px] space-y-1 text-slate-400">
            <p>🗺 Karrow Basin — government mining tithe, unrest reported</p>
            <p>🗺 Northern Relay — jamming the propaganda broadcast</p>
            <p>🗺 Hollowmere Ruins — what is left of the settlement</p>
          </div>
        </Panel>
        <Button tone="primary" onClick={onBase}>
          Back to base
        </Button>
      </div>
    </Screen>
  );
}

const UI_DESIGN_RESOLUTION = { width: 1920, height: 1080 };
const UI_SCALE_OPTIONS = [
  { id: "80", label: "80% · Compact", factor: 0.8 },
  { id: "90", label: "90%", factor: 0.9 },
  { id: "100", label: "100%", factor: 1 },
  { id: "110", label: "110% · Recommended", factor: 1.1 },
  { id: "120", label: "120% · Large", factor: 1.2 },
  { id: "130", label: "130% · Extra Large", factor: 1.3 }
];

const SettingsContext = React.createContext(null);
const MUSIC_EXTENSIONS = ["mp3", "ogg", "wav", "m4a"];
const MUSIC_CONTEXT_LABELS = {
  base: "Resistance Base",
  missions: "Mission Board",
  briefing: "Story / Briefing",
  deployment: "Deployment",
  battle: "Battle",
  results: "Mission Results",
  ending: "Act Ending"
};

function readStoredPercent(key, fallback) {
  if (typeof window === "undefined") return fallback;
  try {
    const parsed = Number(window.localStorage.getItem(key));
    return Number.isFinite(parsed) ? Math.max(0, Math.min(100, parsed)) : fallback;
  } catch (error) {
    return fallback;
  }
}

function readStoredBoolean(key, fallback) {
  if (typeof window === "undefined") return fallback;
  try {
    const stored = window.localStorage.getItem(key);
    return stored == null ? fallback : stored === "true";
  } catch (error) {
    return fallback;
  }
}

function persistSetting(key, value) {
  try {
    window.localStorage.setItem(key, String(value));
  } catch (error) {
    /* The setting remains active for this session if storage is unavailable. */
  }
}

function musicCandidatesFor(request) {
  const context = request && request.context ? request.context : "base";
  const missionId = request && request.missionId ? request.missionId : null;
  const stems = [];
  if (missionId && (context === "battle" || context === "briefing" || context === "deployment")) {
    stems.push("music/missions/" + missionId + "-" + context);
  }
  stems.push("music/" + context);
  if (context === "missions") stems.push("music/mission-board");
  if (context === "ending") stems.push("music/end");
  stems.push("music/default");
  const deduped = Array.from(new Set(stems));
  return deduped.flatMap((stem) => MUSIC_EXTENSIONS.map((extension) => "/assets/" + stem + "." + extension));
}

function MusicTrackPlayer({ candidates, request, enabled, masterVolume, musicVolume, unlocked, onStatus }) {
  const audioRef = React.useRef(null);
  const [candidateIndex, setCandidateIndex] = React.useState(0);
  const currentSrc = candidates[candidateIndex] || null;

  React.useEffect(() => {
    const audio = audioRef.current;
    if (!audio) return;
    audio.volume = Math.max(0, Math.min(1, (masterVolume / 100) * (musicVolume / 100)));
  }, [masterVolume, musicVolume]);

  React.useEffect(() => {
    const audio = audioRef.current;
    if (!audio) return;
    audio.pause();
    if (currentSrc) audio.load();
    if (!enabled || !currentSrc) {
      onStatus({
        state: currentSrc ? "muted" : "missing",
        src: currentSrc,
        context: request && request.context,
        missionId: request && request.missionId,
        candidateIndex,
        candidates
      });
      return;
    }
    if (!unlocked) {
      onStatus({
        state: "waiting",
        src: currentSrc,
        context: request && request.context,
        missionId: request && request.missionId,
        candidateIndex,
        candidates
      });
    }
  }, [currentSrc, enabled, unlocked]);

  const playCurrent = () => {
    const audio = audioRef.current;
    if (!audio || !enabled || !unlocked || !currentSrc) return;
    const promise = audio.play();
    if (promise && typeof promise.catch === "function") {
      promise.catch(() => onStatus({
        state: "blocked",
        src: currentSrc,
        context: request && request.context,
        missionId: request && request.missionId,
        candidateIndex,
        candidates
      }));
    }
  };

  return (
    <audio
      ref={audioRef}
      src={currentSrc || undefined}
      loop
      preload="auto"
      onCanPlay={() => {
        onStatus({
          state: enabled ? "ready" : "muted",
          src: currentSrc,
          context: request && request.context,
          missionId: request && request.missionId,
          candidateIndex,
          candidates
        });
        playCurrent();
      }}
      onPlay={() => onStatus({
        state: "playing",
        src: currentSrc,
        context: request && request.context,
        missionId: request && request.missionId,
        candidateIndex,
        candidates
      })}
      onError={() => {
        if (candidateIndex + 1 < candidates.length) {
          setCandidateIndex((index) => index + 1);
        } else {
          onStatus({
            state: "missing",
            src: null,
            context: request && request.context,
            missionId: request && request.missionId,
            candidateIndex,
            candidates
          });
        }
      }}
      style={{ display: "none" }}
    />
  );
}

function AppMusicPlayer({ request, enabled, masterVolume, musicVolume, onStatus }) {
  const [unlocked, setUnlocked] = React.useState(false);
  const context = request && request.context ? request.context : "base";
  const missionId = request && request.missionId ? request.missionId : null;
  const requestKey = context + "|" + (missionId || "global");
  const candidates = React.useMemo(() => musicCandidatesFor({ context, missionId }), [context, missionId]);

  React.useEffect(() => {
    if (typeof window === "undefined") return undefined;
    const unlock = () => setUnlocked(true);
    window.addEventListener("pointerdown", unlock, { once: true, capture: true });
    window.addEventListener("keydown", unlock, { once: true, capture: true });
    return () => {
      window.removeEventListener("pointerdown", unlock, true);
      window.removeEventListener("keydown", unlock, true);
    };
  }, []);

  return (
    <MusicTrackPlayer
      key={requestKey}
      candidates={candidates}
      request={{ context, missionId }}
      enabled={enabled}
      masterVolume={masterVolume}
      musicVolume={musicVolume}
      unlocked={unlocked}
      onStatus={onStatus}
    />
  );
}

function SettingsMenu({ open, onClose, uiScaleId, onUiScale, masterVolume, onMasterVolume, musicVolume, onMusicVolume, musicEnabled, onMusicEnabled, musicRequest, musicStatus, windowViewport, logicalViewport, onReturnToMenu, canReturnToMenu }) {
  const [confirmingExit, setConfirmingExit] = React.useState(false);
  React.useEffect(() => {
    if (!open) setConfirmingExit(false);
  }, [open]);
  if (!open) return null;
  const context = musicRequest && musicRequest.context ? musicRequest.context : "base";
  const requestedCandidates = musicCandidatesFor(musicRequest || { context });
  const requestedSrc = requestedCandidates[0] || null;
  const usingFallback = !!(musicStatus.src && requestedSrc && musicStatus.src !== requestedSrc);
  const statusLabel = musicStatus.state === "playing"
    ? "Playing"
    : musicStatus.state === "ready"
    ? "Ready"
    : musicStatus.state === "waiting"
    ? "Click once to start audio"
    : musicStatus.state === "muted"
    ? "Music disabled"
    : musicStatus.state === "missing"
    ? "No matching file found"
    : "Waiting for browser audio permission";
  const requestFullscreen = () => {
    if (document.fullscreenElement) document.exitFullscreen();
    else if (document.documentElement.requestFullscreen) document.documentElement.requestFullscreen();
  };
  return (
    <div className="fixed inset-0 z-[1000000] flex items-center justify-center bg-black/75 p-6 font-mono text-slate-100 backdrop-blur-sm">
      <div className="relative w-[620px] max-w-[95vw] border border-sky-300/45 bg-slate-950/98 shadow-[0_35px_120px_rgba(0,0,0,0.85)]">
        <FrameCorners />
        <div className="flex items-center justify-between border-b border-sky-300/15 px-7 py-5">
          <div><p className="text-[11px] uppercase tracking-[0.35em] text-sky-300/70">System</p><h2 className="font-display mt-1 text-[26px] font-black uppercase tracking-[0.025em]">Settings</h2></div>
          <button onClick={onClose} className="h-11 border border-slate-600 px-4 text-[11px] uppercase tracking-[0.2em] text-slate-300 hover:border-sky-300 hover:text-sky-100">Resume · Esc</button>
        </div>
        <div className="space-y-7 p-7">
          <section>
            <p className="mb-3 text-[11px] uppercase tracking-[0.28em] text-sky-300/70">Display</p>
            <div className="grid grid-cols-[190px_1fr] items-center gap-4">
              <label className="text-[12px] text-slate-300">UI scale</label>
              <select value={uiScaleId} onChange={(event) => onUiScale(event.target.value)} className="h-11 border border-slate-600 bg-slate-900 px-3 text-[12px] text-slate-100">{UI_SCALE_OPTIONS.map((option) => <option key={option.id} value={option.id}>{option.label}</option>)}</select>
              <span className="text-[12px] text-slate-300">Display mode</span>
              <button onClick={requestFullscreen} className="h-11 border border-slate-600 bg-slate-900 px-3 text-left text-[11px] uppercase tracking-[0.18em] text-slate-200 hover:border-sky-300/70">Toggle fullscreen</button>
            </div>
            <p className="mt-3 text-[10px] text-slate-600">Display {windowViewport.width}×{windowViewport.height} · logical UI {logicalViewport.width}×{logicalViewport.height}</p>
            <FontDiagnostics />
          </section>

          <section className="border-t border-slate-800 pt-6">
            <div className="mb-4 flex items-center justify-between"><p className="text-[11px] uppercase tracking-[0.28em] text-sky-300/70">Audio</p><button onClick={() => onMusicEnabled(!musicEnabled)} className={(musicEnabled ? "border-sky-300/70 bg-sky-300/15 text-sky-100" : "border-slate-600 bg-slate-900 text-slate-400") + " h-9 border px-4 text-[10px] uppercase tracking-[0.18em]"}>{musicEnabled ? "Music on" : "Music off"}</button></div>
            <div className="space-y-5">
              <label className="grid grid-cols-[190px_1fr_48px] items-center gap-4"><span className="text-[12px] text-slate-300">Master volume</span><input type="range" min="0" max="100" value={masterVolume} onChange={(event) => onMasterVolume(Number(event.target.value))} className="w-full accent-sky-300" /><span className="text-right text-[12px] tabular-nums text-slate-400">{masterVolume}%</span></label>
              <label className="grid grid-cols-[190px_1fr_48px] items-center gap-4"><span className="text-[12px] text-slate-300">Music volume</span><input type="range" min="0" max="100" value={musicVolume} onChange={(event) => onMusicVolume(Number(event.target.value))} className="w-full accent-sky-300" /><span className="text-right text-[12px] tabular-nums text-slate-400">{musicVolume}%</span></label>
            </div>
            <div className="mt-5 border border-slate-700 bg-slate-900/60 p-4">
              <div className="flex items-center justify-between gap-4"><span className="text-[11px] uppercase tracking-[0.2em] text-slate-500">Current soundtrack</span><span className={musicStatus.state === "playing" ? "text-emerald-300" : musicStatus.state === "missing" ? "text-amber-300" : "text-slate-400"}>{statusLabel}</span></div>
              <p className="mt-2 text-[14px] font-bold text-slate-100">{MUSIC_CONTEXT_LABELS[context] || context}</p>
              <p className={"mt-2 text-[10px] uppercase tracking-[0.16em] " + (usingFallback ? "text-amber-300" : "text-emerald-300")}>{usingFallback ? "Fallback track in use" : musicStatus.src ? "Requested track loaded" : "No track loaded"}</p>
              <p className="mt-1 break-all text-[9px] text-slate-500">Requested: {requestedSrc || "none"}</p>
              <p className="mt-1 break-all text-[9px] text-slate-600">Loaded: {musicStatus.src || "none"}</p>
            </div>
          </section>

          {canReturnToMenu ? (
            <section className="border-t border-slate-800 pt-6">
              <p className="mb-3 text-[11px] uppercase tracking-[0.28em] text-sky-300/70">Session</p>
              {confirmingExit ? (
                <div className="border border-amber-300/40 bg-amber-950/20 p-4">
                  <p className="text-[12px] leading-relaxed text-amber-200">
                    Return to the title screen? Nothing is written on the way out, so anything
                    since your last save is discarded — including a battle in progress.
                  </p>
                  <div className="mt-4 flex gap-3">
                    <button
                      onClick={onReturnToMenu}
                      className="h-11 border border-amber-300/60 bg-amber-300/10 px-5 text-[11px] uppercase tracking-[0.18em] text-amber-100 hover:bg-amber-300/20"
                    >
                      Return to main menu
                    </button>
                    <button
                      onClick={() => setConfirmingExit(false)}
                      className="h-11 border border-slate-600 px-5 text-[11px] uppercase tracking-[0.18em] text-slate-300 hover:border-sky-300 hover:text-sky-100"
                    >
                      Stay
                    </button>
                  </div>
                </div>
              ) : (
                <button
                  onClick={() => setConfirmingExit(true)}
                  className="h-11 w-full border border-slate-600 bg-slate-900 px-5 text-left text-[11px] uppercase tracking-[0.18em] text-slate-200 hover:border-sky-300/70 hover:text-sky-100"
                >
                  Return to main menu
                </button>
              )}
            </section>
          ) : null}
        </div>
      </div>
    </div>
  );
}

function readUiScalePreference() {
  if (typeof window === "undefined") return "100";
  try {
    const stored = window.localStorage.getItem("tactical-ui-scale");
    return UI_SCALE_OPTIONS.some((option) => option.id === stored) ? stored : "100";
  } catch (error) {
    return "100";
  }
}

function UiScaleControl({ scaleId, onScale, windowViewport, logicalViewport }) {
  const [open, setOpen] = React.useState(false);
  return (
    <div className="fixed bottom-4 right-4 z-[999999] font-mono">
      {open ? <div className="mb-2 w-[245px] border border-sky-300/35 bg-slate-950/97 p-3 text-slate-300 shadow-2xl"><div className="mb-2 flex items-center justify-between"><span className="text-[10px] uppercase tracking-[0.2em] text-sky-300/70">UI scale</span><button onClick={() => setOpen(false)} className="text-slate-500 hover:text-slate-100">×</button></div><select value={scaleId} onChange={(event) => onScale(event.target.value)} className="h-10 w-full border border-slate-600 bg-slate-900 px-2 text-[11px] text-slate-100">{UI_SCALE_OPTIONS.map((option) => <option key={option.id} value={option.id}>{option.label}</option>)}</select><p className="mt-2 text-[9px] leading-relaxed text-slate-600">Display {windowViewport.width}×{windowViewport.height}<br />Logical UI {logicalViewport.width}×{logicalViewport.height}</p></div> : null}
      <button onClick={() => setOpen((value) => !value)} className="h-11 border border-slate-700 bg-slate-950/92 px-4 text-[10px] uppercase tracking-[0.18em] text-slate-400 shadow-xl hover:border-sky-300/50 hover:text-sky-200">UI Scale · {scaleId}%</button>
    </div>
  );
}

function TacticalBattleContent({ viewport, initialCampaign }) {
  const appSettings = React.useContext(SettingsContext);
  const [deployment, setDeployment] = React.useState(null);
  const [deployed, setDeployed] = React.useState(false);
  const rosterRef = React.useRef(null);

  // Campaign layer: screens, story flags and persistence. `initialCampaign`
  // is what Continue hands in; null means a fresh run, which is both what New
  // Game wants and what a bare mount (playtest, a harness) has always done.
  const [campaign, setCampaign] = React.useState(() => initialCampaign || createCampaignState());
  // The editor's Playtest button drops a mission into sessionStorage and opens
  // the game; when that slot is filled we boot straight into the battle instead
  // of the hub, so painting a tile and standing on it are one click apart.
  const [screen, setScreen] = React.useState(() =>
    MISSION_CONTENT.playtestMissionId ? "battle" : "base"
  );
  const [pendingMissionId, setPendingMissionId] = React.useState(
    MISSION_CONTENT.playtestMissionId || null
  );
  const [missionResult, setMissionResult] = React.useState(null);
  // The authored scene the campaign is currently showing, and where to go once
  // it finishes. Null whenever no scene is playing.
  const [pendingScene, setPendingScene] = React.useState(null);
  const [pendingOutcome, setPendingOutcome] = React.useState(null);
  const [saveNote, setSaveNote] = React.useState(
    initialCampaign ? "Campaign loaded from your last save." : "Campaign not saved yet."
  );
  const [storyLog, setStoryLog] = React.useState([]);
  const [combatDialogueQueue, setCombatDialogueQueue] = React.useState([]);
  // The mission runtime's blocking scene, if the battle is suspended on one.
  const [missionScene, setMissionScene] = React.useState(null);
  const firedTriggersRef = React.useRef([]);

  React.useEffect(() => {
    if (!appSettings || !appSettings.setMusicRequest) return;
    const contextByScreen = {
      base: "base",
      roster: "base",
      missions: "missions",
      briefing: "briefing",
      aftermath: "briefing",
      defeatStory: "briefing",
      deployment: "deployment",
      battle: "battle",
      results: "results",
      prototypeEnd: "ending"
    };
    appSettings.setMusicRequest({
      context: contextByScreen[screen] || "base",
      missionId: pendingMissionId || null
    });
  }, [screen, pendingMissionId]);

  const battleRef = React.useRef(null);
  if (!battleRef.current) {
    battleRef.current = createBattle(
      MISSION_CONTENT.playtestEncounterId || deploymentEncounterId(),
      GAME_CONFIG.defaults.seed,
      // The player is present, so optional reactions ask rather than
      // auto-resolving. Headless runs keep the deterministic policy.
      { autoResolveReactions: false }
    );
  }
  const state = battleRef.current;

  const [version, setVersion] = React.useState(0);
  const [input, setInput] = React.useState(() => createInputState());
  const [seed, setSeed] = React.useState(GAME_CONFIG.defaults.seed);
  const [speedId, setSpeedId] = React.useState(GAME_CONFIG.presentation.defaultSpeedId);
  const [devTab, setDevTab] = React.useState("controls");
  const [logFilter, setLogFilter] = React.useState("all");
  const [notice, setNotice] = React.useState("Battle ready. The timeline decides who acts next.");
  const [presentation, setPresentation] = React.useState({ queue: [], index: 0 });
  const [positions, setPositions] = React.useState({});
  const [popups, setPopups] = React.useState([]);
  const [effects, setEffects] = React.useState([]);
  const [lungingUnitId, setLungingUnitId] = React.useState(null);
  const [testResults, setTestResults] = React.useState(null);
  const [audit, setAudit] = React.useState(null);
  const [running, setRunning] = React.useState(false);
  const [abilityMenuOpen, setAbilityMenuOpen] = React.useState(false);
  const [camera, setCamera] = React.useState(() => createCameraState());
  const [showElevation, setShowElevation] = React.useState(false);
  const [showIntel, setShowIntel] = React.useState(false);
  const dragRef = React.useRef(null);
  const suppressClickRef = React.useRef(false);
  const stageRef = React.useRef(null);
  const [detailsOpen, setDetailsOpen] = React.useState(false);
  const [devOpen, setDevOpen] = React.useState(false);
  const [cursor, setCursor] = React.useState({ x: 0, y: 0 });
  const [checklist, setChecklist] = React.useState({});

  const doneRef = React.useRef(null);
  const popupIdRef = React.useRef(0);
  const effectIdRef = React.useRef(0);
  const timersRef = React.useRef([]);

  // Publishes the live battle on the debug hook so a console — or a headless
  // browser check — can inspect the authoritative state the player is looking
  // at. Read-only by convention; nothing in the app reads it back.
  React.useEffect(() => {
    if (typeof window === "undefined" || !window.STATUS_ZERO) return;
    window.STATUS_ZERO.liveBattle = () => battleRef.current;
    // Lets a console or an acceptance script that drove the simulation
    // directly tell the view to catch up. The normal command path does this
    // itself; nothing in the app reads these back.
    window.STATUS_ZERO.refreshUi = () => setVersion((value) => value + 1);
  });

  const touch = () => setVersion((value) => value + 1);
  const mark = (key) =>
    setChecklist((current) => (current[key] ? current : { ...current, [key]: true }));
  const timing = React.useMemo(() => getAnimationTiming(speedId), [speedId]);

  const projection = React.useMemo(() => battlefieldProjection(), []);

  const layout = React.useMemo(
    () =>
      calculateBattlefieldLayout({
        viewportWidth: viewport.width,
        viewportHeight: viewport.height,
        mapWidth: CONTENT.maps[CONTENT.encounters[state.encounterId].mapId].width,
        mapHeight: CONTENT.maps[CONTENT.encounters[state.encounterId].mapId].height
      }),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [viewport, state.encounterId]
  );

  const stage = React.useMemo(
    () => ({
      left: 0,
      top: HUD_LAYOUT.reserved.top,
      width: Math.max(120, viewport.width - (layout.compact ? 0 : HUD_LAYOUT.reserved.right)),
      height: Math.max(
        120,
        viewport.height - HUD_LAYOUT.reserved.top - HUD_LAYOUT.reserved.bottom
      )
    }),
    [viewport, layout.compact]
  );

  const battleMap = React.useMemo(
    () => CONTENT.maps[CONTENT.encounters[state.encounterId].mapId],
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [state.encounterId, version]
  );

  const mapBounds = React.useMemo(
    () => calculateProjectedMapBounds(battleMap, projection),
    [battleMap, projection]
  );

  // World origin offset so negative projected coordinates stay renderable.
  const worldOrigin = React.useMemo(
    () => ({ originX: -mapBounds.minX, originY: -mapBounds.minY }),
    [mapBounds]
  );

  const cameraForStage = React.useMemo(
    () => ({
      zoom: camera.zoom,
      panX: camera.panX + worldOrigin.originX * camera.zoom,
      panY: camera.panY + worldOrigin.originY * camera.zoom
    }),
    [camera, worldOrigin]
  );

  const fitCamera = React.useCallback(() => {
    setCamera(fitCameraToMap(battleMap, stage, projection));
  }, [battleMap, stage, projection]);

  React.useEffect(() => {
    fitCamera();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [battleMap, stage.width, stage.height]);

  const focusTile = React.useCallback(
    (tile) => {
      if (!tile) return;
      setCamera((current) =>
        clampCameraToBounds(
          focusCameraOnTile(current, tile, stage, projection),
          battleMap,
          stage,
          projection
        )
      );
    },
    [battleMap, stage, projection]
  );

  React.useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const stored = await window.storage.get("debugPrefs");
        if (cancelled || !stored) return;
        const prefs = JSON.parse(stored.value);
        if (prefs.seed != null) setSeed(prefs.seed);
        if (prefs.speedId) setSpeedId(prefs.speedId);
      } catch (error) {
        /* no stored preferences yet */
      }
    })();
    return () => {
      cancelled = true;
    };
  }, []);

  const savePrefs = (next) => {
    try {
      window.storage.set("debugPrefs", JSON.stringify(next));
    } catch (error) {
      /* preferences are optional */
    }
  };

  const clearTimers = () => {
    for (const timer of timersRef.current) clearTimeout(timer);
    timersRef.current = [];
  };
  const later = (fn, ms) => {
    const timer = setTimeout(fn, ms);
    timersRef.current.push(timer);
    return timer;
  };

  const pushPopup = (unitId, text, kind, duration) => {
    const unit = state.units[unitId];
    if (!unit) return;
    popupIdRef.current += 1;
    const popup = {
      id: popupIdRef.current,
      x: unit.x,
      y: unit.y,
      elevation: elevationAt(battleMap, unit.x, unit.y) || 0,
      text,
      kind
    };
    setPopups((current) => current.concat(popup));
    later(
      () => setPopups((current) => current.filter((entry) => entry.id !== popup.id)),
      duration + 250
    );
  };

  const pushBattleEffect = (effect, duration) => {
    effectIdRef.current += 1;
    const entry = { ...effect, id: effectIdRef.current };
    setEffects((current) => current.concat(entry));
    later(
      () => setEffects((current) => current.filter((item) => item.id !== entry.id)),
      Math.max(90, duration || 0)
    );
  };

  const presentationTileForUnit = (unitId) => {
    const override = positions[unitId];
    const unit = state.units[unitId];
    if (!override && !unit) return null;
    return override
      ? { x: override.x, y: override.y, elevation: override.elevation || 0 }
      : { x: unit.x, y: unit.y, elevation: elevationAt(battleMap, unit.x, unit.y) || 0 };
  };

  const playPresentation = (events, onDone) => {
    if (!events.length) {
      if (onDone) onDone();
      touch();
      return;
    }
    // Pre-seed movement overrides so a token never flashes at its destination
    // before its animation starts.
    const overrides = {};
    for (const event of events) {
      if (event.type === "moveAnimation" && !overrides[event.unitId]) {
        overrides[event.unitId] = {
          x: event.path[0].x,
          y: event.path[0].y,
          elevation: elevationAt(battleMap, event.path[0].x, event.path[0].y) || 0,
          duration: 0,
          facing:
            (event.stepFacings && event.stepFacings[0]) ||
            event.startFacing ||
            (state.units[event.unitId] && state.units[event.unitId].facing) ||
            "southeast"
        };
      }
    }
    if (Object.keys(overrides).length) {
      setPositions((current) => ({ ...overrides, ...current }));
    }
    doneRef.current = onDone || null;
    setPresentation({ queue: events, index: 0 });
  };

  React.useEffect(() => () => clearTimers(), []);

  // Presentation queue driver: one presentation event at a time.
  React.useEffect(() => {
    const queue = presentation.queue;
    const index = presentation.index;
    if (!queue.length) return;
    if (index >= queue.length) {
      const done = doneRef.current;
      doneRef.current = null;
      setPresentation({ queue: [], index: 0 });
      setPositions({});
      setEffects([]);
      setLungingUnitId(null);
      if (done) done();
      touch();
      return;
    }
    const event = queue[index];
    const duration = presentationEventDuration(event, timing);

    if (event.type === "moveAnimation") {
      const step = timing.moveTile;
      setPositions((current) => ({
        ...current,
        [event.unitId]: {
          x: event.path[0].x,
          y: event.path[0].y,
          elevation: elevationAt(battleMap, event.path[0].x, event.path[0].y) || 0,
          duration: 0,
          facing:
            (event.stepFacings && event.stepFacings[0]) ||
            event.startFacing ||
            (state.units[event.unitId] && state.units[event.unitId].facing) ||
            "southeast"
        }
      }));
      event.path.slice(1).forEach((tile, tileIndex) => {
        later(() => {
          setPositions((current) => ({
            ...current,
            [event.unitId]: {
              x: tile.x,
              y: tile.y,
              elevation: elevationAt(battleMap, tile.x, tile.y) || 0,
              duration: step,
              facing:
                (event.stepFacings && event.stepFacings[tileIndex]) ||
                facingFromTiles(event.path[tileIndex], tile, event.startFacing)
            }
          }));
        }, step * tileIndex);
      });
    } else if (event.type === "attackAnimation") {
      if (event.facing) {
        setPositions((current) => {
          const prior = current[event.sourceUnitId];
          const actor = state.units[event.sourceUnitId];
          return {
            ...current,
            [event.sourceUnitId]: prior
              ? { ...prior, facing: event.facing, duration: 0 }
              : {
                  x: actor.x,
                  y: actor.y,
                  elevation: elevationAt(battleMap, actor.x, actor.y) || 0,
                  duration: 0,
                  facing: event.facing
                }
          };
        });
      }
      setLungingUnitId(event.sourceUnitId);
      const from = presentationTileForUnit(event.sourceUnitId);
      const targetId = (event.targetUnitIds || [])[0];
      const to = targetId
        ? presentationTileForUnit(targetId)
        : event.targetTile
          ? { ...event.targetTile, elevation: elevationAt(battleMap, event.targetTile.x, event.targetTile.y) || 0 }
          : null;
      if (from && to) {
        pushBattleEffect({
          type: "projectile",
          kind: (event.profile && event.profile.kind) || "ballistic",
          glyph: event.profile && event.profile.projectileGlyph,
          from,
          to
        }, duration);
      }
      later(() => setLungingUnitId(null), Math.max(60, duration));
    } else if (event.type === "impactAnimation") {
      const to = presentationTileForUnit(event.targetUnitId);
      if (to) pushBattleEffect({ type: "impact", kind: event.kind, glyph: event.glyph, to }, duration);
    } else if (event.type === "shieldAnimation") {
      const to = presentationTileForUnit(event.targetUnitId);
      if (to) pushBattleEffect({ type: "shield", kind: "shield", glyph: event.glyph, to }, duration);
    } else if (event.type === "defeatAnimation") {
      const to = presentationTileForUnit(event.unitId);
      if (to) pushBattleEffect({ type: "impact", kind: "damage", glyph: "✹", to }, duration);
    } else if (event.type === "floatingNumber") {
      pushPopup(
        event.targetUnitId,
        (event.kind === "heal" ? "+" : "-") + Math.abs(event.amount),
        event.kind,
        duration
      );
      if (event.kind === "heal") mark("healing");
    } else if (event.type === "floatingText") {
      pushPopup(event.targetUnitId, event.text, event.kind, duration);
    } else if (event.type === "statusPopup") {
      const definition = CONTENT.statuses[event.statusId];
      pushPopup(event.targetUnitId, definition.name + " " + event.kind, "status", duration);
      if (event.kind === "applied" || event.kind === "triggered") mark("poison");
    } else if (event.type === "timelineShift") {
      mark("timelineDelay");
    }

    later(() => setPresentation({ queue: queue, index: index + 1 }), duration);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [presentation, timing]);

  // The turn driver stops while anything is on screen. A mission scene counts:
  // that is what "pause tactical simulation safely" means in practice — the
  // simulation is not mid-anything, it simply is not asked for the next turn.
  const busy =
    presentation.queue.length > 0 ||
    combatDialogueQueue.length > 0 ||
    !!missionScene ||
    !!(state.mission && state.mission.wait) ||
    !!(state.reactions && state.reactions.window);

  const threatZone = React.useMemo(() => {
    if (!input.threatUnitId || !state.units[input.threatUnitId]) return null;
    return calculateUnitThreatZone(state, input.threatUnitId, {
      abilityId: input.threatAbilityId || undefined
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [state, input.threatUnitId, input.threatAbilityId, presentation, version]);

  const threatSummary = React.useMemo(() => {
    if (!input.threatUnitId || !state.units[input.threatUnitId]) return null;
    return createThreatSummary(state, input.threatUnitId);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [state, input.threatUnitId, presentation, version]);

  const reactions = React.useMemo(
    () => reactionModel(state),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [state, version, presentation]
  );

  const answerReaction = React.useCallback(
    (offerId) => {
      resolveReactionChoice(state, offerId || null);
      // Resolving a reaction can end the activation that was on screen. The
      // input machine has no way to notice that on its own, and the version
      // bump alone is not enough — the turn driver refuses to advance while
      // the UI still believes a unit is selected. Reconcile explicitly.
      setInput((current) => reconcileInputWithBattle(current, state));
      touch();
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [state]
  );

  /**
   * The leg the pointer is currently proposing, if the tile under it lies in a
   * straight line from where the route ends.
   */
  const routeCandidate = React.useMemo(() => {
    if (input.mode !== "planningRoute" || !input.routeSegments || !input.hoveredTile) return null;
    const unitId = input.selectedUnitId || state.activeUnitId;
    if (!unitId) return null;
    return straightSegmentTo(routeEndpoint(state, unitId, input.routeSegments), input.hoveredTile);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [state, input.mode, input.routeSegments, input.hoveredTile, input.selectedUnitId, version]);

  /**
   * One planner call, shared by the board overlay and the panel. Drawing the
   * route twice is how a preview starts telling a different story from the
   * numbers beside it.
   */
  const routePreview = React.useMemo(
    () => (input.mode === "planningRoute" ? createRoutePlanModel(state, input, routeCandidate) : null),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [state, input, routeCandidate, version]
  );

  /**
   * The chain under the cursor, or the one already aimed at.
   *
   * Recomputed from live state on every hover, which is the whole reason a
   * player can move an enemy and immediately see a chain that did not exist a
   * moment ago.
   */
  const chainPreview = React.useMemo(() => {
    const unitId = input.selectedUnitId || state.activeUnitId;
    if (!unitId || !propagatingAbility(input.selectedAbilityId)) return null;
    const tile =
      input.mode === "confirmingAction"
        ? input.selectedTarget
        : input.mode === "planningTarget"
        ? input.hoveredTile
        : null;
    if (!tile) return null;
    const occupant = unitAt(state, tile.x, tile.y);
    if (!occupant) return null;
    return createChainPreviewModel(state, unitId, input.selectedAbilityId, occupant.id);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [
    state,
    input.mode,
    input.selectedUnitId,
    input.selectedAbilityId,
    input.hoveredTile,
    input.selectedTarget,
    version
  ]);

  const view = React.useMemo(
    () =>
      createBattleViewModel(state, {
        mode: input.mode,
        selectedUnitId: input.selectedUnitId,
        abilityId: input.selectedAbilityId,
        hoveredTile: input.hoveredTile,
        selectedTargetTile: input.selectedTarget,
        plannedPath: routePreview ? routePreview.tiles : input.plannedPath || input.hoverPath,
        plannedDestination: routePreview
          ? routePreview.endpoint
          : input.plannedMoveDestination,
        route: routePreview,
        chain: chainPreview,
        threatZone
      }),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [state, input, presentation, positions, version, threatZone, routePreview, chainPreview]
  );

  React.useEffect(() => {
    const counts = {};
    for (const entry of view.timeline) {
      counts[entry.unitId] = (counts[entry.unitId] || 0) + 1;
      if (counts[entry.unitId] >= 2) mark("fastRepeat");
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [view.timeline]);

  /**
   * Drains the mission runtime's presentation queue.
   *
   * Everything here is presentation: a scene to show, a camera to move, a
   * music request. None of it can change battle state — the runtime already
   * applied every authoritative change before these requests were queued.
   */
  React.useEffect(() => {
    if (!state.mission) return;
    const requests = takePresentationRequests(state);
    const script = missionScriptFor(state);
    for (const request of requests) {
      if (request.type === "focusCamera" && request.tile) {
        setCamera((current) =>
          focusCameraOnTile(
            current,
            {
              x: request.tile.x,
              y: request.tile.y,
              elevation: elevationAt(battleMap, request.tile.x, request.tile.y) || 0
            },
            { width: stage.width, height: stage.height },
            projection
          )
        );
      } else if (request.type === "requestMusicState") {
        if (appSettings && appSettings.setMusicRequest) {
          appSettings.setMusicRequest({
            context: request.context || "battle",
            missionId: request.track || pendingMissionId || null
          });
        }
      } else if (request.type === "queueBark") {
        const speaker = CAMPAIGN.speakers[request.speaker] || { name: request.speaker };
        setNotice(speaker.name + ": " + request.text);
      }
    }

    // A blocking scene arrives as the runtime's active wait, not in the drain,
    // so a reload can re-show the scene the battle was suspended on.
    const wait = state.mission.wait;
    if (wait && wait.request.type === "showScene") {
      const model = createMissionSceneModel(script, wait.request.sceneRef, wait.token);
      setMissionScene((current) => (current && current.token === wait.token ? current : model));
    } else if (!wait) {
      setMissionScene(null);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [state, version, presentation]);

  const dismissMissionScene = React.useCallback(
    (payload) => {
      const token = missionScene ? missionScene.token : null;
      setMissionScene(null);
      if (!token) return;
      resolveMissionPresentation(state, token, payload || null, {
        campaignFlags: campaign.flags
      });
      checkObjectives(state);
      touch();
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [missionScene, state, campaign]
  );

  React.useEffect(() => {
    if (!pendingMissionId) return;
    const fired = evaluateMidBattleTriggers(pendingMissionId, state, firedTriggersRef.current, campaign);
    if (!fired.length) return;
    firedTriggersRef.current = firedTriggersRef.current.concat(fired.map((entry) => entry.id));
    setStoryLog((current) => current.concat(fired));
    const paused = fired.filter((entry) => entry.pauseBattle !== false);
    if (paused.length) setCombatDialogueQueue((current) => current.concat(paused));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [pendingMissionId, version, presentation, state.finished, campaign]);

  React.useEffect(() => {
    if (state.finished) mark("finishBattle");
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [state.finished, version, presentation]);

  // Turn driver: activates the next unit on the timeline, one at a time.
  //
  // The engine states the continuation; this obeys it. The driver used to
  // decide for itself by reading `input.mode`, which meant any authoritative
  // path that ended an activation without going through the input machine —
  // a resolved reaction, most of all — left the battle waiting for input that
  // could never arrive.
  React.useEffect(() => {
    if (busy) return;
    const next = battleContinuation(state);

    if (next.kind === "finished") {
      mark("finishBattle");
      if (input.mode !== "battleFinished") {
        setInput((current) => inputReducer(current, { type: "battleFinished" }, state).input);
      }
      return;
    }
    if (next.kind === "reaction" || next.kind === "active") return;
    if (next.kind === "stalled") {
      // Never silent. A stall is a bug, and the log is where a bug goes.
      if (!state.__stallReported) {
        state.__stallReported = true;
        state.errors.push("Battle stalled: " + next.reason);
      }
      return;
    }

    // `advance`: the UI may still be showing the unit whose activation just
    // ended. Reconcile before activating anyone, or the reducer will refuse.
    if (input.mode !== "idle") {
      setInput((current) => reconcileInputWithBattle(current, state));
      return;
    }
    const nextId = view.nextUnitId || next.unitId;
    if (!nextId) return;
    const team = view.teams.find((entry) => entry.id === state.units[nextId].teamId);
    const nextName = view.units.find((unit) => unit.id === nextId).name;
    mark("startEncounter");
    if (team && team.controller === "human") {
      const result = executeCommandWithPresentation(state, {
        type: "activateUnit",
        unitId: nextId
      });
      const readyUnit = state.units[nextId];
      const readyWorld = projectTileToWorld(
        {
          x: readyUnit.x,
          y: readyUnit.y,
          elevation: elevationAt(battleMap, readyUnit.x, readyUnit.y) || 0
        },
        projection
      );
      if (!isWorldPointVisible(readyWorld, cameraForStage, stage, 80)) {
        focusTile({
          x: readyUnit.x,
          y: readyUnit.y,
          elevation: elevationAt(battleMap, readyUnit.x, readyUnit.y) || 0
        });
      }
      setNotice(nextName + " is ready.");
      playPresentation(result.presentation, () => {
        if (state.activeUnitId === nextId) {
          mark("selectUnit");
          setAbilityMenuOpen(false);
          setInput(
            (current) =>
              inputReducer(current, { type: "activationStarted", unitId: nextId }, state).input
          );
        }
      });
    } else {
      const result = runAiActivationWithPresentation(state);
      mark("enemyActivation");
      setNotice(nextName + " (enemy) is acting.");
      playPresentation(result.presentation, touch);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [busy, input.mode, view.nextUnitId, state.activeUnitId, state.finished, version]);

  const dispatch = (action) => {
    if (action.type !== "openMenu" && action.type !== "hoverTile" && action.type !== "inspectUnit") {
      setAbilityMenuOpen(false);
    }
    const outcome = inputReducer(input, action, state);
    setInput(outcome.input);
    if (outcome.errors.length) setNotice(outcome.errors[0]);
    if (!outcome.commands.length) return outcome;
    const events = [];
    let failed = null;
    for (const command of outcome.commands) {
      const result = executeCommandWithPresentation(state, command);
      if (!result.ok) {
        failed = result.errors[0];
        break;
      }
      if (command.type === "move") mark("confirmMovement");
      if (command.type === "useAbility") mark("confirmAttack");
      for (const event of result.presentation) events.push(event);
    }
    if (failed) {
      setNotice(failed);
      setInput((current) => inputReducer(current, { type: "presentationFinished" }, state).input);
      return outcome;
    }
    playPresentation(events, () => {
      setInput((current) => inputReducer(current, { type: "presentationFinished" }, state).input);
    });
    return outcome;
  };

  const onHoverTile = (tile) => {
    if (busy) return;
    dispatch({ type: "hoverTile", tile });
    if (tile) setCursor({ x: tile.x, y: tile.y });
    if (tile && !view.finished && input.mode !== "planningTarget") mark("previewMovement");
  };

  const onClickTile = (tile) => {
    if (busy) return;
    if (suppressClickRef.current) {
      suppressClickRef.current = false;
      return;
    }
    const outcome = dispatch({ type: "clickTile", tile });
    if (outcome.input.mode === "confirmingAction") mark("previewTarget");
    if (outcome.input.mode === "planningMove") mark("previewMovement");
  };

  const stagePoint = (event) => {
    const rect = stageRef.current
      ? stageRef.current.getBoundingClientRect()
      : { left: stage.left, top: stage.top };
    return { x: event.clientX - rect.left, y: event.clientY - rect.top };
  };

  const onStageWheel = (event) => {
    event.preventDefault();
    const point = stagePoint(event);
    const direction = event.deltaY > 0 ? -1 : 1;
    setCamera((current) =>
      clampCameraToBounds(
        zoomCameraAtPoint(
          current,
          point,
          current.zoom * (1 + direction * projection.zoomStep),
          projection
        ),
        battleMap,
        stage,
        projection
      )
    );
  };

  const onStagePointerDown = (event) => {
    if (event.button === 2) return;
    // Do not capture the pointer on a normal press. Capturing here retargets the
    // eventual click to the camera stage in real browsers, so TileBlock.onClick
    // never fires. Capture only after the gesture has crossed the drag threshold.
    suppressClickRef.current = false;
    dragRef.current = {
      pointerId: event.pointerId,
      startX: event.clientX,
      startY: event.clientY,
      camera,
      distance: 0,
      dragging: false,
      captured: false
    };
  };

  const onStagePointerMove = (event) => {
    const drag = dragRef.current;
    if (!drag || event.pointerId !== drag.pointerId) return;
    const deltaX = event.clientX - drag.startX;
    const deltaY = event.clientY - drag.startY;
    drag.distance = Math.max(drag.distance, Math.abs(deltaX) + Math.abs(deltaY));
    if (!drag.dragging && drag.distance < projection.dragThresholdPx) return;
    if (!drag.dragging) {
      drag.dragging = true;
      if (event.currentTarget.setPointerCapture) {
        try {
          event.currentTarget.setPointerCapture(event.pointerId);
          drag.captured = true;
        } catch (error) {
          /* pointer capture is optional */
        }
      }
    }
    setCamera(
      clampCameraToBounds(
        { ...drag.camera, panX: drag.camera.panX + deltaX, panY: drag.camera.panY + deltaY },
        battleMap,
        stage,
        projection
      )
    );
  };

  const endDrag = (event) => {
    const drag = dragRef.current;
    dragRef.current = null;
    if (!drag) return false;
    if (
      drag.captured &&
      event &&
      event.currentTarget &&
      event.currentTarget.releasePointerCapture
    ) {
      try {
        event.currentTarget.releasePointerCapture(drag.pointerId);
      } catch (error) {
        /* pointer capture is optional */
      }
    }
    return drag.dragging;
  };

  const onStagePointerUp = (event) => {
    const dragged = endDrag(event);
    if (dragged) suppressClickRef.current = true;
  };

  const onRightClickTile = (tile) => {
    if (busy) return;
    dispatch({ type: "rightClickTile", tile });
  };

  const activeUnit = view.units.find((unit) => unit.id === state.activeUnitId) || null;
  const inspected =
    view.units.find((unit) => unit.id === input.inspectedUnitId) || activeUnit || view.units[0];

  const hoveredUnitId = React.useMemo(() => {
    if (!input.hoveredTile) return null;
    const tile = view.tiles.find(
      (entry) => entry.x === input.hoveredTile.x && entry.y === input.hoveredTile.y
    );
    return tile ? tile.unitId : null;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [input.hoveredTile, view.tiles]);

  const activeResources = React.useMemo(
    () => (state.activeUnitId ? createActivationResources(state, state.activeUnitId) : null),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [state, presentation, version, input.mode]
  );

  const menu = React.useMemo(() => {
    if (!state.activeUnitId) return null;
    const forecastTargetId =
      input.forecast && input.forecast.target ? input.forecast.target.unitId : null;
    const targetUnitId =
      forecastTargetId ||
      hoveredUnitId ||
      (input.inspectedUnitId !== state.activeUnitId ? input.inspectedUnitId : null);
    const suggested =
      activeResources && activeResources.moved && !activeResources.acted
        ? defaultAbilityIdFor(state, state.activeUnitId)
        : null;
    return createCommandMenu(state, state.activeUnitId, {
      targetUnitId,
      suggestedAbilityId: input.selectedAbilityId || suggested
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [state, input, presentation, version, hoveredUnitId, activeResources]);

  const plannedDestination = React.useMemo(() => {
    if (!input.plannedPath || !input.selectedUnitId) return null;
    const last = input.plannedPath[input.plannedPath.length - 1];
    const tile = view.tiles.find((entry) => entry.x === last.x && entry.y === last.y);
    return {
      x: last.x,
      y: last.y,
      tiles: input.plannedPath.length - 1,
      cost: tile && tile.moveCost != null ? tile.moveCost : 0
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [input.plannedPath, view.tiles]);

  const moveRecovery = React.useMemo(() => {
    if (!input.selectedUnitId || !plannedDestination) return null;
    return calculateActionRecoveryPreview(
      state,
      input.selectedUnitId,
      null,
      plannedDestination.tiles
    );
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [state, input.selectedUnitId, plannedDestination]);

  const destinationForecasts = React.useMemo(() => {
    if (!plannedDestination || !input.selectedUnitId || input.plannedSequence) return null;
    if (input.mode !== "planningMove") return null;
    return createDestinationForecasts(state, input.selectedUnitId, plannedDestination);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [state, input.mode, input.selectedUnitId, plannedDestination, input.plannedSequence]);

  const shownForecast = input.forecast || input.hoverForecast;

  const badges = React.useMemo(() => {
    const list = [];
    const forecast = shownForecast;
    if (forecast && forecast.valid && forecast.target) {
      const target = view.units.find((unit) => unit.id === forecast.target.unitId);
      if (target) {
        list.push({
          x: target.x,
          y: target.y,
          elevation: target.elevation,
          kind: forecast.headline.kind,
          lethal: !!forecast.headline.lethal,
          text:
            (forecast.headline.kind === "heal" ? "+" : "") +
            forecast.headline.value +
            (forecast.headline.kind === "heal" ? " HP" : " DMG") +
            (forecast.headline.lethal
              ? " KO"
              : forecast.headline.hitChancePercent != null
              ? " " + forecast.headline.hitChancePercent + "%"
              : "")
        });
      }
    }
    return list;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [shownForecast, view.units]);

  const alternateTimeline = React.useMemo(() => {
    if (!input.selectedUnitId) return null;
    if (input.mode === "planningMove" && moveRecovery) {
      return previewTimelineAfterRecovery(
        state,
        input.selectedUnitId,
        moveRecovery.totalRecovery,
        12
      );
    }
    if (shownForecast && shownForecast.valid) {
      return previewTimelineAfterRecovery(
        state,
        input.selectedUnitId,
        shownForecast.recovery.totalRecovery,
        12
      );
    }
    return null;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [state, input.mode, shownForecast, moveRecovery, input.selectedUnitId]);

  const logGroups = React.useMemo(
    () => createBattleLogViewModel(state, logFilter),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [state, logFilter, presentation, version]
  );

  const summary = React.useMemo(
    () => (state.finished ? createBattleSummary(state) : null),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [state, state.finished, presentation, version]
  );

  /* ---- keyboard ---- */
  React.useEffect(() => {
    if (typeof window === "undefined") return undefined;
    const onKey = (event) => {
      if (appSettings && appSettings.settingsOpen) return;
      if (busy) return;
      const key = event.key;
      if (key === "Enter") {
        if (
          input.mode === "confirmingAction" ||
          input.mode === "planningMove" ||
          (input.mode === "planningRoute" && input.routeSegments && input.routeSegments.length)
        ) {
          dispatch({ type: "confirm" });
        } else if (input.mode === "planningOrder") {
          dispatch({ type: "confirmOrder" });
        } else {
          dispatch({ type: "clickTile", tile: cursor });
        }
        return;
      }
      if (key === "Backspace" && input.mode === "planningRoute") {
        event.preventDefault();
        dispatch({ type: "undoRouteSegment" });
        return;
      }
      if (key === "Backspace" && input.mode === "planningOrder") {
        event.preventDefault();
        dispatch({ type: "undoOrderPick" });
        return;
      }
      const moves = {
        ArrowUp: [0, -1],
        ArrowDown: [0, 1],
        ArrowLeft: [-1, 0],
        ArrowRight: [1, 0],
        w: [0, -1],
        s: [0, 1],
        a: [-1, 0],
        d: [1, 0]
      };
      if (moves[key]) {
        event.preventDefault();
        const next = {
          x: Math.max(0, Math.min(view.width - 1, cursor.x + moves[key][0])),
          y: Math.max(0, Math.min(view.height - 1, cursor.y + moves[key][1]))
        };
        setCursor(next);
        dispatch({ type: "hoverTile", tile: next });
        return;
      }
      if (key === "m" || key === "M") {
        dispatch({ type: "chooseMove" });
        return;
      }
      if (key === "q" || key === "Q") {
        dispatch({ type: "wait" });
        return;
      }
      if (key === "e" || key === "E") {
        dispatch({ type: "endTurn" });
        return;
      }
      if (/^[1-9]$/.test(key) && input.contextOptions && input.contextOptions.length) {
        const option = input.contextOptions[Number(key) - 1];
        if (option) dispatch({ type: "chooseContextOption", abilityId: option.abilityId });
        return;
      }
      if (/^[1-9]$/.test(key) && menu) {
        const abilities = menu.entries.filter((entry) => entry.kind === "ability");
        const ability = abilities[Number(key) - 1];
        if (ability && ability.enabled) {
          mark("selectAbility");
          dispatch({ type: "chooseAbility", abilityId: ability.id });
        }
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [input, cursor, busy, menu, view.width, view.height, appSettings && appSettings.settingsOpen]);

  /* ---- battle lifecycle ---- */
  const startBattle = (nextSeed) => {
    clearTimers();
    battleRef.current = createBattle(activeEncounterId(), Number(nextSeed), {
      roster: rosterRef.current,
      rosterTeamId: "player",
      autoResolveReactions: false
    });
    setInput(createInputState());
    setPresentation({ queue: [], index: 0 });
    setPositions({});
    setPopups([]);
    setCombatDialogueQueue([]);
    firedTriggersRef.current = [];
    setNotice("New battle started with seed " + nextSeed + ".");
    mark("startEncounter");
    touch();
  };

  const devRun = (fn, message) => {
    clearTimers();
    fn();
    setInput(createInputState());
    setPresentation({ queue: [], index: 0 });
    setNotice(message);
    touch();
  };

  const runAllTests = () => {
    setRunning(true);
    setTimeout(() => {
      setTestResults(runTests());
      setAudit(auditArchitecture());
      setRunning(false);
      setDevTab("tests");
    }, 10);
  };

  const deploymentModel = React.useMemo(
    () =>
      pendingMissionId && deployment
        ? createCampaignDeploymentModel(campaign, pendingMissionId, deployment)
        : null,
    [campaign, pendingMissionId, deployment]
  );
  const deploymentValidation = deploymentModel
    ? deploymentModel.validation
    : { valid: false, errors: ["No campaign deployment is active."] };

  const activeEncounterId = React.useCallback(
    () =>
      (pendingMissionId && missionEncounterId(pendingMissionId, campaign)) || deploymentEncounterId(),
    [pendingMissionId, campaign]
  );

  const baseModel = React.useMemo(() => createBaseModel(campaign), [campaign]);
  const missionBoard = React.useMemo(() => createMissionBoardModel(campaign), [campaign]);

  const contentReport = React.useMemo(() => validateContent(), []);
  const blocked = contentReport.errors.length > 0;
  const stageLabel = MODE_LABELS[input.mode] || input.mode;

  const hud = React.useMemo(
    () => createBattleHudModel(state),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [state, presentation, version]
  );

  const characterSheet = React.useMemo(
    () =>
      createCharacterSheetModel(
        state,
        input.inspectedUnitId || state.activeUnitId || view.units[0].id
      ),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [state, input.inspectedUnitId, presentation, version]
  );

  const unitCard = React.useMemo(
    () =>
      createUnitCardModel(
        state,
        input.inspectedUnitId || state.activeUnitId || hoveredUnitId || view.units[0].id
      ),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [state, input.inspectedUnitId, hoveredUnitId, presentation, version]
  );

  const hudPanel = React.useMemo(
    () =>
      state.activeUnitId && input.commandMenuOpen
        ? createBattleHudPanelModel(state, state.activeUnitId)
        : null,
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [state, state.activeUnitId, input.commandMenuOpen, presentation, version]
  );

  const contextModel = React.useMemo(
    () =>
      createContextCommandModel(state, input, {
        abilityMenuOpen,
        routeCandidate,
        chain: chainPreview,
        targetUnitId:
          input.forecast && input.forecast.target
            ? input.forecast.target.unitId
            : hoveredUnitId,
        origin: input.plannedMoveDestination || undefined,
        movementTiles: input.plannedPath ? input.plannedPath.length - 1 : undefined
      }),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [state, input, abilityMenuOpen, hoveredUnitId, presentation, version, routeCandidate, chainPreview]
  );

  const panelVisible = contextModel.visible && !busy;
  const panelHeight = React.useMemo(() => {
    if (!contextModel.visible) return 0;
    if (contextModel.kind === "abilities") return 60 + contextModel.abilities.length * 46;
    if (contextModel.kind === "route") {
      const route = contextModel.route;
      return (
        90 +
        contextModel.actions.length * 26 +
        route.segments.length * 16 +
        route.cost.breakdown.length * 14 +
        route.contacts.length * 74
      );
    }
    if (contextModel.kind === "order") {
      return 130 + contextModel.actions.length * 26 + contextModel.order.entries.length * 30;
    }
    if (contextModel.forecast) {
      return 250 + (contextModel.chain ? 40 + contextModel.chain.nodes.length * 16 : 0);
    }
    return 56 + contextModel.actions.length * 26 + contextModel.lines.length * 4;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [contextModel]);

  const anchorRectFor = React.useCallback(
    (tile) => {
      if (!tile) return null;
      const elevation = elevationAt(battleMap, tile.x, tile.y) || 0;
      const rect = projectTileScreenRect(
        { x: tile.x, y: tile.y, elevation },
        cameraForStage,
        projection
      );
      return {
        left: rect.left + stage.left,
        top: rect.top + stage.top,
        right: rect.right + stage.left,
        bottom: rect.bottom + stage.top,
        width: rect.width,
        height: rect.height
      };
    },
    [battleMap, cameraForStage, projection, stage]
  );

  const panelPosition = React.useMemo(
    () =>
      calculateFloatingPanelPosition({
        anchor: contextModel.anchorTile || { x: 0, y: 0 },
        anchorRect: anchorRectFor(contextModel.anchorTile),
        viewport: { width: viewport.width, height: viewport.height },
        bounds: layout.stageBounds,
        panelWidth: PANEL_WIDTH,
        panelHeight: Math.max(120, panelHeight)
      }),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [contextModel.anchorTile, layout, viewport, panelHeight, anchorRectFor]
  );

  const hoverBadge = React.useMemo(() => {
    if (busy || !input.hoveredTile) return null;
    return createHoverForecastModel(state, input, input.hoveredTile);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [state, input.hoveredTile, input.mode, input.selectedAbilityId, busy, version]);

  const hoverBadgePosition = React.useMemo(() => {
    if (!input.hoveredTile) return { left: 0, top: 0 };
    const placed = calculateFloatingPanelPosition({
      anchor: input.hoveredTile,
      anchorRect: anchorRectFor(input.hoveredTile),
      viewport: { width: viewport.width, height: viewport.height },
      bounds: layout.stageBounds,
      panelWidth: 200,
      panelHeight: 56,
      gap: 8
    });
    return { left: placed.left, top: placed.top };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [input.hoveredTile, layout, viewport, anchorRectFor]);

  const onPanelAction = (entry) => {
    if (!entry.enabled) return;
    switch (entry.id) {
      case "move":
      case "changeTile":
        setAbilityMenuOpen(false);
        dispatch({ type: "chooseMove" });
        return;
      case "abilities":
      case "changeAbility":
        setAbilityMenuOpen(true);
        dispatch({ type: "openMenu" });
        return;
      case "attackFromHere":
        setAbilityMenuOpen(true);
        dispatch({ type: "confirm" });
        return;
      case "wait":
        setAbilityMenuOpen(false);
        dispatch({ type: "wait" });
        return;
      case "endTurn":
        setAbilityMenuOpen(false);
        dispatch({ type: "endTurn" });
        return;
      case "confirm":
        setAbilityMenuOpen(false);
        dispatch({ type: "confirm" });
        return;
      case "undoRouteSegment":
        dispatch({ type: "undoRouteSegment" });
        return;
      case "confirmOrder":
        setAbilityMenuOpen(false);
        dispatch({ type: "confirmOrder" });
        return;
      case "undoOrderPick":
        dispatch({ type: "undoOrderPick" });
        return;
      case "cancel":
        setAbilityMenuOpen(false);
        dispatch({ type: "cancel" });
        return;
      default:
        return;
    }
  };

  const onPanelAbility = (entry) => {
    if (!entry.enabled) return;
    mark("selectAbility");
    setAbilityMenuOpen(false);
    dispatch({ type: "chooseAbility", abilityId: entry.id });
  };

  const launchMission = (missionId) => {
    const nextCampaign = beginMission(campaign, missionId);
    setCampaign(nextCampaign);
    setPendingMissionId(missionId);
    setDeployment(createCampaignDeploymentState(nextCampaign, missionId));
    setPendingOutcome(null);
    setMissionResult(null);
    setDeployed(false);
    firedTriggersRef.current = [];
    setStoryLog([]);
    setCombatDialogueQueue([]);
    // An authored scene, if the mission names one, plays before the briefing.
    // Missions without one behave exactly as before.
    const authored = missionSceneFor(missionId, "preMissionScene");
    setPendingScene(authored ? { scene: authored, next: "briefing" } : null);
    setScreen(authored ? "authoredScene" : "briefing");
  };

  const finishMission = (victory) => {
    const missionId = pendingMissionId;
    if (!missionId) return;
    const battle = battleRef.current;
    const outcome = {
      victory,
      activations: battle.activationCount,
      conditions: collectMissionConditions(battle, rosterRef.current),
      facts: collectMissionFacts(battle, missionId),
      // Who is not walking away. A drop needs this: being on the board is not
      // the same claim as having been defeated.
      defeated: collectDefeatedSources(battle)
    };
    setPendingOutcome(outcome);
    setDeployed(false);
    setScreen(victory ? "aftermath" : "defeatStory");
  };

  const finalizeMission = (providedOutcome) => {
    const missionId = pendingMissionId;
    const outcome = providedOutcome || pendingOutcome;
    if (!missionId || !outcome) return;
    // Planned from the campaign as it stands *before* resolution, which is the
    // same input `resolveMissionOutcome` plans from — deterministic keys mean
    // both calls produce an identical receipt, so the screen shows exactly
    // what was paid. Applying is still guarded by the receipt id, so a second
    // finalize for the same attempt changes nothing.
    const receipt = planMissionRewards(campaign, missionId, outcome);
    const resolved = resolveMissionOutcome(campaign, missionId, outcome);
    setCampaign(resolved);
    setMissionResult(createMissionResultModel(resolved, missionId, outcome, receipt));
    setPendingOutcome(null);
    setDeployed(false);
    setScreen("results");
  };

  const completeStoryScene = (sceneId) => {
    if (!pendingMissionId) return;
    setCampaign((current) => markStorySceneComplete(current, pendingMissionId, sceneId));
  };

  if (screen === "base") {
    return (
      <ResistanceBase
        base={baseModel}
        saveNote={saveNote}
        onMissions={() => setScreen("missions")}
        onRoster={() => setScreen("roster")}
        onEnd={() => setScreen("prototypeEnd")}
        onRepair={(operatorId) => setCampaign((current) => repairCampaignOperator(current, operatorId))}
        onBuildFacility={(facilityId) => setCampaign((current) => buildCampaignFacility(current, facilityId))}
        onChoosePerk={(operatorId, perkId) => setCampaign((current) => chooseCampaignPerk(current, operatorId, perkId))}
        onSave={() => {
          const serialized = saveCampaign(campaign);
          const written = writeCampaignSlot(serialized);
          setSaveNote(
            written
              ? "Campaign saved (" + serialized.length + " bytes)."
              : "Could not save — browser storage is unavailable."
          );
        }}
        onLoad={() => {
          const loaded = loadCampaignSlot();
          if (loaded) {
            setCampaign(loaded);
            setSaveNote("Campaign loaded.");
          } else {
            setSaveNote("No save found.");
          }
        }}
      />
    );
  }

  if (screen === "missions") {
    return (
      <MissionBoard
        board={missionBoard}
        onBack={() => setScreen("base")}
        onSelect={launchMission}
      />
    );
  }

  if (screen === "roster") {
    return <RosterScreen base={baseModel} onBack={() => setScreen("base")} />;
  }

  if (screen === "briefing" && pendingMissionId) {
    const mission = missionBoard.find((entry) => entry.missionId === pendingMissionId);
    const sequence = createStorySequenceModel(campaign, pendingMissionId, "briefing", null);
    return (
      <StorySequenceScreen
        key={pendingMissionId + ":briefing"}
        sequence={sequence}
        title={mission.name}
        subtitle={mission.chapterName + " · " + mission.objectiveText}
        onChoose={(choiceId, optionId) =>
          setCampaign((current) => applyDialogueChoice(current, choiceId, optionId))
        }
        onSceneComplete={completeStoryScene}
        onComplete={() => {
          if (mission.kind === "story") {
            finalizeMission({ victory: true, activations: 0, conditions: { byOperator: {} }, facts: {} });
            return;
          }
          setScreen("deployment");
        }}
      />
    );
  }

  if ((screen === "aftermath" || screen === "defeatStory") && pendingMissionId && pendingOutcome) {
    const mission = missionBoard.find((entry) => entry.missionId === pendingMissionId);
    const sequenceId = pendingOutcome.victory ? "victory" : "defeat";
    const storyCampaign = previewCampaignOutcomeFlags(campaign, pendingMissionId, pendingOutcome);
    const sequence = createStorySequenceModel(storyCampaign, pendingMissionId, sequenceId, {
      outcome: pendingOutcome
    });
    return (
      <StorySequenceScreen
        key={pendingMissionId + ":" + sequenceId}
        sequence={sequence}
        title={pendingOutcome.victory ? "Mission Aftermath" : "Mission Defeat"}
        subtitle={mission.name + " · " + mission.objectiveText}
        onChoose={(choiceId, optionId) =>
          setCampaign((current) => applyDialogueChoice(current, choiceId, optionId))
        }
        onSceneComplete={completeStoryScene}
        onComplete={() => finalizeMission(pendingOutcome)}
      />
    );
  }

  // An authored scene playing inside the campaign flow. The same player the
  // editor previews with, so what an author sees is what a player gets.
  if (screen === "authoredScene" && pendingScene) {
    return (
      <ScenePlayer
        scene={pendingScene.scene}
        onComplete={() => {
          const next = pendingScene.next;
          setPendingScene(null);
          setScreen(next);
        }}
      />
    );
  }

  if (screen === "results" && missionResult) {
    return (
      <ResultsScreen
        result={missionResult}
        onRetry={() => launchMission(missionResult.missionId)}
        onContinue={() => {
          const after = missionSceneFor(missionResult.missionId, "postMissionScene");
          const destination = missionResult.prototypeComplete ? "prototypeEnd" : "base";
          setPendingMissionId(null);
          setDeployment(null);
          setMissionResult(null);
          setPendingScene(after ? { scene: after, next: destination } : null);
          setScreen(after ? "authoredScene" : destination);
        }}
      />
    );
  }

  if (screen === "prototypeEnd") {
    return <EndOfPrototype base={baseModel} onBase={() => setScreen("base")} />;
  }

  if (screen === "deployment" && deploymentModel) {
    return (
      <DeploymentScreen
        model={deploymentModel}
        onBack={() => setScreen("missions")}
        onToggle={(operatorId) =>
          setDeployment((current) => toggleCampaignOperator(campaign, pendingMissionId, current, operatorId))
        }
        onInspect={(operatorId) =>
          setDeployment((current) => ({ ...current, inspectedOperatorId: operatorId, error: null }))
        }
        onEquip={(operatorId, slot, equipmentId) =>
          setDeployment((current) => equipCampaignPart(campaign, current, operatorId, slot, equipmentId))
        }
        onDeploy={() => {
          if (!deploymentValidation.valid) return;
          const committedCampaign = commitCampaignDeployment(campaign, deployment);
          const roster = createCampaignMissionRoster(committedCampaign, pendingMissionId, deployment);
          setCampaign(committedCampaign);
          rosterRef.current = roster;
          clearTimers();
          battleRef.current = createBattle(activeEncounterId(), Number(seed), {
            roster,
            rosterTeamId: "player",
            autoResolveReactions: false
          });
          setInput(createInputState());
          setPresentation({ queue: [], index: 0 });
          setPositions({});
          setPopups([]);
          setNotice("Lance deployed.");
          mark("startEncounter");
          setDeployed(true);
          setScreen("battle");
          firedTriggersRef.current = [];
          touch();
        }}
      />
    );
  }

  return (
    <div
      style={{ width: "100%", height: "100%", overflow: "hidden" }}
      className="relative bg-slate-950 text-slate-200 font-mono select-none"
    >
      <div className="pointer-events-none absolute inset-0" style={{ background: "radial-gradient(circle at 50% 45%, rgba(30,73,105,0.18), transparent 52%), linear-gradient(180deg, #07111c, #02060c)" }} />
      <div className="pointer-events-none absolute inset-0 opacity-20" style={{ backgroundImage: "linear-gradient(rgba(125,183,226,0.07) 1px, transparent 1px)", backgroundSize: "100% 4px" }} />
      {MISSION_CONTENT.playtestMissionId || GAMEPLAY_DRAFT_ACTIVE ? (
        <div
          className="absolute left-1/2 -translate-x-1/2 z-50 flex items-center gap-3 rounded-b border border-t-0 border-amber-500/60 bg-amber-950/90 px-3 py-1 text-[11px] text-amber-200"
          style={{ top: 0 }}
          data-testid="playtest-banner"
        >
          <span className="font-bold tracking-widest">
            {GAMEPLAY_DRAFT_ACTIVE ? "DATA TEST" : "PLAYTEST"}
          </span>
          {/* Unsaved gameplay data is shaping this battle. Saying which entity,
           *  and how much else moved with it, is the difference between "the
           *  numbers changed" and "the numbers are wrong". */}
          <span className="text-amber-100/80">
            {GAMEPLAY_DRAFT_TEST
              ? GAMEPLAY_DRAFT_TEST.id + " · " + GAMEPLAY_DRAFT_TEST.changed + " edited"
              : MISSION_CONTENT.playtestMissionId}
          </span>
          {GAMEPLAY_DRAFT_TEST && GAMEPLAY_DRAFT_TEST.reason ? (
            <span className="max-w-[36ch] truncate text-amber-100/50" title={GAMEPLAY_DRAFT_TEST.reason}>
              {GAMEPLAY_DRAFT_TEST.reason}
            </span>
          ) : null}
          <button
            className="rounded border border-amber-500/60 px-2 py-0.5 hover:bg-amber-800/60"
            onClick={() => {
              // Both slots go together: the draft is only in play because a
              // test put it there, and leaving it behind would silently change
              // the next normal launch.
              clearPlaytestMission();
              clearGameplayDraft();
              window.location.reload();
            }}
          >
            {GAMEPLAY_DRAFT_ACTIVE ? "Exit data test" : "Exit playtest"}
          </button>
        </div>
      ) : null}
      <TopHud
        hud={hud}
        timeline={view.timeline}
        alternate={alternateTimeline}
        speedId={speedId}
        height={HUD_LAYOUT.reserved.top}
        onSpeed={(value) => {
          setSpeedId(value);
          savePrefs({ seed, speedId: value });
        }}
        onSkip={() => setSpeedId("instant")}
        onToggleDetails={() => setDetailsOpen((open) => !open)}
        onToggleDev={() => setDevOpen((open) => !open)}
        devOpen={devOpen}
      />

      <SideUnitCard
        card={unitCard}
        active={activeUnit}
        activeResources={activeResources}
        threat={
          threatSummary && unitCard && threatSummary.unitId === unitCard.id ? threatSummary : null
        }
        onThreatAbility={(abilityId) =>
          dispatch({ type: "showThreat", unitId: input.threatUnitId, abilityId })
        }
        width={HUD_LAYOUT.reserved.right}
        top={HUD_LAYOUT.reserved.top}
        bottom={HUD_LAYOUT.reserved.bottom}
        onDetails={() => setDetailsOpen(true)}
      />

      <div
        ref={stageRef}
        onWheel={onStageWheel}
        onPointerDown={onStagePointerDown}
        onPointerMove={onStagePointerMove}
        onPointerUp={onStagePointerUp}
        onPointerCancel={onStagePointerUp}
        style={{
          position: "absolute",
          left: stage.left,
          top: stage.top,
          width: stage.width,
          height: stage.height,
          overflow: "hidden",
          touchAction: "none"
        }}
        onContextMenu={(event) => event.preventDefault()}
      >
        <div
          aria-hidden="true"
          style={{
            position: "absolute",
            left: Math.max(18, stage.width * 0.08),
            right: Math.max(18, stage.width * 0.08),
            top: Math.max(18, stage.height * 0.09),
            bottom: Math.max(18, stage.height * 0.11),
            border: "1px solid rgba(125,183,226,0.18)",
            background: "linear-gradient(180deg, rgba(6,16,28,0.55), rgba(2,8,16,0.72))",
            boxShadow: "inset 0 0 0 1px rgba(125,183,226,0.05), 0 24px 70px rgba(0,0,0,0.22)",
            clipPath: "polygon(12% 0%, 88% 0%, 100% 18%, 100% 82%, 88% 100%, 12% 100%, 0% 82%, 0% 18%)"
          }}
        >
          <div
            style={{
              position: "absolute",
              inset: 0,
              opacity: 0.18,
              backgroundImage:
                "linear-gradient(rgba(148,197,232,0.06) 1px, transparent 1px), linear-gradient(90deg, rgba(148,197,232,0.04) 1px, transparent 1px)",
              backgroundSize: "100% 4px, 72px 72px"
            }}
          />
        </div>
        <div
          style={{
            position: "absolute",
            left: 0,
            top: 0,
            transformOrigin: "0 0",
            transform:
              "translate(" +
              cameraForStage.panX +
              "px," +
              cameraForStage.panY +
              "px) scale(" +
              camera.zoom +
              ")"
          }}
        >
          <Battlefield
            view={view}
            projection={projection}
            map={battleMap}
            bounds={{ originX: 0, originY: 0 }}
            positions={positions}
            popups={popups}
            effects={effects}
            badges={badges}
            lungingUnitId={lungingUnitId}
            cameraZoom={camera.zoom}
            showElevation={showElevation}
            showIntel={showIntel}
            onHoverTile={onHoverTile}
            onClickTile={onClickTile}
            onRightClickTile={onRightClickTile}
            disabled={busy || !state.activeUnitId}
          />
        </div>
        <FacingControls
          unit={activeUnit}
          disabled={busy}
          onFace={(facing) => dispatch({ type: "setFacing", facing })}
        />
        <CameraControls
          zoom={camera.zoom}
          showElevation={showElevation}
          onToggleElevation={() => setShowElevation((value) => !value)}
          showIntel={showIntel}
          onToggleIntel={() => setShowIntel((value) => !value)}
          onZoomIn={() =>
            setCamera((current) =>
              zoomCameraAtPoint(
                current,
                { x: stage.width / 2, y: stage.height / 2 },
                current.zoom * (1 + projection.zoomStep),
                projection
              )
            )
          }
          onZoomOut={() =>
            setCamera((current) =>
              zoomCameraAtPoint(
                current,
                { x: stage.width / 2, y: stage.height / 2 },
                current.zoom * (1 - projection.zoomStep),
                projection
              )
            )
          }
          onFit={fitCamera}
          onFocus={() => {
            const unit = activeUnit || view.units.find((entry) => entry.alive);
            if (unit) focusTile({ x: unit.x, y: unit.y, elevation: unit.elevation });
          }}
        />
      </div>

      {panelVisible ? (
        <FloatingPanel
          model={contextModel}
          position={panelPosition}
          abilities={contextModel.abilities}
          width={PANEL_WIDTH}
          onAction={onPanelAction}
          onAbility={onPanelAbility}
          onRouteDisplace={(segment, change) =>
            dispatch({ type: "setRouteDisplacement", segment, ...change })
          }
          onOrderPick={(unitId) => dispatch({ type: "toggleOrderPick", unitId })}
          onContextOption={(option) =>
            dispatch({ type: "chooseContextOption", abilityId: option.abilityId })
          }
        />
      ) : null}

      {hoverBadge && !panelVisibleCoversHover(panelPosition, hoverBadgePosition) ? (
        <HoverBadge badge={hoverBadge} position={hoverBadgePosition} />
      ) : null}

      {hudPanel && !busy && !state.finished ? (
        <MechHud
          hud={hudPanel}
          bottom={HUD_LAYOUT.reserved.bottom + 12}
          selectedAbilityId={input.selectedAbilityId}
          onDetails={() => setDetailsOpen(true)}
          onAbility={(ability) => {
            if (!ability.usable) return;
            mark("selectAbility");
            dispatch({ type: "chooseAbility", abilityId: ability.abilityId });
          }}
        />
      ) : null}

      <BottomStrip
        notice={
          blocked
            ? "Content validation failed: " + contentReport.errors.join(" | ")
            : storyLog.length
            ? storyLog[storyLog.length - 1].glyph +
              " " +
              storyLog[storyLog.length - 1].name +
              ": " +
              storyLog[storyLog.length - 1].text
            : stageLabel + " — " + notice
        }
        error={input.errorMessage}
        logGroups={logGroups}
        height={HUD_LAYOUT.reserved.bottom}
        onExpand={() => setDetailsOpen(true)}
      />


      <LinkStrip model={reactions} top={HUD_LAYOUT.reserved.top + 6} />
      <ReactionTicker model={reactions} bottom={HUD_LAYOUT.reserved.bottom + 12} />
      {reactions && reactions.window ? (
        <ReactionPrompt
          model={reactions.window}
          onChoose={(offerId) => answerReaction(offerId)}
          onDecline={() => answerReaction(null)}
        />
      ) : null}
      {missionScene ? (
        <CombatDialogueOverlay entry={missionScene} onDismiss={dismissMissionScene} />
      ) : null}
      {combatDialogueQueue.length ? (
        <CombatDialogueOverlay
          entry={combatDialogueQueue[0]}
          onDismiss={() => setCombatDialogueQueue((current) => current.slice(1))}
        />
      ) : null}

      {detailsOpen ? (
        <DetailsDrawer
          sheet={characterSheet}
          unit={
            view.units.find((unit) => unit.id === input.inspectedUnitId) ||
            activeUnit ||
            view.units[0]
          }
          activeUnit={activeUnit}
          recovery={
            shownForecast && shownForecast.valid ? shownForecast.recovery : moveRecovery
          }
          destination={plannedDestination}
          destinationForecasts={destinationForecasts}
          logGroups={logGroups}
          logFilter={logFilter}
          onFilter={setLogFilter}
          onClose={() => setDetailsOpen(false)}
        />
      ) : null}

      {summary ? (
        <div
          style={createPanelStyle("overlay", { backdropFilter: "blur(3px)" })}
          className="absolute inset-0 z-50 flex items-center justify-center p-4 overflow-auto"
        >
          <div style={{ width: 1040, maxWidth: "92%" }}>
            <BattleEndScreen
              summary={summary}
              onReport={
                pendingMissionId
                  ? () => finishMission(summary.playerVictory === true)
                  : null
              }
              onReplaySameSeed={() => {
                mark("replaySameSeed");
                startBattle(state.randomSeed);
              }}
              onReplayNewSeed={() => {
                const next = Number(seed) + 1;
                setSeed(next);
                startBattle(next);
              }}
              onOpenDebug={() => {
                setDevOpen(true);
                setDevTab("tests");
              }}
            />
          </div>
        </div>
      ) : null}

      {devOpen ? (
        <div
          style={createPanelStyle("overlay")}
          className="absolute inset-0 z-50 overflow-auto p-3"
        >
          <div className="mb-2 flex items-center justify-between">
            <span className="text-[10px] uppercase tracking-[0.2em] text-slate-400">
              Developer tools
            </span>
            <Button size="sm" onClick={() => setDevOpen(false)}>
              Close
            </Button>
          </div>
          <DeveloperTools
            state={state}
            view={view}
            seed={seed}
            onSeed={(value) => {
              setSeed(value);
              savePrefs({ seed: value, speedId });
            }}
            onStart={() => startBattle(seed)}
            onStep={() => devRun(() => runActivation(state), "Ran one activation through the engine.")}
            onRunUntilPlayer={() =>
              devRun(() => {
                let guard = 0;
                while (!state.finished && guard < GAME_CONFIG.limits.maxActivationsPerBattle) {
                  const nextId = getNextActionableUnitId(state);
                  if (!nextId) break;
                  const team = state.teams.find((entry) => entry.id === state.units[nextId].teamId);
                  if (team && team.controller === "human" && guard > 0) break;
                  runActivation(state);
                  guard += 1;
                }
              }, "Ran until the next player activation.")
            }
            onRunAi={() =>
              devRun(() => {
                let done = 0;
                while (!state.finished && done < 10) {
                  const result = runActivation(state);
                  if (!result.unitId) break;
                  done += 1;
                }
              }, "Ran 10 AI activations.")
            }
            onRunFull={() =>
              devRun(() => {
                // Close any open player activation first, then let the AI finish.
                if (state.activeUnitId) {
                  executeCommand(state, { type: "endTurn", unitId: state.activeUnitId });
                }
                runBattle(state, GAME_CONFIG.limits.maxActivationsPerBattle);
              }, "Ran the full battle.")
            }
            onReset={() => startBattle(state.randomSeed)}
            checklist={checklist}
            testResults={testResults}
            audit={audit}
            onRunTests={runAllTests}
            running={running}
            devTab={devTab}
            onDevTab={setDevTab}
            notice={notice}
          />
        </div>
      ) : null}
    </div>
  );
}

/* =========================================================================
 * FRONT DOOR
 *
 * The top-level shell. Three routes:
 *
 *   menu    the title screen — where the application now starts
 *   game    the campaign, unchanged: base -> missions -> briefing -> battle
 *   editor  the existing mission editor, mounted rather than reimplemented
 *
 * The campaign flow below `game` is untouched. This is the shell that was
 * missing above it.
 * =======================================================================*/

const APP_ROUTES = ["menu", "game", "editor", "scene"];

/**
 * Where the application starts.
 *
 * Two things outrank the menu, both of them deliberate requests from a tool
 * rather than a person:
 *
 *   the editor's Playtest slot — paint a tile, press play, stand on it. Making
 *   that round trip pass through a title screen would be a worse tool.
 *
 *   ?boot=  — the explicit harness escape hatch. A test that needs the base
 *   screen or the editor asks for it by name instead of clicking through.
 */
function resolveStartupRoute(search, playtestMissionId) {
  const query = typeof search === "string" ? search : "";
  const requested = (query.match(/[?&]boot=([a-z]+)/i) || [])[1];
  if (requested && APP_ROUTES.includes(requested.toLowerCase())) {
    return requested.toLowerCase();
  }
  const playtest =
    playtestMissionId === undefined ? MISSION_CONTENT.playtestMissionId : playtestMissionId;
  if (playtest) return "game";
  return "menu";
}

function MenuItem({ label, hint, onClick, disabled, tone }) {
  return (
    <button
      type="button"
      onClick={onClick}
      disabled={disabled}
      className={
        "group relative block w-full border px-6 py-4 text-left transition " +
        (disabled
          ? "cursor-not-allowed border-slate-800 bg-slate-950/40 text-slate-700"
          : tone === "primary"
          ? "border-sky-300/45 bg-sky-950/25 text-slate-100 hover:border-sky-200/80 hover:bg-sky-900/30"
          : tone === "warning"
          ? "border-amber-400/50 bg-amber-950/25 text-amber-100 hover:border-amber-300/80 hover:bg-amber-900/30"
          : "border-slate-700 bg-slate-950/60 text-slate-200 hover:border-sky-300/50 hover:bg-slate-900/70")
      }
    >
      <span className="font-display text-[19px] uppercase tracking-[0.14em]">{label}</span>
      {hint ? (
        <span className="mt-1 block text-[11px] leading-relaxed tracking-[0.04em] text-slate-500">
          {hint}
        </span>
      ) : null}
      {!disabled ? (
        <span className="pointer-events-none absolute right-5 top-1/2 -translate-y-1/2 text-[15px] text-sky-300/0 transition group-hover:text-sky-300/70">
          ▸
        </span>
      ) : null}
    </button>
  );
}

function MenuGroup({ label, children }) {
  return (
    <div>
      <p className="mb-3 text-[10px] uppercase tracking-[0.3em] text-slate-600">{label}</p>
      <div className="space-y-3">{children}</div>
    </div>
  );
}

/**
 * The title screen.
 *
 * Deliberately built from the same primitives every other screen uses —
 * `CinematicBackdrop`, `TitlePlaque`, `FrameCorners` — so it reads as part of
 * the game rather than as a launcher bolted onto the front.
 */
function MainMenu({ hasSave, saveSummary, onContinue, onNewGame, onEditor, onSettings }) {
  const [confirmingNew, setConfirmingNew] = React.useState(false);

  return (
    <CinematicBackdrop>
      <div className="absolute inset-0 z-10 flex items-center">
        <div className="w-full px-[110px]">
          <div className="grid items-center gap-16" style={{ gridTemplateColumns: "minmax(0,1fr) 430px" }}>
            <div>
              <p className="font-display text-[13px] uppercase tracking-[0.42em] text-sky-300/70">
                Tactical operations
              </p>
              <h1
                className="mt-4 font-display uppercase leading-[0.9] text-slate-100"
                style={{ fontSize: 104, letterSpacing: "0.04em" }}
              >
                Status<span className="text-sky-300"> Zero</span>
              </h1>
              <div className="mt-7 h-px w-[420px] bg-gradient-to-r from-sky-300/60 to-transparent" />
              <p className="mt-7 max-w-[520px] text-[13px] leading-relaxed text-slate-500">
                A deterministic tactical simulator. Every battle replays from its seed, every
                mission is a file you can open, and every faction only knows what it can see.
              </p>
            </div>

            <div className="relative border border-slate-700/80 bg-slate-950/75 p-8 shadow-[0_24px_70px_rgba(0,0,0,0.55)]">
              <FrameCorners />
              <div className="space-y-8">
                <MenuGroup label="Play">
                  <MenuItem
                    label="Continue"
                    tone="primary"
                    hint={hasSave ? saveSummary : "No saved campaign yet."}
                    disabled={!hasSave}
                    onClick={onContinue}
                  />
                  {confirmingNew ? (
                    <div className="border border-amber-300/40 bg-amber-950/20 px-5 py-4">
                      <p className="text-[12px] leading-relaxed text-amber-200">
                        A saved campaign already exists. Starting a new one leaves it on disk —
                        it is only overwritten the next time you save.
                      </p>
                      <div className="mt-4 flex gap-3">
                        <Button tone="primary" size="sm" onClick={onNewGame}>
                          Start new campaign
                        </Button>
                        <Button size="sm" onClick={() => setConfirmingNew(false)}>
                          Cancel
                        </Button>
                      </div>
                    </div>
                  ) : (
                    <MenuItem
                      label="New Game"
                      hint="Begin the campaign from the first operation."
                      onClick={() => (hasSave ? setConfirmingNew(true) : onNewGame())}
                    />
                  )}
                </MenuGroup>

                <MenuGroup label="Tools">
                  <MenuItem
                    label="Editor"
                    hint="Missions, scenes and gameplay data. Paint a map, write a cutscene or retune a weapon, then play it. Authoring only — never touches your campaign."
                    onClick={onEditor}
                  />
                </MenuGroup>

                {/* A Studio draft rewrites the rules of every battle launched
                 *  from here, so it is never allowed to be invisible on the
                 *  screen you start a campaign from. */}
                {GAMEPLAY_DRAFT_ACTIVE ? (
                  <MenuGroup label="Gameplay data">
                    <MenuItem
                      label="Using draft data"
                      tone="warning"
                      hint={
                        "Unsaved Studio edits are shaping the game" +
                        (GAMEPLAY_DRAFT_TEST ? " (testing " + GAMEPLAY_DRAFT_TEST.id + ")" : "") +
                        ". Select to discard them and reload on the shipped data."
                      }
                      onClick={() => {
                        clearGameplayDraft();
                        window.location.reload();
                      }}
                    />
                  </MenuGroup>
                ) : null}

                <MenuGroup label="System">
                  <MenuItem
                    label="Settings"
                    hint="Display scale, master and music volume."
                    onClick={onSettings}
                  />
                </MenuGroup>
              </div>
            </div>
          </div>
        </div>
      </div>

      <footer className="absolute bottom-6 left-[110px] z-20 text-[10px] uppercase tracking-[0.22em] text-slate-700">
        Prototype build · press Esc for settings
      </footer>
    </CinematicBackdrop>
  );
}

/** Loading state for the lazily-imported editor, in the game's own language. */
function RouteLoading({ label }) {
  return (
    <div className="flex h-full w-full items-center justify-center bg-[#030811] font-mono text-[11px] uppercase tracking-[0.24em] text-slate-600">
      {label}
    </div>
  );
}

/**
 * The mission editor, kept out of the game bundle.
 *
 * Lazily imported so the tool's weight is only paid by someone who opens it,
 * and so `editor.html` and this route render the exact same component. There
 * is no second copy of the editor inside the game shell.
 */
const LazyMissionEditor = React.lazy(() => import("./editor/Editor.jsx"));

export default function TacticalBattle() {
  const [windowViewport, setWindowViewport] = React.useState(() => ({
    width: typeof window === "undefined" ? UI_DESIGN_RESOLUTION.width : window.innerWidth,
    height: typeof window === "undefined" ? UI_DESIGN_RESOLUTION.height : window.innerHeight
  }));
  const [uiScaleId, setUiScaleId] = React.useState(readUiScalePreference);
  const [settingsOpen, setSettingsOpen] = React.useState(false);
  const [route, setRoute] = React.useState(() =>
    resolveStartupRoute(typeof window === "undefined" ? "" : window.location.search)
  );
  // The campaign the game route should open with. Null means "a fresh one",
  // which is what New Game and the playtest slot both want.
  const [bootCampaign, setBootCampaign] = React.useState(null);
  // Remounts the campaign so New Game after Continue genuinely starts over
  // rather than reusing the previous run's component state.
  const [gameInstance, setGameInstance] = React.useState(0);
  // A scene being previewed from the editor, and where it should start. Held
  // in state rather than round-tripped through storage, so the editor's
  // Preview button shows exactly what is on screen right now.
  const [scenePreview, setScenePreview] = React.useState(() => {
    if (typeof window === "undefined") return null;
    if (resolveStartupRoute(window.location.search) !== "scene") return null;
    const previewed = SCENE_CONTENT.previewSceneId
      ? sceneById(SCENE_CONTENT.previewSceneId)
      : null;
    const requested = (window.location.search.match(/[?&]scene=([a-z0-9-]+)/i) || [])[1];
    const step = Number((window.location.search.match(/[?&]step=(\d+)/) || [])[1] || 0);
    const scene = (requested && sceneById(requested)) || previewed;
    return scene ? { scene, startIndex: step, from: "standalone" } : null;
  });
  const [saveSlot, setSaveSlot] = React.useState(() => (route === "menu" ? hasCampaignSlot() : false));
  const [masterVolume, setMasterVolume] = React.useState(() => readStoredPercent("tactical-master-volume", 80));
  const [musicVolume, setMusicVolume] = React.useState(() => readStoredPercent("tactical-music-volume", 70));
  const [musicEnabled, setMusicEnabled] = React.useState(() => readStoredBoolean("tactical-music-enabled", true));
  const [musicRequest, setMusicRequest] = React.useState({ context: "base", missionId: null });
  const [musicStatus, setMusicStatus] = React.useState({ state: "waiting", src: null, context: "base" });

  React.useEffect(() => {
    if (typeof window === "undefined") return undefined;
    const resize = () => setWindowViewport({ width: Math.max(320, window.innerWidth), height: Math.max(180, window.innerHeight) });
    resize();
    window.addEventListener("resize", resize);
    return () => window.removeEventListener("resize", resize);
  }, []);

  React.useEffect(() => {
    if (typeof window === "undefined") return undefined;
    const onKey = (event) => {
      if (event.key !== "Escape" || event.repeat) return;
      // The editor owns its own keyboard. Stealing Escape from it to open the
      // game's settings would be wrong in a tool where Escape cancels things.
      if (route === "editor") return;
      event.preventDefault();
      event.stopPropagation();
      if (typeof event.stopImmediatePropagation === "function") event.stopImmediatePropagation();
      setSettingsOpen((open) => !open);
    };
    window.addEventListener("keydown", onKey, true);
    return () => window.removeEventListener("keydown", onKey, true);
  }, [route]);

  const selectedScale = UI_SCALE_OPTIONS.find((option) => option.id === uiScaleId) || UI_SCALE_OPTIONS[2];
  const uiFactor = selectedScale.factor;
  const fitScale = Math.min(windowViewport.width / UI_DESIGN_RESOLUTION.width, windowViewport.height / UI_DESIGN_RESOLUTION.height);
  const renderScale = Math.max(0.1, fitScale * uiFactor);
  const logicalViewport = React.useMemo(() => ({ width: Math.round(UI_DESIGN_RESOLUTION.width / uiFactor), height: Math.round(UI_DESIGN_RESOLUTION.height / uiFactor) }), [uiFactor]);
  const canvasPhysicalWidth = logicalViewport.width * renderScale;
  const canvasPhysicalHeight = logicalViewport.height * renderScale;

  const changeUiScale = (nextId) => {
    if (!UI_SCALE_OPTIONS.some((option) => option.id === nextId)) return;
    setUiScaleId(nextId);
    persistSetting("tactical-ui-scale", nextId);
  };
  const changeMasterVolume = (value) => { setMasterVolume(value); persistSetting("tactical-master-volume", value); };
  const changeMusicVolume = (value) => { setMusicVolume(value); persistSetting("tactical-music-volume", value); };
  const changeMusicEnabled = (value) => { setMusicEnabled(value); persistSetting("tactical-music-enabled", value); };

  /* ---- route actions ---- */

  const openMenu = React.useCallback(() => {
    setSettingsOpen(false);
    // Going back to the title screen is unambiguously "done playtesting", and
    // the slot outranks the menu at startup — leaving it set would send the
    // next reload straight back into the battle you just walked out of.
    clearPlaytestMission();
    setRoute("menu");
    // Re-read the slot on the way in, so Continue reflects anything the run
    // that just ended saved.
    setSaveSlot(hasCampaignSlot());
  }, []);

  const continueCampaign = React.useCallback(() => {
    const loaded = loadCampaignSlot();
    if (!loaded) {
      // Continue is disabled without a save, so this only happens if the slot
      // was cleared in another tab. Stay put rather than start a silent new run.
      setSaveSlot(false);
      return;
    }
    setBootCampaign(loaded);
    setGameInstance((value) => value + 1);
    setRoute("game");
  }, []);

  const openScenePreview = React.useCallback((scene, startIndex) => {
    setScenePreview({ scene, startIndex: startIndex || 0, from: "editor" });
    setRoute("scene");
  }, []);

  const closeScenePreview = React.useCallback(() => {
    // Back to wherever the preview was launched from. An editor preview
    // returns to the editor with the draft untouched; a standalone preview
    // (a new tab from the editor) has nowhere to go but the title screen.
    setRoute(scenePreview && scenePreview.from === "editor" ? "editor" : "menu");
  }, [scenePreview]);

  const startNewCampaign = React.useCallback(() => {
    // No save is written here. A new campaign only reaches disk when the
    // player saves it, so backing out of one costs nothing.
    setBootCampaign(null);
    setGameInstance((value) => value + 1);
    setRoute("game");
  }, []);

  const settingsContextValue = React.useMemo(() => ({
    settingsOpen,
    openSettings: () => setSettingsOpen(true),
    closeSettings: () => setSettingsOpen(false),
    setMusicRequest,
    logicalViewport,
    route,
    returnToMenu: openMenu
  }), [settingsOpen, logicalViewport, route, openMenu]);

  // The editor is a dense tool, not a cinematic canvas: it takes the whole
  // window rather than being letterboxed into 1920x1080 and scaled.
  if (route === "editor") {
    return (
      <SettingsContext.Provider value={settingsContextValue}>
        <div style={{ width: "100vw", height: "100vh", overflow: "hidden" }} className="bg-[#020609]">
          <React.Suspense fallback={<RouteLoading label="Loading editor…" />}>
            <LazyMissionEditor onExit={openMenu} onScenePreview={openScenePreview} />
          </React.Suspense>
        </div>
      </SettingsContext.Provider>
    );
  }

  return (
    <SettingsContext.Provider value={settingsContextValue}>
      <div style={{ width: "100vw", height: "100vh", overflow: "hidden" }} className="tactical-game-root pixel-crisp-text relative bg-black">
        <GameFontStyles />
        <div
          style={{
            position: "absolute",
            left: "50%",
            top: "50%",
            width: logicalViewport.width,
            height: logicalViewport.height,
            transformOrigin: "50% 50%",
            transform: "translate(-50%, -50%) scale(" + renderScale + ")",
            overflow: "hidden",
            boxShadow: "0 0 0 1px rgba(82,132,171,0.42), 0 30px 100px rgba(0,0,0,0.9)"
          }}
        >
          {route === "scene" && scenePreview ? (
            <ScenePlayer
              scene={scenePreview.scene}
              startIndex={scenePreview.startIndex}
              onComplete={closeScenePreview}
              onExit={closeScenePreview}
              exitLabel={scenePreview.from === "editor" ? "Back to editor" : "Stop"}
            />
          ) : route === "scene" ? (
            <RouteLoading label="No scene to preview" />
          ) : route === "menu" ? (
            <MainMenu
              hasSave={saveSlot}
              saveSummary="Resume your saved campaign."
              onContinue={continueCampaign}
              onNewGame={startNewCampaign}
              onEditor={() => setRoute("editor")}
              onSettings={() => setSettingsOpen(true)}
            />
          ) : (
            <TacticalBattleContent
              key={gameInstance}
              viewport={logicalViewport}
              initialCampaign={bootCampaign}
            />
          )}
        </div>

        {(canvasPhysicalWidth < windowViewport.width - 2 || canvasPhysicalHeight < windowViewport.height - 2) ? (
          <div className="pointer-events-none fixed left-4 top-4 z-[999998] border border-slate-800 bg-black/70 px-3 py-2 font-mono text-[9px] uppercase tracking-[0.16em] text-slate-600">1920×1080 cinematic canvas · 16:9 preserved</div>
        ) : null}

        <button onClick={() => setSettingsOpen(true)} className="fixed bottom-4 right-4 z-[999998] h-11 border border-slate-700 bg-slate-950/92 px-4 font-mono text-[10px] uppercase tracking-[0.18em] text-slate-400 shadow-xl hover:border-sky-300/50 hover:text-sky-200">Settings · Esc</button>

        <AppMusicPlayer
          request={musicRequest}
          enabled={musicEnabled}
          masterVolume={masterVolume}
          musicVolume={musicVolume}
          onStatus={setMusicStatus}
        />

        <SettingsMenu
          open={settingsOpen}
          onClose={() => setSettingsOpen(false)}
          uiScaleId={uiScaleId}
          onUiScale={changeUiScale}
          masterVolume={masterVolume}
          onMasterVolume={changeMasterVolume}
          musicVolume={musicVolume}
          onMusicVolume={changeMusicVolume}
          musicEnabled={musicEnabled}
          onMusicEnabled={changeMusicEnabled}
          musicRequest={musicRequest}
          musicStatus={musicStatus}
          windowViewport={windowViewport}
          logicalViewport={logicalViewport}
          canReturnToMenu={route === "game"}
          onReturnToMenu={openMenu}
        />
      </div>
    </SettingsContext.Provider>
  );
}

/** Keeps the hover badge from sitting on top of the command panel. */
function panelVisibleCoversHover(panel, hover) {
  return Math.abs(panel.left - hover.left) < 24 && Math.abs(panel.top - hover.top) < 24;
}

/* Component registry for the architecture audit. */
